window.SWMN_DATA=window.SWMN_DATA||{};window.SWMN_DATA["k3v3"]=[{"id":"k3v3-b01","courseId":"k3v3","order":1,"title":"Chúng tôi ra sân bay đón các bạn","titleZh":"我们去机场接你们","titlePy":"wǒmen qù jīchǎng jiē nǐmen","vocab":[{"stt":1,"hanzi":"以为","pinyin":"yǐwéi","hanviet":"Dĩ vi","pos":"Động từ","meaning":"tưởng (là), cứ ngỡ (thường là nghĩ sai)","comps":"我以为 (tôi cứ tưởng), 还以为 (còn tưởng là)","example":{"zh":"我以为他是老师。","py":"Wǒ yǐwéi tā shì lǎoshī.","vi":"Mình cứ tưởng anh ấy là giáo viên."}},{"stt":2,"hanzi":"像","pinyin":"xiàng","hanviet":"Tượng","pos":"Động từ","meaning":"giống","comps":"很像 (rất giống), 像……一样 (giống như…)","example":{"zh":"你长得很像你妈妈。","py":"Nǐ zhǎng de hěn xiàng nǐ māma.","vi":"Bạn trông rất giống mẹ bạn."}},{"stt":3,"hanzi":"长","pinyin":"zhǎng","hanviet":"Trưởng","pos":"Động từ","meaning":"mọc, lớn lên; (ngoại hình) trông","comps":"长得 (trông, có ngoại hình…), 长大 (lớn lên)","example":{"zh":"她长得很漂亮。","py":"Tā zhǎng de hěn piàoliang.","vi":"Cô ấy trông rất xinh."}},{"stt":4,"hanzi":"身高","pinyin":"shēngāo","hanviet":"Thân cao","pos":"Danh từ","meaning":"chiều cao (của người)","comps":"身高多少 (cao bao nhiêu), 身高一米七 (cao 1m70)","example":{"zh":"他身高一米八。","py":"Tā shēngāo yì mǐ bā.","vi":"Anh ấy cao một mét tám."}},{"stt":5,"hanzi":"米","pinyin":"mǐ","hanviet":"Mễ","pos":"Lượng từ","meaning":"mét","comps":"一米八 (1m80), 五百米 (500 mét)","example":{"zh":"我弟弟一米七。","py":"Wǒ dìdi yì mǐ qī.","vi":"Em trai mình cao một mét bảy."}},{"stt":6,"hanzi":"瘦","pinyin":"shòu","hanviet":"Sấu","pos":"Tính từ","meaning":"gầy","comps":"很瘦 (rất gầy), 瘦了 (gầy đi)","example":{"zh":"她比我瘦一点儿。","py":"Tā bǐ wǒ shòu yìdiǎnr.","vi":"Cô ấy gầy hơn mình một chút."}},{"stt":7,"hanzi":"接","pinyin":"jiē","hanviet":"Tiếp","pos":"Động từ","meaning":"đón","comps":"接人 (đón người), 去机场接 (ra sân bay đón)","example":{"zh":"明天我去机场接你。","py":"Míngtiān wǒ qù jīchǎng jiē nǐ.","vi":"Mai mình ra sân bay đón bạn."}},{"stt":8,"hanzi":"行李","pinyin":"xíngli","hanviet":"Hành lý","pos":"Danh từ","meaning":"hành lý","comps":"行李箱 (va li), 拿行李 (lấy hành lý)","example":{"zh":"你的行李多不多？","py":"Nǐ de xíngli duō bu duō?","vi":"Hành lý của bạn có nhiều không?"}},{"stt":9,"hanzi":"丢","pinyin":"diū","hanviet":"Đâu","pos":"Động từ","meaning":"mất, đánh rơi","comps":"丢了 (mất rồi), 丢东西 (mất đồ)","example":{"zh":"我的手机丢了。","py":"Wǒ de shǒujī diū le.","vi":"Điện thoại của mình mất rồi."}},{"stt":10,"hanzi":"箱子","pinyin":"xiāngzi","hanviet":"Tương tử","pos":"Danh từ","meaning":"cái hòm, va li","comps":"行李箱 (va li), 大箱子 (hòm to)","example":{"zh":"这个箱子是谁的？","py":"Zhège xiāngzi shì shéi de?","vi":"Cái va li này của ai?"}},{"stt":11,"hanzi":"号码","pinyin":"hàomǎ","hanviet":"Hiệu mã","pos":"Danh từ","meaning":"số (điện thoại, phòng…)","comps":"电话号码 (số điện thoại), 房间号码 (số phòng)","example":{"zh":"你的电话号码是多少？","py":"Nǐ de diànhuà hàomǎ shì duōshao?","vi":"Số điện thoại của bạn là bao nhiêu?"}},{"stt":12,"hanzi":"好像","pinyin":"hǎoxiàng","hanviet":"Hảo tượng","pos":"Phó từ","meaning":"hình như","comps":"好像是 (hình như là), 好像下雨了 (hình như mưa rồi)","example":{"zh":"他好像不在家。","py":"Tā hǎoxiàng bú zài jiā.","vi":"Hình như anh ấy không có nhà."}},{"stt":13,"hanzi":"重要","pinyin":"zhòngyào","hanviet":"Trọng yếu","pos":"Tính từ","meaning":"quan trọng","comps":"很重要 (rất quan trọng), 重要的东西 (đồ quan trọng)","example":{"zh":"这件事很重要。","py":"Zhè jiàn shì hěn zhòngyào.","vi":"Việc này rất quan trọng."}},{"stt":14,"hanzi":"着急","pinyin":"zháojí","hanviet":"Trước cấp","pos":"Tính từ","meaning":"sốt ruột, lo lắng","comps":"别着急 (đừng sốt ruột), 很着急 (rất lo)","example":{"zh":"别着急，慢慢说。","py":"Bié zháojí, mànmàn shuō.","vi":"Đừng sốt ruột, cứ từ từ nói."}},{"stt":15,"hanzi":"护照","pinyin":"hùzhào","hanviet":"Hộ chiếu","pos":"Danh từ","meaning":"hộ chiếu","comps":"带护照 (mang hộ chiếu), 护照号码 (số hộ chiếu)","example":{"zh":"请给我看一下您的护照。","py":"Qǐng gěi wǒ kàn yíxià nín de hùzhào.","vi":"Vui lòng cho tôi xem hộ chiếu của anh/chị."}},{"stt":16,"hanzi":"服务台","pinyin":"fúwùtái","hanviet":"Phục vụ đài","pos":"Danh từ","meaning":"quầy dịch vụ, quầy lễ tân","comps":"去服务台 (đến quầy dịch vụ), 机场服务台 (quầy dịch vụ sân bay)","example":{"zh":"我们去服务台问问吧。","py":"Wǒmen qù fúwùtái wènwen ba.","vi":"Mình ra quầy dịch vụ hỏi thử đi."}},{"stt":17,"hanzi":"应该","pinyin":"yīnggāi","hanviet":"Ưng cai","pos":"Trợ động từ","meaning":"chắc là; nên, phải","comps":"应该快到了 (chắc sắp đến rồi), 应该学习 (nên học)","example":{"zh":"他们应该快出来了。","py":"Tāmen yīnggāi kuài chūlai le.","vi":"Chắc họ sắp ra rồi."}},{"stt":18,"hanzi":"站","pinyin":"zhàn","hanviet":"Trạm","pos":"Động từ","meaning":"đứng","comps":"站起来 (đứng dậy), 站在门口 (đứng ở cửa)","example":{"zh":"他站在我后面。","py":"Tā zhàn zài wǒ hòumian.","vi":"Anh ấy đứng phía sau mình."}},{"stt":19,"hanzi":"中间","pinyin":"zhōngjiān","hanviet":"Trung gian","pos":"Danh từ","meaning":"ở giữa, chính giữa","comps":"站到中间 (đứng vào giữa), 我们中间 (giữa chúng ta)","example":{"zh":"我坐在他们中间。","py":"Wǒ zuò zài tāmen zhōngjiān.","vi":"Mình ngồi giữa hai người họ."}},{"stt":20,"hanzi":"短","pinyin":"duǎn","hanviet":"Đoản","pos":"Tính từ","meaning":"ngắn","comps":"短头发 (tóc ngắn), 很短 (rất ngắn)","example":{"zh":"这件衣服有点儿短。","py":"Zhè jiàn yīfu yǒudiǎnr duǎn.","vi":"Chiếc áo này hơi ngắn."}},{"stt":21,"hanzi":"头发","pinyin":"tóufa","hanviet":"Đầu phát","pos":"Danh từ","meaning":"tóc","comps":"长头发 (tóc dài), 短头发 (tóc ngắn)","example":{"zh":"她的头发很长。","py":"Tā de tóufa hěn cháng.","vi":"Tóc cô ấy rất dài."}},{"stt":22,"hanzi":"年轻","pinyin":"niánqīng","hanviet":"Niên khinh","pos":"Tính từ","meaning":"trẻ, trẻ tuổi","comps":"年轻人 (người trẻ), 很年轻 (rất trẻ)","example":{"zh":"我们老师很年轻。","py":"Wǒmen lǎoshī hěn niánqīng.","vi":"Cô giáo chúng mình rất trẻ."}},{"stt":23,"hanzi":"发现","pinyin":"fāxiàn","hanviet":"Phát hiện","pos":"Động từ","meaning":"phát hiện, nhận ra","comps":"发现问题 (phát hiện vấn đề), 我发现 (tôi nhận ra)","example":{"zh":"我发现手机不见了。","py":"Wǒ fāxiàn shǒujī bújiàn le.","vi":"Mình phát hiện điện thoại không thấy đâu."}},{"stt":24,"hanzi":"不见","pinyin":"bújiàn","hanviet":"Bất kiến","pos":"Động từ","meaning":"không thấy (đâu), biến mất","comps":"不见了 (không thấy đâu nữa), 钱包不见了 (ví biến mất)","example":{"zh":"我的护照不见了！","py":"Wǒ de hùzhào bújiàn le!","vi":"Hộ chiếu của mình không thấy đâu rồi!"}},{"stt":25,"hanzi":"带","pinyin":"dài","hanviet":"Đới","pos":"Động từ","meaning":"dẫn (ai đi); mang theo","comps":"带孩子 (dẫn con), 带护照 (mang hộ chiếu)","example":{"zh":"我带你去服务台。","py":"Wǒ dài nǐ qù fúwùtái.","vi":"Mình dẫn bạn ra quầy dịch vụ."}},{"stt":26,"hanzi":"帮助","pinyin":"bāngzhù","hanviet":"Bang trợ","pos":"Động từ","meaning":"giúp, giúp đỡ","comps":"帮助别人 (giúp người khác), 谢谢你的帮助 (cảm ơn sự giúp đỡ)","example":{"zh":"他帮助我找到了行李箱。","py":"Tā bāngzhù wǒ zhǎodàole xínglixiāng.","vi":"Anh ấy giúp mình tìm lại được va li."}},{"stt":27,"hanzi":"照片","pinyin":"zhàopiàn","hanviet":"Chiếu phiến","pos":"Danh từ","meaning":"ảnh, tấm ảnh","comps":"看照片 (xem ảnh), 一张照片 (một tấm ảnh)","example":{"zh":"这是我家的照片。","py":"Zhè shì wǒ jiā de zhàopiàn.","vi":"Đây là ảnh gia đình mình."}}],"hanzi":[{"char":"以为","pinyin":"yǐwéi","hanviet":"Dĩ vi","chars":["以","为"],"story":"以 = \"lấy, dùng\"; 为 = \"làm, là\" (phồn thể 爲 vẽ bàn tay dắt con voi đi làm việc). 以为 = \"lấy … làm …\" → coi là, tưởng là. Thường dùng khi điều mình tưởng hoá ra không đúng: 我还以为是同乐呢."},{"char":"像","pinyin":"xiàng","hanviet":"Tượng","chars":["像"],"story":"像 là chữ hình thanh: bộ Nhân 亻(người) chỉ nghĩa, 象 xiàng (con voi) chỉ âm. Nghĩa gốc là \"hình tượng của người\" — hình dáng giống người thật → \"giống\"."},{"char":"长","pinyin":"zhǎng","hanviet":"Trưởng","chars":["长"],"story":"长 vốn vẽ một ông già tóc dài chống gậy. Tóc dài → đọc cháng \"dài\"; người lớn tuổi → đọc zhǎng \"trưởng, lớn lên, mọc\". Bài này đọc zhǎng: 长得很像 = trông rất giống."},{"char":"身高","pinyin":"shēngāo","hanviet":"Thân cao","chars":["身","高"],"story":"身 vẽ dáng người nhìn nghiêng có cái bụng nhô ra → \"thân mình\". 高 vẽ toà lầu nhiều tầng → \"cao\". 身高 = độ cao của thân người → chiều cao."},{"char":"米","pinyin":"mǐ","hanviet":"Mễ","chars":["米"],"story":"米 vẽ những hạt gạo rơi quanh một thân lúa → nghĩa gốc \"gạo\" (米饭). Sau được mượn để phiên âm đơn vị đo \"mét\" (meter): 一米八 = 1m80."},{"char":"瘦","pinyin":"shòu","hanviet":"Sấu","chars":["瘦"],"story":"瘦 là chữ hình thanh: bộ Nạch 疒 (bệnh tật) chỉ nghĩa, 叟 sǒu (ông già) chỉ âm. Người ốm, người già thì thân hình hao gầy → \"gầy\"."},{"char":"接","pinyin":"jiē","hanviet":"Tiếp","chars":["接"],"story":"接 là chữ hình thanh: bộ Thủ 扌 (bàn tay) chỉ nghĩa, 妾 qiè chỉ âm. Đưa tay ra đón lấy → \"đón\": 去机场接人 = ra sân bay đón người."},{"char":"行李","pinyin":"xíngli","hanviet":"Hành lý","chars":["行","李"],"story":"行 vẽ ngã tư đường → \"đi\". 李 = 木 (cây) + 子, vốn là cây mận. 行李 = những thứ mang theo khi đi đường → hành lý."},{"char":"丢","pinyin":"diū","hanviet":"Đâu","chars":["丢"],"story":"丢 = 一 (một) + 去 (đi mất), nét trên cùng gộp lại. Một thứ \"đi mất\" → mất, đánh rơi. Mẹo nhớ: 丢 giống 去 có thêm một nét ngang trên đầu."},{"char":"箱子","pinyin":"xiāngzi","hanviet":"Tương tử","chars":["箱","子"],"story":"箱 là chữ hình thanh: bộ Trúc ⺮ (tre) chỉ nghĩa, 相 xiāng chỉ âm — hòm ngày xưa đan bằng tre. 子 là hậu tố danh từ. 行李箱 = va li."},{"char":"号码","pinyin":"hàomǎ","hanviet":"Hiệu mã","chars":["号","码"],"story":"号 = 口 (miệng) + 丂: hô to để gọi → số hiệu, số thứ tự. 码 là chữ hình thanh: 石 (đá) chỉ nghĩa, 马 mǎ chỉ âm — vốn là quả cân bằng đá dùng để đếm. 号码 = con số dùng để gọi, đánh dấu."},{"char":"好像","pinyin":"hǎoxiàng","hanviet":"Hảo tượng","chars":["好","像"],"story":"好 (女 người mẹ + 子 đứa con) + 像 (giống). 好像 = \"trông rất giống như\" → đoán chừng: hình như. 我好像在哪儿看到过 = hình như mình đã thấy ở đâu đó rồi."},{"char":"重要","pinyin":"zhòngyào","hanviet":"Trọng yếu","chars":["重","要"],"story":"重 vẽ người đang vác một bao nặng → \"nặng\". 要 vẽ người phụ nữ chống hai tay vào eo (腰) — eo là chỗ then chốt của cơ thể → \"cần, quan trọng\". 重要 = nặng ký, then chốt → quan trọng."},{"char":"着急","pinyin":"zháojí","hanviet":"Trước cấp","chars":["着","急"],"story":"着 đọc zháo = bị, bén vào (lửa bén 着火). 急 = ⺈ (một người đuổi theo) + 彐 (bàn tay túm lấy) + 心 (tim): đuổi gấp, lòng nóng ruột. 着急 = cái gấp gáp \"bén\" vào lòng → sốt ruột."},{"char":"护照","pinyin":"hùzhào","hanviet":"Hộ chiếu","chars":["护","照"],"story":"护 là chữ hình thanh: 扌 (tay) chỉ nghĩa, 户 hù chỉ âm → che chở, bảo vệ. 照 = 昭 (sáng rõ) + 灬 (lửa) → chiếu sáng; giấy chứng nhận. 护照 = giấy chứng nhận để được bảo hộ khi ra nước ngoài → hộ chiếu."},{"char":"服务台","pinyin":"fúwùtái","hanviet":"Phục vụ đài","chars":["服","务","台"],"story":"服 = phục tùng, làm theo; 务 = 夂 + 力 (dùng sức) → công việc. 服务 = phục vụ. 台 = 厶 + 口 → cái bục, cái quầy. 服务台 = quầy phục vụ."},{"char":"应该","pinyin":"yīnggāi","hanviet":"Ưng cai","chars":["应","该"],"story":"应 = 广 (mái nhà) + 䧹 rút gọn, vốn là \"đáp lời, ứng\" → \"đáng, nên\". 该 = 讠 (lời nói) + 亥 hài chỉ âm → \"phải, đáng\". 应该 = theo lẽ phải như thế → \"nên\"; theo lẽ thường đoán ra → \"chắc là\"."},{"char":"站","pinyin":"zhàn","hanviet":"Trạm","chars":["站"],"story":"站 là chữ hình thanh: bộ Lập 立 (người đứng thẳng trên mặt đất) chỉ nghĩa, 占 zhàn chỉ âm. Người đứng yên một chỗ → \"đứng\"; chỗ xe dừng đứng lại → \"trạm, bến\" (车站)."},{"char":"中间","pinyin":"zhōngjiān","hanviet":"Trung gian","chars":["中","间"],"story":"中 vẽ một cây cột cắm xuyên giữa khung → \"giữa\". 间 = 门 (cánh cửa) + 日 (mặt trời): ánh nắng lọt qua khe cửa → \"khoảng giữa, khe hở\". 中间 = chỗ chính giữa."},{"char":"短","pinyin":"duǎn","hanviet":"Đoản","chars":["短"],"story":"短 = 矢 (mũi tên) + 豆 (cái bát cao chân). Người xưa lấy mũi tên, cái bát — những vật ngắn — làm thước đo vật ngắn → \"ngắn\". Trái nghĩa: 长 cháng (dài)."},{"char":"头发","pinyin":"tóufa","hanviet":"Đầu phát","chars":["头","发"],"story":"头 = 大 (người) + 2 chấm: cái đầu người. 发 ở đây là phồn thể 髮 = 髟 (tóc dài rủ xuống) + 犮 bá chỉ âm → \"tóc\". 头发 = tóc trên đầu. Chú ý: đọc tóufa, 发 thanh nhẹ."},{"char":"年轻","pinyin":"niánqīng","hanviet":"Niên khinh","chars":["年","轻"],"story":"年 vẽ người vác bó lúa trên vai — mỗi năm gặt một vụ → \"năm, tuổi\". 轻 = 车 (xe) + 𢀖 chỉ âm: xe nhẹ chạy nhanh → \"nhẹ\". 年轻 = tuổi còn nhẹ → trẻ."},{"char":"发现","pinyin":"fāxiàn","hanviet":"Phát hiện","chars":["发","现"],"story":"发 = phát ra, bắt đầu (phồn thể 發 = giương cung bắn tên). 现 = 王 (ngọc) + 见 (thấy): ngọc lộ ra cho người thấy → \"hiện ra\". 发现 = làm lộ ra cho mình thấy → phát hiện."},{"char":"不见","pinyin":"bújiàn","hanviet":"Bất kiến","chars":["不","见"],"story":"不 (không) + 见 (目 mắt đặt trên 儿 người → nhìn thấy). 不见 = nhìn không thấy nữa → đồ vật biến mất, không thấy đâu: 行李箱不见了."},{"char":"带","pinyin":"dài","hanviet":"Đới","chars":["带"],"story":"带 vẽ chiếc thắt lưng có đeo các vật trang sức, phía dưới là 巾 (dải vải) rủ xuống → \"dây đai\". Đồ đeo ở thắt lưng thì mang theo người → \"mang theo\", rồi \"dẫn đi cùng\"."},{"char":"帮助","pinyin":"bāngzhù","hanviet":"Bang trợ","chars":["帮","助"],"story":"帮 = 邦 bāng chỉ âm + 巾 → \"giúp\". 助 = 且 qiě chỉ âm + 力 (sức lực): góp thêm sức → \"trợ giúp\". 帮助 = góp sức giúp người. So với 帮忙 (từ ly hợp, không mang tân ngữ): 帮助 mang tân ngữ được — 帮助她."},{"char":"照片","pinyin":"zhàopiàn","hanviet":"Chiếu phiến","chars":["照","片"],"story":"照 = 昭 (sáng rõ) + 灬 (lửa): soi sáng, chiếu → \"chụp (ảnh)\". 片 vẽ nửa bên phải của khúc gỗ bổ đôi → \"tấm mỏng, miếng\". 照片 = tấm mỏng in hình chụp → tấm ảnh."}],"grammar":[{"title":"Cụm 看上去 / 看起来","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>người / vật</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>看上去 / 看起来</b><small>trông có vẻ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词 / 状态</b><small>tính từ · trạng thái</small></span></div>","summary":"<p class=\"gr-lead\">Trông có vẻ — nhận xét vẻ ngoài</p><ul><li><span class=\"zh\">看上去 / 看起来</span> = \"trông có vẻ, nhìn thì\": nhận xét <b>vẻ ngoài, trạng thái</b> dựa vào những gì mắt thấy. Hai cụm dùng như nhau.</li><li>Thường đứng <b>sau chủ ngữ, trước tính từ</b>; cũng có thể đứng đầu câu: <span class=\"zh\">看起来，他今天很累。</span></li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">他们看上去有点儿像。</span>　·　<span class=\"zh\">这些菜看起来都很好吃。</span></p>","note":"<b>Lưu ý:</b> Nhận xét vẻ ngoài không dùng <span class=\"zh\">看见</span>: ✗ <span class=\"zh\">他看见很年轻</span> → ✓ <span class=\"zh\">他看上去很年轻</span>","examples":[{"zh":"他们看上去有点儿像。","py":"Tāmen kàn shàngqu yǒudiǎnr xiàng.","vi":"Trông họ hơi giống nhau."},{"zh":"这些菜看起来都很好吃。","py":"Zhèxiē cài kàn qǐlai dōu hěn hǎochī.","vi":"Mấy món này trông đều rất ngon."},{"zh":"那个新来的老师看上去很年轻。","py":"Nàge xīn lái de lǎoshī kàn shàngqu hěn niánqīng.","vi":"Thầy giáo mới đến kia trông rất trẻ."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">你____长得更像你妈妈。</span><span class=\"qz-hint\">Trông bạn giống mẹ bạn hơn.</span>","answer":["看上去","看起来"],"explain":"你看上去长得更像你妈妈。 (Nǐ kàn shàngqu zhǎng de gèng xiàng nǐ māma.)"},{"type":"fill","q":"<span class=\"zh\">你____，好好休息一下吧。</span><span class=\"qz-hint\">Trông bạn mệt lắm, nghỉ ngơi cho tốt đi.</span>","answer":["看起来很累","看上去很累","看起来有点儿累","看上去有点儿累"],"explain":"你看起来很累，好好休息一下吧。 (Nǐ kàn qǐlai hěn lèi, hǎohāo xiūxi yíxià ba.)"},{"type":"fill","q":"<span class=\"zh\">你怎么了？今天____。</span><span class=\"qz-hint\">Bạn sao thế? Hôm nay trông có vẻ không vui lắm.</span>","answer":["看起来不太高兴","看上去不太高兴","看起来不高兴","看上去不高兴","看起来不开心","看上去不开心"],"explain":"你怎么了？今天看起来不太高兴。 (Nǐ zěnme le? Jīntiān kàn qǐlai bú tài gāoxìng.)"}]},{"title":"Đại từ nghi vấn dùng không để hỏi (1)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>陈述句</b><small>câu kể (không phải câu hỏi)</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>哪儿 · 什么 · 谁 · 哪</b><small>đại từ nghi vấn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>= 不确定</b><small>không biết rõ / không cần nói rõ</small></span></div>","summary":"<p class=\"gr-lead\">Ai đó · gì đó · đâu đó</p><ul><li>Đại từ nghi vấn đặt trong <b>câu kể</b> → chỉ người / vật / nơi chốn / thời gian <b>không biết rõ hoặc không cần nói rõ</b>.</li><li>Câu kết thúc bằng 。 hoặc <span class=\"zh\">吧</span>, đọc <b>không lên giọng hỏi</b>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">疑问代词的非疑问用法 (1)</span> · Bốn đại từ</h4><p>Câu hỏi ↔ câu kể</p><div class=\"gr-formula\"><div class=\"fx-lbl\">哪儿 · đâu đó</div><div class=\"fx-row\"><span class=\"fx-p\"><b>在</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>哪儿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>看到过</b></span></div><div class=\"fx-ex zh\">我好像在哪儿看到过这个箱子。</div><div class=\"fx-lbl\">什么 · gì đó</div><div class=\"fx-row\"><span class=\"fx-p\"><b>吃点儿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>什么</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>再走</b></span></div><div class=\"fx-ex zh\">你吃点儿什么再走吧。</div><div class=\"fx-lbl\">谁 · ai đó</div><div class=\"fx-row\"><span class=\"fx-p\"><b>找</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>谁</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>问一下</b></span></div><div class=\"fx-ex zh\">我们快找谁问一下吧。</div><div class=\"fx-lbl\">哪 + LT · nào đó</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我们</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>哪天</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>一起去</b></span></div><div class=\"fx-ex zh\">我们哪天一起去踢足球吧。</div></div><p class=\"gr-key\">Câu hỏi: <span class=\"zh\">你去哪儿？</span> (Bạn đi đâu?)　→　Câu kể: <span class=\"zh\">我想去哪儿玩玩。</span> (Mình muốn đi <b>đâu đó</b> chơi.)</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我好像在哪儿看到过这个箱子。</span> = Hình như mình đã thấy cái va li này <b>ở đâu đó</b>.</p>","note":"<b>Lưu ý:</b> Thêm <span class=\"zh\">吗</span> thành câu hỏi có/không: <span class=\"zh\">你想吃点儿什么吗？</span> = \"Bạn có muốn ăn <b>gì đó</b> không?\", khác <span class=\"zh\">你想吃什么？</span> = \"Bạn muốn ăn gì?\"","examples":[{"zh":"我好像在哪儿看到过这个箱子。","py":"Wǒ hǎoxiàng zài nǎr kàndàoguo zhège xiāngzi.","vi":"Hình như mình đã thấy cái va li này ở đâu đó rồi."},{"zh":"你吃点儿什么再走吧。","py":"Nǐ chī diǎnr shénme zài zǒu ba.","vi":"Bạn ăn chút gì đó rồi hẵng đi."},{"zh":"我们哪天一起去踢足球吧。","py":"Wǒmen nǎ tiān yìqǐ qù tī zúqiú ba.","vi":"Hôm nào đó chúng mình cùng đi đá bóng nhé."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我们是不是走错了？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我也不知道，我去____。（谁）</span></span></span><span class=\"qz-hint\">Có phải chúng mình đi nhầm rồi không? — Mình cũng không biết, để mình đi tìm ai đó hỏi thử.</span>","answer":["找谁问一下","找谁问问","找人问一下"],"explain":"我也不知道，我去找谁问一下。（谁） (Wǒ yě bù zhīdào, wǒ qù zhǎo shéi wèn yíxià. (shéi))"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你有时间了来我家，我____给你吃。（什么）</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">好的，谢谢你。</span></span></span><span class=\"qz-hint\">Lúc nào rảnh bạn đến nhà mình, mình nấu chút gì đó cho bạn ăn. — Được, cảm ơn bạn.</span>","answer":["做点儿什么","做点什么","做些什么"],"explain":"你有时间了来我家，我做点儿什么给你吃。（什么） (Nǐ yǒu shíjiān le lái wǒ jiā, wǒ zuò diǎnr shénme gěi nǐ chī. (shénme))"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这几天太累了，我想____。（哪儿）</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">那你去西安吧。</span></span></span><span class=\"qz-hint\">Mấy hôm nay mệt quá, mình muốn đi đâu đó chơi. — Vậy bạn đi Tây An đi.</span>","answer":["去哪儿玩玩","去哪儿玩一玩","去哪儿玩一下","去哪里玩玩"],"explain":"这几天太累了，我想去哪儿玩玩。（哪儿） (Zhè jǐ tiān tài lèi le, wǒ xiǎng qù nǎr wánwan. (nǎr))"}]},{"title":"Nhiều định ngữ (多项定语)","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>时间 / 处所</b><small>thời gian · nơi chốn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动作 / 状态 + 的</b><small>hành động · trạng thái</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>特点 (+ 的)</b><small>đặc điểm</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>中心语</b><small>danh từ chính</small></span></div>","summary":"<p class=\"gr-lead\">Nhiều định ngữ chồng nhau</p><ul><li>Trước danh từ có thể xếp <b>nhiều định ngữ</b>, theo thứ tự: <b>thời gian / nơi chốn → hành động / trạng thái → đặc điểm</b>.</li><li>Cụm <span class=\"zh\">那个 / 这件 / 两个</span> đứng trước hoặc sau định ngữ hành động: <span class=\"zh\">那个穿着黑衣服的…</span> · <span class=\"zh\">昨天…的两个人</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">多项定语 · 汉语 ↔ 越南语</span> · Đối chiếu</h4><p>Tiếng Việt xếp ngược lại</p><div class=\"ct-box\"><div class=\"ct-cap\">Ví dụ · Đối chiếu tiếng Việt</div><div class=\"ct-intro\"><span class=\"ct-lg a\">Định ngữ</span><span class=\"ct-lg k\">的</span><span class=\"ct-lg b\">Danh từ</span>tiếng Việt: danh từ lên <b>đầu</b>, định ngữ xếp <b>ngược</b> lại</div><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>Tiếng Trung<small>Định ngữ … + 的 + Danh từ</small></th><th>Tiếng Việt<small>Danh từ + định ngữ …</small></th></tr></thead><tbody><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-a\"><b class=\"zh\">那个</b><small>nàge</small></span><span class=\"ct-w c-a\"><b class=\"zh\">穿着黑衣服</b><small>chuānzhe hēi yīfu</small></span><span class=\"ct-w c-k\"><b class=\"zh\">的</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">短头发</b><small>duǎn tóufa</small></span><span class=\"ct-w c-k\"><b class=\"zh\">的</b><small>de</small></span><span class=\"ct-w c-b\"><b class=\"zh\">年轻人</b><small>niánqīngrén</small></span></div><div class=\"ct-vi\">kia · mặc áo đen · tóc ngắn · người trẻ</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-b\">cậu thanh niên</span><span class=\"ct-w c-a\">tóc ngắn</span><span class=\"ct-w c-a\">mặc áo đen</span><span class=\"ct-w c-a\">kia</span></div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-a\"><b class=\"zh\">昨天和家月一起看电影</b><small>zuótiān hé Jiāyuè yìqǐ kàn diànyǐng</small></span><span class=\"ct-w c-k\"><b class=\"zh\">的</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">两个</b><small>liǎng ge</small></span><span class=\"ct-w c-b\"><b class=\"zh\">人</b><small>rén</small></span></div><div class=\"ct-vi\">hôm qua cùng Gia Nguyệt xem phim · hai · người</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-b\">hai người</span><span class=\"ct-w c-a\">hôm qua xem phim cùng Gia Nguyệt</span></div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-a\"><b class=\"zh\">我那件</b><small>wǒ nà jiàn</small></span><span class=\"ct-w c-a\"><b class=\"zh\">新买</b><small>xīn mǎi</small></span><span class=\"ct-w c-k\"><b class=\"zh\">的</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">白色</b><small>báisè</small></span><span class=\"ct-w c-k\"><b class=\"zh\">的</b><small>de</small></span><span class=\"ct-w c-b\"><b class=\"zh\">衣服</b><small>yīfu</small></span></div><div class=\"ct-vi\">của tôi · chiếc kia · mới mua · màu trắng · áo</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-b\">chiếc áo</span><span class=\"ct-w c-a\">trắng</span><span class=\"ct-w c-a\">mới mua</span><span class=\"ct-w c-a\">của mình</span></div></td></tr></tbody></table></div></div></div><p class=\"gr-key\"><b>Câu mẫu:</b> Cụm số lượng / chỉ thị (<span class=\"zh\">那个 · 两个</span>) linh hoạt: đứng <b>trước hoặc sau</b> định ngữ hành động.</p>","note":"<b>Lưu ý:</b> Tiếng Việt đặt định ngữ <b>sau</b> danh từ, tiếng Trung đặt <b>trước</b>: ✗ <span class=\"zh\">年轻人穿着黑衣服的</span> → ✓ <span class=\"zh\">穿着黑衣服的年轻人</span>","examples":[{"zh":"李文是那个穿着黑衣服的短头发的年轻人吗？","py":"Lǐ Wén shì nàge chuānzhe hēi yīfu de duǎn tóufa de niánqīngrén ma?","vi":"Lý Văn có phải là cậu thanh niên tóc ngắn mặc áo đen kia không?"},{"zh":"昨天和家月一起看电影的两个人是我的朋友。","py":"Zuótiān hé Jiāyuè yìqǐ kàn diànyǐng de liǎng ge rén shì wǒ de péngyou.","vi":"Hai người hôm qua xem phim cùng Gia Nguyệt là bạn mình."},{"zh":"我那件新买的白色的衣服在哪儿？","py":"Wǒ nà jiàn xīn mǎi de báisè de yīfu zài nǎr?","vi":"Chiếc áo trắng mới mua của mình đâu rồi?"}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在家里","titleVi":"Ở nhà — hai vợ chồng xem ảnh trên sofa","lines":[{"speaker":"明","name":"Lưu Minh","zh":"这是杨同乐吗？他怎么跟白家月在一起？","py":"Zhè shì Yáng Tónglè ma? Tā zěnme gēn Bái Jiāyuè zài yìqǐ?","vi":"Đây là Dương Đồng Lạc à? Sao cậu ấy lại ở cùng Bạch Gia Nguyệt?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"他不是杨同乐，他叫李文，是白家月的好朋友。","py":"Tā bú shì Yáng Tónglè, tā jiào Lǐ Wén, shì Bái Jiāyuè de hǎo péngyou.","vi":"Cậu ấy không phải Dương Đồng Lạc, cậu ấy tên Lý Văn, là bạn thân của Gia Nguyệt."},{"speaker":"明","name":"Lưu Minh","zh":"我还以为是同乐呢，他们看上去有点儿像。","py":"Wǒ hái yǐwéi shì Tónglè ne, tāmen kàn shàngqu yǒudiǎnr xiàng.","vi":"Anh cứ tưởng là Đồng Lạc chứ, trông hai người hơi giống nhau."},{"speaker":"雪","name":"Nhất Tuyết","zh":"是长得有点儿像，但是他比同乐高，身高有一米八。","py":"Shì zhǎng de yǒudiǎnr xiàng, dànshì tā bǐ Tónglè gāo, shēngāo yǒu yì mǐ bā.","vi":"Đúng là trông hơi giống, nhưng cậu ấy cao hơn Đồng Lạc, cao tới một mét tám."},{"speaker":"明","name":"Lưu Minh","zh":"看起来也比同乐瘦一点儿。","py":"Kàn qǐlai yě bǐ Tónglè shòu yìdiǎnr.","vi":"Trông cũng gầy hơn Đồng Lạc một chút."},{"speaker":"雪","name":"Nhất Tuyết","zh":"下个星期家月和李文要来北京，我去机场接他们。","py":"Xià ge xīngqī Jiāyuè hé Lǐ Wén yào lái Běijīng, wǒ qù jīchǎng jiē tāmen.","vi":"Tuần sau Gia Nguyệt và Lý Văn sẽ đến Bắc Kinh, em ra sân bay đón hai đứa."},{"speaker":"明","name":"Lưu Minh","zh":"他们哪天到北京？我跟你一起去机场接他们吧。","py":"Tāmen nǎ tiān dào Běijīng? Wǒ gēn nǐ yìqǐ qù jīchǎng jiē tāmen ba.","vi":"Hôm nào hai đứa đến Bắc Kinh? Anh đi cùng em ra sân bay đón nhé."}]},{"titleZh":"课文二 · 在机场","titleVi":"Sân bay — chờ lấy hành lý","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"我的行李怎么还没出来？是不是丢了？","py":"Wǒ de xíngli zěnme hái méi chūlai? Shì bu shì diū le?","vi":"Sao hành lý của mình vẫn chưa ra nhỉ? Có phải bị mất rồi không?"},{"speaker":"文","name":"Lý Văn","zh":"你的行李箱是什么样的？","py":"Nǐ de xínglixiāng shì shénme yàng de?","vi":"Va li của bạn trông thế nào?"},{"speaker":"月","name":"Gia Nguyệt","zh":"是一个黑色的箱子，上面写着我的名字和电话号码。","py":"Shì yí ge hēisè de xiāngzi, shàngmian xiězhe wǒ de míngzi hé diànhuà hàomǎ.","vi":"Là một chiếc va li màu đen, bên trên có ghi tên và số điện thoại của mình."},{"speaker":"文","name":"Lý Văn","zh":"我好像在哪儿看到过这个箱子，是不是有人拿错了？","py":"Wǒ hǎoxiàng zài nǎr kàndàoguo zhège xiāngzi, shì bu shì yǒu rén nácuò le?","vi":"Hình như mình đã thấy cái va li này ở đâu đó rồi, có phải ai cầm nhầm không?"},{"speaker":"月","name":"Gia Nguyệt","zh":"我们快找谁问一下吧，箱子里有不少重要的东西。","py":"Wǒmen kuài zhǎo shéi wèn yíxià ba, xiāngzi li yǒu bù shǎo zhòngyào de dōngxi.","vi":"Mình mau tìm ai đó hỏi thử đi, trong va li có khá nhiều đồ quan trọng."},{"speaker":"文","name":"Lý Văn","zh":"别着急，我们拿着护照和机票，去服务台问问吧。","py":"Bié zháojí, wǒmen názhe hùzhào hé jīpiào, qù fúwùtái wènwen ba.","vi":"Đừng sốt ruột, mình cầm hộ chiếu với vé máy bay ra quầy dịch vụ hỏi xem."}]},{"titleZh":"课文三 · 在机场大厅","titleVi":"Sảnh sân bay — hai vợ chồng chờ đón","lines":[{"speaker":"明","name":"Lưu Minh","zh":"飞机早就到了，你看见白家月他们了吗？","py":"Fēijī zǎo jiù dào le, nǐ kànjiàn Bái Jiāyuè tāmen le ma?","vi":"Máy bay đến từ lâu rồi, em thấy bọn Gia Nguyệt chưa?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"没有，他们应该快出来了。","py":"Méiyǒu, tāmen yīnggāi kuài chūlai le.","vi":"Chưa, chắc hai đứa sắp ra rồi."},{"speaker":"明","name":"Lưu Minh","zh":"我们站到中间去吧，这样他们好找一些。","py":"Wǒmen zhàndào zhōngjiān qù ba, zhèyàng tāmen hǎo zhǎo yìxiē.","vi":"Mình ra đứng ở giữa đi, như vậy tụi nhỏ dễ tìm hơn."},{"speaker":"雪","name":"Nhất Tuyết","zh":"你看那个高个子的人是李文吗？","py":"Nǐ kàn nàge gāo gèzi de rén shì Lǐ Wén ma?","vi":"Anh xem người cao cao kia có phải Lý Văn không?"},{"speaker":"明","name":"Lưu Minh","zh":"你说的是哪个？那个穿着黑衣服的短头发的年轻人？","py":"Nǐ shuō de shì nǎge? Nàge chuānzhe hēi yīfu de duǎn tóufa de niánqīngrén?","vi":"Em nói người nào? Cậu thanh niên tóc ngắn mặc áo đen kia à?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"对，那个人就是李文！你看，家月在他后面呢。","py":"Duì, nàge rén jiù shì Lǐ Wén! Nǐ kàn, Jiāyuè zài tā hòumian ne.","vi":"Đúng, người đó chính là Lý Văn! Anh xem, Gia Nguyệt ở ngay sau cậu ấy kìa."}]},{"titleZh":"课文四 · 在宾馆房间","titleVi":"Phòng khách sạn — nhật ký Lý Văn","para":true,"speaker":"文","lines":[{"zh":"昨天我到北京了。","py":"Zuótiān wǒ dào Běijīng le.","vi":"Hôm qua tôi đã đến Bắc Kinh."},{"zh":"虽然路上花了十几个小时，但是跟家月坐在一起，我觉得时间过得很快。","py":"Suīrán lùshang huāle shí jǐ ge xiǎoshí, dànshì gēn Jiāyuè zuò zài yìqǐ, wǒ juéde shíjiān guò de hěn kuài.","vi":"Tuy trên đường mất hơn mười tiếng, nhưng được ngồi cạnh Gia Nguyệt nên tôi thấy thời gian trôi rất nhanh."},{"zh":"到机场的时候，家月发现行李箱不见了，我带她去服务台，帮助她找到了行李箱。","py":"Dào jīchǎng de shíhou, Jiāyuè fāxiàn xínglixiāng bújiàn le, wǒ dài tā qù fúwùtái, bāngzhù tā zhǎodàole xínglixiāng.","vi":"Lúc đến sân bay, Gia Nguyệt phát hiện va li không thấy đâu, tôi dẫn cô ấy ra quầy dịch vụ, giúp cô ấy tìm lại được va li."},{"zh":"走出机场的时候，已经八点多了，我们一出来就看见了王老师的姐姐，她看起来比照片上年轻。","py":"Zǒuchū jīchǎng de shíhou, yǐjīng bā diǎn duō le, wǒmen yì chūlai jiù kànjiànle Wáng lǎoshī de jiějie, tā kàn qǐlai bǐ zhàopiàn shang niánqīng.","vi":"Lúc ra khỏi sân bay đã hơn tám giờ, chúng tôi vừa ra là thấy ngay chị của cô Vương, trông chị ấy trẻ hơn trong ảnh."},{"zh":"晚上，一雪姐带我们去吃了一家很好吃的中国菜。","py":"Wǎnshang, Yīxuě jiě dài wǒmen qù chīle yì jiā hěn hǎochī de Zhōngguócài.","vi":"Buổi tối, chị Nhất Tuyết dẫn chúng tôi đi ăn ở một quán món Trung Quốc rất ngon."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Cảnh 1 · Ra sân bay đón người","q":{"zh":"A去机场接B，不知道B长什么样；B打电话告诉A自己在哪儿。","py":"A qù jīchǎng jiē B, bù zhīdào B zhǎng shénme yàng; B dǎ diànhuà gàosu A zìjǐ zài nǎr.","vi":"A ra sân bay đón B nhưng không biết B trông thế nào; B gọi điện báo A mình đang ở đâu."},"items":[{"lines":[{"who":"A","zh":"喂，你出来了吗？你在哪儿？","py":"Wèi, nǐ chūlai le ma? Nǐ zài nǎr?","vi":"A lô, bạn ra chưa? Bạn đang ở đâu?"},{"who":"B","zh":"我站在服务台旁边，拿着一个黑色的行李箱。","py":"Wǒ zhàn zài fúwùtái pángbiān, názhe yí ge hēisè de xínglixiāng.","vi":"Mình đứng cạnh quầy dịch vụ, cầm một chiếc va li màu đen."}]},{"zh":"我是那个穿着白衣服的短头发的女孩儿。","py":"Wǒ shì nàge chuānzhe bái yīfu de duǎn tóufa de nǚháir.","vi":"Mình là cô gái tóc ngắn mặc áo trắng kia."},{"zh":"你看上去比照片上年轻！","py":"Nǐ kàn shàngqu bǐ zhàopiàn shang niánqīng!","vi":"Trông bạn trẻ hơn trong ảnh!"}]},{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Cảnh 2 · Hộ chiếu không thấy đâu","q":{"zh":"A到机场，发现护照不见了，很着急；B是A的朋友，帮忙找护照。","py":"A dào jīchǎng, fāxiàn hùzhào bújiàn le, hěn zháojí; B shì A de péngyou, bāngmáng zhǎo hùzhào.","vi":"A đến sân bay thì phát hiện hộ chiếu không thấy đâu, rất sốt ruột; B là bạn của A, giúp tìm."},"items":[{"lines":[{"who":"A","zh":"我的护照不见了！是不是丢了？","py":"Wǒ de hùzhào bújiàn le! Shì bu shì diū le?","vi":"Hộ chiếu của mình không thấy đâu! Có phải mất rồi không?"},{"who":"B","zh":"别着急，你的护照是什么样的？","py":"Bié zháojí, nǐ de hùzhào shì shénme yàng de?","vi":"Đừng sốt ruột, hộ chiếu của bạn trông thế nào?"}]},{"zh":"我好像在哪儿看到过，是不是在你的包里？","py":"Wǒ hǎoxiàng zài nǎr kàndàoguo, shì bu shì zài nǐ de bāo li?","vi":"Hình như mình đã thấy ở đâu đó, có phải trong túi bạn không?"},{"zh":"我们去服务台找谁问一下吧。","py":"Wǒmen qù fúwùtái zhǎo shéi wèn yíxià ba.","vi":"Mình ra quầy dịch vụ tìm ai đó hỏi thử đi."}]}],"speak":[]}},{"id":"k3v3-b02","courseId":"k3v3","order":2,"title":"Các bạn muốn ăn gì thì gọi nấy","titleZh":"你们想吃什么就点什么","titlePy":"nǐmen xiǎng chī shénme jiù diǎn shénme","vocab":[{"stt":1,"hanzi":"菜单","pinyin":"càidān","hanviet":"Thái đơn","pos":"Danh từ","meaning":"thực đơn","comps":"看菜单 (xem thực đơn), 一张菜单 (một tờ thực đơn)","example":{"zh":"服务员，请给我们菜单。","py":"Fúwùyuán, qǐng gěi wǒmen càidān.","vi":"Em ơi, cho chúng tôi xin thực đơn."}},{"stt":2,"hanzi":"又","pinyin":"yòu","hanviet":"Hựu","pos":"Phó từ","meaning":"vừa… (vừa…); lại","comps":"又……又…… (vừa… vừa…), 又高又瘦 (vừa cao vừa gầy)","example":{"zh":"这个苹果又大又甜。","py":"Zhège píngguǒ yòu dà yòu tián.","vi":"Quả táo này vừa to vừa ngọt."}},{"stt":3,"hanzi":"饿","pinyin":"è","hanviet":"Ngạ","pos":"Tính từ","meaning":"đói","comps":"饿了 (đói rồi), 很饿 (rất đói)","example":{"zh":"我饿了，我们去吃饭吧。","py":"Wǒ è le, wǒmen qù chīfàn ba.","vi":"Mình đói rồi, chúng mình đi ăn đi."}},{"stt":4,"hanzi":"渴","pinyin":"kě","hanviet":"Khát","pos":"Tính từ","meaning":"khát","comps":"渴了 (khát rồi), 又饿又渴 (vừa đói vừa khát)","example":{"zh":"你渴不渴？喝点儿水吧。","py":"Nǐ kě bu kě? Hē diǎnr shuǐ ba.","vi":"Bạn có khát không? Uống chút nước đi."}},{"stt":5,"hanzi":"客气","pinyin":"kèqi","hanviet":"Khách khí","pos":"Động từ / Tính từ","meaning":"khách sáo; lịch sự","comps":"别客气 (đừng khách sáo), 不客气 (không có gì)","example":{"zh":"别客气，多吃点儿。","py":"Bié kèqi, duō chī diǎnr.","vi":"Đừng khách sáo, ăn nhiều vào nhé."}},{"stt":6,"hanzi":"饮料","pinyin":"yǐnliào","hanviet":"Ẩm liệu","pos":"Danh từ","meaning":"đồ uống","comps":"喝饮料 (uống nước ngọt / đồ uống), 买饮料 (mua đồ uống)","example":{"zh":"你想喝什么饮料？","py":"Nǐ xiǎng hē shénme yǐnliào?","vi":"Bạn muốn uống gì?"}},{"stt":7,"hanzi":"好久","pinyin":"hǎojiǔ","hanviet":"Hảo cửu","pos":"Tính từ","meaning":"rất lâu, lâu lắm","comps":"好久不见 (lâu rồi không gặp), 等了好久 (đợi rất lâu)","example":{"zh":"好久不见，你最近怎么样？","py":"Hǎojiǔ bú jiàn, nǐ zuìjìn zěnmeyàng?","vi":"Lâu rồi không gặp, dạo này bạn thế nào?"}},{"stt":8,"hanzi":"服务","pinyin":"fúwù","hanviet":"Phục vụ","pos":"Động từ","meaning":"phục vụ","comps":"服务很好 (phục vụ tốt), 服务台 (quầy dịch vụ)","example":{"zh":"这家饭馆的服务很好。","py":"Zhè jiā fànguǎn de fúwù hěn hǎo.","vi":"Quán này phục vụ rất tốt."}},{"stt":9,"hanzi":"员","pinyin":"yuán","hanviet":"Viên","pos":"Hậu tố","meaning":"viên, người (làm việc gì)","comps":"服务员 (nhân viên phục vụ), 售货员 (người bán hàng)","example":{"zh":"服务员，请给我一杯水。","py":"Fúwùyuán, qǐng gěi wǒ yì bēi shuǐ.","vi":"Em ơi, cho tôi một cốc nước."}},{"stt":10,"hanzi":"双","pinyin":"shuāng","hanviet":"Song","pos":"Lượng từ","meaning":"đôi","comps":"一双筷子 (một đôi đũa), 一双鞋 (một đôi giày)","example":{"zh":"我买了一双新鞋。","py":"Wǒ mǎile yì shuāng xīn xié.","vi":"Mình mua một đôi giày mới."}},{"stt":11,"hanzi":"筷子","pinyin":"kuàizi","hanviet":"Khoái tử","pos":"Danh từ","meaning":"đũa","comps":"用筷子 (dùng đũa), 一双筷子 (một đôi đũa)","example":{"zh":"你会用筷子吗？","py":"Nǐ huì yòng kuàizi ma?","vi":"Bạn có biết dùng đũa không?"}},{"stt":12,"hanzi":"勺子","pinyin":"sháozi","hanviet":"Chước tử","pos":"Danh từ","meaning":"thìa, muỗng","comps":"一个勺子 (một cái thìa), 用勺子 (dùng thìa)","example":{"zh":"请再给我一个勺子。","py":"Qǐng zài gěi wǒ yí ge sháozi.","vi":"Cho tôi thêm một cái thìa nữa."}},{"stt":13,"hanzi":"碗","pinyin":"wǎn","hanviet":"Uyển","pos":"Danh từ","meaning":"bát, chén","comps":"一个碗 (một cái bát), 一碗米饭 (một bát cơm)","example":{"zh":"我吃了两碗米饭。","py":"Wǒ chīle liǎng wǎn mǐfàn.","vi":"Mình ăn hai bát cơm."}},{"stt":14,"hanzi":"马上","pinyin":"mǎshàng","hanviet":"Mã thượng","pos":"Phó từ","meaning":"ngay, lập tức","comps":"马上来 (đến ngay), 马上就好 (xong ngay)","example":{"zh":"请等一下，我马上来。","py":"Qǐng děng yíxià, wǒ mǎshàng lái.","vi":"Xin chờ một chút, tôi đến ngay."}},{"stt":15,"hanzi":"热情","pinyin":"rèqíng","hanviet":"Nhiệt tình","pos":"Tính từ","meaning":"nhiệt tình","comps":"很热情 (rất nhiệt tình), 热情的人 (người nhiệt tình)","example":{"zh":"我的中国朋友都很热情。","py":"Wǒ de Zhōngguó péngyou dōu hěn rèqíng.","vi":"Bạn bè Trung Quốc của mình đều rất nhiệt tình."}},{"stt":16,"hanzi":"尝","pinyin":"cháng","hanviet":"Thường","pos":"Động từ","meaning":"nếm","comps":"尝尝 (nếm thử), 尝一下 (nếm một chút)","example":{"zh":"你尝尝这个菜，很好吃。","py":"Nǐ chángchang zhège cài, hěn hǎochī.","vi":"Bạn nếm thử món này đi, ngon lắm."}},{"stt":17,"hanzi":"记","pinyin":"jì","hanviet":"Ký","pos":"Động từ","meaning":"nhớ, ghi nhớ; ghi lại","comps":"记住 (nhớ kỹ), 记下来 (ghi lại)","example":{"zh":"我记住你的名字了。","py":"Wǒ jìzhù nǐ de míngzi le.","vi":"Mình nhớ tên bạn rồi."}},{"stt":18,"hanzi":"用","pinyin":"yòng","hanviet":"Dụng","pos":"Động từ","meaning":"dùng (lịch sự: ăn, uống)","comps":"请慢用 (mời dùng bữa ngon miệng), 用筷子 (dùng đũa)","example":{"zh":"菜来了，请慢用。","py":"Cài lái le, qǐng màn yòng.","vi":"Món lên rồi, mời quý khách dùng bữa."}},{"stt":19,"hanzi":"鸡","pinyin":"jī","hanviet":"Kê","pos":"Danh từ","meaning":"gà","comps":"鸡肉 (thịt gà), 鸡肉饭 (cơm gà)","example":{"zh":"我最喜欢吃鸡肉。","py":"Wǒ zuì xǐhuan chī jīròu.","vi":"Mình thích ăn thịt gà nhất."}},{"stt":20,"hanzi":"张","pinyin":"zhāng","hanviet":"Trương","pos":"Lượng từ","meaning":"tờ, tấm (vật mỏng, phẳng)","comps":"一张菜单 (một tờ thực đơn), 一张照片 (một tấm ảnh)","example":{"zh":"我买了两张电影票。","py":"Wǒ mǎile liǎng zhāng diànyǐngpiào.","vi":"Mình mua hai vé xem phim."}},{"stt":21,"hanzi":"不用","pinyin":"búyòng","hanviet":"Bất dụng","pos":"Phó từ","meaning":"không cần","comps":"不用谢 (không cần cảm ơn), 不用拿 (không cần mang)","example":{"zh":"明天是周末，不用上班。","py":"Míngtiān shì zhōumò, búyòng shàngbān.","vi":"Mai là cuối tuần, không cần đi làm."}},{"stt":22,"hanzi":"选","pinyin":"xuǎn","hanviet":"Tuyển","pos":"Động từ","meaning":"chọn","comps":"选好 (chọn xong), 选一个 (chọn một cái)","example":{"zh":"这两件衣服，你选哪件？","py":"Zhè liǎng jiàn yīfu, nǐ xuǎn nǎ jiàn?","vi":"Hai chiếc áo này, bạn chọn chiếc nào?"}},{"stt":23,"hanzi":"外卖","pinyin":"wàimài","hanviet":"Ngoại mại","pos":"Danh từ / Động từ","meaning":"đồ ăn giao tận nơi; bán mang đi","comps":"点外卖 (gọi đồ ăn ngoài), 送外卖 (giao đồ ăn)","example":{"zh":"今天太累了，我们点外卖吧。","py":"Jīntiān tài lèi le, wǒmen diǎn wàimài ba.","vi":"Hôm nay mệt quá, mình gọi đồ ăn ngoài đi."}},{"stt":24,"hanzi":"方便","pinyin":"fāngbiàn","hanviet":"Phương tiện","pos":"Tính từ","meaning":"tiện lợi, thuận tiện","comps":"很方便 (rất tiện), 不方便 (không tiện)","example":{"zh":"住在这儿，买东西很方便。","py":"Zhù zài zhèr, mǎi dōngxi hěn fāngbiàn.","vi":"Sống ở đây mua đồ rất tiện."}},{"stt":25,"hanzi":"蛋糕","pinyin":"dàngāo","hanviet":"Đản cao","pos":"Danh từ","meaning":"bánh ngọt, bánh gato","comps":"生日蛋糕 (bánh sinh nhật), 一块蛋糕 (một miếng bánh)","example":{"zh":"这是妈妈做的生日蛋糕。","py":"Zhè shì māma zuò de shēngrì dàngāo.","vi":"Đây là bánh sinh nhật mẹ làm."}},{"stt":26,"hanzi":"只","pinyin":"zhǐ","hanviet":"Chỉ","pos":"Phó từ","meaning":"chỉ","comps":"只有 (chỉ có), 只吃 (chỉ ăn)","example":{"zh":"早上我只喝了一杯咖啡。","py":"Zǎoshang wǒ zhǐ hēle yì bēi kāfēi.","vi":"Sáng nay mình chỉ uống một cốc cà phê."}},{"stt":27,"hanzi":"方便面","pinyin":"fāngbiànmiàn","hanviet":"Phương tiện miến","pos":"Danh từ","meaning":"mì ăn liền, mì tôm","comps":"吃方便面 (ăn mì tôm), 一包方便面 (một gói mì)","example":{"zh":"太忙的时候，我常吃方便面。","py":"Tài máng de shíhou, wǒ cháng chī fāngbiànmiàn.","vi":"Lúc bận quá, mình hay ăn mì tôm."}},{"stt":28,"hanzi":"简单","pinyin":"jiǎndān","hanviet":"Giản đơn","pos":"Tính từ","meaning":"đơn giản","comps":"很简单 (rất đơn giản), 简单的菜 (món đơn giản)","example":{"zh":"这个问题很简单。","py":"Zhège wèntí hěn jiǎndān.","vi":"Câu hỏi này rất đơn giản."}}],"hanzi":[{"char":"菜单","pinyin":"càidān","hanviet":"Thái đơn","chars":["菜","单"],"story":"菜 = 艹 (cỏ, rau) + 采 cǎi (hái): rau hái về → rau, món ăn. 单 = tờ giấy ghi, danh sách (单子). 菜单 = danh sách các món → thực đơn."},{"char":"又","pinyin":"yòu","hanviet":"Hựu","chars":["又"],"story":"又 vẽ bàn tay phải (ba ngón). Bàn tay phải làm đi làm lại một việc → \"lại, nữa\". Đặt hai lần: 又A又B = vừa A vừa B."},{"char":"饿","pinyin":"è","hanviet":"Ngạ","chars":["饿"],"story":"饿 là chữ hình thanh: bộ Thực 饣 (ăn) chỉ nghĩa, 我 wǒ chỉ âm. Mẹo nhớ: \"我\" chưa được \"ăn\" 饣 → đói."},{"char":"渴","pinyin":"kě","hanviet":"Khát","chars":["渴"],"story":"渴 là chữ hình thanh: bộ Thuỷ 氵 (nước) chỉ nghĩa, 曷 hé chỉ âm. Thiếu nước → khát. Phân biệt: 喝 (bộ Khẩu 口 — uống) và 渴 (bộ Thuỷ 氵 — khát)."},{"char":"客气","pinyin":"kèqi","hanviet":"Khách khí","chars":["客","气"],"story":"客 = 宀 (mái nhà) + 各 (từ nơi khác tới): người từ nơi khác đến nhà → khách. 气 = hơi, khí, phong thái. 客气 = phong thái của khách → khách sáo, lịch sự."},{"char":"饮料","pinyin":"yǐnliào","hanviet":"Ẩm liệu","chars":["饮","料"],"story":"饮 = 饣 (ăn uống) + 欠 (người há miệng) → uống. 料 = 米 (gạo) + 斗 (cái đấu đong) → nguyên liệu, thứ. 饮料 = thứ để uống → đồ uống."},{"char":"好久","pinyin":"hǎojiǔ","hanviet":"Hảo cửu","chars":["好","久"],"story":"好 ở đây là phó từ \"rất, lắm\" (như 好多, 好几天). 久 vẽ người có vật kéo dài phía sau → kéo dài, lâu. 好久 = rất lâu: 好久不见 = lâu lắm không gặp."},{"char":"服务","pinyin":"fúwù","hanviet":"Phục vụ","chars":["服","务"],"story":"服 = phục tùng, làm theo; 务 = 夂 + 力 (dùng sức) → công việc. 服务 = làm việc theo ý người khác → phục vụ. Đã gặp trong 服务台 (bài 1)."},{"char":"员","pinyin":"yuán","hanviet":"Viên","chars":["员"],"story":"员 = 口 + 贝 (vỏ sò): vốn chỉ miệng chiếc vạc tròn, sau mượn chỉ \"người, thành viên\". Đứng sau danh từ / động từ để chỉ người làm việc đó: 服务员, 售货员."},{"char":"双","pinyin":"shuāng","hanviet":"Song","chars":["双"],"story":"双 = hai chữ 又 (bàn tay) đứng cạnh nhau → hai bàn tay → một đôi. Phồn thể 雙 vẽ bàn tay cầm hai con chim. 一双筷子 = một đôi đũa."},{"char":"筷子","pinyin":"kuàizi","hanviet":"Khoái tử","chars":["筷","子"],"story":"筷 là chữ hình thanh: bộ Trúc ⺮ (tre) chỉ nghĩa, 快 kuài (nhanh) chỉ âm — đũa xưa làm bằng tre. Mẹo nhớ: đôi đũa tre giúp gắp \"nhanh\". 子 là hậu tố danh từ."},{"char":"勺子","pinyin":"sháozi","hanviet":"Chước tử","chars":["勺","子"],"story":"勺 vẽ cái muôi cong, chấm bên trong là thức ăn được múc lên → muôi, thìa. 子 là hậu tố danh từ. 勺子 = cái thìa."},{"char":"碗","pinyin":"wǎn","hanviet":"Uyển","chars":["碗"],"story":"碗 là chữ hình thanh: bộ Thạch 石 (đá) chỉ nghĩa, 宛 wǎn chỉ âm — bát xưa làm bằng đá, gốm. 碗 vừa là danh từ (一个碗) vừa làm lượng từ (一碗米饭)."},{"char":"马上","pinyin":"mǎshàng","hanviet":"Mã thượng","chars":["马","上"],"story":"马 = con ngựa, 上 = ở trên. 马上 = \"đang ở trên lưng ngựa\" — lên ngựa là đi được ngay → ngay, lập tức."},{"char":"热情","pinyin":"rèqíng","hanviet":"Nhiệt tình","chars":["热","情"],"story":"热 = 执 + 灬 (lửa) → nóng. 情 = 忄 (trái tim) chỉ nghĩa + 青 qīng chỉ âm → tình cảm. 热情 = tình cảm nóng hổi → nhiệt tình."},{"char":"尝","pinyin":"cháng","hanviet":"Thường","chars":["尝"],"story":"Phồn thể 嘗 = 尚 (chỉ âm) + 旨 (vị ngon): đưa vào miệng để biết vị ngon → nếm. Hay dùng dạng lặp 尝尝 = nếm thử."},{"char":"记","pinyin":"jì","hanviet":"Ký","chars":["记"],"story":"记 là chữ hình thanh: bộ Ngôn 讠 (lời nói) chỉ nghĩa, 己 jǐ chỉ âm. Ghi lời nói lại → ghi, nhớ. 记住 = nhớ kỹ, không quên."},{"char":"用","pinyin":"yòng","hanviet":"Dụng","chars":["用"],"story":"用 vẽ cái thùng gỗ, đồ dùng → dùng. Ở nhà hàng, 用 là cách nói lịch sự thay cho \"ăn, uống\": 请慢用 = mời quý khách dùng bữa (cứ thong thả)."},{"char":"鸡","pinyin":"jī","hanviet":"Kê","chars":["鸡"],"story":"鸡 = 又 + 鸟 (chim). Phồn thể 雞 = 奚 xī chỉ âm + 隹 (chim đuôi ngắn). Loài chim nuôi trong nhà → gà. 鸡肉 = thịt gà."},{"char":"张","pinyin":"zhāng","hanviet":"Trương","chars":["张"],"story":"张 là chữ hình thanh: bộ Cung 弓 (cây cung) chỉ nghĩa, 长 cháng chỉ âm → nghĩa gốc là giương cung. Mặt cung giương ra phẳng → làm lượng từ cho vật mỏng, phẳng: 一张纸, 一张菜单, 一张照片. 张 cũng là họ Trương."},{"char":"不用","pinyin":"búyòng","hanviet":"Bất dụng","chars":["不","用"],"story":"不 (không) + 用 (dùng, cần đến). 不用 = không cần dùng tới → không cần, khỏi phải. 不用谢 = không cần cảm ơn."},{"char":"选","pinyin":"xuǎn","hanviet":"Tuyển","chars":["选"],"story":"选 = 辶 (bước đi) + 先 xiān (trước): bước lên trước để lựa ra → chọn. 选好了 = chọn xong rồi."},{"char":"外卖","pinyin":"wàimài","hanviet":"Ngoại mại","chars":["外","卖"],"story":"外 = 夕 (buổi tối) + 卜 (bói): bói vào buổi tối là việc ngoài lệ → bên ngoài. 卖 = 十 + 买 (mua): đem ra cho người mua → bán. 外卖 = bán ra ngoài → đồ ăn mang đi, giao tận nơi."},{"char":"方便","pinyin":"fāngbiàn","hanviet":"Phương tiện","chars":["方","便"],"story":"方 = phương, cách. 便 = 亻 (người) + 更 (đổi): người đổi cách cho thuận → tiện. 方便 = có cách làm thuận lợi → tiện lợi."},{"char":"蛋糕","pinyin":"dàngāo","hanviet":"Đản cao","chars":["蛋","糕"],"story":"蛋 = 疋 + 虫 → trứng. 糕 là chữ hình thanh: bộ Mễ 米 (gạo, bột) chỉ nghĩa, 羔 gāo chỉ âm → bánh làm từ bột. 蛋糕 = bánh làm từ trứng và bột → bánh ngọt."},{"char":"只","pinyin":"zhǐ","hanviet":"Chỉ","chars":["只"],"story":"只 = 口 + 八. Đọc zhǐ là phó từ \"chỉ\": 只吃方便面. Cùng chữ này đọc zhī là lượng từ cho con vật: 一只猫 — chú ý phân biệt."},{"char":"方便面","pinyin":"fāngbiànmiàn","hanviet":"Phương tiện miến","chars":["方","便","面"],"story":"方便 (tiện lợi) + 面 (mì, sợi mì). Chỉ cần đổ nước sôi chờ vài phút là ăn được → mì ăn liền, mì tôm."},{"char":"简单","pinyin":"jiǎndān","hanviet":"Giản đơn","chars":["简","单"],"story":"简 là chữ hình thanh: bộ Trúc ⺮ (tre) chỉ nghĩa, 间 jiān chỉ âm — thẻ tre viết chữ thời xưa, nên viết thật gọn. 单 = đơn, một. 简单 = gọn và đơn → đơn giản."}],"grammar":[{"title":"Câu phức 又……又……","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>người / vật</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>又</b><small>vừa</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词₁</b><small>tính từ 1</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>又</b><small>vừa</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词₂</b><small>tính từ 2</small></span></div>","summary":"<p class=\"gr-lead\">Vừa… vừa… — hai đặc điểm cùng lúc</p><ul><li><span class=\"zh\">又 A 又 B</span> = \"vừa A vừa B\": người / vật <b>đồng thời có hai đặc điểm</b>; A, B thường là tính từ.</li><li>Hai đặc điểm thường <b>cùng chiều</b> (cùng tốt / cùng xấu): <span class=\"zh\">又便宜又好吃</span> · <span class=\"zh\">又忙又累</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我现在还真是又饿又渴。</span>　·　<span class=\"zh\">这个饭馆的菜又便宜又好吃。</span></p>","note":"<b>Lưu ý:</b> Không dùng <span class=\"zh\">和</span> nối hai tính từ: ✗ <span class=\"zh\">那个女孩儿高和漂亮</span> → ✓ <span class=\"zh\">那个女孩儿又高又漂亮</span>","examples":[{"zh":"我现在还真是又饿又渴。","py":"Wǒ xiànzài hái zhēn shì yòu è yòu kě.","vi":"Bây giờ mình đúng là vừa đói vừa khát."},{"zh":"那个女孩儿又高又漂亮。","py":"Nàge nǚháir yòu gāo yòu piàoliang.","vi":"Cô gái kia vừa cao vừa xinh."},{"zh":"这个饭馆的菜又便宜又好吃。","py":"Zhège fànguǎn de cài yòu piányi yòu hǎochī.","vi":"Món ăn ở quán này vừa rẻ vừa ngon."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">他的新家很大，也很干净。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">他的新家____。</span></span></span><span class=\"qz-hint\">Nhà mới của anh ấy rất rộng, cũng rất sạch. — Nhà mới của anh ấy vừa rộng vừa sạch.</span>","answer":["又大又干净"],"explain":"他的新家又大又干净。 (Tā de xīn jiā yòu dà yòu gānjìng.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">他写汉字写得很快，也很漂亮。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">他写汉字写得____。</span></span></span><span class=\"qz-hint\">Anh ấy viết chữ Hán rất nhanh, cũng rất đẹp. — Anh ấy viết chữ Hán vừa nhanh vừa đẹp.</span>","answer":["又快又漂亮"],"explain":"他写汉字写得又快又漂亮。 (Tā xiě Hànzì xiě de yòu kuài yòu piàoliang.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这个超市里的东西很多，也很便宜。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">这个超市里的东西____。</span></span></span><span class=\"qz-hint\">Đồ trong siêu thị này rất nhiều, cũng rất rẻ. — Đồ trong siêu thị này vừa nhiều vừa rẻ.</span>","answer":["又多又便宜"],"explain":"这个超市里的东西又多又便宜。 (Zhège chāoshì li de dōngxi yòu duō yòu piányi.)"}]},{"title":"Đại từ nghi vấn dùng không để hỏi (2)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>(主语)</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>谁 · 什么 · 哪 · 怎么</b><small>bất kỳ…</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>都</b><small>đều, cũng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>谓语</b><small>vị ngữ</small></span></div>","summary":"<p class=\"gr-lead\">Ai cũng · gì cũng · đâu cũng</p><ul><li>Đại từ nghi vấn chỉ <b>bất kỳ</b> ai / cái gì / nơi nào / cách nào: <span class=\"zh\">谁</span> = bất kỳ ai, <span class=\"zh\">什么</span> = bất kỳ cái gì.</li><li>Phía sau thường có <span class=\"zh\">都</span> hô ứng: <span class=\"zh\">去哪儿都可以</span> = đi đâu cũng được.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">疑问代词的非疑问用法 (2)</span> · Bốn đại từ</h4><p>Câu hỏi ↔ phiếm chỉ</p><div class=\"gr-formula\"><div class=\"fx-lbl\">哪 + LT · nào cũng</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>哪个菜</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>都</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>好吃</b></span></div><div class=\"fx-ex zh\">哪个菜都好吃。</div><div class=\"fx-lbl\">哪儿 · đâu cũng</div><div class=\"fx-row\"><span class=\"fx-p\"><b>去</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>哪儿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>都可以</b></span></div><div class=\"fx-ex zh\">这次旅游，我去哪儿都可以。</div><div class=\"fx-lbl\">什么时候 · lúc nào cũng</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>什么时候</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>来</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>都没问题</b></span></div><div class=\"fx-ex zh\">你想什么时候来都没问题。</div><div class=\"fx-lbl\">谁 · ai cũng</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>谁</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>都</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>知道</b></span></div><div class=\"fx-ex zh\">这件事谁都知道。</div></div><p class=\"gr-key\">Câu hỏi: <span class=\"zh\">你想去哪儿？</span> (Bạn muốn đi đâu?)　→　Phiếm chỉ: <span class=\"zh\">我去哪儿都可以。</span> (Mình đi <b>đâu cũng</b> được.)</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">哪个菜都好吃。</span> = Món <b>nào cũng</b> ngon.</p>","note":"<b>Lưu ý:</b> <span class=\"zh\">都</span> đứng <b>sau</b> đại từ nghi vấn: ✗ <span class=\"zh\">我都什么喜欢吃</span> → ✓ <span class=\"zh\">我什么都喜欢吃</span>","examples":[{"zh":"哪个菜都好吃。","py":"Nǎge cài dōu hǎochī.","vi":"Món nào cũng ngon."},{"zh":"这次旅游，我去哪儿都可以。","py":"Zhè cì lǚyóu, wǒ qù nǎr dōu kěyǐ.","vi":"Chuyến du lịch lần này, mình đi đâu cũng được."},{"zh":"我下午有时间，你想什么时候来都没问题。","py":"Wǒ xiàwǔ yǒu shíjiān, nǐ xiǎng shénme shíhou lái dōu méi wèntí.","vi":"Chiều nay mình rảnh, bạn muốn đến lúc nào cũng được."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我喜欢吃中国菜，也喜欢吃外国菜。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我____。（什么）</span></span></span><span class=\"qz-hint\">Mình thích ăn món Trung Quốc, cũng thích món nước ngoài. — Món gì mình cũng thích ăn.</span>","answer":["什么菜都喜欢吃","什么菜我都喜欢吃","什么都喜欢吃"],"explain":"我什么菜都喜欢吃。（什么） (Wǒ shénme cài dōu xǐhuan chī. (shénme))"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">小李很会做饭，大家都喜欢吃他做的饭。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">小李很会做饭，____。（谁）</span></span></span><span class=\"qz-hint\">Tiểu Lý nấu ăn rất giỏi, mọi người đều thích cơm cậu ấy nấu. — Tiểu Lý nấu ăn rất giỏi, ai cũng thích cơm cậu ấy nấu.</span>","answer":["谁都喜欢吃他做的饭","谁都喜欢吃他做的菜"],"explain":"小李很会做饭，谁都喜欢吃他做的饭。（谁） (Xiǎo Lǐ hěn huì zuòfàn, shéi dōu xǐhuan chī tā zuò de fàn. (shéi))"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">饭馆不太远，我们打车、坐公交车、走路去都可以。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">饭馆不太远，我们____。（怎么）</span></span></span><span class=\"qz-hint\">Quán không xa lắm, đi taxi, xe buýt hay đi bộ đều được. — Quán không xa lắm, mình đi cách nào cũng được.</span>","answer":["怎么去都可以","怎么去都行"],"explain":"饭馆不太远，我们怎么去都可以。（怎么） (Fànguǎn bú tài yuǎn, wǒmen zěnme qù dōu kěyǐ. (zěnme))"}]},{"title":"Đại từ nghi vấn dùng không để hỏi (3)","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>(主语₁) + V₁ + 疑问代词</b><small>… gì / nào / đâu</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>(主语₂) + 就</b><small>thì</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>V₂ + 疑问代词</b><small>… nấy / đó</small></span></div>","summary":"<p class=\"gr-lead\">… gì thì … nấy</p><ul><li>Hai đại từ nghi vấn <b>giống nhau</b> hô ứng trước – sau, cùng chỉ một người / vật / nơi / lúc: \"… gì thì … nấy\".</li><li><b>Cùng chủ ngữ</b> → vế sau lược chủ ngữ. <b>Khác chủ ngữ</b> → chủ ngữ thứ hai đặt <b>trước 就</b>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">疑问代词的非疑问用法 (3)</span> · Cùng / khác chủ ngữ</h4><p>Đại từ trước = đại từ sau</p><div class=\"gr-formula\"><div class=\"fx-lbl\">什么 · gì → nấy</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>想吃什么</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>点什么</b></span></div><div class=\"fx-ex zh\">你们想吃什么就点什么。</div><div class=\"fx-lbl\">哪个 · nào → nấy</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>哪个好看</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>买哪个</b></span></div><div class=\"fx-ex zh\">你觉得哪个好看就买哪个。</div><div class=\"fx-lbl\">哪儿 · khác chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>你想去哪儿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>我们 + 就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>去哪儿</b></span></div><div class=\"fx-ex zh\">你想去哪儿，我们就去哪儿。</div><div class=\"fx-lbl\">谁 · ai → người đó</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>谁先到</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>谁 + 就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>点菜</b></span></div><div class=\"fx-ex zh\">谁先到，谁就点菜。</div></div><p class=\"gr-key\">Cùng chủ ngữ: vế sau <b>lược</b> chủ ngữ　·　Khác chủ ngữ: <b>chủ ngữ 2 + 就</b></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">你们想吃什么就点什么。</span> = Các bạn muốn ăn <b>gì</b> thì gọi <b>nấy</b>.</p>","note":"<b>Lưu ý:</b> Khác chủ ngữ: ✗ <span class=\"zh\">你想去哪儿，就我们去哪儿</span> → ✓ <span class=\"zh\">你想去哪儿，我们就去哪儿</span>","examples":[{"zh":"你们想吃什么就点什么。","py":"Nǐmen xiǎng chī shénme jiù diǎn shénme.","vi":"Các bạn muốn ăn gì thì gọi nấy."},{"zh":"你觉得哪个好看就买哪个。","py":"Nǐ juéde nǎge hǎokàn jiù mǎi nǎge.","vi":"Bạn thấy cái nào đẹp thì mua cái đó."},{"zh":"你想去哪儿，我们就去哪儿。","py":"Nǐ xiǎng qù nǎr, wǒmen jiù qù nǎr.","vi":"Bạn muốn đi đâu thì chúng mình đi đó."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这是菜单，我们点什么？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____。</span></span></span><span class=\"qz-hint\">Thực đơn đây, mình gọi món gì? — Bạn muốn ăn gì thì gọi nấy.</span>","answer":["你想吃什么就点什么","想吃什么就点什么","你想点什么就点什么"],"explain":"你想吃什么就点什么。 (Nǐ xiǎng chī shénme jiù diǎn shénme.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我们怎么去电影院？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____。</span></span></span><span class=\"qz-hint\">Mình đi đến rạp chiếu phim bằng cách nào? — Bạn muốn đi thế nào thì mình đi thế ấy.</span>","answer":["你想怎么去，我们就怎么去","你想怎么去就怎么去","你想怎么去，咱们就怎么去"],"explain":"你想怎么去，我们就怎么去。 (Nǐ xiǎng zěnme qù, wǒmen jiù zěnme qù.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我什么时候去找你？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____。</span></span></span><span class=\"qz-hint\">Lúc nào mình đến tìm bạn? — Lúc nào bạn rảnh thì lúc đó đến.</span>","answer":["你什么时候有时间就什么时候来","你什么时候有空就什么时候来","什么时候有时间就什么时候来"],"explain":"你什么时候有时间就什么时候来。 (Nǐ shénme shíhou yǒu shíjiān jiù shénme shíhou lái.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在饭馆","titleVi":"Nhà hàng — cả nhóm xem thực đơn","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"家月、李文，你们看看菜单，想吃点儿什么？","py":"Jiāyuè, Lǐ Wén, nǐmen kànkan càidān, xiǎng chī diǎnr shénme?","vi":"Gia Nguyệt, Lý Văn, các em xem thực đơn đi, muốn ăn gì nào?"},{"speaker":"文","name":"Lý Văn","zh":"谢谢一雪姐，我都可以，你们点吧。","py":"Xièxie Yīxuě jiě, wǒ dōu kěyǐ, nǐmen diǎn ba.","vi":"Cảm ơn chị Nhất Tuyết, em ăn gì cũng được, mọi người gọi đi ạ."},{"speaker":"月","name":"Gia Nguyệt","zh":"飞了这么远，现在还真是又饿又渴。","py":"Fēile zhème yuǎn, xiànzài hái zhēn shì yòu è yòu kě.","vi":"Bay xa như vậy, giờ đúng là vừa đói vừa khát."},{"speaker":"雪","name":"Nhất Tuyết","zh":"那多点点儿，别客气。你们喝什么饮料？","py":"Nà duō diǎn diǎnr, bié kèqi. Nǐmen hē shénme yǐnliào?","vi":"Vậy gọi nhiều chút, đừng khách sáo. Các em uống gì?"},{"speaker":"月","name":"Gia Nguyệt","zh":"好久没喝中国茶，也好久没吃饺子了。我想喝绿茶、吃饺子，可以吗？","py":"Hǎojiǔ méi hē Zhōngguó chá, yě hǎojiǔ méi chī jiǎozi le. Wǒ xiǎng hē lǜchá, chī jiǎozi, kěyǐ ma?","vi":"Lâu lắm em không uống trà Trung Quốc, cũng lâu lắm không ăn sủi cảo. Em muốn uống trà xanh, ăn sủi cảo, được không ạ?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"没问题。你们看看还想吃什么。","py":"Méi wèntí. Nǐmen kànkan hái xiǎng chī shénme.","vi":"Không vấn đề gì. Các em xem còn muốn ăn gì nữa nhé."}]},{"titleZh":"课文二 · 在饭馆","titleVi":"Nhà hàng — cả nhóm cùng ăn","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"服务员，再给我们拿一双筷子、一个勺子和一个碗。","py":"Fúwùyuán, zài gěi wǒmen ná yì shuāng kuàizi, yí ge sháozi hé yí ge wǎn.","vi":"Em ơi, lấy thêm cho chị một đôi đũa, một cái thìa và một cái bát."},{"speaker":"员","name":"Nhân viên","zh":"好的，请等一下，我马上去拿。","py":"Hǎo de, qǐng děng yíxià, wǒ mǎshàng qù ná.","vi":"Vâng, xin chờ một chút, em đi lấy ngay ạ."},{"speaker":"雪","name":"Nhất Tuyết","zh":"这家饭馆的服务很热情，菜也都做得很好吃。你们尝尝，看喜不喜欢这些菜。","py":"Zhè jiā fànguǎn de fúwù hěn rèqíng, cài yě dōu zuò de hěn hǎochī. Nǐmen chángchang, kàn xǐ bu xǐhuan zhèxiē cài.","vi":"Quán này phục vụ rất nhiệt tình, món nào cũng nấu rất ngon. Các em nếm thử xem có thích không."},{"speaker":"月","name":"Gia Nguyệt","zh":"哪个菜都好吃。您点的这些菜真不错。","py":"Nǎge cài dōu hǎochī. Nín diǎn de zhèxiē cài zhēn búcuò.","vi":"Món nào cũng ngon ạ. Mấy món chị gọi thật tuyệt."},{"speaker":"雪","name":"Nhất Tuyết","zh":"这里的饭菜又便宜又好吃，我们经常来，服务员都记住我们爱吃的菜了。","py":"Zhèli de fàncài yòu piányi yòu hǎochī, wǒmen jīngcháng lái, fúwùyuán dōu jìzhù wǒmen ài chī de cài le.","vi":"Cơm canh ở đây vừa rẻ vừa ngon, bọn chị hay đến, nhân viên nhớ cả những món bọn chị thích rồi."},{"speaker":"员","name":"Nhân viên","zh":"王姐，您经常来吃饭，今天送您一些水果，请慢用。","py":"Wáng jiě, nín jīngcháng lái chīfàn, jīntiān sòng nín yìxiē shuǐguǒ, qǐng màn yòng.","vi":"Chị Vương, chị hay đến ăn, hôm nay quán tặng chị ít hoa quả, mời mọi người dùng bữa ạ."}]},{"titleZh":"课文三 · 在饭馆","titleVi":"Nhà hàng — vừa ăn vừa trò chuyện","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"这个鸡肉饭太好吃了，我要再来吃一次。","py":"Zhège jīròufàn tài hǎochī le, wǒ yào zài lái chī yí cì.","vi":"Món cơm gà này ngon quá, em phải đến ăn thêm lần nữa."},{"speaker":"文","name":"Lý Văn","zh":"你可以拿走这张菜单，看看下次还吃点儿什么。","py":"Nǐ kěyǐ názǒu zhè zhāng càidān, kànkan xià cì hái chī diǎnr shénme.","vi":"Bạn có thể cầm tờ thực đơn này về, xem lần sau ăn thêm món gì."},{"speaker":"雪","name":"Nhất Tuyết","zh":"不用拿菜单，在手机上就能看到，也可以选好了让他们给你送。","py":"Búyòng ná càidān, zài shǒujī shang jiù néng kàndào, yě kěyǐ xuǎnhǎole ràng tāmen gěi nǐ sòng.","vi":"Không cần cầm thực đơn đâu, trên điện thoại là xem được, cũng có thể chọn xong rồi bảo họ giao cho em."},{"speaker":"月","name":"Gia Nguyệt","zh":"他们家还能送外卖？","py":"Tāmen jiā hái néng sòng wàimài?","vi":"Quán này còn giao đồ ăn nữa ạ?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"对，现在很多饭馆都能送外卖，想吃什么就点什么。","py":"Duì, xiànzài hěn duō fànguǎn dōu néng sòng wàimài, xiǎng chī shénme jiù diǎn shénme.","vi":"Đúng, bây giờ nhiều quán đều giao đồ ăn, muốn ăn gì thì gọi nấy."},{"speaker":"月","name":"Gia Nguyệt","zh":"那真是太方便了！","py":"Nà zhēn shì tài fāngbiàn le!","vi":"Vậy thì tiện quá!"}]},{"titleZh":"课文四 · 在李文家","titleVi":"Nhà Lý Văn — Lý Văn viết nhật ký","para":true,"speaker":"文","lines":[{"zh":"这些年在国外，我很少自己做饭。","py":"Zhèxiē nián zài guówài, wǒ hěn shǎo zìjǐ zuòfàn.","vi":"Mấy năm ở nước ngoài, tôi rất ít khi tự nấu ăn."},{"zh":"早饭我吃一个面包，有时候吃一块蛋糕，再喝一杯咖啡。","py":"Zǎofàn wǒ chī yí ge miànbāo, yǒu shíhou chī yí kuài dàngāo, zài hē yì bēi kāfēi.","vi":"Bữa sáng tôi ăn một cái bánh mì, có khi ăn một miếng bánh ngọt, rồi uống một cốc cà phê."},{"zh":"午饭和晚饭也都在外面吃。","py":"Wǔfàn hé wǎnfàn yě dōu zài wàimian chī.","vi":"Bữa trưa và bữa tối cũng đều ăn ở ngoài."},{"zh":"快要考试的时候又忙又累，没时间出去吃饭，家里又什么吃的都没有，我可能好几天只吃方便面。","py":"Kuàiyào kǎoshì de shíhou yòu máng yòu lèi, méi shíjiān chūqu chīfàn, jiāli yòu shénme chī de dōu méiyǒu, wǒ kěnéng hǎo jǐ tiān zhǐ chī fāngbiànmiàn.","vi":"Lúc sắp thi vừa bận vừa mệt, không có thời gian ra ngoài ăn, trong nhà lại chẳng có gì ăn, có khi tôi chỉ ăn mì tôm mấy ngày liền."},{"zh":"现在回到中国了，每天能吃到妈妈做的饭，我真是太高兴了！","py":"Xiànzài huídào Zhōngguó le, měi tiān néng chīdào māma zuò de fàn, wǒ zhēn shì tài gāoxìng le!","vi":"Bây giờ về Trung Quốc rồi, ngày nào cũng được ăn cơm mẹ nấu, tôi thật sự vui quá!"},{"zh":"有时候妈妈只做几个简单的菜，我也非常爱吃，因为什么都没有妈妈做的饭好吃。","py":"Yǒu shíhou māma zhǐ zuò jǐ ge jiǎndān de cài, wǒ yě fēicháng ài chī, yīnwèi shénme dōu méiyǒu māma zuò de fàn hǎochī.","vi":"Có hôm mẹ chỉ nấu vài món đơn giản, tôi cũng rất thích ăn, vì chẳng có gì ngon bằng cơm mẹ nấu."}]}]},"extra":[],"activity":{"act":[{"zh":"多人活动","py":"duōrén huódòng","tag":"Hoạt động nhóm","mean":"Ăn ngoài hay tự nấu?","q":{"zh":"在饭馆吃饭、点外卖和自己做饭，你们更喜欢哪种？为什么？","py":"Zài fànguǎn chīfàn, diǎn wàimài hé zìjǐ zuòfàn, nǐmen gèng xǐhuan nǎ zhǒng? Wèi shénme?","vi":"Ăn nhà hàng, gọi đồ ăn ngoài hay tự nấu — nhóm thích cách nào hơn? Vì sao?"},"items":[{"zh":"我更喜欢点外卖，又方便又快，想吃什么就点什么。","py":"Wǒ gèng xǐhuan diǎn wàimài, yòu fāngbiàn yòu kuài, xiǎng chī shénme jiù diǎn shénme.","vi":"Mình thích gọi đồ ăn ngoài hơn, vừa tiện vừa nhanh, muốn ăn gì thì gọi nấy."},{"zh":"在饭馆吃饭，服务员很热情，哪个菜都好吃。","py":"Zài fànguǎn chīfàn, fúwùyuán hěn rèqíng, nǎge cài dōu hǎochī.","vi":"Ăn ở nhà hàng thì nhân viên nhiệt tình, món nào cũng ngon."},{"zh":"自己做饭又便宜又好吃，简单的菜我也爱吃。","py":"Zìjǐ zuòfàn yòu piányi yòu hǎochī, jiǎndān de cài wǒ yě ài chī.","vi":"Tự nấu vừa rẻ vừa ngon, món đơn giản mình cũng thích."}]}],"speak":[]}},{"id":"k3v3-b03","courseId":"k3v3","order":3,"title":"Khu chung cư này khá tốt","titleZh":"这个小区挺好的","titlePy":"zhège xiǎoqū tǐng hǎo de","vocab":[{"stt":1,"hanzi":"初中","pinyin":"chūzhōng","hanviet":"Sơ trung","pos":"Danh từ","meaning":"trường cấp hai (THCS)","comps":"上初中 (học cấp hai), 初中生 (học sinh cấp hai)","example":{"zh":"我妹妹今年上初中了。","py":"Wǒ mèimei jīnnián shàng chūzhōng le.","vi":"Em gái mình năm nay lên cấp hai rồi."}},{"stt":2,"hanzi":"咱们","pinyin":"zánmen","hanviet":"Cha môn","pos":"Đại từ","meaning":"chúng ta, mình (gồm người nghe)","comps":"咱们走吧 (chúng mình đi thôi), 咱们家 (nhà mình)","example":{"zh":"咱们一起去吃饭吧。","py":"Zánmen yìqǐ qù chīfàn ba.","vi":"Chúng mình cùng đi ăn đi."}},{"stt":3,"hanzi":"换","pinyin":"huàn","hanviet":"Hoán","pos":"Động từ","meaning":"đổi, thay","comps":"换衣服 (thay quần áo), 换房子 (đổi nhà)","example":{"zh":"我想换一个大点儿的手机。","py":"Wǒ xiǎng huàn yí ge dà diǎnr de shǒujī.","vi":"Mình muốn đổi một chiếc điện thoại to hơn chút."}},{"stt":4,"hanzi":"房子","pinyin":"fángzi","hanviet":"Phòng tử","pos":"Danh từ","meaning":"nhà, căn nhà","comps":"买房子 (mua nhà), 新房子 (nhà mới)","example":{"zh":"他们的房子离公司很近。","py":"Tāmen de fángzi lí gōngsī hěn jìn.","vi":"Nhà của họ rất gần công ty."}},{"stt":5,"hanzi":"小区","pinyin":"xiǎoqū","hanviet":"Tiểu khu","pos":"Danh từ","meaning":"khu dân cư, khu chung cư","comps":"新小区 (khu chung cư mới), 小区里 (trong khu)","example":{"zh":"我们小区里有一个大超市。","py":"Wǒmen xiǎoqū li yǒu yí ge dà chāoshì.","vi":"Trong khu chung cư nhà mình có một siêu thị lớn."}},{"stt":6,"hanzi":"环境","pinyin":"huánjìng","hanviet":"Hoàn cảnh","pos":"Danh từ","meaning":"môi trường, khung cảnh","comps":"学习环境 (môi trường học tập), 环境很好 (môi trường tốt)","example":{"zh":"这个学校的环境很好。","py":"Zhège xuéxiào de huánjìng hěn hǎo.","vi":"Khung cảnh của ngôi trường này rất đẹp."}},{"stt":7,"hanzi":"挺","pinyin":"tǐng","hanviet":"Đĩnh","pos":"Phó từ","meaning":"khá, rất (khẩu ngữ)","comps":"挺好的 (khá tốt), 挺喜欢 (khá thích)","example":{"zh":"这件衣服挺好看的。","py":"Zhè jiàn yīfu tǐng hǎokàn de.","vi":"Chiếc áo này khá đẹp."}},{"stt":8,"hanzi":"空调","pinyin":"kōngtiáo","hanviet":"Không điều","pos":"Danh từ","meaning":"điều hoà","comps":"开空调 (bật điều hoà), 关空调 (tắt điều hoà)","example":{"zh":"太热了，开空调吧。","py":"Tài rè le, kāi kōngtiáo ba.","vi":"Nóng quá, bật điều hoà đi."}},{"stt":9,"hanzi":"洗衣机","pinyin":"xǐyījī","hanviet":"Tẩy y cơ","pos":"Danh từ","meaning":"máy giặt","comps":"用洗衣机 (dùng máy giặt), 新洗衣机 (máy giặt mới)","example":{"zh":"我家的洗衣机是新买的。","py":"Wǒ jiā de xǐyījī shì xīn mǎi de.","vi":"Máy giặt nhà mình mới mua."}},{"stt":10,"hanzi":"层","pinyin":"céng","hanviet":"Tằng","pos":"Lượng từ","meaning":"tầng, lớp","comps":"一层 (tầng một), 住在五层 (ở tầng năm)","example":{"zh":"我家住在十二层。","py":"Wǒ jiā zhù zài shí'èr céng.","vi":"Nhà mình ở tầng mười hai."}},{"stt":11,"hanzi":"花园","pinyin":"huāyuán","hanviet":"Hoa viên","pos":"Danh từ","meaning":"vườn hoa, khu vườn","comps":"小花园 (vườn nhỏ), 花园里 (trong vườn)","example":{"zh":"我家后面有一个小花园。","py":"Wǒ jiā hòumian yǒu yí ge xiǎo huāyuán.","vi":"Phía sau nhà mình có một khu vườn nhỏ."}},{"stt":12,"hanzi":"灯","pinyin":"dēng","hanviet":"Đăng","pos":"Danh từ","meaning":"đèn","comps":"开灯 (bật đèn), 关灯 (tắt đèn)","example":{"zh":"房间里太黑了，开灯吧。","py":"Fángjiān li tài hēi le, kāi dēng ba.","vi":"Trong phòng tối quá, bật đèn lên đi."}},{"stt":13,"hanzi":"关","pinyin":"guān","hanviet":"Quan","pos":"Động từ","meaning":"tắt; đóng","comps":"关灯 (tắt đèn), 关门 (đóng cửa)","example":{"zh":"出门的时候别忘了关灯。","py":"Chūmén de shíhou bié wàngle guān dēng.","vi":"Lúc ra ngoài đừng quên tắt đèn."}},{"stt":14,"hanzi":"冰箱","pinyin":"bīngxiāng","hanviet":"Băng tương","pos":"Danh từ","meaning":"tủ lạnh","comps":"放在冰箱里 (để trong tủ lạnh), 新冰箱 (tủ lạnh mới)","example":{"zh":"水果在冰箱里，你自己拿吧。","py":"Shuǐguǒ zài bīngxiāng li, nǐ zìjǐ ná ba.","vi":"Hoa quả ở trong tủ lạnh, bạn tự lấy nhé."}},{"stt":15,"hanzi":"卫生间","pinyin":"wèishēngjiān","hanviet":"Vệ sinh gian","pos":"Danh từ","meaning":"nhà vệ sinh, phòng tắm","comps":"去卫生间 (đi vệ sinh), 打扫卫生间 (dọn nhà vệ sinh)","example":{"zh":"请问，卫生间在哪儿？","py":"Qǐngwèn, wèishēngjiān zài nǎr?","vi":"Xin hỏi, nhà vệ sinh ở đâu ạ?"}},{"stt":16,"hanzi":"打扫","pinyin":"dǎsǎo","hanviet":"Đả tảo","pos":"Động từ","meaning":"quét dọn","comps":"打扫房间 (dọn phòng), 打扫干净 (dọn sạch)","example":{"zh":"周末我要打扫房间。","py":"Zhōumò wǒ yào dǎsǎo fángjiān.","vi":"Cuối tuần mình phải dọn phòng."}},{"stt":17,"hanzi":"搬家","pinyin":"bānjiā","hanviet":"Bàn gia","pos":"Động từ (li hợp)","meaning":"chuyển nhà","comps":"搬过两次家 (chuyển nhà hai lần), 搬家公司 (công ty chuyển nhà)","example":{"zh":"我们下个月搬家。","py":"Wǒmen xià ge yuè bānjiā.","vi":"Tháng sau nhà mình chuyển nhà."}},{"stt":18,"hanzi":"办","pinyin":"bàn","hanviet":"Biện","pos":"Động từ","meaning":"làm (thủ tục, giấy tờ)","comps":"办信用卡 (làm thẻ tín dụng), 办护照 (làm hộ chiếu)","example":{"zh":"我明天要去办护照。","py":"Wǒ míngtiān yào qù bàn hùzhào.","vi":"Ngày mai mình phải đi làm hộ chiếu."}},{"stt":19,"hanzi":"信用卡","pinyin":"xìnyòngkǎ","hanviet":"Tín dụng tạp","pos":"Danh từ","meaning":"thẻ tín dụng","comps":"办信用卡 (làm thẻ tín dụng), 用信用卡 (dùng thẻ tín dụng)","example":{"zh":"这儿可以用信用卡吗？","py":"Zhèr kěyǐ yòng xìnyòngkǎ ma?","vi":"Ở đây có dùng được thẻ tín dụng không?"}},{"stt":20,"hanzi":"还","pinyin":"huán","hanviet":"Hoàn","pos":"Động từ","meaning":"trả (lại)","comps":"还钱 (trả tiền), 还书 (trả sách)","example":{"zh":"这本书我下个星期还你。","py":"Zhè běn shū wǒ xià ge xīngqī huán nǐ.","vi":"Quyển sách này tuần sau mình trả bạn."}},{"stt":21,"hanzi":"听说","pinyin":"tīngshuō","hanviet":"Thính thuyết","pos":"Động từ","meaning":"nghe nói","comps":"听说过 (đã từng nghe nói), 我听说… (tôi nghe nói…)","example":{"zh":"听说他下个月要搬家。","py":"Tīngshuō tā xià ge yuè yào bānjiā.","vi":"Nghe nói tháng sau anh ấy chuyển nhà."}},{"stt":22,"hanzi":"银行","pinyin":"yínháng","hanviet":"Ngân hàng","pos":"Danh từ","meaning":"ngân hàng","comps":"去银行 (đi ngân hàng), 银行卡 (thẻ ngân hàng)","example":{"zh":"请问，附近有银行吗？","py":"Qǐngwèn, fùjìn yǒu yínháng ma?","vi":"Xin hỏi, gần đây có ngân hàng không?"}},{"stt":23,"hanzi":"才","pinyin":"cái","hanviet":"Tài","pos":"Phó từ","meaning":"mới (muộn, chậm)","comps":"才来 (mới đến), 才能到 (mới đến được)","example":{"zh":"他昨天晚上十二点才睡觉。","py":"Tā zuótiān wǎnshang shí'èr diǎn cái shuìjiào.","vi":"Tối qua 12 giờ anh ấy mới đi ngủ."}},{"stt":24,"hanzi":"纸","pinyin":"zhǐ","hanviet":"Chỉ","pos":"Danh từ","meaning":"giấy","comps":"一张纸 (một tờ giấy), 纸箱 (thùng giấy)","example":{"zh":"请给我一张纸。","py":"Qǐng gěi wǒ yì zhāng zhǐ.","vi":"Cho mình xin một tờ giấy."}},{"stt":25,"hanzi":"搬","pinyin":"bān","hanviet":"Bàn","pos":"Động từ","meaning":"chuyển, khuân, dời","comps":"搬东西 (chuyển đồ), 搬桌子 (khiêng bàn)","example":{"zh":"你能帮我搬一下桌子吗？","py":"Nǐ néng bāng wǒ bān yíxià zhuōzi ma?","vi":"Bạn giúp mình khiêng cái bàn được không?"}},{"stt":26,"hanzi":"需要","pinyin":"xūyào","hanviet":"Nhu yếu","pos":"Động từ / Danh từ","meaning":"cần; nhu cầu","comps":"需要帮助 (cần giúp đỡ), 需要多长时间 (cần bao lâu)","example":{"zh":"做完这些事需要多长时间？","py":"Zuòwán zhèxiē shì xūyào duō cháng shíjiān?","vi":"Làm xong những việc này cần bao lâu?"}}],"hanzi":[{"char":"初中","pinyin":"chūzhōng","hanviet":"Sơ trung","chars":["初","中"],"story":"初 = 衤 (áo) + 刀 (dao): cắt vải là bước đầu tiên khi may áo → ban đầu. 中 = giữa, trung học. 初中 = 初级中学 (trung học cấp đầu) → trường cấp hai. Cấp ba là 高中."},{"char":"咱们","pinyin":"zánmen","hanviet":"Cha môn","chars":["咱","们"],"story":"咱 = 口 (miệng) + 自 (bản thân): miệng nói về chính mình → mình, ta. 们 là hậu tố số nhiều. 咱们 luôn gồm cả người nghe; 我们 có khi không gồm người nghe."},{"char":"换","pinyin":"huàn","hanviet":"Hoán","chars":["换"],"story":"换 là chữ hình thanh: bộ Thủ 扌 (tay) chỉ nghĩa, 奂 huàn chỉ âm. Đưa tay trao cái này lấy cái kia → đổi, thay: 换衣服, 换房子."},{"char":"房子","pinyin":"fángzi","hanviet":"Phòng tử","chars":["房","子"],"story":"房 = 户 (cánh cửa) chỉ nghĩa + 方 fāng chỉ âm → gian phòng có cửa, nhà. 子 là hậu tố danh từ. 房子 = căn nhà; 房间 = căn phòng."},{"char":"小区","pinyin":"xiǎoqū","hanviet":"Tiểu khu","chars":["小","区"],"story":"小 = nhỏ. 区 = 匚 (khung bao) + 乂 (đánh dấu): vùng đất được khoanh lại → khu vực. 小区 = một khu nhỏ có tường bao → khu dân cư, khu chung cư."},{"char":"环境","pinyin":"huánjìng","hanviet":"Hoàn cảnh","chars":["环","境"],"story":"环 = 王 (ngọc) + 不: vòng ngọc → vòng quanh, bao quanh. 境 = 土 (đất) + 竟 (hết, tận) → bờ cõi, cảnh. 环境 = cảnh vật bao quanh → môi trường."},{"char":"挺","pinyin":"tǐng","hanviet":"Đĩnh","chars":["挺"],"story":"挺 là chữ hình thanh: bộ Thủ 扌 (tay) chỉ nghĩa, 廷 tíng chỉ âm; nghĩa gốc là vươn thẳng (挺直). Trong khẩu ngữ mượn làm phó từ \"khá, rất\": 挺好的."},{"char":"空调","pinyin":"kōngtiáo","hanviet":"Không điều","chars":["空","调"],"story":"空 = không khí (空气). 调 = 讠 + 周 → điều chỉnh. 空调 là cách gọi tắt của 空气调节器 = máy điều chỉnh không khí → điều hoà."},{"char":"洗衣机","pinyin":"xǐyījī","hanviet":"Tẩy y cơ","chars":["洗","衣","机"],"story":"洗 = 氵 (nước) + 先 → rửa, giặt. 衣 vẽ chiếc áo có cổ và vạt. 机 = 木 (gỗ) + 几 → máy móc. 洗衣机 = máy giặt áo quần."},{"char":"层","pinyin":"céng","hanviet":"Tằng","chars":["层"],"story":"层 = 尸 (mái nhà) + 云 (mây): nhà xếp chồng từng lớp cao tới mây → tầng, lớp. Phồn thể 層 = 尸 + 曾 céng chỉ âm. Chú ý: 一层 = tầng một (số thứ tự)."},{"char":"花园","pinyin":"huāyuán","hanviet":"Hoa viên","chars":["花","园"],"story":"花 = 艹 (cỏ) + 化 huà chỉ âm → hoa. 园 = 囗 (hàng rào bao quanh) + 元 yuán chỉ âm → khu vườn có rào. 花园 = vườn hoa, khu vườn."},{"char":"灯","pinyin":"dēng","hanviet":"Đăng","chars":["灯"],"story":"灯 là chữ hình thanh: bộ Hoả 火 (lửa) chỉ nghĩa, 丁 dīng chỉ âm — đèn xưa thắp bằng lửa. 开灯 = bật đèn, 关灯 = tắt đèn."},{"char":"关","pinyin":"guān","hanviet":"Quan","chars":["关"],"story":"Phồn thể 關 = 門 (cửa) + then cài ở giữa → cài then, đóng cửa. Mở rộng: tắt thiết bị: 关灯, 关空调. Trái nghĩa: 开 (mở, bật)."},{"char":"冰箱","pinyin":"bīngxiāng","hanviet":"Băng tương","chars":["冰","箱"],"story":"冰 = 冫 (băng) + 水 (nước) → nước đóng băng. 箱 = ⺮ (tre) + 相 xiāng chỉ âm → hòm, thùng (箱子 bài 1). 冰箱 = cái thùng lạnh → tủ lạnh."},{"char":"卫生间","pinyin":"wèishēngjiān","hanviet":"Vệ sinh gian","chars":["卫","生","间"],"story":"卫生 = vệ sinh (giữ gìn sức khoẻ). 间 = 门 (cửa) + 日 (mặt trời): nắng lọt qua khe cửa → khoảng, gian. 卫生间 = gian vệ sinh → nhà vệ sinh, phòng tắm."},{"char":"打扫","pinyin":"dǎsǎo","hanviet":"Đả tảo","chars":["打","扫"],"story":"打 = làm (một động tác bằng tay). 扫 = 扌 (tay) + 彐 (cây chổi) → tay cầm chổi quét. 打扫 = quét dọn: 打扫房间, 打扫干净."},{"char":"搬家","pinyin":"bānjiā","hanviet":"Bàn gia","chars":["搬","家"],"story":"搬 = 扌 (tay) + 般 bān chỉ âm → khuân, dời đồ. 家 = nhà. 搬家 = dời nhà → chuyển nhà. Là từ li hợp: 搬过两次家 (chuyển nhà hai lần)."},{"char":"办","pinyin":"bàn","hanviet":"Biện","chars":["办"],"story":"Phồn thể 辦 = 力 (sức) đứng giữa hai chữ 辛 (vất vả): dồn sức giải quyết việc khó → làm, xử lý. Khẩu ngữ hay dùng cho thủ tục, giấy tờ: 办信用卡, 办护照."},{"char":"信用卡","pinyin":"xìnyòngkǎ","hanviet":"Tín dụng tạp","chars":["信","用","卡"],"story":"信 = 亻 (người) + 言 (lời): lời người nói phải đáng tin → tin. 信用 = uy tín. 卡 = 上 + 下: kẹp giữa trên và dưới → tấm thẻ (cũng phiên âm \"card\"). 信用卡 = thẻ dựa trên uy tín → thẻ tín dụng."},{"char":"还","pinyin":"huán","hanviet":"Hoàn","chars":["还"],"story":"还 = 辶 (bước đi) + 不: đi rồi quay lại → trở về, trả lại. Chữ này có 2 âm: huán = trả (还钱, 还书) · hái = còn, vẫn (还不远). Nhìn ngữ cảnh để đọc đúng."},{"char":"听说","pinyin":"tīngshuō","hanviet":"Thính thuyết","chars":["听","说"],"story":"听 = 口 (miệng) + 斤 jīn chỉ âm → nghe. 说 = 讠 (lời) → nói. 听说 = nghe người khác nói → nghe nói. Hay đứng đầu câu: 听说中国银行的服务不错。"},{"char":"银行","pinyin":"yínháng","hanviet":"Ngân hàng","chars":["银","行"],"story":"银 = 钅 (kim loại) + 艮 gèn chỉ âm → bạc. 行 ở đây đọc háng = cửa hiệu, ngành nghề (không đọc xíng). 银行 = cửa hiệu giữ bạc → ngân hàng."},{"char":"才","pinyin":"cái","hanviet":"Tài","chars":["才"],"story":"才 vẽ mầm cây vừa nhú lên khỏi mặt đất → vừa mới. Làm phó từ: việc xảy ra muộn / chậm hơn mong đợi → \"mới\": 很晚才能回来. Đối lập với 就 (sớm, nhanh)."},{"char":"纸","pinyin":"zhǐ","hanviet":"Chỉ","chars":["纸"],"story":"纸 là chữ hình thanh: bộ Mịch 纟 (sợi tơ) chỉ nghĩa, 氏 shì chỉ âm — giấy xưa làm từ sợi tơ, vỏ cây. 一张纸 = một tờ giấy (张 lượng từ vật mỏng — bài 2)."},{"char":"搬","pinyin":"bān","hanviet":"Bàn","chars":["搬"],"story":"搬 = 扌 (tay) + 般 bān chỉ âm → dùng tay khuân, dời đồ vật. 搬东西 = chuyển đồ; 搬家 (từ 17) = chuyển nhà."},{"char":"需要","pinyin":"xūyào","hanviet":"Nhu yếu","chars":["需","要"],"story":"需 = 雨 (mưa) + 而: người chờ mưa xuống → mong, cần. 要 = muốn, cần. 需要 = cần. Vừa là động từ (需要帮助) vừa là danh từ \"nhu cầu\"."}],"grammar":[{"title":"Phó từ chỉ mức độ 挺","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>người / vật</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>挺</b><small>khá, rất</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词 / 心理动词</b><small>tính từ / ĐT tâm lý</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的</b><small>(cuối câu)</small></span></div>","summary":"<p class=\"gr-lead\">挺……的 — khá…, … lắm</p><ul><li><span class=\"zh\">挺</span> đứng trước <b>tính từ</b> hoặc <b>động từ tâm lý</b> (<span class=\"zh\">喜欢 · 想</span>…), chỉ mức độ khá cao; hay dùng trong <b>khẩu ngữ</b>.</li><li>Cuối câu thường có <span class=\"zh\">的</span>: <span class=\"zh\">挺好吃的</span> · <span class=\"zh\">我挺喜欢这个颜色的</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">这个小区环境挺好的。</span> = Môi trường khu chung cư này <b>khá</b> tốt.</p>","note":"<b>Lưu ý:</b> Không dùng chồng với <span class=\"zh\">很</span>: ✗ <span class=\"zh\">这个小区挺很好的</span> → ✓ <span class=\"zh\">这个小区挺好的</span>","examples":[{"zh":"这个小区环境挺好的。","py":"Zhège xiǎoqū huánjìng tǐng hǎo de.","vi":"Môi trường khu chung cư này khá tốt."},{"zh":"这家饭馆的菜挺好吃的。","py":"Zhè jiā fànguǎn de cài tǐng hǎochī de.","vi":"Món ăn của quán này khá ngon."},{"zh":"买这个吧，我挺喜欢这个颜色的。","py":"Mǎi zhège ba, wǒ tǐng xǐhuan zhège yánsè de.","vi":"Mua cái này đi, mình khá thích màu này."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你爱游泳吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____。</span></span></span><span class=\"qz-hint\">Bạn có thích bơi không? — Mình khá thích bơi.</span>","answer":["我挺爱游泳的","挺爱游泳的","我挺喜欢游泳的"],"explain":"我挺爱游泳的。 (Wǒ tǐng ài yóuyǒng de.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你的床舒服吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____。</span></span></span><span class=\"qz-hint\">Giường của bạn có êm không? — Giường của mình khá êm.</span>","answer":["我的床挺舒服的","挺舒服的","我的床挺舒服"],"explain":"我的床挺舒服的。 (Wǒ de chuáng tǐng shūfu de.)"}]},{"title":"Bổ ngữ trình độ (1): 坏了","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>người</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词</b><small>tính từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>坏了</b><small>… muốn xỉu</small></span></div>","summary":"<p class=\"gr-lead\">… muốn xỉu, … chết đi được</p><ul><li>Tính từ + <span class=\"zh\">坏了</span>: mức độ <b>rất cao</b>, giọng <b>phóng đại</b> — \"… muốn xỉu, … chết đi được\".</li><li>Hay dùng cho trạng thái <b>khó chịu</b>: <span class=\"zh\">累坏了 · 饿坏了 · 渴坏了</span>. Khác: <span class=\"zh\">洗衣机坏了</span> = máy giặt <b>hỏng</b>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我这几天忙坏了。</span> = Mấy hôm nay mình bận <b>muốn xỉu</b>.</p>","note":"<b>Lưu ý:</b> Đã có 坏了 thì không thêm <span class=\"zh\">很</span>: ✗ <span class=\"zh\">我很累坏了</span> → ✓ <span class=\"zh\">我累坏了</span>","examples":[{"zh":"我这几天忙坏了。","py":"Wǒ zhè jǐ tiān máng huài le.","vi":"Mấy hôm nay mình bận muốn xỉu."},{"zh":"我渴坏了，哪里能买水？","py":"Wǒ kě huài le, nǎli néng mǎi shuǐ?","vi":"Mình khát chết đi được, chỗ nào mua được nước?"},{"zh":"这几天非常忙，大家都累坏了。","py":"Zhè jǐ tiān fēicháng máng, dàjiā dōu lèi huài le.","vi":"Mấy hôm nay bận quá, ai cũng mệt rã rời."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">今天搬家，我和刘明都____。</span><span class=\"qz-hint\">Hôm nay chuyển nhà, tôi và Lưu Minh đều mệt rã rời.</span>","answer":["累坏了"],"explain":"今天搬家，我和刘明都累坏了。 (Jīntiān bānjiā, wǒ hé Liú Míng dōu lèi huài le.)"},{"type":"fill","q":"<span class=\"zh\">我今天没吃午饭和晚饭，____。</span><span class=\"qz-hint\">Hôm nay mình chưa ăn trưa và tối, đói muốn xỉu.</span>","answer":["饿坏了"],"explain":"我今天没吃午饭和晚饭，饿坏了。 (Wǒ jīntiān méi chī wǔfàn hé wǎnfàn, è huài le.)"},{"type":"fill","q":"<span class=\"zh\">房间里没有空调，我们都____。</span><span class=\"qz-hint\">Trong phòng không có điều hoà, chúng mình nóng chết đi được.</span>","answer":["热坏了"],"explain":"房间里没有空调，我们都热坏了。 (Fángjiān li méiyǒu kōngtiáo, wǒmen dōu rè huài le.)"}]},{"title":"Phân biệt 就 và 才","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>người</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>时间 / 时量</b><small>lúc nào / bao lâu</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就 / 才</b><small>sớm·nhanh / muộn·chậm</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span></div>","summary":"<p class=\"gr-lead\">Sớm, nhanh 就 · muộn, chậm 才</p><ul><li><span class=\"zh\">就</span>: người nói thấy việc xảy ra <b>sớm, nhanh, suôn sẻ</b> · <span class=\"zh\">才</span>: <b>muộn, chậm, không suôn sẻ</b>.</li><li>Cùng một mốc giờ, chọn theo <b>cảm nhận</b>: <span class=\"zh\">八点就到了</span> (sớm) · <span class=\"zh\">八点才到</span> (muộn).</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">\"就\" 和 \"才\"</span> · Sớm · muộn · nhanh · chậm</h4><p>就 ↔ 才</p><div class=\"gr-formula\"><div class=\"fx-lbl\">就 · sớm</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>早上五点</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>起床了</b></span></div><div class=\"fx-ex zh\">我早上五点就起床了。</div><div class=\"fx-lbl\">就 · nhanh</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>走路几分钟</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>能到</b></span></div><div class=\"fx-ex zh\">中国银行很近，走路几分钟就能到。</div><div class=\"fx-lbl\">才 · muộn</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>很晚</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>才</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>能回来</b></span></div><div class=\"fx-ex zh\">我下午要去医院，很晚才能回来。</div><div class=\"fx-lbl\">才 · chậm</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>五个小时</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>才</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>能到</b></span></div><div class=\"fx-ex zh\">坐火车去北京，五个小时才能到。</div></div><p class=\"gr-key\"><span class=\"zh\">就</span> hay đi với <span class=\"zh\">了</span> cuối câu　·　<span class=\"zh\">才</span> thường không có <span class=\"zh\">了</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我早上五点就起床了。</span> (sớm)　·　<span class=\"zh\">我很晚才能回来。</span> (muộn)</p>","note":"<b>Lưu ý:</b> Câu có 才 thường <b>không</b> có 了 cuối câu: ✗ <span class=\"zh\">他十点才起床了</span> → ✓ <span class=\"zh\">他十点才起床</span>","examples":[{"zh":"中国银行很近，走路几分钟就能到。","py":"Zhōngguó Yínháng hěn jìn, zǒulù jǐ fēnzhōng jiù néng dào.","vi":"Ngân hàng Trung Quốc rất gần, đi bộ vài phút là tới."},{"zh":"我下午要去医院，很晚才能回来。","py":"Wǒ xiàwǔ yào qù yīyuàn, hěn wǎn cái néng huílai.","vi":"Chiều mình phải đến bệnh viện, rất muộn mới về được."},{"zh":"我早上五点就起床了。","py":"Wǒ zǎoshang wǔ diǎn jiù qǐchuáng le.","vi":"Sáng nay mình 5 giờ đã dậy rồi."},{"zh":"坐火车去北京，五个小时才能到。","py":"Zuò huǒchē qù Běijīng, wǔ ge xiǎoshí cái néng dào.","vi":"Đi tàu hoả đến Bắc Kinh, năm tiếng mới tới được."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在家里","titleVi":"Ở nhà — hai vợ chồng tìm nhà mới","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"小雪的初中离家有点儿远，咱们换一个近点儿的房子吧。","py":"Xiǎoxuě de chūzhōng lí jiā yǒudiǎnr yuǎn, zánmen huàn yí ge jìn diǎnr de fángzi ba.","vi":"Trường cấp hai của Tiểu Tuyết hơi xa nhà, mình đổi sang căn nhà nào gần hơn đi anh."},{"speaker":"明","name":"Lưu Minh","zh":"好啊，我上网看看。你觉得这个小区怎么样？","py":"Hǎo a, wǒ shàngwǎng kànkan. Nǐ juéde zhège xiǎoqū zěnmeyàng?","vi":"Được thôi, anh lên mạng xem thử. Em thấy khu chung cư này thế nào?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"环境挺好的，离地铁站还不远。","py":"Huánjìng tǐng hǎo de, lí dìtiězhàn hái bù yuǎn.","vi":"Môi trường khá tốt, lại không xa ga tàu điện ngầm."},{"speaker":"明","name":"Lưu Minh","zh":"房子里面也不错，空调和洗衣机都是新的。","py":"Fángzi lǐmian yě búcuò, kōngtiáo hé xǐyījī dōu shì xīn de.","vi":"Bên trong nhà cũng được, điều hoà và máy giặt đều mới."},{"speaker":"雪","name":"Nhất Tuyết","zh":"是不错，但是我不喜欢住一层。","py":"Shì búcuò, dànshì wǒ bù xǐhuan zhù yī céng.","vi":"Đúng là không tệ, nhưng em không thích ở tầng một."},{"speaker":"明","name":"Lưu Minh","zh":"这个一层带一个小花园，我觉得咱们可以去看看。","py":"Zhège yī céng dài yí ge xiǎo huāyuán, wǒ juéde zánmen kěyǐ qù kànkan.","vi":"Tầng một này có kèm một khu vườn nhỏ, anh nghĩ mình có thể đi xem thử."}]},{"titleZh":"课文二 · 在新家","titleVi":"Nhà mới — Nhất Tuyết đang dọn phòng","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"我今天早上来的时候，灯还开着。","py":"Wǒ jīntiān zǎoshang lái de shíhou, dēng hái kāizhe.","vi":"Sáng nay lúc em đến, đèn vẫn còn bật."},{"speaker":"明","name":"Lưu Minh","zh":"我这几天忙坏了，可能走的时候忘关了。","py":"Wǒ zhè jǐ tiān máng huài le, kěnéng zǒu de shíhou wàng guān le.","vi":"Mấy hôm nay anh bận muốn xỉu, chắc lúc về quên tắt."},{"speaker":"雪","name":"Nhất Tuyết","zh":"冰箱不能用，这些吃的东西放在哪儿？","py":"Bīngxiāng bù néng yòng, zhèxiē chī de dōngxi fàng zài nǎr?","vi":"Tủ lạnh không dùng được, mấy thứ đồ ăn này để đâu bây giờ?"},{"speaker":"明","name":"Lưu Minh","zh":"不可能吧？冰箱是新买的，我来看看。","py":"Bù kěnéng ba? Bīngxiāng shì xīn mǎi de, wǒ lái kànkan.","vi":"Không thể nào? Tủ lạnh mới mua mà, để anh xem."},{"speaker":"雪","name":"Nhất Tuyết","zh":"洗衣机也坏了吗？","py":"Xǐyījī yě huài le ma?","vi":"Máy giặt cũng hỏng rồi à?"},{"speaker":"明","name":"Lưu Minh","zh":"没坏，但是卫生间没打扫好，还不能洗衣服。","py":"Méi huài, dànshì wèishēngjiān méi dǎsǎo hǎo, hái bù néng xǐ yīfu.","vi":"Không hỏng, nhưng nhà vệ sinh chưa dọn xong, vẫn chưa giặt đồ được."},{"speaker":"雪","name":"Nhất Tuyết","zh":"星期天我们真的能搬家吗？","py":"Xīngqītiān wǒmen zhēn de néng bānjiā ma?","vi":"Chủ nhật mình thật sự chuyển nhà được không đây?"}]},{"titleZh":"课文三 · 在家里","titleVi":"Phòng khách — chuyện tiền chuyển nhà","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"这个月花了不少钱。","py":"Zhège yuè huāle bù shǎo qián.","vi":"Tháng này tiêu khá nhiều tiền."},{"speaker":"明","name":"Lưu Minh","zh":"是的，我们买了很多搬家时要用的东西。","py":"Shì de, wǒmen mǎile hěn duō bānjiā shí yào yòng de dōngxi.","vi":"Ừ, mình mua rất nhiều thứ cần dùng khi chuyển nhà."},{"speaker":"雪","name":"Nhất Tuyết","zh":"咱们办张信用卡吧，花的钱可以慢慢还。听说中国银行的服务不错，办了信用卡买东西还能便宜。","py":"Zánmen bàn zhāng xìnyòngkǎ ba, huā de qián kěyǐ mànmàn huán. Tīngshuō Zhōngguó Yínháng de fúwù búcuò, bànle xìnyòngkǎ mǎi dōngxi hái néng piányi.","vi":"Mình làm một cái thẻ tín dụng đi, tiền tiêu rồi có thể trả từ từ. Nghe nói Ngân hàng Trung Quốc phục vụ khá tốt, làm thẻ rồi mua đồ còn được rẻ hơn."},{"speaker":"明","name":"Lưu Minh","zh":"好啊！中国银行很近，走路几分钟就能到。咱们什么时候去？","py":"Hǎo a! Zhōngguó Yínháng hěn jìn, zǒulù jǐ fēnzhōng jiù néng dào. Zánmen shénme shíhou qù?","vi":"Được đấy! Ngân hàng Trung Quốc rất gần, đi bộ vài phút là tới. Khi nào mình đi?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"今天下午？","py":"Jīntiān xiàwǔ?","vi":"Chiều nay nhé?"},{"speaker":"明","name":"Lưu Minh","zh":"我下午要去医院，很晚才能回来。","py":"Wǒ xiàwǔ yào qù yīyuàn, hěn wǎn cái néng huílai.","vi":"Chiều anh phải đến bệnh viện, rất muộn mới về được."},{"speaker":"雪","name":"Nhất Tuyết","zh":"那我下午自己去吧。","py":"Nà wǒ xiàwǔ zìjǐ qù ba.","vi":"Vậy chiều em tự đi vậy."}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — bàn kế hoạch chuyển nhà","lines":[{"speaker":"明","name":"Lưu Minh","zh":"我觉得这个星期就能搬家。我明天去买一些纸箱，很快就能准备好。搬家那天，我想请几位朋友来帮忙，最多一天就能搬完。","py":"Wǒ juéde zhège xīngqī jiù néng bānjiā. Wǒ míngtiān qù mǎi yìxiē zhǐxiāng, hěn kuài jiù néng zhǔnbèi hǎo. Bānjiā nà tiān, wǒ xiǎng qǐng jǐ wèi péngyou lái bāngmáng, zuì duō yì tiān jiù néng bānwán.","vi":"Anh nghĩ tuần này là chuyển nhà được rồi. Mai anh đi mua ít thùng giấy, chuẩn bị xong nhanh thôi. Hôm chuyển nhà, anh muốn nhờ vài người bạn đến giúp, nhiều nhất một ngày là chuyển xong."},{"speaker":"雪","name":"Nhất Tuyết","zh":"我觉得下个月才能搬家。这周开始准备，下周去打扫新家，这么多事情最少需要两个星期才能做完。搬家那天，我们应该找一家搬家公司。","py":"Wǒ juéde xià ge yuè cái néng bānjiā. Zhè zhōu kāishǐ zhǔnbèi, xià zhōu qù dǎsǎo xīn jiā, zhème duō shìqing zuì shǎo xūyào liǎng ge xīngqī cái néng zuòwán. Bānjiā nà tiān, wǒmen yīnggāi zhǎo yì jiā bānjiā gōngsī.","vi":"Em nghĩ tháng sau mới chuyển được. Tuần này bắt đầu chuẩn bị, tuần sau đi dọn nhà mới, nhiều việc thế này ít nhất cũng cần hai tuần mới làm xong. Hôm chuyển nhà, mình nên thuê một công ty chuyển nhà."}]}]},"extra":[],"activity":{"act":[{"zh":"多人活动","py":"duōrén huódòng","tag":"Hoạt động nhóm","mean":"Chuyển nhà khó quên","q":{"zh":"分享一次你最难忘的搬家经历。","py":"Fēnxiǎng yí cì nǐ zuì nánwàng de bānjiā jīnglì.","vi":"Nhóm 3 người, chia sẻ một lần chuyển nhà khó quên nhất của bạn."},"items":[{"zh":"你为什么要搬家？","py":"Nǐ wèi shénme yào bānjiā?","vi":"Vì sao bạn chuyển nhà?"},{"zh":"搬家前你准备了哪些东西？","py":"Bānjiā qián nǐ zhǔnbèile nǎxiē dōngxi?","vi":"Trước khi chuyển, bạn đã chuẩn bị những gì?"},{"zh":"你有没有请搬家公司？为什么？","py":"Nǐ yǒu méiyǒu qǐng bānjiā gōngsī? Wèi shénme?","vi":"Bạn có thuê công ty chuyển nhà không? Vì sao?"},{"zh":"搬家的时候遇到了什么问题？","py":"Bānjiā de shíhou yùdàole shénme wèntí?","vi":"Lúc chuyển nhà bạn gặp vấn đề gì?"},{"zh":"搬进新家后，你觉得怎么样？","py":"Bānjìn xīn jiā hòu, nǐ juéde zěnmeyàng?","vi":"Vào nhà mới rồi, bạn thấy thế nào?"}]}],"speak":[]},"review":{"range":"1–3","rows":[{"l":1,"zh":"固定短语 \"看上去 / 看起来\"","vi":"Cụm cố định 看上去 / 看起来","ex":{"zh":"他们看上去有点儿像。","py":"Tāmen kàn shàngqu yǒudiǎnr xiàng.","vi":"Trông họ hơi giống nhau."}},{"l":1,"zh":"疑问代词的非疑问用法 (1)","vi":"Đại từ nghi vấn dùng không để hỏi (1)","ex":{"zh":"我好像在哪儿看到过这个箱子。","py":"Wǒ hǎoxiàng zài nǎr kàndàoguo zhège xiāngzi.","vi":"Hình như mình đã thấy cái va li này ở đâu đó rồi."}},{"l":1,"zh":"多项定语","vi":"Nhiều định ngữ","ex":{"zh":"李文是那个穿着黑衣服的短头发的年轻人吗？","py":"Lǐ Wén shì nàge chuānzhe hēi yīfu de duǎn tóufa de niánqīngrén ma?","vi":"Lý Văn có phải là cậu thanh niên tóc ngắn mặc áo đen kia không?"}},{"l":2,"zh":"并列复句 \"又……又……\"","vi":"Câu phức đẳng lập 又……又……","ex":{"zh":"我现在还真是又饿又渴。","py":"Wǒ xiànzài hái zhēn shì yòu è yòu kě.","vi":"Bây giờ mình đúng là vừa đói vừa khát."}},{"l":2,"zh":"疑问代词的非疑问用法 (2)","vi":"Đại từ nghi vấn dùng không để hỏi (2)","ex":{"zh":"哪个菜都好吃。","py":"Nǎge cài dōu hǎochī.","vi":"Món nào cũng ngon."}},{"l":2,"zh":"疑问代词的非疑问用法 (3)","vi":"Đại từ nghi vấn dùng không để hỏi (3)","ex":{"zh":"你们想吃什么就点什么。","py":"Nǐmen xiǎng chī shénme jiù diǎn shénme.","vi":"Các bạn muốn ăn gì thì gọi nấy."}},{"l":3,"zh":"程度副词 \"挺\"","vi":"Phó từ chỉ mức độ 挺","ex":{"zh":"这个小区环境挺好的。","py":"Zhège xiǎoqū huánjìng tǐng hǎo de.","vi":"Môi trường khu chung cư này khá tốt."}},{"l":3,"zh":"程度补语 (1) \"坏了\"","vi":"Bổ ngữ trình độ (1): 坏了","ex":{"zh":"我这几天忙坏了。","py":"Wǒ zhè jǐ tiān máng huài le.","vi":"Mấy hôm nay mình bận muốn xỉu."}},{"l":3,"zh":"\"就\" 和 \"才\"","vi":"Phân biệt 就 và 才","ex":{"zh":"中国银行很近，走路几分钟就能到。我下午要去医院，很晚才能回来。","py":"Zhōngguó Yínháng hěn jìn, zǒulù jǐ fēnzhōng jiù néng dào. Wǒ xiàwǔ yào qù yīyuàn, hěn wǎn cái néng huílai.","vi":"Ngân hàng Trung Quốc rất gần, đi bộ vài phút là tới. Chiều mình phải đến bệnh viện, rất muộn mới về được."}}]}},{"id":"k3v3-b04","courseId":"k3v3","order":4,"title":"Khách sạn này chẳng giống chỗ nào khác","titleZh":"这家宾馆跟别的都不一样","titlePy":"zhè jiā bīnguǎn gēn biéde dōu bù yíyàng","vocab":[{"stt":1,"hanzi":"假期","pinyin":"jiàqī","hanviet":"Giả kỳ","pos":"Danh từ","meaning":"kỳ nghỉ","comps":"这个假期 (kỳ nghỉ này), 假期计划 (kế hoạch kỳ nghỉ)","example":{"zh":"这个假期你打算去哪儿？","py":"Zhège jiàqī nǐ dǎsuan qù nǎr?","vi":"Kỳ nghỉ này bạn định đi đâu?"}},{"stt":2,"hanzi":"海","pinyin":"hǎi","hanviet":"Hải","pos":"Danh từ","meaning":"biển","comps":"海边 (bờ biển), 大海 (biển cả)","example":{"zh":"我很喜欢去海边玩儿。","py":"Wǒ hěn xǐhuan qù hǎibiān wánr.","vi":"Mình rất thích ra biển chơi."}},{"stt":3,"hanzi":"草原","pinyin":"cǎoyuán","hanviet":"Thảo nguyên","pos":"Danh từ","meaning":"thảo nguyên, đồng cỏ","comps":"大草原 (thảo nguyên rộng lớn), 草原上 (trên thảo nguyên)","example":{"zh":"夏天的草原非常漂亮。","py":"Xiàtiān de cǎoyuán fēicháng piàoliang.","vi":"Thảo nguyên mùa hè vô cùng đẹp."}},{"stt":4,"hanzi":"主意","pinyin":"zhǔyi","hanviet":"Chủ ý","pos":"Danh từ","meaning":"ý kiến, ý tưởng","comps":"好主意 (ý hay), 出主意 (bày cách, góp ý)","example":{"zh":"周末去爬山？这是个好主意！","py":"Zhōumò qù pá shān? Zhè shì ge hǎo zhǔyi!","vi":"Cuối tuần đi leo núi à? Ý hay đấy!"}},{"stt":5,"hanzi":"骑","pinyin":"qí","hanviet":"Kỵ","pos":"Động từ","meaning":"cưỡi; đi (xe đạp, xe máy)","comps":"骑马 (cưỡi ngựa), 骑自行车 (đi xe đạp)","example":{"zh":"我每天骑自行车去学校。","py":"Wǒ měi tiān qí zìxíngchē qù xuéxiào.","vi":"Ngày nào mình cũng đi xe đạp đến trường."}},{"stt":6,"hanzi":"马","pinyin":"mǎ","hanviet":"Mã","pos":"Danh từ","meaning":"ngựa","comps":"骑马 (cưỡi ngựa), 白马 (ngựa trắng)","example":{"zh":"草原上有很多马。","py":"Cǎoyuán shang yǒu hěn duō mǎ.","vi":"Trên thảo nguyên có rất nhiều ngựa."}},{"stt":7,"hanzi":"羊","pinyin":"yáng","hanviet":"Dương","pos":"Danh từ","meaning":"cừu, dê","comps":"羊肉 (thịt cừu), 小羊 (cừu con)","example":{"zh":"你吃过羊肉吗？","py":"Nǐ chīguo yángròu ma?","vi":"Bạn đã ăn thịt cừu bao giờ chưa?"}},{"stt":8,"hanzi":"月亮","pinyin":"yuèliang","hanviet":"Nguyệt lượng","pos":"Danh từ","meaning":"mặt trăng","comps":"看月亮 (ngắm trăng), 今天的月亮 (trăng đêm nay)","example":{"zh":"今天晚上的月亮真漂亮！","py":"Jīntiān wǎnshang de yuèliang zhēn piàoliang!","vi":"Trăng tối nay đẹp thật!"}},{"stt":9,"hanzi":"一定","pinyin":"yídìng","hanviet":"Nhất định","pos":"Phó từ","meaning":"nhất định, chắc chắn","comps":"一定要来 (nhất định phải đến), 不一定 (chưa chắc)","example":{"zh":"明天你一定要来我家玩儿。","py":"Míngtiān nǐ yídìng yào lái wǒ jiā wánr.","vi":"Mai bạn nhất định phải đến nhà mình chơi nhé."}},{"stt":10,"hanzi":"刻","pinyin":"kè","hanviet":"Khắc","pos":"Lượng từ","meaning":"khắc (15 phút)","comps":"一刻 (15 phút), 三点一刻 (3 giờ 15)","example":{"zh":"我们八点一刻上课。","py":"Wǒmen bā diǎn yí kè shàngkè.","vi":"8 giờ 15 bọn mình vào học."}},{"stt":11,"hanzi":"起飞","pinyin":"qǐfēi","hanviet":"Khởi phi","pos":"Động từ","meaning":"cất cánh","comps":"飞机起飞 (máy bay cất cánh), 马上起飞 (sắp cất cánh)","example":{"zh":"我们的飞机几点起飞？","py":"Wǒmen de fēijī jǐ diǎn qǐfēi?","vi":"Máy bay của chúng ta mấy giờ cất cánh?"}},{"stt":12,"hanzi":"宾馆","pinyin":"bīnguǎn","hanviet":"Tân quán","pos":"Danh từ","meaning":"khách sạn","comps":"住宾馆 (ở khách sạn), 找宾馆 (tìm khách sạn)","example":{"zh":"这家宾馆离火车站很近。","py":"Zhè jiā bīnguǎn lí huǒchēzhàn hěn jìn.","vi":"Khách sạn này rất gần ga tàu."}},{"stt":13,"hanzi":"特别","pinyin":"tèbié","hanviet":"Đặc biệt","pos":"Tính từ / Phó từ","meaning":"đặc biệt; vô cùng","comps":"很特别 (rất đặc biệt), 特别好 (cực kỳ tốt)","example":{"zh":"他特别喜欢吃中国菜。","py":"Tā tèbié xǐhuan chī Zhōngguócài.","vi":"Anh ấy cực kỳ thích ăn món Trung Quốc."}},{"stt":14,"hanzi":"别的","pinyin":"biéde","hanviet":"Biệt đích","pos":"Đại từ","meaning":"cái khác, (người / vật) khác","comps":"别的东西 (đồ khác), 别的人 (người khác)","example":{"zh":"你还想买别的吗？","py":"Nǐ hái xiǎng mǎi biéde ma?","vi":"Bạn còn muốn mua gì khác không?"}},{"stt":15,"hanzi":"一样","pinyin":"yíyàng","hanviet":"Nhất dạng","pos":"Tính từ","meaning":"giống nhau, như nhau","comps":"不一样 (không giống), 一样大 (to như nhau)","example":{"zh":"我们两个人的衣服一样。","py":"Wǒmen liǎng ge rén de yīfu yíyàng.","vi":"Quần áo của hai đứa mình giống nhau."}},{"stt":16,"hanzi":"牛","pinyin":"niú","hanviet":"Ngưu","pos":"Danh từ","meaning":"bò, trâu","comps":"牛肉 (thịt bò), 牛奶 (sữa bò)","example":{"zh":"我早上喝了一杯牛奶。","py":"Wǒ zǎoshang hēle yì bēi niúnǎi.","vi":"Sáng nay mình uống một cốc sữa bò."}},{"stt":17,"hanzi":"相机","pinyin":"xiàngjī","hanviet":"Tướng cơ","pos":"Danh từ","meaning":"máy ảnh","comps":"照相机 (máy chụp ảnh), 新相机 (máy ảnh mới)","example":{"zh":"这是我新买的相机。","py":"Zhè shì wǒ xīn mǎi de xiàngjī.","vi":"Đây là chiếc máy ảnh mình mới mua."}},{"stt":18,"hanzi":"欢迎","pinyin":"huānyíng","hanviet":"Hoan nghênh","pos":"Động từ","meaning":"chào mừng, hoan nghênh","comps":"欢迎你 (chào mừng bạn), 欢迎光临 (hân hạnh đón tiếp)","example":{"zh":"欢迎你们来我家玩儿！","py":"Huānyíng nǐmen lái wǒ jiā wánr!","vi":"Chào mừng các bạn đến nhà mình chơi!"}},{"stt":19,"hanzi":"司机","pinyin":"sījī","hanviet":"Tư cơ","pos":"Danh từ","meaning":"tài xế, lái xe","comps":"出租车司机 (tài xế taxi), 当司机 (làm tài xế)","example":{"zh":"我爸爸是出租车司机。","py":"Wǒ bàba shì chūzūchē sījī.","vi":"Bố mình là tài xế taxi."}},{"stt":20,"hanzi":"晚点","pinyin":"wǎndiǎn","hanviet":"Vãn điểm","pos":"Động từ","meaning":"trễ giờ (tàu, xe, máy bay)","comps":"飞机晚点 (máy bay trễ), 晚点两个小时 (trễ hai tiếng)","example":{"zh":"火车晚点了半个小时。","py":"Huǒchē wǎndiǎnle bàn ge xiǎoshí.","vi":"Tàu hoả trễ nửa tiếng."}},{"stt":21,"hanzi":"久","pinyin":"jiǔ","hanviet":"Cửu","pos":"Tính từ","meaning":"lâu","comps":"很久 (rất lâu), 多久 (bao lâu)","example":{"zh":"好久不见，你最近怎么样？","py":"Hǎojiǔ bú jiàn, nǐ zuìjìn zěnmeyàng?","vi":"Lâu lắm không gặp, dạo này bạn thế nào?"}},{"stt":22,"hanzi":"除了","pinyin":"chúle","hanviet":"Trừ liễu","pos":"Giới từ","meaning":"ngoài … ra; trừ","comps":"除了他 (trừ anh ấy ra), 除了……以外 (ngoài … ra)","example":{"zh":"除了星期天，我每天都上班。","py":"Chúle xīngqītiān, wǒ měi tiān dōu shàngbān.","vi":"Trừ chủ nhật ra, ngày nào mình cũng đi làm."}},{"stt":23,"hanzi":"以外","pinyin":"yǐwài","hanviet":"Dĩ ngoại","pos":"Danh từ","meaning":"ngoài ra, ngoài (phạm vi)","comps":"除了……以外 (ngoài … ra), 学校以外 (ngoài trường)","example":{"zh":"除了汉语以外，他还会说英语。","py":"Chúle Hànyǔ yǐwài, tā hái huì shuō Yīngyǔ.","vi":"Ngoài tiếng Trung ra, anh ấy còn biết nói tiếng Anh."}},{"stt":24,"hanzi":"先","pinyin":"xiān","hanviet":"Tiên","pos":"Phó từ","meaning":"trước (làm trước)","comps":"先走 (đi trước), 你先说 (bạn nói trước)","example":{"zh":"你先休息一下，晚上我们再说。","py":"Nǐ xiān xiūxi yíxià, wǎnshang wǒmen zài shuō.","vi":"Bạn nghỉ trước một lát, tối mình nói tiếp."}},{"stt":25,"hanzi":"一直","pinyin":"yìzhí","hanviet":"Nhất trực","pos":"Phó từ","meaning":"luôn, suốt; (đi) thẳng","comps":"一直等 (đợi suốt), 一直往前走 (cứ đi thẳng)","example":{"zh":"我一直在家等你。","py":"Wǒ yìzhí zài jiā děng nǐ.","vi":"Mình đợi bạn ở nhà suốt."}},{"stt":26,"hanzi":"干净","pinyin":"gānjìng","hanviet":"Can tịnh","pos":"Tính từ","meaning":"sạch sẽ","comps":"很干净 (rất sạch), 打扫干净 (dọn sạch)","example":{"zh":"房间打扫干净了吗？","py":"Fángjiān dǎsǎo gānjìng le ma?","vi":"Phòng dọn sạch chưa?"}},{"stt":27,"hanzi":"满意","pinyin":"mǎnyì","hanviet":"Mãn ý","pos":"Động từ","meaning":"hài lòng","comps":"很满意 (rất hài lòng), 对……满意 (hài lòng với…)","example":{"zh":"我对这次考试很满意。","py":"Wǒ duì zhè cì kǎoshì hěn mǎnyì.","vi":"Mình rất hài lòng với kỳ thi lần này."}}],"hanzi":[{"char":"假期","pinyin":"jiàqī","hanviet":"Giả kỳ","chars":["假","期"],"story":"假 = 亻 (người) + 叚 jiǎ chỉ âm; đọc jià nghĩa là nghỉ (放假), đọc jiǎ là giả. 期 = 其 qí chỉ âm + 月 (trăng) → một khoảng thời gian. 假期 = khoảng thời gian được nghỉ → kỳ nghỉ."},{"char":"海","pinyin":"hǎi","hanviet":"Hải","chars":["海"],"story":"海 = 氵 (nước) + 每 měi chỉ âm: nơi nước của mọi dòng sông dồn về → biển. 海边 = bờ biển, 大海 = biển cả."},{"char":"草原","pinyin":"cǎoyuán","hanviet":"Thảo nguyên","chars":["草","原"],"story":"草 = 艹 (cỏ) + 早 zǎo chỉ âm → cỏ. 原 = 厂 (vách núi) + 泉 (suối) → nguồn; vùng đất bằng rộng. 草原 = cánh đồng cỏ rộng mênh mông → thảo nguyên."},{"char":"主意","pinyin":"zhǔyi","hanviet":"Chủ ý","chars":["主","意"],"story":"主 vẽ ngọn đèn có ngọn lửa ở trên → chủ, chính. 意 = 音 (âm thanh) + 心 (tim): tiếng nói trong lòng → ý. 主意 = ý chính trong đầu → ý tưởng; 意 đọc nhẹ yi."},{"char":"骑","pinyin":"qí","hanviet":"Kỵ","chars":["骑"],"story":"骑 = 马 (ngựa) + 奇 qí chỉ âm → ngồi dạng chân trên lưng ngựa → cưỡi. Mở rộng cho xe ngồi dạng chân: 骑自行车. Còn ô tô, tàu thì dùng 坐."},{"char":"马","pinyin":"mǎ","hanviet":"Mã","chars":["马"],"story":"马 là chữ tượng hình con ngựa: đầu, bờm, thân và bốn chân (nét móc cuối). 马 làm bộ trong 骑, và chỉ âm trong 吗, 妈, 码."},{"char":"羊","pinyin":"yáng","hanviet":"Dương","chars":["羊"],"story":"羊 là chữ tượng hình đầu con dê / cừu: hai sừng cong ở trên (丷), mặt và thân bên dưới. 羊肉 = thịt cừu. Chữ 美 (đẹp) có 羊 ở trên."},{"char":"月亮","pinyin":"yuèliang","hanviet":"Nguyệt lượng","chars":["月","亮"],"story":"月 vẽ vầng trăng khuyết. 亮 = phía trên giống 高 (cao) + 几 (người): người đứng trên cao thấy sáng → sáng. 月亮 = vầng trăng sáng → mặt trăng; 亮 đọc nhẹ liang."},{"char":"一定","pinyin":"yídìng","hanviet":"Nhất định","chars":["一","定"],"story":"一 = một. 定 = 宀 (mái nhà) + 正 biến thể: đã ở yên dưới mái nhà → yên, định. 一定 = đã định một lần là không đổi → nhất định, chắc chắn. 不一定 = chưa chắc."},{"char":"刻","pinyin":"kè","hanviet":"Khắc","chars":["刻"],"story":"刻 = 亥 hài chỉ âm + 刂 (dao) → khắc, chạm. Đồng hồ nước xưa khắc vạch chia thời gian → 一刻 = 15 phút, 三刻 = 45 phút. Không nói 两刻 (dùng 半)."},{"char":"起飞","pinyin":"qǐfēi","hanviet":"Khởi phi","chars":["起","飞"],"story":"起 = 走 (đi) + 己 jǐ chỉ âm → đứng dậy, bắt đầu. 飞 vẽ đôi cánh chim đang vỗ → bay. 起飞 = bắt đầu bay lên → cất cánh."},{"char":"宾馆","pinyin":"bīnguǎn","hanviet":"Tân quán","chars":["宾","馆"],"story":"宾 = 宀 (mái nhà) + 兵: người đến ở dưới mái nhà mình → khách (来宾). 馆 = 饣 (ăn) + 官 guān chỉ âm → nơi cho khách ăn ở. 宾馆 = nơi khách nghỉ lại → khách sạn."},{"char":"特别","pinyin":"tèbié","hanviet":"Đặc biệt","chars":["特","别"],"story":"特 = 牛 (bò) + 寺 sì chỉ âm: con bò đực nổi bật nhất đàn → đặc biệt. 别 = khác. 特别 = khác hẳn mọi cái → đặc biệt; đứng trước tính từ / động từ = cực kỳ: 特别好."},{"char":"别的","pinyin":"biéde","hanviet":"Biệt đích","chars":["别","的"],"story":"别 = 另 + 刂 (dao): dùng dao tách ra → chia lìa, khác. 的 = của. 别的 = cái khác. Phân biệt: 别去 (đừng đi) · 别的东西 (đồ khác)."},{"char":"一样","pinyin":"yíyàng","hanviet":"Nhất dạng","chars":["一","样"],"story":"一 = một. 样 = 木 (cây) + 羊 yáng chỉ âm → hình dạng, kiểu (怎么样). 一样 = cùng một kiểu → giống nhau. Phủ định: 不一样."},{"char":"牛","pinyin":"niú","hanviet":"Ngưu","chars":["牛"],"story":"牛 là chữ tượng hình đầu con bò nhìn từ phía trước: hai sừng và mặt. 牛肉 = thịt bò, 牛奶 = sữa bò. Bộ 牛 có trong chữ 特."},{"char":"相机","pinyin":"xiàngjī","hanviet":"Tướng cơ","chars":["相","机"],"story":"相 = 木 (cây) + 目 (mắt): đứng sau cây nhìn kỹ → nhìn; dung mạo, hình ảnh (照相 = chụp ảnh). 机 = máy. 相机 = 照相机 = máy chụp ảnh."},{"char":"欢迎","pinyin":"huānyíng","hanviet":"Hoan nghênh","chars":["欢","迎"],"story":"欢 = 又 + 欠 (người há miệng) → cười nói vui vẻ. 迎 = 辶 (đi) + 卬 → đi ra đón. 欢迎 = vui vẻ ra đón → chào mừng, hoan nghênh."},{"char":"司机","pinyin":"sījī","hanviet":"Tư cơ","chars":["司","机"],"story":"司 = trông coi, điều khiển (公司 = công ty). 机 = 木 (gỗ) + 几 → máy móc. 司机 = người điều khiển máy → tài xế, lái xe."},{"char":"晚点","pinyin":"wǎndiǎn","hanviet":"Vãn điểm","chars":["晚","点"],"story":"晚 = 日 (mặt trời) + 免 miǎn chỉ âm → chiều tối, muộn. 点 = giờ (giờ đã định). 晚点 = muộn so với giờ → trễ giờ, dùng cho tàu, xe, máy bay. Người đến muộn thì dùng 迟到."},{"char":"久","pinyin":"jiǔ","hanviet":"Cửu","chars":["久"],"story":"久 vẽ người đang đi, phía sau có vật níu kéo → đi chậm, kéo dài → lâu. 好久不见 = lâu rồi không gặp; 多久 = bao lâu."},{"char":"除了","pinyin":"chúle","hanviet":"Trừ liễu","chars":["除","了"],"story":"除 = 阝 (gò đất) + 余 yú chỉ âm → bậc thềm; dọn bỏ đi → trừ (除夕 = đêm trừ tịch). 了 đọc le. 除了 = trừ ra, ngoài … ra; hay đi với 以外 và 都 / 还 / 也."},{"char":"以外","pinyin":"yǐwài","hanviet":"Dĩ ngoại","chars":["以","外"],"story":"以 = lấy làm mốc. 外 = 夕 (buổi tối) + 卜 (bói): bói vào ban đêm là việc ngoài lệ → bên ngoài. 以外 = từ mốc đó trở ra → ngoài ra: 除了……以外."},{"char":"先","pinyin":"xiān","hanviet":"Tiên","chars":["先"],"story":"先: phía trên là bàn chân (止 biến thể) bước lên trước người 儿 → đi trước, trước. Hay dùng 先……再…… = trước … rồi mới …"},{"char":"一直","pinyin":"yìzhí","hanviet":"Nhất trực","chars":["一","直"],"story":"一 = một. 直 = 十 (mười) + 目 (mắt): mười con mắt cùng nhìn thì không lệch → thẳng. 一直 = một mạch thẳng → luôn, suốt (thời gian); đi thẳng (hướng)."},{"char":"干净","pinyin":"gānjìng","hanviet":"Can tịnh","chars":["干","净"],"story":"干 = khô (đọc gān; 干 gàn = làm). 净 = 冫 (băng, trong) + 争 zhēng chỉ âm → sạch, trong. 干净 = khô ráo, sạch sẽ: 打扫干净."},{"char":"满意","pinyin":"mǎnyì","hanviet":"Mãn ý","chars":["满","意"],"story":"满 = 氵 (nước) + 㒼 → nước đầy tràn. 意 = ý muốn. 满意 = ý muốn được lấp đầy → hài lòng. Ngược lại: 不满意."}],"grammar":[{"title":"Cấu trúc 一……也/都 + 不/没……","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>一 + 量词 (+ 名词)</b><small>một + LT (+ DT)</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>也 / 都</b><small>cũng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不 / 没</b><small>không / chưa</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span></div>","summary":"<p class=\"gr-lead\">Một … cũng không — phủ định hoàn toàn</p><ul><li>Biểu thị <b>phủ định hoàn toàn</b>: <span class=\"zh\">她一件衣服都不想买</span> = một cái áo cũng không muốn mua.</li><li>\"一 + lượng từ\" có thể thay bằng <span class=\"zh\">一点儿</span>; vị ngữ là <b>tính từ</b> → <span class=\"zh\">一点儿也不冷</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">一……也/都不/没</span> · Ba dạng thường gặp</h4><p>Một … cũng không · chẳng … chút nào</p><div class=\"gr-formula\"><div class=\"fx-lbl\">一 + LT + DT</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>一件衣服</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>都</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>不想买</b></span></div><div class=\"fx-ex zh\">她一件衣服都不想买。</div><div class=\"fx-lbl\">没 · chưa từng</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>一个中国电影</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>也</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>没看过</b></span></div><div class=\"fx-ex zh\">我一个中国电影也没看过。</div><div class=\"fx-lbl\">一点儿 + DT</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>一点儿东西</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>也</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>不想吃</b></span></div><div class=\"fx-ex zh\">我一点儿东西也不想吃。</div><div class=\"fx-lbl\">一点儿 + TT</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>一点儿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>也</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>不冷</b></span></div><div class=\"fx-ex zh\">草原一点儿也不冷。</div></div><p class=\"gr-key\"><span class=\"zh\">不</span>: không muốn / không (hiện tại)　·　<span class=\"zh\">没</span>: chưa / đã không (sự việc đã qua)</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> Vị ngữ là tính từ: <span class=\"zh\">一点儿 + 也/都 + 不/没 + 形容词</span> = chẳng … chút nào.</p>","note":"<b>Lưu ý:</b> Không xếp theo tiếng Việt: ✗ <span class=\"zh\">我没看过一个中国电影</span> → ✓ <span class=\"zh\">我一个中国电影也没看过</span>","examples":[{"zh":"她一件衣服都不想买。","py":"Tā yí jiàn yīfu dōu bù xiǎng mǎi.","vi":"Cô ấy chẳng muốn mua cái áo nào."},{"zh":"他对打球一点儿兴趣都没有。","py":"Tā duì dǎ qiú yìdiǎnr xìngqù dōu méiyǒu.","vi":"Anh ấy chẳng có chút hứng thú nào với chơi bóng."},{"zh":"草原一点儿也不冷。","py":"Cǎoyuán yìdiǎnr yě bù lěng.","vi":"Thảo nguyên chẳng lạnh chút nào."},{"zh":"他们一点儿也没着急。","py":"Tāmen yìdiǎnr yě méi zháojí.","vi":"Họ chẳng sốt ruột chút nào."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">这件衣服____，你买吧。（贵）</span><span class=\"qz-hint\">Cái áo này chẳng đắt chút nào, bạn mua đi.</span>","answer":["一点儿也不贵","一点儿都不贵","一点也不贵","一点都不贵"],"explain":"这件衣服一点儿也不贵，你买吧。（贵） (Zhè jiàn yīfu yìdiǎnr yě bú guì, nǐ mǎi ba. (guì))"},{"type":"fill","q":"<span class=\"zh\">我们上个月搬家了，____。（认识）</span><span class=\"qz-hint\">Tháng trước chúng mình chuyển nhà, chẳng quen ai cả.</span>","answer":["一个人都不认识","一个人也不认识","我一个人都不认识","我一个人也不认识"],"explain":"我们上个月搬家了，一个人都不认识。（认识） (Wǒmen shàng ge yuè bānjiā le, yí ge rén dōu bú rènshi. (rènshi))"},{"type":"fill","q":"<span class=\"zh\">这个星期我太忙了，____。（时间）</span><span class=\"qz-hint\">Tuần này mình bận quá, chẳng có chút thời gian nào.</span>","answer":["一点儿时间也没有","一点儿时间都没有","我一点儿时间也没有","一点时间也没有"],"explain":"这个星期我太忙了，一点儿时间也没有。（时间） (Zhège xīngqī wǒ tài máng le, yìdiǎnr shíjiān yě méiyǒu. (shíjiān))"}]},{"title":"Câu so sánh (9): A跟B一样","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>A</b><small>người / vật A</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>跟</b><small>với</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b><small>người / vật B</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>(不) 一样</b><small>(không) giống</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词</b><small>phương diện</small></span></div>","summary":"<p class=\"gr-lead\">A giống B · A … bằng B</p><ul><li><span class=\"zh\">A 跟 B 一样</span>: so sánh xong thấy <b>giống nhau</b>; thêm tính từ sau 一样 để nói giống về <b>mặt nào</b>: <span class=\"zh\">一样大 · 一样高</span>.</li><li>Phủ định: <span class=\"zh\">不</span> đặt <b>trước 一样</b>: <span class=\"zh\">这家宾馆跟别的都不一样</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">这个房间跟那个房间一样大。</span> = Phòng này <b>to bằng</b> phòng kia.</p>","note":"<b>Lưu ý:</b> Không xếp theo tiếng Việt \"cao bằng\": ✗ <span class=\"zh\">他高跟我一样</span> → ✓ <span class=\"zh\">他跟我一样高</span>","examples":[{"zh":"这家宾馆跟别的都不一样。","py":"Zhè jiā bīnguǎn gēn biéde dōu bù yíyàng.","vi":"Khách sạn này chẳng giống chỗ nào khác."},{"zh":"他买的新手机跟我的一样。","py":"Tā mǎi de xīn shǒujī gēn wǒ de yíyàng.","vi":"Chiếc điện thoại mới anh ấy mua giống của mình."},{"zh":"这个房间跟那个房间一样大。","py":"Zhège fángjiān gēn nàge fángjiān yíyàng dà.","vi":"Phòng này to bằng phòng kia."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">我的杯子____。</span><span class=\"qz-hint\">Cốc của mình giống của bạn.</span>","answer":["跟你的一样","和你的一样"],"explain":"我的杯子跟你的一样。 (Wǒ de bēizi gēn nǐ de yíyàng.)"}]},{"title":"Cấu trúc 除了……（以外），……都/还/也……","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>除了</b><small>trừ / ngoài</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>A</b><small>phần tách ra</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>(以外)，</b><small>có thể lược</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>(主语) 都 / 还 / 也</b><small>đều / còn / cũng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>……</b><small>phần còn lại</small></span></div>","summary":"<p class=\"gr-lead\">Trừ … ra, … đều · Ngoài … ra, … còn</p><ul><li><span class=\"zh\">除了…（以外），…都…</span>: <b>loại trừ</b> — trừ A ra, những cái khác đều như nhau; <span class=\"zh\">以外</span> có thể lược.</li><li><span class=\"zh\">除了…（以外），…还/也…</span>: <b>bổ sung</b> — ngoài A ra còn thêm; chủ ngữ ở <b>đầu câu</b> hoặc <b>trước 还/也</b>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">除了……（以外）</span> · Loại trừ · Bổ sung</h4><p>都 ↔ 还 / 也</p><div class=\"gr-formula\"><div class=\"fx-lbl\">都 · loại trừ</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>除了我以外</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>都</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>在玩手机</b></span></div><div class=\"fx-ex zh\">除了我以外，大家都在玩手机。</div><div class=\"fx-lbl\">都 · loại trừ</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>除了这个汉字</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>都</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>会写</b></span></div><div class=\"fx-ex zh\">除了这个汉字，别的汉字我都会写。</div><div class=\"fx-lbl\">还 · bổ sung</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>除了行李箱</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>还</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>有别的</b></span></div><div class=\"fx-ex zh\">除了这个行李箱以外，还有别的东西吗？</div><div class=\"fx-lbl\">也 · bổ sung</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>除了唱歌</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>也</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>喜欢跳舞</b></span></div><div class=\"fx-ex zh\">除了唱歌以外，他也喜欢跳舞。</div></div><p class=\"gr-key\">Loại trừ: A <b>không</b> nằm trong nhóm \"都\"　·　Bổ sung: A <b>cũng</b> được tính, còn thêm cái khác</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">……都……</span> → <b>loại trừ</b>　·　<span class=\"zh\">……还 / 也……</span> → <b>bổ sung</b></p>","note":"<b>Lưu ý:</b> Chủ ngữ không đứng sau 还/也: ✗ <span class=\"zh\">除了唱歌，也他喜欢跳舞</span> → ✓ <span class=\"zh\">除了唱歌，他也喜欢跳舞</span>","examples":[{"zh":"除了我以外，大家都在玩手机。","py":"Chúle wǒ yǐwài, dàjiā dōu zài wán shǒujī.","vi":"Trừ mình ra, mọi người đều đang chơi điện thoại."},{"zh":"除了这个汉字，别的汉字我都会写。","py":"Chúle zhège Hànzì, biéde Hànzì wǒ dōu huì xiě.","vi":"Trừ chữ Hán này ra, các chữ khác mình đều viết được."},{"zh":"除了这个行李箱以外，还有别的东西吗？","py":"Chúle zhège xínglixiāng yǐwài, hái yǒu biéde dōngxi ma?","vi":"Ngoài cái va li này ra, còn đồ gì khác không?"},{"zh":"除了唱歌以外，他也喜欢跳舞。","py":"Chúle chànggē yǐwài, tā yě xǐhuan tiàowǔ.","vi":"Ngoài hát ra, anh ấy cũng thích nhảy."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">妈妈喜欢喝咖啡，也喜欢喝茶。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____。</span></span></span><span class=\"qz-hint\">Mẹ thích uống cà phê, cũng thích uống trà. — Ngoài cà phê ra, mẹ cũng thích uống trà.</span>","answer":["除了咖啡以外，妈妈也喜欢喝茶","除了咖啡，妈妈也喜欢喝茶","除了咖啡以外，妈妈还喜欢喝茶","妈妈除了咖啡以外，也喜欢喝茶","妈妈除了咖啡以外，还喜欢喝茶"],"explain":"除了咖啡以外，妈妈也喜欢喝茶。 (Chúle kāfēi yǐwài, māma yě xǐhuan hē chá.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">王老师是中国人，别的老师都是外国人。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____。</span></span></span><span class=\"qz-hint\">Cô Vương là người Trung Quốc, các thầy cô khác đều là người nước ngoài. — Trừ cô Vương ra, các thầy cô khác đều là người nước ngoài.</span>","answer":["除了王老师以外，别的老师都是外国人","除了王老师，别的老师都是外国人"],"explain":"除了王老师以外，别的老师都是外国人。 (Chúle Wáng lǎoshī yǐwài, biéde lǎoshī dōu shì wàiguórén.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我只想吃水果，别的东西都不想吃。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____。</span></span></span><span class=\"qz-hint\">Mình chỉ muốn ăn hoa quả, những thứ khác đều không muốn ăn. — Ngoài hoa quả ra, những thứ khác mình đều không muốn ăn.</span>","answer":["除了水果以外，别的东西我都不想吃","除了水果，别的东西我都不想吃","除了水果以外，我别的东西都不想吃"],"explain":"除了水果以外，别的东西我都不想吃。 (Chúle shuǐguǒ yǐwài, biéde dōngxi wǒ dōu bù xiǎng chī.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在王一飞家","titleVi":"Nhà Nhất Phi — bàn chuyện kỳ nghỉ","lines":[{"speaker":"乐","name":"Đồng Lạc","zh":"这个假期咱们去哪儿玩玩吧。","py":"Zhège jiàqī zánmen qù nǎr wánwan ba.","vi":"Kỳ nghỉ này mình đi đâu đó chơi đi."},{"speaker":"飞","name":"Nhất Phi","zh":"好啊，你想去哪儿，咱们就去哪儿。","py":"Hǎo a, nǐ xiǎng qù nǎr, zánmen jiù qù nǎr.","vi":"Được thôi, anh muốn đi đâu thì mình đi đó."},{"speaker":"乐","name":"Đồng Lạc","zh":"你喜欢海，找个海边住几天，怎么样？","py":"Nǐ xǐhuan hǎi, zhǎo ge hǎibiān zhù jǐ tiān, zěnmeyàng?","vi":"Em thích biển, tìm chỗ nào ven biển ở vài ngày, thấy sao?"},{"speaker":"飞","name":"Nhất Phi","zh":"现在去海边有点儿冷。","py":"Xiànzài qù hǎibiān yǒudiǎnr lěng.","vi":"Giờ ra biển hơi lạnh."},{"speaker":"乐","name":"Đồng Lạc","zh":"那去草原吧？草原一点儿也不冷。","py":"Nà qù cǎoyuán ba? Cǎoyuán yìdiǎnr yě bù lěng.","vi":"Vậy đi thảo nguyên nhé? Thảo nguyên chẳng lạnh chút nào."},{"speaker":"飞","name":"Nhất Phi","zh":"这个主意好！我好久没骑马了。","py":"Zhège zhǔyi hǎo! Wǒ hǎojiǔ méi qí mǎ le.","vi":"Ý này hay đấy! Lâu lắm rồi em không cưỡi ngựa."},{"speaker":"乐","name":"Đồng Lạc","zh":"对，在草原上骑马、吃羊肉、看月亮，一定很有意思。","py":"Duì, zài cǎoyuán shang qí mǎ, chī yángròu, kàn yuèliang, yídìng hěn yǒu yìsi.","vi":"Đúng thế, trên thảo nguyên cưỡi ngựa, ăn thịt cừu, ngắm trăng, chắc chắn rất thú vị."}]},{"titleZh":"课文二 · 在王一飞家","titleVi":"Phòng khách — chuẩn bị cho chuyến đi","lines":[{"speaker":"乐","name":"Đồng Lạc","zh":"出去玩的机票买好了吗？","py":"Chūqu wán de jīpiào mǎihǎo le ma?","vi":"Vé máy bay đi chơi mua xong chưa?"},{"speaker":"飞","name":"Nhất Phi","zh":"买好了。星期六上午十点一刻起飞。","py":"Mǎihǎo le. Xīngqīliù shàngwǔ shí diǎn yí kè qǐfēi.","vi":"Mua xong rồi. 10 giờ 15 sáng thứ bảy cất cánh."},{"speaker":"乐","name":"Đồng Lạc","zh":"宾馆也选好了吗？","py":"Bīnguǎn yě xuǎnhǎo le ma?","vi":"Khách sạn cũng chọn xong rồi à?"},{"speaker":"飞","name":"Nhất Phi","zh":"是的，这家宾馆很特别，跟别的都不一样，一出门就能看见牛和羊！","py":"Shì de, zhè jiā bīnguǎn hěn tèbié, gēn biéde dōu bù yíyàng, yì chūmén jiù néng kànjiàn niú hé yáng!","vi":"Vâng, khách sạn này rất đặc biệt, chẳng giống chỗ nào khác, vừa bước ra cửa là thấy bò và cừu!"},{"speaker":"乐","name":"Đồng Lạc","zh":"太好了！你看看要带什么东西？","py":"Tài hǎo le! Nǐ kànkan yào dài shénme dōngxi?","vi":"Tuyệt quá! Em xem cần mang theo những gì?"},{"speaker":"飞","name":"Nhất Phi","zh":"我们不用带太多东西，别忘了拿上新买的相机。","py":"Wǒmen búyòng dài tài duō dōngxi, bié wàngle náshang xīn mǎi de xiàngjī.","vi":"Mình không cần mang nhiều đồ quá, đừng quên cầm theo cái máy ảnh mới mua."},{"speaker":"乐","name":"Đồng Lạc","zh":"一定不会忘带的。我现在就去准备行李。","py":"Yídìng bú huì wàng dài de. Wǒ xiànzài jiù qù zhǔnbèi xíngli.","vi":"Chắc chắn không quên đâu. Anh đi chuẩn bị hành lý ngay đây."}]},{"titleZh":"课文三 · 在机场","titleVi":"Sân bay — tài xế Tiểu Lý ra đón","lines":[{"speaker":"李","name":"Tiểu Lý","zh":"欢迎你们！我是你们的司机，我姓李，叫我小李就可以。","py":"Huānyíng nǐmen! Wǒ shì nǐmen de sījī, wǒ xìng Lǐ, jiào wǒ Xiǎo Lǐ jiù kěyǐ.","vi":"Chào mừng anh chị! Tôi là tài xế của anh chị, tôi họ Lý, cứ gọi tôi là Tiểu Lý."},{"speaker":"乐","name":"Đồng Lạc","zh":"您好！不好意思，飞机晚点了，让您久等了。","py":"Nín hǎo! Bù hǎoyìsi, fēijī wǎndiǎn le, ràng nín jiǔ děng le.","vi":"Chào anh! Ngại quá, máy bay bị trễ, để anh đợi lâu rồi."},{"speaker":"李","name":"Tiểu Lý","zh":"没关系。除了这个行李箱以外，还有别的东西吗？","py":"Méi guānxi. Chúle zhège xínglixiāng yǐwài, hái yǒu biéde dōngxi ma?","vi":"Không sao. Ngoài cái va li này ra, còn đồ gì khác không ạ?"},{"speaker":"乐","name":"Đồng Lạc","zh":"还有一个包，我自己拿就可以。","py":"Hái yǒu yí ge bāo, wǒ zìjǐ ná jiù kěyǐ.","vi":"Còn một cái túi, tôi tự xách được."},{"speaker":"李","name":"Tiểu Lý","zh":"车在一层，请跟我来。","py":"Chē zài yī céng, qǐng gēn wǒ lái.","vi":"Xe ở tầng một, mời đi theo tôi."},{"speaker":"乐","name":"Đồng Lạc","zh":"我们住的宾馆离机场远吗？","py":"Wǒmen zhù de bīnguǎn lí jīchǎng yuǎn ma?","vi":"Khách sạn chúng tôi ở có xa sân bay không?"},{"speaker":"李","name":"Tiểu Lý","zh":"不远，三十分钟就能到。两位到了可以先休息休息，晚饭的时候我叫你们。","py":"Bù yuǎn, sānshí fēnzhōng jiù néng dào. Liǎng wèi dàole kěyǐ xiān xiūxi xiūxi, wǎnfàn de shíhou wǒ jiào nǐmen.","vi":"Không xa, ba mươi phút là tới. Hai vị đến nơi cứ nghỉ ngơi trước, đến bữa tối tôi gọi."}]},{"titleZh":"课文四 · 在宾馆","titleVi":"Khách sạn — Nhất Phi viết nhật ký","para":true,"speaker":"飞","lines":[{"zh":"今天是我们旅游的第一天。","py":"Jīntiān shì wǒmen lǚyóu de dì yī tiān.","vi":"Hôm nay là ngày đầu tiên của chuyến du lịch."},{"zh":"我们很早就起床去机场了，没想到飞机晚点了。","py":"Wǒmen hěn zǎo jiù qǐchuáng qù jīchǎng le, méi xiǎngdào fēijī wǎndiǎn le.","vi":"Chúng tôi dậy từ rất sớm để ra sân bay, không ngờ máy bay lại bị trễ."},{"zh":"我们到的时候，天已经黑了，但是司机小李一直在机场等我们，一点儿也没着急。","py":"Wǒmen dào de shíhou, tiān yǐjīng hēi le, dànshì sījī Xiǎo Lǐ yìzhí zài jīchǎng děng wǒmen, yìdiǎnr yě méi zháojí.","vi":"Lúc chúng tôi đến nơi, trời đã tối, nhưng tài xế Tiểu Lý vẫn đợi chúng tôi ở sân bay suốt, chẳng sốt ruột chút nào."},{"zh":"他特别热情，路上给我们介绍了很多东西，还准备了水果。","py":"Tā tèbié rèqíng, lùshang gěi wǒmen jièshàole hěn duō dōngxi, hái zhǔnbèile shuǐguǒ.","vi":"Anh ấy cực kỳ nhiệt tình, trên đường giới thiệu cho chúng tôi rất nhiều thứ, còn chuẩn bị cả hoa quả."},{"zh":"宾馆的房间跟我想的一样漂亮，又大又干净，我非常满意。","py":"Bīnguǎn de fángjiān gēn wǒ xiǎng de yíyàng piàoliang, yòu dà yòu gānjìng, wǒ fēicháng mǎnyì.","vi":"Phòng khách sạn đẹp đúng như tôi nghĩ, vừa rộng vừa sạch, tôi vô cùng hài lòng."}]}]},"extra":[],"activity":{"act":[{"zh":"多人活动","py":"duōrén huódòng","tag":"Hoạt động nhóm","mean":"Kế hoạch kỳ nghỉ","q":{"zh":"四人一组，设计一个假期旅游计划，比一比哪组的最好玩儿。","py":"Sì rén yì zǔ, shèjì yí ge jiàqī lǚyóu jìhuà, bǐ yi bǐ nǎ zǔ de zuì hǎowánr.","vi":"Nhóm 4 người lập kế hoạch du lịch, trình bày rồi cả lớp bỏ phiếu (2 phiếu / người)."},"items":[{"zh":"地点：除了海边以外，我们还想去草原。","py":"Dìdiǎn: chúle hǎibiān yǐwài, wǒmen hái xiǎng qù cǎoyuán.","vi":"Địa điểm: ngoài biển ra, nhóm còn muốn đi thảo nguyên."},{"zh":"交通：我们坐飞机去，上午十点一刻起飞。","py":"Jiāotōng: wǒmen zuò fēijī qù, shàngwǔ shí diǎn yí kè qǐfēi.","vi":"Đi lại: đi máy bay, 10 giờ 15 sáng cất cánh."},{"zh":"住宿：这家宾馆很特别，跟别的都不一样。","py":"Zhùsù: zhè jiā bīnguǎn hěn tèbié, gēn biéde dōu bù yíyàng.","vi":"Chỗ ở: khách sạn này rất đặc biệt, chẳng giống chỗ nào."},{"zh":"活动：每天骑马、看月亮，一点儿也不累。","py":"Huódòng: měi tiān qí mǎ, kàn yuèliang, yìdiǎnr yě bú lèi.","vi":"Hoạt động: ngày nào cũng cưỡi ngựa, ngắm trăng, chẳng mệt chút nào."}]}],"speak":[]}},{"id":"k3v3-b05","courseId":"k3v3","order":5,"title":"Ảnh như thế này mới đẹp","titleZh":"这样的照片才好看","titlePy":"zhèyàng de zhàopiàn cái hǎokàn","vocab":[{"stt":1,"hanzi":"总是","pinyin":"zǒngshì","hanviet":"Tổng thị","pos":"Phó từ","meaning":"luôn luôn, lúc nào cũng","comps":"总是这样 (lúc nào cũng thế), 总是迟到 (luôn đến muộn)","example":{"zh":"他总是很早就来教室。","py":"Tā zǒngshì hěn zǎo jiù lái jiàoshì.","vi":"Cậu ấy lúc nào cũng đến lớp rất sớm."}},{"stt":2,"hanzi":"终于","pinyin":"zhōngyú","hanviet":"Chung vu","pos":"Phó từ","meaning":"cuối cùng (thì)","comps":"终于到了 (cuối cùng cũng tới), 终于明白了 (cuối cùng cũng hiểu)","example":{"zh":"等了一个小时，车终于来了。","py":"Děngle yí ge xiǎoshí, chē zhōngyú lái le.","vi":"Đợi một tiếng, cuối cùng xe cũng đến."}},{"stt":3,"hanzi":"爬","pinyin":"pá","hanviet":"Bà","pos":"Động từ","meaning":"leo, trèo; bò","comps":"爬山 (leo núi), 爬上去 (leo lên)","example":{"zh":"电梯坏了，我们爬上去吧。","py":"Diàntī huài le, wǒmen pá shàngqu ba.","vi":"Thang máy hỏng rồi, mình leo bộ lên đi."}},{"stt":4,"hanzi":"山","pinyin":"shān","hanviet":"Sơn","pos":"Danh từ","meaning":"núi","comps":"爬山 (leo núi), 山上 (trên núi)","example":{"zh":"我们周末去爬山吧。","py":"Wǒmen zhōumò qù pá shān ba.","vi":"Cuối tuần mình đi leo núi nhé."}},{"stt":5,"hanzi":"锻炼","pinyin":"duànliàn","hanviet":"Đoán luyện","pos":"Động từ","meaning":"rèn luyện, tập thể dục","comps":"锻炼身体 (rèn luyện sức khoẻ), 去锻炼 (đi tập)","example":{"zh":"我每天早上都去公园锻炼身体。","py":"Wǒ měi tiān zǎoshang dōu qù gōngyuán duànliàn shēntǐ.","vi":"Sáng nào mình cũng ra công viên tập thể dục."}},{"stt":6,"hanzi":"照","pinyin":"zhào","hanviet":"Chiếu","pos":"Động từ","meaning":"chụp (ảnh)","comps":"照照片 (chụp ảnh), 照一张 (chụp một tấm)","example":{"zh":"你帮我照一张照片，好吗？","py":"Nǐ bāng wǒ zhào yì zhāng zhàopiàn, hǎo ma?","vi":"Bạn chụp giúp mình một tấm ảnh được không?"}},{"stt":7,"hanzi":"鞋","pinyin":"xié","hanviet":"Hài","pos":"Danh từ","meaning":"giày","comps":"运动鞋 (giày thể thao), 一双鞋 (một đôi giày)","example":{"zh":"这双鞋穿着很舒服。","py":"Zhè shuāng xié chuānzhe hěn shūfu.","vi":"Đôi giày này đi rất thoải mái."}},{"stt":8,"hanzi":"大衣","pinyin":"dàyī","hanviet":"Đại y","pos":"Danh từ","meaning":"áo khoác dài, áo măng tô","comps":"穿大衣 (mặc áo khoác), 一件大衣 (một chiếc áo khoác)","example":{"zh":"外边很冷，穿上大衣吧。","py":"Wàibian hěn lěng, chuānshang dàyī ba.","vi":"Ngoài trời lạnh lắm, mặc áo khoác vào đi."}},{"stt":9,"hanzi":"拍照","pinyin":"pāizhào","hanviet":"Phách chiếu","pos":"Động từ (li hợp)","meaning":"chụp ảnh","comps":"喜欢拍照 (thích chụp ảnh), 拍几张照 (chụp vài tấm)","example":{"zh":"这里不能拍照。","py":"Zhèli bù néng pāizhào.","vi":"Ở đây không được chụp ảnh."}},{"stt":10,"hanzi":"感兴趣","pinyin":"gǎn xìngqù","hanviet":"Cảm hứng thú","pos":"Cụm động từ","meaning":"cảm thấy hứng thú","comps":"对……感兴趣 (hứng thú với…), 不感兴趣 (không hứng thú)","example":{"zh":"我对中国文化很感兴趣。","py":"Wǒ duì Zhōngguó wénhuà hěn gǎn xìngqù.","vi":"Mình rất hứng thú với văn hoá Trung Quốc."}},{"stt":11,"hanzi":"照相","pinyin":"zhàoxiàng","hanviet":"Chiếu tướng","pos":"Động từ (li hợp)","meaning":"chụp ảnh","comps":"照相机 (máy ảnh), 给他照相 (chụp ảnh cho anh ấy)","example":{"zh":"我们在这儿照个相吧。","py":"Wǒmen zài zhèr zhào ge xiàng ba.","vi":"Mình chụp một tấm ở đây đi."}},{"stt":12,"hanzi":"难看","pinyin":"nánkàn","hanviet":"Nan khán","pos":"Tính từ","meaning":"xấu, khó coi","comps":"很难看 (rất xấu), 不难看 (không xấu)","example":{"zh":"这件衣服的颜色有点儿难看。","py":"Zhè jiàn yīfu de yánsè yǒudiǎnr nánkàn.","vi":"Màu của chiếc áo này hơi xấu."}},{"stt":13,"hanzi":"比较","pinyin":"bǐjiào","hanviet":"Tỷ giảo","pos":"Động từ / Phó từ","meaning":"so sánh; tương đối, khá","comps":"比较一下 (so sánh thử), 比较好 (khá tốt)","example":{"zh":"今天比较冷，多穿点儿衣服。","py":"Jīntiān bǐjiào lěng, duō chuān diǎnr yīfu.","vi":"Hôm nay khá lạnh, mặc thêm áo vào."}},{"stt":14,"hanzi":"水平","pinyin":"shuǐpíng","hanviet":"Thuỷ bình","pos":"Danh từ","meaning":"trình độ","comps":"汉语水平 (trình độ tiếng Trung), 水平高 (trình độ cao)","example":{"zh":"他的汉语水平很高。","py":"Tā de Hànyǔ shuǐpíng hěn gāo.","vi":"Trình độ tiếng Trung của anh ấy rất cao."}},{"stt":15,"hanzi":"太阳","pinyin":"tàiyáng","hanviet":"Thái dương","pos":"Danh từ","meaning":"mặt trời; nắng","comps":"出太阳 (có nắng), 太阳很大 (nắng to)","example":{"zh":"今天太阳很大，别忘了带水。","py":"Jīntiān tàiyáng hěn dà, bié wàngle dài shuǐ.","vi":"Hôm nay nắng to, đừng quên mang nước."}},{"stt":16,"hanzi":"树","pinyin":"shù","hanviet":"Thụ","pos":"Danh từ","meaning":"cây","comps":"大树 (cây to), 树上 (trên cây)","example":{"zh":"学校里有很多大树。","py":"Xuéxiào li yǒu hěn duō dà shù.","vi":"Trong trường có rất nhiều cây to."}},{"stt":17,"hanzi":"干","pinyin":"gàn","hanviet":"Cán","pos":"Động từ","meaning":"làm","comps":"干什么 (làm gì), 干活儿 (làm việc)","example":{"zh":"你周末想干什么？","py":"Nǐ zhōumò xiǎng gàn shénme?","vi":"Cuối tuần bạn muốn làm gì?"}},{"stt":18,"hanzi":"电","pinyin":"diàn","hanviet":"Điện","pos":"Danh từ","meaning":"điện; pin","comps":"没电了 (hết pin / mất điện), 停电 (mất điện)","example":{"zh":"我的手机快没电了。","py":"Wǒ de shǒujī kuài méi diàn le.","vi":"Điện thoại mình sắp hết pin rồi."}},{"stt":19,"hanzi":"收到","pinyin":"shōudào","hanviet":"Thu đáo","pos":"Động từ","meaning":"nhận được","comps":"收到邮件 (nhận được email), 收到礼物 (nhận được quà)","example":{"zh":"你收到我的短信了吗？","py":"Nǐ shōudào wǒ de duǎnxìn le ma?","vi":"Bạn nhận được tin nhắn của mình chưa?"}},{"stt":20,"hanzi":"封","pinyin":"fēng","hanviet":"Phong","pos":"Lượng từ","meaning":"bức, lá (thư)","comps":"一封信 (một bức thư), 一封邮件 (một email)","example":{"zh":"我昨天给老师写了一封邮件。","py":"Wǒ zuótiān gěi lǎoshī xiěle yì fēng yóujiàn.","vi":"Hôm qua mình viết cho cô giáo một email."}},{"stt":21,"hanzi":"邮件","pinyin":"yóujiàn","hanviet":"Bưu kiện","pos":"Danh từ","meaning":"thư, email","comps":"发邮件 (gửi email), 电子邮件 (thư điện tử)","example":{"zh":"我每天早上都看邮件。","py":"Wǒ měi tiān zǎoshang dōu kàn yóujiàn.","vi":"Sáng nào mình cũng xem email."}},{"stt":22,"hanzi":"难过","pinyin":"nánguò","hanviet":"Nan quá","pos":"Tính từ","meaning":"buồn","comps":"很难过 (rất buồn), 别难过 (đừng buồn)","example":{"zh":"考得不好，她难过得很。","py":"Kǎo de bù hǎo, tā nánguò de hěn.","vi":"Thi không tốt, cô ấy buồn lắm."}},{"stt":23,"hanzi":"哈哈","pinyin":"hāhā","hanviet":"Cáp cáp","pos":"Từ tượng thanh","meaning":"ha ha (tiếng cười)","comps":"哈哈大笑 (cười ha hả), 哈哈哈 (ha ha ha)","example":{"zh":"哈哈，你说得太有意思了！","py":"Hāhā, nǐ shuō de tài yǒu yìsi le!","vi":"Ha ha, bạn nói thú vị quá!"}},{"stt":24,"hanzi":"音乐","pinyin":"yīnyuè","hanviet":"Âm nhạc","pos":"Danh từ","meaning":"âm nhạc","comps":"听音乐 (nghe nhạc), 中国音乐 (nhạc Trung Quốc)","example":{"zh":"你喜欢听什么音乐？","py":"Nǐ xǐhuan tīng shénme yīnyuè?","vi":"Bạn thích nghe nhạc gì?"}},{"stt":25,"hanzi":"兴趣","pinyin":"xìngqù","hanviet":"Hứng thú","pos":"Danh từ","meaning":"hứng thú, sở thích","comps":"有兴趣 (có hứng thú), 兴趣爱好 (sở thích)","example":{"zh":"他对画画儿很有兴趣。","py":"Tā duì huà huàr hěn yǒu xìngqù.","vi":"Cậu ấy rất có hứng thú với vẽ tranh."}},{"stt":26,"hanzi":"会","pinyin":"huì","hanviet":"Hội","pos":"Danh từ","meaning":"buổi (hội); cuộc họp","comps":"音乐会 (buổi hoà nhạc), 开会 (họp)","example":{"zh":"明天上午我们要开会。","py":"Míngtiān shàngwǔ wǒmen yào kāihuì.","vi":"Sáng mai chúng mình phải họp."}},{"stt":27,"hanzi":"结束","pinyin":"jiéshù","hanviet":"Kết thúc","pos":"Động từ","meaning":"kết thúc","comps":"考试结束 (thi xong), 结束了 (kết thúc rồi)","example":{"zh":"电影几点结束？","py":"Diànyǐng jǐ diǎn jiéshù?","vi":"Phim mấy giờ kết thúc?"}}],"hanzi":[{"char":"总是","pinyin":"zǒngshì","hanviet":"Tổng thị","chars":["总","是"],"story":"总 (phồn thể 總 = 糸 sợi tơ + 悤) → gom các sợi lại một mối → tổng, gộp. 是 = là. 总是 = gộp mọi lần lại đều như thế → luôn luôn, lúc nào cũng."},{"char":"终于","pinyin":"zhōngyú","hanviet":"Chung vu","chars":["终","于"],"story":"终 = 纟 (sợi tơ) + 冬 dōng chỉ âm (mùa đông, cuối năm) → đầu cuối sợi tơ → kết thúc. 于 = vào, ở. 终于 = đến lúc cuối → cuối cùng (thì), thường sau khi chờ đợi lâu."},{"char":"爬","pinyin":"pá","hanviet":"Bà","chars":["爬"],"story":"爬 = 爪 (móng vuốt) + 巴 bā chỉ âm → bám tay chân mà đi → bò, leo. 爬山 = leo núi, 爬楼 = leo cầu thang."},{"char":"山","pinyin":"shān","hanviet":"Sơn","chars":["山"],"story":"山 là chữ tượng hình ba ngọn núi nhô lên, ngọn giữa cao nhất. 山上 = trên núi, 爬山 = leo núi."},{"char":"锻炼","pinyin":"duànliàn","hanviet":"Đoán luyện","chars":["锻","炼"],"story":"锻 = 钅 (kim loại) + 段 duàn chỉ âm → rèn sắt. 炼 = 火 (lửa) + 柬 → luyện trong lửa. 锻炼 = rèn luyện như rèn sắt → tập luyện thân thể: 锻炼身体."},{"char":"照","pinyin":"zhào","hanviet":"Chiếu","chars":["照"],"story":"照 = 昭 (sáng rõ) + 灬 (lửa) → ánh sáng chiếu rọi. Ánh sáng chiếu vào ống kính → chụp ảnh. 照 là động từ đơn, mang tân ngữ: 照照片, 给我照几张."},{"char":"鞋","pinyin":"xié","hanviet":"Hài","chars":["鞋"],"story":"鞋 = 革 (da thuộc) + 圭 guī chỉ âm → giày làm bằng da. 运动鞋 = giày thể thao; lượng từ dùng 双: 一双鞋."},{"char":"大衣","pinyin":"dàyī","hanviet":"Đại y","chars":["大","衣"],"story":"大 = to. 衣 vẽ cổ áo và hai vạt áo → áo. 大衣 = chiếc áo to, dài mặc ngoài cùng → áo khoác dài, áo măng tô."},{"char":"拍照","pinyin":"pāizhào","hanviet":"Phách chiếu","chars":["拍","照"],"story":"拍 = 扌 (tay) + 白 bái chỉ âm → vỗ, đập; bấm (máy ảnh). 照 = ảnh. 拍照 = bấm máy → chụp ảnh. Li hợp: 拍几张照."},{"char":"感兴趣","pinyin":"gǎn xìngqù","hanviet":"Cảm hứng thú","chars":["感","兴","趣"],"story":"感 = 咸 + 心 (tim) → cảm nhận trong lòng. 兴 đọc xìng = hứng. 趣 = 走 + 取 qǔ chỉ âm → thú vị. 感兴趣 = cảm thấy hứng thú; dùng: 对 A 感兴趣."},{"char":"照相","pinyin":"zhàoxiàng","hanviet":"Chiếu tướng","chars":["照","相"],"story":"照 = chiếu sáng, chụp. 相 = 木 + 目 (mắt) → nhìn; dung mạo, đọc xiàng. 照相 = chụp lại dung mạo → chụp ảnh. 照相 = 拍照, đều là li hợp; còn 照 mang tân ngữ trực tiếp."},{"char":"难看","pinyin":"nánkàn","hanviet":"Nan khán","chars":["难","看"],"story":"难 = 又 + 隹 (chim) → khó. 看 = 手 (tay) che trên 目 (mắt) → nhìn. 难看 = khó nhìn → xấu, khó coi. Trái nghĩa: 好看."},{"char":"比较","pinyin":"bǐjiào","hanviet":"Tỷ giảo","chars":["比","较"],"story":"比 vẽ hai người đứng cạnh nhau → so. 较 = 车 + 交 jiāo chỉ âm → so đo. 比较 = so sánh; đứng trước tính từ làm phó từ: 比较好 = khá tốt."},{"char":"水平","pinyin":"shuǐpíng","hanviet":"Thuỷ bình","chars":["水","平"],"story":"水 = nước. 平 = phẳng. 水平 = mặt nước phẳng lặng, dùng làm thước đo cân bằng → mức độ, trình độ: 汉语水平, 拍照水平."},{"char":"太阳","pinyin":"tàiyáng","hanviet":"Thái dương","chars":["太","阳"],"story":"太 = 大 thêm một chấm → rất lớn. 阳 = 阝 (gò đất) + 日 (mặt trời) → phía có nắng. 太阳 = vầng sáng rất lớn → mặt trời; 出太阳 = có nắng."},{"char":"树","pinyin":"shù","hanviet":"Thụ","chars":["树"],"story":"树 = 木 (cây) + 对 (biến âm) → cái cây. 木 còn làm bộ trong 林, 桌, 椅. 树上 = trên cây, 大树 = cây to."},{"char":"干","pinyin":"gàn","hanviet":"Cán","chars":["干"],"story":"干 có hai âm: gān = khô (干净, bài 4) · gàn = làm (干什么). Chữ vẽ cây chày có cán → cầm công cụ để làm. 干 gàn mang sắc thái khẩu ngữ hơn 做."},{"char":"电","pinyin":"diàn","hanviet":"Điện","chars":["电"],"story":"电 vẽ tia chớp xé qua đám mây: phần 日 là mây, nét móc dài là tia sét → điện. 电话, 电脑, 电视 đều có 电. 手机没电了 = điện thoại hết pin."},{"char":"收到","pinyin":"shōudào","hanviet":"Thu đáo","chars":["收","到"],"story":"收 = 丩 + 攵 (tay cầm gậy) → gom, thu về. 到 = đến. 收到 = thu được, đã đến tay → nhận được: 收到邮件, 收到礼物."},{"char":"封","pinyin":"fēng","hanviet":"Phong","chars":["封"],"story":"封 = 圭 (hai lớp đất) + 寸 (bàn tay) → đắp đất bao kín → niêm phong. Thư được dán kín → lượng từ cho thư: 一封信, 一封邮件."},{"char":"邮件","pinyin":"yóujiàn","hanviet":"Bưu kiện","chars":["邮","件"],"story":"邮 = 阝 (thành ấp) + 由 yóu chỉ âm → trạm chuyển thư (bưu). 件 = 亻 + 牛 → món, cái. 邮件 = món đồ gửi qua bưu điện → thư; nay chủ yếu là email."},{"char":"难过","pinyin":"nánguò","hanviet":"Nan quá","chars":["难","过"],"story":"难 = khó. 过 = 辶 (đi) + 寸 → trải qua, sống qua. 难过 = ngày khó trôi qua → buồn. Phân biệt: 难看 (xấu) · 难过 (buồn)."},{"char":"哈哈","pinyin":"hāhā","hanviet":"Cáp cáp","chars":["哈","哈"],"story":"哈 = 口 (miệng) + 合 hé chỉ âm → tiếng há miệng cười. 哈哈 = ha ha; 哈哈大笑 = cười ha hả. Hay dùng cuối tin nhắn để đùa vui."},{"char":"音乐","pinyin":"yīnyuè","hanviet":"Âm nhạc","chars":["音","乐"],"story":"音 = 立 + 日: tiếng phát ra từ miệng → âm thanh. 乐 vẽ cây đàn trên giá gỗ → nhạc, đọc yuè; đọc lè là vui (快乐). 音乐 = âm nhạc."},{"char":"兴趣","pinyin":"xìngqù","hanviet":"Hứng thú","chars":["兴","趣"],"story":"兴 đọc xìng = hứng (như 高兴). 趣 = 走 (đi) + 取 qǔ chỉ âm → điều khiến người ta tìm đến → thú vị. 兴趣 = hứng thú; 对……有兴趣 = 对……感兴趣."},{"char":"会","pinyin":"huì","hanviet":"Hội","chars":["会"],"story":"会 = 人 (mái che) + 云 → mọi người tụ họp dưới một mái → hội, buổi họp: 音乐会, 开会. Khác 会 động từ năng nguyện (biết, sẽ): 我会说汉语."},{"char":"结束","pinyin":"jiéshù","hanviet":"Kết thúc","chars":["结","束"],"story":"结 = 纟 (sợi tơ) + 吉 jí chỉ âm → thắt nút. 束 = 木 + 口 (dây buộc) → bó lại. 结束 = thắt nút buộc lại → kết thúc. Trái nghĩa: 开始."}],"grammar":[{"title":"Bổ ngữ trình độ (2): 形容词 + 得很","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词</b><small>tính từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>得很</b><small>… lắm</small></span></div>","summary":"<p class=\"gr-lead\">Tính từ + 得很: … lắm, … cực kỳ</p><ul><li><span class=\"zh\">得很</span> đứng <b>sau tính từ</b>, chỉ mức độ cao, thường dùng trong <b>khẩu ngữ</b>: <span class=\"zh\">现在天气好得很</span>.</li><li>Tính từ đứng trước 得很 <b>không</b> thêm 很 / 非常 / 太 nữa.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">好得很</span> = đẹp lắm · <span class=\"zh\">热得很</span> = nóng lắm — nhấn mạnh hơn <span class=\"zh\">很好 · 很热</span>, mang sắc thái khẩu ngữ.</p>","note":"<b>Lưu ý:</b> Không đặt phó từ mức độ trước tính từ: ✗ <span class=\"zh\">房间里面很热得很</span> → ✓ <span class=\"zh\">房间里面热得很</span>","examples":[{"zh":"现在天气好得很。","py":"Xiànzài tiānqì hǎo de hěn.","vi":"Bây giờ thời tiết đẹp lắm."},{"zh":"房间里面热得很。","py":"Fángjiān lǐmiàn rè de hěn.","vi":"Trong phòng nóng lắm."},{"zh":"我觉得爬山累得很。","py":"Wǒ juéde pá shān lèi de hěn.","vi":"Mình thấy leo núi mệt lắm."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这里的东西很贵，我什么也不想买。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____，我什么也不想买。</span></span></span><span class=\"qz-hint\">Đồ ở đây rất đắt, mình chẳng muốn mua gì. — Đồ ở đây đắt lắm, mình chẳng muốn mua gì.</span>","answer":["这里的东西贵得很"],"explain":"这里的东西贵得很，我什么也不想买。 (Zhèli de dōngxi guì de hěn, wǒ shénme yě bù xiǎng mǎi.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">超市里的水果特别多，想吃什么有什么。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____，想吃什么有什么。</span></span></span><span class=\"qz-hint\">Hoa quả trong siêu thị cực nhiều, muốn ăn gì có nấy. — Hoa quả trong siêu thị nhiều lắm, muốn ăn gì có nấy.</span>","answer":["超市里的水果多得很"],"explain":"超市里的水果多得很，想吃什么有什么。 (Chāoshì li de shuǐguǒ duō de hěn, xiǎng chī shénme yǒu shénme.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我好多天没看见他了，他这个月非常忙。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我好多天没看见他了，____。</span></span></span><span class=\"qz-hint\">Bao nhiêu ngày rồi mình không gặp anh ấy, tháng này anh ấy vô cùng bận. — Bao nhiêu ngày rồi mình không gặp anh ấy, tháng này anh ấy bận lắm.</span>","answer":["他这个月忙得很","这个月他忙得很"],"explain":"我好多天没看见他了，他这个月忙得很。 (Wǒ hǎo duō tiān méi kànjiàn tā le, tā zhège yuè máng de hěn.)"}]},{"title":"Lặp lượng từ: 张张 / 个个 / 天天 + 都","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>(名词)</b><small>phạm vi</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>量词 + 量词</b><small>LT lặp AA</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>都</b><small>đều</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>……</b><small>đặc điểm</small></span></div>","summary":"<p class=\"gr-lead\">Cái nào cũng …</p><ul><li>Lượng từ lặp <b>AA</b> = \"mỗi … đều\", nhấn mạnh <b>tất cả</b> thành viên trong phạm vi có cùng đặc điểm; phía sau thường có <span class=\"zh\">都</span>.</li><li>Danh từ thời gian đơn âm cũng lặp được: <span class=\"zh\">天天 · 年年</span> (= 每天 · 每年).</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">量词重叠</span> · AA = 每 + LT</h4><p>Mỗi … đều …</p><div class=\"gr-formula\"><div class=\"fx-lbl\">张张 = 每张</div><div class=\"fx-row\"><span class=\"fx-p\"><b>这些照片</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>张张</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>都</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>非常好看</b></span></div><div class=\"fx-ex zh\">这些照片张张都非常好看。</div><div class=\"fx-lbl\">个个 = 每个</div><div class=\"fx-row\"><span class=\"fx-p\"><b>这些苹果</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>个个</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>都</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>很大</b></span></div><div class=\"fx-ex zh\">这些苹果个个都很大。</div><div class=\"fx-lbl\">件件 = 每件</div><div class=\"fx-row\"><span class=\"fx-p\"><b>她的衣服</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>件件</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>都</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>很漂亮</b></span></div><div class=\"fx-ex zh\">她的衣服件件都很漂亮。</div><div class=\"fx-lbl\">天天 = 每天</div><div class=\"fx-row\"><span class=\"fx-p\"><b>想出去拍照，但是</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>天天</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>下雨</b></span></div><div class=\"fx-ex zh\">我想出去拍照，但是天天下雨。</div></div><p class=\"gr-key\"><span class=\"zh\">天天 · 年年</span> vốn là danh từ thời gian nhưng lặp như lượng từ　·　<span class=\"zh\">都</span> thường có, đôi khi lược</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">这些照片张张都非常好看。</span> = <span class=\"zh\">每张照片都非常好看。</span> = Tấm nào cũng rất đẹp.</p>","note":"<b>Lưu ý:</b> Dạng lặp đứng trước vị ngữ, không làm tân ngữ: ✗ <span class=\"zh\">我喜欢张张照片</span> → ✓ <span class=\"zh\">这些照片我张张都喜欢</span>","examples":[{"zh":"这些照片张张都非常好看。","py":"Zhèxiē zhàopiàn zhāngzhāng dōu fēicháng hǎokàn.","vi":"Những tấm ảnh này tấm nào cũng rất đẹp."},{"zh":"这些苹果个个都很大。","py":"Zhèxiē píngguǒ gègè dōu hěn dà.","vi":"Mấy quả táo này quả nào cũng to."},{"zh":"我想出去拍照，但是天天下雨。","py":"Wǒ xiǎng chūqu pāizhào, dànshì tiāntiān xià yǔ.","vi":"Mình muốn ra ngoài chụp ảnh, nhưng ngày nào cũng mưa."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你喜欢哪个菜？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____。（个）</span></span></span><span class=\"qz-hint\">Bạn thích món nào? — Mấy món này món nào cũng ngon.</span>","answer":["这些菜个个都很好吃","个个都很好吃","这些菜个个都好吃","个个都好吃"],"explain":"这些菜个个都很好吃。（个） (Zhèxiē cài gègè dōu hěn hǎochī. (gè))"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你觉得这些衣服怎么样？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____。（件）</span></span></span><span class=\"qz-hint\">Bạn thấy mấy bộ quần áo này thế nào? — Chiếc nào cũng đẹp.</span>","answer":["件件都很漂亮","件件都漂亮","件件都很好看","件件都好看"],"explain":"件件都很漂亮。（件） (Jiànjiàn dōu hěn piàoliang. (jiàn))"}]},{"title":"Câu tồn hiện (3): 处所 + 动词 + 补语 + 数量 + 人/物","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>处所</b><small>nơi chốn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>趋向 / 结果补语</b><small>BN xu hướng / KQ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(了)</b><small>đã</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>数量 + 人/物</b><small>số lượng + người/vật</small></span></div>","summary":"<p class=\"gr-lead\">Xuất hiện · biến mất</p><ul><li>Đầu câu là <b>nơi chốn</b>; người / vật xuất hiện hay biến mất đứng <b>cuối câu</b>, thường có <b>số lượng</b> đi kèm.</li><li>Người / vật cuối câu là thông tin <b>mới, chưa xác định</b> → không dùng 这 / 那.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">存现句 (3)</span> · Xuất hiện · Biến mất</h4><p>Nơi chốn đầu câu</p><div class=\"gr-formula\"><div class=\"fx-lbl\">đi ngang · 过去</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>后边</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>走过去</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>两个人</b></span></div><div class=\"fx-ex zh\">后边走过去两个人。</div><div class=\"fx-lbl\">xuất hiện · 下来</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>楼上</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>下来了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>几个人</b></span></div><div class=\"fx-ex zh\">楼上下来了几个人。</div><div class=\"fx-lbl\">xuất hiện · 来</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>树上</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>飞来了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>几只鸟</b></span></div><div class=\"fx-ex zh\">树上飞来了几只鸟。</div><div class=\"fx-lbl\">biến mất · 走</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>我们小区</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>搬走了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>两家人</b></span></div><div class=\"fx-ex zh\">我们小区搬走了两家人。</div></div><p class=\"gr-key\">BN xu hướng <span class=\"zh\">来 · 过来 · 下来 · 进来</span> → xuất hiện　·　BN kết quả <span class=\"zh\">走</span> → biến mất</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">后边走过去两个人。</span> = Phía sau có hai người đi qua.</p>","note":"<b>Lưu ý:</b> Đầu câu không thêm 在: ✗ <span class=\"zh\">在后边走过去两个人</span> → ✓ <span class=\"zh\">后边走过去两个人</span>","examples":[{"zh":"后边走过去两个人。","py":"Hòubian zǒu guòqu liǎng ge rén.","vi":"Phía sau có hai người đi qua."},{"zh":"前面开过来很多车。","py":"Qiánmiàn kāi guòlai hěn duō chē.","vi":"Phía trước có rất nhiều xe chạy tới."},{"zh":"楼上下来了几个人。","py":"Lóu shang xiàlaile jǐ ge rén.","vi":"Trên lầu có mấy người đi xuống."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">教室里____。</span><span class=\"qz-hint\">Trong lớp có một thầy giáo đi vào.</span>","answer":["走进来一位老师","走进来一个老师","走进来了一位老师"],"explain":"教室里走进来一位老师。 (Jiàoshì li zǒu jìnlai yí wèi lǎoshī.)"},{"type":"fill","q":"<span class=\"zh\">____一个人。</span><span class=\"qz-hint\">Phía trước có một người đi lại.</span>","answer":["前面走过来","前边走过来","前面走来"],"explain":"前面走过来一个人。 (Qiánmiàn zǒu guòlai yí ge rén.)"},{"type":"fillm","q":"<span class=\"zh\">{{0}}飞过来{{1}}。</span><span class=\"qz-hint\">Trên trời có mấy con chim bay lại.</span>","blanks":[["天上"],["几只鸟","一只鸟","两只鸟","几只小鸟"]],"explain":"天上飞过来几只鸟。 (Tiānshang fēi guòlai jǐ zhī niǎo.)"}]},{"title":"Câu phức rút gọn: 动词₁ + 了 …… 就 + 动词₂","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>动词₁ + 了</b><small>làm xong việc 1</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b><small>tân ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b><small>là … ngay</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词₂ ……</b><small>việc 2</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>(了)</b><small>đã xong</small></span></div>","summary":"<p class=\"gr-lead\">… xong là … ngay</p><ul><li>Hành động 2 xảy ra <b>ngay sau</b> hành động 1: <span class=\"zh\">了</span> đứng sau ĐT₁, <span class=\"zh\">就</span> đứng trước ĐT₂.</li><li>Việc 2 <b>đã xong</b> → thêm <span class=\"zh\">了</span> cuối câu: <span class=\"zh\">昨天我们下了课就回家了</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">……了……就……</span> · Có 了 cuối câu không?</h4><p>Chưa xảy ra ↔ đã xảy ra</p><div class=\"gr-formula\"><div class=\"fx-lbl\">sắp làm · không 了</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>听完了音乐会</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>来我家吃饭</b></span></div><div class=\"fx-ex zh\">你听完了音乐会就来我家吃饭。</div><div class=\"fx-lbl\">thói quen · không 了</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>每天下了班</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>去锻炼身体</b></span></div><div class=\"fx-ex zh\">他每天下了班就去锻炼身体。</div><div class=\"fx-lbl\">đã xong · 了 cuối</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>吃了早饭</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>去学校了</b></span></div><div class=\"fx-ex zh\">我吃了早饭就去学校了。</div><div class=\"fx-lbl\">đã xong · 了 cuối</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>下了课</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>回家了</b></span></div><div class=\"fx-ex zh\">昨天我们下了课就回家了。</div></div><p class=\"gr-key\">Chưa xảy ra / thói quen → <b>không</b> có 了 cuối câu　·　Đã xảy ra → <span class=\"zh\">……了……就……了</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我吃了早饭就去学校了。</span> = Mình ăn sáng xong là đi học luôn.</p>","note":"<b>Lưu ý:</b> Việc chưa xảy ra không thêm 了 cuối câu: ✗ <span class=\"zh\">明天我下了课就去找你了</span> → ✓ <span class=\"zh\">明天我下了课就去找你</span>","examples":[{"zh":"你听完了音乐会就来我家吃饭。","py":"Nǐ tīngwánle yīnyuèhuì jiù lái wǒ jiā chīfàn.","vi":"Bạn nghe hoà nhạc xong thì đến nhà mình ăn cơm."},{"zh":"我吃了早饭就去学校了。","py":"Wǒ chīle zǎofàn jiù qù xuéxiào le.","vi":"Mình ăn sáng xong là đi học luôn."},{"zh":"昨天我们下了课就回家了。","py":"Zuótiān wǒmen xiàle kè jiù huí jiā le.","vi":"Hôm qua tan học là bọn mình về nhà luôn."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">爸爸每次上了飞机就____。</span><span class=\"qz-hint\">Lần nào bố lên máy bay xong là ngủ luôn.</span>","answer":["睡觉","睡觉了"],"explain":"爸爸每次上了飞机就睡觉。 (Bàba měi cì shàngle fēijī jiù shuìjiào.)"},{"type":"fill","q":"<span class=\"zh\">今天我没吃早饭，所以下了课就____。</span><span class=\"qz-hint\">Hôm nay mình chưa ăn sáng nên tan học là đi ăn luôn.</span>","answer":["去吃饭了","去吃饭"],"explain":"今天我没吃早饭，所以下了课就去吃饭了。 (Jīntiān wǒ méi chī zǎofàn, suǒyǐ xiàle kè jiù qù chīfàn le.)"},{"type":"fill","q":"<span class=\"zh\">我今天有点儿不舒服，____。</span><span class=\"qz-hint\">Hôm nay mình hơi mệt, tan làm là về nhà nghỉ luôn.</span>","answer":["下了班就回家休息","下了班就回家","我下了班就回家休息"],"explain":"我今天有点儿不舒服，下了班就回家休息。 (Wǒ jīntiān yǒudiǎnr bù shūfu, xiàle bān jiù huí jiā xiūxi.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在街上","titleVi":"Trên phố — vừa đi dạo vừa trò chuyện","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"这个星期总是阴天，今天终于晴了。","py":"Zhège xīngqī zǒngshì yīntiān, jīntiān zhōngyú qíng le.","vi":"Tuần này toàn trời âm u, hôm nay cuối cùng cũng nắng rồi."},{"speaker":"文","name":"Lý Văn","zh":"现在天气好得很！我们去爬山怎么样？","py":"Xiànzài tiānqì hǎo de hěn! Wǒmen qù pá shān zěnmeyàng?","vi":"Bây giờ thời tiết đẹp lắm! Mình đi leo núi nhé?"},{"speaker":"月","name":"Gia Nguyệt","zh":"好啊！又能锻炼身体，又能照好看的照片。","py":"Hǎo a! Yòu néng duànliàn shēntǐ, yòu néng zhào hǎokàn de zhàopiàn.","vi":"Hay đấy! Vừa rèn luyện sức khoẻ, vừa chụp được ảnh đẹp."},{"speaker":"文","name":"Lý Văn","zh":"那我带点儿水和吃的，咱们现在就去？","py":"Nà wǒ dài diǎnr shuǐ hé chī de, zánmen xiànzài jiù qù?","vi":"Vậy anh mang ít nước và đồ ăn, mình đi luôn bây giờ nhé?"},{"speaker":"月","name":"Gia Nguyệt","zh":"我回去穿上运动鞋，拿上大衣。要不要叫一雪姐一起去？","py":"Wǒ huíqu chuānshang yùndòngxié, náshang dàyī. Yào bu yào jiào Yīxuě jiě yìqǐ qù?","vi":"Em về đi giày thể thao, lấy áo khoác. Có rủ chị Nhất Tuyết đi cùng không?"},{"speaker":"文","name":"Lý Văn","zh":"好主意。给她打个电话吧。","py":"Hǎo zhǔyi. Gěi tā dǎ ge diànhuà ba.","vi":"Ý hay đấy. Gọi điện cho chị ấy đi."}]},{"titleZh":"课文二 · 在出租车上","titleVi":"Trên taxi — cùng xem ảnh","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"这些照片是谁给您照的？张张都非常好看。","py":"Zhèxiē zhàopiàn shì shéi gěi nín zhào de? Zhāngzhāng dōu fēicháng hǎokàn.","vi":"Những tấm ảnh này ai chụp cho chị vậy? Tấm nào cũng rất đẹp."},{"speaker":"雪","name":"Nhất Tuyết","zh":"一飞。她对拍照一直很感兴趣，经常给我照相。","py":"Yīfēi. Tā duì pāizhào yìzhí hěn gǎn xìngqù, jīngcháng gěi wǒ zhàoxiàng.","vi":"Nhất Phi đấy. Em ấy luôn rất thích chụp ảnh, hay chụp cho chị lắm."},{"speaker":"月","name":"Gia Nguyệt","zh":"我喜欢您大笑的这张，看起来很漂亮。","py":"Wǒ xǐhuan nín dà xiào de zhè zhāng, kàn qǐlai hěn piàoliang.","vi":"Em thích tấm chị cười tươi này, trông rất đẹp."},{"speaker":"雪","name":"Nhất Tuyết","zh":"我觉得这张有点儿难看，那时候我不知道她在给我照相。","py":"Wǒ juéde zhè zhāng yǒudiǎnr nánkàn, nà shíhou wǒ bù zhīdào tā zài gěi wǒ zhàoxiàng.","vi":"Chị thấy tấm này hơi xấu, lúc đó chị không biết em ấy đang chụp mình."},{"speaker":"月","name":"Gia Nguyệt","zh":"这样的照片才好看。我也喜欢拍照，爬山的时候我给您照几张照片吧。","py":"Zhèyàng de zhàopiàn cái hǎokàn. Wǒ yě xǐhuan pāizhào, pá shān de shíhou wǒ gěi nín zhào jǐ zhāng zhàopiàn ba.","vi":"Ảnh như thế này mới đẹp chứ. Em cũng thích chụp ảnh, lúc leo núi em chụp cho chị mấy tấm nhé."},{"speaker":"雪","name":"Nhất Tuyết","zh":"好，我可以比较一下你们两个谁的水平高。","py":"Hǎo, wǒ kěyǐ bǐjiào yíxià nǐmen liǎng ge shéi de shuǐpíng gāo.","vi":"Được, chị có thể so xem hai đứa ai chụp giỏi hơn."}]},{"titleZh":"课文三 · 在山上","titleVi":"Trên núi — chụp ảnh giữa hàng cây","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"家月，这里挺漂亮的，咱们在这里拍照吧。","py":"Jiāyuè, zhèli tǐng piàoliang de, zánmen zài zhèli pāizhào ba.","vi":"Gia Nguyệt, chỗ này đẹp đấy, mình chụp ảnh ở đây đi."},{"speaker":"月","name":"Gia Nguyệt","zh":"这边没有太阳，咱们去那边吧。","py":"Zhèbiān méiyǒu tàiyáng, zánmen qù nàbiān ba.","vi":"Bên này không có nắng, mình sang bên kia đi chị."},{"speaker":"雪","name":"Nhất Tuyết","zh":"好。你觉得我站在这些树中间怎么样？","py":"Hǎo. Nǐ juéde wǒ zhàn zài zhèxiē shù zhōngjiān zěnmeyàng?","vi":"Ừ. Em thấy chị đứng giữa mấy cái cây này thế nào?"},{"speaker":"月","name":"Gia Nguyệt","zh":"挺好的。等一下，后边走过去两个人。","py":"Tǐng hǎo de. Děng yíxià, hòubian zǒu guòqu liǎng ge rén.","vi":"Đẹp đấy ạ. Chờ chút, phía sau có hai người đi qua."},{"speaker":"雪","name":"Nhất Tuyết","zh":"我准备好了，你照的时候告诉我。","py":"Wǒ zhǔnbèi hǎo le, nǐ zhào de shíhou gàosu wǒ.","vi":"Chị chuẩn bị xong rồi, lúc nào chụp thì báo chị nhé."},{"speaker":"月","name":"Gia Nguyệt","zh":"你不用看着我，想干什么都可以。","py":"Nǐ búyòng kànzhe wǒ, xiǎng gàn shénme dōu kěyǐ.","vi":"Chị không cần nhìn em đâu, muốn làm gì cũng được."},{"speaker":"雪","name":"Nhất Tuyết","zh":"树上飞来了几只鸟，我就看它们吧。","py":"Shù shang fēiláile jǐ zhī niǎo, wǒ jiù kàn tāmen ba.","vi":"Trên cây có mấy con chim bay đến, vậy chị nhìn chúng nhé."},{"speaker":"月","name":"Gia Nguyệt","zh":"啊，手机没电了。","py":"À, shǒujī méi diàn le.","vi":"Á, điện thoại hết pin rồi."}]},{"titleZh":"课文四 · 在咖啡厅里","titleVi":"Quán cà phê — Nhất Tuyết nhắn tin","para":true,"speaker":"雪","lines":[{"zh":"家月，我收到了你的那封邮件，也看到了你给我照的照片，张张都很漂亮。","py":"Jiāyuè, wǒ shōudàole nǐ de nà fēng yóujiàn, yě kàndàole nǐ gěi wǒ zhào de zhàopiàn, zhāngzhāng dōu hěn piàoliang.","vi":"Gia Nguyệt, chị nhận được email của em rồi, cũng xem những tấm ảnh em chụp cho chị, tấm nào cũng rất đẹp."},{"zh":"我已经告诉了一飞，你的拍照水平比她高，她难过得很，哈哈。","py":"Wǒ yǐjīng gàosule Yīfēi, nǐ de pāizhào shuǐpíng bǐ tā gāo, tā nánguò de hěn, hāhā.","vi":"Chị đã nói với Nhất Phi rằng em chụp ảnh giỏi hơn em ấy, em ấy buồn lắm, ha ha."},{"zh":"不知道你对中国的音乐有没有兴趣？","py":"Bù zhīdào nǐ duì Zhōngguó de yīnyuè yǒu méiyǒu xìngqù?","vi":"Không biết em có hứng thú với âm nhạc Trung Quốc không?"},{"zh":"我送你一张明天下午音乐会的门票。","py":"Wǒ sòng nǐ yì zhāng míngtiān xiàwǔ yīnyuèhuì de ménpiào.","vi":"Chị tặng em một vé buổi hoà nhạc chiều mai."},{"zh":"音乐会七点多结束，你听完了音乐会就来我家吃饭，尝尝我做的中国菜。","py":"Yīnyuèhuì qī diǎn duō jiéshù, nǐ tīngwánle yīnyuèhuì jiù lái wǒ jiā chīfàn, chángchang wǒ zuò de Zhōngguócài.","vi":"Buổi hoà nhạc hơn bảy giờ kết thúc, em nghe xong thì đến nhà chị ăn cơm, nếm thử món Trung Quốc chị nấu nhé."},{"zh":"你觉得怎么样？","py":"Nǐ juéde zěnmeyàng?","vi":"Em thấy thế nào?"}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Sở thích của bạn","q":{"zh":"两人一组，互相问答，介绍自己的兴趣爱好。","py":"Liǎng rén yì zǔ, hùxiāng wèndá, jièshào zìjǐ de xìngqù àihào.","vi":"Theo cặp hỏi đáp: giới thiệu sở thích của mình và nói lý do."},"items":[{"zh":"你对拍照感兴趣吗？为什么？","py":"Nǐ duì pāizhào gǎn xìngqù ma? Wèi shénme?","vi":"Bạn có hứng thú với chụp ảnh không? Vì sao?"},{"zh":"天气好的时候，你会去爬山吗？为什么？","py":"Tiānqì hǎo de shíhou, nǐ huì qù pá shān ma? Wèi shénme?","vi":"Lúc trời đẹp, bạn có đi leo núi không? Vì sao?"},{"zh":"你喜欢听什么样的音乐？为什么？","py":"Nǐ xǐhuan tīng shénme yàng de yīnyuè? Wèi shénme?","vi":"Bạn thích nghe loại nhạc nào? Vì sao?"},{"zh":"你最近做的有意思的事情是什么？","py":"Nǐ zuìjìn zuò de yǒu yìsi de shìqing shì shénme?","vi":"Việc thú vị bạn làm gần đây là gì?"}]}],"speak":[]}},{"id":"k3v3-b06","courseId":"k3v3","order":6,"title":"Trên tàu cao tốc còn gọi được đồ ăn","titleZh":"高铁上还可以点外卖","titlePy":"gāotiě shang hái kěyǐ diǎn wàimài","vocab":[{"stt":1,"hanzi":"该","pinyin":"gāi","hanviet":"Cai","pos":"Trợ động từ","meaning":"nên, phải; đến lúc","comps":"该走了 (đến lúc đi rồi), 该你了 (đến lượt bạn)","example":{"zh":"不早了，我该回家了。","py":"Bù zǎo le, wǒ gāi huí jiā le.","vi":"Muộn rồi, mình phải về nhà thôi."}},{"stt":2,"hanzi":"打算","pinyin":"dǎsuàn","hanviet":"Đả toán","pos":"Động từ / Danh từ","meaning":"dự định, định; kế hoạch","comps":"打算去旅游 (định đi du lịch), 你的打算 (dự định của bạn)","example":{"zh":"这个周末你有什么打算？","py":"Zhège zhōumò nǐ yǒu shénme dǎsuàn?","vi":"Cuối tuần này bạn có dự định gì?"}},{"stt":3,"hanzi":"高铁","pinyin":"gāotiě","hanviet":"Cao thiết","pos":"Danh từ","meaning":"tàu cao tốc","comps":"坐高铁 (đi tàu cao tốc), 高铁站 (ga tàu cao tốc)","example":{"zh":"从北京坐高铁去上海只要四个多小时。","py":"Cóng Běijīng zuò gāotiě qù Shànghǎi zhǐ yào sì ge duō xiǎoshí.","vi":"Đi tàu cao tốc từ Bắc Kinh đến Thượng Hải chỉ hơn bốn tiếng."}},{"stt":4,"hanzi":"行","pinyin":"xíng","hanviet":"Hành","pos":"Động từ / Tính từ","meaning":"được, ổn; giỏi","comps":"行吗 (được không), 你真行 (bạn giỏi thật)","example":{"zh":"明天下午三点见，行吗？","py":"Míngtiān xiàwǔ sān diǎn jiàn, xíng ma?","vi":"Ba giờ chiều mai gặp nhé, được không?"}},{"stt":5,"hanzi":"路口","pinyin":"lùkǒu","hanviet":"Lộ khẩu","pos":"Danh từ","meaning":"ngã tư, giao lộ","comps":"十字路口 (ngã tư), 前面的路口 (ngã tư phía trước)","example":{"zh":"我在路口等你。","py":"Wǒ zài lùkǒu děng nǐ.","vi":"Mình đợi bạn ở ngã tư."}},{"stt":6,"hanzi":"小心","pinyin":"xiǎoxīn","hanviet":"Tiểu tâm","pos":"Động từ / Tính từ","meaning":"cẩn thận; coi chừng","comps":"小心点儿 (cẩn thận chút), 小心车 (coi chừng xe)","example":{"zh":"下雨了，路上小心点儿。","py":"Xià yǔ le, lù shang xiǎoxīn diǎnr.","vi":"Trời mưa rồi, đi đường cẩn thận nhé."}},{"stt":7,"hanzi":"迟到","pinyin":"chídào","hanviet":"Trì đáo","pos":"Động từ","meaning":"đến muộn","comps":"上课迟到 (đi học muộn), 别迟到 (đừng đến muộn)","example":{"zh":"明天八点上课，别迟到。","py":"Míngtiān bā diǎn shàngkè, bié chídào.","vi":"Mai tám giờ vào học, đừng đến muộn nhé."}},{"stt":8,"hanzi":"红绿灯","pinyin":"hóng-lǜdēng","hanviet":"Hồng lục đăng","pos":"Danh từ","meaning":"đèn giao thông","comps":"过红绿灯 (qua đèn giao thông), 红绿灯路口 (ngã tư có đèn)","example":{"zh":"过了红绿灯就是我们学校。","py":"Guòle hóng-lǜdēng jiù shì wǒmen xuéxiào.","vi":"Qua đèn giao thông là đến trường mình."}},{"stt":9,"hanzi":"后来","pinyin":"hòulái","hanviet":"Hậu lai","pos":"Danh từ","meaning":"sau đó, về sau","comps":"后来呢 (sau đó thì sao), 后来才知道 (về sau mới biết)","example":{"zh":"我们以前是同学，后来就不常见面了。","py":"Wǒmen yǐqián shì tóngxué, hòulái jiù bù cháng jiànmiàn le.","vi":"Trước đây bọn mình là bạn học, về sau thì ít gặp nhau."}},{"stt":10,"hanzi":"急","pinyin":"jí","hanviet":"Cấp","pos":"Tính từ / Động từ","meaning":"gấp; sốt ruột, vội","comps":"很急 (rất gấp), 别急 (đừng vội)","example":{"zh":"别急，我们还有时间。","py":"Bié jí, wǒmen hái yǒu shíjiān.","vi":"Đừng vội, chúng ta vẫn còn thời gian."}},{"stt":11,"hanzi":"如果","pinyin":"rúguǒ","hanviet":"Như quả","pos":"Liên từ","meaning":"nếu","comps":"如果……就…… (nếu … thì …), 如果下雨 (nếu trời mưa)","example":{"zh":"如果你不舒服，就在家休息吧。","py":"Rúguǒ nǐ bù shūfu, jiù zài jiā xiūxi ba.","vi":"Nếu bạn không khoẻ thì ở nhà nghỉ đi."}},{"stt":12,"hanzi":"以前","pinyin":"yǐqián","hanviet":"Dĩ tiền","pos":"Danh từ","meaning":"trước đây; trước (khi)","comps":"两年以前 (hai năm trước), 睡觉以前 (trước khi ngủ)","example":{"zh":"我以前没坐过高铁。","py":"Wǒ yǐqián méi zuòguo gāotiě.","vi":"Trước đây mình chưa đi tàu cao tốc bao giờ."}},{"stt":13,"hanzi":"耳机","pinyin":"ěrjī","hanviet":"Nhĩ cơ","pos":"Danh từ","meaning":"tai nghe","comps":"戴耳机 (đeo tai nghe), 耳机没电了 (tai nghe hết pin)","example":{"zh":"在图书馆听音乐要用耳机。","py":"Zài túshūguǎn tīng yīnyuè yào yòng ěrjī.","vi":"Nghe nhạc trong thư viện phải dùng tai nghe."}},{"stt":14,"hanzi":"充电宝","pinyin":"chōngdiànbǎo","hanviet":"Sung điện bảo","pos":"Danh từ","meaning":"sạc dự phòng","comps":"带充电宝 (mang sạc dự phòng), 借充电宝 (mượn sạc dự phòng)","example":{"zh":"出门的时候别忘了带充电宝。","py":"Chūmén de shíhou bié wàngle dài chōngdiànbǎo.","vi":"Lúc ra ngoài đừng quên mang sạc dự phòng."}},{"stt":15,"hanzi":"常用","pinyin":"cháng yòng","hanviet":"Thường dụng","pos":"Cụm từ","meaning":"thường dùng, hay dùng","comps":"常用的东西 (đồ hay dùng), 常用词 (từ thường dùng)","example":{"zh":"这是我最常用的手机App。","py":"Zhè shì wǒ zuì cháng yòng de shǒujī App.","vi":"Đây là App điện thoại mình hay dùng nhất."}},{"stt":16,"hanzi":"越","pinyin":"yuè","hanviet":"Việt","pos":"Phó từ","meaning":"càng","comps":"越来越 (ngày càng), 越……越…… (càng … càng …)","example":{"zh":"他的汉语越来越好了。","py":"Tā de Hànyǔ yuè lái yuè hǎo le.","vi":"Tiếng Trung của anh ấy ngày càng giỏi."}},{"stt":17,"hanzi":"分开","pinyin":"fēnkāi","hanviet":"Phân khai","pos":"Động từ","meaning":"tách ra, chia ra","comps":"分开走 (tách ra đi riêng), 分开放 (để riêng)","example":{"zh":"这两种水果要分开放。","py":"Zhè liǎng zhǒng shuǐguǒ yào fēnkāi fàng.","vi":"Hai loại hoa quả này phải để riêng."}},{"stt":18,"hanzi":"检查","pinyin":"jiǎnchá","hanviet":"Kiểm tra","pos":"Động từ","meaning":"kiểm tra","comps":"检查身体 (khám sức khoẻ), 检查一下 (kiểm tra thử)","example":{"zh":"考试的时候，写完了要检查一下。","py":"Kǎoshì de shíhou, xiěwánle yào jiǎnchá yíxià.","vi":"Lúc thi, viết xong phải kiểm tra lại."}},{"stt":19,"hanzi":"刷","pinyin":"shuā","hanviet":"Loát","pos":"Động từ","meaning":"quẹt, quét (thẻ, mã)","comps":"刷卡 (quẹt thẻ), 刷护照 (quẹt hộ chiếu)","example":{"zh":"在这里买东西可以刷卡。","py":"Zài zhèli mǎi dōngxi kěyǐ shuā kǎ.","vi":"Mua đồ ở đây có thể quẹt thẻ."}},{"stt":20,"hanzi":"检票","pinyin":"jiǎnpiào","hanviet":"Kiểm phiếu","pos":"Động từ","meaning":"soát vé","comps":"检票口 (cửa soát vé), 开始检票 (bắt đầu soát vé)","example":{"zh":"火车马上就要开始检票了。","py":"Huǒchē mǎshàng jiù yào kāishǐ jiǎnpiào le.","vi":"Tàu hoả sắp bắt đầu soát vé rồi."}},{"stt":21,"hanzi":"电梯","pinyin":"diàntī","hanviet":"Điện thê","pos":"Danh từ","meaning":"thang máy, thang cuốn","comps":"坐电梯 (đi thang máy), 电梯坏了 (thang máy hỏng)","example":{"zh":"我家在十层，每天坐电梯上下楼。","py":"Wǒ jiā zài shí céng, měi tiān zuò diàntī shàngxià lóu.","vi":"Nhà mình ở tầng mười, ngày nào cũng đi thang máy lên xuống."}},{"stt":22,"hanzi":"放假","pinyin":"fàngjià","hanviet":"Phóng giá","pos":"Động từ (li hợp)","meaning":"được nghỉ (lễ, phép)","comps":"放假了 (được nghỉ rồi), 放三天假 (nghỉ ba ngày)","example":{"zh":"放假的时候你打算去哪儿玩？","py":"Fàngjià de shíhou nǐ dǎsuàn qù nǎr wán?","vi":"Lúc được nghỉ bạn định đi đâu chơi?"}},{"stt":23,"hanzi":"沙发","pinyin":"shāfā","hanviet":"Sa phát","pos":"Danh từ","meaning":"ghế sofa","comps":"坐在沙发上 (ngồi trên sofa), 新沙发 (sofa mới)","example":{"zh":"爸爸喜欢坐在沙发上看电视。","py":"Bàba xǐhuan zuò zài shāfā shang kàn diànshì.","vi":"Bố thích ngồi trên sofa xem tivi."}},{"stt":24,"hanzi":"安静","pinyin":"ānjìng","hanviet":"An tĩnh","pos":"Tính từ","meaning":"yên tĩnh","comps":"很安静 (rất yên tĩnh), 安静点儿 (trật tự chút)","example":{"zh":"图书馆里很安静。","py":"Túshūguǎn li hěn ānjìng.","vi":"Trong thư viện rất yên tĩnh."}},{"stt":25,"hanzi":"选择","pinyin":"xuǎnzé","hanviet":"Tuyển trạch","pos":"Động từ","meaning":"lựa chọn","comps":"选择题 (câu trắc nghiệm), 选择好 (chọn xong)","example":{"zh":"这两件衣服都很好看，我不知道选择哪件。","py":"Zhè liǎng jiàn yīfu dōu hěn hǎokàn, wǒ bù zhīdào xuǎnzé nǎ jiàn.","vi":"Hai chiếc áo đều đẹp, mình không biết chọn chiếc nào."}},{"stt":26,"hanzi":"必须","pinyin":"bìxū","hanviet":"Tất tu","pos":"Phó từ","meaning":"phải, bắt buộc","comps":"必须去 (bắt buộc phải đi), 必须带护照 (phải mang hộ chiếu)","example":{"zh":"去国外旅游必须带护照。","py":"Qù guówài lǚyóu bìxū dài hùzhào.","vi":"Đi du lịch nước ngoài bắt buộc phải mang hộ chiếu."}},{"stt":27,"hanzi":"北京南站","pinyin":"Běijīng Nán Zhàn","hanviet":"Bắc Kinh Nam Trạm","pos":"Danh từ riêng","meaning":"Ga Nam Bắc Kinh","comps":"去北京南站 (đến ga Nam Bắc Kinh), 北京站 (ga Bắc Kinh)","example":{"zh":"北京南站有很多去上海的高铁。","py":"Běijīng Nán Zhàn yǒu hěn duō qù Shànghǎi de gāotiě.","vi":"Ga Nam Bắc Kinh có rất nhiều tàu cao tốc đi Thượng Hải."}}],"hanzi":[{"char":"该","pinyin":"gāi","hanviet":"Cai","chars":["该"],"story":"该 = 讠 (lời nói) + 亥 hài chỉ âm → điều lời nói đã định sẵn → nên, phải. 该……了 = đã đến lúc phải làm gì rồi; 该你了 = đến lượt bạn."},{"char":"打算","pinyin":"dǎsuàn","hanviet":"Đả toán","chars":["打","算"],"story":"打 = 扌 (tay) + 丁 → ra tay làm. 算 = ⺮ (que tre) + 目 + 廾 (hai tay) → cầm que tre mà tính. 打算 = tính toán trước → dự định; cũng là danh từ: 你有什么打算？"},{"char":"高铁","pinyin":"gāotiě","hanviet":"Cao thiết","chars":["高","铁"],"story":"高 vẽ toà lầu cao → cao. 铁 = 钅 (kim loại) + 失 → sắt. 高铁 là cách gọi tắt của 高速铁路 (đường sắt cao tốc) → tàu cao tốc."},{"char":"行","pinyin":"xíng","hanviet":"Hành","chars":["行"],"story":"行 vẽ ngã tư đường → đi. Đi được → được, ổn: 行吗？ / 行！; làm được việc → giỏi: 你真行. Đọc háng là hàng, dãy: 银行."},{"char":"路口","pinyin":"lùkǒu","hanviet":"Lộ khẩu","chars":["路","口"],"story":"路 = 足 (chân) + 各 → đường chân đi. 口 = miệng, cửa. 路口 = miệng đường, chỗ các con đường gặp nhau → ngã tư, giao lộ."},{"char":"小心","pinyin":"xiǎoxīn","hanviet":"Tiểu tâm","chars":["小","心"],"story":"小 = nhỏ. 心 = tim, lòng. 小心 = để tâm cả vào chỗ nhỏ nhất → cẩn thận. Đứng trước danh từ = coi chừng: 小心车！"},{"char":"迟到","pinyin":"chídào","hanviet":"Trì đáo","chars":["迟","到"],"story":"迟 = 辶 (bước đi) + 尺 → đi chậm → muộn, trễ. 到 = đến. 迟到 = đến muộn. Trái nghĩa: 早到 (đến sớm)."},{"char":"红绿灯","pinyin":"hóng-lǜdēng","hanviet":"Hồng lục đăng","chars":["红","绿","灯"],"story":"红 = đỏ, 绿 = xanh lá — cùng bộ 纟 (sợi tơ) vì là màu nhuộm vải. 灯 = 火 (lửa) + 丁 → đèn. 红绿灯 = đèn đỏ đèn xanh → đèn giao thông."},{"char":"后来","pinyin":"hòulái","hanviet":"Hậu lai","chars":["后","来"],"story":"后 = sau. 来 = đến. 后来 = phần đến sau → sau đó, về sau. Chỉ kể chuyện đã qua; nói tương lai dùng 以后."},{"char":"急","pinyin":"jí","hanviet":"Cấp","chars":["急"],"story":"急 = 刍 (người đang đuổi theo) + 心 (tim) → lòng như bị đuổi gấp → vội, sốt ruột, gấp. 着急 ở bài 1 cũng có chữ 急."},{"char":"如果","pinyin":"rúguǒ","hanviet":"Như quả","chars":["如","果"],"story":"如 = 女 + 口 → làm theo như lời → như. 果 vẽ quả trên cây → quả, kết quả. 如果 = giả như … thì sẽ ra kết quả → nếu; hay đi với 就."},{"char":"以前","pinyin":"yǐqián","hanviet":"Dĩ tiền","chars":["以","前"],"story":"以 = lấy làm mốc. 前 = trước. 以前 = tính từ mốc trở về trước → trước đây; đứng sau mốc: 两年以前, 睡觉以前."},{"char":"耳机","pinyin":"ěrjī","hanviet":"Nhĩ cơ","chars":["耳","机"],"story":"耳 vẽ cái tai → tai. 机 = 木 + 几 → máy móc. 耳机 = cái máy nhỏ đeo ở tai → tai nghe."},{"char":"充电宝","pinyin":"chōngdiànbǎo","hanviet":"Sung điện bảo","chars":["充","电","宝"],"story":"充 = làm đầy, nạp. 电 = điện. 宝 = 宀 (mái nhà) + 玉 (ngọc) → của quý. 充电宝 = \"bảo bối nạp điện\" → sạc dự phòng."},{"char":"常用","pinyin":"cháng yòng","hanviet":"Thường dụng","chars":["常","用"],"story":"常 = thường, hay. 用 = dùng. 常用 = thường dùng; hay làm định ngữ có 的: 常用的东西 (đồ hay dùng)."},{"char":"越","pinyin":"yuè","hanviet":"Việt","chars":["越"],"story":"越 = 走 (chạy) + 戉 yuè chỉ âm → chạy vượt qua. Vượt lên mãi → càng. Dùng trong 越来越 (bài này) và 越 A 越 B (bài 9)."},{"char":"分开","pinyin":"fēnkāi","hanviet":"Phân khai","chars":["分","开"],"story":"分 = 八 (tách đôi) + 刀 (dao) → dùng dao chia ra. 开 = mở ra. 分开 = tách ra, chia ra. Trái nghĩa: 在一起."},{"char":"检查","pinyin":"jiǎnchá","hanviet":"Kiểm tra","chars":["检","查"],"story":"检 = 木 + 佥 → xem xét. 查 = 木 + 旦 → tra xét. 检查 = xem xét kỹ → kiểm tra (đọc Hán Việt cũng là \"kiểm tra\")."},{"char":"刷","pinyin":"shuā","hanviet":"Loát","chars":["刷"],"story":"刷 = 刂 (dao) + 尸 + 巾 (khăn) → chà, cọ: 刷牙 = đánh răng. Nghĩa trong bài: quẹt thẻ, quét giấy tờ qua máy: 刷卡, 刷护照."},{"char":"检票","pinyin":"jiǎnpiào","hanviet":"Kiểm phiếu","chars":["检","票"],"story":"检 = kiểm tra. 票 = vé. 检票 = soát vé. 检票口 = cửa soát vé; 检票进站 = soát vé vào ga."},{"char":"电梯","pinyin":"diàntī","hanviet":"Điện thê","chars":["电","梯"],"story":"电 = điện. 梯 = 木 (gỗ) + 弟 dì chỉ âm → cái thang gỗ có bậc. 电梯 = thang chạy bằng điện → thang máy, thang cuốn."},{"char":"放假","pinyin":"fàngjià","hanviet":"Phóng giá","chars":["放","假"],"story":"放 = thả ra, cho nghỉ. 假 đọc jià = kỳ nghỉ (đọc jiǎ = giả). 放假 = cho nghỉ, được nghỉ; li hợp: 放三天假."},{"char":"沙发","pinyin":"shāfā","hanviet":"Sa phát","chars":["沙","发"],"story":"沙发 là từ phiên âm tiếng Anh \"sofa\" → chỉ mượn âm, không ghép nghĩa từng chữ (沙 = cát, 发 = phát). Lượng từ: 一个沙发."},{"char":"安静","pinyin":"ānjìng","hanviet":"An tĩnh","chars":["安","静"],"story":"安 = 宀 (mái nhà) + 女 → người phụ nữ ở trong nhà → yên. 静 = 青 + 争 → lặng. 安静 = yên tĩnh; 安静点儿 = trật tự chút."},{"char":"选择","pinyin":"xuǎnzé","hanviet":"Tuyển trạch","chars":["选","择"],"story":"选 = 辶 + 先 → chọn (bài 2). 择 = 扌 (tay) + 㚔 → lấy tay nhặt ra. 选择 = lựa chọn, trang trọng hơn 选."},{"char":"必须","pinyin":"bìxū","hanviet":"Tất tu","chars":["必","须"],"story":"必 = tất, nhất định. 须 = cần. 必须 = nhất định phải. Phủ định không nói ✗ 不必须 mà dùng 不用 / 不必."},{"char":"北京南站","pinyin":"Běijīng Nán Zhàn","hanviet":"Bắc Kinh Nam Trạm","chars":["北","京","南","站"],"story":"北京 = Bắc Kinh. 南 = phía nam. 站 = ga, trạm (bài 1: 站 = đứng). 北京南站 = ga phía nam Bắc Kinh, ga tàu cao tốc lớn đi Thượng Hải."}],"grammar":[{"title":"Cấu trúc 该 + động từ + 了","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>(主语)</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>该</b><small>phải, nên</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词 / 动词短语</b><small>việc cần làm</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b><small>rồi</small></span></div>","summary":"<p class=\"gr-lead\">Đến lúc phải … rồi</p><ul><li><span class=\"zh\">该……了</span> = <b>đã đến lúc</b> phải làm việc gì, dùng nhiều trong <b>khẩu ngữ</b>; phía trước hay có câu nêu thời gian / lý do: <span class=\"zh\">已经很晚了，</span>…</li><li><span class=\"zh\">该</span> + người + <span class=\"zh\">了</span> = đến lượt ai: <span class=\"zh\">该你了</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">八点了，该上课了。</span> = Tám giờ rồi, đến giờ vào học rồi.</p>","note":"<b>Lưu ý:</b> 了 đứng cuối câu, không đặt sau động từ: ✗ <span class=\"zh\">咱们该买了票</span> → ✓ <span class=\"zh\">咱们该买票了</span>","examples":[{"zh":"咱们该买去上海的票了。","py":"Zánmen gāi mǎi qù Shànghǎi de piào le.","vi":"Mình phải mua vé đi Thượng Hải rồi."},{"zh":"八点了，该上课了。","py":"Bā diǎn le, gāi shàngkè le.","vi":"Tám giờ rồi, đến giờ vào học rồi."},{"zh":"已经很晚了，我该睡觉了。","py":"Yǐjīng hěn wǎn le, wǒ gāi shuìjiào le.","vi":"Đã muộn lắm rồi, mình phải đi ngủ thôi."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">天已经黑了，____。</span><span class=\"qz-hint\">Trời tối rồi, chúng ta phải về nhà thôi.</span>","answer":["我们该回家了","该回家了","咱们该回家了"],"explain":"天已经黑了，我们该回家了。 (Tiān yǐjīng hēi le, wǒmen gāi huí jiā le.)"},{"type":"fill","q":"<span class=\"zh\">电影就要开始了，____。</span><span class=\"qz-hint\">Phim sắp bắt đầu rồi, chúng ta phải vào thôi.</span>","answer":["我们该进去了","该进去了","咱们该进去了"],"explain":"电影就要开始了，我们该进去了。 (Diànyǐng jiù yào kāishǐ le, wǒmen gāi jìnqu le.)"},{"type":"fill","q":"<span class=\"zh\">他下个星期过生日，____。</span><span class=\"qz-hint\">Tuần sau là sinh nhật anh ấy, mình phải chuẩn bị quà rồi.</span>","answer":["我们该给他准备礼物了","该给他准备礼物了","我们该给他买礼物了"],"explain":"他下个星期过生日，我们该给他准备礼物了。 (Tā xià ge xīngqī guò shēngrì, wǒmen gāi gěi tā zhǔnbèi lǐwù le.)"}]},{"title":"Câu phức giả thiết: 如果……，(主语) 就……","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>如果</b><small>nếu</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>假设</b><small>giả thiết</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(主语₂)</b><small>CN vế 2</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b><small>thì</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>结果</b><small>kết quả</small></span></div>","summary":"<p class=\"gr-lead\">Nếu … thì …</p><ul><li>Vế sau <span class=\"zh\">如果</span> là <b>giả thiết</b>, vế sau <span class=\"zh\">就</span> là <b>kết quả</b> trong tình huống đó.</li><li>Giả thiết trái với việc đã xảy ra cũng dùng được: <span class=\"zh\">如果没走错，二十分钟以前就到了</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">如果……，就……</span> · Ba dạng thường gặp</h4><p>Nếu … thì …</p><div class=\"gr-formula\"><div class=\"fx-lbl\">CN vế 2 + 就</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>如果</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>下雨</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>不去了</b></span></div><div class=\"fx-ex zh\">如果下雨，我就不去了。</div><div class=\"fx-lbl\">Vế 2 lược CN</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>如果</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>你需要帮忙</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>打电话</b></span></div><div class=\"fx-ex zh\">如果你需要帮忙，就打电话。</div><div class=\"fx-lbl\">Trái việc đã qua</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>如果</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>没走错</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>早</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>到了</b></span></div><div class=\"fx-ex zh\">如果没走错，早就到了。</div></div><p class=\"gr-key\"><span class=\"zh\">就</span> đứng sau chủ ngữ và trạng ngữ thời gian của vế 2　·　vế <span class=\"zh\">如果</span> luôn đứng trước</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">如果有时间，我就去上海玩几天。</span> — chủ ngữ <span class=\"zh\">我</span> đứng <b>trước</b> <span class=\"zh\">就</span>.</p>","note":"<b>Lưu ý:</b> Chủ ngữ vế 2 đặt trước 就: ✗ <span class=\"zh\">如果有时间，就我去上海</span> → ✓ <span class=\"zh\">如果有时间，我就去上海</span>","examples":[{"zh":"如果没走错，二十分钟以前就到了。","py":"Rúguǒ méi zǒucuò, èrshí fēnzhōng yǐqián jiù dào le.","vi":"Nếu không đi nhầm thì hai mươi phút trước đã đến rồi."},{"zh":"如果你需要帮忙，就给我打电话。","py":"Rúguǒ nǐ xūyào bāngmáng, jiù gěi wǒ dǎ diànhuà.","vi":"Nếu bạn cần giúp thì gọi điện cho mình."},{"zh":"如果有时间，我就去上海玩几天。","py":"Rúguǒ yǒu shíjiān, wǒ jiù qù Shànghǎi wán jǐ tiān.","vi":"Nếu có thời gian, mình sẽ đi Thượng Hải chơi vài ngày."}],"exercises":[]},{"title":"Cụm cố định 越来越 + tính từ / động từ tâm lý","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>越来越</b><small>ngày càng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词 / 心理动词</b><small>TT / ĐT tâm lý</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(了)</b><small>rồi</small></span></div>","summary":"<p class=\"gr-lead\">Ngày càng …</p><ul><li><span class=\"zh\">越来越</span> + <b>tính từ</b> hoặc <b>động từ tâm lý</b> (<span class=\"zh\">喜欢 · 想 · 着急</span>…) → mức độ thay đổi theo thời gian; cuối câu hay có <span class=\"zh\">了</span>.</li><li><span class=\"zh\">越来越</span> thay đổi theo <b>thời gian</b>; <span class=\"zh\">越 A 越 B</span> (bài 9) thay đổi theo một điều kiện khác.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">越来越</span> · Ba cách dùng</h4><p>Ngày càng …</p><div class=\"gr-formula\"><div class=\"fx-lbl\">+ Tính từ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>天气</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>越来越</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>冷</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b></span></div><div class=\"fx-ex zh\">天气越来越冷了。</div><div class=\"fx-lbl\">+ ĐT tâm lý</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>越来越</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>想</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>家了</b></span></div><div class=\"fx-ex zh\">我越来越想家了。</div><div class=\"fx-lbl\">Hai vế nối nhau</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>越来越</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>高</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>也</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>越来越</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>漂亮</b></span></div><div class=\"fx-ex zh\">她越来越高，也越来越漂亮了。</div></div><p class=\"gr-key\">Tính từ / ĐT tâm lý đứng ngay sau <span class=\"zh\">越来越</span>, không thêm <span class=\"zh\">很 · 非常 · 太</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">前面的人越来越多。</span> = Người phía trước ngày càng đông.</p>","note":"<b>Lưu ý:</b> Không thêm phó từ mức độ: ✗ <span class=\"zh\">天气越来越很冷</span> → ✓ <span class=\"zh\">天气越来越冷了</span>","examples":[{"zh":"前面的人越来越多。","py":"Qiánmian de rén yuè lái yuè duō.","vi":"Người phía trước ngày càng đông."},{"zh":"我越来越喜欢这里的生活了。","py":"Wǒ yuè lái yuè xǐhuan zhèli de shēnghuó le.","vi":"Mình ngày càng thích cuộc sống ở đây."},{"zh":"她越来越高，也越来越漂亮了。","py":"Tā yuè lái yuè gāo, yě yuè lái yuè piàoliang le.","vi":"Cô bé ngày càng cao, cũng ngày càng xinh."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">这些年的天气____。</span><span class=\"qz-hint\">Thời tiết mấy năm nay ngày càng nóng.</span>","answer":["越来越热了","越来越热"],"explain":"这些年的天气越来越热了。 (Zhèxiē nián de tiānqì yuè lái yuè rè le.)"},{"type":"fill","q":"<span class=\"zh\">他每天都运动，现在____。</span><span class=\"qz-hint\">Anh ấy ngày nào cũng tập, giờ sức khoẻ ngày càng tốt.</span>","answer":["身体越来越好了","身体越来越好","越来越健康了"],"explain":"他每天都运动，现在身体越来越好了。 (Tā měi tiān dōu yùndòng, xiànzài shēntǐ yuè lái yuè hǎo le.)"},{"type":"fill","q":"<span class=\"zh\">孩子还没有到家，妈妈____。</span><span class=\"qz-hint\">Con vẫn chưa về đến nhà, mẹ ngày càng sốt ruột.</span>","answer":["越来越着急了","越来越着急"],"explain":"孩子还没有到家，妈妈越来越着急了。 (Háizi hái méiyǒu dào jiā, māma yuè lái yuè zháojí le.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在咖啡厅里","titleVi":"Quán cà phê — bàn chuyện đi Thượng Hải","lines":[{"speaker":"文","name":"Lý Văn","zh":"家月，咱们该买去上海的票了。你打算怎么去上海？","py":"Jiāyuè, zánmen gāi mǎi qù Shànghǎi de piào le. Nǐ dǎsuàn zěnme qù Shànghǎi?","vi":"Gia Nguyệt, mình phải mua vé đi Thượng Hải rồi. Em định đi Thượng Hải bằng gì?"},{"speaker":"月","name":"Gia Nguyệt","zh":"我还没坐过高铁，咱们坐高铁去，怎么样？","py":"Wǒ hái méi zuòguo gāotiě, zánmen zuò gāotiě qù, zěnmeyàng?","vi":"Em chưa đi tàu cao tốc bao giờ, mình đi tàu cao tốc nhé?"},{"speaker":"文","name":"Lý Văn","zh":"没问题，从北京到上海的高铁很多，非常方便。","py":"Méi wèntí, cóng Běijīng dào Shànghǎi de gāotiě hěn duō, fēicháng fāngbiàn.","vi":"Không vấn đề gì, tàu cao tốc Bắc Kinh – Thượng Hải nhiều lắm, rất tiện."},{"speaker":"月","name":"Gia Nguyệt","zh":"行！怎么买高铁票？","py":"Xíng! Zěnme mǎi gāotiě piào?","vi":"Được! Mua vé tàu cao tốc thế nào anh?"},{"speaker":"文","name":"Lý Văn","zh":"用手机App就能买。给我你的护照，我帮你买。","py":"Yòng shǒujī App jiù néng mǎi. Gěi wǒ nǐ de hùzhào, wǒ bāng nǐ mǎi.","vi":"Dùng App trên điện thoại là mua được. Đưa anh hộ chiếu, anh mua giúp em."},{"speaker":"月","name":"Gia Nguyệt","zh":"早就听说过高铁，终于可以坐上了。","py":"Zǎo jiù tīngshuōguo gāotiě, zhōngyú kěyǐ zuòshang le.","vi":"Nghe nói về tàu cao tốc từ lâu, cuối cùng cũng được đi rồi."},{"speaker":"文","name":"Lý Văn","zh":"高铁又快又舒服，你一定会喜欢的。","py":"Gāotiě yòu kuài yòu shūfu, nǐ yídìng huì xǐhuan de.","vi":"Tàu cao tốc vừa nhanh vừa thoải mái, em chắc chắn sẽ thích."}]},{"titleZh":"课文二 · 在车上","titleVi":"Trên xe — Lưu Minh đưa hai người ra ga","lines":[{"speaker":"明","name":"Lưu Minh","zh":"过了前面的路口就到高铁站了。","py":"Guòle qiánmian de lùkǒu jiù dào gāotiězhàn le.","vi":"Qua ngã tư phía trước là đến ga tàu cao tốc rồi."},{"speaker":"月","name":"Gia Nguyệt","zh":"我看见了。马上就到了，这条路车很多，您小心点儿。","py":"Wǒ kànjiàn le. Mǎshàng jiù dào le, zhè tiáo lù chē hěn duō, nín xiǎoxīn diǎnr.","vi":"Em thấy rồi. Sắp đến rồi, đường này nhiều xe, anh cẩn thận chút ạ."},{"speaker":"明","name":"Lưu Minh","zh":"好，你们还有一个小时，应该不会迟到的。","py":"Hǎo, nǐmen hái yǒu yí ge xiǎoshí, yīnggāi bú huì chídào de.","vi":"Ừ, các em còn một tiếng nữa, chắc không trễ đâu."},{"speaker":"月","name":"Gia Nguyệt","zh":"我发现这条路车多，红绿灯也多。","py":"Wǒ fāxiàn zhè tiáo lù chē duō, hóng-lǜdēng yě duō.","vi":"Em thấy đường này xe nhiều, đèn giao thông cũng nhiều."},{"speaker":"明","name":"Lưu Minh","zh":"是啊，这条路我走过一次，后来再也不走了。","py":"Shì a, zhè tiáo lù wǒ zǒuguo yí cì, hòulái zài yě bù zǒu le.","vi":"Đúng thế, đường này anh đi một lần rồi, về sau không bao giờ đi nữa."},{"speaker":"月","name":"Gia Nguyệt","zh":"那您今天为什么走了这条路？","py":"Nà nín jīntiān wèi shénme zǒule zhè tiáo lù?","vi":"Vậy sao hôm nay anh lại đi đường này?"},{"speaker":"明","name":"Lưu Minh","zh":"我一急就走错了。如果没走错，二十分钟以前就到了。","py":"Wǒ yì jí jiù zǒucuò le. Rúguǒ méi zǒucuò, èrshí fēnzhōng yǐqián jiù dào le.","vi":"Anh vội quá nên đi nhầm. Nếu không nhầm thì hai mươi phút trước đã đến rồi."}]},{"titleZh":"课文三 · 在高铁站","titleVi":"Ga tàu cao tốc — xếp hàng soát vé","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"李文，我的耳机没电了，你有充电宝吗？","py":"Lǐ Wén, wǒ de ěrjī méi diàn le, nǐ yǒu chōngdiànbǎo ma?","vi":"Lý Văn, tai nghe của em hết pin rồi, anh có sạc dự phòng không?"},{"speaker":"文","name":"Lý Văn","zh":"有，这些常用的东西我都放在包里了，我给你拿。","py":"Yǒu, zhèxiē cháng yòng de dōngxi wǒ dōu fàng zài bāo li le, wǒ gěi nǐ ná.","vi":"Có, mấy thứ hay dùng anh đều để trong túi, anh lấy cho em."},{"speaker":"月","name":"Gia Nguyệt","zh":"前面的人越来越多。","py":"Qiánmian de rén yuè lái yuè duō.","vi":"Người phía trước ngày càng đông."},{"speaker":"文","name":"Lý Văn","zh":"对，马上就进高铁站了。咱们一起走，别分开。","py":"Duì, mǎshàng jiù jìn gāotiězhàn le. Zánmen yìqǐ zǒu, bié fēnkāi.","vi":"Ừ, sắp vào ga rồi. Mình đi cùng nhau, đừng tách ra nhé."},{"speaker":"月","name":"Gia Nguyệt","zh":"好，你检查一下，高铁票都拿好了吗？","py":"Hǎo, nǐ jiǎnchá yíxià, gāotiě piào dōu náhǎo le ma?","vi":"Vâng, anh kiểm tra xem, vé tàu cầm đủ chưa?"},{"speaker":"文","name":"Lý Văn","zh":"不用拿票，刷护照就能检票进站。","py":"Búyòng ná piào, shuā hùzhào jiù néng jiǎnpiào jìn zhàn.","vi":"Không cần cầm vé, quẹt hộ chiếu là soát vé vào ga được."},{"speaker":"月","name":"Gia Nguyệt","zh":"去哪里检票？","py":"Qù nǎli jiǎnpiào?","vi":"Soát vé ở đâu anh?"},{"speaker":"文","name":"Lý Văn","zh":"检票口在二层，我们一会儿坐电梯上去。","py":"Jiǎnpiàokǒu zài èr céng, wǒmen yíhuìr zuò diàntī shàngqu.","vi":"Cửa soát vé ở tầng hai, lát nữa mình đi thang cuốn lên."}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — Gia Nguyệt gọi điện cho Annie","para":true,"speaker":"月","lines":[{"zh":"这次放假，我去了北京，还去了上海。","py":"Zhè cì fàngjià, wǒ qùle Běijīng, hái qùle Shànghǎi.","vi":"Kỳ nghỉ này, mình đã đi Bắc Kinh, còn đi cả Thượng Hải."},{"zh":"我是从北京南站坐高铁去的上海。","py":"Wǒ shì cóng Běijīng Nán Zhàn zuò gāotiě qù de Shànghǎi.","vi":"Mình đi tàu cao tốc từ ga Nam Bắc Kinh đến Thượng Hải."},{"zh":"我觉得坐在高铁上跟坐在家里的沙发上一样，又安静又舒服。","py":"Wǒ juéde zuò zài gāotiě shang gēn zuò zài jiāli de shāfā shang yíyàng, yòu ānjìng yòu shūfu.","vi":"Mình thấy ngồi trên tàu cao tốc giống như ngồi trên sofa ở nhà, vừa yên tĩnh vừa thoải mái."},{"zh":"坐累了就站一会儿，饿了就点外卖。","py":"Zuò lèile jiù zhàn yíhuìr, èle jiù diǎn wàimài.","vi":"Ngồi mỏi thì đứng một lát, đói thì gọi đồ ăn."},{"zh":"对，你没听错，高铁上可以点外卖，只需要选择好车站和想吃的东西，到站时不用下车，服务员就会给你拿过来。","py":"Duì, nǐ méi tīngcuò, gāotiě shang kěyǐ diǎn wàimài, zhǐ xūyào xuǎnzé hǎo chēzhàn hé xiǎng chī de dōngxi, dào zhàn shí búyòng xià chē, fúwùyuán jiù huì gěi nǐ ná guòlai.","vi":"Đúng vậy, cậu không nghe nhầm đâu, trên tàu cao tốc gọi được đồ ăn, chỉ cần chọn ga và món muốn ăn, đến ga không cần xuống tàu, nhân viên sẽ mang đến cho cậu."},{"zh":"现在喜欢坐高铁的人越来越多。","py":"Xiànzài xǐhuan zuò gāotiě de rén yuè lái yuè duō.","vi":"Bây giờ người thích đi tàu cao tốc ngày càng nhiều."},{"zh":"我爸妈来中国旅游的时候，必须带他们也坐一次高铁。","py":"Wǒ bà mā lái Zhōngguó lǚyóu de shíhou, bìxū dài tāmen yě zuò yí cì gāotiě.","vi":"Khi bố mẹ mình sang Trung Quốc du lịch, nhất định phải dẫn họ đi tàu cao tốc một lần."}]}]},"extra":[],"activity":{"act":[{"zh":"多人活动","py":"duōrén huódòng","tag":"Hoạt động nhóm","mean":"Trải nghiệm đi lại","q":{"zh":"介绍自己乘坐交通工具出行的经历。","py":"Jièshào zìjǐ chéngzuò jiāotōng gōngjù chūxíng de jīnglì.","vi":"Nhóm 4 người, kể trải nghiệm đi lại bằng phương tiện giao thông."},"items":[{"zh":"你是怎么买票的？","py":"Nǐ shì zěnme mǎi piào de?","vi":"Bạn đã mua vé thế nào?"},{"zh":"你是怎么去车站或者机场的？","py":"Nǐ shì zěnme qù chēzhàn huòzhě jīchǎng de?","vi":"Bạn ra ga hoặc sân bay bằng cách nào?"},{"zh":"怎么检票进站？不能带什么东西？","py":"Zěnme jiǎnpiào jìn zhàn? Bù néng dài shénme dōngxi?","vi":"Soát vé vào ga thế nào? Không được mang gì?"},{"zh":"如果你不能和朋友坐在一起，你们会怎么办？","py":"Rúguǒ nǐ bù néng hé péngyou zuò zài yìqǐ, nǐmen huì zěnme bàn?","vi":"Nếu không được ngồi cạnh bạn, các bạn sẽ làm sao?"},{"zh":"如果朋友第一次坐高铁或者飞机，你想告诉他什么？","py":"Rúguǒ péngyou dì yī cì zuò gāotiě huòzhě fēijī, nǐ xiǎng gàosu tā shénme?","vi":"Nếu bạn bè lần đầu đi tàu / máy bay, bạn muốn dặn gì?"}]}],"speak":[{"zh":"口语练习","py":"kǒuyǔ liànxí","tag":"Luyện nói","mean":"Ôn bài 1–6 · Chuyến đi khó quên","prep":3,"talk":2,"q":{"zh":"请你说说你最难忘的一次旅游。","py":"Qǐng nǐ shuōshuo nǐ zuì nánwàng de yí cì lǚyóu.","vi":"Hãy kể về chuyến du lịch khó quên nhất của bạn."},"frame":[{"lbl":"开头","zh":"那次放假，我觉得该出去玩玩了，就和……去了……。","py":"Nà cì fàngjià, wǒ juéde gāi chūqu wánwan le, jiù hé …… qùle …….","vi":"Kỳ nghỉ đó, mình thấy đến lúc đi chơi rồi, nên cùng … đi …","ex":{"zh":"去年放假，我觉得该出去玩玩了，就和朋友去了上海。","py":"Qùnián fàngjià, wǒ juéde gāi chūqu wánwan le, jiù hé péngyou qùle Shànghǎi.","vi":"Kỳ nghỉ năm ngoái, mình thấy đến lúc đi chơi rồi, nên cùng bạn đi Thượng Hải."}},{"lbl":"中间","zh":"我们是坐……去的，……又……又……。","py":"Wǒmen shì zuò …… qù de, …… yòu …… yòu …….","vi":"Bọn mình đi bằng …, … vừa … vừa …","ex":{"zh":"我们是坐高铁去的，高铁又快又舒服。","py":"Wǒmen shì zuò gāotiě qù de, gāotiě yòu kuài yòu shūfu.","vi":"Bọn mình đi bằng tàu cao tốc, tàu vừa nhanh vừa thoải mái."}},{"lbl":"中间","zh":"……看起来……，跟……一点儿也不一样。","py":"…… kàn qǐlai ……, gēn …… yìdiǎnr yě bù yíyàng.","vi":"… trông …, chẳng giống … chút nào.","ex":{"zh":"上海看起来很漂亮，跟北京一点儿也不一样。","py":"Shànghǎi kàn qǐlai hěn piàoliang, gēn Běijīng yìdiǎnr yě bù yíyàng.","vi":"Thượng Hải trông rất đẹp, chẳng giống Bắc Kinh chút nào."}},{"lbl":"中间","zh":"除了……以外，我们还……，……张张都挺……的。","py":"Chúle …… yǐwài, wǒmen hái ……, …… zhāngzhāng dōu tǐng …… de.","vi":"Ngoài … ra, bọn mình còn …, tấm nào cũng khá …","ex":{"zh":"除了吃好吃的以外，我们还拍了很多照片，张张都挺好看的。","py":"Chúle chī hǎochī de yǐwài, wǒmen hái pāile hěn duō zhàopiàn, zhāngzhāng dōu tǐng hǎokàn de.","vi":"Ngoài ăn đồ ngon ra, bọn mình còn chụp rất nhiều ảnh, tấm nào cũng khá đẹp."}},{"lbl":"结尾","zh":"我越来越喜欢……了，如果……，我就……。","py":"Wǒ yuè lái yuè xǐhuan …… le, rúguǒ ……, wǒ jiù …….","vi":"Mình ngày càng thích … , nếu …, mình sẽ …","ex":{"zh":"我越来越喜欢旅游了，如果明年有时间，我就再去一次。","py":"Wǒ yuè lái yuè xǐhuan lǚyóu le, rúguǒ míngnián yǒu shíjiān, wǒ jiù zài qù yí cì.","vi":"Mình ngày càng thích du lịch, nếu sang năm có thời gian, mình sẽ đi thêm lần nữa."}}]}]},"review":{"range":"4–6","rows":[{"l":4,"zh":"固定格式 \"一……也/都 + 不/没……\"","vi":"Cấu trúc 一……也/都 + 不/没……","ex":{"zh":"她一件衣服都不想买。","py":"Tā yí jiàn yīfu dōu bù xiǎng mǎi.","vi":"Cô ấy chẳng muốn mua bộ quần áo nào."}},{"l":4,"zh":"比较句 (9) \"A 跟 B 一样\"","vi":"Câu so sánh (9): A 跟 B 一样","ex":{"zh":"这家宾馆跟别的都不一样。","py":"Zhè jiā bīnguǎn gēn bié de dōu bù yíyàng.","vi":"Khách sạn này chẳng giống nơi nào khác."}},{"l":4,"zh":"固定格式 \"除了……（以外）\"","vi":"Cấu trúc 除了……（以外），……都/还/也……","ex":{"zh":"除了我以外，大家都在玩手机。","py":"Chúle wǒ yǐwài, dàjiā dōu zài wán shǒujī.","vi":"Ngoài mình ra, mọi người đều đang chơi điện thoại."}},{"l":5,"zh":"程度补语 (2) \"得很\"","vi":"Bổ ngữ trình độ (2): 得很","ex":{"zh":"现在天气好得很。","py":"Xiànzài tiānqì hǎo de hěn.","vi":"Bây giờ thời tiết đẹp lắm."}},{"l":5,"zh":"量词重叠","vi":"Lặp lượng từ","ex":{"zh":"这些照片张张都非常好看。","py":"Zhèxiē zhàopiàn zhāngzhāng dōu fēicháng hǎokàn.","vi":"Những tấm ảnh này tấm nào cũng rất đẹp."}},{"l":5,"zh":"存现句 (3)","vi":"Câu tồn hiện (3)","ex":{"zh":"后边走过去两个人。","py":"Hòubian zǒu guòqu liǎng ge rén.","vi":"Phía sau có hai người đi qua."}},{"l":5,"zh":"紧缩复句 \"……了……就……\"","vi":"Câu phức rút gọn ……了……就……","ex":{"zh":"你听完了音乐会就来我家吃饭。","py":"Nǐ tīngwánle yīnyuèhuì jiù lái wǒ jiā chīfàn.","vi":"Em nghe xong buổi hoà nhạc thì đến nhà chị ăn cơm."}},{"l":6,"zh":"固定格式 \"该……了\"","vi":"Cấu trúc 该……了","ex":{"zh":"咱们该买去上海的票了。","py":"Zánmen gāi mǎi qù Shànghǎi de piào le.","vi":"Mình phải mua vé đi Thượng Hải rồi."}},{"l":6,"zh":"假设复句 \"如果……，就……\"","vi":"Câu phức giả thiết 如果……，就……","ex":{"zh":"如果没走错，二十分钟以前就到了。","py":"Rúguǒ méi zǒucuò, èrshí fēnzhōng yǐqián jiù dào le.","vi":"Nếu không đi nhầm thì hai mươi phút trước đã đến rồi."}},{"l":6,"zh":"固定短语 \"越来越\"","vi":"Cụm cố định 越来越","ex":{"zh":"前面的人越来越多。","py":"Qiánmian de rén yuè lái yuè duō.","vi":"Người phía trước ngày càng đông."}}]}},{"id":"k3v3-b07","courseId":"k3v3","order":7,"title":"Chiếc váy kia đẹp hơn chiếc quần đùi","titleZh":"那条裙子比短裤更好看","titlePy":"nà tiáo qúnzi bǐ duǎnkù gèng hǎokàn","vocab":[{"stt":1,"hanzi":"辆","pinyin":"liàng","hanviet":"Lượng","pos":"Lượng từ","meaning":"chiếc (xe)","comps":"一辆车 (một chiếc xe), 两辆自行车 (hai chiếc xe đạp)","example":{"zh":"我家楼下停着两辆车。","py":"Wǒ jiā lóu xià tíngzhe liǎng liàng chē.","vi":"Dưới nhà mình có hai chiếc xe đang đỗ."}},{"stt":2,"hanzi":"自行车","pinyin":"zìxíngchē","hanviet":"Tự hành xa","pos":"Danh từ","meaning":"xe đạp","comps":"骑自行车 (đi xe đạp), 新自行车 (xe đạp mới)","example":{"zh":"我每天骑自行车去学校。","py":"Wǒ měi tiān qí zìxíngchē qù xuéxiào.","vi":"Ngày nào mình cũng đạp xe đến trường."}},{"stt":3,"hanzi":"旧","pinyin":"jiù","hanviet":"Cựu","pos":"Tính từ","meaning":"cũ","comps":"旧衣服 (quần áo cũ), 有点儿旧了 (hơi cũ rồi)","example":{"zh":"这个手机太旧了，我想换个新的。","py":"Zhège shǒujī tài jiù le, wǒ xiǎng huàn ge xīn de.","vi":"Cái điện thoại này cũ quá, mình muốn đổi cái mới."}},{"stt":4,"hanzi":"矮","pinyin":"ǎi","hanviet":"Ải","pos":"Tính từ","meaning":"thấp, lùn","comps":"个子矮 (dáng người thấp), 矮一点儿 (thấp hơn một chút)","example":{"zh":"我比哥哥矮一点儿。","py":"Wǒ bǐ gēge ǎi yìdiǎnr.","vi":"Mình thấp hơn anh trai một chút."}},{"stt":5,"hanzi":"试","pinyin":"shì","hanviet":"Thí","pos":"Động từ","meaning":"thử","comps":"试一下 (thử một chút), 试试这件 (thử chiếc này xem)","example":{"zh":"这件衣服很漂亮，你试一下吧。","py":"Zhè jiàn yīfu hěn piàoliang, nǐ shì yíxià ba.","vi":"Chiếc áo này đẹp lắm, bạn mặc thử xem."}},{"stt":6,"hanzi":"黄色","pinyin":"huángsè","hanviet":"Hoàng sắc","pos":"Danh từ","meaning":"màu vàng","comps":"黄色的花 (hoa màu vàng), 黄色的衣服 (áo màu vàng)","example":{"zh":"她最喜欢黄色。","py":"Tā zuì xǐhuan huángsè.","vi":"Cô ấy thích nhất màu vàng."}},{"stt":7,"hanzi":"短裤","pinyin":"duǎnkù","hanviet":"Đoản khố","pos":"Danh từ","meaning":"quần đùi, quần soóc","comps":"一条短裤 (một chiếc quần soóc), 穿短裤 (mặc quần soóc)","example":{"zh":"天气太热了，我想穿短裤。","py":"Tiānqì tài rè le, wǒ xiǎng chuān duǎnkù.","vi":"Trời nóng quá, mình muốn mặc quần soóc."}},{"stt":8,"hanzi":"大小","pinyin":"dàxiǎo","hanviet":"Đại tiểu","pos":"Danh từ","meaning":"kích cỡ, cỡ","comps":"大小合适 (cỡ vừa), 大小不一样 (cỡ khác nhau)","example":{"zh":"这双鞋大小正好。","py":"Zhè shuāng xié dàxiǎo zhènghǎo.","vi":"Đôi giày này cỡ vừa khít."}},{"stt":9,"hanzi":"合适","pinyin":"héshì","hanviet":"Hợp thích","pos":"Tính từ","meaning":"vừa vặn, phù hợp","comps":"很合适 (rất vừa), 不太合适 (không hợp lắm)","example":{"zh":"这件衣服你穿很合适。","py":"Zhè jiàn yīfu nǐ chuān hěn héshì.","vi":"Chiếc áo này bạn mặc rất vừa."}},{"stt":10,"hanzi":"裙子","pinyin":"qúnzi","hanviet":"Quần tử","pos":"Danh từ","meaning":"váy","comps":"一条裙子 (một chiếc váy), 穿裙子 (mặc váy)","example":{"zh":"她今天穿了一条白色的裙子。","py":"Tā jīntiān chuānle yì tiáo báisè de qúnzi.","vi":"Hôm nay cô ấy mặc một chiếc váy trắng."}},{"stt":11,"hanzi":"更","pinyin":"gèng","hanviet":"Cánh","pos":"Phó từ","meaning":"càng, hơn nữa","comps":"更好 (tốt hơn nữa), 更喜欢 (thích hơn)","example":{"zh":"我喜欢喝茶，更喜欢喝咖啡。","py":"Wǒ xǐhuan hē chá, gèng xǐhuan hē kāfēi.","vi":"Mình thích uống trà, nhưng thích cà phê hơn."}},{"stt":12,"hanzi":"决定","pinyin":"juédìng","hanviet":"Quyết định","pos":"Động từ / Danh từ","meaning":"quyết định","comps":"决定去 (quyết định đi), 你的决定 (quyết định của bạn)","example":{"zh":"我们决定明天去爬山。","py":"Wǒmen juédìng míngtiān qù pá shān.","vi":"Chúng mình quyết định mai đi leo núi."}},{"stt":13,"hanzi":"西瓜","pinyin":"xīguā","hanviet":"Tây qua","pos":"Danh từ","meaning":"dưa hấu","comps":"一个西瓜 (một quả dưa hấu), 吃西瓜 (ăn dưa hấu)","example":{"zh":"夏天我最喜欢吃西瓜。","py":"Xiàtiān wǒ zuì xǐhuan chī xīguā.","vi":"Mùa hè mình thích ăn dưa hấu nhất."}},{"stt":14,"hanzi":"新鲜","pinyin":"xīnxiān","hanviet":"Tân tiên","pos":"Tính từ","meaning":"tươi","comps":"新鲜的水果 (hoa quả tươi), 很新鲜 (rất tươi)","example":{"zh":"这家超市的菜都很新鲜。","py":"Zhè jiā chāoshì de cài dōu hěn xīnxiān.","vi":"Rau ở siêu thị này đều rất tươi."}},{"stt":15,"hanzi":"甜","pinyin":"tián","hanviet":"Điềm","pos":"Tính từ","meaning":"ngọt","comps":"很甜 (rất ngọt), 甜的东西 (đồ ngọt)","example":{"zh":"这个蛋糕太甜了。","py":"Zhège dàngāo tài tián le.","vi":"Chiếc bánh ngọt này ngọt quá."}},{"stt":16,"hanzi":"公斤","pinyin":"gōngjīn","hanviet":"Công cân","pos":"Lượng từ","meaning":"kilôgam (kg)","comps":"一公斤 (một cân / 1 kg), 多少钱一公斤 (bao nhiêu tiền một cân)","example":{"zh":"苹果十块钱一公斤。","py":"Píngguǒ shí kuài qián yì gōngjīn.","vi":"Táo mười tệ một cân (kg)."}},{"stt":17,"hanzi":"冰","pinyin":"bīng","hanviet":"Băng","pos":"Động từ / Danh từ","meaning":"ướp lạnh; băng, đá","comps":"冰西瓜 (dưa hấu ướp lạnh), 冰水 (nước đá)","example":{"zh":"天气太热了，我想喝冰水。","py":"Tiānqì tài rè le, wǒ xiǎng hē bīng shuǐ.","vi":"Trời nóng quá, mình muốn uống nước đá."}},{"stt":18,"hanzi":"极","pinyin":"jí","hanviet":"Cực","pos":"Phó từ","meaning":"cực kỳ","comps":"好极了 (tuyệt quá), 甜极了 (ngọt cực kỳ)","example":{"zh":"听说你要来，我高兴极了。","py":"Tīngshuō nǐ yào lái, wǒ gāoxìng jí le.","vi":"Nghe nói bạn sắp đến, mình vui lắm luôn."}},{"stt":19,"hanzi":"斤","pinyin":"jīn","hanviet":"Cân","pos":"Lượng từ","meaning":"cân (Trung Quốc, 0,5 kg)","comps":"一斤 (nửa cân / 0,5 kg), 两斤香蕉 (1 kg chuối)","example":{"zh":"我买了三斤苹果。","py":"Wǒ mǎile sān jīn píngguǒ.","vi":"Mình mua ba cân (1,5 kg) táo."}},{"stt":20,"hanzi":"香蕉","pinyin":"xiāngjiāo","hanviet":"Hương tiêu","pos":"Danh từ","meaning":"chuối","comps":"一斤香蕉 (nửa cân chuối), 吃香蕉 (ăn chuối)","example":{"zh":"香蕉多少钱一斤？","py":"Xiāngjiāo duōshao qián yì jīn?","vi":"Chuối bao nhiêu tiền một cân?"}},{"stt":21,"hanzi":"一共","pinyin":"yígòng","hanviet":"Nhất cộng","pos":"Phó từ","meaning":"tổng cộng","comps":"一共多少钱 (tổng cộng bao nhiêu tiền), 一共三个人 (tất cả ba người)","example":{"zh":"这些东西一共多少钱？","py":"Zhèxiē dōngxi yígòng duōshao qián?","vi":"Chỗ đồ này tổng cộng bao nhiêu tiền?"}},{"stt":22,"hanzi":"毛","pinyin":"máo","hanviet":"Mao","pos":"Lượng từ","meaning":"hào (1/10 tệ)","comps":"五毛钱 (năm hào), 三块五毛 (ba tệ năm hào)","example":{"zh":"一瓶水两块五毛钱。","py":"Yì píng shuǐ liǎng kuài wǔ máo qián.","vi":"Một chai nước hai tệ năm hào."}},{"stt":23,"hanzi":"结婚","pinyin":"jiéhūn","hanviet":"Kết hôn","pos":"Động từ (li hợp)","meaning":"kết hôn","comps":"跟他结婚 (kết hôn với anh ấy), 结婚了 (đã kết hôn)","example":{"zh":"我哥哥去年结婚了。","py":"Wǒ gēge qùnián jiéhūn le.","vi":"Anh trai mình kết hôn năm ngoái."}},{"stt":24,"hanzi":"不但","pinyin":"búdàn","hanviet":"Bất đãn","pos":"Liên từ","meaning":"không những","comps":"不但……而且…… (không những … mà còn …)","example":{"zh":"她不但漂亮，而且很聪明。","py":"Tā búdàn piàoliang, érqiě hěn cōngming.","vi":"Cô ấy không những xinh đẹp mà còn rất thông minh."}},{"stt":25,"hanzi":"而且","pinyin":"érqiě","hanviet":"Nhi thả","pos":"Liên từ","meaning":"mà còn, hơn nữa","comps":"而且还 (mà còn), 而且也 (mà … cũng)","example":{"zh":"这家店的菜很好吃，而且不贵。","py":"Zhè jiā diàn de cài hěn hǎochī, érqiě bú guì.","vi":"Món ở quán này rất ngon, mà lại không đắt."}},{"stt":26,"hanzi":"声","pinyin":"shēng","hanviet":"Thanh","pos":"Lượng từ / Danh từ","meaning":"tiếng; âm thanh","comps":"叫一声 (gọi một tiếng), 声音 (âm thanh)","example":{"zh":"到了门口，你叫我一声。","py":"Dàole ménkǒu, nǐ jiào wǒ yì shēng.","vi":"Đến cửa thì bạn gọi mình một tiếng nhé."}},{"stt":27,"hanzi":"开机","pinyin":"kāijī","hanviet":"Khai cơ","pos":"Động từ","meaning":"bật máy, mở máy","comps":"手机开机 (bật điện thoại), 开机了 (máy bật rồi)","example":{"zh":"我的电脑开机很慢。","py":"Wǒ de diànnǎo kāijī hěn màn.","vi":"Máy tính của mình khởi động rất chậm."}}],"hanzi":[{"char":"辆","pinyin":"liàng","hanviet":"Lượng","chars":["辆"],"story":"辆 = 车 (xe) + 两 liǎng chỉ âm, nhắc xe xưa có hai bánh → lượng từ cho xe cộ: 一辆车, 两辆自行车. Nhớ: 两辆 liǎng liàng — hai chữ khác thanh."},{"char":"自行车","pinyin":"zìxíngchē","hanviet":"Tự hành xa","chars":["自","行","车"],"story":"自 vẽ cái mũi → bản thân. 行 = đi. 车 = xe. 自行车 = xe tự mình đi bằng sức chân → xe đạp. Động từ đi kèm là 骑 (cưỡi), không dùng 开."},{"char":"旧","pinyin":"jiù","hanviet":"Cựu","chars":["旧"],"story":"旧 = 丨 + 日 → một ngày đã trôi qua từ lâu → cũ. Trái nghĩa: 新. Chỉ đồ vật cũ; người già dùng 老, không dùng 旧."},{"char":"矮","pinyin":"ǎi","hanviet":"Ải","chars":["矮"],"story":"矮 = 矢 (mũi tên ngắn) + 委 chỉ âm → thấp như mũi tên → thấp, lùn. 矮 trái nghĩa 高 (chiều cao); 短 trái nghĩa 长 (chiều dài)."},{"char":"试","pinyin":"shì","hanviet":"Thí","chars":["试"],"story":"试 = 讠 (lời nói) + 式 (khuôn mẫu) → làm theo mẫu xem có được không → thử. 试一下 / 试试 = thử xem; 考试 = thi."},{"char":"黄色","pinyin":"huángsè","hanviet":"Hoàng sắc","chars":["黄","色"],"story":"黄 vẽ miếng ngọc vàng đeo ở thắt lưng → màu vàng. 色 = màu. Cùng cách ghép: 白色, 红色, 黑色 — 颜色 = màu sắc."},{"char":"短裤","pinyin":"duǎnkù","hanviet":"Đoản khố","chars":["短","裤"],"story":"短 = 矢 (mũi tên) + 豆 → ngắn. 裤 = 衤 (bộ y — áo quần) + 库 chỉ âm → quần. 短裤 = quần ngắn → quần soóc; quần dài là 长裤 / 裤子."},{"char":"大小","pinyin":"dàxiǎo","hanviet":"Đại tiểu","chars":["大","小"],"story":"大 (to) + 小 (nhỏ) → ghép hai tính từ trái nghĩa thành danh từ chỉ kích cỡ: 大小合适. Cùng kiểu: 长短 (độ dài), 多少 (số lượng)."},{"char":"合适","pinyin":"héshì","hanviet":"Hợp thích","chars":["合","适"],"story":"合 = 亼 (nắp) + 口 → nắp đậy khít miệng → hợp. 适 = 辶 + 舌 → vừa. 合适 là tính từ: 很合适. Phân biệt: 适合 là động từ có tân ngữ — 这件衣服适合你."},{"char":"裙子","pinyin":"qúnzi","hanviet":"Quần tử","chars":["裙","子"],"story":"裙 = 衤 (bộ y) + 君 qún chỉ âm → váy. 子 là hậu tố đọc nhẹ zi. Lượng từ của 裙子 / 短裤 / 裤子 đều là 条."},{"char":"更","pinyin":"gèng","hanviet":"Cánh","chars":["更"],"story":"更 gèng = càng, hơn nữa — đứng trước tính từ / động từ tâm lý: 更好看, 更喜欢. Trong câu 比: A比B更 + tính từ. Đọc gēng trong 更新 (đổi mới)."},{"char":"决定","pinyin":"juédìng","hanviet":"Quyết định","chars":["决","定"],"story":"决 = 冫 (nước) + 夬 → nước phá bờ tuôn ra một hướng → dứt khoát. 定 = định, yên. 决定 = dứt khoát định ra → quyết định; dùng được cả động từ lẫn danh từ."},{"char":"西瓜","pinyin":"xīguā","hanviet":"Tây qua","chars":["西","瓜"],"story":"西 = phía tây. 瓜 vẽ quả dưa treo trên dây. 西瓜 = dưa từ phương Tây (Tây Vực) truyền sang → dưa hấu. Cùng họ: 黄瓜 (dưa chuột)."},{"char":"新鲜","pinyin":"xīnxiān","hanviet":"Tân tiên","chars":["新","鲜"],"story":"新 = mới. 鲜 = 鱼 (cá) + 羊 (dê) → thịt cá, thịt dê vừa làm → tươi ngon. 新鲜 = mới và tươi: rau, quả, cá, thịt; cũng nói 新鲜空气 (không khí trong lành)."},{"char":"甜","pinyin":"tián","hanviet":"Điềm","chars":["甜"],"story":"甜 = 舌 (lưỡi) + 甘 (ngọt) → lưỡi nếm thấy vị ngọt → ngọt. Các vị khác: 酸 (chua), 苦 (đắng), 辣 (cay)."},{"char":"公斤","pinyin":"gōngjīn","hanviet":"Công cân","chars":["公","斤"],"story":"公 = chung, công. 斤 vẽ cái rìu — đơn vị cân xưa. 公斤 = cân \"quốc tế\" = 1 kg = 2 斤. Người Trung Quốc đi chợ hay nói 斤 hơn 公斤."},{"char":"冰","pinyin":"bīng","hanviet":"Băng","chars":["冰"],"story":"冰 = 冫 (hai giọt nước đông) + 水 → nước đóng băng → băng, đá. Làm động từ = ướp lạnh: 冰一下, 冰西瓜. Bộ 冫 còn ở 冷 (lạnh)."},{"char":"极","pinyin":"jí","hanviet":"Cực","chars":["极"],"story":"极 = 木 (cây) + 及 (tới) → cây xà cao nhất của nhà → đỉnh, tột cùng → cực kỳ. Hay đứng sau tính từ: 好极了, 甜极了."},{"char":"斤","pinyin":"jīn","hanviet":"Cân","chars":["斤"],"story":"斤 vẽ cái rìu có cán → xưa dùng rìu làm quả cân → đơn vị cân. 1 斤 = 0,5 kg. Hỏi giá: 多少钱一斤？"},{"char":"香蕉","pinyin":"xiāngjiāo","hanviet":"Hương tiêu","chars":["香","蕉"],"story":"香 = 禾 (lúa) + 日 → lúa chín thơm → thơm. 蕉 = 艹 (cỏ cây) + 焦 chỉ âm → cây chuối. 香蕉 = quả chuối thơm → chuối."},{"char":"一共","pinyin":"yígòng","hanviet":"Nhất cộng","chars":["一","共"],"story":"一 = một. 共 vẽ hai tay cùng nâng một vật → chung, cùng. 一共 = gộp hết lại làm một → tổng cộng: 一共多少钱？"},{"char":"毛","pinyin":"máo","hanviet":"Mao","chars":["毛"],"story":"毛 vẽ sợi lông → lông. Trong khẩu ngữ, 毛 là hào = 1/10 tệ (văn viết là 角). 块 = tệ (văn viết 元): 五十八块五毛."},{"char":"结婚","pinyin":"jiéhūn","hanviet":"Kết hôn","chars":["结","婚"],"story":"结 = 纟 (sợi tơ) + 吉 → buộc nút → kết. 婚 = 女 + 昏 (hoàng hôn) — xưa cưới vợ vào lúc chiều tối. 结婚 là động từ li hợp: 结了婚, 跟他结婚 (✗ 结婚他)."},{"char":"不但","pinyin":"búdàn","hanviet":"Bất đãn","chars":["不","但"],"story":"不 = không. 但 = 亻 + 旦 → chỉ, chỉ có. 不但 = không chỉ → không những; luôn đi cặp với 而且 ở vế sau."},{"char":"而且","pinyin":"érqiě","hanviet":"Nhi thả","chars":["而","且"],"story":"而 vẽ chòm râu → làm liên từ nối hai ý. 且 = vả lại. 而且 = mà còn, hơn nữa — nối ý thứ hai mạnh hơn ý trước."},{"char":"声","pinyin":"shēng","hanviet":"Thanh","chars":["声"],"story":"声 vẽ người gõ khánh đá → âm thanh → tiếng. Làm lượng từ cho tiếng gọi, tiếng kêu: 叫一声, 说一声 (nói một tiếng)."},{"char":"开机","pinyin":"kāijī","hanviet":"Khai cơ","chars":["开","机"],"story":"开 = mở, bật. 机 = 木 + 几 → máy móc. 开机 = bật máy (điện thoại, tivi, máy tính); ngược lại là 关机 (tắt máy)."}],"grammar":[{"title":"Câu liên động: 动词₁ + 着 + (宾语₁) + 动词₂ + (宾语₂)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词₁</b><small>cách thức</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>着</b><small>trợ từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语₁)</b><small>TN 1</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词₂</b><small>việc chính</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语₂)</b><small>TN 2</small></span></div>","summary":"<p class=\"gr-lead\">Làm việc 2 theo cách / trạng thái của việc 1</p><ul><li><span class=\"zh\">动词₁ + 着</span> chỉ <b>trạng thái / cách thức</b>; <span class=\"zh\">动词₂</span> mới là <b>việc chính</b>: <span class=\"zh\">坐着看电视</span> = ngồi (mà) xem tivi.</li><li>Hay gặp: <span class=\"zh\">走着去 · 站着说 · 笑着说 · 躺着看书 · 拿着……去</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">动词₁+着+动词₂</span> · Ba dạng thường gặp</h4><p>Làm việc 2 theo cách của việc 1</p><div class=\"gr-formula\"><div class=\"fx-lbl\">V₁着 + V₂</div><div class=\"fx-row\"><span class=\"fx-p\"><b>她</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>笑</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>着</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>说</b></span></div><div class=\"fx-ex zh\">她笑着说：\"谢谢你！\"</div><div class=\"fx-lbl\">V₁着 + TN₁ + V₂</div><div class=\"fx-row\"><span class=\"fx-p\"><b>他</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>拿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>着</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>手机</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>出去了</b></span></div><div class=\"fx-ex zh\">他拿着手机出去了。</div><div class=\"fx-lbl\">V₁着 + V₂ + TN₂</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>躺</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>着</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>看</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>书</b></span></div><div class=\"fx-ex zh\">我喜欢躺着看书。</div></div><p class=\"gr-key\">Động từ 1 + <span class=\"zh\">着</span> = làm <b>theo cách nào</b>　·　động từ 2 = làm <b>việc gì</b></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">咱们可以走着去。</span> = Mình có thể đi bộ đến đó (đến bằng cách đi bộ).</p>","note":"<b>Lưu ý:</b> 着 đứng ngay sau động từ 1: ✗ <span class=\"zh\">他们坐看着电视</span> → ✓ <span class=\"zh\">他们坐着看电视</span>","examples":[{"zh":"咱们可以走着去。","py":"Zánmen kěyǐ zǒuzhe qù.","vi":"Mình có thể đi bộ đến đó."},{"zh":"弟弟吃着苹果写作业。","py":"Dìdi chīzhe píngguǒ xiě zuòyè.","vi":"Em trai vừa ăn táo vừa làm bài tập."},{"zh":"他们坐着看电视。","py":"Tāmen zuòzhe kàn diànshì.","vi":"Họ ngồi xem tivi."}],"exercises":[]},{"title":"Câu so sánh: A + 不比 + B + 形容词 (+ 多少)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>A</b><small>người / vật 1</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不比</b><small>không hơn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b><small>người / vật 2</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词</b><small>tính từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(多少)</b><small>bao nhiêu</small></span></div>","summary":"<p class=\"gr-lead\">A chẳng hơn B</p><ul><li><span class=\"zh\">A不比B + TT</span> = A <b>không hơn</b> B, hai bên <b>xấp xỉ</b> nhau; thêm <span class=\"zh\">多少</span> = chẳng hơn bao nhiêu.</li><li>Hay dùng để <b>phản bác</b>: A：<span class=\"zh\">他比你高吧？</span> B：<span class=\"zh\">他不比我高。</span></li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">比 · 不比 · 没有</span> · Phân biệt ba cách so sánh</h4><p>Hơn · ngang ngang · kém</p><div class=\"gr-formula\"><div class=\"fx-lbl\">A > B</div><div class=\"fx-row\"><span class=\"fx-p\"><b>他</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>比</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>高</b></span></div><div class=\"fx-ex zh\">他比我高。</div><div class=\"fx-lbl\">A ≈ B (phản bác)</div><div class=\"fx-row\"><span class=\"fx-p\"><b>他</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不比</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>高</b></span></div><div class=\"fx-ex zh\">他不比我高。</div><div class=\"fx-lbl\">A < B</div><div class=\"fx-row\"><span class=\"fx-p\"><b>他</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>没有</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>高</b></span></div><div class=\"fx-ex zh\">他没有我高。</div></div><p class=\"gr-key\"><span class=\"zh\">不比</span> không có nghĩa là \"kém hơn\" — chỉ nói A <b>không hơn</b> B</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">裙子不比短裤贵多少。</span> = Váy cũng chẳng đắt hơn quần soóc bao nhiêu.</p>","note":"<b>Lưu ý:</b> 不比 ≠ 没有: <span class=\"zh\">他不比我高</span> (≈ bằng nhau) · <span class=\"zh\">他没有我高</span> (anh ấy thấp hơn tôi)","examples":[{"zh":"裙子不比短裤贵多少。","py":"Qúnzi bù bǐ duǎnkù guì duōshao.","vi":"Váy cũng chẳng đắt hơn quần soóc bao nhiêu."},{"zh":"他的中文不比你好。","py":"Tā de Zhōngwén bù bǐ nǐ hǎo.","vi":"Tiếng Trung của anh ấy cũng chẳng giỏi hơn bạn."},{"zh":"他跑得不比我快多少。","py":"Tā pǎo de bù bǐ wǒ kuài duōshao.","vi":"Anh ấy chạy cũng chẳng nhanh hơn tôi bao nhiêu."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">天中学中文的时间更长，他的中文水平比家月高吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____。</span></span></span><span class=\"qz-hint\">Thiên Trung học tiếng Trung lâu hơn, trình độ có cao hơn Gia Nguyệt không? — Trình độ tiếng Trung của anh ấy cũng chẳng cao hơn Gia Nguyệt.</span>","answer":["他的中文水平不比家月高","不比家月高","他的汉语水平不比家月高"],"explain":"他的中文水平不比家月高。 (Tā de Zhōngwén shuǐpíng bù bǐ Jiāyuè gāo.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你姐姐一个人住，她一定比你更会做饭吧？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____。</span></span></span><span class=\"qz-hint\">Chị bạn sống một mình, chắc chắn nấu ăn giỏi hơn bạn nhỉ? — Chưa chắc, chị ấy cũng chẳng nấu giỏi hơn mình.</span>","answer":["不一定，她不比我会做饭","她不比我会做饭"],"explain":"不一定，她不比我会做饭。 (Bù yídìng, tā bù bǐ wǒ huì zuò fàn.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我觉得篮球比足球更有意思，你觉得呢？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____，你多跟我去踢一踢足球就知道了。</span></span></span><span class=\"qz-hint\">Mình thấy bóng rổ thú vị hơn bóng đá, bạn thấy sao? — Bóng đá chẳng kém bóng rổ đâu, bạn đá với mình vài lần là biết.</span>","answer":["足球不比篮球差"],"explain":"足球不比篮球差，你多跟我去踢一踢足球就知道了。 (Zúqiú bù bǐ lánqiú chà, nǐ duō gēn wǒ qù tī yi tī zúqiú jiù zhīdào le.)"}]},{"title":"Bổ ngữ trình độ: 形容词 / 心理动词 + 极了","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>(主语)</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词 / 心理动词</b><small>tính từ / ĐT tâm lý</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>极了</b><small>cực kỳ</small></span></div>","summary":"<p class=\"gr-lead\">… cực kỳ, … vô cùng</p><ul><li><span class=\"zh\">极了</span> đứng <b>sau</b> tính từ hoặc động từ tâm lý (<span class=\"zh\">喜欢 · 想 · 担心</span>…) → mức độ <b>rất cao</b>; dùng nhiều trong khẩu ngữ.</li><li><span class=\"zh\">极了</span> đứng cuối câu, phía trước <b>không</b> thêm phó từ chỉ mức độ <span class=\"zh\">很 / 非常 / 太</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">这块冰西瓜甜极了。</span> = Miếng dưa hấu ướp lạnh này ngọt cực kỳ.</p>","note":"<b>Lưu ý:</b> ✗ <span class=\"zh\">这块西瓜很甜极了</span> → ✓ <span class=\"zh\">这块西瓜甜极了</span>","examples":[{"zh":"这块冰西瓜甜极了。","py":"Zhè kuài bīng xīguā tián jí le.","vi":"Miếng dưa hấu ướp lạnh này ngọt cực kỳ."},{"zh":"今年夏天热极了。","py":"Jīnnián xiàtiān rè jí le.","vi":"Mùa hè năm nay nóng vô cùng."},{"zh":"这本书我喜欢极了。","py":"Zhè běn shū wǒ xǐhuan jí le.","vi":"Cuốn sách này mình thích lắm luôn."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">她做的中国菜____。</span><span class=\"qz-hint\">Món Trung Quốc cô ấy nấu ngon cực kỳ.</span>","answer":["好吃极了"],"explain":"她做的中国菜好吃极了。 (Tā zuò de Zhōngguócài hǎochī jí le.)"},{"type":"fill","q":"<span class=\"zh\">我昨天晚上睡得____。</span><span class=\"qz-hint\">Tối qua mình ngủ ngon vô cùng.</span>","answer":["好极了"],"explain":"我昨天晚上睡得好极了。 (Wǒ zuótiān wǎnshang shuì de hǎo jí le.)"},{"type":"fill","q":"<span class=\"zh\">这些水果五块钱，真是____。</span><span class=\"qz-hint\">Chỗ hoa quả này năm tệ, đúng là rẻ cực kỳ.</span>","answer":["便宜极了"],"explain":"这些水果五块钱，真是便宜极了。 (Zhèxiē shuǐguǒ wǔ kuài qián, zhēn shì piányi jí le.)"}]},{"title":"Câu phức tăng tiến: 不但……，而且……","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不但</b><small>không những</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>A</b><small>ý 1</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，而且</b><small>mà còn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>B</b><small>ý 2 (mạnh hơn)</small></span></div>","summary":"<p class=\"gr-lead\">Không những … mà còn …</p><ul><li>Vế <span class=\"zh\">而且</span> nói thêm một ý <b>tiến thêm một bước</b> so với vế <span class=\"zh\">不但</span>; vế 2 hay thêm <span class=\"zh\">还 / 也</span>.</li><li><b>Cùng</b> chủ ngữ → <span class=\"zh\">不但</span> đặt <b>sau</b> chủ ngữ; <b>khác</b> chủ ngữ → <span class=\"zh\">不但</span> đặt <b>trước</b> chủ ngữ 1, vế 2 dùng <span class=\"zh\">也</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">不但……，而且……</span> · Vị trí của 不但</h4><p>Không những … mà còn …</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Cùng chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>水果</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不但</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>新鲜</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>而且</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>便宜</b></span></div><div class=\"fx-ex zh\">水果不但新鲜，而且便宜。</div><div class=\"fx-lbl\">Khác chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>不但</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>我去</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>而且</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>他也去</b></span></div><div class=\"fx-ex zh\">不但我去，而且他也去。</div></div><p class=\"gr-key\">Cùng chủ ngữ: <b>CN + 不但</b>　·　khác chủ ngữ: <b>不但 + CN₁ …，而且 + CN₂ + 也</b>　·　vế 2 hay thêm <b>还 / 也</b></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">现在的电视不但便宜，而且用着非常方便。</span> = Tivi bây giờ không những rẻ mà dùng còn rất tiện.</p>","note":"<b>Lưu ý:</b> Cùng chủ ngữ: ✗ <span class=\"zh\">不但他会说汉语，而且会写</span> → ✓ <span class=\"zh\">他不但会说汉语，而且会写</span>","examples":[{"zh":"现在的电视不但便宜，而且用着非常方便。","py":"Xiànzài de diànshì búdàn piányi, érqiě yòngzhe fēicháng fāngbiàn.","vi":"Tivi bây giờ không những rẻ mà dùng còn rất tiện."},{"zh":"家月不但喜欢唱歌，而且唱得很好听。","py":"Jiāyuè búdàn xǐhuan chàng gē, érqiě chàng de hěn hǎotīng.","vi":"Gia Nguyệt không những thích hát mà còn hát rất hay."},{"zh":"不但家月会说汉语，而且天中也会说汉语。","py":"Búdàn Jiāyuè huì shuō Hànyǔ, érqiě Tiānzhōng yě huì shuō Hànyǔ.","vi":"Không những Gia Nguyệt biết nói tiếng Trung mà Thiên Trung cũng biết."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在家里","titleVi":"Ở nhà — bàn chuyện mua xe đạp mới","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"这辆自行车是小雪八岁的时候买的，看起来有点儿旧了。","py":"Zhè liàng zìxíngchē shì Xiǎoxuě bā suì de shíhou mǎi de, kàn qǐlai yǒudiǎnr jiù le.","vi":"Chiếc xe đạp này mua hồi Tiểu Tuyết tám tuổi, trông hơi cũ rồi."},{"speaker":"明","name":"Lưu Minh","zh":"是啊，她现在长高了，这辆车已经太矮了。","py":"Shì a, tā xiànzài zhǎnggāo le, zhè liàng chē yǐjīng tài ǎi le.","vi":"Ừ, giờ con bé cao lên rồi, chiếc xe này đã quá thấp."},{"speaker":"雪","name":"Nhất Tuyết","zh":"商场里开了一家自行车店，咱们给她买辆新的吧。","py":"Shāngchǎng li kāile yì jiā zìxíngchē diàn, zánmen gěi tā mǎi liàng xīn de ba.","vi":"Trung tâm thương mại mới mở một cửa hàng xe đạp, mình mua cho con chiếc mới nhé."},{"speaker":"明","name":"Lưu Minh","zh":"好，咱们带小雪一起去，让她试一下。","py":"Hǎo, zánmen dài Xiǎoxuě yìqǐ qù, ràng tā shì yíxià.","vi":"Được, mình dẫn Tiểu Tuyết đi cùng, cho con thử luôn."},{"speaker":"雪","name":"Nhất Tuyết","zh":"那今天就去吧！我也想再看看衣服。咱们怎么去？","py":"Nà jīntiān jiù qù ba! Wǒ yě xiǎng zài kànkan yīfu. Zánmen zěnme qù?","vi":"Vậy đi luôn hôm nay đi! Em cũng muốn xem thêm quần áo. Mình đi bằng gì?"},{"speaker":"明","name":"Lưu Minh","zh":"商场不远，咱们可以走着去。","py":"Shāngchǎng bù yuǎn, zánmen kěyǐ zǒuzhe qù.","vi":"Trung tâm thương mại không xa, mình có thể đi bộ."}]},{"titleZh":"课文二 · 在商场","titleVi":"Trung tâm thương mại — chọn quần áo","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"你看我穿这条黄色的短裤好看吗？","py":"Nǐ kàn wǒ chuān zhè tiáo huángsè de duǎnkù hǎokàn ma?","vi":"Anh xem em mặc chiếc quần soóc màu vàng này có đẹp không?"},{"speaker":"明","name":"Lưu Minh","zh":"大小合适，但我觉得那条裙子比短裤更好看。","py":"Dàxiǎo héshì, dàn wǒ juéde nà tiáo qúnzi bǐ duǎnkù gèng hǎokàn.","vi":"Cỡ thì vừa, nhưng anh thấy chiếc váy kia đẹp hơn quần soóc."},{"speaker":"雪","name":"Nhất Tuyết","zh":"裙子比短裤贵一点儿。","py":"Qúnzi bǐ duǎnkù guì yìdiǎnr.","vi":"Váy đắt hơn quần soóc một chút."},{"speaker":"明","name":"Lưu Minh","zh":"贵多少？","py":"Guì duōshao?","vi":"Đắt hơn bao nhiêu?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"裙子480，短裤400。","py":"Qúnzi sìbǎi bāshí, duǎnkù sìbǎi.","vi":"Váy 480, quần soóc 400."},{"speaker":"明","name":"Lưu Minh","zh":"裙子不比短裤贵多少，还是买裙子吧，你穿裙子更好看。","py":"Qúnzi bù bǐ duǎnkù guì duōshao, háishi mǎi qúnzi ba, nǐ chuān qúnzi gèng hǎokàn.","vi":"Váy cũng chẳng đắt hơn bao nhiêu, mua váy đi, em mặc váy đẹp hơn."},{"speaker":"雪","name":"Nhất Tuyết","zh":"我多看看再决定。你看，那边有买二送一！","py":"Wǒ duō kànkan zài juédìng. Nǐ kàn, nàbiān yǒu mǎi èr sòng yī!","vi":"Em xem thêm rồi quyết định. Anh xem, bên kia có mua hai tặng một kìa!"}]},{"titleZh":"课文三 · 在商店","titleVi":"Cửa hàng — Nhất Tuyết mua hoa quả","lines":[{"speaker":"店","name":"Người bán","zh":"西瓜又大又新鲜，不甜不要钱！","py":"Xīguā yòu dà yòu xīnxiān, bù tián bú yào qián!","vi":"Dưa hấu vừa to vừa tươi, không ngọt không lấy tiền!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"西瓜看起来不错，怎么卖？","py":"Xīguā kàn qǐlai búcuò, zěnme mài?","vi":"Dưa hấu trông được đấy, bán thế nào?"},{"speaker":"店","name":"Người bán","zh":"五块钱一公斤。来，您先尝尝这块冰西瓜，甜极了！","py":"Wǔ kuài qián yì gōngjīn. Lái, nín xiān chángchang zhè kuài bīng xīguā, tián jí le!","vi":"Năm tệ một cân (kg). Nào, chị nếm miếng dưa ướp lạnh này trước đi, ngọt lắm luôn!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"是挺甜的！帮我选个大点儿的，再来两斤香蕉。","py":"Shì tǐng tián de! Bāng wǒ xuǎn ge dà diǎnr de, zài lái liǎng jīn xiāngjiāo.","vi":"Ngọt thật! Chọn giúp tôi quả to to một chút, thêm hai cân (jin) chuối nữa."},{"speaker":"店","name":"Người bán","zh":"一共五十八块五毛。","py":"Yígòng wǔshíbā kuài wǔ máo.","vi":"Tổng cộng năm mươi tám tệ năm hào."},{"speaker":"雪","name":"Nhất Tuyết","zh":"我买了这么多，便宜点儿吧。","py":"Wǒ mǎile zhème duō, piányi diǎnr ba.","vi":"Tôi mua nhiều thế này, bớt chút đi."},{"speaker":"店","name":"Người bán","zh":"您给我五十五吧，不能再便宜了。","py":"Nín gěi wǒ wǔshíwǔ ba, bù néng zài piányi le.","vi":"Chị đưa tôi năm mươi lăm thôi, không bớt được nữa đâu."}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — Lưu Minh đang xem tivi","para":true,"speaker":"明","lines":[{"zh":"这几天我们在新家坐着看电视的时候，又发现了新问题。","py":"Zhè jǐ tiān wǒmen zài xīn jiā zuòzhe kàn diànshì de shíhou, yòu fāxiànle xīn wèntí.","vi":"Mấy hôm nay lúc ngồi xem tivi ở nhà mới, chúng tôi lại phát hiện ra vấn đề mới."},{"zh":"房子大了，电视看起来就有点儿小。","py":"Fángzi dà le, diànshì kàn qǐlai jiù yǒudiǎnr xiǎo.","vi":"Nhà rộng ra, cái tivi trông có vẻ hơi nhỏ."},{"zh":"这个电视是我们结婚时买的，是时候换个新电视了。","py":"Zhège diànshì shì wǒmen jiéhūn shí mǎi de, shì shíhou huàn ge xīn diànshì le.","vi":"Cái tivi này mua từ hồi chúng tôi cưới, đã đến lúc đổi tivi mới rồi."},{"zh":"今天我一直在网上选电视，没想到，现在的电视不但便宜，而且用着非常方便，有的电视叫它一声就能开机。","py":"Jīntiān wǒ yìzhí zài wǎngshang xuǎn diànshì, méi xiǎngdào, xiànzài de diànshì búdàn piányi, érqiě yòngzhe fēicháng fāngbiàn, yǒude diànshì jiào tā yì shēng jiù néng kāijī.","vi":"Hôm nay tôi chọn tivi trên mạng suốt, không ngờ tivi bây giờ không những rẻ mà dùng còn rất tiện, có loại chỉ cần gọi một tiếng là bật lên."},{"zh":"我看了好几个，都很满意，晚上让一雪来决定吧。","py":"Wǒ kànle hǎo jǐ ge, dōu hěn mǎnyì, wǎnshang ràng Yīxuě lái juédìng ba.","vi":"Tôi xem mấy cái rồi, cái nào cũng ưng, tối để Nhất Tuyết quyết định vậy."}]}]},"extra":[],"activity":{"act":[{"zh":"猜猜他是谁","py":"cāicai tā shì shéi","tag":"Trò chơi đoán người","mean":"Ảnh 1 · Trong quán cà phê","q":{"zh":"用\"着\"描述照片中的一个人，其他同学猜猜是谁。","py":"Yòng \"zhe\" miáoshù zhàopiàn zhōng de yí ge rén, qítā tóngxué cāicai shì shéi.","vi":"Dùng 着 tả một người trong ảnh, các bạn khác đoán xem là ai."},"items":[{"zh":"他穿着一件白衣服。","py":"Tā chuānzhe yí jiàn bái yīfu.","vi":"Anh ấy mặc một chiếc áo trắng."},{"zh":"他跟朋友一起坐着聊天儿。","py":"Tā gēn péngyou yìqǐ zuòzhe liáotiānr.","vi":"Anh ấy ngồi trò chuyện cùng bạn bè."},{"zh":"她手里拿着一本书。","py":"Tā shǒu li názhe yì běn shū.","vi":"Cô ấy đang cầm một quyển sách."},{"zh":"她坐着跟朋友聊天儿。","py":"Tā zuòzhe gēn péngyou liáotiānr.","vi":"Cô ấy ngồi trò chuyện với bạn bè."},{"zh":"她穿着一件白衣服，笑着看旁边的朋友。","py":"Tā chuānzhe yí jiàn bái yīfu, xiàozhe kàn pángbiān de péngyou.","vi":"Cô ấy mặc áo trắng, cười nhìn người bạn bên cạnh."},{"zh":"她笑着跟朋友说话。","py":"Tā xiàozhe gēn péngyou shuōhuà.","vi":"Cô ấy cười nói chuyện với bạn bè."},{"zh":"她站着，穿着一件红色的衣服。","py":"Tā zhànzhe, chuānzhe yí jiàn hóngsè de yīfu.","vi":"Cô ấy đang đứng, mặc chiếc áo màu đỏ."},{"zh":"他在沙发上坐着。","py":"Tā zài shāfā shang zuòzhe.","vi":"Anh ấy đang ngồi trên sofa."},{"zh":"他手里拿着手机。","py":"Tā shǒu li názhe shǒujī.","vi":"Anh ấy đang cầm điện thoại."},{"zh":"他穿着一件蓝色的衬衫，笑着看手机。","py":"Tā chuānzhe yí jiàn lánsè de chènshān, xiàozhe kàn shǒujī.","vi":"Anh ấy mặc áo sơ mi xanh, cười nhìn điện thoại."},{"zh":"他坐着听朋友说话。","py":"Tā zuòzhe tīng péngyou shuōhuà.","vi":"Anh ấy ngồi nghe bạn nói."},{"zh":"他里面穿着一件白衣服。","py":"Tā lǐmiàn chuānzhe yí jiàn bái yīfu.","vi":"Bên trong anh ấy mặc một chiếc áo trắng."},{"zh":"他外面穿着一件黑衣服，坐在两个女孩子中间。","py":"Tā wàimiàn chuānzhe yí jiàn hēi yīfu, zuò zài liǎng ge nǚháizi zhōngjiān.","vi":"Bên ngoài anh ấy mặc áo đen, ngồi giữa hai bạn nữ."}]},{"zh":"猜猜他是谁","py":"cāicai tā shì shéi","tag":"Trò chơi đoán người","mean":"Ảnh 2 · Đi dạo trên phố","q":{"zh":"用\"着\"描述照片中的一个人，其他同学猜猜是谁。","py":"Yòng \"zhe\" miáoshù zhàopiàn zhōng de yí ge rén, qítā tóngxué cāicai shì shéi.","vi":"Dùng 着 tả một người trong ảnh, các bạn khác đoán xem là ai."},"items":[{"zh":"他穿着一件白衣服。","py":"Tā chuānzhe yí jiàn bái yīfu.","vi":"Anh ấy mặc một chiếc áo trắng."},{"zh":"他跟朋友一起坐着聊天儿。","py":"Tā gēn péngyou yìqǐ zuòzhe liáotiānr.","vi":"Anh ấy ngồi trò chuyện cùng bạn bè."},{"zh":"她手里拿着一杯饮料。","py":"Tā shǒu li názhe yì bēi yǐnliào.","vi":"Cô ấy đang cầm một cốc đồ uống."},{"zh":"她笑着往前走。","py":"Tā xiàozhe wǎng qián zǒu.","vi":"Cô ấy vừa cười vừa đi về phía trước."},{"zh":"她穿着一件蓝色的衣服，戴着帽子。","py":"Tā chuānzhe yí jiàn lánsè de yīfu, dàizhe màozi.","vi":"Cô ấy mặc đồ màu xanh, đội mũ."},{"zh":"他笑着看旁边的朋友。","py":"Tā xiàozhe kàn pángbiān de péngyou.","vi":"Anh ấy cười nhìn người bạn bên cạnh."},{"zh":"他手里拿着一杯咖啡。","py":"Tā shǒu li názhe yì bēi kāfēi.","vi":"Anh ấy đang cầm một cốc cà phê."},{"zh":"他穿着一件蓝色的衬衫，站在最右边。","py":"Tā chuānzhe yí jiàn lánsè de chènshān, zhàn zài zuì yòubian.","vi":"Anh ấy mặc sơ mi xanh, đứng ngoài cùng bên phải."},{"zh":"他手里拿着一杯饮料。","py":"Tā shǒu li názhe yì bēi yǐnliào.","vi":"Anh ấy đang cầm một cốc đồ uống."},{"zh":"他笑着看旁边的女孩子。","py":"Tā xiàozhe kàn pángbiān de nǚháizi.","vi":"Anh ấy cười nhìn bạn nữ bên cạnh."},{"zh":"他穿着一件黑色的衣服。","py":"Tā chuānzhe yí jiàn hēisè de yīfu.","vi":"Anh ấy mặc chiếc áo màu đen."},{"zh":"他看着右边的朋友说话。","py":"Tā kànzhe yòubian de péngyou shuōhuà.","vi":"Anh ấy nhìn người bạn bên phải mà nói chuyện."},{"zh":"她笑着跟朋友说话。","py":"Tā xiàozhe gēn péngyou shuōhuà.","vi":"Cô ấy cười nói chuyện với bạn bè."},{"zh":"她穿着一件白衬衫。","py":"Tā chuānzhe yí jiàn bái chènshān.","vi":"Cô ấy mặc một chiếc sơ mi trắng."},{"zh":"她手里拿着一个相机。","py":"Tā shǒu li názhe yí ge xiàngjī.","vi":"Cô ấy đang cầm một chiếc máy ảnh."}]}],"speak":[]}},{"id":"k3v3-b08","courseId":"k3v3","order":8,"title":"Hôm nay tôi ra viện rồi","titleZh":"今天我出院了","titlePy":"jīntiān wǒ chūyuàn le","vocab":[{"stt":1,"hanzi":"最近","pinyin":"zuìjìn","hanviet":"Tối cận","pos":"Danh từ","meaning":"gần đây, dạo này","comps":"最近很忙 (dạo này rất bận), 最近一次 (lần gần đây nhất)","example":{"zh":"你最近怎么样？工作忙吗？","py":"Nǐ zuìjìn zěnmeyàng? Gōngzuò máng ma?","vi":"Dạo này bạn thế nào? Công việc bận không?"}},{"stt":2,"hanzi":"常","pinyin":"cháng","hanviet":"Thường","pos":"Phó từ","meaning":"thường, hay","comps":"常来 (hay đến), 不常去 (không hay đi)","example":{"zh":"周末我常跟朋友去爬山。","py":"Zhōumò wǒ cháng gēn péngyou qù pá shān.","vi":"Cuối tuần mình hay đi leo núi với bạn."}},{"stt":3,"hanzi":"体育馆","pinyin":"tǐyùguǎn","hanviet":"Thể dục quán","pos":"Danh từ","meaning":"nhà thi đấu, nhà thể thao","comps":"学校的体育馆 (nhà thi đấu của trường), 去体育馆 (đến nhà thi đấu)","example":{"zh":"学校的体育馆很大，下课以后人很多。","py":"Xuéxiào de tǐyùguǎn hěn dà, xiàkè yǐhòu rén hěn duō.","vi":"Nhà thi đấu của trường rất rộng, tan học rất đông người."}},{"stt":4,"hanzi":"习惯","pinyin":"xíguàn","hanviet":"Tập quán","pos":"Danh từ / Động từ","meaning":"thói quen; quen với","comps":"好习惯 (thói quen tốt), 习惯了 (quen rồi)","example":{"zh":"我已经习惯了这里的天气。","py":"Wǒ yǐjīng xíguànle zhèli de tiānqì.","vi":"Mình đã quen với thời tiết ở đây rồi."}},{"stt":5,"hanzi":"胖","pinyin":"pàng","hanviet":"Bàn","pos":"Tính từ","meaning":"béo, mập","comps":"有点儿胖 (hơi béo), 胖了五斤 (béo lên năm cân)","example":{"zh":"过了一个春节，我胖了不少。","py":"Guòle yí ge Chūnjié, wǒ pàngle bù shǎo.","vi":"Qua một cái Tết, mình béo lên không ít."}},{"stt":6,"hanzi":"健康","pinyin":"jiànkāng","hanviet":"Kiện khang","pos":"Tính từ","meaning":"khoẻ mạnh, lành mạnh","comps":"身体健康 (cơ thể khoẻ mạnh), 健康的习惯 (thói quen lành mạnh)","example":{"zh":"祝你身体健康！","py":"Zhù nǐ shēntǐ jiànkāng!","vi":"Chúc bạn sức khoẻ dồi dào!"}},{"stt":7,"hanzi":"以后","pinyin":"yǐhòu","hanviet":"Dĩ hậu","pos":"Danh từ","meaning":"sau khi, sau này","comps":"下课以后 (sau khi tan học), 以后再说 (sau này hãy tính)","example":{"zh":"我下班以后去超市买东西。","py":"Wǒ xiàbān yǐhòu qù chāoshì mǎi dōngxi.","vi":"Tan làm mình đi siêu thị mua đồ."}},{"stt":8,"hanzi":"羽毛球","pinyin":"yǔmáoqiú","hanviet":"Vũ mao cầu","pos":"Danh từ","meaning":"cầu lông","comps":"打羽毛球 (đánh cầu lông), 羽毛球比赛 (thi đấu cầu lông)","example":{"zh":"周末我常和姐姐打羽毛球。","py":"Zhōumò wǒ cháng hé jiějie dǎ yǔmáoqiú.","vi":"Cuối tuần mình hay đánh cầu lông với chị."}},{"stt":9,"hanzi":"耳朵","pinyin":"ěrduo","hanviet":"Nhĩ đoá","pos":"Danh từ","meaning":"tai","comps":"耳朵疼 (đau tai), 两只耳朵 (hai cái tai)","example":{"zh":"游完泳以后，我的耳朵有点儿不舒服。","py":"Yóuwán yǒng yǐhòu, wǒ de ěrduo yǒudiǎnr bù shūfu.","vi":"Bơi xong, tai mình hơi khó chịu."}},{"stt":10,"hanzi":"感冒","pinyin":"gǎnmào","hanviet":"Cảm mạo","pos":"Động từ / Danh từ","meaning":"bị cảm; cảm cúm","comps":"感冒了 (bị cảm rồi), 小心感冒 (cẩn thận kẻo cảm)","example":{"zh":"天冷了，多穿点儿衣服，别感冒了。","py":"Tiān lěng le, duō chuān diǎnr yīfu, bié gǎnmào le.","vi":"Trời lạnh rồi, mặc thêm áo vào, đừng để bị cảm."}},{"stt":11,"hanzi":"发烧","pinyin":"fāshāo","hanviet":"Phát thiêu","pos":"Động từ (li hợp)","meaning":"sốt","comps":"发高烧 (sốt cao), 发低烧 (sốt nhẹ)","example":{"zh":"孩子发烧了，我得带她去医院。","py":"Háizi fāshāo le, wǒ děi dài tā qù yīyuàn.","vi":"Con bị sốt rồi, mình phải đưa con đi viện."}},{"stt":12,"hanzi":"低","pinyin":"dī","hanviet":"Đê","pos":"Tính từ","meaning":"thấp","comps":"很低 (rất thấp), 低一点儿 (thấp hơn chút)","example":{"zh":"今天的气温很低，出门要多穿点儿。","py":"Jīntiān de qìwēn hěn dī, chūmén yào duō chuān diǎnr.","vi":"Nhiệt độ hôm nay rất thấp, ra ngoài nhớ mặc thêm."}},{"stt":13,"hanzi":"关心","pinyin":"guānxīn","hanviet":"Quan tâm","pos":"Động từ","meaning":"quan tâm","comps":"关心朋友 (quan tâm bạn bè), 谢谢关心 (cảm ơn đã quan tâm)","example":{"zh":"妈妈很关心我的学习。","py":"Māma hěn guānxīn wǒ de xuéxí.","vi":"Mẹ rất quan tâm đến việc học của mình."}},{"stt":14,"hanzi":"注意","pinyin":"zhùyì","hanviet":"Chú ý","pos":"Động từ","meaning":"chú ý, để ý","comps":"注意身体 (giữ gìn sức khoẻ), 注意安全 (chú ý an toàn)","example":{"zh":"最近天气变化大，你要注意身体。","py":"Zuìjìn tiānqì biànhuà dà, nǐ yào zhùyì shēntǐ.","vi":"Dạo này thời tiết thay đổi nhiều, bạn nhớ giữ gìn sức khoẻ."}},{"stt":15,"hanzi":"突然","pinyin":"tūrán","hanviet":"Đột nhiên","pos":"Tính từ","meaning":"đột ngột, bỗng nhiên","comps":"很突然 (rất đột ngột), 突然下雨了 (bỗng nhiên mưa)","example":{"zh":"我们正在上课，突然停电了。","py":"Wǒmen zhèngzài shàngkè, tūrán tíngdiàn le.","vi":"Chúng mình đang học thì bỗng nhiên mất điện."}},{"stt":16,"hanzi":"住院","pinyin":"zhùyuàn","hanviet":"Trú viện","pos":"Động từ (li hợp)","meaning":"nằm viện","comps":"住院检查 (nằm viện kiểm tra), 住了三天院 (nằm viện ba ngày)","example":{"zh":"奶奶住院了，我们每天去看她。","py":"Nǎinai zhùyuàn le, wǒmen měi tiān qù kàn tā.","vi":"Bà nằm viện rồi, ngày nào chúng mình cũng đến thăm."}},{"stt":17,"hanzi":"担心","pinyin":"dānxīn","hanviet":"Đảm tâm","pos":"Động từ","meaning":"lo lắng","comps":"别担心 (đừng lo), 担心孩子 (lo cho con)","example":{"zh":"这么晚了他还没回家，妈妈很担心。","py":"Zhème wǎn le tā hái méi huí jiā, māma hěn dānxīn.","vi":"Muộn thế này anh ấy vẫn chưa về, mẹ rất lo."}},{"stt":18,"hanzi":"腿","pinyin":"tuǐ","hanviet":"Thoái","pos":"Danh từ","meaning":"chân, cẳng chân","comps":"腿疼 (đau chân), 两条腿 (hai cái chân)","example":{"zh":"爬了一天山，我的腿很疼。","py":"Pále yì tiān shān, wǒ de tuǐ hěn téng.","vi":"Leo núi cả ngày, chân mình đau lắm."}},{"stt":19,"hanzi":"病人","pinyin":"bìngrén","hanviet":"Bệnh nhân","pos":"Danh từ","meaning":"bệnh nhân, người bệnh","comps":"看病人 (thăm người bệnh), 很多病人 (nhiều bệnh nhân)","example":{"zh":"医院里的病人很多，我们等了很久。","py":"Yīyuàn li de bìngrén hěn duō, wǒmen děngle hěn jiǔ.","vi":"Bệnh viện đông bệnh nhân, chúng mình đợi rất lâu."}},{"stt":20,"hanzi":"差不多","pinyin":"chàbuduō","hanviet":"Sai bất đa","pos":"Phó từ / Tính từ","meaning":"gần như, khoảng; xấp xỉ","comps":"差不多两年 (gần hai năm), 差不多大 (to xấp xỉ nhau)","example":{"zh":"我们俩的个子差不多高。","py":"Wǒmen liǎ de gèzi chàbuduō gāo.","vi":"Hai đứa mình cao xấp xỉ nhau."}},{"stt":21,"hanzi":"得","pinyin":"děi","hanviet":"Đắc","pos":"Trợ động từ","meaning":"phải, cần phải","comps":"得去 (phải đi), 得早点儿起床 (phải dậy sớm)","example":{"zh":"太晚了，我得回家了。","py":"Tài wǎn le, wǒ děi huí jiā le.","vi":"Muộn quá rồi, mình phải về nhà thôi."}},{"stt":22,"hanzi":"开心","pinyin":"kāixīn","hanviet":"Khai tâm","pos":"Tính từ","meaning":"vui vẻ, vui","comps":"很开心 (rất vui), 玩得很开心 (chơi rất vui)","example":{"zh":"收到你的礼物，我非常开心。","py":"Shōudào nǐ de lǐwù, wǒ fēicháng kāixīn.","vi":"Nhận được quà của bạn, mình vui lắm."}},{"stt":23,"hanzi":"出院","pinyin":"chūyuàn","hanviet":"Xuất viện","pos":"Động từ (li hợp)","meaning":"ra viện, xuất viện","comps":"出院了 (ra viện rồi), 出院以后 (sau khi ra viện)","example":{"zh":"医生说他下个星期就能出院。","py":"Yīshēng shuō tā xià ge xīngqī jiù néng chūyuàn.","vi":"Bác sĩ nói tuần sau anh ấy có thể ra viện."}},{"stt":24,"hanzi":"开","pinyin":"kāi","hanviet":"Khai","pos":"Động từ","meaning":"kê (đơn thuốc)","comps":"开药 (kê thuốc), 开了几种药 (kê mấy loại thuốc)","example":{"zh":"医生给我开了一点儿感冒药。","py":"Yīshēng gěi wǒ kāile yìdiǎnr gǎnmàoyào.","vi":"Bác sĩ kê cho mình một ít thuốc cảm."}},{"stt":25,"hanzi":"种","pinyin":"zhǒng","hanviet":"Chủng","pos":"Lượng từ","meaning":"loại, kiểu","comps":"这种药 (loại thuốc này), 很多种水果 (nhiều loại hoa quả)","example":{"zh":"这种水果我从来没吃过。","py":"Zhè zhǒng shuǐguǒ wǒ cónglái méi chīguo.","vi":"Loại hoa quả này mình chưa ăn bao giờ."}},{"stt":26,"hanzi":"方法","pinyin":"fāngfǎ","hanviet":"Phương pháp","pos":"Danh từ","meaning":"phương pháp, cách","comps":"学习方法 (phương pháp học), 好方法 (cách hay)","example":{"zh":"你有什么学汉语的好方法？","py":"Nǐ yǒu shénme xué Hànyǔ de hǎo fāngfǎ?","vi":"Bạn có cách học tiếng Hán nào hay không?"}},{"stt":27,"hanzi":"其他","pinyin":"qítā","hanviet":"Kỳ tha","pos":"Đại từ","meaning":"khác, (những) cái khác","comps":"其他人 (những người khác), 其他东西 (đồ khác)","example":{"zh":"我只喜欢喝茶，其他饮料都不喝。","py":"Wǒ zhǐ xǐhuan hē chá, qítā yǐnliào dōu bù hē.","vi":"Mình chỉ thích uống trà, đồ uống khác đều không uống."}},{"stt":28,"hanzi":"心里","pinyin":"xīnli","hanviet":"Tâm lý","pos":"Danh từ","meaning":"trong lòng","comps":"记在心里 (ghi nhớ trong lòng), 心里很高兴 (trong lòng rất vui)","example":{"zh":"老师的话我都记在心里了。","py":"Lǎoshī de huà wǒ dōu jì zài xīnli le.","vi":"Lời cô dặn em đều ghi nhớ trong lòng rồi."}}],"hanzi":[{"char":"最近","pinyin":"zuìjìn","hanviet":"Tối cận","chars":["最","近"],"story":"最 = 曰 + 取 (lấy) → lấy cái đứng đầu → nhất. 近 = 辶 (đi) + 斤 chỉ âm → đường đi ngắn → gần. 最近 = gần nhất về thời gian → dạo gần đây. Chỉ khoảng cách thì nói 很近."},{"char":"常","pinyin":"cháng","hanviet":"Thường","chars":["常"],"story":"常 = 尚 chỉ âm + 巾 (tấm vải) → tấm vải dài dùng hằng ngày → thường. 常 = 常常 = 经常. Phủ định nói 不常, không nói 不常常."},{"char":"体育馆","pinyin":"tǐyùguǎn","hanviet":"Thể dục quán","chars":["体","育","馆"],"story":"体 = 亻 + 本 → thân người. 育 = nuôi dạy. 馆 = 饣 + 官 → ngôi nhà lớn công cộng: 图书馆, 饭馆. 体育馆 = nhà để rèn luyện thân thể → nhà thi đấu."},{"char":"习惯","pinyin":"xíguàn","hanviet":"Tập quán","chars":["习","惯"],"story":"习 vẽ đôi cánh chim non tập bay → luyện tập. 惯 = 忄 (lòng) + 贯 (xuyên suốt) → làm mãi lòng đã quen. Danh từ: 好习惯; động từ: 习惯了这里的生活."},{"char":"胖","pinyin":"pàng","hanviet":"Bàn","chars":["胖"],"story":"胖 = 月 (thịt) + 半 chỉ âm → người nhiều thịt → béo. Trái nghĩa 瘦 (bài 1). 胖了十多斤 = béo lên hơn chục cân (1 斤 = nửa kg)."},{"char":"健康","pinyin":"jiànkāng","hanviet":"Kiện khang","chars":["健","康"],"story":"健 = 亻 + 建 (dựng) → người dựng vững → khoẻ. 康 = yên ổn. 健康 = khoẻ mạnh, lành mạnh: 身体健康, 健康的生活习惯. Lời chúc quen thuộc: 祝你身体健康！"},{"char":"以后","pinyin":"yǐhòu","hanviet":"Dĩ hậu","chars":["以","后"],"story":"以 = lấy làm mốc, 后 = sau → sau mốc đó. Sau sự việc: 下课以后 (tan học xong); đứng đầu câu: 以后 = sau này. Dạng gọn 后: 饭后, 下班后 (ngữ pháp 4)."},{"char":"羽毛球","pinyin":"yǔmáoqiú","hanviet":"Vũ mao cầu","chars":["羽","毛","球"],"story":"羽 vẽ hai chiếc lông vũ. 毛 = lông. 球 = 王 (ngọc) + 求 chỉ âm → quả bóng. 羽毛球 = quả cầu cắm lông → cầu lông; động từ đi kèm là 打."},{"char":"耳朵","pinyin":"ěrduo","hanviet":"Nhĩ đoá","chars":["耳","朵"],"story":"耳 vẽ cái tai có vành. 朵 = bông hoa (lượng từ 一朵花) — vành tai xoè như cánh hoa. 朵 trong 耳朵 đọc nhẹ duo."},{"char":"感冒","pinyin":"gǎnmào","hanviet":"Cảm mạo","chars":["感","冒"],"story":"感 = 咸 + 心 → lòng cảm thấy. 冒 = 冃 (mũ trùm) + 目 → bị gió lạnh xâm vào. Động từ: 我感冒了; danh từ: 这次感冒很厉害."},{"char":"发烧","pinyin":"fāshāo","hanviet":"Phát thiêu","chars":["发","烧"],"story":"发 = phát ra. 烧 = 火 (lửa) + 尧 chỉ âm → đốt nóng. 发烧 = người phát nóng → sốt. Là từ ly hợp: 发低烧, 发高烧, 发了三天烧."},{"char":"低","pinyin":"dī","hanviet":"Đê","chars":["低"],"story":"低 = 亻 + 氐 (đáy) → người ở chỗ thấp → thấp. Dùng cho nhiệt độ, giọng, trình độ: 低烧, 气温低. Người thấp bé dùng 矮."},{"char":"关心","pinyin":"guānxīn","hanviet":"Quan tâm","chars":["关","心"],"story":"关 = then cửa → liên quan, gắn với. 心 = tim, lòng. 关心 = để lòng gắn với ai → quan tâm. Đáp lời hỏi thăm: 谢谢关心！"},{"char":"注意","pinyin":"zhùyì","hanviet":"Chú ý","chars":["注","意"],"story":"注 = 氵 + 主 → rót nước dồn vào một chỗ. 意 = 音 + 心 → ý nghĩ. 注意 = dồn ý vào → chú ý: 注意身体, 注意安全, 我会注意的."},{"char":"突然","pinyin":"tūrán","hanviet":"Đột nhiên","chars":["突","然"],"story":"突 = 穴 (hang) + 犬 (chó) → con chó vụt lao ra khỏi hang → đột ngột. 然 = như thế. Làm vị ngữ: 这件事很突然; làm trạng ngữ: 突然下雨了."},{"char":"住院","pinyin":"zhùyuàn","hanviet":"Trú viện","chars":["住","院"],"story":"住 = ở. 院 = 阝 + 完 → khu nhà có tường bao → viện (医院). 住院 = ở lại bệnh viện → nằm viện. Từ ly hợp: 住了三天院."},{"char":"担心","pinyin":"dānxīn","hanviet":"Đảm tâm","chars":["担","心"],"story":"担 = 扌 (tay) + 旦 chỉ âm → gánh vác. 心 = lòng. 担心 = gánh nỗi lo trong lòng → lo lắng: 别担心, 担心你. Trái nghĩa: 放心."},{"char":"腿","pinyin":"tuǐ","hanviet":"Thoái","chars":["腿"],"story":"腿 = 月 (thịt) + 退 (lùi) → phần thân dùng để bước tới lui → chân (từ đùi xuống cổ chân). Bàn chân là 脚. Lượng từ: 一条腿."},{"char":"病人","pinyin":"bìngrén","hanviet":"Bệnh nhân","chars":["病","人"],"story":"病 = 疒 (bộ nạch — bệnh tật) + 丙 chỉ âm → bệnh. 病人 = người bệnh. Các từ đã học: 生病 (bị ốm), 看病 (khám bệnh)."},{"char":"差不多","pinyin":"chàbuduō","hanviet":"Sai bất đa","chars":["差","不","多"],"story":"差 chà = kém, chênh lệch. 不多 = không nhiều → chênh không bao nhiêu → xấp xỉ. Trước số lượng: 差不多两年 (gần hai năm); làm tính từ: 大小差不多."},{"char":"得","pinyin":"děi","hanviet":"Đắc","chars":["得"],"story":"Một chữ ba âm: 得 de (跑得快) · 得 dé (得到) · 得 děi = phải. 得 děi là khẩu ngữ, ≈ 要 / 应该. Phủ định dùng 不用, không nói 不得."},{"char":"开心","pinyin":"kāixīn","hanviet":"Khai tâm","chars":["开","心"],"story":"开 = mở. 心 = lòng → lòng mở ra → vui vẻ. ≈ 高兴: 很开心, 玩得很开心, 开心多了 (vui hơn nhiều)."},{"char":"出院","pinyin":"chūyuàn","hanviet":"Xuất viện","chars":["出","院"],"story":"出 = ra. 院 = viện → ra viện. Cặp trái nghĩa 住院 ↔ 出院. Từ ly hợp: 出了院以后, 出院前."},{"char":"开","pinyin":"kāi","hanviet":"Khai","chars":["开"],"story":"开 vẽ hai tay mở then cửa → mở. Nghĩa bài này: kê đơn — 开药. Ôn nghĩa khác: 开门, 开车, 开机, 开了一家店 (mở cửa hàng)."},{"char":"种","pinyin":"zhǒng","hanviet":"Chủng","chars":["种"],"story":"种 = 禾 (cây lúa) + 中 chỉ âm → giống lúa → loại. Lượng từ: 一种药, 这种水果, 几种. Đọc zhòng khi là động từ \"trồng\" (种树)."},{"char":"方法","pinyin":"fāngfǎ","hanviet":"Phương pháp","chars":["方","法"],"story":"方 = phương, hướng. 法 = 氵 + 去 → phép tắc, cách. 方法 = cách làm: 学习方法, 吃药的方法."},{"char":"其他","pinyin":"qítā","hanviet":"Kỳ tha","chars":["其","他"],"story":"其 = cái ấy. 他 = khác. 其他 = những cái khác ngoài cái vừa nói: 其他几种, 其他人. Hay đi với 都: 其他饮料都不喝."},{"char":"心里","pinyin":"xīnli","hanviet":"Tâm lý","chars":["心","里"],"story":"心 = tim, lòng. 里 = bên trong (đọc nhẹ li). 心里 = trong lòng: 记在心里 (ghi nhớ trong lòng), 心里很高兴."}],"grammar":[{"title":"动词 / 形容词 + 下去","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(再 / 一直)</b><small>nữa / mãi</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词 / 形容词</b><small>ĐT / TT</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>下去</b><small>tiếp tục</small></span></div>","summary":"<p class=\"gr-lead\">Việc đã bắt đầu sẽ còn tiếp tục</p><ul><li><span class=\"zh\">V / TT + 下去</span>: việc / trạng thái <b>đã bắt đầu</b> và còn <b>tiếp tục</b> — không phải \"đi xuống\".</li><li>Hay đi với <span class=\"zh\">再 · 一直</span>: <span class=\"zh\">不能再胖下去了 · 我想一直学下去</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">动词 / 形容词 + 下去</span> · Ba cách dùng thường gặp</h4><p>Tiếp tục làm · tiếp tục như thế</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Động từ + 下去</div><div class=\"fx-row\"><span class=\"fx-p\"><b>后面的</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>你</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>读</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>下去</b></span></div><div class=\"fx-ex zh\">后面的你读下去。</div><div class=\"fx-lbl\">再 + Tính từ + 下去</div><div class=\"fx-row\"><span class=\"fx-p\"><b>不能</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>再</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>胖</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>下去</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b></span></div><div class=\"fx-ex zh\">我不能再胖下去了。</div><div class=\"fx-lbl\">一直 + Động từ + 下去</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>想</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>一直</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>学</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>下去</b></span></div><div class=\"fx-ex zh\">我想一直学下去。</div></div><p class=\"gr-key\">Tính từ + <span class=\"zh\">下去</span> thường nói về điều <b>không muốn</b> tiếp diễn: <span class=\"zh\">再热下去 · 再胖下去</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我不能再胖下去了。</span> = Mình không thể cứ béo thêm mãi nữa.</p>","note":"<b>Lưu ý:</b> Tân ngữ không đứng sau 下去: ✗ <span class=\"zh\">我想学下去汉语</span> → ✓ <span class=\"zh\">汉语我想一直学下去</span>","examples":[{"zh":"我今年胖了十多斤，不能再胖下去了。","py":"Wǒ jīnnián pàngle shí duō jīn, bù néng zài pàng xiàqu le.","vi":"Năm nay mình béo lên hơn chục cân, không thể béo thêm nữa."},{"zh":"她读完了第一个问题，后面的你读下去。","py":"Tā dúwánle dì yī ge wèntí, hòumiàn de nǐ dú xiàqu.","vi":"Cô ấy đọc xong câu thứ nhất, phần sau bạn đọc tiếp."},{"zh":"这几天太热了，如果再热下去就不能出门了。","py":"Zhè jǐ tiān tài rè le, rúguǒ zài rè xiàqu jiù bù néng chūmén le.","vi":"Mấy hôm nay nóng quá, cứ nóng nữa thì khỏi ra ngoài."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">现在她很喜欢汉语，还打算____。</span><span class=\"qz-hint\">Giờ cô ấy rất thích tiếng Hán, còn định học mãi.</span>","answer":["一直学下去","学下去"],"explain":"现在她很喜欢汉语，还打算一直学下去。 (Xiànzài tā hěn xǐhuan Hànyǔ, hái dǎsuàn yìzhí xué xiàqu.)"},{"type":"fill","q":"<span class=\"zh\">这本书太有意思了，我想一直____。</span><span class=\"qz-hint\">Cuốn sách này hay quá, mình muốn đọc tiếp mãi.</span>","answer":["看下去"],"explain":"这本书太有意思了，我想一直看下去。 (Zhè běn shū tài yǒu yìsi le, wǒ xiǎng yìzhí kàn xiàqu.)"},{"type":"fill","q":"<span class=\"zh\">我不想在这里____，下个星期就去找新房子。</span><span class=\"qz-hint\">Mình không muốn ở đây nữa, tuần sau đi tìm nhà mới.</span>","answer":["住下去"],"explain":"我不想在这里住下去，下个星期就去找新房子。 (Wǒ bù xiǎng zài zhèli zhù xiàqu, xià ge xīngqī jiù qù zhǎo xīn fángzi.)"}]},{"title":"离合词：动词部分 + 补语 / 了 / 数量 + 名词部分","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>动词部分</b><small>phần ĐT</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>补语 / 了 / 数量</b><small>chen giữa</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>名词部分</b><small>phần DT</small></span></div>","summary":"<p class=\"gr-lead\">Chen bổ ngữ vào giữa</p><ul><li>Từ ly hợp = <b>động từ + danh từ</b>: <span class=\"zh\">游泳 · 下雨 · 结婚 · 睡觉 · 考试 · 放假 · 发烧</span> → thường <b>không</b> mang tân ngữ.</li><li>Có bổ ngữ / <span class=\"zh\">了</span> / số lượng → <b>chen vào giữa</b>: <span class=\"zh\">游完泳 · 下了两次雨</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">离合词 + 补语 / 了 / 数量</span> · Bốn kiểu thường gặp</h4><p>Chen vào giữa · đối tượng đưa lên trước</p><div class=\"gr-formula\"><div class=\"fx-lbl\">+ bổ ngữ kết quả</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>游</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>完</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>泳</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>以后</b></span></div><div class=\"fx-ex zh\">游完泳以后，耳朵有点儿疼。</div><div class=\"fx-lbl\">+ 了 + số lần</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>下</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了两次</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>雨</b></span></div><div class=\"fx-ex zh\">今年夏天只下了两次雨。</div><div class=\"fx-lbl\">+ số lượng</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>睡</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>一</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>觉</b></span></div><div class=\"fx-ex zh\">我先回去睡一觉。</div><div class=\"fx-lbl\">跟 + Người + ĐT</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>跟</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>他女朋友</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>结婚</b></span></div><div class=\"fx-ex zh\">小张下个月跟他女朋友结婚。</div></div><p class=\"gr-key\">Tra từ điển thấy <span class=\"zh\">游//泳 · 结//婚</span> (có dấu //) là từ ly hợp</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">游完泳 · 下了两次雨 · 睡一觉</span> — phần chen giữa đứng sau phần động từ.</p>","note":"<b>Lưu ý:</b> Đối tượng dùng giới từ đưa lên trước: ✗ <span class=\"zh\">他结婚他女朋友</span> → ✓ <span class=\"zh\">他跟他女朋友结婚</span>","examples":[{"zh":"昨天游完泳以后，我的耳朵一直有点儿疼。","py":"Zuótiān yóuwán yǒng yǐhòu, wǒ de ěrduo yìzhí yǒudiǎnr téng.","vi":"Hôm qua bơi xong, tai mình cứ hơi đau suốt."},{"zh":"今年夏天只下了两次雨。","py":"Jīnnián xiàtiān zhǐ xiàle liǎng cì yǔ.","vi":"Mùa hè năm nay chỉ mưa có hai lần."},{"zh":"小张下个月跟他女朋友结婚。","py":"Xiǎo Zhāng xià ge yuè gēn tā nǚpéngyou jiéhūn.","vi":"Tháng sau Tiểu Trương cưới bạn gái."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">____，我要和朋友去旅游。（考试）</span><span class=\"qz-hint\">Thi xong, mình sẽ đi du lịch với bạn.</span>","answer":["考完试以后","考完试","考了试以后"],"explain":"考完试以后，我要和朋友去旅游。（考试） (Kǎowán shì yǐhòu, wǒ yào hé péngyou qù lǚyóu. (kǎoshì))"},{"type":"fill","q":"<span class=\"zh\">学校____，大家都很高兴。（放假）</span><span class=\"qz-hint\">Trường cho nghỉ một tháng, ai cũng vui.</span>","answer":["放了一个月的假","放了一个月假"],"explain":"学校放了一个月的假，大家都很高兴。（放假） (Xuéxiào fàngle yí ge yuè de jià, dàjiā dōu hěn gāoxìng. (fàngjià))"},{"type":"fill","q":"<span class=\"zh\">天气太热了，我想____，再去吃饭。（洗澡）</span><span class=\"qz-hint\">Trời nóng quá, mình muốn tắm cái đã rồi đi ăn.</span>","answer":["先洗个澡","先洗一个澡","先洗澡"],"explain":"天气太热了，我想先洗个澡，再去吃饭。（洗澡） (Tiānqì tài rè le, wǒ xiǎng xiān xǐ ge zǎo, zài qù chīfàn. (xǐzǎo))"}]},{"title":"动词（不能持续）+ (宾语) + 时量 + 了","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>动词</b><small>không kéo dài</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b><small>tân ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>时量</b><small>thời lượng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b><small>đến nay</small></span></div>","summary":"<p class=\"gr-lead\">Từ khi việc xong đến nay đã bao lâu</p><ul><li>Động từ <b>không kéo dài</b> (<span class=\"zh\">来 · 去 · 回 · 结婚 · 开学</span>…): thời lượng = từ lúc việc <b>xong</b> đến <b>bây giờ</b>.</li><li>Tân ngữ đứng <b>trước</b> thời lượng: <span class=\"zh\">回家两个月了 · 来中国一年了</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">持续 · 不能持续</span> · Hai loại động từ</h4><p>Làm suốt bao lâu · xong được bao lâu</p><div class=\"gr-formula\"><div class=\"fx-lbl\">ĐT kéo dài</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>学</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>两年</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>汉语</b></span></div><div class=\"fx-ex zh\">我学了两年汉语。</div><div class=\"fx-lbl\">ĐT không kéo dài</div><div class=\"fx-row\"><span class=\"fx-p\"><b>她</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>回</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>家</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>两个月</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b></span></div><div class=\"fx-ex zh\">她回家两个月了。</div><div class=\"fx-lbl\">Sự việc + 已经</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>开学</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>已经</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>三个多星期</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b></span></div><div class=\"fx-ex zh\">开学已经三个多星期了。</div><div class=\"fx-lbl\">… 已经过去</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>上次来医院</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>已经过去</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>两年</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b></span></div><div class=\"fx-ex zh\">已经过去差不多两年了。</div></div><p class=\"gr-key\"><span class=\"zh\">他等了两个月</span> = đợi <b>suốt</b> 2 tháng　·　<span class=\"zh\">他回家两个月了</span> = về nhà <b>được</b> 2 tháng</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">她回家两个月了。</span> = Cô ấy về nhà được hai tháng rồi.</p>","note":"<b>Lưu ý:</b> Không chen thời lượng vào giữa: ✗ <span class=\"zh\">她回两个月家了</span> → ✓ <span class=\"zh\">她回家两个月了</span>","examples":[{"zh":"我上次来医院已经过去差不多两年了。","py":"Wǒ shàng cì lái yīyuàn yǐjīng guòqu chàbuduō liǎng nián le.","vi":"Lần trước mình đến bệnh viện đã gần hai năm rồi."},{"zh":"她回家两个月了。","py":"Tā huí jiā liǎng ge yuè le.","vi":"Cô ấy về nhà được hai tháng rồi."},{"zh":"开学已经三个多星期了。","py":"Kāixué yǐjīng sān ge duō xīngqī le.","vi":"Khai giảng đã hơn ba tuần rồi."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">听说你们已经结婚了？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我们是前年结的，已经____。</span></span></span><span class=\"qz-hint\">Nghe nói hai bạn cưới rồi à? — Bọn mình cưới năm kia, đã được hai năm rồi.</span>","answer":["结婚两年了","结婚两年"],"explain":"我们是前年结的，已经结婚两年了。 (Wǒmen shì qiánnián jié de, yǐjīng jiéhūn liǎng nián le.)"}]},{"title":"时间 / 事件 + 以前 / 前 · 以后 / 后","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>时间 / 事件</b><small>mốc</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>以前 · 前</b><small>trước</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>/</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>以后 · 后</b><small>sau</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>，主语 + 动词</b><small>việc chính</small></span></div>","summary":"<p class=\"gr-lead\">Trước khi … · sau khi …</p><ul><li>Mốc là <b>thời gian</b> (<span class=\"zh\">三天以前 · 十点以后</span>) hoặc <b>sự việc</b> (<span class=\"zh\">睡前 · 下班后 · 考完试以后</span>).</li><li><span class=\"zh\">前 / 后</span> gọn hơn, hay ghép với từ ngắn: <span class=\"zh\">睡前 · 饭后 · 出院前</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">以前 · 前 · 以后 · 后</span> · Mốc thời gian · mốc sự việc</h4><p>Đặt sau mốc, khác tiếng Việt</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Thời gian + 以前</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>三天</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>以前</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>，他还在北京</b></span></div><div class=\"fx-ex zh\">三天以前，他还在北京。</div><div class=\"fx-lbl\">Sự việc + 前</div><div class=\"fx-row\"><span class=\"fx-p\"><b>每天</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>睡</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>前</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>吃一次</b></span></div><div class=\"fx-ex zh\">这种药需要每天睡前吃一次。</div><div class=\"fx-lbl\">Sự việc + 后</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>下班</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>后</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>一起去看电影</b></span></div><div class=\"fx-ex zh\">我们决定下班后一起去看个电影。</div><div class=\"fx-lbl\">Sự việc + 以后</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>考完试</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>以后</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>去旅游</b></span></div><div class=\"fx-ex zh\">考完试以后，咱们一起去旅游吧。</div></div><p class=\"gr-key\">Đứng một mình, <span class=\"zh\">以前 / 以后</span> = <b>trước đây / sau này</b>: <span class=\"zh\">我以前很胖 · 以后我会注意</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">出院前，医生给我开了几种药。</span> = Trước khi ra viện, bác sĩ kê cho tôi mấy loại thuốc.</p>","note":"<b>Lưu ý:</b> Ngược trật tự tiếng Việt: \"trước khi ngủ\" → ✓ <span class=\"zh\">睡前</span>, ✗ <span class=\"zh\">以前睡觉</span>","examples":[{"zh":"这种药需要每天睡前吃一次。","py":"Zhè zhǒng yào xūyào měi tiān shuì qián chī yí cì.","vi":"Loại thuốc này mỗi ngày uống một lần trước khi ngủ."},{"zh":"我们决定下班后一起去看个电影。","py":"Wǒmen juédìng xiàbān hòu yìqǐ qù kàn ge diànyǐng.","vi":"Chúng mình quyết định tan làm cùng đi xem phim."},{"zh":"考完试以后，咱们一起去旅游吧。","py":"Kǎowán shì yǐhòu, zánmen yìqǐ qù lǚyóu ba.","vi":"Thi xong, chúng mình cùng đi du lịch nhé."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在学校的体育馆","titleVi":"Nhà thi đấu — Lý Văn gặp Thiên Trung","lines":[{"speaker":"文","name":"Lý Văn","zh":"天中，最近常看见你来体育馆。","py":"Tiānzhōng, zuìjìn cháng kànjiàn nǐ lái tǐyùguǎn.","vi":"Thiên Trung, dạo này hay thấy cậu đến nhà thi đấu thế."},{"speaker":"中","name":"Thiên Trung","zh":"我每天下午都来跑一个小时步。","py":"Wǒ měi tiān xiàwǔ dōu lái pǎo yí ge xiǎoshí bù.","vi":"Chiều nào mình cũng đến chạy bộ một tiếng."},{"speaker":"文","name":"Lý Văn","zh":"你的运动习惯真不错。","py":"Nǐ de yùndòng xíguàn zhēn búcuò.","vi":"Thói quen vận động của cậu tốt thật."},{"speaker":"中","name":"Thiên Trung","zh":"因为我今年胖了十多斤，不能再胖下去了，有点儿不健康。","py":"Yīnwèi wǒ jīnnián pàngle shí duō jīn, bù néng zài pàng xiàqu le, yǒudiǎnr bú jiànkāng.","vi":"Vì năm nay mình béo lên hơn chục cân, không thể béo thêm nữa, hơi không khoẻ rồi."},{"speaker":"文","name":"Lý Văn","zh":"我下课以后常去打羽毛球，你也来玩吧。","py":"Wǒ xiàkè yǐhòu cháng qù dǎ yǔmáoqiú, nǐ yě lái wán ba.","vi":"Tan học mình hay đi đánh cầu lông, cậu cũng đến chơi đi."},{"speaker":"中","name":"Thiên Trung","zh":"我知道，但是你们的水平太高了，我打得不怎么样。","py":"Wǒ zhīdào, dànshì nǐmen de shuǐpíng tài gāo le, wǒ dǎ de bù zěnmeyàng.","vi":"Mình biết, nhưng trình độ các cậu cao quá, mình đánh chẳng ra sao."},{"speaker":"文","name":"Lý Văn","zh":"没关系，我可以教你。","py":"Méi guānxi, wǒ kěyǐ jiāo nǐ.","vi":"Không sao, mình có thể dạy cậu."}]},{"titleZh":"课文二 · 在教室","titleVi":"Lớp học — Annie hỏi thăm Thiên Trung","lines":[{"speaker":"妮","name":"Annie","zh":"你怎么了？看上去有点儿不舒服。","py":"Nǐ zěnme le? Kàn shàngqu yǒudiǎnr bù shūfu.","vi":"Cậu sao thế? Trông có vẻ hơi mệt."},{"speaker":"中","name":"Thiên Trung","zh":"昨天游完泳以后，耳朵一直有点儿疼。","py":"Zuótiān yóuwán yǒng yǐhòu, ěrduo yìzhí yǒudiǎnr téng.","vi":"Hôm qua bơi xong, tai cứ hơi đau suốt."},{"speaker":"妮","name":"Annie","zh":"是不是感冒了？发烧吗？","py":"Shì bu shì gǎnmào le? Fāshāo ma?","vi":"Có phải bị cảm không? Có sốt không?"},{"speaker":"中","name":"Thiên Trung","zh":"好像发低烧了。","py":"Hǎoxiàng fā dīshāo le.","vi":"Hình như sốt nhẹ."},{"speaker":"妮","name":"Annie","zh":"我送你去医院，让医生检查一下吧。","py":"Wǒ sòng nǐ qù yīyuàn, ràng yīshēng jiǎnchá yíxià ba.","vi":"Mình đưa cậu đi bệnh viện, để bác sĩ kiểm tra xem."},{"speaker":"中","name":"Thiên Trung","zh":"我先回去睡一觉，可能休息休息就好了。","py":"Wǒ xiān huíqu shuì yí jiào, kěnéng xiūxi xiūxi jiù hǎo le.","vi":"Mình về ngủ một giấc trước đã, có khi nghỉ chút là khỏi."},{"speaker":"妮","name":"Annie","zh":"好吧，如果下午还发烧，就一定要去看医生。","py":"Hǎo ba, rúguǒ xiàwǔ hái fāshāo, jiù yídìng yào qù kàn yīshēng.","vi":"Thôi được, nếu chiều vẫn sốt thì nhất định phải đi khám bác sĩ."},{"speaker":"中","name":"Thiên Trung","zh":"谢谢关心，我会注意的。","py":"Xièxie guānxīn, wǒ huì zhùyì de.","vi":"Cảm ơn cậu quan tâm, mình sẽ chú ý."}]},{"titleZh":"课文三 · 在医院病房","titleVi":"Bệnh viện — Annie đến thăm bạn","lines":[{"speaker":"妮","name":"Annie","zh":"你怎么突然住院了？大家都很担心你。","py":"Nǐ zěnme tūrán zhùyuàn le? Dàjiā dōu hěn dānxīn nǐ.","vi":"Sao tự nhiên cậu lại nằm viện thế? Mọi người đều rất lo cho cậu."},{"speaker":"中","name":"Thiên Trung","zh":"我的腿疼了几个星期了，医生说需要住院做检查。","py":"Wǒ de tuǐ téngle jǐ ge xīngqī le, yīshēng shuō xūyào zhùyuàn zuò jiǎnchá.","vi":"Chân mình đau mấy tuần rồi, bác sĩ nói cần nằm viện làm kiểm tra."},{"speaker":"妮","name":"Annie","zh":"你看起来一点儿也不像病人。","py":"Nǐ kàn qǐlai yìdiǎnr yě bú xiàng bìngrén.","vi":"Trông cậu chẳng giống bệnh nhân chút nào."},{"speaker":"中","name":"Thiên Trung","zh":"是啊，我很少生病。我上次来医院已经过去差不多两年了。","py":"Shì a, wǒ hěn shǎo shēngbìng. Wǒ shàng cì lái yīyuàn yǐjīng guòqu chàbuduō liǎng nián le.","vi":"Đúng thế, mình ít khi ốm. Lần trước mình đến bệnh viện đã gần hai năm rồi."},{"speaker":"妮","name":"Annie","zh":"你每天跑步，有时候还去游泳，是不是运动太多了？","py":"Nǐ měi tiān pǎobù, yǒu shíhou hái qù yóuyǒng, shì bu shì yùndòng tài duō le?","vi":"Ngày nào cậu cũng chạy bộ, có hôm còn đi bơi, có phải vận động nhiều quá không?"},{"speaker":"中","name":"Thiên Trung","zh":"医生也这么说，但是还得做完检查才能知道。","py":"Yīshēng yě zhème shuō, dànshì hái děi zuòwán jiǎnchá cái néng zhīdào.","vi":"Bác sĩ cũng nói vậy, nhưng còn phải kiểm tra xong mới biết được."},{"speaker":"妮","name":"Annie","zh":"别担心！听医生的话，好好休息，你的腿一定能好。","py":"Bié dānxīn! Tīng yīshēng de huà, hǎohāo xiūxi, nǐ de tuǐ yídìng néng hǎo.","vi":"Đừng lo! Nghe lời bác sĩ, nghỉ ngơi cho tốt, chân cậu nhất định sẽ khỏi."},{"speaker":"中","name":"Thiên Trung","zh":"谢谢。有人来看我，我就开心多了。","py":"Xièxie. Yǒu rén lái kàn wǒ, wǒ jiù kāixīn duō le.","vi":"Cảm ơn cậu. Có người đến thăm, mình vui hơn nhiều rồi."}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — Thiên Trung uống thuốc, nghỉ ngơi","para":true,"speaker":"中","lines":[{"zh":"今天我出院了。","py":"Jīntiān wǒ chūyuàn le.","vi":"Hôm nay tôi ra viện rồi."},{"zh":"出院前，医生给我开了几种药，而且告诉了我吃药的方法。","py":"Chūyuàn qián, yīshēng gěi wǒ kāile jǐ zhǒng yào, érqiě gàosule wǒ chī yào de fāngfǎ.","vi":"Trước khi ra viện, bác sĩ kê cho tôi mấy loại thuốc, còn dặn tôi cách uống thuốc."},{"zh":"有一种药需要每天睡前吃一次，其他几种每天吃三次，饭后吃。","py":"Yǒu yì zhǒng yào xūyào měi tiān shuì qián chī yí cì, qítā jǐ zhǒng měi tiān chī sān cì, fàn hòu chī.","vi":"Có một loại mỗi ngày uống một lần trước khi ngủ, mấy loại khác mỗi ngày uống ba lần, sau bữa ăn."},{"zh":"除了吃药，医生还说最重要的是多休息。","py":"Chúle chī yào, yīshēng hái shuō zuì zhòngyào de shì duō xiūxi.","vi":"Ngoài uống thuốc, bác sĩ còn nói quan trọng nhất là nghỉ ngơi nhiều."},{"zh":"我都记在心里了，回家以后一定会多注意。","py":"Wǒ dōu jì zài xīnli le, huí jiā yǐhòu yídìng huì duō zhùyì.","vi":"Tôi đều ghi nhớ trong lòng rồi, về nhà nhất định sẽ chú ý hơn."},{"zh":"希望我的腿能快一点儿好。","py":"Xīwàng wǒ de tuǐ néng kuài yìdiǎnr hǎo.","vi":"Mong chân tôi mau khỏi."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Phần 1 · Vận động và bị ốm","q":{"zh":"两人一组，谈论生病的经历和健康的生活习惯。","py":"Liǎng rén yì zǔ, tánlùn shēngbìng de jīnglì hé jiànkāng de shēnghuó xíguàn.","vi":"Theo cặp: kể chuyện bị ốm và thói quen sống lành mạnh (dùng từ ly hợp, bổ ngữ thời lượng)."},"items":[{"zh":"你怎么锻炼身体？每周锻炼几次？每次多长时间？","py":"Nǐ zěnme duànliàn shēntǐ? Měi zhōu duànliàn jǐ cì? Měi cì duō cháng shíjiān?","vi":"Bạn rèn luyện thế nào? Mỗi tuần mấy lần? Mỗi lần bao lâu?"},{"zh":"你最近生过病吗？去了几次医院？","py":"Nǐ zuìjìn shēngguo bìng ma? Qùle jǐ cì yīyuàn?","vi":"Gần đây bạn có bị ốm không? Đi viện mấy lần?"},{"zh":"如果发高烧，你会怎么做？","py":"Rúguǒ fā gāoshāo, nǐ huì zěnme zuò?","vi":"Nếu sốt cao, bạn sẽ làm gì?"}]},{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Phần 2 · Nằm viện và sức khoẻ","q":{"zh":"两人一组，谈论生病的经历和健康的生活习惯。","py":"Liǎng rén yì zǔ, tánlùn shēngbìng de jīnglì hé jiànkāng de shēnghuó xíguàn.","vi":"Theo cặp: kể chuyện bị ốm và thói quen sống lành mạnh (dùng từ ly hợp, bổ ngữ thời lượng)."},"items":[{"zh":"你住过院吗？住了几天？为什么？","py":"Nǐ zhùguo yuàn ma? Zhùle jǐ tiān? Wèi shénme?","vi":"Bạn từng nằm viện chưa? Nằm mấy ngày? Vì sao?"},{"zh":"你出院的时候，医生说什么了？","py":"Nǐ chūyuàn de shíhou, yīshēng shuō shénme le?","vi":"Lúc bạn ra viện, bác sĩ dặn gì?"},{"zh":"有人说胖一点儿健康，有人说瘦一点儿好看，你怎么看？","py":"Yǒu rén shuō pàng yìdiǎnr jiànkāng, yǒu rén shuō shòu yìdiǎnr hǎokàn, nǐ zěnme kàn?","vi":"Người bảo béo chút khoẻ, người bảo gầy chút đẹp, bạn nghĩ sao?"}]}],"speak":[]}},{"id":"k3v3-b09","courseId":"k3v3","order":9,"title":"Đánh không giỏi cũng không sao","titleZh":"打不好没关系","titlePy":"dǎ bu hǎo méi guānxi","vocab":[{"stt":1,"hanzi":"校园","pinyin":"xiàoyuán","hanviet":"Hiệu viên","pos":"Danh từ","meaning":"khuôn viên trường","comps":"校园卡 (thẻ trường), 在校园里 (trong khuôn viên trường)","example":{"zh":"我们的校园很漂亮，有很多树和花。","py":"Wǒmen de xiàoyuán hěn piàoliang, yǒu hěn duō shù hé huā.","vi":"Khuôn viên trường mình rất đẹp, có nhiều cây và hoa."}},{"stt":2,"hanzi":"卡","pinyin":"kǎ","hanviet":"Tạp","pos":"Danh từ","meaning":"thẻ","comps":"校园卡 (thẻ trường), 银行卡 (thẻ ngân hàng)","example":{"zh":"进图书馆要用校园卡。","py":"Jìn túshūguǎn yào yòng xiàoyuánkǎ.","vi":"Vào thư viện phải dùng thẻ trường."}},{"stt":3,"hanzi":"球场","pinyin":"qiúchǎng","hanviet":"Cầu trường","pos":"Danh từ","meaning":"sân bóng","comps":"篮球场 (sân bóng rổ), 去球场 (ra sân bóng)","example":{"zh":"下课以后，球场上有很多人在打球。","py":"Xiàkè yǐhòu, qiúchǎng shang yǒu hěn duō rén zài dǎ qiú.","vi":"Tan học, trên sân có rất nhiều người đang chơi bóng."}},{"stt":4,"hanzi":"为了","pinyin":"wèile","hanviet":"Vị liễu","pos":"Giới từ","meaning":"để, vì (chỉ mục đích)","comps":"为了健康 (vì sức khoẻ), 为了考试 (để đi thi)","example":{"zh":"为了身体健康，他每天都去跑步。","py":"Wèile shēntǐ jiànkāng, tā měi tiān dōu qù pǎobù.","vi":"Vì sức khoẻ, ngày nào anh ấy cũng đi chạy bộ."}},{"stt":5,"hanzi":"运动会","pinyin":"yùndònghuì","hanviet":"Vận động hội","pos":"Danh từ","meaning":"đại hội thể thao, hội thao","comps":"学校运动会 (hội thao của trường), 参加运动会 (tham gia hội thao)","example":{"zh":"下个月学校要开运动会。","py":"Xià ge yuè xuéxiào yào kāi yùndònghuì.","vi":"Tháng sau trường sẽ tổ chức hội thao."}},{"stt":6,"hanzi":"男生","pinyin":"nánshēng","hanviet":"Nam sinh","pos":"Danh từ","meaning":"nam sinh, bạn nam","comps":"几个男生 (mấy bạn nam), 男生和女生 (nam sinh và nữ sinh)","example":{"zh":"我们班的男生比女生多。","py":"Wǒmen bān de nánshēng bǐ nǚshēng duō.","vi":"Lớp mình bạn nam nhiều hơn bạn nữ."}},{"stt":7,"hanzi":"练","pinyin":"liàn","hanviet":"Luyện","pos":"Động từ","meaning":"luyện, tập","comps":"练球 (tập bóng), 练字 (luyện chữ)","example":{"zh":"他每天下午都去球场练球。","py":"Tā měi tiān xiàwǔ dōu qù qiúchǎng liàn qiú.","vi":"Chiều nào anh ấy cũng ra sân tập bóng."}},{"stt":8,"hanzi":"参加","pinyin":"cānjiā","hanviet":"Tham gia","pos":"Động từ","meaning":"tham gia, tham dự","comps":"参加比赛 (tham gia thi đấu), 参加考试 (dự thi)","example":{"zh":"你想参加这次比赛吗？","py":"Nǐ xiǎng cānjiā zhè cì bǐsài ma?","vi":"Bạn có muốn tham gia cuộc thi lần này không?"}},{"stt":9,"hanzi":"网球","pinyin":"wǎngqiú","hanviet":"Võng cầu","pos":"Danh từ","meaning":"quần vợt, tennis","comps":"打网球 (chơi quần vợt), 网球比赛 (thi đấu quần vợt)","example":{"zh":"我姐姐网球打得很好。","py":"Wǒ jiějie wǎngqiú dǎ de hěn hǎo.","vi":"Chị mình chơi quần vợt rất giỏi."}},{"stt":10,"hanzi":"比赛","pinyin":"bǐsài","hanviet":"Tỷ tái","pos":"Danh từ / Động từ","meaning":"trận đấu, cuộc thi; thi đấu","comps":"足球比赛 (trận bóng đá), 比赛开始了 (trận đấu bắt đầu rồi)","example":{"zh":"今天晚上有一场足球比赛。","py":"Jīntiān wǎnshang yǒu yì chǎng zúqiú bǐsài.","vi":"Tối nay có một trận bóng đá."}},{"stt":11,"hanzi":"练习","pinyin":"liànxí","hanviet":"Luyện tập","pos":"Động từ / Danh từ","meaning":"luyện tập; bài tập","comps":"练习口语 (luyện khẩu ngữ), 做练习 (làm bài tập)","example":{"zh":"学汉语要多听多说多练习。","py":"Xué Hànyǔ yào duō tīng duō shuō duō liànxí.","vi":"Học tiếng Hán phải nghe nhiều, nói nhiều, luyện nhiều."}},{"stt":12,"hanzi":"好多","pinyin":"hǎoduō","hanviet":"Hảo đa","pos":"Số từ","meaning":"rất nhiều","comps":"好多人 (rất nhiều người), 好多年 (nhiều năm)","example":{"zh":"周末公园里有好多人。","py":"Zhōumò gōngyuán li yǒu hǎoduō rén.","vi":"Cuối tuần trong công viên đông người lắm."}},{"stt":13,"hanzi":"几乎","pinyin":"jīhū","hanviet":"Cơ hồ","pos":"Phó từ","meaning":"hầu như, gần như","comps":"几乎每天 (hầu như ngày nào), 几乎忘了 (gần như quên mất)","example":{"zh":"他几乎每天都去体育馆。","py":"Tā jīhū měi tiān dōu qù tǐyùguǎn.","vi":"Hầu như ngày nào anh ấy cũng đến nhà thi đấu."}},{"stt":14,"hanzi":"只是","pinyin":"zhǐshì","hanviet":"Chỉ thị","pos":"Phó từ / Liên từ","meaning":"chỉ là; có điều","comps":"只是为了 (chỉ là để), 只是有点儿贵 (có điều hơi đắt)","example":{"zh":"这家饭馆的菜很好吃，只是有点儿贵。","py":"Zhè jiā fànguǎn de cài hěn hǎochī, zhǐshì yǒudiǎnr guì.","vi":"Món ở quán này rất ngon, có điều hơi đắt."}},{"stt":15,"hanzi":"啤酒","pinyin":"píjiǔ","hanviet":"Ti tửu","pos":"Danh từ","meaning":"bia","comps":"一瓶啤酒 (một chai bia), 喝啤酒 (uống bia)","example":{"zh":"天太热了，我想喝一瓶冰啤酒。","py":"Tiān tài rè le, wǒ xiǎng hē yì píng bīng píjiǔ.","vi":"Trời nóng quá, mình muốn uống một chai bia lạnh."}},{"stt":16,"hanzi":"回","pinyin":"huí","hanviet":"Hồi","pos":"Lượng từ","meaning":"chuyện, lần (cho sự việc)","comps":"怎么回事 (chuyện gì vậy), 去过两回 (đi hai lần)","example":{"zh":"门怎么开着？这是怎么回事？","py":"Mén zěnme kāizhe? Zhè shì zěnme huí shì?","vi":"Sao cửa lại mở thế này? Chuyện gì vậy?"}},{"stt":17,"hanzi":"紧张","pinyin":"jǐnzhāng","hanviet":"Khẩn trương","pos":"Tính từ","meaning":"căng thẳng, hồi hộp","comps":"很紧张 (rất hồi hộp), 别紧张 (đừng căng thẳng)","example":{"zh":"考试的时候别紧张，慢慢做。","py":"Kǎoshì de shíhou bié jǐnzhāng, mànmàn zuò.","vi":"Lúc thi đừng căng thẳng, cứ làm từ từ."}},{"stt":18,"hanzi":"主要","pinyin":"zhǔyào","hanviet":"Chủ yếu","pos":"Tính từ","meaning":"chủ yếu, chính","comps":"主要的问题 (vấn đề chính), 主要是 (chủ yếu là)","example":{"zh":"我学汉语主要是为了工作。","py":"Wǒ xué Hànyǔ zhǔyào shì wèile gōngzuò.","vi":"Mình học tiếng Hán chủ yếu là vì công việc."}},{"stt":19,"hanzi":"受到","pinyin":"shòudào","hanviet":"Thụ đáo","pos":"Động từ","meaning":"bị, chịu; được","comps":"受到影响 (bị ảnh hưởng), 受到欢迎 (được hoan nghênh)","example":{"zh":"因为下雨，比赛受到了影响。","py":"Yīnwèi xià yǔ, bǐsài shòudàole yǐngxiǎng.","vi":"Vì trời mưa, trận đấu bị ảnh hưởng."}},{"stt":20,"hanzi":"影响","pinyin":"yǐngxiǎng","hanviet":"Ảnh hưởng","pos":"Danh từ / Động từ","meaning":"ảnh hưởng","comps":"有影响 (có ảnh hưởng), 影响学习 (ảnh hưởng việc học)","example":{"zh":"晚上玩手机太久，会影响睡觉。","py":"Wǎnshang wán shǒujī tài jiǔ, huì yǐngxiǎng shuìjiào.","vi":"Buổi tối chơi điện thoại lâu quá sẽ ảnh hưởng giấc ngủ."}},{"stt":21,"hanzi":"得分","pinyin":"défēn","hanviet":"Đắc phân","pos":"Động từ / Danh từ","meaning":"ghi điểm; điểm số, tỉ số","comps":"得了十分 (ghi được 10 điểm), 比赛的得分 (tỉ số trận đấu)","example":{"zh":"这场比赛他一个人得了二十分。","py":"Zhè chǎng bǐsài tā yí ge rén déle èrshí fēn.","vi":"Trận này một mình anh ấy ghi được 20 điểm."}},{"stt":22,"hanzi":"体育","pinyin":"tǐyù","hanviet":"Thể dục","pos":"Danh từ","meaning":"thể dục thể thao","comps":"体育比赛 (thi đấu thể thao), 体育课 (giờ thể dục)","example":{"zh":"我们每个星期有两节体育课。","py":"Wǒmen měi ge xīngqī yǒu liǎng jié tǐyù kè.","vi":"Mỗi tuần chúng mình có hai tiết thể dục."}},{"stt":23,"hanzi":"世界","pinyin":"shìjiè","hanviet":"Thế giới","pos":"Danh từ","meaning":"thế giới","comps":"世界上 (trên thế giới), 全世界 (toàn thế giới)","example":{"zh":"长城是世界上很有名的地方。","py":"Chángchéng shì shìjiè shang hěn yǒumíng de dìfang.","vi":"Vạn Lý Trường Thành là nơi rất nổi tiếng trên thế giới."}},{"stt":24,"hanzi":"运动员","pinyin":"yùndòngyuán","hanviet":"Vận động viên","pos":"Danh từ","meaning":"vận động viên","comps":"足球运动员 (cầu thủ bóng đá), 网球运动员 (VĐV quần vợt)","example":{"zh":"他是一名很有名的网球运动员。","py":"Tā shì yì míng hěn yǒumíng de wǎngqiú yùndòngyuán.","vi":"Anh ấy là một vận động viên quần vợt rất nổi tiếng."}},{"stt":25,"hanzi":"得到","pinyin":"dédào","hanviet":"Đắc đáo","pos":"Động từ","meaning":"đạt được, nhận được","comps":"得到帮助 (nhận được giúp đỡ), 得到好成绩 (đạt thành tích tốt)","example":{"zh":"在中国的时候，我得到了很多朋友的帮助。","py":"Zài Zhōngguó de shíhou, wǒ dédàole hěn duō péngyou de bāngzhù.","vi":"Hồi ở Trung Quốc, mình nhận được nhiều sự giúp đỡ của bạn bè."}},{"stt":26,"hanzi":"成绩","pinyin":"chéngjì","hanviet":"Thành tích","pos":"Danh từ","meaning":"thành tích, kết quả (điểm)","comps":"考试成绩 (kết quả thi), 成绩很好 (thành tích tốt)","example":{"zh":"他的汉语成绩是我们班最好的。","py":"Tā de Hànyǔ chéngjì shì wǒmen bān zuì hǎo de.","vi":"Điểm tiếng Hán của cậu ấy cao nhất lớp mình."}},{"stt":27,"hanzi":"奥运会","pinyin":"Àoyùnhuì","hanviet":"Áo vận hội","pos":"Danh từ riêng","meaning":"Thế vận hội Olympic","comps":"参加奥运会 (dự Olympic), 看奥运会 (xem Olympic)","example":{"zh":"很多人都喜欢看奥运会的比赛。","py":"Hěn duō rén dōu xǐhuan kàn Àoyùnhuì de bǐsài.","vi":"Rất nhiều người thích xem các trận đấu ở Olympic."}},{"stt":28,"hanzi":"刘长春","pinyin":"Liú Chángchūn","hanviet":"Lưu Trường Xuân","pos":"Danh từ riêng","meaning":"Lưu Trường Xuân","comps":"运动员刘长春 (VĐV Lưu Trường Xuân), 刘老师 (thầy / cô họ Lưu)","example":{"zh":"刘长春是第一位参加奥运会的中国运动员。","py":"Liú Chángchūn shì dì-yī wèi cānjiā Àoyùnhuì de Zhōngguó yùndòngyuán.","vi":"Lưu Trường Xuân là VĐV Trung Quốc đầu tiên dự Olympic."}}],"hanzi":[{"char":"校园","pinyin":"xiàoyuán","hanviet":"Hiệu viên","chars":["校","园"],"story":"校 = 木 + 交 → trường học (学校). 园 = 囗 (vòng rào) + 元 → khu vườn có rào quanh. 校园 = khu vườn của trường → khuôn viên trường: 校园卡, 在校园里."},{"char":"卡","pinyin":"kǎ","hanviet":"Tạp","chars":["卡"],"story":"卡 = 上 + 下 → mắc kẹt giữa trên và dưới; mượn âm \"card\" → thẻ: 校园卡, 银行卡, 信用卡 (bài 3). Lượng từ đi kèm: 一张卡."},{"char":"球场","pinyin":"qiúchǎng","hanviet":"Cầu trường","chars":["球","场"],"story":"球 = 王 (ngọc) + 求 chỉ âm → quả bóng. 场 = 土 + 昜 → bãi đất rộng. 球场 = sân bóng: 篮球场, 足球场, 网球场."},{"char":"为了","pinyin":"wèile","hanviet":"Vị liễu","chars":["为","了"],"story":"为 đọc wèi = vì, cho; 为了 + mục đích → để …: 为了健康. 为了 nêu mục đích, 因为 nêu nguyên nhân. Trong 以为 (bài 1) chữ 为 đọc wéi."},{"char":"运动会","pinyin":"yùndònghuì","hanviet":"Vận động hội","chars":["运","动","会"],"story":"运动 = vận động, thể thao. 会 = cuộc tụ họp, hội (音乐会 bài 5). 运动会 = hội thi thể thao: 学校运动会, 参加运动会."},{"char":"男生","pinyin":"nánshēng","hanviet":"Nam sinh","chars":["男","生"],"story":"男 = 田 (ruộng) + 力 (sức) → người dùng sức làm ruộng → nam. 生 = học sinh (学生). 男生 / 女生 = nam sinh / nữ sinh, cũng gọi chung con trai / con gái trẻ."},{"char":"练","pinyin":"liàn","hanviet":"Luyện","chars":["练"],"story":"练 = 纟 (tơ) + 柬 chỉ âm → luyện tơ cho mềm → rèn, luyện. 练 + việc cần luyện: 练球, 练字. Dạng hai âm tiết: 练习."},{"char":"参加","pinyin":"cānjiā","hanviet":"Tham gia","chars":["参","加"],"story":"参 = dự vào. 加 = 力 + 口 → thêm vào. 参加 + hoạt động / tổ chức: 参加比赛, 参加运动会. Không nói ✗ 参加朋友."},{"char":"网球","pinyin":"wǎngqiú","hanviet":"Võng cầu","chars":["网","球"],"story":"网 vẽ tấm lưới (上网, 网上 cũng là chữ này). 网球 = bóng đánh qua lưới → quần vợt; động từ đi kèm là 打: 打网球."},{"char":"比赛","pinyin":"bǐsài","hanviet":"Tỷ tái","chars":["比","赛"],"story":"比 vẽ hai người đứng cạnh nhau để so (比较). 赛 = thi đua. 比赛 = so tài → trận đấu, cuộc thi: 足球比赛; động từ: 我们比赛一下."},{"char":"练习","pinyin":"liànxí","hanviet":"Luyện tập","chars":["练","习"],"story":"练 = luyện + 习 = tập (习惯 bài 8) → luyện tập. Động từ: 每天练习口语; danh từ: 做练习 = làm bài tập."},{"char":"好多","pinyin":"hǎoduō","hanviet":"Hảo đa","chars":["好","多"],"story":"好 đứng trước số lượng = rất. 好多 = 很多, mang sắc thái khẩu ngữ, cảm thán: 好多年, 好多人. So sánh: 好几天 = mấy ngày liền."},{"char":"几乎","pinyin":"jīhū","hanviet":"Cơ hồ","chars":["几","乎"],"story":"几 ở đây đọc jī (thanh 1) = gần, sắp — khác 几个 jǐ. 乎 = trợ từ. 几乎 = gần như, hầu như: 几乎每天, 几乎忘了."},{"char":"只是","pinyin":"zhǐshì","hanviet":"Chỉ thị","chars":["只","是"],"story":"只 = chỉ (bài 2) + 是 → chỉ là: 只是为了锻炼身体. Làm liên từ = có điều, chỉ có điều: 很好看，只是有点儿贵."},{"char":"啤酒","pinyin":"píjiǔ","hanviet":"Ti tửu","chars":["啤","酒"],"story":"啤 = 口 + 卑 chỉ âm → phiên âm \"beer\". 酒 = 氵 (nước) + 酉 (vò rượu) → rượu. 啤酒 = loại rượu \"pí\" → bia: 一瓶啤酒, 冰啤酒."},{"char":"回","pinyin":"huí","hanviet":"Hồi","chars":["回"],"story":"回 vẽ vòng xoáy nằm trong vòng → quay về (động từ 回家). Làm lượng từ cho sự việc: 怎么回事 = chuyện gì vậy; 去过两回 = 去过两次."},{"char":"紧张","pinyin":"jǐnzhāng","hanviet":"Khẩn trương","chars":["紧","张"],"story":"紧 = 臤 + 糸 (sợi tơ) → buộc chặt. 张 = 弓 + 长 → giương cung. 紧张 = dây cung căng chặt → căng thẳng, hồi hộp. Khác \"khẩn trương\" (gấp gáp) trong tiếng Việt!"},{"char":"主要","pinyin":"zhǔyào","hanviet":"Chủ yếu","chars":["主","要"],"story":"主 vẽ ngọn đèn, chấm trên là ngọn lửa → người chủ, cái chính. 要 = quan trọng (重要). 主要 = chính, chủ yếu: 主要的球员, 主要是为了…."},{"char":"受到","pinyin":"shòudào","hanviet":"Thụ đáo","chars":["受","到"],"story":"受 = 爫 (bàn tay trên) + 冖 + 又 (bàn tay dưới) → trao – nhận. 到 = đến. 受到 + danh từ: 受到影响 (bị), 受到欢迎 (được)."},{"char":"影响","pinyin":"yǐngxiǎng","hanviet":"Ảnh hưởng","chars":["影","响"],"story":"影 = 景 + 彡 (tia sáng) → cái bóng. 响 = 口 + 向 → tiếng vang. Bóng theo hình, vang theo tiếng → ảnh hưởng: 受到…的影响, 影响学习."},{"char":"得分","pinyin":"défēn","hanviet":"Đắc phân","chars":["得","分"],"story":"得 dé = được (bài 8: de / dé / děi). 分 = 八 + 刀 → chia ra; điểm (一百分). 得分 = được điểm → ghi điểm; danh từ = điểm số, tỉ số trận đấu."},{"char":"体育","pinyin":"tǐyù","hanviet":"Thể dục","chars":["体","育"],"story":"体 = 亻 + 本 → thân thể (体育馆 bài 8). 育 = nuôi dạy. 体育 = rèn dạy thân thể → thể dục thể thao: 体育比赛, 体育课."},{"char":"世界","pinyin":"shìjiè","hanviet":"Thế giới","chars":["世","界"],"story":"世 = ba chữ 十 nối nhau (30 năm = một đời) → đời, thế. 界 = 田 + 介 → ranh giới ruộng. 世界 = cõi đời → thế giới. Hay nói 世界上 + 最…."},{"char":"运动员","pinyin":"yùndòngyuán","hanviet":"Vận động viên","chars":["运","动","员"],"story":"运动 = vận động, thể thao. 员 = người làm một việc (服务员 bài 2). 运动员 = vận động viên. Cầu thủ nói 球员 (bài khoá 3)."},{"char":"得到","pinyin":"dédào","hanviet":"Đắc đáo","chars":["得","到"],"story":"得 = 彳 (đi) + bàn tay cầm được → được. 到 = đến tay. 得到 = có được: 得到帮助, 得到好成绩. So sánh: 受到影响 — chịu tác động."},{"char":"成绩","pinyin":"chéngjì","hanviet":"Thành tích","chars":["成","绩"],"story":"成 = làm xong, thành. 绩 = 纟 + 责 → sợi tơ dệt được → công lao. 成绩 = cái làm thành được → thành tích, điểm số: 考试成绩, 好成绩."},{"char":"奥运会","pinyin":"Àoyùnhuì","hanviet":"Áo vận hội","chars":["奥","运","会"],"story":"奥 = phiên âm chữ \"O\" trong Olympic (奥林匹克). 运 = 运动. 会 = hội (运动会). 奥运会 = gọi tắt của Thế vận hội Olympic."},{"char":"刘长春","pinyin":"Liú Chángchūn","hanviet":"Lưu Trường Xuân","chars":["刘","长","春"],"story":"刘 = họ Lưu. 长 ở đây đọc cháng (dài) — khác zhǎng (bài 1). 春 = mùa xuân. 长春 cũng là tên thành phố Trường Xuân ở Đông Bắc Trung Quốc."}],"grammar":[{"title":"为了 + 目的，(主语) + 行动","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>为了</b><small>để</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>目的</b><small>mục đích</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(主语)</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>行动</b><small>hành động</small></span></div>","summary":"<p class=\"gr-lead\">Để … (thì) …</p><ul><li><span class=\"zh\">为了</span> + <b>mục đích</b>, vế kia là <b>hành động</b> để đạt mục đích: <span class=\"zh\">为了早点儿到家，我打算坐飞机回去</span>.</li><li>Nhấn mạnh mục đích → đưa ra cuối câu bằng <span class=\"zh\">是为了</span>: <span class=\"zh\">大家打球只是为了锻炼身体</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">为了 · 是为了</span> · Ba vị trí thường gặp</h4><p>Đầu câu · sau chủ ngữ · cuối câu</p><div class=\"gr-formula\"><div class=\"fx-lbl\">为了… đầu câu</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>为了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>早点儿到家</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>坐飞机</b></span></div><div class=\"fx-ex zh\">为了早点儿到家，我坐飞机。</div><div class=\"fx-lbl\">Chủ ngữ + 为了…</div><div class=\"fx-row\"><span class=\"fx-p\"><b>她</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>为了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>考上大学</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>努力学习</b></span></div><div class=\"fx-ex zh\">她为了考上大学，努力学习。</div><div class=\"fx-lbl\">Hành động + 是为了…</div><div class=\"fx-row\"><span class=\"fx-p\"><b>打球</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>只是</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>为了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>锻炼身体</b></span></div><div class=\"fx-ex zh\">打球只是为了锻炼身体。</div></div><p class=\"gr-key\"><span class=\"zh\">为了 + mục đích</span> (để …)　·　<span class=\"zh\">因为 + nguyên nhân</span> (vì …)</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">为了考上大学，她每天努力学习。</span> = Để thi đỗ đại học, ngày nào cô ấy cũng chăm chỉ học.</p>","note":"<b>Lưu ý:</b> <span class=\"zh\">为了</span> nêu mục đích, <span class=\"zh\">因为</span> nêu nguyên nhân: ✗ <span class=\"zh\">为了下雨，我没去</span> → ✓ <span class=\"zh\">因为下雨，我没去</span>","examples":[{"zh":"听说为了准备运动会，你们几个男生每天都练球。","py":"Tīngshuō wèile zhǔnbèi yùndònghuì, nǐmen jǐ ge nánshēng měi tiān dōu liàn qiú.","vi":"Nghe nói để chuẩn bị hội thao, mấy bạn nam ngày nào cũng tập bóng."},{"zh":"为了考上大学，她每天努力学习。","py":"Wèile kǎoshàng dàxué, tā měi tiān nǔlì xuéxí.","vi":"Để thi đỗ đại học, ngày nào cô ấy cũng chăm chỉ học."},{"zh":"为了早点儿到家，我打算坐飞机回去。","py":"Wèile zǎo diǎnr dào jiā, wǒ dǎsuàn zuò fēijī huíqu.","vi":"Để về đến nhà sớm hơn, mình định đi máy bay về."}],"exercises":[]},{"title":"动词 + 得 / 不 + 结果补语 / 趋向补语","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>得 / 不</b><small>được / không</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>补语</b><small>BN kết quả / xu hướng</small></span></div>","summary":"<p class=\"gr-lead\">… được / không … được</p><ul><li>Chèn <span class=\"zh\">得 / 不</span> giữa động từ và bổ ngữ kết quả / xu hướng: <span class=\"zh\">看得懂 · 听不见 · 踢不进去</span>.</li><li>Câu hỏi: <span class=\"zh\">看得懂看不懂？</span> hoặc <span class=\"zh\">看得懂吗？</span></li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">动词 + 得 / 不 + 补语</span> · Khẳng định · phủ định · câu hỏi</h4><p>Bốn dạng của bổ ngữ khả năng</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Khẳng định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>听</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>得</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>见</b></span></div><div class=\"fx-ex zh\">没问题，我听得见。</div><div class=\"fx-lbl\">Phủ định</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>打</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>好</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>没关系</b></span></div><div class=\"fx-ex zh\">打不好没关系。</div><div class=\"fx-lbl\">Hỏi: V得C V不C</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>看</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>得</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>懂</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>看</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>懂</b></span></div><div class=\"fx-ex zh\">看得懂看不懂？</div><div class=\"fx-lbl\">Hỏi: V得C + 吗</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>学</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>得</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>会</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>游泳</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>吗</b></span></div><div class=\"fx-ex zh\">学得会游泳吗？</div></div><p class=\"gr-key\">Với bổ ngữ xu hướng: <span class=\"zh\">踢不进去 · 回得来</span>　·　<span class=\"zh\">接不住球</span> (bài khoá 2)</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">打不好没关系。</span> = Đánh không giỏi cũng không sao.</p>","note":"<b>Lưu ý:</b> Nói \"không … được\" do điều kiện → dùng <span class=\"zh\">V不C</span>: ✗ <span class=\"zh\">我不能听懂</span> → ✓ <span class=\"zh\">我听不懂</span>","examples":[{"zh":"打不好没关系。","py":"Dǎ bu hǎo méi guānxi.","vi":"Đánh không giỏi cũng không sao."},{"zh":"这本书你看得懂看不懂？","py":"Zhè běn shū nǐ kàn de dǒng kàn bu dǒng?","vi":"Cuốn sách này bạn đọc có hiểu không?"},{"zh":"你只有一个星期的时间，学得会游泳吗？","py":"Nǐ zhǐ yǒu yí ge xīngqī de shíjiān, xué de huì yóuyǒng ma?","vi":"Bạn chỉ có một tuần, học bơi có được không?"}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我和你妈妈在门口等着你呢。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">机场人太多了，我____。</span></span></span><span class=\"qz-hint\">Bố với mẹ con đang đợi con ở cửa đây. — Sân bay đông quá, con không nhìn thấy bố mẹ.</span>","answer":["看不见你们","看不到你们","看不见"],"explain":"机场人太多了，我看不见你们。 (Jīchǎng rén tài duō le, wǒ kàn bu jiàn nǐmen.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">喂？喂？我说话你____？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">没问题，我听得见。</span></span></span><span class=\"qz-hint\">A lô? A lô? Mình nói bạn có nghe thấy không? — Không vấn đề gì, mình nghe thấy.</span>","answer":["听得见吗","听得到吗","听得清楚吗"],"explain":"喂？喂？我说话你听得见吗？ (Wéi? Wéi? Wǒ shuōhuà nǐ tīng de jiàn ma?)"},{"type":"fillm","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">咱们还没做今天的作业呢，半个小时{{0}}？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">没问题，{{1}}，今天的作业一点儿也不多。</span></span></span><span class=\"qz-hint\">Mình còn chưa làm bài tập hôm nay, nửa tiếng làm xong không? — Không sao, làm xong được, bài hôm nay chẳng nhiều chút nào.</span>","blanks":[["做得完吗"],["做得完"]],"explain":"咱们还没做今天的作业呢，半个小时做得完吗？ (Zánmen hái méi zuò jīntiān de zuòyè ne, bàn ge xiǎoshí zuò de wán ma?) · 没问题，做得完，今天的作业一点儿也不多。 (Méi wèntí, zuò de wán, jīntiān de zuòyè yìdiǎnr yě bù duō.)"}]},{"title":"(主语) + 越 + A + 越 + B","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>(主语)</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>越</b><small>càng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>A</b><small>ĐT / TT</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>越</b><small>càng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b><small>ĐT / TT</small></span></div>","summary":"<p class=\"gr-lead\">Càng A càng B</p><ul><li>A, B là cụm động từ hoặc tính từ: <span class=\"zh\">越看越着急 · 越多越好</span>; hai chủ ngữ: <span class=\"zh\">妈妈越说，他越不高兴</span>.</li><li>Khác <span class=\"zh\">越来越</span> (bài 6) — thay đổi theo <b>thời gian</b>: <span class=\"zh\">天气越来越冷</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">越A越B · 越来越</span> · Bốn dạng thường gặp</h4><p>Cùng / khác chủ ngữ · so với 越来越</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Cùng chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>越</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>看</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>越</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>着急</b></span></div><div class=\"fx-ex zh\">我越看越着急。</div><div class=\"fx-lbl\">Hai chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>妈妈</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>越</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>说</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>他</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>越</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>不高兴</b></span></div><div class=\"fx-lbl\">越 + TT + 越 + TT</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>越</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>多</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>越</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>好</b></span></div><div class=\"fx-ex zh\">朋友越多越好。</div><div class=\"fx-lbl\">越来越 (bài 6)</div><div class=\"fx-row\"><span class=\"fx-p\"><b>天气</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>越来越</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>冷</b></span></div><div class=\"fx-ex zh\">天气越来越冷了。</div></div><p class=\"gr-key\"><span class=\"zh\">越A越B</span>: B đổi theo A　·　<span class=\"zh\">越来越B</span>: B đổi theo thời gian</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">今天的足球比赛我越看越着急。</span> = Trận bóng hôm nay mình càng xem càng sốt ruột.</p>","note":"<b>Lưu ý:</b> Sau <span class=\"zh\">越</span> không thêm 很 / 非常: ✗ <span class=\"zh\">越看越很着急</span> → ✓ <span class=\"zh\">越看越着急</span>","examples":[{"zh":"今天的足球比赛我越看越着急。","py":"Jīntiān de zúqiú bǐsài wǒ yuè kàn yuè zháojí.","vi":"Trận bóng hôm nay mình càng xem càng sốt ruột."},{"zh":"妈妈越说，他越不高兴。","py":"Māma yuè shuō, tā yuè bù gāoxìng.","vi":"Mẹ càng nói, cậu ấy càng không vui."},{"zh":"我想认识中国朋友，越多越好。","py":"Wǒ xiǎng rènshi Zhōngguó péngyou, yuè duō yuè hǎo.","vi":"Mình muốn quen bạn Trung Quốc, càng nhiều càng tốt."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在图书馆门口","titleVi":"Cửa thư viện — Lý Văn chạy đến","lines":[{"speaker":"文","name":"Lý Văn","zh":"家月，对不起，我昨天忘了还你校园卡了。","py":"Jiāyuè, duìbuqǐ, wǒ zuótiān wàngle huán nǐ xiàoyuánkǎ le.","vi":"Gia Nguyệt, xin lỗi, hôm qua mình quên trả thẻ trường cho bạn."},{"speaker":"月","name":"Gia Nguyệt","zh":"没关系。你怎么这么快就过来了？","py":"Méi guānxi. Nǐ zěnme zhème kuài jiù guòlai le?","vi":"Không sao. Sao bạn đến nhanh thế?"},{"speaker":"文","name":"Lý Văn","zh":"我正在球场打球呢，接了你的电话就跑过来了。","py":"Wǒ zhèngzài qiúchǎng dǎ qiú ne, jiēle nǐ de diànhuà jiù pǎo guòlai le.","vi":"Mình đang chơi bóng ở sân, nghe điện thoại của bạn xong là chạy qua luôn."},{"speaker":"月","name":"Gia Nguyệt","zh":"听说为了准备运动会，你们几个男生每天都练球。","py":"Tīngshuō wèile zhǔnbèi yùndònghuì, nǐmen jǐ ge nánshēng měi tiān dōu liàn qiú.","vi":"Nghe nói để chuẩn bị hội thao, mấy bạn nam các cậu ngày nào cũng tập bóng."},{"speaker":"文","name":"Lý Văn","zh":"是啊！你打算参加运动会吗？","py":"Shì a! Nǐ dǎsuàn cānjiā yùndònghuì ma?","vi":"Đúng thế! Bạn định tham gia hội thao không?"},{"speaker":"月","name":"Gia Nguyệt","zh":"我想参加网球比赛，最近一直在练习。","py":"Wǒ xiǎng cānjiā wǎngqiú bǐsài, zuìjìn yìzhí zài liànxí.","vi":"Mình muốn thi quần vợt, dạo này vẫn luôn luyện tập."},{"speaker":"文","name":"Lý Văn","zh":"好，到时候我去看你的比赛。","py":"Hǎo, dào shíhou wǒ qù kàn nǐ de bǐsài.","vi":"Được, đến lúc đó mình đi xem bạn thi đấu."}]},{"titleZh":"课文二 · 在校园里","titleVi":"Sân trường — rủ đánh cầu lông","lines":[{"speaker":"文","name":"Lý Văn","zh":"家月，你跟我们一起打羽毛球吧？","py":"Jiāyuè, nǐ gēn wǒmen yìqǐ dǎ yǔmáoqiú ba?","vi":"Gia Nguyệt, bạn đánh cầu lông cùng bọn mình nhé?"},{"speaker":"月","name":"Gia Nguyệt","zh":"我好多年没打羽毛球了，几乎忘了怎么打了。","py":"Wǒ hǎoduō nián méi dǎ yǔmáoqiú le, jīhū wàngle zěnme dǎ le.","vi":"Nhiều năm rồi mình không đánh cầu lông, gần như quên cách đánh rồi."},{"speaker":"文","name":"Lý Văn","zh":"不是比赛，打不好没关系。","py":"Bú shì bǐsài, dǎ bu hǎo méi guānxi.","vi":"Đâu phải thi đấu, đánh không giỏi cũng không sao."},{"speaker":"月","name":"Gia Nguyệt","zh":"这么多同学一起打，如果总是接不住球，就太不好意思了。","py":"Zhème duō tóngxué yìqǐ dǎ, rúguǒ zǒngshì jiē bu zhù qiú, jiù tài bù hǎoyìsi le.","vi":"Nhiều bạn cùng đánh thế này, nếu cứ đỡ không được cầu thì ngại lắm."},{"speaker":"文","name":"Lý Văn","zh":"你想得太多了！大家打球只是为了锻炼身体。","py":"Nǐ xiǎng de tài duō le! Dàjiā dǎ qiú zhǐshì wèile duànliàn shēntǐ.","vi":"Bạn nghĩ nhiều quá rồi! Mọi người chơi chỉ là để rèn luyện sức khoẻ thôi."},{"speaker":"月","name":"Gia Nguyệt","zh":"我先自己练练吧，下周再跟你们一起打。","py":"Wǒ xiān zìjǐ liànlian ba, xià zhōu zài gēn nǐmen yìqǐ dǎ.","vi":"Mình tự tập trước đã, tuần sau rồi đánh cùng các bạn."},{"speaker":"文","name":"Lý Văn","zh":"我在教天中打羽毛球，你可以过来跟我们一起练。","py":"Wǒ zài jiāo Tiānzhōng dǎ yǔmáoqiú, nǐ kěyǐ guòlai gēn wǒmen yìqǐ liàn.","vi":"Mình đang dạy Thiên Trung đánh cầu lông, bạn có thể qua tập cùng bọn mình."}]},{"titleZh":"课文三 · 在李文家","titleVi":"Nhà Lý Văn — cùng xem bóng đá","lines":[{"speaker":"中","name":"Thiên Trung","zh":"足球比赛已经开始了，快过来看吧！","py":"Zúqiú bǐsài yǐjīng kāishǐ le, kuài guòlai kàn ba!","vi":"Trận bóng đá bắt đầu rồi, mau qua xem đi!"},{"speaker":"文","name":"Lý Văn","zh":"你们先看，冰箱里有啤酒和饮料，我去拿一下。","py":"Nǐmen xiān kàn, bīngxiāng li yǒu píjiǔ hé yǐnliào, wǒ qù ná yíxià.","vi":"Các cậu xem trước đi, trong tủ lạnh có bia và nước ngọt, mình đi lấy."},{"speaker":"月","name":"Gia Nguyệt","zh":"今天怎么回事？总是踢不进去！","py":"Jīntiān zěnme huí shì? Zǒngshì tī bu jìnqu!","vi":"Hôm nay làm sao thế nhỉ? Cứ sút mãi không vào!"},{"speaker":"中","name":"Thiên Trung","zh":"几个老球员生病了，新球员第一次参加这么重要的比赛，太紧张了。","py":"Jǐ ge lǎo qiúyuán shēngbìng le, xīn qiúyuán dì-yī cì cānjiā zhème zhòngyào de bǐsài, tài jǐnzhāng le.","vi":"Mấy cầu thủ kỳ cựu bị ốm, cầu thủ mới lần đầu đá trận quan trọng thế này, căng thẳng quá."},{"speaker":"文","name":"Lý Văn","zh":"是啊，主要的球员没参加比赛，所以大家也都受到影响了。","py":"Shì a, zhǔyào de qiúyuán méi cānjiā bǐsài, suǒyǐ dàjiā yě dōu shòudào yǐngxiǎng le.","vi":"Ừ, cầu thủ chủ chốt không ra sân nên cả đội cũng bị ảnh hưởng."},{"speaker":"月","name":"Gia Nguyệt","zh":"越看越着急。我不看了，你们告诉我得分吧。","py":"Yuè kàn yuè zháojí. Wǒ bú kàn le, nǐmen gàosu wǒ défēn ba.","vi":"Càng xem càng sốt ruột. Mình không xem nữa, các cậu báo tỉ số cho mình nhé."}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — Lý Văn soạn bài nói","para":true,"speaker":"文","lines":[{"zh":"我喜欢看体育比赛，最爱看的就是奥运会。","py":"Wǒ xǐhuan kàn tǐyù bǐsài, zuì ài kàn de jiù shì Àoyùnhuì.","vi":"Tôi thích xem thi đấu thể thao, thích xem nhất chính là Thế vận hội Olympic."},{"zh":"奥运会是世界上影响最大的体育比赛。","py":"Àoyùnhuì shì shìjiè shang yǐngxiǎng zuì dà de tǐyù bǐsài.","vi":"Olympic là giải đấu thể thao có ảnh hưởng lớn nhất thế giới."},{"zh":"从1896年到2024年，每次奥运会都有非常多的运动员参加。","py":"Cóng 1896 nián dào 2024 nián, měi cì Àoyùnhuì dōu yǒu fēicháng duō de yùndòngyuán cānjiā.","vi":"Từ năm 1896 đến năm 2024, kỳ Olympic nào cũng có rất nhiều vận động viên tham gia."},{"zh":"第一位参加奥运会的中国运动员是刘长春，他1932年参加了100米和200米短跑比赛。","py":"Dì-yī wèi cānjiā Àoyùnhuì de Zhōngguó yùndòngyuán shì Liú Chángchūn, tā 1932 nián cānjiāle 100 mǐ hé 200 mǐ duǎnpǎo bǐsài.","vi":"Vận động viên Trung Quốc đầu tiên dự Olympic là Lưu Trường Xuân, năm 1932 ông thi chạy ngắn 100 mét và 200 mét."},{"zh":"虽然他没有得到好成绩，但是他让世界认识了中国。","py":"Suīrán tā méiyǒu dédào hǎo chéngjì, dànshì tā ràng shìjiè rènshile Zhōngguó.","vi":"Tuy ông không đạt thành tích tốt, nhưng ông đã giúp thế giới biết đến Trung Quốc."}]}]},"extra":[],"activity":{"act":[{"zh":"多人活动","py":"duōrén huódòng","tag":"Hoạt động nhóm","mean":"Môn thể thao của em","q":{"zh":"四人一组，介绍自己熟悉的运动。","py":"Sì rén yì zǔ, jièshào zìjǐ shúxī de yùndòng.","vi":"Nhóm 4 người: giới thiệu môn thể thao mình quen thuộc, rồi cử 1 bạn trình bày trước lớp."},"items":[{"zh":"你最喜欢的运动是什么？为什么？","py":"Nǐ zuì xǐhuan de yùndòng shì shénme? Wèi shénme?","vi":"Môn thể thao bạn thích nhất là gì? Vì sao?"},{"zh":"你是受到谁的影响开始喜欢这个运动的？","py":"Nǐ shì shòudào shéi de yǐngxiǎng kāishǐ xǐhuan zhège yùndòng de?","vi":"Bạn bắt đầu thích môn này do ai ảnh hưởng?"},{"zh":"你多久练习一次？每次练习多长时间？","py":"Nǐ duō jiǔ liànxí yí cì? Měi cì liànxí duō cháng shíjiān?","vi":"Bao lâu bạn tập một lần? Mỗi lần bao lâu?"},{"zh":"这个运动对你有什么影响？","py":"Zhège yùndòng duì nǐ yǒu shénme yǐngxiǎng?","vi":"Môn này ảnh hưởng đến bạn thế nào?"},{"zh":"你参加过什么体育比赛？","py":"Nǐ cānjiāguo shénme tǐyù bǐsài?","vi":"Bạn từng tham gia cuộc thi thể thao nào?"},{"zh":"你成绩最好的一次比赛是什么？","py":"Nǐ chéngjì zuì hǎo de yí cì bǐsài shì shénme?","vi":"Trận đấu bạn đạt thành tích tốt nhất là trận nào?"}]}],"speak":[]},"review":{"range":"7–9","rows":[{"l":7,"zh":"连动句 (2) \"动词₁ + 着 + 动词₂\"","vi":"Câu liên động (2): V₁ + 着 + V₂","ex":{"zh":"咱们可以走着去。","py":"Zánmen kěyǐ zǒuzhe qù.","vi":"Mình có thể đi bộ đến đó."}},{"l":7,"zh":"比较句 (10) \"A 不比 B\"","vi":"Câu so sánh (10): A 不比 B","ex":{"zh":"裙子不比短裤贵多少。","py":"Qúnzi bù bǐ duǎnkù guì duōshao.","vi":"Váy chẳng đắt hơn quần soóc bao nhiêu."}},{"l":7,"zh":"程度补语 (3) \"极了\"","vi":"Bổ ngữ trình độ (3): 极了","ex":{"zh":"这块冰西瓜甜极了。","py":"Zhè kuài bīng xīguā tián jí le.","vi":"Miếng dưa hấu lạnh này ngọt cực."}},{"l":7,"zh":"递进复句 \"不但……，而且……\"","vi":"Câu phức tăng tiến 不但……，而且……","ex":{"zh":"现在的电视不但便宜，而且用着非常方便。","py":"Xiànzài de diànshì búdàn piányi, érqiě yòngzhe fēicháng fāngbiàn.","vi":"Tivi bây giờ không những rẻ mà dùng còn rất tiện."}},{"l":8,"zh":"趋向补语的引申用法 (1) \"下去\"","vi":"Bổ ngữ xu hướng — nghĩa mở rộng (1): 下去","ex":{"zh":"我今年胖了十多斤，不能再胖下去了。","py":"Wǒ jīnnián pàngle shí duō jīn, bù néng zài pàng xiàqu le.","vi":"Năm nay mình béo lên hơn chục cân, không thể béo thêm nữa."}},{"l":8,"zh":"离合词 (2)","vi":"Từ ly hợp (2)","ex":{"zh":"昨天游完泳以后，我的耳朵一直有点儿疼。","py":"Zuótiān yóuwán yǒng yǐhòu, wǒ de ěrduo yìzhí yǒudiǎnr téng.","vi":"Hôm qua bơi xong, tai mình cứ hơi đau suốt."}},{"l":8,"zh":"时量补语 (2)","vi":"Bổ ngữ thời lượng (2)","ex":{"zh":"我上次来医院已经过去差不多两年了。","py":"Wǒ shàng cì lái yīyuàn yǐjīng guòqu chàbuduō liǎng nián le.","vi":"Lần trước mình đến bệnh viện đã gần hai năm rồi."}},{"l":8,"zh":"固定格式 \"……以前/以后/前/后\"","vi":"Cấu trúc ……以前 / 以后 / 前 / 后","ex":{"zh":"这种药需要每天睡前吃一次。","py":"Zhè zhǒng yào xūyào měi tiān shuì qián chī yí cì.","vi":"Loại thuốc này mỗi ngày uống một lần trước khi ngủ."}},{"l":9,"zh":"目的复句 \"为了……，……\"","vi":"Câu phức mục đích 为了……，……","ex":{"zh":"听说为了准备运动会，你们几个男生每天都练球。","py":"Tīngshuō wèile zhǔnbèi yùndònghuì, nǐmen jǐ ge nánshēng měi tiān dōu liàn qiú.","vi":"Nghe nói để chuẩn bị hội thao, mấy bạn nam các cậu ngày nào cũng tập bóng."}},{"l":9,"zh":"可能补语","vi":"Bổ ngữ khả năng","ex":{"zh":"打不好没关系。","py":"Dǎ bu hǎo méi guānxi.","vi":"Đánh không giỏi cũng không sao."}},{"l":9,"zh":"固定格式 \"越A越B\"","vi":"Cấu trúc cố định 越A越B","ex":{"zh":"今天的足球比赛我越看越着急。","py":"Jīntiān de zúqiú bǐsài wǒ yuè kàn yuè zháojí.","vi":"Trận bóng hôm nay mình càng xem càng sốt ruột."}}]}},{"id":"k3v3-b10","courseId":"k3v3","order":10,"title":"Mai các em hẵng trả sách cho cô","titleZh":"你明天再把书还给我","titlePy":"nǐ míngtiān zài bǎ shū huán gěi wǒ","vocab":[{"stt":1,"hanzi":"数学","pinyin":"shùxué","hanviet":"Số học","pos":"Danh từ","meaning":"toán, môn toán","comps":"数学课 (giờ toán), 数学老师 (giáo viên toán)","example":{"zh":"我弟弟数学很好，每次考试都考一百分。","py":"Wǒ dìdi shùxué hěn hǎo, měi cì kǎoshì dōu kǎo yìbǎi fēn.","vi":"Em trai mình giỏi toán, lần thi nào cũng được 100 điểm."}},{"stt":2,"hanzi":"认真","pinyin":"rènzhēn","hanviet":"Nhận chân","pos":"Tính từ","meaning":"nghiêm túc, chăm chỉ","comps":"认真学习 (chăm chỉ học), 认真听课 (chăm chú nghe giảng)","example":{"zh":"他工作非常认真，大家都很喜欢他。","py":"Tā gōngzuò fēicháng rènzhēn, dàjiā dōu hěn xǐhuan tā.","vi":"Anh ấy làm việc rất nghiêm túc, mọi người đều quý anh ấy."}},{"stt":3,"hanzi":"笔记","pinyin":"bǐjì","hanviet":"Bút ký","pos":"Danh từ","meaning":"ghi chép, vở ghi","comps":"记笔记 (ghi chép), 笔记本 (sổ ghi chép)","example":{"zh":"上课的时候，我都会记笔记。","py":"Shàngkè de shíhou, wǒ dōu huì jì bǐjì.","vi":"Trong giờ học, mình luôn ghi chép."}},{"stt":4,"hanzi":"清楚","pinyin":"qīngchu","hanviet":"Thanh sở","pos":"Tính từ / Động từ","meaning":"rõ ràng; biết rõ","comps":"看清楚 (nhìn rõ), 说清楚 (nói rõ), 不清楚 (không rõ)","example":{"zh":"这件事我也不太清楚，你问问他吧。","py":"Zhè jiàn shì wǒ yě bú tài qīngchu, nǐ wènwen tā ba.","vi":"Chuyện này mình cũng không rõ lắm, bạn hỏi anh ấy xem."}},{"stt":5,"hanzi":"黑板","pinyin":"hēibǎn","hanviet":"Hắc bản","pos":"Danh từ","meaning":"bảng (đen)","comps":"黑板上 (trên bảng), 看黑板 (nhìn lên bảng)","example":{"zh":"我坐在后面，看不清楚黑板上的字。","py":"Wǒ zuò zài hòumian, kàn bu qīngchu hēibǎn shang de zì.","vi":"Mình ngồi phía sau, nhìn không rõ chữ trên bảng."}},{"stt":6,"hanzi":"把","pinyin":"bǎ","hanviet":"Bả","pos":"Giới từ","meaning":"(đưa tân ngữ lên trước động từ)","comps":"把书放在桌子上 (đặt sách lên bàn), 把名字写在这里 (viết tên vào đây)","example":{"zh":"请把你的名字写在黑板上。","py":"Qǐng bǎ nǐ de míngzi xiě zài hēibǎn shang.","vi":"Em hãy viết tên mình lên bảng."}},{"stt":7,"hanzi":"作业","pinyin":"zuòyè","hanviet":"Tác nghiệp","pos":"Danh từ","meaning":"bài tập (về nhà)","comps":"写作业 (làm bài tập), 作业本 (vở bài tập)","example":{"zh":"我每天晚上八点开始写作业。","py":"Wǒ měi tiān wǎnshang bā diǎn kāishǐ xiě zuòyè.","vi":"Tối nào mình cũng bắt đầu làm bài tập lúc 8 giờ."}},{"stt":8,"hanzi":"遍","pinyin":"biàn","hanviet":"Biến","pos":"Lượng từ","meaning":"lượt, lần (từ đầu đến cuối)","comps":"看一遍 (xem một lượt), 再说一遍 (nói lại lần nữa)","example":{"zh":"对不起，我没听清楚，请再说一遍。","py":"Duìbuqǐ, wǒ méi tīng qīngchu, qǐng zài shuō yí biàn.","vi":"Xin lỗi, mình nghe không rõ, nói lại lần nữa nhé."}},{"stt":9,"hanzi":"提高","pinyin":"tígāo","hanviet":"Đề cao","pos":"Động từ","meaning":"nâng cao","comps":"提高成绩 (nâng điểm số), 提高水平 (nâng trình độ)","example":{"zh":"多听多说，汉语水平才能提高。","py":"Duō tīng duō shuō, Hànyǔ shuǐpíng cái néng tígāo.","vi":"Nghe nhiều nói nhiều thì trình độ tiếng Hán mới nâng lên được."}},{"stt":10,"hanzi":"历史","pinyin":"lìshǐ","hanviet":"Lịch sử","pos":"Danh từ","meaning":"lịch sử, môn sử","comps":"历史课 (giờ sử), 中国历史 (lịch sử Trung Quốc)","example":{"zh":"我对中国历史很感兴趣。","py":"Wǒ duì Zhōngguó lìshǐ hěn gǎn xìngqù.","vi":"Mình rất hứng thú với lịch sử Trung Quốc."}},{"stt":11,"hanzi":"难","pinyin":"nán","hanviet":"Nan","pos":"Tính từ","meaning":"khó","comps":"很难 (rất khó), 难学 (khó học)","example":{"zh":"汉字有点儿难写，可是很有意思。","py":"Hànzì yǒudiǎnr nán xiě, kěshì hěn yǒu yìsi.","vi":"Chữ Hán hơi khó viết, nhưng rất thú vị."}},{"stt":12,"hanzi":"要求","pinyin":"yāoqiú","hanviet":"Yêu cầu","pos":"Danh từ / Động từ","meaning":"yêu cầu","comps":"考试要求 (yêu cầu của bài thi), 要求很高 (yêu cầu rất cao)","example":{"zh":"我们老师对学生的要求很高。","py":"Wǒmen lǎoshī duì xuésheng de yāoqiú hěn gāo.","vi":"Cô giáo mình yêu cầu học sinh rất cao."}},{"stt":13,"hanzi":"差","pinyin":"chà","hanviet":"Sai","pos":"Tính từ / Động từ","meaning":"kém; thiếu","comps":"考得很差 (thi rất tệ), 差五分八点 (8 giờ kém 5)","example":{"zh":"我的数学比较差，你能帮帮我吗？","py":"Wǒ de shùxué bǐjiào chà, nǐ néng bāngbang wǒ ma?","vi":"Toán của mình khá kém, bạn giúp mình được không?"}},{"stt":14,"hanzi":"复习","pinyin":"fùxí","hanviet":"Phục tập","pos":"Động từ","meaning":"ôn tập","comps":"复习课文 (ôn bài khoá), 复习一下 (ôn lại một chút)","example":{"zh":"明天要考试，我今天晚上得好好复习。","py":"Míngtiān yào kǎoshì, wǒ jīntiān wǎnshang děi hǎohāo fùxí.","vi":"Mai thi rồi, tối nay mình phải ôn thật kỹ."}},{"stt":15,"hanzi":"外语","pinyin":"wàiyǔ","hanviet":"Ngoại ngữ","pos":"Danh từ","meaning":"ngoại ngữ","comps":"学外语 (học ngoại ngữ), 外语老师 (giáo viên ngoại ngữ)","example":{"zh":"学外语要每天听，每天说。","py":"Xué wàiyǔ yào měi tiān tīng, měi tiān shuō.","vi":"Học ngoại ngữ phải nghe mỗi ngày, nói mỗi ngày."}},{"stt":16,"hanzi":"当然","pinyin":"dāngrán","hanviet":"Đương nhiên","pos":"Phó từ","meaning":"đương nhiên, tất nhiên","comps":"当然可以 (tất nhiên là được), 当然了 (đương nhiên rồi)","example":{"zh":"我能用一下你的笔吗？——当然可以。","py":"Wǒ néng yòng yíxià nǐ de bǐ ma? —— Dāngrán kěyǐ.","vi":"Mình mượn bút bạn một chút được không? — Tất nhiên rồi."}},{"stt":17,"hanzi":"遇到","pinyin":"yùdào","hanviet":"Ngộ đáo","pos":"Động từ","meaning":"gặp, gặp phải","comps":"遇到问题 (gặp vấn đề), 遇到老朋友 (gặp bạn cũ)","example":{"zh":"昨天在超市，我遇到了我的初中老师。","py":"Zuótiān zài chāoshì, wǒ yùdàole wǒ de chūzhōng lǎoshī.","vi":"Hôm qua ở siêu thị, mình gặp cô giáo cấp hai."}},{"stt":18,"hanzi":"办公室","pinyin":"bàngōngshì","hanviet":"Biện công thất","pos":"Danh từ","meaning":"văn phòng","comps":"老师办公室 (phòng giáo viên), 在办公室 (ở văn phòng)","example":{"zh":"王老师现在不在办公室，她去上课了。","py":"Wáng lǎoshī xiànzài bú zài bàngōngshì, tā qù shàngkè le.","vi":"Cô Vương giờ không có ở văn phòng, cô đi dạy rồi."}},{"stt":19,"hanzi":"页","pinyin":"yè","hanviet":"Hiệt","pos":"Lượng từ","meaning":"trang","comps":"第五页 (trang 5), 三十页 (30 trang)","example":{"zh":"今天的作业在书上第二十页。","py":"Jīntiān de zuòyè zài shū shang dì-èrshí yè.","vi":"Bài tập hôm nay ở trang 20 trong sách."}},{"stt":20,"hanzi":"对话","pinyin":"duìhuà","hanviet":"Đối thoại","pos":"Động từ / Danh từ","meaning":"đối thoại; đoạn hội thoại","comps":"跟老师对话 (trò chuyện với cô), 这个对话 (đoạn hội thoại này)","example":{"zh":"请两个同学读一下这个对话。","py":"Qǐng liǎng ge tóngxué dú yíxià zhège duìhuà.","vi":"Mời hai bạn đọc đoạn hội thoại này."}},{"stt":21,"hanzi":"明白","pinyin":"míngbai","hanviet":"Minh bạch","pos":"Động từ / Tính từ","meaning":"hiểu; rõ ràng","comps":"我明白了 (em hiểu rồi), 讲得很明白 (giảng rất rõ)","example":{"zh":"老师讲得很明白，大家都听懂了。","py":"Lǎoshī jiǎng de hěn míngbai, dàjiā dōu tīngdǒng le.","vi":"Cô giảng rất rõ, cả lớp đều nghe hiểu."}},{"stt":22,"hanzi":"讲","pinyin":"jiǎng","hanviet":"Giảng","pos":"Động từ","meaning":"giảng, giải thích; kể","comps":"讲题 (giảng bài tập), 讲一遍 (giảng một lượt)","example":{"zh":"这个题我不会，你能给我讲讲吗？","py":"Zhège tí wǒ bú huì, nǐ néng gěi wǒ jiǎngjiang ma?","vi":"Câu này mình không biết làm, bạn giảng cho mình được không?"}},{"stt":23,"hanzi":"句","pinyin":"jù","hanviet":"Cú","pos":"Lượng từ","meaning":"câu (lời nói)","comps":"一句话 (một câu nói), 几句话 (mấy câu)","example":{"zh":"他只说了一句话就走了。","py":"Tā zhǐ shuōle yí jù huà jiù zǒu le.","vi":"Anh ấy chỉ nói một câu rồi đi luôn."}},{"stt":24,"hanzi":"句子","pinyin":"jùzi","hanviet":"Cú tử","pos":"Danh từ","meaning":"câu","comps":"写句子 (viết câu), 这个句子 (câu này)","example":{"zh":"请用\"把\"写三个句子。","py":"Qǐng yòng \"bǎ\" xiě sān ge jùzi.","vi":"Hãy dùng \"把\" viết ba câu."}},{"stt":25,"hanzi":"年级","pinyin":"niánjí","hanviet":"Niên cấp","pos":"Danh từ","meaning":"lớp, khối lớp (năm học)","comps":"三年级 (lớp 3), 几年级 (lớp mấy)","example":{"zh":"我妹妹今年上小学三年级。","py":"Wǒ mèimei jīnnián shàng xiǎoxué sān niánjí.","vi":"Em gái mình năm nay học lớp 3."}},{"stt":26,"hanzi":"后年","pinyin":"hòunián","hanviet":"Hậu niên","pos":"Danh từ","meaning":"năm sau nữa","comps":"明年和后年 (sang năm và năm sau nữa), 后年夏天 (mùa hè năm sau nữa)","example":{"zh":"我们打算后年去中国旅游。","py":"Wǒmen dǎsuàn hòunián qù Zhōngguó lǚyóu.","vi":"Chúng mình định năm sau nữa đi du lịch Trung Quốc."}},{"stt":27,"hanzi":"一般","pinyin":"yìbān","hanviet":"Nhất ban","pos":"Tính từ","meaning":"thông thường; bình thường","comps":"一般是 (thường là), 很一般 (bình thường thôi)","example":{"zh":"我一般晚上十一点睡觉。","py":"Wǒ yìbān wǎnshang shíyī diǎn shuìjiào.","vi":"Mình thường 11 giờ tối đi ngủ."}},{"stt":28,"hanzi":"努力","pinyin":"nǔlì","hanviet":"Nỗ lực","pos":"Tính từ / Động từ","meaning":"nỗ lực, cố gắng","comps":"努力学习 (chăm chỉ học), 非常努力 (rất cố gắng)","example":{"zh":"他学习非常努力，成绩越来越好。","py":"Tā xuéxí fēicháng nǔlì, chéngjì yuè lái yuè hǎo.","vi":"Bạn ấy học rất chăm, điểm ngày càng tốt."}}],"hanzi":[{"char":"数学","pinyin":"shùxué","hanviet":"Số học","chars":["数","学"],"story":"数 đọc shù = con số (đọc shǔ = đếm). 学 = môn học. 数学 = môn học về con số → toán. Các môn khác trong bài: 历史, 外语."},{"char":"认真","pinyin":"rènzhēn","hanviet":"Nhận chân","chars":["认","真"],"story":"认 = 讠 + 人 → nhận ra. 真 = thật. 认真 = coi là thật, không đùa → nghiêm túc, chăm chỉ: 认真学习, 工作很认真."},{"char":"笔记","pinyin":"bǐjì","hanviet":"Bút ký","chars":["笔","记"],"story":"笔 = ⺮ (tre) + 毛 (lông) → bút lông cán tre. 记 = ghi nhớ (bài 2). 笔记 = điều ghi bằng bút → ghi chép; động từ đi kèm là 记: 记笔记."},{"char":"清楚","pinyin":"qīngchu","hanviet":"Thanh sở","chars":["清","楚"],"story":"清 = 氵 + 青 → nước trong. 楚 = rõ. 清楚 = trong và rõ. Tính từ: 写得很清楚; động từ = biết rõ: 我不清楚. Hay làm bổ ngữ: 看清楚, 说清楚."},{"char":"黑板","pinyin":"hēibǎn","hanviet":"Hắc bản","chars":["黑","板"],"story":"黑 = đen. 板 = 木 + 反 → tấm ván gỗ. 黑板 = tấm ván đen → cái bảng. \"Trên bảng\" = 黑板上: 写在黑板上."},{"char":"把","pinyin":"bǎ","hanviet":"Bả","chars":["把"],"story":"把 = 扌 (tay) + 巴 → tay nắm lấy. Giới từ 把 \"nắm\" tân ngữ đưa lên trước động từ để nói đã làm gì với nó: 把书放在桌子上. Bài 12 học thêm 把 với nghĩa khác."},{"char":"作业","pinyin":"zuòyè","hanviet":"Tác nghiệp","chars":["作","业"],"story":"作 = 亻 + 乍 → làm. 业 = việc học, nghề nghiệp. 作业 = việc phải làm → bài tập. Động từ đi kèm: 写作业, 做作业."},{"char":"遍","pinyin":"biàn","hanviet":"Biến","chars":["遍"],"story":"遍 = 辶 (đi) + 扁 chỉ âm → đi khắp lượt. 遍 đếm động tác làm trọn từ đầu đến cuối: 看一遍, 讲一遍. 次 chỉ đếm số lần: 去过两次."},{"char":"提高","pinyin":"tígāo","hanviet":"Đề cao","chars":["提","高"],"story":"提 = 扌 + 是 → xách lên. 高 = cao. 提高 = nhấc lên cao → nâng cao: 提高成绩, 提高水平."},{"char":"历史","pinyin":"lìshǐ","hanviet":"Lịch sử","chars":["历","史"],"story":"历 = trải qua. 史 = sử, ghi chép việc đã qua. 历史 = những gì đã trải qua → lịch sử: 历史课, 中国历史."},{"char":"难","pinyin":"nán","hanviet":"Nan","chars":["难"],"story":"难 = 又 + 隹 (chim đuôi ngắn) → bắt chim thật khó. 难 nán = khó: 很难, 难写. Đã gặp trong 难看, 难过 (bài 5)."},{"char":"要求","pinyin":"yāoqiú","hanviet":"Yêu cầu","chars":["要","求"],"story":"要 = muốn, cần. 求 = cầu, xin. 要求 = đòi hỏi → yêu cầu. Danh từ: 考试的要求; động từ: 老师要求我们每天写作业."},{"char":"差","pinyin":"chà","hanviet":"Sai","chars":["差"],"story":"差 đọc chà = kém (考得很差), thiếu (差五分八点). Đã gặp trong 差不多 (bài 8): chẳng thiếu bao nhiêu → gần như."},{"char":"复习","pinyin":"fùxí","hanviet":"Phục tập","chars":["复","习"],"story":"复 = lặp lại. 习 = tập (练习 bài 9). 复习 = tập lại → ôn tập: 复习课文, 复习生词."},{"char":"外语","pinyin":"wàiyǔ","hanviet":"Ngoại ngữ","chars":["外","语"],"story":"外 = bên ngoài. 语 = tiếng nói (汉语). 外语 = tiếng nước ngoài: 学外语, 外语考试."},{"char":"当然","pinyin":"dāngrán","hanviet":"Đương nhiên","chars":["当","然"],"story":"当 = đáng, nên. 然 = như vậy. 当然 = lẽ ra như vậy → đương nhiên. Có thể đứng một mình để trả lời: 当然！ 当然可以！"},{"char":"遇到","pinyin":"yùdào","hanviet":"Ngộ đáo","chars":["遇","到"],"story":"遇 = 辶 (đi) + 禺 → đi đường gặp nhau. 到 = bổ ngữ kết quả. 遇到 = gặp (tình cờ), gặp phải: 遇到老朋友, 遇到问题."},{"char":"办公室","pinyin":"bàngōngshì","hanviet":"Biện công thất","chars":["办","公","室"],"story":"办 = làm, lo việc (办信用卡 bài 3). 公 = việc chung. 室 = 宀 + 至 → căn phòng (教室). 办公室 = phòng làm việc → văn phòng."},{"char":"页","pinyin":"yè","hanviet":"Hiệt","chars":["页"],"story":"页 vốn vẽ cái đầu người (题 cũng có bộ 页). Mượn chỉ trang sách: 第五页, 这本书有两百页."},{"char":"对话","pinyin":"duìhuà","hanviet":"Đối thoại","chars":["对","话"],"story":"对 = đối diện. 话 = 讠 + 舌 → lời nói. 对话 = hai bên đối mặt nói với nhau → đối thoại; cũng chỉ \"đoạn hội thoại\": 书上的对话."},{"char":"明白","pinyin":"míngbai","hanviet":"Minh bạch","chars":["明","白"],"story":"明 = 日 + 月 → sáng. 白 = trắng. 明白 = sáng rõ → hiểu ra: 我明白了. Giống 懂, nhưng 明白 còn làm tính từ: 讲得很明白."},{"char":"讲","pinyin":"jiǎng","hanviet":"Giảng","chars":["讲"],"story":"讲 = 讠 (lời nói) + 井. 讲 = giảng giải: 讲题, 讲课; cũng = nói, kể. Giảng cho ai: 给 + người + 讲: 再给你们讲一遍."},{"char":"句","pinyin":"jù","hanviet":"Cú","chars":["句"],"story":"句 = 勹 (bọc) + 口 → lời nói gói trọn → câu. Lượng từ cho lời nói: 一句话, 这几句话."},{"char":"句子","pinyin":"jùzi","hanviet":"Cú tử","chars":["句","子"],"story":"句 + hậu tố 子 → danh từ \"câu\": 这个句子, 写句子. So sánh: 一句话 (句 là lượng từ) · 一个句子 (句子 là danh từ)."},{"char":"年级","pinyin":"niánjí","hanviet":"Niên cấp","chars":["年","级"],"story":"年 = năm. 级 = 纟 + 及 → bậc, cấp. 年级 = bậc theo năm học → lớp mấy. 初中二年级 = năm hai cấp hai = lớp 8 ở Việt Nam."},{"char":"后年","pinyin":"hòunián","hanviet":"Hậu niên","chars":["后","年"],"story":"后 = sau. 后年 = năm sau nữa. Dãy năm: 前年 · 去年 · 今年 · 明年 · 后年 (giống 前天 … 后天)."},{"char":"一般","pinyin":"yìbān","hanviet":"Nhất ban","chars":["一","般"],"story":"般 = loại, kiểu. 一般 = cùng một kiểu → thông thường: 我一般七点起床; làm vị ngữ = bình thường, xoàng: 他的成绩很一般."},{"char":"努力","pinyin":"nǔlì","hanviet":"Nỗ lực","chars":["努","力"],"story":"努 = 奴 + 力, 力 = sức. 努力 = dồn hết sức → nỗ lực: 努力学习, 我现在非常努力. Khác 认真 (nghiêm túc, cẩn thận)."}],"grammar":[{"title":"主语 + 把 + 宾语 + 动词 + 在/到 + 地点","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b><small>(đem)</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>宾语</b><small>vật xác định</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>在 / 到</b><small>ở / tới</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>地点</b><small>nơi chốn</small></span></div>","summary":"<p class=\"gr-lead\">Đem … (để) ở / tới …</p><ul><li>Tân ngữ sau <span class=\"zh\">把</span> là người / vật <b>xác định</b>; sau động từ là <span class=\"zh\">在 / 到 + nơi chốn</span>: <span class=\"zh\">我会把这些题都记在本子上</span>.</li><li><span class=\"zh\">不 / 没</span> và động từ năng nguyện (<span class=\"zh\">能 · 会 · 应该</span>) đứng <b>trước 把</b>: <span class=\"zh\">你不能把名字写在这里</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">把 + 宾语 + 动词 + 在 / 到</span> · Ba dạng thường gặp</h4><p>Khẳng định · năng nguyện · phủ định</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Khẳng định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>他</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>书</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>放在</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>桌子上</b></span></div><div class=\"fx-ex zh\">他把书放在桌子上。</div><div class=\"fx-lbl\">Năng nguyện + 把</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我会</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>题</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>记在</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>本子上</b></span></div><div class=\"fx-ex zh\">我会把题记在本子上。</div><div class=\"fx-lbl\">不 / 没 + 把</div><div class=\"fx-row\"><span class=\"fx-p\"><b>你不能</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>名字</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>写在</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>这里</b></span></div><div class=\"fx-ex zh\">你不能把名字写在这里。</div></div><p class=\"gr-key\"><span class=\"zh\">V + 在</span> = để <b>ở</b> đâu (vật dừng lại)　·　<span class=\"zh\">V + 到</span> = đưa <b>tới</b> đâu (vật di chuyển tới)</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">老师把作业本放到桌子上了。</span> = Cô đặt vở bài tập lên bàn rồi.</p>","note":"<b>Lưu ý:</b> ✗ <span class=\"zh\">你把名字不能写在这里</span> → ✓ <span class=\"zh\">你不能把名字写在这里</span>","examples":[{"zh":"我会把这些题都记在本子上。","py":"Wǒ huì bǎ zhèxiē tí dōu jì zài běnzi shang.","vi":"Mình sẽ chép hết những bài này vào vở."},{"zh":"老师把作业本放到桌子上了。","py":"Lǎoshī bǎ zuòyèběn fàngdào zhuōzi shang le.","vi":"Cô đặt vở bài tập lên bàn rồi."},{"zh":"你不能把名字写在这里。","py":"Nǐ bù néng bǎ míngzi xiě zài zhèlǐ.","vi":"Bạn không được viết tên vào chỗ này."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">司机把我们的行李____。</span><span class=\"qz-hint\">Tài xế đã để hành lý của chúng tôi lên xe.</span>","answer":["放到车上了","放在车上了","放到车上"],"explain":"司机把我们的行李放到车上了。 (Sījī bǎ wǒmen de xíngli fàngdào chē shang le.)"},{"type":"fill","q":"<span class=\"zh\">检票的时候我才发现，没把护照____。</span><span class=\"qz-hint\">Lúc soát vé mình mới phát hiện không mang hộ chiếu theo người.</span>","answer":["带在身上","带来"],"explain":"检票的时候我才发现，没把护照带在身上。 (Jiǎnpiào de shíhou wǒ cái fāxiàn, méi bǎ hùzhào dài zài shēn shang.)"}]},{"title":"在 + 名词 / 短语 + 上 / 中 / 下","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>在</b><small>(tại)</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>名词 / 短语</b><small>danh từ / cụm từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>上 / 中 / 下</b><small>phạm vi / hoàn cảnh / điều kiện</small></span></div>","summary":"<p class=\"gr-lead\">Về mặt … · Trong … · Dưới (nhờ) …</p><ul><li><span class=\"zh\">在…上</span> = <b>về mặt</b> …: <span class=\"zh\">在工作上</span> · <span class=\"zh\">在…中</span> = <b>trong</b> (lúc / hoàn cảnh) …: <span class=\"zh\">在比赛中</span>.</li><li><span class=\"zh\">在 + … 的 + động từ 2 âm tiết + 下</span> = <b>dưới / nhờ</b> (điều kiện) …: <span class=\"zh\">在老师的帮助下</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">在……上 · 在……中 · 在……下</span> · Ba nghĩa của cấu trúc</h4><p>Phạm vi · hoàn cảnh · điều kiện</p><div class=\"gr-formula\"><div class=\"fx-lbl\">在…上 · về mặt</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>在</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>学习</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>上</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>遇到问题都可以问我</b></span></div><div class=\"fx-ex zh\">在学习上，遇到什么问题都可以问我。</div><div class=\"fx-lbl\">在…中 · trong lúc</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>在</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>比赛</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>中</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>他得分最高</b></span></div><div class=\"fx-ex zh\">在比赛中，他得分最高。</div><div class=\"fx-lbl\">在…下 · nhờ, dưới</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>在</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>她的影响</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>下</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>我开始喜欢拍照</b></span></div><div class=\"fx-ex zh\">在她的影响下，我开始喜欢拍照。</div></div><p class=\"gr-key\">Hay gặp: <span class=\"zh\">在生活上 · 在假期中 · 在…的帮助下 · 在…的影响下</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">在学习上，遇到什么问题都可以问我。</span> = Về chuyện học, gặp vấn đề gì cũng có thể hỏi mình.</p>","note":"<b>Lưu ý:</b> \"Dưới sự giúp đỡ của cô\" — 下 đứng <b>cuối</b>: ✗ <span class=\"zh\">在下老师的帮助</span> → ✓ <span class=\"zh\">在老师的帮助下</span>","examples":[{"zh":"在工作上，他总是能给我很多帮助。","py":"Zài gōngzuò shang, tā zǒngshì néng gěi wǒ hěn duō bāngzhù.","vi":"Trong công việc, anh ấy luôn giúp mình rất nhiều."},{"zh":"在假期中，我认识了几个新朋友。","py":"Zài jiàqī zhōng, wǒ rènshile jǐ ge xīn péngyou.","vi":"Trong kỳ nghỉ, mình quen được mấy người bạn mới."},{"zh":"在老师的帮助下，我的成绩提高很快。","py":"Zài lǎoshī de bāngzhù xià, wǒ de chéngjì tígāo hěn kuài.","vi":"Nhờ thầy cô giúp đỡ, điểm của mình tiến bộ rất nhanh."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">在____，我和弟弟都对足球感兴趣了。</span><span class=\"qz-hint\">Do ảnh hưởng của bố, mình và em trai đều mê bóng đá.</span>","answer":["爸爸的影响下"],"explain":"在爸爸的影响下，我和弟弟都对足球感兴趣了。 (Zài bàba de yǐngxiǎng xià, wǒ hé dìdi dōu duì zúqiú gǎn xìngqù le.)"},{"type":"fill","q":"<span class=\"zh\">在生活上，我帮助她；____，她帮助我。</span><span class=\"qz-hint\">Trong cuộc sống mình giúp bạn ấy; trong học tập bạn ấy giúp mình.</span>","answer":["在学习上"],"explain":"在生活上，我帮助她；在学习上，她帮助我。 (Zài shēnghuó shang, wǒ bāngzhù tā; zài xuéxí shang, tā bāngzhù wǒ.)"},{"type":"fill","q":"<span class=\"zh\">他非常热情，____，我们玩得很开心。</span><span class=\"qz-hint\">Anh ấy rất nhiệt tình, nhờ anh ấy giúp, chúng mình chơi rất vui.</span>","answer":["在他的帮助下","在他的帮助之下"],"explain":"他非常热情，在他的帮助下，我们玩得很开心。 (Tā fēicháng rèqíng, zài tā de bāngzhù xià, wǒmen wán de hěn kāixīn.)"}]},{"title":"主语 + 把 + 宾语₁ + 动词 + 给 + 宾语₂","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b><small>(đem)</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>宾语₁</b><small>vật xác định</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>给</b><small>cho</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>宾语₂</b><small>người nhận</small></span></div>","summary":"<p class=\"gr-lead\">Đem … (đưa) cho …</p><ul><li>Động từ hay gặp: <span class=\"zh\">还 · 送 · 带 · 借</span> + <span class=\"zh\">给 + người</span>: <span class=\"zh\">我把礼物送给她了</span>.</li><li><span class=\"zh\">不 / 没</span>, động từ năng nguyện đứng <b>trước 把</b>: <span class=\"zh\">我还没把书还给他</span> · <span class=\"zh\">我要把花送给妈妈</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">把（1）· 把（2）</span> · Đổi chỗ · đổi chủ</h4><p>Đối chiếu hai loại câu chữ 把</p><div class=\"gr-formula\"><div class=\"fx-lbl\">把 (1) · đổi chỗ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>书</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>放在</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>桌子上</b></span></div><div class=\"fx-ex zh\">我把书放在桌子上。</div><div class=\"fx-lbl\">把 (2) · đổi chủ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>书</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>还给</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>老师</b></span></div><div class=\"fx-ex zh\">我把书还给老师了。</div><div class=\"fx-lbl\">Phủ định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我还没</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>笔记</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>借给</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>他</b></span></div><div class=\"fx-ex zh\">我还没把笔记借给他。</div></div><p class=\"gr-key\"><span class=\"zh\">在 / 到 + nơi chốn</span> → vật đổi <b>chỗ</b>　·　<span class=\"zh\">给 + người</span> → vật đổi <b>chủ</b></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">你明天再把书还给我。</span> = Mai các em hẵng trả sách cho cô.</p>","note":"<b>Lưu ý:</b> Vật sau 把 phải xác định: ✗ <span class=\"zh\">我把一本书送给她</span> → ✓ <span class=\"zh\">我把这本书送给她</span>","examples":[{"zh":"你明天再把书还给我。","py":"Nǐ míngtiān zài bǎ shū huán gěi wǒ.","vi":"Mai các em hẵng trả sách cho cô."},{"zh":"我把礼物送给她了。","py":"Wǒ bǎ lǐwù sòng gěi tā le.","vi":"Mình tặng quà cho cô ấy rồi."},{"zh":"请你把这本书带给老师。","py":"Qǐng nǐ bǎ zhè běn shū dài gěi lǎoshī.","vi":"Bạn mang cuốn sách này đến cho cô giúp mình nhé."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">今天是妈妈的生日，我要把这些花____。</span><span class=\"qz-hint\">Hôm nay sinh nhật mẹ, mình sẽ tặng mẹ chỗ hoa này.</span>","answer":["送给她","送给妈妈"],"explain":"今天是妈妈的生日，我要把这些花送给她。 (Jīntiān shì māma de shēngrì, wǒ yào bǎ zhèxiē huā sòng gěi tā.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在教室里","titleVi":"Lớp học — bàn về cách học toán","lines":[{"speaker":"同","name":"Bạn học","zh":"你的数学越来越好，能不能介绍一下学习方法？","py":"Nǐ de shùxué yuè lái yuè hǎo, néng bu néng jièshào yíxià xuéxí fāngfǎ?","vi":"Môn toán của cậu ngày càng giỏi, giới thiệu cách học được không?"},{"speaker":"小","name":"Tiểu Tuyết","zh":"没有什么特别的方法，认真听课，认真记笔记。","py":"Méiyǒu shénme tèbié de fāngfǎ, rènzhēn tīngkè, rènzhēn jì bǐjì.","vi":"Chẳng có cách gì đặc biệt, chăm chú nghe giảng, chăm chỉ ghi chép."},{"speaker":"同","name":"Bạn học","zh":"我看过你的笔记，记得非常清楚。","py":"Wǒ kànguo nǐ de bǐjì, jì de fēicháng qīngchu.","vi":"Mình xem vở ghi của cậu rồi, ghi rất rõ ràng."},{"speaker":"小","name":"Tiểu Tuyết","zh":"老师写在黑板上的题都很重要，所以我会把这些题都记在本子上。","py":"Lǎoshī xiě zài hēibǎn shang de tí dōu hěn zhòngyào, suǒyǐ wǒ huì bǎ zhèxiē tí dōu jì zài běnzi shang.","vi":"Bài thầy cô viết trên bảng đều quan trọng, nên mình chép hết vào vở."},{"speaker":"同","name":"Bạn học","zh":"你说得对。我没有记笔记的习惯。","py":"Nǐ shuō de duì. Wǒ méiyǒu jì bǐjì de xíguàn.","vi":"Cậu nói đúng. Mình không có thói quen ghi chép."},{"speaker":"小","name":"Tiểu Tuyết","zh":"笔记挺重要的，我每天写作业以前，都要看一遍。","py":"Bǐjì tǐng zhòngyào de, wǒ měi tiān xiě zuòyè yǐqián, dōu yào kàn yí biàn.","vi":"Ghi chép khá quan trọng đấy, ngày nào trước khi làm bài tập mình cũng xem lại một lượt."},{"speaker":"同","name":"Bạn học","zh":"这个方法真好！我以后也试试，希望能提高成绩。","py":"Zhège fāngfǎ zhēn hǎo! Wǒ yǐhòu yě shìshi, xīwàng néng tígāo chéngjì.","vi":"Cách này hay thật! Sau này mình cũng thử, mong nâng được điểm."}]},{"titleZh":"课文二 · 在教室里","titleVi":"Lớp học — chuyện bài thi hôm qua","lines":[{"speaker":"同","name":"Bạn học","zh":"小雪，昨天的考试，你考得怎么样？","py":"Xiǎoxuě, zuótiān de kǎoshì, nǐ kǎo de zěnmeyàng?","vi":"Tiểu Tuyết, bài thi hôm qua cậu làm thế nào?"},{"speaker":"小","name":"Tiểu Tuyết","zh":"我觉得历史有点儿难，你呢？","py":"Wǒ juéde lìshǐ yǒudiǎnr nán, nǐ ne?","vi":"Mình thấy môn sử hơi khó, còn cậu?"},{"speaker":"同","name":"Bạn học","zh":"数学考试我没看清楚要求，做错了好几个题，考得挺差的。","py":"Shùxué kǎoshì wǒ méi kàn qīngchu yāoqiú, zuòcuòle hǎo jǐ ge tí, kǎo de tǐng chà de.","vi":"Thi toán mình không đọc kỹ yêu cầu, làm sai mấy câu liền, thi khá tệ."},{"speaker":"小","name":"Tiểu Tuyết","zh":"明天还有考试呢，别想那么多了，先复习外语吧。","py":"Míngtiān hái yǒu kǎoshì ne, bié xiǎng nàme duō le, xiān fùxí wàiyǔ ba.","vi":"Mai còn thi nữa đấy, đừng nghĩ nhiều thế, ôn ngoại ngữ trước đi."},{"speaker":"同","name":"Bạn học","zh":"外语作业里有几个问题，我可以问问你吗？","py":"Wàiyǔ zuòyè li yǒu jǐ ge wèntí, wǒ kěyǐ wènwen nǐ ma?","vi":"Bài tập ngoại ngữ có mấy câu, mình hỏi cậu được không?"},{"speaker":"小","name":"Tiểu Tuyết","zh":"当然可以。在学习上，遇到什么问题都可以问我。","py":"Dāngrán kěyǐ. Zài xuéxí shang, yùdào shénme wèntí dōu kěyǐ wèn wǒ.","vi":"Đương nhiên được. Về chuyện học, gặp vấn đề gì cũng cứ hỏi mình."},{"gap":true,"zh":"……"},{"speaker":"小","name":"Tiểu Tuyết","zh":"不好意思，这几个题我也不会。咱们还是一起去办公室问问李老师吧。","py":"Bù hǎoyìsi, zhè jǐ ge tí wǒ yě bú huì. Zánmen háishi yìqǐ qù bàngōngshì wènwen Lǐ lǎoshī ba.","vi":"Ngại quá, mấy câu này mình cũng không biết. Hay mình cùng lên văn phòng hỏi cô Lý đi."}]},{"titleZh":"课文三 · 在李老师办公室","titleVi":"Văn phòng cô Lý — hỏi bài","lines":[{"speaker":"同","name":"Bạn học","zh":"李老师，书上有几个问题，我们想问问您。","py":"Lǐ lǎoshī, shū shang yǒu jǐ ge wèntí, wǒmen xiǎng wènwen nín.","vi":"Cô Lý ơi, trong sách có mấy câu, chúng em muốn hỏi cô ạ."},{"speaker":"师","name":"Cô Lý","zh":"好，坐下说吧，哪个题不会？","py":"Hǎo, zuòxia shuō ba, nǎge tí bú huì?","vi":"Được, ngồi xuống nói nào, câu nào không làm được?"},{"speaker":"同","name":"Bạn học","zh":"书上第五页的这个对话我看不懂，小雪也不明白。","py":"Shū shang dì-wǔ yè de zhège duìhuà wǒ kàn bu dǒng, Xiǎoxuě yě bù míngbai.","vi":"Đoạn hội thoại trang 5 em đọc không hiểu, Tiểu Tuyết cũng không hiểu ạ."},{"speaker":"师","name":"Cô Lý","zh":"我课上讲过这几句话，再给你们讲一遍。","py":"Wǒ kè shang jiǎngguo zhè jǐ jù huà, zài gěi nǐmen jiǎng yí biàn.","vi":"Mấy câu này cô giảng trên lớp rồi, cô giảng lại cho các em một lượt nhé."},{"zh":"（李老师给学生讲题。）","py":"(Lǐ lǎoshī gěi xuésheng jiǎng tí.)","vi":"(Cô Lý giảng bài cho học sinh.)"},{"speaker":"同","name":"Bạn học","zh":"我终于懂了。这些句子一点儿也不难。","py":"Wǒ zhōngyú dǒng le. Zhèxiē jùzi yìdiǎnr yě bù nán.","vi":"Cuối cùng em cũng hiểu rồi. Mấy câu này chẳng khó chút nào."},{"speaker":"小","name":"Tiểu Tuyết","zh":"我也明白了，谢谢您，李老师。","py":"Wǒ yě míngbai le, xièxie nín, Lǐ lǎoshī.","vi":"Em cũng hiểu rồi, cảm ơn cô Lý ạ."},{"speaker":"师","name":"Cô Lý","zh":"我这本书上还有几个练习，你们回家也做一做，明天再把书还给我。","py":"Wǒ zhè běn shū shang hái yǒu jǐ ge liànxí, nǐmen huí jiā yě zuò yi zuò, míngtiān zài bǎ shū huán gěi wǒ.","vi":"Sách này của cô còn mấy bài luyện tập, các em về nhà làm thử, mai hẵng trả sách cho cô."}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — Tiểu Tuyết viết email","para":true,"speaker":"小","lines":[{"zh":"家月姐姐：","py":"Jiāyuè jiějie:","vi":"Chị Gia Nguyệt thân mến!"},{"zh":"你最近怎么样？忙不忙？","py":"Nǐ zuìjìn zěnmeyàng? Máng bu máng?","vi":"Dạo này chị thế nào? Có bận không ạ?","br":true},{"zh":"我现在上初中二年级，学习越来越忙，后年就要考高中了。","py":"Wǒ xiànzài shàng chūzhōng èr niánjí, xuéxí yuè lái yuè máng, hòunián jiù yào kǎo gāozhōng le.","vi":"Em đang học lớp 8 (năm hai cấp hai), việc học ngày càng bận, năm sau nữa là thi vào cấp ba rồi.","br":true},{"zh":"中国的学校一般是小学六年，初中三年，高中三年。","py":"Zhōngguó de xuéxiào yìbān shì xiǎoxué liù nián, chūzhōng sān nián, gāozhōng sān nián.","vi":"Trường học ở Trung Quốc thường là tiểu học sáu năm, cấp hai ba năm, cấp ba ba năm."},{"zh":"妈妈说想考上好大学，就得上一个好高中；为了考上好高中，初中就得有一个不错的成绩，所以我现在非常努力。","py":"Māma shuō xiǎng kǎoshang hǎo dàxué, jiù děi shàng yí ge hǎo gāozhōng; wèile kǎoshang hǎo gāozhōng, chūzhōng jiù děi yǒu yí ge búcuò de chéngjì, suǒyǐ wǒ xiànzài fēicháng nǔlì.","vi":"Mẹ nói muốn đỗ đại học tốt thì phải học trường cấp ba tốt; để đỗ cấp ba tốt thì cấp hai phải có thành tích khá, vì vậy bây giờ em rất cố gắng."},{"zh":"家月姐姐，你知道吗？","py":"Jiāyuè jiějie, nǐ zhīdào ma?","vi":"Chị Gia Nguyệt, chị biết không?","br":true},{"zh":"在你的影响下，我也开始喜欢拍照了。","py":"Zài nǐ de yǐngxiǎng xià, wǒ yě kāishǐ xǐhuan pāizhào le.","vi":"Nhờ ảnh hưởng của chị, em cũng bắt đầu thích chụp ảnh rồi."},{"zh":"下次你再来北京，我给你看看我照的照片。","py":"Xià cì nǐ zài lái Běijīng, wǒ gěi nǐ kànkan wǒ zhào de zhàopiàn.","vi":"Lần sau chị lại đến Bắc Kinh, em cho chị xem ảnh em chụp nhé."}]}]},"extra":[],"activity":{"act":[{"zh":"多人活动","py":"duōrén huódòng","tag":"Hoạt động nhóm","mean":"Cách học ngoại ngữ","q":{"zh":"四人一组，交流学习外语的方法，然后向全班分享。","py":"Sì rén yì zǔ, jiāoliú xuéxí wàiyǔ de fāngfǎ, ránhòu xiàng quán bān fēnxiǎng.","vi":"Nhóm 4 người trao đổi cách học ngoại ngữ, chia sẻ trước lớp; cả lớp bỏ phiếu chọn 3 cách hiệu quả nhất."},"items":[{"zh":"认真记笔记，回家再看一遍。","py":"Rènzhēn jì bǐjì, huí jiā zài kàn yí biàn.","vi":"Chăm chỉ ghi chép, về nhà xem lại một lượt."},{"zh":"把生词写在本子上，每天复习。","py":"Bǎ shēngcí xiě zài běnzi shang, měi tiān fùxí.","vi":"Chép từ mới vào vở, ngày nào cũng ôn."},{"zh":"遇到不明白的句子，就去问老师。","py":"Yùdào bù míngbai de jùzi, jiù qù wèn lǎoshī.","vi":"Gặp câu nào không hiểu thì đi hỏi thầy cô."},{"zh":"在朋友的帮助下练习对话。","py":"Zài péngyou de bāngzhù xià liànxí duìhuà.","vi":"Nhờ bạn bè giúp để luyện hội thoại."}]}],"speak":[]}},{"id":"k3v3-b11","courseId":"k3v3","order":11,"title":"Xem ra tôi không giải quyết được vấn đề này","titleZh":"看来我没办法解决这个问题","titlePy":"kànlái wǒ méi bànfǎ jiějué zhège wèntí","vocab":[{"stt":1,"hanzi":"会议","pinyin":"huìyì","hanviet":"Hội nghị","pos":"Danh từ","meaning":"cuộc họp, hội nghị","comps":"会议室 (phòng họp), 参加会议 (dự họp)","example":{"zh":"明天上午的会议很重要，大家都要参加。","py":"Míngtiān shàngwǔ de huìyì hěn zhòngyào, dàjiā dōu yào cānjiā.","vi":"Cuộc họp sáng mai rất quan trọng, mọi người đều phải dự."}},{"stt":2,"hanzi":"经理","pinyin":"jīnglǐ","hanviet":"Kinh lý","pos":"Danh từ","meaning":"giám đốc, quản lý","comps":"刘经理 (giám đốc Lưu), 经理办公室 (phòng giám đốc)","example":{"zh":"经理现在正在开会，请您等一下。","py":"Jīnglǐ xiànzài zhèngzài kāihuì, qǐng nín děng yíxià.","vi":"Giám đốc đang họp, mời anh/chị đợi một chút."}},{"stt":3,"hanzi":"开会","pinyin":"kāihuì","hanviet":"Khai hội","pos":"Động từ (li hợp)","meaning":"họp","comps":"开完会 (họp xong), 开了两个小时会 (họp hai tiếng)","example":{"zh":"我们每个星期一上午都要开会。","py":"Wǒmen měi ge xīngqīyī shàngwǔ dōu yào kāihuì.","vi":"Sáng thứ Hai nào chúng tôi cũng phải họp."}},{"stt":4,"hanzi":"后天","pinyin":"hòutiān","hanviet":"Hậu thiên","pos":"Danh từ","meaning":"ngày kia","comps":"后天上午 (sáng ngày kia), 明天或者后天 (mai hoặc ngày kia)","example":{"zh":"今天是星期三，后天是星期五。","py":"Jīntiān shì xīngqīsān, hòutiān shì xīngqīwǔ.","vi":"Hôm nay là thứ Tư, ngày kia là thứ Sáu."}},{"stt":5,"hanzi":"地点","pinyin":"dìdiǎn","hanviet":"Địa điểm","pos":"Danh từ","meaning":"địa điểm","comps":"会议地点 (địa điểm họp), 时间和地点 (thời gian và địa điểm)","example":{"zh":"请告诉我比赛的时间和地点。","py":"Qǐng gàosu wǒ bǐsài de shíjiān hé dìdiǎn.","vi":"Hãy cho mình biết thời gian và địa điểm thi đấu."}},{"stt":6,"hanzi":"室","pinyin":"shì","hanviet":"Thất","pos":"Danh từ","meaning":"phòng","comps":"会议室 (phòng họp), 教室 (lớp học), 办公室 (văn phòng)","example":{"zh":"李老师的办公室在三层305室。","py":"Lǐ lǎoshī de bàngōngshì zài sān céng 305 shì.","vi":"Văn phòng cô Lý ở phòng 305 tầng ba."}},{"stt":7,"hanzi":"发","pinyin":"fā","hanviet":"Phát","pos":"Động từ","meaning":"gửi","comps":"发邮件 (gửi email), 发照片 (gửi ảnh)","example":{"zh":"你把昨天的照片发给我吧。","py":"Nǐ bǎ zuótiān de zhàopiàn fā gěi wǒ ba.","vi":"Bạn gửi ảnh hôm qua cho mình nhé."}},{"stt":8,"hanzi":"笔记本（电脑）","pinyin":"bǐjìběn (diànnǎo)","hanviet":"Bút ký bản (điện não)","pos":"Danh từ","meaning":"máy tính xách tay, laptop","comps":"笔记本电脑 (laptop), 笔记本 (laptop; sổ ghi chép)","example":{"zh":"我的笔记本电脑很轻，去哪儿都能带着。","py":"Wǒ de bǐjìběn diànnǎo hěn qīng, qù nǎr dōu néng dàizhe.","vi":"Laptop của mình rất nhẹ, đi đâu cũng mang theo được."}},{"stt":9,"hanzi":"或者","pinyin":"huòzhě","hanviet":"Hoặc giả","pos":"Liên từ","meaning":"hoặc","comps":"今天或者明天 (hôm nay hoặc mai), 坐地铁或者打车 (đi tàu điện hoặc taxi)","example":{"zh":"周末我常常在家看书或者去爬山。","py":"Zhōumò wǒ chángcháng zài jiā kàn shū huòzhě qù páshān.","vi":"Cuối tuần mình thường ở nhà đọc sách hoặc đi leo núi."}},{"stt":10,"hanzi":"声音","pinyin":"shēngyīn","hanviet":"Thanh âm","pos":"Danh từ","meaning":"âm thanh, tiếng","comps":"声音很大 (tiếng to), 听不见声音 (không nghe thấy tiếng)","example":{"zh":"你的声音太小了，我听不清楚。","py":"Nǐ de shēngyīn tài xiǎo le, wǒ tīng bu qīngchu.","vi":"Tiếng bạn nhỏ quá, mình nghe không rõ."}},{"stt":11,"hanzi":"看来","pinyin":"kànlái","hanviet":"Khán lai","pos":"Động từ","meaning":"xem ra, có vẻ như","comps":"看来他不来了 (xem ra anh ấy không đến), 看来要下雨了 (có vẻ sắp mưa)","example":{"zh":"他还没起床，看来昨天睡得很晚。","py":"Tā hái méi qǐchuáng, kànlái zuótiān shuì de hěn wǎn.","vi":"Cậu ấy vẫn chưa dậy, xem ra hôm qua ngủ muộn lắm."}},{"stt":12,"hanzi":"办法","pinyin":"bànfǎ","hanviet":"Biện pháp","pos":"Danh từ","meaning":"cách, biện pháp","comps":"有办法 (có cách), 没办法 (hết cách), 想办法 (nghĩ cách)","example":{"zh":"别着急，我们一起想想办法。","py":"Bié zháojí, wǒmen yìqǐ xiǎngxiang bànfǎ.","vi":"Đừng lo, chúng mình cùng nghĩ cách."}},{"stt":13,"hanzi":"解决","pinyin":"jiějué","hanviet":"Giải quyết","pos":"Động từ","meaning":"giải quyết","comps":"解决问题 (giải quyết vấn đề), 解决不了 (không giải quyết được)","example":{"zh":"这个问题我解决不了，得问问经理。","py":"Zhège wèntí wǒ jiějué bu liǎo, děi wènwen jīnglǐ.","vi":"Vấn đề này em không giải quyết được, phải hỏi giám đốc."}},{"stt":14,"hanzi":"只能","pinyin":"zhǐ néng","hanviet":"Chỉ năng","pos":"Cụm từ","meaning":"chỉ có thể, đành phải","comps":"只能这样 (đành vậy), 只能走回去 (đành đi bộ về)","example":{"zh":"太晚了，没有出租车，我们只能走回去。","py":"Tài wǎn le, méiyǒu chūzūchē, wǒmen zhǐ néng zǒu huíqu.","vi":"Muộn quá, không có taxi, chúng mình đành đi bộ về."}},{"stt":15,"hanzi":"别人","pinyin":"biérén","hanviet":"Biệt nhân","pos":"Đại từ","meaning":"người khác","comps":"帮助别人 (giúp người khác), 问别人 (hỏi người khác)","example":{"zh":"这是别人的东西，你不能拿。","py":"Zhè shì biérén de dōngxi, nǐ bù néng ná.","vi":"Đây là đồ của người khác, bạn không được lấy."}},{"stt":16,"hanzi":"请假","pinyin":"qǐngjià","hanviet":"Thỉnh giả","pos":"Động từ (li hợp)","meaning":"xin nghỉ","comps":"请一天假 (xin nghỉ một ngày), 请病假 (xin nghỉ ốm)","example":{"zh":"我今天有点儿不舒服，想跟经理请半天假。","py":"Wǒ jīntiān yǒudiǎnr bù shūfu, xiǎng gēn jīnglǐ qǐng bàn tiān jià.","vi":"Hôm nay em hơi mệt, muốn xin giám đốc nghỉ nửa ngày."}},{"stt":17,"hanzi":"同事","pinyin":"tóngshì","hanviet":"Đồng sự","pos":"Danh từ","meaning":"đồng nghiệp","comps":"老同事 (đồng nghiệp lâu năm), 公司的同事 (đồng nghiệp ở công ty)","example":{"zh":"下班以后，我常常跟同事一起去吃饭。","py":"Xiàbān yǐhòu, wǒ chángcháng gēn tóngshì yìqǐ qù chīfàn.","vi":"Tan làm, mình hay cùng đồng nghiệp đi ăn."}},{"stt":18,"hanzi":"休假","pinyin":"xiūjià","hanviet":"Hưu giả","pos":"Động từ (li hợp)","meaning":"nghỉ phép","comps":"休一个星期假 (nghỉ phép một tuần), 去海边休假 (ra biển nghỉ phép)","example":{"zh":"经理下周休假，要去海边玩几天。","py":"Jīnglǐ xià zhōu xiūjià, yào qù hǎibiān wán jǐ tiān.","vi":"Tuần sau giám đốc nghỉ phép, định ra biển chơi mấy ngày."}},{"stt":19,"hanzi":"怕","pinyin":"pà","hanviet":"Phạ","pos":"Động từ","meaning":"sợ","comps":"怕冷 (sợ lạnh), 怕干不完 (sợ làm không xong)","example":{"zh":"我很怕冷，冬天不太喜欢出门。","py":"Wǒ hěn pà lěng, dōngtiān bú tài xǐhuan chūmén.","vi":"Mình rất sợ lạnh, mùa đông không thích ra ngoài lắm."}},{"stt":20,"hanzi":"邮箱","pinyin":"yóuxiāng","hanviet":"Bưu tương","pos":"Danh từ","meaning":"hộp thư (email)","comps":"电子邮箱 (hộp thư điện tử), 公司的邮箱 (hộp thư công ty)","example":{"zh":"请把你的邮箱告诉我，我把照片发给你。","py":"Qǐng bǎ nǐ de yóuxiāng gàosu wǒ, wǒ bǎ zhàopiàn fā gěi nǐ.","vi":"Cho mình địa chỉ email của bạn, mình gửi ảnh cho."}},{"stt":21,"hanzi":"愿意","pinyin":"yuànyì","hanviet":"Nguyện ý","pos":"Trợ động từ","meaning":"bằng lòng, muốn","comps":"愿意帮忙 (sẵn lòng giúp), 不愿意去 (không muốn đi)","example":{"zh":"你愿意跟我一起去参加比赛吗？","py":"Nǐ yuànyì gēn wǒ yìqǐ qù cānjiā bǐsài ma?","vi":"Bạn có muốn cùng mình đi dự thi không?"}},{"stt":22,"hanzi":"城市","pinyin":"chéngshì","hanviet":"Thành thị","pos":"Danh từ","meaning":"thành phố","comps":"大城市 (thành phố lớn), 这个城市 (thành phố này)","example":{"zh":"我很喜欢这个城市，这里的人都很热情。","py":"Wǒ hěn xǐhuan zhège chéngshì, zhèlǐ de rén dōu hěn rèqíng.","vi":"Mình rất thích thành phố này, người ở đây đều nhiệt tình."}},{"stt":23,"hanzi":"离开","pinyin":"líkāi","hanviet":"Ly khai","pos":"Động từ","meaning":"rời khỏi, rời xa","comps":"离开家 (rời nhà), 离开北京 (rời Bắc Kinh)","example":{"zh":"我十八岁就离开家，去别的城市上大学了。","py":"Wǒ shíbā suì jiù líkāi jiā, qù biéde chéngshì shàng dàxué le.","vi":"Mười tám tuổi mình đã rời nhà sang thành phố khác học đại học."}},{"stt":24,"hanzi":"机会","pinyin":"jīhuì","hanviet":"Cơ hội","pos":"Danh từ","meaning":"cơ hội","comps":"有机会 (có cơ hội), 好机会 (cơ hội tốt)","example":{"zh":"有机会的话，我想去中国学习。","py":"Yǒu jīhuì dehuà, wǒ xiǎng qù Zhōngguó xuéxí.","vi":"Nếu có cơ hội, mình muốn sang Trung Quốc học."}},{"stt":25,"hanzi":"生活","pinyin":"shēnghuó","hanviet":"Sinh hoạt","pos":"Danh từ / Động từ","meaning":"cuộc sống; sống","comps":"大学生活 (cuộc sống đại học), 在北京生活 (sống ở Bắc Kinh)","example":{"zh":"我在这个城市生活了五年，已经习惯了。","py":"Wǒ zài zhège chéngshì shēnghuóle wǔ nián, yǐjīng xíguàn le.","vi":"Mình sống ở thành phố này năm năm, đã quen rồi."}},{"stt":26,"hanzi":"为","pinyin":"wèi","hanviet":"Vị","pos":"Giới từ","meaning":"vì, cho","comps":"为工作 (vì công việc), 为你高兴 (mừng cho bạn)","example":{"zh":"听说你找到工作了，我真为你高兴！","py":"Tīngshuō nǐ zhǎodào gōngzuò le, wǒ zhēn wèi nǐ gāoxìng!","vi":"Nghe nói bạn tìm được việc rồi, mình mừng cho bạn quá!"}},{"stt":27,"hanzi":"或","pinyin":"huò","hanviet":"Hoặc","pos":"Liên từ","meaning":"hoặc","comps":"今天或明天 (hôm nay hoặc mai), 工作或学习 (công việc hoặc học tập)","example":{"zh":"有问题可以给我打电话或发邮件。","py":"Yǒu wèntí kěyǐ gěi wǒ dǎ diànhuà huò fā yóujiàn.","vi":"Có vấn đề cứ gọi điện hoặc gửi email cho mình."}},{"stt":28,"hanzi":"老张","pinyin":"Lǎo Zhāng","hanviet":"Lão Trương","pos":"Danh từ riêng","meaning":"anh Trương (gọi thân)","comps":"老张 · 老王 (gọi thân người lớn hơn), 小李 (gọi thân người trẻ)","example":{"zh":"老张是我们公司的老同事了。","py":"Lǎo Zhāng shì wǒmen gōngsī de lǎo tóngshì le.","vi":"Anh Trương là đồng nghiệp lâu năm ở công ty chúng tôi."}}],"hanzi":[{"char":"会议","pinyin":"huìyì","hanviet":"Hội nghị","chars":["会","议"],"story":"会 = tụ họp (音乐会 bài 5). 议 = 讠 (lời nói) + 义 → bàn bạc. 会议 = tụ lại bàn bạc → cuộc họp. Phòng họp = 会议室."},{"char":"经理","pinyin":"jīnglǐ","hanviet":"Kinh lý","chars":["经","理"],"story":"经 = 纟 (sợi tơ) → sợi dọc, điều hành. 理 = 王 (ngọc) + 里 → mài giũa, sắp xếp. 经理 = người điều hành, sắp xếp công việc → giám đốc, quản lý. Gọi kèm họ: 刘经理."},{"char":"开会","pinyin":"kāihuì","hanviet":"Khai hội","chars":["开","会"],"story":"开 = mở (开机 bài 7). 会 = cuộc họp. 开会 = mở cuộc họp → họp. Động từ li hợp: 开完会, 开了一个会 — không nói ✗ 开会了两个小时."},{"char":"后天","pinyin":"hòutiān","hanviet":"Hậu thiên","chars":["后","天"],"story":"前天 (hôm kia) · 昨天 · 今天 · 明天 · 后天 (ngày kia). 后 = sau → 后天 = ngày sau ngày mai. Cùng kiểu với 后年 (bài 10)."},{"char":"地点","pinyin":"dìdiǎn","hanviet":"Địa điểm","chars":["地","点"],"story":"地 = 土 (đất) + 也 → nơi chốn. 点 = điểm. 地点 = điểm trên mặt đất → địa điểm. Hay đi cặp với 时间: 时间和地点."},{"char":"室","pinyin":"shì","hanviet":"Thất","chars":["室"],"story":"室 = 宀 (mái nhà) + 至 (đến) → nơi đi đến dưới mái nhà → căn phòng. Thường đứng sau làm hậu tố: 教室, 办公室 (bài 10), 会议室."},{"char":"发","pinyin":"fā","hanviet":"Phát","chars":["发"],"story":"发 = phát ra, gửi đi: 发邮件, 发照片. Đã gặp 发现 (bài 1 – phát hiện), 发烧 (bài 8 – phát sốt): cùng nghĩa gốc \"phát ra\"."},{"char":"笔记本（电脑）","pinyin":"bǐjìběn (diànnǎo)","hanviet":"Bút ký bản (điện não)","chars":["笔","记","本","电","脑"],"story":"笔记本 = sổ ghi chép (笔记 bài 10 + 本 cuốn). Máy tính mỏng, gập lại như cuốn sổ → 笔记本电脑, nói tắt 笔记本. 电脑 = 电 (điện) + 脑 (não) → \"não điện\"."},{"char":"或者","pinyin":"huòzhě","hanviet":"Hoặc giả","chars":["或","者"],"story":"或 = hoặc; 者 là hậu tố. 或者 dùng trong câu kể: 今天或者明天都可以. Câu hỏi lựa chọn phải dùng 还是. Văn viết rút gọn thành 或 (học ở buổi 下)."},{"char":"声音","pinyin":"shēngyīn","hanviet":"Thanh âm","chars":["声","音"],"story":"声 = tiếng (叫它一声 bài 7). 音 = âm (音乐 bài 5). 声音 = âm thanh, giọng nói: 声音很大, 听不见声音."},{"char":"看来","pinyin":"kànlái","hanviet":"Khán lai","chars":["看","来"],"story":"看 = nhìn. 看来 = nhìn rồi suy ra → xem ra, có vẻ: 看来他今天不会来了. Khác 看起来 / 看上去 (bài 1) = trông có vẻ, nhận xét vẻ bề ngoài."},{"char":"办法","pinyin":"bànfǎ","hanviet":"Biện pháp","chars":["办","法"],"story":"办 = làm, lo việc (办公室 bài 10). 法 = 氵 + 去 → phép, cách (方法 bài 8). 办法 = cách làm → biện pháp: 有办法, 没办法, 想办法."},{"char":"解决","pinyin":"jiějué","hanviet":"Giải quyết","chars":["解","决"],"story":"解 = 角 (sừng) + 刀 (dao) + 牛 (bò) → dùng dao tách sừng bò → tháo gỡ. 决 = quyết (决定 bài 7). 解决 = gỡ ra rồi quyết → giải quyết: 解决问题."},{"char":"只能","pinyin":"zhǐ néng","hanviet":"Chỉ năng","chars":["只","能"],"story":"只 zhǐ = chỉ (bài 2). 能 = có thể. 只能 = chỉ có thể, ngoài ra không còn cách → đành phải: 只能走下去, 只能找别人帮忙."},{"char":"别人","pinyin":"biérén","hanviet":"Biệt nhân","chars":["别","人"],"story":"别 = khác (别的 bài 4). 人 = người. 别人 = người khác: 帮助别人, 别人的东西. Phân biệt 别 = đừng: 别着急."},{"char":"请假","pinyin":"qǐngjià","hanviet":"Thỉnh giả","chars":["请","假"],"story":"请 = xin, mời. 假 đọc jià = kỳ nghỉ (放假, 假期 bài 4). 请假 = xin nghỉ. Động từ li hợp: 请两天假, 请了假 — không nói ✗ 请假两天."},{"char":"同事","pinyin":"tóngshì","hanviet":"Đồng sự","chars":["同","事"],"story":"同 = cùng (同学). 事 = việc. 同事 = người cùng làm việc → đồng nghiệp. So sánh: 同学 = bạn cùng học."},{"char":"休假","pinyin":"xiūjià","hanviet":"Hưu giả","chars":["休","假"],"story":"休 = 亻 (người) + 木 (cây) → người tựa gốc cây nghỉ (休息). 假 = kỳ nghỉ. 休假 = nghỉ phép theo chế độ; 请假 = xin nghỉ vì có việc riêng."},{"char":"怕","pinyin":"pà","hanviet":"Phạ","chars":["怕"],"story":"怕 = 忄 (tim) + 白 (trắng) → tim trắng bệch → sợ. 怕 + danh từ / động từ: 怕冷, 怕狗, 怕干不完."},{"char":"邮箱","pinyin":"yóuxiāng","hanviet":"Bưu tương","chars":["邮","箱"],"story":"邮 = bưu (邮件 bài 5). 箱 = ⺮ + 相 → cái hòm, hộp (箱子 bài 1, 冰箱 bài 3). 邮箱 = hòm thư → ngày nay chủ yếu là hộp thư email."},{"char":"愿意","pinyin":"yuànyì","hanviet":"Nguyện ý","chars":["愿","意"],"story":"愿 = 原 + 心 → điều lòng mong. 意 = 音 + 心 → ý trong lòng. 愿意 = trong lòng muốn → bằng lòng, sẵn lòng. Hỏi: 愿意不愿意 / 愿不愿意."},{"char":"城市","pinyin":"chéngshì","hanviet":"Thành thị","chars":["城","市"],"story":"城 = 土 (đất) + 成 → tường thành. 市 = chợ. Có tường thành, có chợ → thành phố: 大城市, 这个城市."},{"char":"离开","pinyin":"líkāi","hanviet":"Ly khai","chars":["离","开"],"story":"离 = cách xa (离学校很远). 开 = mở, tách ra. 离开 = tách xa ra → rời khỏi: 离开家, 离开北京. Không cần giới từ: ✗ 离开从北京."},{"char":"机会","pinyin":"jīhuì","hanviet":"Cơ hội","chars":["机","会"],"story":"机 = 木 + 几 → cái then máy, thời cơ. 会 = gặp. 机会 = thời cơ gặp được → cơ hội: 有机会, 好机会, 没有机会."},{"char":"生活","pinyin":"shēnghuó","hanviet":"Sinh hoạt","chars":["生","活"],"story":"生 = sống. 活 = 氵 (nước) + 舌 → sống động. 生活 = cuộc sống (danh từ: 大学生活), sống (động từ: 在北京生活)."},{"char":"为","pinyin":"wèi","hanviet":"Vị","chars":["为"],"story":"为 đọc wèi = vì, cho: 为工作离开家人, 为你高兴. Đã gặp trong 为了 (bài 9), 因为. Cấu trúc: 为 + người / việc + động từ."},{"char":"或","pinyin":"huò","hanviet":"Hoặc","chars":["或"],"story":"或 = 或者 viết gọn, hay gặp trong văn viết: 工作或学习, 打电话或发邮件. Câu hỏi lựa chọn vẫn dùng 还是."},{"char":"老张","pinyin":"Lǎo Zhāng","hanviet":"Lão Trương","chars":["老","张"],"story":"老 + họ = cách gọi thân người lớn hơn hoặc đồng nghiệp lâu năm: 老张, 老王. 小 + họ cho người trẻ hơn: 小李 (bài 4). 张 ở đây là họ Trương (张 lượng từ bài 2)."}],"grammar":[{"title":"问句：A 还是 B？　陈述句：A 或者 B","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>A</b><small>lựa chọn 1</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>还是</b><small>câu hỏi</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>或者</b><small>câu kể</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>B</b><small>lựa chọn 2</small></span></div>","summary":"<p class=\"gr-lead\">Hay (là) … ? · … hoặc …</p><ul><li><span class=\"zh\">还是</span> dùng trong <b>câu hỏi</b>, đưa ra 2+ lựa chọn để người nghe chọn: <span class=\"zh\">我们今天去、明天去还是后天去？</span></li><li><span class=\"zh\">或者</span> dùng trong <b>câu trần thuật</b>, không dùng để hỏi: <span class=\"zh\">你可以坐地铁或者打车去学校</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">还是 · 或者</span> · Câu hỏi và câu kể</h4><p>Hay … ? · Hoặc …</p><div class=\"gr-formula\"><div class=\"fx-lbl\">还是 · câu hỏi</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>今天去</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>还是</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>明天去</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>？</b></span></div><div class=\"fx-ex zh\">我们今天去还是明天去？</div><div class=\"fx-lbl\">或者 · câu kể</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>坐地铁</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>或者</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>打车</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>都可以</b></span></div><div class=\"fx-ex zh\">坐地铁或者打车都可以。</div><div class=\"fx-lbl\">或者 · gợi ý</div><div class=\"fx-row\"><span class=\"fx-p\"><b>你可以</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>喝茶</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>或者</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>喝咖啡</b></span></div><div class=\"fx-ex zh\">你可以喝茶或者喝咖啡。</div></div><p class=\"gr-key\">Câu hỏi có <span class=\"zh\">还是</span> <b>không thêm 吗</b> ở cuối　·　<span class=\"zh\">或者</span> hay đi với <span class=\"zh\">都可以 / 都行</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">你喝茶还是喝咖啡？——茶或者咖啡都可以。</span> = Bạn uống trà hay cà phê? — Trà hoặc cà phê đều được.</p>","note":"<b>Lưu ý:</b> Tiếng Việt đều nói \"hay\": ✗ <span class=\"zh\">你去或者不去？</span> → ✓ <span class=\"zh\">你去还是不去？</span>","examples":[{"zh":"我们用会议室的电脑还是自己的笔记本电脑？","py":"Wǒmen yòng huìyìshì de diànnǎo háishi zìjǐ de bǐjìběn diànnǎo?","vi":"Chúng ta dùng máy tính phòng họp hay laptop của mình?"},{"zh":"我们今天去、明天去还是后天去？","py":"Wǒmen jīntiān qù、míngtiān qù háishi hòutiān qù?","vi":"Chúng ta đi hôm nay, ngày mai hay ngày kia?"},{"zh":"会议室的电脑或者自己的电脑都可以。","py":"Huìyìshì de diànnǎo huòzhě zìjǐ de diànnǎo dōu kěyǐ.","vi":"Máy tính phòng họp hoặc máy của mình đều được."},{"zh":"你可以坐地铁或者打车去学校。","py":"Nǐ kěyǐ zuò dìtiě huòzhě dǎchē qù xuéxiào.","vi":"Bạn có thể đi tàu điện ngầm hoặc taxi đến trường."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">____？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">是明天，下午两点在第一会议室。</span></span></span><span class=\"qz-hint\">Cuộc họp là hôm nay hay ngày mai? — Là ngày mai, 2 giờ chiều ở phòng họp số 1.</span>","answer":["会议是今天还是明天","是今天还是明天开会","今天还是明天开会"],"explain":"会议是今天还是明天？ (Huìyì shì jīntiān háishi míngtiān?)"}]},{"title":"（情况），看来 + 结论","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>情况</b><small>điều quan sát được</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>看来</b><small>xem ra</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>结论</b><small>kết luận / suy đoán</small></span></div>","summary":"<p class=\"gr-lead\">Xem ra …, có vẻ như …</p><ul><li>Trước <span class=\"zh\">看来</span> là <b>điều nhìn thấy</b>, sau là <b>kết luận</b>: <span class=\"zh\">电梯坏了，看来咱们只能走下去了</span>.</li><li><span class=\"zh\">看来</span> đứng <b>đầu vế câu</b>, hay đi với <span class=\"zh\">会 · 要 · 只能 · 不会……了</span> để suy đoán.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">看来 · 看起来</span> · Phân biệt với bài 1</h4><p>Suy ra · trông có vẻ</p><div class=\"gr-formula\"><div class=\"fx-lbl\">看来 · suy ra</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>他没接电话</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>看来</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>在开会</b></span></div><div class=\"fx-ex zh\">他没接电话，看来在开会。</div><div class=\"fx-lbl\">看起来 · vẻ ngoài</div><div class=\"fx-row\"><span class=\"fx-p\"><b>他</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>看起来</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>很累</b></span></div><div class=\"fx-ex zh\">他看起来很累。</div><div class=\"fx-lbl\">Dùng cả hai</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>他看起来很累</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>看来</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>没睡好</b></span></div><div class=\"fx-ex zh\">他看起来很累，看来没睡好。</div></div><p class=\"gr-key\"><span class=\"zh\">看起来 / 看上去</span> + tính từ (miêu tả)　·　<span class=\"zh\">看来</span> + cả một câu kết luận</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">这么晚了，看来他今天不会来了。</span> = Muộn thế này rồi, xem ra hôm nay anh ấy không đến đâu.</p>","note":"<b>Lưu ý:</b> Tả vẻ ngoài dùng 看起来: ✗ <span class=\"zh\">他看来很年轻</span> → ✓ <span class=\"zh\">他看起来很年轻</span>","examples":[{"zh":"看来我没办法解决这个问题。","py":"Kànlái wǒ méi bànfǎ jiějué zhège wèntí.","vi":"Xem ra tôi không giải quyết được vấn đề này."},{"zh":"这么晚了，看来他今天不会来了。","py":"Zhème wǎn le, kànlái tā jīntiān bú huì lái le.","vi":"Muộn thế này rồi, xem ra hôm nay anh ấy không đến."},{"zh":"电梯坏了，看来咱们只能走下去了。","py":"Diàntī huài le, kànlái zánmen zhǐ néng zǒu xiàqu le.","vi":"Thang máy hỏng rồi, xem ra mình đành đi bộ xuống thôi."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">现在外面天阴得很，____。</span><span class=\"qz-hint\">Bên ngoài trời âm u lắm, xem ra sắp mưa rồi.</span>","answer":["看来要下雨了","看来要下雨","看来快要下雨了","看来快下雨了"],"explain":"现在外面天阴得很，看来要下雨了。 (Xiànzài wàimian tiān yīn de hěn, kànlái yào xià yǔ le.)"}]},{"title":"主语 + 把 + 宾语 + 动词 + 结果补语","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b><small>(đem)</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>宾语</b><small>vật xác định</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>结果补语</b><small>bổ ngữ kết quả</small></span></div>","summary":"<p class=\"gr-lead\">Làm … cho xong / sạch / tốt</p><ul><li>Sau động từ phải có <b>bổ ngữ kết quả</b> (<span class=\"zh\">完 · 好 · 干净 · 清楚 · 错</span>): <span class=\"zh\">我跟您一起把这些工作做完</span>.</li><li>Phủ định: <span class=\"zh\">没 / 还没</span> đứng <b>trước 把</b>, bỏ <span class=\"zh\">了</span>: <span class=\"zh\">他还没把笔记本电脑接好</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">把 + 宾语 + 动词 + 结果补语</span> · Bổ ngữ kết quả hay gặp</h4><p>完 · 干净 · 好 · 清楚</p><div class=\"gr-formula\"><div class=\"fx-lbl\">V + 完 · xong</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>工作</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>做</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>完</b></span></div><div class=\"fx-ex zh\">我把这些工作做完了。</div><div class=\"fx-lbl\">V + 干净 · sạch</div><div class=\"fx-row\"><span class=\"fx-p\"><b>妈妈</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>衣服</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>洗</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>干净</b></span></div><div class=\"fx-ex zh\">妈妈把衣服洗干净了。</div><div class=\"fx-lbl\">没 · V + 好</div><div class=\"fx-row\"><span class=\"fx-p\"><b>他还没</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>电脑</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>接</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>好</b></span></div><div class=\"fx-ex zh\">他还没把电脑接好。</div><div class=\"fx-lbl\">V + 清楚 · rõ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>请</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>问题</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>说</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>清楚</b></span></div><div class=\"fx-ex zh\">请把问题说清楚。</div></div><p class=\"gr-key\">Ôn: 把(1) <span class=\"zh\">V + 在 / 到</span> đổi chỗ　·　把(2) <span class=\"zh\">V + 给</span> chuyển giao　·　把(3) <span class=\"zh\">V + kết quả</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">妈妈把衣服洗干净了。</span> = Mẹ giặt sạch quần áo rồi.</p>","note":"<b>Lưu ý:</b> Không để động từ trơn: ✗ <span class=\"zh\">我把这些工作做</span> → ✓ <span class=\"zh\">我把这些工作做完</span>","examples":[{"zh":"我跟您一起把这些工作做完。","py":"Wǒ gēn nín yìqǐ bǎ zhèxiē gōngzuò zuòwán.","vi":"Em cùng chị làm xong chỗ việc này."},{"zh":"妈妈把衣服洗干净了。","py":"Māma bǎ yīfu xǐ gānjìng le.","vi":"Mẹ giặt sạch quần áo rồi."},{"zh":"他还没把笔记本电脑接好。","py":"Tā hái méi bǎ bǐjìběn diànnǎo jiēhǎo.","vi":"Anh ấy vẫn chưa kết nối xong laptop."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">妈妈，我饿了，现在可以吃晚饭吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">再等一会儿，我还____。</span></span></span><span class=\"qz-hint\">Mẹ ơi, con đói rồi, giờ ăn tối được chưa? — Đợi chút nữa, mẹ còn chưa nấu xong thức ăn.</span>","answer":["没把菜做好呢","没把饭做好呢","没把菜做好"],"explain":"再等一会儿，我还没把菜做好呢。 (Zài děng yíhuìr, wǒ hái méi bǎ cài zuòhǎo ne.)"}]},{"title":"对 + 人 / 对象 + 来说，……","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>对</b><small>đối với</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>人 / 对象</b><small>người / đối tượng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>来说</b><small>mà nói</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>观点 / 感受</b><small>quan điểm / cảm nhận</small></span></div>","summary":"<p class=\"gr-lead\">Đối với … mà nói</p><ul><li><span class=\"zh\">对……来说</span> thường đứng <b>đầu câu</b>, sau là nhận xét / cảm nhận của người đó: <span class=\"zh\">对她来说，学习汉语很有意思</span>.</li><li>Giữa <span class=\"zh\">对</span> và <span class=\"zh\">来说</span> là <b>người / nhóm người</b>: <span class=\"zh\">对我来说 · 对年轻人来说</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">对 + 人 + 来说</span> · Cảm nhận của ai?</h4><p>Tôi · một người · một nhóm</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Người nói</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>对</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>来说</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>生活也很重要</b></span></div><div class=\"fx-ex zh\">对我来说，生活也很重要。</div><div class=\"fx-lbl\">Người khác</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>对</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>她</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>来说</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>汉语很有意思</b></span></div><div class=\"fx-ex zh\">对她来说，汉语很有意思。</div><div class=\"fx-lbl\">Một nhóm người</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>对</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>孩子</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>来说</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>玩也是学习</b></span></div><div class=\"fx-ex zh\">对孩子来说，玩也是学习。</div></div><p class=\"gr-key\">Khác <span class=\"zh\">对</span> = với (thái độ): <span class=\"zh\">老师对我们很好</span> — không có <span class=\"zh\">来说</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">对孩子来说，玩也是一种学习。</span> = Đối với trẻ con, chơi cũng là một cách học.</p>","note":"<b>Lưu ý:</b> Không dùng 给 thay 对: ✗ <span class=\"zh\">给我来说，生活很重要</span> → ✓ <span class=\"zh\">对我来说，生活很重要</span>","examples":[{"zh":"对我来说，生活也很重要，我不愿意为工作或学习离开家人。","py":"Duì wǒ lái shuō, shēnghuó yě hěn zhòngyào, wǒ bú yuànyì wèi gōngzuò huò xuéxí líkāi jiārén.","vi":"Đối với tôi, cuộc sống cũng quan trọng, tôi không muốn vì công việc hay học tập mà xa gia đình."},{"zh":"对她来说，学习汉语很有意思。","py":"Duì tā lái shuō, xuéxí Hànyǔ hěn yǒu yìsi.","vi":"Đối với cô ấy, học tiếng Hán rất thú vị."},{"zh":"对孩子来说，玩也是一种学习。","py":"Duì háizi lái shuō, wán yě shì yì zhǒng xuéxí.","vi":"Đối với trẻ con, chơi cũng là một cách học."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在办公室里","titleVi":"Văn phòng — hỏi lịch họp","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"会议下午几点开始？","py":"Huìyì xiàwǔ jǐ diǎn kāishǐ?","vi":"Cuộc họp chiều mấy giờ bắt đầu?"},{"speaker":"乐","name":"Đồng Lạc","zh":"今天下午经理不在，不开会了。","py":"Jīntiān xiàwǔ jīnglǐ bú zài, bù kāihuì le.","vi":"Chiều nay giám đốc vắng, không họp nữa ạ."},{"speaker":"雪","name":"Nhất Tuyết","zh":"那什么时候开会？","py":"Nà shénme shíhou kāihuì?","vi":"Vậy khi nào họp?"},{"speaker":"乐","name":"Đồng Lạc","zh":"后天上午十点，会议地点换到第一会议室。我正要给大家发邮件。","py":"Hòutiān shàngwǔ shí diǎn, huìyì dìdiǎn huàndào dì-yī huìyìshì. Wǒ zhèng yào gěi dàjiā fā yóujiàn.","vi":"10 giờ sáng ngày kia, địa điểm đổi sang phòng họp số 1. Em đang định gửi email cho mọi người."},{"speaker":"雪","name":"Nhất Tuyết","zh":"开会的时候，我们用会议室的电脑还是自己的笔记本电脑？","py":"Kāihuì de shíhou, wǒmen yòng huìyìshì de diànnǎo háishi zìjǐ de bǐjìběn diànnǎo?","vi":"Lúc họp mình dùng máy tính phòng họp hay laptop của mình?"},{"speaker":"乐","name":"Đồng Lạc","zh":"会议室的电脑或者自己的电脑都可以。","py":"Huìyìshì de diànnǎo huòzhě zìjǐ de diànnǎo dōu kěyǐ.","vi":"Máy tính phòng họp hoặc máy của mình đều được ạ."},{"speaker":"雪","name":"Nhất Tuyết","zh":"那到时候咱们早点儿过去，你帮我把电脑接好吧。","py":"Nà dào shíhou zánmen zǎo diǎnr guòqu, nǐ bāng wǒ bǎ diànnǎo jiēhǎo ba.","vi":"Vậy đến lúc đó mình qua sớm chút, em giúp chị kết nối máy tính nhé."}]},{"titleZh":"课文二 · 在会议室","titleVi":"Phòng họp — chuẩn bị trước giờ họp","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"电脑接好了吗？","py":"Diànnǎo jiēhǎo le ma?","vi":"Máy tính kết nối xong chưa em?"},{"speaker":"乐","name":"Đồng Lạc","zh":"已经接好了，您开机看看有没有问题。","py":"Yǐjīng jiēhǎo le, nín kāijī kànkan yǒu méiyǒu wèntí.","vi":"Xong rồi ạ, chị bật máy xem có vấn đề gì không."},{"speaker":"雪","name":"Nhất Tuyết","zh":"现在什么都看不见。","py":"Xiànzài shénme dōu kàn bu jiàn.","vi":"Giờ chẳng thấy gì cả."},{"speaker":"乐","name":"Đồng Lạc","zh":"我检查一下哪里出问题了……您再试一下。","py":"Wǒ jiǎnchá yíxià nǎli chū wèntí le…… Nín zài shì yíxià.","vi":"Để em kiểm tra xem lỗi ở đâu… Chị thử lại xem."},{"speaker":"雪","name":"Nhất Tuyết","zh":"看见了，但是听不见声音。","py":"Kànjiàn le, dànshì tīng bu jiàn shēngyīn.","vi":"Thấy rồi, nhưng không nghe thấy tiếng."},{"speaker":"乐","name":"Đồng Lạc","zh":"现在呢？","py":"Xiànzài ne?","vi":"Giờ thì sao ạ?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"听得见声音，但是声音有点儿小，听不清楚。","py":"Tīng de jiàn shēngyīn, dànshì shēngyīn yǒudiǎnr xiǎo, tīng bu qīngchu.","vi":"Nghe thấy tiếng rồi, nhưng tiếng hơi nhỏ, nghe không rõ."},{"speaker":"乐","name":"Đồng Lạc","zh":"看来我没办法解决这个问题，只能找别人来帮帮忙了。","py":"Kànlái wǒ méi bànfǎ jiějué zhège wèntí, zhǐ néng zhǎo biérén lái bāngbang máng le.","vi":"Xem ra em không giải quyết được, đành nhờ người khác đến giúp thôi."}]},{"titleZh":"课文三 · 在办公室里","titleVi":"Văn phòng — nhiều việc, ít người","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"同乐，你看见老张了吗？","py":"Tónglè, nǐ kànjiàn Lǎo Zhāng le ma?","vi":"Đồng Lạc, em có thấy anh Trương đâu không?"},{"speaker":"乐","name":"Đồng Lạc","zh":"老张没来。他说家里有点儿事，所以请假了。","py":"Lǎo Zhāng méi lái. Tā shuō jiāli yǒudiǎnr shì, suǒyǐ qǐngjià le.","vi":"Anh Trương không đến. Anh ấy nói nhà có chút việc nên xin nghỉ rồi ạ."},{"speaker":"雪","name":"Nhất Tuyết","zh":"好几个同事都休假了，开会前这么多工作我怕干不完。","py":"Hǎo jǐ ge tóngshì dōu xiūjià le, kāihuì qián zhème duō gōngzuò wǒ pà gàn bu wán.","vi":"Mấy đồng nghiệp đều nghỉ phép, trước cuộc họp nhiều việc thế này chị sợ làm không xong."},{"speaker":"乐","name":"Đồng Lạc","zh":"十二点多了，咱们先去吃饭吧。吃完饭，我跟您一起把这些工作做完。","py":"Shí'èr diǎn duō le, zánmen xiān qù chīfàn ba. Chīwán fàn, wǒ gēn nín yìqǐ bǎ zhèxiē gōngzuò zuòwán.","vi":"Hơn 12 giờ rồi, mình đi ăn trước đã. Ăn xong em cùng chị làm xong chỗ việc này."},{"speaker":"雪","name":"Nhất Tuyết","zh":"你先去吃，我想再干一会儿。明天开会前要发到公司的邮箱里。","py":"Nǐ xiān qù chī, wǒ xiǎng zài gàn yíhuìr. Míngtiān kāihuì qián yào fādào gōngsī de yóuxiāng li.","vi":"Em đi ăn trước đi, chị làm thêm lát nữa. Trước giờ họp mai phải gửi vào hộp thư công ty."},{"speaker":"乐","name":"Đồng Lạc","zh":"您没看到邮件吗？经理还没回来呢，下周才能开会。","py":"Nín méi kàndào yóujiàn ma? Jīnglǐ hái méi huílai ne, xià zhōu cái néng kāihuì.","vi":"Chị chưa xem email ạ? Giám đốc vẫn chưa về, tuần sau mới họp được."},{"speaker":"雪","name":"Nhất Tuyết","zh":"那不着急了。走，吃饭去。","py":"Nà bù zháojí le. Zǒu, chīfàn qù.","vi":"Vậy thì không vội nữa. Đi, ăn cơm thôi."}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — Nhất Tuyết viết nhật ký","para":true,"speaker":"雪","lines":[{"zh":"前几天，上海的同事来北京了。","py":"Qián jǐ tiān, Shànghǎi de tóngshì lái Běijīng le.","vi":"Mấy hôm trước, đồng nghiệp ở Thượng Hải đến Bắc Kinh."},{"zh":"一起吃饭时，他们跟我说最近有不少同事去上海工作了，问我愿意不愿意也去上海。","py":"Yìqǐ chīfàn shí, tāmen gēn wǒ shuō zuìjìn yǒu bù shǎo tóngshì qù Shànghǎi gōngzuò le, wèn wǒ yuànyì bu yuànyì yě qù Shànghǎi.","vi":"Lúc cùng ăn cơm, họ kể gần đây có khá nhiều đồng nghiệp đã sang Thượng Hải làm việc, hỏi tôi có muốn cũng sang Thượng Hải không."},{"zh":"我是这样想的：现在丈夫和孩子都在北京，刘明的工作很忙，小雪和小明也还小，我去别的城市工作就要离开他们。","py":"Wǒ shì zhèyàng xiǎng de: xiànzài zhàngfu hé háizi dōu zài Běijīng, Liú Míng de gōngzuò hěn máng, Xiǎoxuě hé Xiǎomíng yě hái xiǎo, wǒ qù biéde chéngshì gōngzuò jiù yào líkāi tāmen.","vi":"Tôi nghĩ thế này: hiện giờ chồng và các con đều ở Bắc Kinh, công việc của Lưu Minh rất bận, Tiểu Tuyết và Tiểu Minh còn nhỏ, tôi sang thành phố khác làm việc thì phải xa họ."},{"zh":"虽然去上海可能会有更好的机会，但是对我来说，生活也很重要，我不愿意为工作或学习离开家人。","py":"Suīrán qù Shànghǎi kěnéng huì yǒu gèng hǎo de jīhuì, dànshì duì wǒ lái shuō, shēnghuó yě hěn zhòngyào, wǒ bú yuànyì wèi gōngzuò huò xuéxí líkāi jiārén.","vi":"Tuy sang Thượng Hải có thể sẽ có cơ hội tốt hơn, nhưng đối với tôi, cuộc sống cũng rất quan trọng, tôi không muốn vì công việc hay học tập mà xa gia đình."}]}]},"extra":[],"activity":{"act":[{"zh":"猜猜是什么工作","py":"cāicai shì shénme gōngzuò","tag":"Trò chơi đoán nghề","mean":"Lượt 1 · Những nghề quen thuộc","q":{"zh":"描述一个职业，不能说出职业的名称，其他人猜猜是什么工作。","py":"Miáoshù yí ge zhíyè, bù néng shuōchū zhíyè de míngchēng, qítā rén cāicai shì shénme gōngzuò.","vi":"Tả một nghề, không được nói tên nghề, người khác đoán xem là nghề gì."},"banks":[{"lbl":"Các đáp án","items":[{"zh":"🩺 医生","py":"yīshēng","vi":"bác sĩ"},{"zh":"📚 老师","py":"lǎoshī","vi":"giáo viên"},{"zh":"🚕 司机","py":"sījī","vi":"tài xế"},{"zh":"🍽️ 服务员","py":"fúwùyuán","vi":"nhân viên phục vụ"},{"zh":"💼 经理","py":"jīnglǐ","vi":"giám đốc"},{"zh":"🏃 运动员","py":"yùndòngyuán","vi":"vận động viên"}]}],"items":[{"zh":"对很多人来说，如果身体不舒服就会去找他。","py":"Duì hěn duō rén lái shuō, rúguǒ shēntǐ bù shūfu jiù huì qù zhǎo tā.","vi":"Đối với nhiều người, nếu không khoẻ thì sẽ đi tìm người ấy."},{"lines":[{"who":"1","zh":"对很多人来说，如果身体不舒服就会去找他。","py":"Duì hěn duō rén lái shuō, rúguǒ shēntǐ bù shūfu jiù huì qù zhǎo tā.","vi":"Đối với nhiều người, nếu không khoẻ thì sẽ đi tìm anh ấy."},{"who":"2","zh":"他工作的时候常常穿着白色的衣服。","py":"Tā gōngzuò de shíhou chángcháng chuānzhe báisè de yīfu.","vi":"Lúc làm việc anh ấy thường mặc áo trắng."},{"who":"3","zh":"他在医院工作，每天都要见很多病人。","py":"Tā zài yīyuàn gōngzuò, měi tiān dōu yào jiàn hěn duō bìngrén.","vi":"Anh ấy làm ở bệnh viện, ngày nào cũng gặp rất nhiều bệnh nhân."},{"who":"✓","zh":"医生","py":"yīshēng","vi":"bác sĩ"}]},{"lines":[{"who":"1","zh":"他工作的地方有很多年轻人或者孩子。","py":"Tā gōngzuò de dìfang yǒu hěn duō niánqīngrén huòzhě háizi.","vi":"Nơi anh ấy làm việc có nhiều người trẻ hoặc trẻ em."},{"who":"2","zh":"他每天都要把很多字写在黑板上。","py":"Tā měi tiān dōu yào bǎ hěn duō zì xiě zài hēibǎn shang.","vi":"Ngày nào anh ấy cũng viết rất nhiều chữ lên bảng."},{"who":"3","zh":"学生遇到不明白的问题，都会去问他。","py":"Xuésheng yùdào bù míngbai de wèntí, dōu huì qù wèn tā.","vi":"Học sinh gặp chỗ không hiểu đều đến hỏi anh ấy."},{"who":"✓","zh":"老师","py":"lǎoshī","vi":"giáo viên"}]},{"lines":[{"who":"1","zh":"他的工作地点不在办公室，他每天都在路上。","py":"Tā de gōngzuò dìdiǎn bú zài bàngōngshì, tā měi tiān dōu zài lù shang.","vi":"Nơi làm việc của anh ấy không ở văn phòng, ngày nào cũng ở trên đường."},{"who":"2","zh":"他对这个城市的路非常清楚。","py":"Tā duì zhège chéngshì de lù fēicháng qīngchu.","vi":"Anh ấy rất rành đường sá thành phố này."},{"who":"3","zh":"他每天都把客人送到他们想去的地方。","py":"Tā měi tiān dōu bǎ kèrén sòngdào tāmen xiǎng qù de dìfang.","vi":"Ngày nào anh ấy cũng đưa khách đến nơi họ muốn."},{"who":"✓","zh":"司机","py":"sījī","vi":"tài xế"}]},{"lines":[{"who":"1","zh":"他工作的时候常常站着，很少坐下。","py":"Tā gōngzuò de shíhou chángcháng zhànzhe, hěn shǎo zuòxia.","vi":"Lúc làm việc anh ấy thường đứng, ít khi ngồi."},{"who":"2","zh":"客人来了，他会把菜单拿给客人。","py":"Kèrén lái le, tā huì bǎ càidān ná gěi kèrén.","vi":"Khách đến, anh ấy đưa thực đơn cho khách."},{"who":"3","zh":"客人吃完饭，他要把桌子打扫干净。","py":"Kèrén chīwán fàn, tā yào bǎ zhuōzi dǎsǎo gānjìng.","vi":"Khách ăn xong, anh ấy phải lau dọn bàn sạch sẽ."},{"who":"✓","zh":"服务员","py":"fúwùyuán","vi":"nhân viên phục vụ"}]},{"lines":[{"who":"1","zh":"他在公司工作，每天都很忙。","py":"Tā zài gōngsī gōngzuò, měi tiān dōu hěn máng.","vi":"Anh ấy làm ở công ty, ngày nào cũng rất bận."},{"who":"2","zh":"他常常在会议室跟同事们开会。","py":"Tā chángcháng zài huìyìshì gēn tóngshìmen kāihuì.","vi":"Anh ấy thường họp với đồng nghiệp ở phòng họp."},{"who":"3","zh":"同事遇到解决不了的问题，都会去他的办公室找他。","py":"Tóngshì yùdào jiějué bu liǎo de wèntí, dōu huì qù tā de bàngōngshì zhǎo tā.","vi":"Đồng nghiệp gặp vấn đề không giải quyết được đều đến văn phòng tìm anh ấy."},{"who":"✓","zh":"经理","py":"jīnglǐ","vi":"giám đốc"}]},{"lines":[{"who":"1","zh":"对他来说，锻炼身体就是工作。","py":"Duì tā lái shuō, duànliàn shēntǐ jiù shì gōngzuò.","vi":"Đối với anh ấy, rèn luyện thân thể chính là công việc."},{"who":"2","zh":"他每天都要练习好几个小时。","py":"Tā měi tiān dōu yào liànxí hǎo jǐ ge xiǎoshí.","vi":"Ngày nào anh ấy cũng phải luyện tập mấy tiếng liền."},{"who":"3","zh":"他常常参加比赛，希望能得到好成绩。","py":"Tā chángcháng cānjiā bǐsài, xīwàng néng dédào hǎo chéngjì.","vi":"Anh ấy thường dự thi đấu, mong đạt thành tích tốt."},{"who":"✓","zh":"运动员","py":"yùndòngyuán","vi":"vận động viên"}]}]},{"zh":"猜猜是什么工作","py":"cāicai shì shénme gōngzuò","tag":"Trò chơi đoán nghề","mean":"Lượt 2 · Thêm nhiều nghề khác","q":{"zh":"描述一个职业，不能说出职业的名称，其他人猜猜是什么工作。","py":"Miáoshù yí ge zhíyè, bù néng shuōchū zhíyè de míngchēng, qítā rén cāicai shì shénme gōngzuò.","vi":"Tả một nghề, không được nói tên nghề, người khác đoán xem là nghề gì."},"banks":[{"lbl":"Các đáp án","items":[{"zh":"👮 警察","py":"jǐngchá","vi":"cảnh sát"},{"zh":"🍳 厨师","py":"chúshī","vi":"đầu bếp"},{"zh":"💉 护士","py":"hùshi","vi":"y tá"},{"zh":"🗺️ 导游","py":"dǎoyóu","vi":"hướng dẫn viên"},{"zh":"🎬 演员","py":"yǎnyuán","vi":"diễn viên"},{"zh":"📦 快递员","py":"kuàidìyuán","vi":"người giao hàng"}]}],"items":[{"zh":"对很多人来说，如果身体不舒服就会去找他。","py":"Duì hěn duō rén lái shuō, rúguǒ shēntǐ bù shūfu jiù huì qù zhǎo tā.","vi":"Đối với nhiều người, nếu không khoẻ thì sẽ đi tìm người ấy."},{"lines":[{"who":"1","zh":"他工作的时候常常穿着蓝色或者黑色的衣服。","py":"Tā gōngzuò de shíhou chángcháng chuānzhe lánsè huòzhě hēisè de yīfu.","vi":"Lúc làm việc anh ấy thường mặc đồ xanh hoặc đen."},{"who":"2","zh":"别人遇到问题，常常会给他打电话。","py":"Biérén yùdào wèntí, chángcháng huì gěi tā dǎ diànhuà.","vi":"Người khác gặp chuyện thường gọi điện cho anh ấy."},{"who":"3","zh":"有人把东西丢了，可以去找他帮忙。","py":"Yǒu rén bǎ dōngxi diū le, kěyǐ qù zhǎo tā bāngmáng.","vi":"Ai làm mất đồ có thể tìm anh ấy giúp."},{"who":"✓","zh":"警察","py":"jǐngchá","vi":"cảnh sát"}]},{"lines":[{"who":"1","zh":"他在饭馆工作，但是客人很少看见他。","py":"Tā zài fànguǎn gōngzuò, dànshì kèrén hěn shǎo kànjiàn tā.","vi":"Anh ấy làm ở nhà hàng, nhưng khách ít khi thấy anh ấy."},{"who":"2","zh":"对他来说，做的菜好吃最重要。","py":"Duì tā lái shuō, zuò de cài hǎochī zuì zhòngyào.","vi":"Đối với anh ấy, món nấu ra ngon là quan trọng nhất."},{"who":"3","zh":"服务员把菜单给他，他就开始做菜。","py":"Fúwùyuán bǎ càidān gěi tā, tā jiù kāishǐ zuò cài.","vi":"Phục vụ đưa thực đơn cho anh ấy, anh ấy liền bắt đầu nấu."},{"who":"✓","zh":"厨师","py":"chúshī","vi":"đầu bếp"}]},{"lines":[{"who":"1","zh":"她在医院工作，可是她不是医生。","py":"Tā zài yīyuàn gōngzuò, kěshì tā bú shì yīshēng.","vi":"Cô ấy làm ở bệnh viện, nhưng không phải bác sĩ."},{"who":"2","zh":"她工作的时候也穿着白色的衣服。","py":"Tā gōngzuò de shíhou yě chuānzhe báisè de yīfu.","vi":"Lúc làm việc cô ấy cũng mặc áo trắng."},{"who":"3","zh":"病人住院的时候，她每天都要关心病人的身体。","py":"Bìngrén zhùyuàn de shíhou, tā měi tiān dōu yào guānxīn bìngrén de shēntǐ.","vi":"Khi bệnh nhân nằm viện, ngày nào cô ấy cũng chăm lo sức khoẻ họ."},{"who":"✓","zh":"护士","py":"hùshi","vi":"y tá"}]},{"lines":[{"who":"1","zh":"对他来说，旅游就是工作。","py":"Duì tā lái shuō, lǚyóu jiù shì gōngzuò.","vi":"Đối với anh ấy, du lịch chính là công việc."},{"who":"2","zh":"他常常带着客人去别的城市。","py":"Tā chángcháng dàizhe kèrén qù biéde chéngshì.","vi":"Anh ấy thường dẫn khách đến thành phố khác."},{"who":"3","zh":"他给客人介绍一个地方的历史，还帮客人拍照。","py":"Tā gěi kèrén jièshào yí ge dìfang de lìshǐ, hái bāng kèrén pāizhào.","vi":"Anh ấy giới thiệu lịch sử nơi đó cho khách, còn chụp ảnh giúp khách."},{"who":"✓","zh":"导游","py":"dǎoyóu","vi":"hướng dẫn viên"}]},{"lines":[{"who":"1","zh":"很多人都认识他，但是他不认识他们。","py":"Hěn duō rén dōu rènshi tā, dànshì tā bú rènshi tāmen.","vi":"Rất nhiều người biết anh ấy, nhưng anh ấy không biết họ."},{"who":"2","zh":"他常常在很多人前面说话、唱歌或者跳舞。","py":"Tā chángcháng zài hěn duō rén qiánmiàn shuōhuà、chànggē huòzhě tiàowǔ.","vi":"Anh ấy thường nói, hát hoặc nhảy trước rất nhiều người."},{"who":"3","zh":"我们常常在电视或者电影里看到他。","py":"Wǒmen chángcháng zài diànshì huòzhě diànyǐng li kàndào tā.","vi":"Chúng ta thường thấy anh ấy trên tivi hoặc trong phim."},{"who":"✓","zh":"演员","py":"yǎnyuán","vi":"diễn viên"}]},{"lines":[{"who":"1","zh":"他每天骑着车在城市里跑来跑去。","py":"Tā měi tiān qízhe chē zài chéngshì li pǎo lái pǎo qù.","vi":"Ngày nào anh ấy cũng đạp xe chạy khắp thành phố."},{"who":"2","zh":"很多人喜欢在网上买东西，所以他非常忙。","py":"Hěn duō rén xǐhuan zài wǎngshang mǎi dōngxi, suǒyǐ tā fēicháng máng.","vi":"Nhiều người thích mua đồ trên mạng nên anh ấy rất bận."},{"who":"3","zh":"他的工作是把东西送到别人家里。","py":"Tā de gōngzuò shì bǎ dōngxi sòngdào biérén jiāli.","vi":"Công việc của anh ấy là đưa đồ đến nhà người khác."},{"who":"✓","zh":"快递员","py":"kuàidìyuán","vi":"người giao hàng"}]}]}],"speak":[]}},{"id":"k3v3-b12","courseId":"k3v3","order":12,"title":"Mùa này thời tiết thay đổi rất nhanh","titleZh":"这个季节天气变化很快","titlePy":"zhège jìjié tiānqì biànhuà hěn kuài","vocab":[{"stt":1,"hanzi":"街","pinyin":"jiē","hanviet":"Nhai","pos":"Danh từ","meaning":"phố, đường phố","comps":"这条街 (con phố này), 上街 (ra phố), 街上 (trên phố)","example":{"zh":"这条街上有很多小饭馆，周末人很多。","py":"Zhè tiáo jiē shang yǒu hěn duō xiǎo fànguǎn, zhōumò rén hěn duō.","vi":"Phố này có nhiều quán ăn nhỏ, cuối tuần rất đông người."}},{"stt":2,"hanzi":"开花","pinyin":"kāihuā","hanviet":"Khai hoa","pos":"Động từ (li hợp)","meaning":"nở hoa","comps":"树开花了 (cây nở hoa rồi), 开了很多花 (nở rất nhiều hoa)","example":{"zh":"春天到了，小区里的树都开花了。","py":"Chūntiān dào le, xiǎoqū li de shù dōu kāihuā le.","vi":"Mùa xuân đến rồi, cây trong khu chung cư đều nở hoa."}},{"stt":3,"hanzi":"公园","pinyin":"gōngyuán","hanviet":"Công viên","pos":"Danh từ","meaning":"công viên","comps":"去公园 (đi công viên), 公园里 (trong công viên)","example":{"zh":"我家旁边有个公园，我每天早上去那儿跑步。","py":"Wǒ jiā pángbiān yǒu ge gōngyuán, wǒ měi tiān zǎoshang qù nàr pǎobù.","vi":"Cạnh nhà mình có công viên, sáng nào mình cũng ra đó chạy bộ."}},{"stt":4,"hanzi":"船","pinyin":"chuán","hanviet":"Thuyền","pos":"Danh từ","meaning":"thuyền, tàu thuỷ","comps":"坐船 (đi thuyền), 一条船 (một chiếc thuyền)","example":{"zh":"坐船去上海要很长时间，我们还是坐高铁吧。","py":"Zuò chuán qù Shànghǎi yào hěn cháng shíjiān, wǒmen háishi zuò gāotiě ba.","vi":"Đi tàu thuỷ đến Thượng Hải lâu lắm, mình đi tàu cao tốc thôi."}},{"stt":5,"hanzi":"工作日","pinyin":"gōngzuòrì","hanviet":"Công tác nhật","pos":"Danh từ","meaning":"ngày làm việc","comps":"工作日 (thứ Hai – thứ Sáu), 工作日的早上 (sáng ngày thường)","example":{"zh":"工作日的早上，地铁里的人特别多。","py":"Gōngzuòrì de zǎoshang, dìtiě li de rén tèbié duō.","vi":"Sáng ngày làm việc, tàu điện ngầm cực kỳ đông."}},{"stt":6,"hanzi":"地方","pinyin":"dìfang","hanviet":"Địa phương","pos":"Danh từ","meaning":"nơi, chỗ","comps":"什么地方 (chỗ nào), 很多地方 (nhiều nơi), 远的地方 (nơi xa)","example":{"zh":"这个地方环境挺好的，有山有水。","py":"Zhège dìfang huánjìng tǐng hǎo de, yǒu shān yǒu shuǐ.","vi":"Nơi này môi trường khá tốt, có núi có sông."}},{"stt":7,"hanzi":"刚才","pinyin":"gāngcái","hanviet":"Cương tài","pos":"Danh từ","meaning":"vừa nãy, vừa rồi","comps":"刚才的电话 (cuộc gọi vừa nãy), 刚才还… (vừa nãy còn…)","example":{"zh":"刚才有人给你打电话，你不在。","py":"Gāngcái yǒu rén gěi nǐ dǎ diànhuà, nǐ bú zài.","vi":"Vừa nãy có người gọi cho bạn, bạn không có ở đây."}},{"stt":8,"hanzi":"刮","pinyin":"guā","hanviet":"Quát","pos":"Động từ","meaning":"(gió) thổi","comps":"刮风 (nổi gió), 刮大风 (gió to)","example":{"zh":"外面刮着大风，你多穿点儿衣服。","py":"Wàimian guāzhe dà fēng, nǐ duō chuān diǎnr yīfu.","vi":"Ngoài trời đang gió to, bạn mặc thêm áo vào."}},{"stt":9,"hanzi":"风","pinyin":"fēng","hanviet":"Phong","pos":"Danh từ","meaning":"gió","comps":"风很大 (gió rất to), 刮风 (nổi gió)","example":{"zh":"今天风很大，别去爬山了。","py":"Jīntiān fēng hěn dà, bié qù páshān le.","vi":"Hôm nay gió to lắm, đừng đi leo núi nữa."}},{"stt":10,"hanzi":"新闻","pinyin":"xīnwén","hanviet":"Tân văn","pos":"Danh từ","meaning":"tin tức","comps":"看新闻 (xem tin tức), 体育新闻 (tin thể thao), 新闻里说 (tin tức nói)","example":{"zh":"我每天早上都在手机上看新闻。","py":"Wǒ měi tiān zǎoshang dōu zài shǒujī shang kàn xīnwén.","vi":"Sáng nào mình cũng xem tin tức trên điện thoại."}},{"stt":11,"hanzi":"伞","pinyin":"sǎn","hanviet":"Tản","pos":"Danh từ","meaning":"ô, dù","comps":"雨伞 (ô che mưa), 带伞 (mang ô), 一把伞 (một cái ô)","example":{"zh":"外面下雨了，你带伞了吗？","py":"Wàimian xià yǔ le, nǐ dài sǎn le ma?","vi":"Ngoài trời mưa rồi, bạn mang ô chưa?"}},{"stt":12,"hanzi":"借","pinyin":"jiè","hanviet":"Tá","pos":"Động từ","meaning":"cho mượn; mượn","comps":"借给 (cho … mượn), 跟…借 (mượn của …), 借书 (mượn sách)","example":{"zh":"我的书借给同学了，明天他才还给我。","py":"Wǒ de shū jiè gěi tóngxué le, míngtiān tā cái huán gěi wǒ.","vi":"Sách của mình cho bạn mượn rồi, mai bạn ấy mới trả."}},{"stt":13,"hanzi":"把","pinyin":"bǎ","hanviet":"Bả","pos":"Lượng từ","meaning":"cái, chiếc (vật có cán)","comps":"一把伞 (một cái ô), 两把椅子 (hai cái ghế)","example":{"zh":"我车里有一把伞，你先用吧。","py":"Wǒ chē li yǒu yì bǎ sǎn, nǐ xiān yòng ba.","vi":"Trong xe mình có một cái ô, bạn dùng trước đi."}},{"stt":14,"hanzi":"雨衣","pinyin":"yǔyī","hanviet":"Vũ y","pos":"Danh từ","meaning":"áo mưa","comps":"穿雨衣 (mặc áo mưa), 一件雨衣 (một chiếc áo mưa)","example":{"zh":"下雨的时候，骑自行车要穿雨衣。","py":"Xià yǔ de shíhou, qí zìxíngchē yào chuān yǔyī.","vi":"Lúc trời mưa, đi xe đạp phải mặc áo mưa."}},{"stt":15,"hanzi":"变","pinyin":"biàn","hanviet":"Biến","pos":"Động từ","meaning":"biến, thay đổi","comps":"变好 (tốt lên), 变冷 (lạnh đi), 变了 (thay đổi rồi)","example":{"zh":"几年没见，你变漂亮了！","py":"Jǐ nián méi jiàn, nǐ biàn piàoliang le!","vi":"Mấy năm không gặp, cậu xinh ra đấy!"}},{"stt":16,"hanzi":"季节","pinyin":"jìjié","hanviet":"Quý tiết","pos":"Danh từ","meaning":"mùa","comps":"这个季节 (mùa này), 喜欢的季节 (mùa yêu thích)","example":{"zh":"这个季节常常下雨，出门别忘了带伞。","py":"Zhège jìjié chángcháng xià yǔ, chūmén bié wàngle dài sǎn.","vi":"Mùa này hay mưa, ra ngoài đừng quên mang ô."}},{"stt":17,"hanzi":"变化","pinyin":"biànhuà","hanviet":"Biến hoá","pos":"Động từ / Danh từ","meaning":"thay đổi; sự thay đổi","comps":"变化很大 (thay đổi nhiều), 天气变化 (thời tiết thay đổi)","example":{"zh":"这几年我们城市的变化很大。","py":"Zhè jǐ nián wǒmen chéngshì de biànhuà hěn dà.","vi":"Mấy năm nay thành phố chúng tôi thay đổi rất nhiều."}},{"stt":18,"hanzi":"冬天","pinyin":"dōngtiān","hanviet":"Đông thiên","pos":"Danh từ","meaning":"mùa đông","comps":"冬天很冷 (mùa đông rất lạnh), 今年冬天 (mùa đông năm nay)","example":{"zh":"北京的冬天很冷，常常下雪。","py":"Běijīng de dōngtiān hěn lěng, chángcháng xià xuě.","vi":"Mùa đông Bắc Kinh rất lạnh, hay có tuyết."}},{"stt":19,"hanzi":"常常","pinyin":"chángcháng","hanviet":"Thường thường","pos":"Phó từ","meaning":"thường, thường xuyên","comps":"常常下雨 (hay mưa), 不常 (không hay…)","example":{"zh":"周末我常常去图书馆看书。","py":"Zhōumò wǒ chángcháng qù túshūguǎn kàn shū.","vi":"Cuối tuần mình thường đến thư viện đọc sách."}},{"stt":20,"hanzi":"关注","pinyin":"guānzhù","hanviet":"Quan chú","pos":"Động từ","meaning":"quan tâm, theo dõi","comps":"关注天气 (theo dõi thời tiết), 关注新闻 (theo dõi tin tức)","example":{"zh":"我爸爸每天都关注天气变化。","py":"Wǒ bàba měi tiān dōu guānzhù tiānqì biànhuà.","vi":"Bố mình ngày nào cũng theo dõi thời tiết thay đổi."}},{"stt":21,"hanzi":"四季","pinyin":"sìjì","hanviet":"Tứ quý","pos":"Danh từ","meaning":"bốn mùa","comps":"一年四季 (quanh năm), 北京的四季 (bốn mùa Bắc Kinh)","example":{"zh":"这里一年四季都不太冷，也不太热。","py":"Zhèli yì nián sìjì dōu bú tài lěng, yě bú tài rè.","vi":"Ở đây quanh năm không lạnh lắm, cũng không nóng lắm."}},{"stt":22,"hanzi":"春天","pinyin":"chūntiān","hanviet":"Xuân thiên","pos":"Danh từ","meaning":"mùa xuân","comps":"春天来了 (mùa xuân đến rồi), 春天的花 (hoa mùa xuân)","example":{"zh":"春天来了，公园里的花都开了。","py":"Chūntiān lái le, gōngyuán li de huā dōu kāi le.","vi":"Mùa xuân đến rồi, hoa trong công viên đều nở."}},{"stt":23,"hanzi":"夏天","pinyin":"xiàtiān","hanviet":"Hạ thiên","pos":"Danh từ","meaning":"mùa hè","comps":"夏天很热 (mùa hè rất nóng), 今年夏天 (mùa hè năm nay)","example":{"zh":"夏天太热了，我每天都去游泳。","py":"Xiàtiān tài rè le, wǒ měi tiān dōu qù yóuyǒng.","vi":"Mùa hè nóng quá, ngày nào mình cũng đi bơi."}},{"stt":24,"hanzi":"凉快","pinyin":"liángkuai","hanviet":"Lương khoái","pos":"Tính từ","meaning":"mát mẻ","comps":"很凉快 (rất mát), 凉快多了 (mát hơn nhiều)","example":{"zh":"下了雨以后，天气凉快多了。","py":"Xiàle yǔ yǐhòu, tiānqì liángkuai duō le.","vi":"Mưa xong, trời mát hơn nhiều rồi."}},{"stt":25,"hanzi":"秋天","pinyin":"qiūtiān","hanviet":"Thu thiên","pos":"Danh từ","meaning":"mùa thu","comps":"秋天的北京 (Bắc Kinh mùa thu), 到了秋天 (đến mùa thu)","example":{"zh":"秋天不冷不热，是去旅游最好的季节。","py":"Qiūtiān bù lěng bú rè, shì qù lǚyóu zuì hǎo de jìjié.","vi":"Mùa thu không nóng không lạnh, là mùa đi du lịch tuyệt nhất."}},{"stt":26,"hanzi":"叶子","pinyin":"yèzi","hanviet":"Diệp tử","pos":"Danh từ","meaning":"lá, lá cây","comps":"树叶子 (lá cây), 黄叶子 (lá vàng)","example":{"zh":"秋天到了，树上的叶子都黄了。","py":"Qiūtiān dào le, shù shang de yèzi dōu huáng le.","vi":"Mùa thu đến rồi, lá trên cây đều vàng cả."}},{"stt":27,"hanzi":"变成","pinyin":"biànchéng","hanviet":"Biến thành","pos":"Động từ","meaning":"trở thành, biến thành","comps":"变成红色 (chuyển sang màu đỏ), 雨变成了雪 (mưa chuyển thành tuyết)","example":{"zh":"天气越来越冷，雨变成了雪。","py":"Tiānqì yuè lái yuè lěng, yǔ biànchéngle xuě.","vi":"Trời ngày càng lạnh, mưa chuyển thành tuyết."}}],"hanzi":[{"char":"街","pinyin":"jiē","hanviet":"Nhai","chars":["街"],"story":"街 = 行 (ngã tư đường, tách ra hai bên) + 圭 (hai lớp 土 – đất). Đường đi có nhà cửa hai bên → phố. 街上 = trên phố; lượng từ 条: 一条街."},{"char":"开花","pinyin":"kāihuā","hanviet":"Khai hoa","chars":["开","花"],"story":"开 = mở. 花 = 艹 (cỏ) + 化 (biến hoá) → cây cỏ hoá thành hoa. 开花 = hoa mở ra → nở hoa. Từ li hợp: 开了很多花; nói gọn 花开了."},{"char":"公园","pinyin":"gōngyuán","hanviet":"Công viên","chars":["公","园"],"story":"公 = chung (公司, 公斤). 园 = 囗 (vòng rào) + 元 → khu vườn có rào. 公园 = khu vườn chung của mọi người → công viên. Cùng chữ 园 với 校园 (bài 9)."},{"char":"船","pinyin":"chuán","hanviet":"Thuyền","chars":["船"],"story":"船 = 舟 (hình chiếc thuyền gỗ) + 㕣. Bộ 舟 chỉ tàu thuyền. 坐船 = đi thuyền / tàu thuỷ, giống 坐车, 坐飞机."},{"char":"工作日","pinyin":"gōngzuòrì","hanviet":"Công tác nhật","chars":["工","作","日"],"story":"工作 (làm việc) + 日 (ngày) → ngày làm việc, thứ Hai – thứ Sáu. Ngược lại là 周末. Ngày làm việc ít người đi chơi: 工作日人不多."},{"char":"地方","pinyin":"dìfang","hanviet":"Địa phương","chars":["地","方"],"story":"地 = đất, 方 = phương hướng. 地方 đọc dìfang (thanh nhẹ) = nơi, chỗ: 什么地方, 很远的地方. Đọc dìfāng mới là \"địa phương\" (đối lập trung ương)."},{"char":"刚才","pinyin":"gāngcái","hanviet":"Cương tài","chars":["刚","才"],"story":"刚 = vừa; 才 = mới. 刚才 = vừa nãy, là danh từ thời gian: đứng trước hoặc sau chủ ngữ (刚才他来了 / 他刚才来了). Bài 18 sẽ phân biệt 刚才 với 刚刚."},{"char":"刮","pinyin":"guā","hanviet":"Quát","chars":["刮"],"story":"刮 = 舌 (lưỡi) + 刂 (dao) → cạo, gọt. Gió như lưỡi dao cạo qua mặt đất → (gió) thổi. Chỉ đi với gió: 刮风, 刮大风 — không nói ✗ 吹风了 khi tả thời tiết."},{"char":"风","pinyin":"fēng","hanviet":"Phong","chars":["风"],"story":"风 = 几 (khung buồm) + 㐅 → gió thổi căng buồm. 刮风 = nổi gió; 风很大 = gió to; 风停了 = gió ngừng."},{"char":"新闻","pinyin":"xīnwén","hanviet":"Tân văn","chars":["新","闻"],"story":"新 = mới. 闻 = 门 (cửa) + 耳 (tai) → ghé tai bên cửa mà nghe. 新闻 = điều mới nghe được → tin tức. 新闻里说… = tin tức nói…"},{"char":"伞","pinyin":"sǎn","hanviet":"Tản","chars":["伞"],"story":"伞 là chữ tượng hình chiếc ô: mái che 人 ở trên, các nan ô ở giữa, cán 十 ở dưới. 雨伞 = ô che mưa; lượng từ 把: 一把伞."},{"char":"借","pinyin":"jiè","hanviet":"Tá","chars":["借"],"story":"借 = 亻 (người) + 昔 → người đưa đồ cho nhau dùng tạm. 借给 + ai = cho ai mượn; 跟 + ai + 借 = mượn của ai. Trả lại dùng 还 huán (bài 3)."},{"char":"把","pinyin":"bǎ","hanviet":"Bả","chars":["把"],"story":"把 = 扌 (tay) + 巴 → chỗ tay nắm. Bài 10 học 把 là giới từ (把书还给我). Bài này 把 là lượng từ cho đồ có cán / tay cầm: 一把伞, 一把椅子."},{"char":"雨衣","pinyin":"yǔyī","hanviet":"Vũ y","chars":["雨","衣"],"story":"雨 = giọt nước rơi dưới mây. 衣 = áo. 雨衣 = áo mưa; dùng với 穿: 穿雨衣. Cùng kiểu với 雨伞 (ô che mưa)."},{"char":"变","pinyin":"biàn","hanviet":"Biến","chars":["变"],"story":"变 = thay đổi. 变 + tính từ = trở nên…: 变好, 变冷, 变漂亮. 天气变了 = thời tiết thay đổi rồi. Buổi sau học 变成 + danh từ."},{"char":"季节","pinyin":"jìjié","hanviet":"Quý tiết","chars":["季","节"],"story":"季 = 禾 (lúa) + 子 → mỗi vụ lúa là một mùa. 节 = 艹 + 卩 → đốt tre, tiết. 季节 = mùa. Bài 14 sẽ học 节 với nghĩa khác (lượng từ: 一节课)."},{"char":"变化","pinyin":"biànhuà","hanviet":"Biến hoá","chars":["变","化"],"story":"变 = đổi; 化 = 亻 (người đứng) + 匕 (người ngã) → biến hoá. 变化 vừa là động từ vừa là danh từ: 天气变化很快 / 变化很大."},{"char":"冬天","pinyin":"dōngtiān","hanviet":"Đông thiên","chars":["冬","天"],"story":"冬 = 夂 + 冫 (hai chấm băng) → mùa nước đóng băng → mùa đông. Bốn mùa: 春 · 夏 · 秋 · 冬; thêm 天 thành tên mùa: 冬天."},{"char":"常常","pinyin":"chángcháng","hanviet":"Thường thường","chars":["常","常"],"story":"常 = thường (bài 8: 常). Lặp lại 常常 = thường thường, nhấn mạnh hơn. Phủ định nói 不常 — không nói ✗ 不常常."},{"char":"关注","pinyin":"guānzhù","hanviet":"Quan chú","chars":["关","注"],"story":"关 lấy từ 关心 (bài 8), 注 lấy từ 注意 (bài 8). 关注 = vừa quan tâm vừa để ý theo dõi: 关注天气, 关注新闻, 关注比赛."},{"char":"四季","pinyin":"sìjì","hanviet":"Tứ quý","chars":["四","季"],"story":"四 = bốn; 季 = 禾 (lúa) + 子 → mùa. 四季 = bốn mùa xuân · hạ · thu · đông. 一年四季 = suốt cả năm."},{"char":"春天","pinyin":"chūntiān","hanviet":"Xuân thiên","chars":["春","天"],"story":"春 = phần trên 三 + 人 (cây cỏ đâm chồi) + 日 (mặt trời) → nắng ấm, cây nảy mầm → mùa xuân. Tết Nguyên đán là 春节 (bài 18)."},{"char":"夏天","pinyin":"xiàtiān","hanviet":"Hạ thiên","chars":["夏","天"],"story":"夏 = hình người có đầu 页, tay chân dang ra → người cởi trần giữa trời nóng → mùa hè. 夏天 = mùa hè."},{"char":"凉快","pinyin":"liángkuai","hanviet":"Lương khoái","chars":["凉","快"],"story":"凉 = 冫 (băng, lạnh) + 京 → mát. 快 trong 快乐 = dễ chịu. 凉快 = mát mẻ dễ chịu (khen); 冷 = lạnh (khó chịu). Pinyin 快 đọc thanh nhẹ."},{"char":"秋天","pinyin":"qiūtiān","hanviet":"Thu thiên","chars":["秋","天"],"story":"秋 = 禾 (lúa) + 火 (lửa) → lúa chín vàng như lửa → mùa thu, mùa gặt. 秋天的叶子 = lá mùa thu."},{"char":"叶子","pinyin":"yèzi","hanviet":"Diệp tử","chars":["叶","子"],"story":"叶 = 口 + 十 → chiếc lá; 子 là hậu tố (như 箱子, 筷子). 树叶 / 叶子 = lá cây. Lá mùa thu: 叶子黄了."},{"char":"变成","pinyin":"biànchéng","hanviet":"Biến thành","chars":["变","成"],"story":"变 = đổi (buổi trước) + 成 = thành. 变成 + danh từ = biến thành: 变成红色, 变成了雪. So sánh 变 + tính từ: 变红了, 变冷了."}],"grammar":[{"title":"或者 + A，或者 + B（，或者 + C）","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>或者</b><small>hoặc</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>A</b><small>khả năng 1</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，或者</b><small>hoặc</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>B</b><small>khả năng 2</small></span></div>","summary":"<p class=\"gr-lead\">Hoặc là …, hoặc là …</p><ul><li>Nêu <b>2 hoặc nhiều khả năng</b>, chỉ chọn một: <span class=\"zh\">或者吃中国菜，或者吃日本菜，或者吃泰国菜</span>.</li><li>Cùng chủ ngữ → chủ ngữ đứng <b>trước 或者 đầu tiên</b>: <span class=\"zh\">我们或者今天去，或者明天去</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">或者……，或者……</span> · Hai, ba lựa chọn</h4><p>Hoặc …, hoặc …</p><div class=\"gr-formula\"><div class=\"fx-lbl\">2 lựa chọn</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>或者</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>明天去</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，或者</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>后天去</b></span></div><div class=\"fx-ex zh\">或者明天去，或者后天去。</div><div class=\"fx-lbl\">Có chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我们</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>或者</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>今天去</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，或者</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>明天去</b></span></div><div class=\"fx-ex zh\">我们或者今天去，或者明天去。</div></div><p class=\"gr-key\">Có thể nêu 3 lựa chọn: <span class=\"zh\">或者A，或者B，或者C</span>　·　Bài 11 học <span class=\"zh\">A 或者 B</span> (chỉ một 或者)</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">或者明天去，或者后天去，我给你打电话。</span> = Hoặc mai đi, hoặc ngày kia đi, cô sẽ gọi cho em.</p>","note":"<b>Lưu ý:</b> Câu hỏi lựa chọn vẫn dùng 还是: ✗ <span class=\"zh\">你或者喝茶，或者喝咖啡？</span> → ✓ <span class=\"zh\">你喝茶还是喝咖啡？</span>","examples":[{"zh":"或者明天去，或者后天去，我给你打电话。","py":"Huòzhě míngtiān qù, huòzhě hòutiān qù, wǒ gěi nǐ dǎ diànhuà.","vi":"Hoặc mai đi, hoặc ngày kia đi, cô sẽ gọi cho em."},{"zh":"我们或者今天去电影院看电影，或者明天在家看电影。","py":"Wǒmen huòzhě jīntiān qù diànyǐngyuàn kàn diànyǐng, huòzhě míngtiān zài jiā kàn diànyǐng.","vi":"Chúng ta hoặc hôm nay ra rạp xem phim, hoặc mai xem phim ở nhà."},{"zh":"晚饭你自己选，或者吃中国菜，或者吃日本菜，或者吃泰国菜。","py":"Wǎnfàn nǐ zìjǐ xuǎn, huòzhě chī Zhōngguócài, huòzhě chī Rìběncài, huòzhě chī Tàiguócài.","vi":"Bữa tối em tự chọn, hoặc món Trung, hoặc món Nhật, hoặc món Thái."}],"exercises":[]},{"title":"动词 / 形容词 + 起来 · 动词 + 起 + 宾语 + 来","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>ĐT / TT</b><small>động từ / tính từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>起</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>(Tân ngữ)</b><small>chen giữa</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>来</b></span></div>","summary":"<p class=\"gr-lead\">… lên, bắt đầu …</p><ul><li>Sau <b>động từ</b> → hành động bắt đầu: <span class=\"zh\">雨已经下起来了</span>; sau <b>tính từ</b> → trạng thái mới: <span class=\"zh\">天气热起来了</span>.</li><li>Động từ có <b>tân ngữ</b> → tân ngữ chen <b>giữa 起 và 来</b>: <span class=\"zh\">刮起风来了 · 唱起歌来</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">起来 · 起……来</span> · Ba dạng thường gặp</h4><p>Bắt đầu … · … lên</p><div class=\"gr-formula\"><div class=\"fx-lbl\">ĐT + 起来</div><div class=\"fx-row\"><span class=\"fx-p\"><b>雨</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>下</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>起来</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b></span></div><div class=\"fx-ex zh\">雨已经下起来了。</div><div class=\"fx-lbl\">TT + 起来</div><div class=\"fx-row\"><span class=\"fx-p\"><b>天气</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>热</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>起来</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b></span></div><div class=\"fx-ex zh\">最近天气热起来了。</div><div class=\"fx-lbl\">ĐT + 起 + TN + 来</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>刮</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>起</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>风</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>来</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b></span></div><div class=\"fx-ex zh\">怎么突然刮起风来了？</div></div><p class=\"gr-key\">Tính từ chiều tốt / mạnh lên hay đi với 起来: <span class=\"zh\">好起来 · 热起来 · 忙起来 · 多起来</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">怎么突然刮起风来了？</span> = Sao tự nhiên lại nổi gió thế?</p>","note":"<b>Lưu ý:</b> Không đặt tân ngữ sau 起来: ✗ <span class=\"zh\">刮起来风了</span> → ✓ <span class=\"zh\">刮起风来了</span>","examples":[{"zh":"雨已经下起来了。","py":"Yǔ yǐjīng xià qǐlai le.","vi":"Mưa đã bắt đầu rơi rồi."},{"zh":"最近天气热起来了。","py":"Zuìjìn tiānqì rè qǐlai le.","vi":"Dạo này trời bắt đầu nóng lên rồi."},{"zh":"怎么突然刮起风来了？","py":"Zěnme tūrán guā qǐ fēng lai le?","vi":"Sao tự nhiên lại nổi gió thế?"}],"exercises":[{"type":"fill","q":"<span class=\"zh\">看到那张照片，大家都____。</span><span class=\"qz-hint\">Nhìn thấy tấm ảnh đó, mọi người đều bật cười.</span>","answer":["笑了起来","笑起来了","笑起来"],"explain":"看到那张照片，大家都笑了起来。 (Kàndào nà zhāng zhàopiàn, dàjiā dōu xiàole qǐlai.)"},{"type":"fill","q":"<span class=\"zh\">吃了药以后，他的身体____。</span><span class=\"qz-hint\">Uống thuốc xong, sức khoẻ anh ấy dần khá lên.</span>","answer":["慢慢好起来了","好起来了","慢慢好起来"],"explain":"吃了药以后，他的身体慢慢好起来了。 (Chīle yào yǐhòu, tā de shēntǐ mànmàn hǎo qǐlai le.)"},{"type":"fill","q":"<span class=\"zh\">他写完作业就____。</span><span class=\"qz-hint\">Làm xong bài tập là cậu ấy bắt đầu xem tivi.</span>","answer":["看起电视来了","看起电视来"],"explain":"他写完作业就看起电视来了。 (Tā xiěwán zuòyè jiù kàn qǐ diànshì lai le.)"}]},{"title":"就 + 动词 + 数量词 · 就 + 名词（例外）","formula":"<div class=\"fx-row\"><span class=\"fx-p c-b\"><b>Chủ ngữ</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b><small>chỉ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>ĐT + 了 + số lượng</b><small>ít, ngắn</small></span></div>","summary":"<p class=\"gr-lead\">Chỉ …; chỉ riêng … là …</p><ul><li>就 + <b>động từ có số lượng</b> → người nói thấy <b>ít, nhẹ, ngắn</b>: <span class=\"zh\">他昨天就看了十分钟书</span>.</li><li>就 + <b>danh từ / chủ ngữ</b> → <b>ngoại lệ</b> (\"chỉ riêng … là\"): <span class=\"zh\">大家都来了，就他没来</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">就 · số lượng · ngoại lệ</span> · Hai cách dùng</h4><p>Chỉ … · ngoại lệ</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Số lượng ít</div><div class=\"fx-row\"><span class=\"fx-p\"><b>今年</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>下了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>一次</b></span></div><div class=\"fx-ex zh\">听说今年就下了一次。</div><div class=\"fx-lbl\">Thời gian ngắn</div><div class=\"fx-row\"><span class=\"fx-p\"><b>他</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>看了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>十分钟</b></span></div><div class=\"fx-ex zh\">他昨天就看了十分钟书。</div><div class=\"fx-lbl\">Ngoại lệ · thời gian</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>今天</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>没带</b></span></div><div class=\"fx-ex zh\">每天都带伞，就今天没带。</div><div class=\"fx-lbl\">Ngoại lệ · người, vật</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>我点的菜</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>不太好吃</b></span></div><div class=\"fx-ex zh\">就我点的这个菜不太好吃。</div></div><p class=\"gr-key\">Bài 3: 就 sau thời gian = <b>sớm, nhanh</b> (<span class=\"zh\">七点就到了</span>)　·　Bài 12: 就 = <b>chỉ</b></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">北京常常下雪，但听说今年就下了一次。</span> = Bắc Kinh hay có tuyết, nhưng nghe nói năm nay chỉ rơi có một lần.</p>","note":"<b>Lưu ý:</b> 就 đứng trước động từ: ✗ <span class=\"zh\">他看了就十分钟书</span> → ✓ <span class=\"zh\">他就看了十分钟书</span>","examples":[{"zh":"北京常常下雪，但听说今年就下了一次。","py":"Běijīng chángcháng xià xuě, dàn tīngshuō jīnnián jiù xiàle yí cì.","vi":"Bắc Kinh hay có tuyết, nhưng nghe nói năm nay chỉ rơi một lần."},{"zh":"他昨天就看了十分钟书。","py":"Tā zuótiān jiù kànle shí fēnzhōng shū.","vi":"Hôm qua cậu ấy chỉ đọc sách có mười phút."},{"zh":"我每天书包里都放着雨伞，就今天没带。","py":"Wǒ měi tiān shūbāo li dōu fàngzhe yǔsǎn, jiù jīntiān méi dài.","vi":"Ngày nào trong cặp mình cũng để ô, chỉ hôm nay là không mang."},{"zh":"你们点的菜都挺好吃的，就我点的这个菜不太好吃。","py":"Nǐmen diǎn de cài dōu tǐng hǎochī de, jiù wǒ diǎn de zhège cài bú tài hǎochī.","vi":"Món các bạn gọi đều ngon, chỉ món mình gọi là không ngon lắm."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">这次考试大家都考得很好，____。</span><span class=\"qz-hint\">Lần thi này ai cũng làm tốt, chỉ cậu ấy là không tốt lắm.</span>","answer":["就他考得不太好","就他考得不好"],"explain":"这次考试大家都考得很好，就他考得不太好。 (Zhè cì kǎoshì dàjiā dōu kǎo de hěn hǎo, jiù tā kǎo de bú tài hǎo.)"},{"type":"fill","q":"<span class=\"zh\">我们班同学几乎都会打篮球，____。</span><span class=\"qz-hint\">Bạn lớp mình gần như ai cũng biết chơi bóng rổ, chỉ mình là không biết.</span>","answer":["就我不会打","就我不会","就我不会打篮球"],"explain":"我们班同学几乎都会打篮球，就我不会打。 (Wǒmen bān tóngxué jīhū dōu huì dǎ lánqiú, jiù wǒ bú huì dǎ.)"}]},{"title":"动词 + 下来","formula":"<div class=\"fx-row\"><span class=\"fx-p c-b\"><b>(Khoảng thời gian)</b><small>bao lâu</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>Động từ</b><small>việc vất vả</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>下来</b><small>làm trọn được</small></span></div>","summary":"<p class=\"gr-lead\">… (trụ) được đến cùng</p><ul><li>ĐT + 下来 → đã <b>làm trọn</b> một việc mất nhiều thời gian, công sức: <span class=\"zh\">5000米的长跑，我跑下来了</span>.</li><li>Hay có <b>khoảng thời gian</b> ở trước: <span class=\"zh\">这半年练下来 · 这一年多住下来</span> = sau ngần ấy thời gian…</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">下来 · 下去</span> · Đối chiếu bài 8</h4><p>Làm trọn được · tiếp tục</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Sống, ở</div><div class=\"fx-row\"><span class=\"fx-p\"><b>一年</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>住</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>下来</b></span></div><div class=\"fx-ex zh\">一年住下来，我习惯了。</div><div class=\"fx-lbl\">Luyện tập</div><div class=\"fx-row\"><span class=\"fx-p\"><b>半年</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>练</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>下来</b></span></div><div class=\"fx-ex zh\">半年练下来，水平提高了。</div><div class=\"fx-lbl\">Việc khó</div><div class=\"fx-row\"><span class=\"fx-p\"><b>5000米</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>跑</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>下来了</b></span></div><div class=\"fx-ex zh\">5000米，我跑下来了。</div><div class=\"fx-lbl\">下去 · bài 8</div><div class=\"fx-row\"><span class=\"fx-p\"><b>一直</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>学</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>下去</b></span></div><div class=\"fx-ex zh\">我想一直学下去。</div></div><p class=\"gr-key\"><span class=\"zh\">下来</span> = nhìn lại, việc khó <b>đã</b> làm xong　·　<span class=\"zh\">下去</span> = nhìn tới, <b>tiếp tục</b> làm</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">这一年多住下来，我还是更喜欢北京的四季。</span> = Sống hơn một năm qua, tôi vẫn thích bốn mùa Bắc Kinh hơn.</p>","note":"<b>Lưu ý:</b> 下来 nhìn lại việc đã xong, 下去 (bài 8) là tiếp tục: ✗ <span class=\"zh\">一年住下去，我习惯了</span> → ✓ <span class=\"zh\">住下来</span>","examples":[{"zh":"这一年多住下来，我还是更喜欢北京的四季。","py":"Zhè yì nián duō zhù xiàlai, wǒ háishi gèng xǐhuan Běijīng de sìjì.","vi":"Sống hơn một năm qua, tôi vẫn thích bốn mùa Bắc Kinh hơn."},{"zh":"这半年练下来，他画画的水平提高了不少。","py":"Zhè bàn nián liàn xiàlai, tā huà huà de shuǐpíng tígāole bù shǎo.","vi":"Nửa năm luyện tập, trình độ vẽ của cậu ấy lên không ít."},{"zh":"5000米的长跑比赛，没想到我跑下来了。","py":"5000 mǐ de chángpǎo bǐsài, méi xiǎngdào wǒ pǎo xiàlai le.","vi":"Cuộc thi chạy dài 5000 mét, không ngờ mình chạy hết được."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">谢谢你一直帮助我，才让我____。</span><span class=\"qz-hint\">Cảm ơn bạn luôn giúp đỡ, nhờ vậy mình mới trụ lại được ở đây.</span>","answer":["在这里住了下来","住了下来","在这里住下来了"],"explain":"谢谢你一直帮助我，才让我在这里住了下来。 (Xièxie nǐ yìzhí bāngzhù wǒ, cái ràng wǒ zài zhèli zhùle xiàlai.)"},{"type":"fill","q":"<span class=\"zh\">虽然外语很难学，可是我____。</span><span class=\"qz-hint\">Tuy ngoại ngữ khó học, nhưng mình vẫn học được đến cùng.</span>","answer":["还是学下来了","学下来了"],"explain":"虽然外语很难学，可是我还是学下来了。 (Suīrán wàiyǔ hěn nán xué, kěshì wǒ háishi xué xiàlai le.)"},{"type":"fill","q":"<span class=\"zh\">这本书对我来说很难，我用了一个月终于____。</span><span class=\"qz-hint\">Cuốn sách này với mình rất khó, mất một tháng mình mới đọc hết được.</span>","answer":["把它看下来了"],"explain":"这本书对我来说很难，我用了一个月终于把它看下来了。 (Zhè běn shū duì wǒ lái shuō hěn nán, wǒ yòngle yí ge yuè zhōngyú bǎ tā kàn xiàlai le.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在街上","titleVi":"Trên phố — rủ nhau đi chèo thuyền","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"王老师，您看，这条街上的树都开花了。","py":"Wáng lǎoshī, nín kàn, zhè tiáo jiē shang de shù dōu kāihuā le.","vi":"Cô Vương ơi, cô xem, cây trên phố này nở hoa hết rồi."},{"speaker":"飞","name":"Nhất Phi","zh":"上周我去公园坐船了，公园里的花也开了。","py":"Shàng zhōu wǒ qù gōngyuán zuò chuán le, gōngyuán li de huā yě kāi le.","vi":"Tuần trước cô đi công viên chèo thuyền, hoa trong công viên cũng nở rồi."},{"speaker":"月","name":"Gia Nguyệt","zh":"天气这么好，下午我也想去公园坐船。","py":"Tiānqì zhème hǎo, xiàwǔ wǒ yě xiǎng qù gōngyuán zuò chuán.","vi":"Trời đẹp thế này, chiều em cũng muốn đi công viên chèo thuyền."},{"speaker":"飞","name":"Nhất Phi","zh":"去吧！今天是工作日，人应该不多。","py":"Qù ba! Jīntiān shì gōngzuòrì, rén yīnggāi bù duō.","vi":"Đi đi! Hôm nay là ngày làm việc, chắc không đông người đâu."},{"speaker":"月","name":"Gia Nguyệt","zh":"您有时间吗？我想跟您一起去。","py":"Nín yǒu shíjiān ma? Wǒ xiǎng gēn nín yìqǐ qù.","vi":"Cô có rảnh không ạ? Em muốn đi cùng cô."},{"speaker":"飞","name":"Nhất Phi","zh":"我今天下午有课，不能去太远的地方。","py":"Wǒ jīntiān xiàwǔ yǒu kè, bù néng qù tài yuǎn de dìfang.","vi":"Chiều nay cô có tiết, không đi chỗ xa quá được."},{"speaker":"月","name":"Gia Nguyệt","zh":"那咱们换一天去？","py":"Nà zánmen huàn yì tiān qù?","vi":"Vậy mình đổi sang hôm khác đi ạ?"},{"speaker":"飞","name":"Nhất Phi","zh":"行。或者明天去，或者后天去，我给你打电话。","py":"Xíng. Huòzhě míngtiān qù, huòzhě hòutiān qù, wǒ gěi nǐ dǎ diànhuà.","vi":"Được. Hoặc mai đi, hoặc ngày kia đi, cô sẽ gọi điện cho em."}]},{"titleZh":"课文二 · 在街上","titleVi":"Trên phố — trời bỗng nổi gió","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"刚才还是大晴天呢，怎么突然就刮起风来了？","py":"Gāngcái hái shì dà qíngtiān ne, zěnme tūrán jiù guā qǐ fēng lai le?","vi":"Vừa nãy còn nắng to, sao tự nhiên lại nổi gió thế?"},{"speaker":"飞","name":"Nhất Phi","zh":"好像新闻里说今天有雨。","py":"Hǎoxiàng xīnwén li shuō jīntiān yǒu yǔ.","vi":"Hình như tin tức nói hôm nay có mưa."},{"speaker":"月","name":"Gia Nguyệt","zh":"啊？我每天书包里都放着雨伞，就今天没带。","py":"Á? Wǒ měi tiān shūbāo li dōu fàngzhe yǔsǎn, jiù jīntiān méi dài.","vi":"Hả? Ngày nào trong cặp em cũng để ô, chỉ hôm nay là không mang."},{"speaker":"飞","name":"Nhất Phi","zh":"我可以借给你，我车里有一把伞和一件雨衣。","py":"Wǒ kěyǐ jiè gěi nǐ, wǒ chē li yǒu yì bǎ sǎn hé yí jiàn yǔyī.","vi":"Cô cho em mượn, trong xe cô có một cái ô và một chiếc áo mưa."},{"speaker":"月","name":"Gia Nguyệt","zh":"谢谢，希望下午天气能变好。","py":"Xièxie, xīwàng xiàwǔ tiānqì néng biàn hǎo.","vi":"Cảm ơn cô, mong chiều nay trời sẽ đẹp lên."},{"speaker":"飞","name":"Nhất Phi","zh":"这个季节天气变化很快。","py":"Zhège jìjié tiānqì biànhuà hěn kuài.","vi":"Mùa này thời tiết thay đổi rất nhanh."},{"speaker":"月","name":"Gia Nguyệt","zh":"雨已经下起来了，咱们快点儿走吧。","py":"Yǔ yǐjīng xià qǐlai le, zánmen kuài diǎnr zǒu ba.","vi":"Mưa bắt đầu rơi rồi, mình đi nhanh lên cô ơi."}]},{"titleZh":"课文三 · 在教室里","titleVi":"Lớp học — hai cô trò trú mưa","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"您来这里已经一年多了，习惯了吧？","py":"Nín lái zhèli yǐjīng yì nián duō le, xíguàn le ba?","vi":"Cô đến đây đã hơn một năm rồi, quen rồi chứ ạ?"},{"speaker":"飞","name":"Nhất Phi","zh":"别的早就习惯了，就是天气我还不太习惯。","py":"Biéde zǎo jiù xíguàn le, jiùshì tiānqì wǒ hái bú tài xíguàn.","vi":"Những thứ khác quen từ lâu rồi, chỉ có thời tiết là cô vẫn chưa quen lắm."},{"speaker":"月","name":"Gia Nguyệt","zh":"为什么？您不喜欢这里的天气吗？","py":"Wèi shénme? Nín bù xǐhuan zhèli de tiānqì ma?","vi":"Sao vậy ạ? Cô không thích thời tiết ở đây à?"},{"speaker":"飞","name":"Nhất Phi","zh":"我觉得冬天太冷了。","py":"Wǒ juéde dōngtiān tài lěng le.","vi":"Cô thấy mùa đông lạnh quá."},{"speaker":"月","name":"Gia Nguyệt","zh":"冬天虽然冷，但是下雪的时候特别漂亮。","py":"Dōngtiān suīrán lěng, dànshì xià xuě de shíhou tèbié piàoliang.","vi":"Mùa đông tuy lạnh nhưng lúc tuyết rơi đẹp lắm ạ."},{"speaker":"飞","name":"Nhất Phi","zh":"我也喜欢雪。北京常常下雪，但听说今年就下了一次。","py":"Wǒ yě xǐhuan xuě. Běijīng chángcháng xià xuě, dàn tīngshuō jīnnián jiù xiàle yí cì.","vi":"Cô cũng thích tuyết. Bắc Kinh hay có tuyết, nhưng nghe nói năm nay chỉ rơi có một lần."},{"speaker":"月","name":"Gia Nguyệt","zh":"我没关注过北京的天气，但是新闻里说过，今年冬天很多地方雪下得都少了。","py":"Wǒ méi guānzhùguo Běijīng de tiānqì, dànshì xīnwén li shuōguo, jīnnián dōngtiān hěn duō dìfang xuě xià de dōu shǎo le.","vi":"Em chưa theo dõi thời tiết Bắc Kinh, nhưng tin tức có nói mùa đông năm nay nhiều nơi tuyết đều ít đi."}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — Nhất Phi viết nhật ký","para":true,"speaker":"飞","lines":[{"zh":"我离开北京到这里工作一年多了。","py":"Wǒ líkāi Běijīng dào zhèli gōngzuò yì nián duō le.","vi":"Tôi rời Bắc Kinh đến đây làm việc đã hơn một năm."},{"zh":"这一年多住下来，我还是更喜欢北京的四季。","py":"Zhè yì nián duō zhù xiàlai, wǒ háishi gèng xǐhuan Běijīng de sìjì.","vi":"Sống hơn một năm qua, tôi vẫn thích bốn mùa của Bắc Kinh hơn."},{"zh":"北京的春天最舒服，天气不冷不热。","py":"Běijīng de chūntiān zuì shūfu, tiānqì bù lěng bú rè.","vi":"Mùa xuân Bắc Kinh dễ chịu nhất, trời không lạnh không nóng."},{"zh":"夏天白天很热，但是晚上比较凉快。","py":"Xiàtiān báitiān hěn rè, dànshì wǎnshang bǐjiào liángkuai.","vi":"Mùa hè ban ngày rất nóng, nhưng buổi tối khá mát mẻ."},{"zh":"秋天树上的叶子都变成了红色、黄色，非常漂亮。","py":"Qiūtiān shù shang de yèzi dōu biànchéngle hóngsè, huángsè, fēicháng piàoliang.","vi":"Mùa thu lá trên cây đều chuyển sang đỏ, vàng, vô cùng đẹp."},{"zh":"冬天不但冷，而且风很大，我最不喜欢冬天。","py":"Dōngtiān búdàn lěng, érqiě fēng hěn dà, wǒ zuì bù xǐhuan dōngtiān.","vi":"Mùa đông không những lạnh mà gió còn rất to, tôi ghét mùa đông nhất."},{"zh":"每个人都有自己最喜欢的季节，你最喜欢哪个季节呢？","py":"Měi ge rén dōu yǒu zìjǐ zuì xǐhuan de jìjié, nǐ zuì xǐhuan nǎge jìjié ne?","vi":"Mỗi người đều có mùa mình thích nhất, bạn thích mùa nào nhất?"}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Phần 1 · Thành phố bạn đang sống","q":{"zh":"两人一组，围绕以下问题讨论现在住的城市。","py":"Liǎng rén yì zǔ, wéirào yǐxià wèntí tǎolùn xiànzài zhù de chéngshì.","vi":"Theo cặp: trao đổi về thành phố đang sống (dùng từ và ngữ pháp bài 12)."},"items":[{"zh":"你在现在的城市已经住了多久了？","py":"Nǐ zài xiànzài de chéngshì yǐjīng zhùle duō jiǔ le?","vi":"Bạn sống ở thành phố hiện tại bao lâu rồi?"},{"zh":"在这里住下来以后，你习惯了吗？","py":"Zài zhèli zhù xiàlai yǐhòu, nǐ xíguàn le ma?","vi":"Sống ở đây một thời gian rồi, bạn đã quen chưa?"},{"zh":"这个城市一年有几个季节？每个季节的天气是什么样的？","py":"Zhège chéngshì yì nián yǒu jǐ ge jìjié? Měi ge jìjié de tiānqì shì shénme yàng de?","vi":"Thành phố này một năm có mấy mùa? Thời tiết mỗi mùa thế nào?"}]},{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Phần 2 · Mùa và thời tiết","q":{"zh":"两人一组，围绕以下问题讨论现在住的城市。","py":"Liǎng rén yì zǔ, wéirào yǐxià wèntí tǎolùn xiànzài zhù de chéngshì.","vi":"Theo cặp: trao đổi về thành phố đang sống (dùng từ và ngữ pháp bài 12)."},"items":[{"zh":"现在是哪个季节？人们在这个季节喜欢做什么？","py":"Xiànzài shì nǎge jìjié? Rénmen zài zhège jìjié xǐhuan zuò shénme?","vi":"Bây giờ là mùa nào? Mùa này mọi người thích làm gì?"},{"zh":"你最喜欢哪个季节？为什么？","py":"Nǐ zuì xǐhuan nǎge jìjié? Wèi shénme?","vi":"Bạn thích mùa nào nhất? Vì sao?"},{"zh":"你觉得今年的天气和以前比，有什么不一样？","py":"Nǐ juéde jīnnián de tiānqì hé yǐqián bǐ, yǒu shénme bù yíyàng?","vi":"Bạn thấy thời tiết năm nay so với trước có gì khác?"}]}],"speak":[{"zh":"口语练习","py":"kǒuyǔ liànxí","tag":"Luyện nói","mean":"Ôn bài 7–12 · Học tiếng Trung","prep":3,"talk":2,"q":{"zh":"请你谈谈你学习汉语的经历。","py":"Qǐng nǐ tántan nǐ xuéxí Hànyǔ de jīnglì.","vi":"Hãy kể về quá trình học tiếng Trung của bạn."},"frame":[{"lbl":"开头","zh":"为了……，我……开始学汉语，已经学了……了。","py":"Wèile ……, wǒ …… kāishǐ xué Hànyǔ, yǐjīng xuéle …… le.","vi":"Để …, mình bắt đầu học tiếng Trung từ …, đã học được … rồi.","ex":{"zh":"为了去中国工作，我去年开始学汉语，已经学了一年多了。","py":"Wèile qù Zhōngguó gōngzuò, wǒ qùnián kāishǐ xué Hànyǔ, yǐjīng xuéle yì nián duō le.","vi":"Để sang Trung Quốc làm việc, mình học từ năm ngoái, đã hơn một năm rồi."}},{"lbl":"中间","zh":"刚开始的时候，我常常……不懂，但是我想一直学下去。","py":"Gāng kāishǐ de shíhou, wǒ chángcháng …… bu dǒng, dànshì wǒ xiǎng yìzhí xué xiàqu.","vi":"Lúc mới đầu, mình thường … không hiểu, nhưng mình muốn học tiếp mãi.","ex":{"zh":"刚开始的时候，我常常听不懂，但是我想一直学下去。","py":"Gāng kāishǐ de shíhou, wǒ chángcháng tīng bu dǒng, dànshì wǒ xiǎng yìzhí xué xiàqu.","vi":"Lúc mới đầu, mình thường nghe không hiểu, nhưng mình muốn học tiếp mãi."}},{"lbl":"中间","zh":"在……的帮助下，这一年学下来，我的……。","py":"Zài …… de bāngzhù xià, zhè yì nián xué xiàlai, wǒ de …….","vi":"Nhờ … giúp đỡ, học suốt một năm qua, … của mình …","ex":{"zh":"在老师的帮助下，这一年学下来，我的水平提高了不少。","py":"Zài lǎoshī de bāngzhù xià, zhè yì nián xué xiàlai, wǒ de shuǐpíng tígāole bù shǎo.","vi":"Nhờ cô giáo giúp, học suốt một năm qua, trình độ mình lên không ít."}},{"lbl":"中间","zh":"对我来说，……最难，不过我越……越……。","py":"Duì wǒ lái shuō, …… zuì nán, búguò wǒ yuè …… yuè …….","vi":"Với mình, … khó nhất, nhưng mình càng … càng …","ex":{"zh":"对我来说，汉字最难，不过我越写越喜欢。","py":"Duì wǒ lái shuō, Hànzì zuì nán, búguò wǒ yuè xiě yuè xǐhuan.","vi":"Với mình, chữ Hán khó nhất, nhưng mình càng viết càng thích."}},{"lbl":"结尾","zh":"学完这本书以后，我或者……，或者……。","py":"Xuéwán zhè běn shū yǐhòu, wǒ huòzhě ……, huòzhě …….","vi":"Học xong cuốn sách này, mình hoặc …, hoặc …","ex":{"zh":"学完这本书以后，我或者去中国学习，或者找工作。","py":"Xuéwán zhè běn shū yǐhòu, wǒ huòzhě qù Zhōngguó xuéxí, huòzhě zhǎo gōngzuò.","vi":"Học xong cuốn này, mình hoặc sang Trung Quốc học, hoặc đi tìm việc."}}]}]},"review":{"range":"10–12","rows":[{"l":10,"zh":"\"把\"字句 (1)","vi":"Câu chữ 把 (1)","ex":{"zh":"我会把这些题都记在本子上。","py":"Wǒ huì bǎ zhèxiē tí dōu jì zài běnzi shang.","vi":"Em sẽ ghi hết những bài này vào vở."}},{"l":10,"zh":"固定格式 \"在……上/中/下\"","vi":"Cấu trúc 在……上 / 中 / 下","ex":{"zh":"在学习上，遇到什么问题都可以问我。","py":"Zài xuéxí shang, yùdào shénme wèntí dōu kěyǐ wèn wǒ.","vi":"Về học tập, gặp vấn đề gì cũng có thể hỏi cô."}},{"l":10,"zh":"\"把\"字句 (2)","vi":"Câu chữ 把 (2)","ex":{"zh":"你明天再把书还给我。","py":"Nǐ míngtiān zài bǎ shū huán gěi wǒ.","vi":"Mai em hãy trả sách cho cô."}},{"l":11,"zh":"\"还是\"和\"或者\"","vi":"Phân biệt 还是 và 或者","ex":{"zh":"我们用会议室的电脑还是自己的笔记本电脑？","py":"Wǒmen yòng huìyìshì de diànnǎo háishi zìjǐ de bǐjìběn diànnǎo?","vi":"Chúng ta dùng máy tính phòng họp hay laptop của mình?"}},{"l":11,"zh":"固定短语 \"看来\"","vi":"Cụm cố định 看来","ex":{"zh":"看来我没办法解决这个问题。","py":"Kànlái wǒ méi bànfǎ jiějué zhège wèntí.","vi":"Xem ra em không giải quyết được vấn đề này."}},{"l":11,"zh":"\"把\"字句 (3)","vi":"Câu chữ 把 (3)","ex":{"zh":"我跟您一起把这些工作做完。","py":"Wǒ gēn nín yìqǐ bǎ zhèxiē gōngzuò zuòwán.","vi":"Em cùng chị làm xong chỗ việc này."}},{"l":11,"zh":"固定格式 \"对……来说\"","vi":"Cấu trúc 对……来说","ex":{"zh":"对我来说，生活也很重要，我不愿意为工作或学习离开家人。","py":"Duì wǒ lái shuō, shēnghuó yě hěn zhòngyào, wǒ bú yuànyì wèi gōngzuò huò xuéxí líkāi jiārén.","vi":"Với em, cuộc sống cũng quan trọng, em không muốn vì công việc hay học tập mà xa gia đình."}},{"l":12,"zh":"选择复句 \"或者……，或者……\"","vi":"Câu phức lựa chọn 或者……，或者……","ex":{"zh":"或者明天去，或者后天去，我给你打电话。","py":"Huòzhě míngtiān qù, huòzhě hòutiān qù, wǒ gěi nǐ dǎ diànhuà.","vi":"Hoặc mai đi, hoặc ngày kia đi, cô sẽ gọi cho em."}},{"l":12,"zh":"趋向补语的引申用法 (2) \"起来\"","vi":"Bổ ngữ xu hướng — nghĩa mở rộng (2): 起来","ex":{"zh":"雨已经下起来了。","py":"Yǔ yǐjīng xià qǐlai le.","vi":"Mưa đã bắt đầu rơi rồi."}},{"l":12,"zh":"范围副词 \"就\"","vi":"Phó từ phạm vi 就","ex":{"zh":"北京常常下雪，但听说今年就下了一次。","py":"Běijīng chángcháng xià xuě, dàn tīngshuō jīnnián jiù xiàle yí cì.","vi":"Bắc Kinh hay có tuyết, nhưng nghe nói năm nay chỉ rơi một lần."}},{"l":12,"zh":"趋向补语的引申用法 (3) \"下来\"","vi":"Bổ ngữ xu hướng — nghĩa mở rộng (3): 下来","ex":{"zh":"这一年多住下来，我还是更喜欢北京的四季。","py":"Zhè yì nián duō zhù xiàlai, wǒ háishi gèng xǐhuan Běijīng de sìjì.","vi":"Sống hơn một năm qua, tôi vẫn thích bốn mùa Bắc Kinh hơn."}}]}},{"id":"k3v3-b13","courseId":"k3v3","order":13,"title":"Hàng xóm mới của tôi đến từ Anh","titleZh":"我的新邻居来自英国","titlePy":"wǒ de xīn línjū láizì Yīngguó","vocab":[{"stt":1,"hanzi":"请客","pinyin":"qǐngkè","hanviet":"Thỉnh khách","pos":"Động từ (li hợp)","meaning":"mời (ăn), khao","comps":"我请客 (tôi mời / tôi khao), 请客吃饭 (mời ăn cơm)","example":{"zh":"今天是我的生日，晚饭我请客。","py":"Jīntiān shì wǒ de shēngrì, wǎnfàn wǒ qǐngkè.","vi":"Hôm nay sinh nhật mình, bữa tối mình khao."}},{"stt":2,"hanzi":"南方","pinyin":"nánfāng","hanviet":"Nam phương","pos":"Danh từ","meaning":"miền Nam, phương nam","comps":"南方菜 (món miền Nam), 南方人 (người miền Nam)","example":{"zh":"南方的冬天不太冷，可是常常下雨。","py":"Nánfāng de dōngtiān bú tài lěng, kěshì chángcháng xià yǔ.","vi":"Mùa đông miền Nam không lạnh lắm, nhưng hay mưa."}},{"stt":3,"hanzi":"北方","pinyin":"běifāng","hanviet":"Bắc phương","pos":"Danh từ","meaning":"miền Bắc, phương bắc","comps":"北方菜 (món miền Bắc), 北方人 (người miền Bắc)","example":{"zh":"我是北方人，我很喜欢吃面条。","py":"Wǒ shì běifāngrén, wǒ hěn xǐhuan chī miàntiáo.","vi":"Mình là người miền Bắc, mình rất thích ăn mì."}},{"stt":4,"hanzi":"做法","pinyin":"zuòfǎ","hanviet":"Tố pháp","pos":"Danh từ","meaning":"cách làm","comps":"菜的做法 (cách nấu món ăn), 这种做法 (cách làm này)","example":{"zh":"这个菜的做法很简单，你也能学会。","py":"Zhège cài de zuòfǎ hěn jiǎndān, nǐ yě néng xuéhuì.","vi":"Cách nấu món này rất đơn giản, bạn cũng học được."}},{"stt":5,"hanzi":"不同","pinyin":"bù tóng","hanviet":"Bất đồng","pos":"Cụm từ","meaning":"khác nhau","comps":"跟…不同 (khác với…), 不同的地方 (những nơi khác nhau)","example":{"zh":"每个人的生活习惯都不同。","py":"Měi ge rén de shēnghuó xíguàn dōu bù tóng.","vi":"Thói quen sinh hoạt của mỗi người đều khác nhau."}},{"stt":6,"hanzi":"加","pinyin":"jiā","hanviet":"Gia","pos":"Động từ","meaning":"thêm","comps":"加牛奶 (thêm sữa), 再加一个菜 (gọi thêm một món)","example":{"zh":"你的咖啡要加牛奶吗？","py":"Nǐ de kāfēi yào jiā niúnǎi ma?","vi":"Cà phê của bạn có cho thêm sữa không?"}},{"stt":7,"hanzi":"的话","pinyin":"dehuà","hanviet":"Đích thoại","pos":"Trợ từ","meaning":"nếu … (thì)","comps":"有时间的话 (nếu có thời gian), 如果……的话 (nếu như…)","example":{"zh":"明天下雨的话，我们就不去公园了。","py":"Míngtiān xià yǔ dehuà, wǒmen jiù bú qù gōngyuán le.","vi":"Nếu mai mưa thì chúng mình không đi công viên nữa."}},{"stt":8,"hanzi":"做客","pinyin":"zuòkè","hanviet":"Tố khách","pos":"Động từ (li hợp)","meaning":"làm khách, đến nhà ai chơi","comps":"来我家做客 (đến nhà tôi chơi), 去朋友家做客","example":{"zh":"周末我去朋友家做客，带了一些水果。","py":"Zhōumò wǒ qù péngyou jiā zuòkè, dàile yìxiē shuǐguǒ.","vi":"Cuối tuần mình đến nhà bạn chơi, có mang ít hoa quả."}},{"stt":9,"hanzi":"邻居","pinyin":"línjū","hanviet":"Lân cư","pos":"Danh từ","meaning":"hàng xóm","comps":"新邻居 (hàng xóm mới), 我的邻居 (hàng xóm của tôi)","example":{"zh":"我的邻居很热情，常常帮助我。","py":"Wǒ de línjū hěn rèqíng, chángcháng bāngzhù wǒ.","vi":"Hàng xóm của mình rất nhiệt tình, hay giúp mình."}},{"stt":10,"hanzi":"放心","pinyin":"fàngxīn","hanviet":"Phóng tâm","pos":"Động từ (li hợp)","meaning":"yên tâm","comps":"放心吧 (yên tâm đi), 不放心 (không yên tâm)","example":{"zh":"放心吧，我到了就给你打电话。","py":"Fàngxīn ba, wǒ dàole jiù gěi nǐ dǎ diànhuà.","vi":"Yên tâm đi, đến nơi mình gọi cho bạn ngay."}},{"stt":11,"hanzi":"酒","pinyin":"jiǔ","hanviet":"Tửu","pos":"Danh từ","meaning":"rượu","comps":"喝酒 (uống rượu), 啤酒 (bia), 一瓶酒 (một chai rượu)","example":{"zh":"开车的时候不能喝酒。","py":"Kāichē de shíhou bù néng hē jiǔ.","vi":"Khi lái xe không được uống rượu."}},{"stt":12,"hanzi":"放","pinyin":"fàng","hanviet":"Phóng","pos":"Động từ","meaning":"đặt, để","comps":"放在桌子上 (để trên bàn), 放进冰箱 (cho vào tủ lạnh)","example":{"zh":"你的手机我放在桌子上了。","py":"Nǐ de shǒujī wǒ fàng zài zhuōzi shang le.","vi":"Điện thoại của bạn mình để trên bàn rồi."}},{"stt":13,"hanzi":"客人","pinyin":"kèrén","hanviet":"Khách nhân","pos":"Danh từ","meaning":"khách","comps":"来客人了 (có khách đến), 请客人吃饭 (mời khách ăn cơm)","example":{"zh":"今天家里来客人了，妈妈做了很多菜。","py":"Jīntiān jiā li lái kèrén le, māma zuòle hěn duō cài.","vi":"Hôm nay nhà có khách, mẹ nấu rất nhiều món."}},{"stt":14,"hanzi":"晚会","pinyin":"wǎnhuì","hanviet":"Vãn hội","pos":"Danh từ","meaning":"buổi liên hoan tối, dạ hội","comps":"生日晚会 (tiệc sinh nhật buổi tối), 新年晚会 (dạ hội năm mới)","example":{"zh":"周五晚上我们班有一个新年晚会。","py":"Zhōuwǔ wǎnshang wǒmen bān yǒu yí ge xīnnián wǎnhuì.","vi":"Tối thứ Sáu lớp mình có buổi liên hoan năm mới."}},{"stt":15,"hanzi":"礼物","pinyin":"lǐwù","hanviet":"Lễ vật","pos":"Danh từ","meaning":"quà, món quà","comps":"生日礼物 (quà sinh nhật), 送礼物 (tặng quà), 小礼物 (món quà nhỏ)","example":{"zh":"这是我给你买的生日礼物，希望你喜欢。","py":"Zhè shì wǒ gěi nǐ mǎi de shēngrì lǐwù, xīwàng nǐ xǐhuan.","vi":"Đây là quà sinh nhật mình mua cho bạn, mong bạn thích."}},{"stt":16,"hanzi":"画家","pinyin":"huàjiā","hanviet":"Hoạ gia","pos":"Danh từ","meaning":"hoạ sĩ","comps":"一名画家 (một hoạ sĩ), 有名的画家 (hoạ sĩ nổi tiếng)","example":{"zh":"他爸爸是一名画家，家里有很多画。","py":"Tā bàba shì yì míng huàjiā, jiā li yǒu hěn duō huà.","vi":"Bố cậu ấy là hoạ sĩ, trong nhà có rất nhiều tranh."}},{"stt":17,"hanzi":"盘子","pinyin":"pánzi","hanviet":"Bàn tử","pos":"Danh từ","meaning":"cái đĩa","comps":"一个盘子 (một cái đĩa), 洗盘子 (rửa đĩa)","example":{"zh":"吃完饭，我来洗盘子吧。","py":"Chīwán fàn, wǒ lái xǐ pánzi ba.","vi":"Ăn xong, để mình rửa đĩa cho."}},{"stt":18,"hanzi":"一边","pinyin":"yìbiān","hanviet":"Nhất biên","pos":"Phó từ","meaning":"vừa … (vừa …)","comps":"一边……一边…… (vừa … vừa …), 边吃边聊 (vừa ăn vừa nói chuyện)","example":{"zh":"他喜欢一边听音乐，一边做作业。","py":"Tā xǐhuan yìbiān tīng yīnyuè, yìbiān zuò zuòyè.","vi":"Cậu ấy thích vừa nghe nhạc vừa làm bài tập."}},{"stt":19,"hanzi":"聊天儿","pinyin":"liáotiānr","hanviet":"Liêu thiên","pos":"Động từ (li hợp)","meaning":"trò chuyện, tán gẫu","comps":"跟朋友聊天儿 (trò chuyện với bạn), 聊了一会儿天儿","example":{"zh":"下课以后，我们常常在咖啡馆聊天儿。","py":"Xiàkè yǐhòu, wǒmen chángcháng zài kāfēiguǎn liáotiānr.","vi":"Tan học, tụi mình hay ngồi cà phê trò chuyện."}},{"stt":20,"hanzi":"来自","pinyin":"láizì","hanviet":"Lai tự","pos":"Động từ","meaning":"đến từ","comps":"来自中国 (đến từ Trung Quốc), 来自哪里 (đến từ đâu)","example":{"zh":"我们班的同学来自不同的国家。","py":"Wǒmen bān de tóngxué láizì bù tóng de guójiā.","vi":"Các bạn lớp mình đến từ nhiều nước khác nhau."}},{"stt":21,"hanzi":"夫妻","pinyin":"fūqī","hanviet":"Phu thê","pos":"Danh từ","meaning":"vợ chồng","comps":"年轻夫妻 (vợ chồng trẻ), 一对夫妻 (một cặp vợ chồng)","example":{"zh":"楼下住着一对年轻夫妻。","py":"Lóu xià zhùzhe yí duì niánqīng fūqī.","vi":"Tầng dưới có một cặp vợ chồng trẻ ở."}},{"stt":22,"hanzi":"直到","pinyin":"zhídào","hanviet":"Trực đáo","pos":"Động từ","meaning":"mãi đến, cho đến tận","comps":"直到现在 (mãi đến bây giờ), 直到……才…… (mãi đến … mới …)","example":{"zh":"他昨天工作到很晚，直到十一点才回家。","py":"Tā zuótiān gōngzuò dào hěn wǎn, zhídào shíyī diǎn cái huí jiā.","vi":"Hôm qua anh ấy làm muộn, mãi 11 giờ mới về nhà."}},{"stt":23,"hanzi":"地图","pinyin":"dìtú","hanviet":"Địa đồ","pos":"Danh từ","meaning":"bản đồ","comps":"世界地图 (bản đồ thế giới), 看地图 (xem bản đồ), 手机地图","example":{"zh":"我不认识路，我们看看手机地图吧。","py":"Wǒ bú rènshi lù, wǒmen kànkan shǒujī dìtú ba.","vi":"Mình không biết đường, mình xem bản đồ điện thoại đi."}},{"stt":24,"hanzi":"点","pinyin":"diǎn","hanviet":"Điểm","pos":"Danh từ","meaning":"chấm, điểm","comps":"红点 (chấm đỏ), 一个点 (một chấm)","example":{"zh":"地图上的这个红点就是我们的学校。","py":"Dìtú shang de zhège hóng diǎn jiù shì wǒmen de xuéxiào.","vi":"Chấm đỏ này trên bản đồ chính là trường mình."}},{"stt":25,"hanzi":"感到","pinyin":"gǎndào","hanviet":"Cảm đáo","pos":"Động từ","meaning":"cảm thấy","comps":"感到高兴 (thấy vui), 感到很累 (cảm thấy rất mệt)","example":{"zh":"能来中国学习，我感到很高兴。","py":"Néng lái Zhōngguó xuéxí, wǒ gǎndào hěn gāoxìng.","vi":"Được sang Trung Quốc học, mình thấy rất vui."}},{"stt":26,"hanzi":"东方","pinyin":"dōngfāng","hanviet":"Đông phương","pos":"Danh từ","meaning":"phương Đông","comps":"东方文化 (văn hoá phương Đông), 东方人 (người phương Đông)","example":{"zh":"每天早上，太阳从东方出来。","py":"Měi tiān zǎoshang, tàiyáng cóng dōngfāng chūlai.","vi":"Mỗi sáng, mặt trời mọc ở phương Đông."}},{"stt":27,"hanzi":"文化","pinyin":"wénhuà","hanviet":"Văn hoá","pos":"Danh từ","meaning":"văn hoá","comps":"中国文化 (văn hoá Trung Quốc), 文化不同 (văn hoá khác nhau)","example":{"zh":"我对中国文化很感兴趣。","py":"Wǒ duì Zhōngguó wénhuà hěn gǎn xìngqù.","vi":"Mình rất hứng thú với văn hoá Trung Quốc."}},{"stt":28,"hanzi":"英国","pinyin":"Yīngguó","hanviet":"Anh quốc","pos":"Danh từ riêng","meaning":"nước Anh","comps":"英国人 (người Anh), 英语 (tiếng Anh)","example":{"zh":"她是英国人，现在在北京学习中文。","py":"Tā shì Yīngguórén, xiànzài zài Běijīng xuéxí Zhōngwén.","vi":"Cô ấy là người Anh, hiện đang học tiếng Trung ở Bắc Kinh."}}],"hanzi":[{"char":"请客","pinyin":"qǐngkè","hanviet":"Thỉnh khách","chars":["请","客"],"story":"请 = 讠 (lời nói) + 青 → lời mời. 客 = 宀 (mái nhà) + 各 → người nơi khác đến dưới mái nhà → khách. 请客 = mời khách, khao (mình trả tiền). Li hợp: 请了一次客."},{"char":"南方","pinyin":"nánfāng","hanviet":"Nam phương","chars":["南","方"],"story":"南 = phương nam; 方 = phương, hướng. 南方 = miền Nam (ở Trung Quốc: phía nam sông Trường Giang). Cùng nhóm: 北方, 东方 (buổi sau), 西方."},{"char":"北方","pinyin":"běifāng","hanviet":"Bắc phương","chars":["北","方"],"story":"北 = hai người quay lưng vào nhau → cái lưng; nhà xưa quay lưng về hướng bắc → phương bắc. 北方 = miền Bắc. 北京 = kinh đô phía bắc."},{"char":"做法","pinyin":"zuòfǎ","hanviet":"Tố pháp","chars":["做","法"],"story":"做 = làm. 法 = 氵 (nước) + 去 → nước chảy theo đường → phép tắc, cách. 做法 = cách làm (món ăn, công việc). Cùng chữ 法 với 方法 (bài 8), 办法 (bài 11)."},{"char":"不同","pinyin":"bù tóng","hanviet":"Bất đồng","chars":["不","同"],"story":"同 = cùng (同学, 同事). 不同 = không cùng → khác nhau. A 跟 B 不同 = A 跟 B 不一样 (bài 4). Trước danh từ thêm 的: 不同的地方, 不同的国家."},{"char":"加","pinyin":"jiā","hanviet":"Gia","chars":["加"],"story":"加 = 力 (sức) + 口 (miệng) → vừa ra sức vừa hô thêm → thêm vào. 加 + vật: 加牛奶, 加水. Gọi món: 再加一个菜 = gọi thêm một món."},{"char":"的话","pinyin":"dehuà","hanviet":"Đích thoại","chars":["的","话"],"story":"话 = lời nói. 的话 đặt cuối vế giả thiết = \"nếu nói là…\" → nếu…: 有时间的话. Có thể đi cùng 如果 (bài 6): 如果明天下雨的话, 我们就不去了."},{"char":"做客","pinyin":"zuòkè","hanviet":"Tố khách","chars":["做","客"],"story":"做 = làm; 客 = khách → làm khách, đến nhà người khác chơi. 来 / 去 + nhà ai + 做客: 来我家做客. Chủ nhà thì 请客, khách thì 做客."},{"char":"邻居","pinyin":"línjū","hanviet":"Lân cư","chars":["邻","居"],"story":"邻 = 令 + 阝 (làng xóm) → người cùng xóm ở sát bên. 居 = 尸 + 古 → ở, cư trú (居住). 邻居 = người ở sát bên → hàng xóm (Lân cư)."},{"char":"放心","pinyin":"fàngxīn","hanviet":"Phóng tâm","chars":["放","心"],"story":"放 = thả ra; 心 = trái tim. 放心 = thả lỏng trái tim → yên tâm. Ngược nghĩa với 担心 (bài 8). Câu trấn an quen thuộc: 放心吧!"},{"char":"酒","pinyin":"jiǔ","hanviet":"Tửu","chars":["酒"],"story":"酒 = 氵 (nước) + 酉 (hình bình rượu cổ) → rượu. Chỉ chung đồ uống có cồn: 啤酒 (bia, bài 9), 红酒 (rượu vang). Lượng từ 瓶 / 杯."},{"char":"放","pinyin":"fàng","hanviet":"Phóng","chars":["放"],"story":"放 = 方 + 攵 (tay cầm roi) → thả ra, đặt xuống. 放在 + nơi: 放在桌子上; 放进 + nơi: 放进冰箱里. Ôn: 放假 (nghỉ), 放心 (yên tâm)."},{"char":"客人","pinyin":"kèrén","hanviet":"Khách nhân","chars":["客","人"],"story":"客 = khách; 人 = người. 客人 = khách đến nhà / đến cửa hàng. 来客人了 = có khách tới. Người tiếp khách là 主人 (chủ nhà)."},{"char":"晚会","pinyin":"wǎnhuì","hanviet":"Vãn hội","chars":["晚","会"],"story":"晚 = 日 (mặt trời) + 免 → lúc mặt trời đã lặn → buổi tối. 会 = người tụ họp dưới mái nhà. 晚会 = buổi tụ họp buổi tối → liên hoan, dạ hội. 生日晚会 = tiệc sinh nhật tối."},{"char":"礼物","pinyin":"lǐwù","hanviet":"Lễ vật","chars":["礼","物"],"story":"礼 = 礻 (bộ thị — cúng lễ) + 乚 → lễ nghi. 物 = 牛 + 勿 → đồ vật. 礼物 = vật dâng theo lễ → quà (Lễ vật). Đi với 送 / 准备 / 收到: 送礼物."},{"char":"画家","pinyin":"huàjiā","hanviet":"Hoạ gia","chars":["画","家"],"story":"画 = vẽ; tranh. 家 làm hậu tố = người có chuyên môn: 画家 (hoạ sĩ), 音乐家 (nhạc sĩ). So sánh hậu tố 员 = người làm nghề: 服务员, 运动员."},{"char":"盘子","pinyin":"pánzi","hanviet":"Bàn tử","chars":["盘","子"],"story":"盘 = 舟 + 皿 (bộ mãnh — đồ đựng) → cái mâm, cái đĩa. 子 là hậu tố danh từ (筷子, 勺子 bài 2). 盘子 = cái đĩa; 碗 = cái bát."},{"char":"一边","pinyin":"yìbiān","hanviet":"Nhất biên","chars":["一","边"],"story":"边 = bên, phía (旁边). 一边 A，一边 B = một bên làm A, một bên làm B → vừa A vừa B, hai việc cùng lúc. Nói nhanh: 边吃边聊."},{"char":"聊天儿","pinyin":"liáotiānr","hanviet":"Liêu thiên","chars":["聊","天","儿"],"story":"聊 = 耳 (tai) + 卯 → nghe nhau nói. 天 = trời. 聊天儿 = \"nói chuyện trên trời dưới đất\" → trò chuyện, tán gẫu. Li hợp: 聊了一会儿天儿."},{"char":"来自","pinyin":"láizì","hanviet":"Lai tự","chars":["来","自"],"story":"来 = đến; 自 = từ (vốn vẽ cái mũi — người TQ chỉ vào mũi khi nói \"tôi\"). 来自 + nơi = đến từ: 来自英国. Văn viết hơn 从……来."},{"char":"夫妻","pinyin":"fūqī","hanviet":"Phu thê","chars":["夫","妻"],"story":"夫 = 大 + 一 (cây trâm cài tóc) → người đàn ông trưởng thành → chồng. 妻 = 女 + tay cầm trâm → vợ. 夫妻 = vợ chồng (Phu thê); lượng từ 对: 一对夫妻."},{"char":"直到","pinyin":"zhídào","hanviet":"Trực đáo","chars":["直","到"],"story":"直 = 十 + 目 → nhìn thẳng (一直 bài 4). 到 = đến. 直到 = thẳng một mạch đến → mãi đến. Hay đi với 才: 直到十二点多才回家."},{"char":"地图","pinyin":"dìtú","hanviet":"Địa đồ","chars":["地","图"],"story":"地 = 土 (đất) + 也. 图 = 囗 (khung) + 冬 → hình vẽ trong khung. 地图 = hình vẽ mặt đất → bản đồ (Địa đồ). 世界地图 = bản đồ thế giới."},{"char":"点","pinyin":"diǎn","hanviet":"Điểm","chars":["点"],"story":"点 = 占 + 灬 (bốn chấm lửa) → dấu chấm nhỏ. Bài này 点 là danh từ: 红点 = chấm đỏ. Ôn các nghĩa cũ: 三点 (giờ), 点菜 (gọi món), 一点儿 (một chút)."},{"char":"感到","pinyin":"gǎndào","hanviet":"Cảm đáo","chars":["感","到"],"story":"感 = 咸 + 心 → trái tim rung động. 到 = đến. 感到 + tính từ / cảm xúc = cảm thấy: 感到高兴, 感到很特别. Gần nghĩa 觉得 nhưng trang trọng hơn."},{"char":"东方","pinyin":"dōngfāng","hanviet":"Đông phương","chars":["东","方"],"story":"东 phồn thể 東 = 木 (cây) + 日 (mặt trời) → mặt trời mọc sau rặng cây → hướng đông. 东方 = phương Đông (châu Á); đối lập 西方 = phương Tây."},{"char":"文化","pinyin":"wénhuà","hanviet":"Văn hoá","chars":["文","化"],"story":"文 = hình người có hoa văn trên ngực → chữ viết, văn. 化 = biến đổi (变化 bài 12). 文化 = dùng chữ nghĩa để giáo hoá con người → văn hoá. 中国文化, 东方文化."},{"char":"英国","pinyin":"Yīngguó","hanviet":"Anh quốc","chars":["英","国"],"story":"英 = 艹 + 央 → bông hoa đẹp nhất, tinh anh. 英国 = phiên âm tên nước Anh (England) → nước Anh. 英语 = tiếng Anh, 英国人 = người Anh."}],"grammar":[{"title":"（主语）+ 假设 + 的话，（主语）+ 就 + 结果","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>Giả thiết</b><small>tình huống giả định</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的话</b><small>nếu</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>，(Chủ ngữ)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b><small>thì</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>Kết quả</b><small>kết quả / kết luận</small></span></div>","summary":"<p class=\"gr-lead\">Nếu … thì …</p><ul><li>的话 đứng <b>cuối vế giả thiết</b>; vế sau thường có <span class=\"zh\">就</span>: <span class=\"zh\">你觉得满意的话，咱们就买</span>.</li><li>Có thể thêm <span class=\"zh\">如果</span> (bài 6) ở đầu: <span class=\"zh\">如果明天天气好的话，我就去爬山</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">……的话，就……</span> · Ba cách nói</h4><p>Nếu … thì …</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Cùng chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>有时间</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的话</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>来我家</b></span></div><div class=\"fx-ex zh\">有时间的话，就来我家。</div><div class=\"fx-lbl\">Hai chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>你满意</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的话</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>咱们就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>买</b></span></div><div class=\"fx-ex zh\">你满意的话，咱们就买。</div><div class=\"fx-lbl\">如果……的话</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>如果</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>下雨</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的话</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>就不去了</b></span></div><div class=\"fx-ex zh\">如果下雨的话，就不去了。</div></div><p class=\"gr-key\"><span class=\"zh\">……的话</span> mang màu khẩu ngữ　·　<span class=\"zh\">如果……就……</span> (bài 6) dùng được cả nói lẫn viết</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">你们有时间的话，就来我家做客。</span> = Mọi người có thời gian thì đến nhà chị chơi.</p>","note":"<b>Lưu ý:</b> 就 đứng <b>sau chủ ngữ</b> vế sau: ✗ <span class=\"zh\">天气好的话，就我去爬山</span> → ✓ <span class=\"zh\">我就去爬山</span>","examples":[{"zh":"你们有时间的话，就来我家做客。","py":"Nǐmen yǒu shíjiān dehuà, jiù lái wǒ jiā zuòkè.","vi":"Mọi người có thời gian thì đến nhà chị chơi."},{"zh":"你觉得满意的话，咱们就买。","py":"Nǐ juéde mǎnyì dehuà, zánmen jiù mǎi.","vi":"Nếu em thấy hài lòng thì mình mua."},{"zh":"明天天气好的话，我就去爬山。","py":"Míngtiān tiānqì hǎo dehuà, wǒ jiù qù páshān.","vi":"Nếu mai trời đẹp thì mình đi leo núi."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">明天你没事的话，____。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">好啊，早就听说你做的北京菜特别好吃。</span></span></span><span class=\"qz-hint\">Mai bạn không bận thì đến nhà mình ăn cơm nhé. — Hay quá, nghe nói lâu rồi món Bắc Kinh bạn nấu ngon lắm.</span>","answer":["就来我家吃饭吧","就来我家吃饭","来我家吃饭吧"],"explain":"明天你没事的话，就来我家吃饭吧。 (Míngtiān nǐ méi shì dehuà, jiù lái wǒ jiā chī fàn ba.)"}]},{"title":"主语 + 把 + 宾语 + 动词 + 趋向补语 / 状态补语","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b><small>(đem)</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>宾语</b><small>vật xác định</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>趋向 / 得 + 状态</b><small>bổ ngữ</small></span></div>","summary":"<p class=\"gr-lead\">Đem … ra / vào / qua · làm … đến mức …</p><ul><li>Bổ ngữ <b>xu hướng</b> → đổi vị trí: <span class=\"zh\">把饮料拿出来 · 把球踢进去 · 把盘子拿过来</span>.</li><li>Bổ ngữ <b>trạng thái</b> (<span class=\"zh\">得 + …</span>) → kết quả, mức độ: <span class=\"zh\">你把声音开得太大了</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">把 + 宾语 + 动词 + 补语</span> · Hai loại bổ ngữ</h4><p>Xu hướng · trạng thái</p><div class=\"gr-formula\"><div class=\"fx-lbl\">V + 出来 · ra</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>饮料</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>拿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>出来</b></span></div><div class=\"fx-ex zh\">我已经把饮料拿出来了。</div><div class=\"fx-lbl\">V + 进 + nơi</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>酒</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>放</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>进冰箱里</b></span></div><div class=\"fx-ex zh\">我把酒放进冰箱里了。</div><div class=\"fx-lbl\">V + 过来 · qua</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我去</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>盘子</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>拿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>过来</b></span></div><div class=\"fx-ex zh\">我去把盘子拿过来。</div><div class=\"fx-lbl\">V + 得 + trạng thái</div><div class=\"fx-row\"><span class=\"fx-p\"><b>你</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>声音</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>开</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>得太大了</b></span></div><div class=\"fx-ex zh\">你把声音开得太大了。</div></div><p class=\"gr-key\">Ôn: 把(1) <span class=\"zh\">V + 在 / 到</span>　·　把(2) <span class=\"zh\">V + 给</span>　·　把(3) <span class=\"zh\">V + kết quả</span>　·　把(4) <span class=\"zh\">V + xu hướng / 得…</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我把饮料和酒都放进冰箱里了。</span> = Anh cho đồ uống và rượu vào tủ lạnh hết rồi.</p>","note":"<b>Lưu ý:</b> Phải có bổ ngữ chỉ hướng: ✗ <span class=\"zh\">我把饮料放冰箱了</span> → ✓ <span class=\"zh\">我把饮料放进冰箱里了</span>","examples":[{"zh":"你把声音开得太大了。","py":"Nǐ bǎ shēngyīn kāi de tài dà le.","vi":"Em mở âm thanh to quá rồi."},{"zh":"他把球踢进去了吗？","py":"Tā bǎ qiú tī jìnqu le ma?","vi":"Cậu ấy sút bóng vào lưới chưa?"},{"zh":"你把字写得太小了，我看不清楚。","py":"Nǐ bǎ zì xiě de tài xiǎo le, wǒ kàn bu qīngchu.","vi":"Bạn viết chữ nhỏ quá, mình nhìn không rõ."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">妈妈把房间____。</span><span class=\"qz-hint\">Mẹ dọn phòng rất sạch.</span>","answer":["打扫得很干净","打扫得干干净净","打扫干净了"],"explain":"妈妈把房间打扫得很干净。 (Māma bǎ fángjiān dǎsǎo de hěn gānjìng.)"},{"type":"fill","q":"<span class=\"zh\">现在天气太热了，你应该把这些东西____。</span><span class=\"qz-hint\">Bây giờ trời nóng quá, bạn nên cho mấy thứ này vào tủ lạnh.</span>","answer":["放进冰箱里","放进冰箱","放到冰箱里"],"explain":"现在天气太热了，你应该把这些东西放进冰箱里。 (Xiànzài tiānqì tài rè le, nǐ yīnggāi bǎ zhèxiē dōngxi fàngjìn bīngxiāng li.)"},{"type":"fill","q":"<span class=\"zh\">天气太冷了，你去把大衣____。</span><span class=\"qz-hint\">Trời lạnh quá, con đi lấy áo khoác lại đây.</span>","answer":["拿过来","拿来"],"explain":"天气太冷了，你去把大衣拿过来。 (Tiānqì tài lěng le, nǐ qù bǎ dàyī ná guòlai.)"}]},{"title":"（主语）+ 一边 + 动词₁，一边 + 动词₂ · 边……边……","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>(Chủ ngữ)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>一边</b><small>vừa</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>ĐT₁</b><small>hành động 1</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，一边</b><small>vừa</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>ĐT₂</b><small>hành động 2</small></span></div>","summary":"<p class=\"gr-lead\">Vừa … vừa …</p><ul><li>Hai <b>hành động</b> cùng một người làm <b>cùng lúc</b>: <span class=\"zh\">我喜欢一边跑步，一边听音乐</span>.</li><li>Rút gọn thành <span class=\"zh\">边……边……</span> (bỏ dấu phẩy): <span class=\"zh\">你不应该边开车边打电话</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">一边……，一边…… · 边……边……</span> · Hai dạng</h4><p>Vừa … vừa …</p><div class=\"gr-formula\"><div class=\"fx-lbl\">一边……，一边……</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>一边</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>吃蛋糕</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，一边</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>聊天儿</b></span></div><div class=\"fx-ex zh\">一边吃蛋糕，一边聊天儿。</div><div class=\"fx-lbl\">Có chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>一边</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>跑步</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，一边</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>听歌</b></span></div><div class=\"fx-ex zh\">我一边跑步，一边听歌。</div><div class=\"fx-lbl\">边……边……</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>边</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>开车</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>边</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>打电话</b></span></div><div class=\"fx-ex zh\">别边开车边打电话。</div></div><p class=\"gr-key\">Phân biệt: <span class=\"zh\">一边……一边……</span> + động từ (hai việc cùng lúc)　·　<span class=\"zh\">又……又……</span> (bài 2) + tính từ (hai đặc điểm)</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">咱们一边吃蛋糕，一边聊天儿吧。</span> = Mình vừa ăn bánh vừa trò chuyện nhé.</p>","note":"<b>Lưu ý:</b> Chỉ dùng với động từ, không dùng với tính từ: ✗ <span class=\"zh\">他一边高，一边瘦</span> → ✓ <span class=\"zh\">他又高又瘦</span>","examples":[{"zh":"咱们一边吃蛋糕，一边聊天儿吧。","py":"Zánmen yìbiān chī dàngāo, yìbiān liáotiānr ba.","vi":"Mình vừa ăn bánh vừa trò chuyện nhé."},{"zh":"我喜欢一边跑步，一边听音乐。","py":"Wǒ xǐhuan yìbiān pǎobù, yìbiān tīng yīnyuè.","vi":"Mình thích vừa chạy bộ vừa nghe nhạc."},{"zh":"你不应该边开车边打电话。","py":"Nǐ bù yīnggāi biān kāichē biān dǎ diànhuà.","vi":"Bạn không nên vừa lái xe vừa gọi điện."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">昨天你跟家月去哪儿了？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">去饭馆了，我们____，开心极了。</span></span></span><span class=\"qz-hint\">Hôm qua bạn với Gia Nguyệt đi đâu thế? — Đi nhà hàng, bọn mình vừa ăn vừa trò chuyện, vui cực.</span>","answer":["一边吃饭，一边聊天儿","一边吃饭一边聊天","一边吃一边聊"],"explain":"去饭馆了，我们一边吃饭，一边聊天儿，开心极了。 (Qù fànguǎn le, wǒmen yìbiān chī fàn, yìbiān liáotiānr, kāixīn jí le.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在饭馆","titleVi":"Nhà hàng — Đồng Lạc mời đồng nghiệp","lines":[{"speaker":"乐","name":"Đồng Lạc","zh":"今天我请客，你们想吃什么就点什么！","py":"Jīntiān wǒ qǐngkè, nǐmen xiǎng chī shénme jiù diǎn shénme!","vi":"Hôm nay em mời, mọi người muốn ăn gì cứ gọi nấy!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"那我就不客气了。听说这家饭馆的鱼做得很特别？","py":"Nà wǒ jiù bú kèqi le. Tīngshuō zhè jiā fànguǎn de yú zuò de hěn tèbié?","vi":"Vậy chị không khách sáo nhé. Nghe nói cá ở quán này làm rất đặc biệt?"},{"speaker":"乐","name":"Đồng Lạc","zh":"对，南方菜跟你们北方菜的做法不同。除了鱼，你们还想吃什么？","py":"Duì, nánfāng cài gēn nǐmen běifāng cài de zuòfǎ bù tóng. Chúle yú, nǐmen hái xiǎng chī shénme?","vi":"Đúng ạ, món miền Nam khác cách làm món miền Bắc. Ngoài cá, mọi người còn muốn ăn gì?"},{"speaker":"事","name":"Đồng nghiệp","zh":"我不常吃南方菜，还是你决定吧。","py":"Wǒ bù cháng chī nánfāng cài, háishi nǐ juédìng ba.","vi":"Tôi ít ăn món miền Nam, hay là cậu quyết đi."},{"speaker":"乐","name":"Đồng Lạc","zh":"好，那再加一个鸡肉，一个……","py":"Hǎo, nà zài jiā yí ge jīròu, yí ge……","vi":"Được, vậy thêm một món gà, một món…"},{"speaker":"雪","name":"Nhất Tuyết","zh":"咱们就三个人，别点那么多。","py":"Zánmen jiù sān ge rén, bié diǎn nàme duō.","vi":"Mình chỉ có ba người, đừng gọi nhiều thế."},{"speaker":"乐","name":"Đồng Lạc","zh":"好，那先来这几个菜。","py":"Hǎo, nà xiān lái zhè jǐ ge cài.","vi":"Vâng, vậy trước mắt gọi mấy món này."},{"speaker":"雪","name":"Nhất Tuyết","zh":"对了，下周我儿子过生日，你们有时间的话，就来我家做客，我给你们做北京菜。","py":"Duìle, xià zhōu wǒ érzi guò shēngrì, nǐmen yǒu shíjiān dehuà, jiù lái wǒ jiā zuòkè, wǒ gěi nǐmen zuò Běijīng cài.","vi":"À, tuần sau con trai chị sinh nhật, mọi người có thời gian thì đến nhà chị chơi, chị nấu món Bắc Kinh cho."}]},{"titleZh":"课文二 · 在家里","titleVi":"Ở nhà — chuẩn bị đón hàng xóm mới","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"第一次请新邻居来做客，总是担心有什么没准备好。","py":"Dì-yī cì qǐng xīn línjū lái zuòkè, zǒngshì dānxīn yǒu shénme méi zhǔnbèi hǎo.","vi":"Lần đầu mời hàng xóm mới đến chơi, em cứ lo có gì chưa chuẩn bị xong."},{"speaker":"明","name":"Lưu Minh","zh":"放心吧，我帮你看了，都已经准备好了。","py":"Fàngxīn ba, wǒ bāng nǐ kàn le, dōu yǐjīng zhǔnbèi hǎo le.","vi":"Yên tâm đi, anh xem giúp em rồi, chuẩn bị xong hết rồi."},{"speaker":"雪","name":"Nhất Tuyết","zh":"我记得刚才已经把饮料拿出来了，怎么不见了？","py":"Wǒ jìde gāngcái yǐjīng bǎ yǐnliào ná chūlai le, zěnme bú jiàn le?","vi":"Em nhớ vừa nãy đã lấy đồ uống ra rồi, sao không thấy đâu nữa?"},{"speaker":"明","name":"Lưu Minh","zh":"我把饮料和酒都放进冰箱里了，客人来了再拿出来。","py":"Wǒ bǎ yǐnliào hé jiǔ dōu fàngjìn bīngxiāng li le, kèrén láile zài ná chūlai.","vi":"Anh cho đồ uống và rượu vào tủ lạnh hết rồi, khách đến rồi hẵng lấy ra."},{"speaker":"雪","name":"Nhất Tuyết","zh":"音乐的声音合适吗？","py":"Yīnyuè de shēngyīn héshì ma?","vi":"Âm lượng nhạc vừa chưa anh?"},{"speaker":"明","name":"Lưu Minh","zh":"你把声音开得太大了，我去关小一点儿。","py":"Nǐ bǎ shēngyīn kāi de tài dà le, wǒ qù guān xiǎo yìdiǎnr.","vi":"Em mở to quá rồi, để anh vặn nhỏ lại chút."},{"speaker":"雪","name":"Nhất Tuyết","zh":"好，那我们就等客人来吧。","py":"Hǎo, nà wǒmen jiù děng kèrén lái ba.","vi":"Được, vậy mình chờ khách đến thôi."}]},{"titleZh":"课文三 · 在家里","titleVi":"Ở nhà — tiệc sinh nhật Tiểu Minh","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"谢谢你们来参加我儿子的生日晚会，希望大家今晚玩得开心。","py":"Xièxie nǐmen lái cānjiā wǒ érzi de shēngrì wǎnhuì, xīwàng dàjiā jīnwǎn wán de kāixīn.","vi":"Cảm ơn mọi người đến dự tiệc sinh nhật con trai tôi, mong tối nay mọi người chơi vui."},{"speaker":"乐","name":"Đồng Lạc","zh":"小明，生日快乐！我准备了一个小礼物，希望你喜欢！","py":"Xiǎomíng, shēngrì kuàilè! Wǒ zhǔnbèile yí ge xiǎo lǐwù, xīwàng nǐ xǐhuan!","vi":"Tiểu Minh, chúc mừng sinh nhật! Chú có món quà nhỏ, mong cháu thích!"},{"speaker":"弟","name":"Tiểu Minh","zh":"谢谢您，我可以打开吗？","py":"Xièxie nín, wǒ kěyǐ dǎkāi ma?","vi":"Cháu cảm ơn chú, cháu mở ra được không ạ?"},{"speaker":"乐","name":"Đồng Lạc","zh":"当然可以，你妈妈说你跟姐姐一样，都喜欢画画，对吗？","py":"Dāngrán kěyǐ, nǐ māma shuō nǐ gēn jiějie yíyàng, dōu xǐhuan huà huà, duì ma?","vi":"Tất nhiên rồi, mẹ cháu nói cháu cũng giống chị, đều thích vẽ tranh, đúng không?"},{"speaker":"弟","name":"Tiểu Minh","zh":"对，我想做一名画家。啊！画板和画笔，这正是我需要的。我太喜欢了。","py":"Duì, wǒ xiǎng zuò yì míng huàjiā. À! Huàbǎn hé huàbǐ, zhè zhèng shì wǒ xūyào de. Wǒ tài xǐhuan le.","vi":"Vâng, cháu muốn làm hoạ sĩ. A! Bảng vẽ và bút vẽ, đúng thứ cháu cần. Cháu thích lắm ạ."},{"speaker":"雪","name":"Nhất Tuyết","zh":"我去把盘子拿过来，咱们一边吃蛋糕，一边聊天儿吧。","py":"Wǒ qù bǎ pánzi ná guòlai, zánmen yìbiān chī dàngāo, yìbiān liáotiānr ba.","vi":"Để tôi đi lấy đĩa, mình vừa ăn bánh vừa trò chuyện nhé."}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — Nhất Tuyết viết nhật ký","para":true,"speaker":"雪","lines":[{"zh":"我的新邻居是来自英国的夫妻。","py":"Wǒ de xīn línjū shì láizì Yīngguó de fūqī.","vi":"Hàng xóm mới của tôi là một cặp vợ chồng đến từ Anh."},{"zh":"上周我去他们家做客了。","py":"Shàng zhōu wǒ qù tāmen jiā zuòkè le.","vi":"Tuần trước tôi sang nhà họ chơi."},{"zh":"他们做了很多好吃的，还准备了英国的红茶。","py":"Tāmen zuòle hěn duō hǎochī de, hái zhǔnbèile Yīngguó de hóngchá.","vi":"Họ nấu rất nhiều món ngon, còn chuẩn bị cả trà đen của Anh."},{"zh":"那天我跟他们一边喝红茶，一边聊天儿，直到十二点多才回家。","py":"Nà tiān wǒ gēn tāmen yìbiān hē hóngchá, yìbiān liáotiānr, zhídào shí'èr diǎn duō cái huí jiā.","vi":"Hôm đó tôi vừa uống trà vừa trò chuyện với họ, mãi đến hơn mười hai giờ mới về nhà."},{"zh":"他们年轻的时候喜欢旅游，他家有一张世界地图，上面每一个红点都是他们去过的地方。","py":"Tāmen niánqīng de shíhou xǐhuan lǚyóu, tā jiā yǒu yì zhāng shìjiè dìtú, shàngmian měi yí ge hóng diǎn dōu shì tāmen qùguo de dìfang.","vi":"Hồi trẻ họ thích du lịch, nhà họ có một tấm bản đồ thế giới, mỗi chấm đỏ trên đó là một nơi họ từng đến."},{"zh":"后来，他们感到东方的文化很特别，就开始学习中文。","py":"Hòulái, tāmen gǎndào dōngfāng de wénhuà hěn tèbié, jiù kāishǐ xuéxí Zhōngwén.","vi":"Về sau, họ thấy văn hoá phương Đông rất đặc biệt nên bắt đầu học tiếng Trung."},{"zh":"今天是小明的生日，我请他们到我家玩，来看看中国人的家，也尝尝中国菜。","py":"Jīntiān shì Xiǎomíng de shēngrì, wǒ qǐng tāmen dào wǒ jiā wán, lái kànkan Zhōngguórén de jiā, yě chángchang Zhōngguócài.","vi":"Hôm nay sinh nhật Tiểu Minh, tôi mời họ đến nhà chơi, xem nhà người Trung Quốc, cũng nếm thử món Trung Quốc."}]}]},"extra":[],"activity":{"act":[{"zh":"多人活动","py":"duōrén huódòng","tag":"Hoạt động nhóm","mean":"Thói quen đãi khách","q":{"zh":"四人一组，每人介绍自己家乡请客与做客的习惯。","py":"Sì rén yì zǔ, měi rén jièshào zìjǐ jiāxiāng qǐngkè yǔ zuòkè de xíguàn.","vi":"Nhóm 4 người: mỗi người giới thiệu thói quen mời khách và đi làm khách ở quê mình."},"items":[{"zh":"人们更喜欢怎么请客？（去饭馆吃饭、在家吃饭……）","py":"Rénmen gèng xǐhuan zěnme qǐngkè? (Qù fànguǎn chī fàn, zài jiā chī fàn……)","vi":"Mọi người thích mời khách thế nào hơn? (ra nhà hàng, ăn ở nhà…)"},{"zh":"去别人家做客，客人需要带礼物吗？常常带什么？","py":"Qù biérén jiā zuòkè, kèrén xūyào dài lǐwù ma? Chángcháng dài shénme?","vi":"Đến nhà người khác chơi, khách có cần mang quà không? Thường mang gì?"},{"zh":"做客的时候，常常吃什么？喝什么？","py":"Zuòkè de shíhou, chángcháng chī shénme? Hē shénme?","vi":"Khi làm khách, thường ăn gì? Uống gì?"},{"zh":"客人们除了吃饭，一般会做什么？（聊天儿、看电影……）","py":"Kèrénmen chúle chī fàn, yìbān huì zuò shénme? (Liáotiānr, kàn diànyǐng……)","vi":"Ngoài ăn uống, khách thường làm gì? (trò chuyện, xem phim…)"}]}],"speak":[]}},{"id":"k3v3-b14","courseId":"k3v3","order":14,"title":"Cuốn sách này bị người khác mượn mất rồi","titleZh":"这本书被别人借走了","titlePy":"zhè běn shū bèi biérén jièzǒu le","vocab":[{"stt":1,"hanzi":"词典","pinyin":"cídiǎn","hanviet":"Từ điển","pos":"Danh từ","meaning":"từ điển","comps":"汉语词典 (từ điển tiếng Trung), 一本词典 (một cuốn từ điển)","example":{"zh":"这本词典很有用，我每天都用。","py":"Zhè běn cídiǎn hěn yǒuyòng, wǒ měi tiān dōu yòng.","vi":"Cuốn từ điển này rất có ích, ngày nào mình cũng dùng."}},{"stt":2,"hanzi":"最好","pinyin":"zuìhǎo","hanviet":"Tối hảo","pos":"Phó từ","meaning":"tốt nhất là, nên","comps":"你最好… (tốt nhất bạn nên…), 最好别… (tốt nhất đừng…)","example":{"zh":"外面下雨了，你最好带上伞。","py":"Wàimiàn xià yǔ le, nǐ zuìhǎo dàishang sǎn.","vi":"Bên ngoài mưa rồi, tốt nhất bạn nên mang ô."}},{"stt":3,"hanzi":"节","pinyin":"jié","hanviet":"Tiết","pos":"Lượng từ","meaning":"tiết (học)","comps":"两节课 (hai tiết học), 一节课 (một tiết học)","example":{"zh":"今天上午我有四节课。","py":"Jīntiān shàngwǔ wǒ yǒu sì jié kè.","vi":"Sáng nay mình có bốn tiết học."}},{"stt":4,"hanzi":"图书馆","pinyin":"túshūguǎn","hanviet":"Đồ thư quán","pos":"Danh từ","meaning":"thư viện","comps":"去图书馆借书 (đến thư viện mượn sách), 学校图书馆 (thư viện trường)","example":{"zh":"周末我常常在图书馆看书。","py":"Zhōumò wǒ chángcháng zài túshūguǎn kàn shū.","vi":"Cuối tuần mình hay đọc sách ở thư viện."}},{"stt":5,"hanzi":"被","pinyin":"bèi","hanviet":"Bị","pos":"Giới từ","meaning":"bị, được (bị động)","comps":"被别人借走了 (bị người khác mượn mất), 被叫错名字 (bị gọi nhầm tên)","example":{"zh":"我的蛋糕被弟弟吃了。","py":"Wǒ de dàngāo bèi dìdi chī le.","vi":"Bánh ngọt của mình bị em trai ăn mất rồi."}},{"stt":6,"hanzi":"名人","pinyin":"míngrén","hanviet":"Danh nhân","pos":"Danh từ","meaning":"người nổi tiếng","comps":"名人的故事 (chuyện người nổi tiếng), 体育名人 (người nổi tiếng giới thể thao)","example":{"zh":"他是我们城市的名人，很多人都认识他。","py":"Tā shì wǒmen chéngshì de míngrén, hěn duō rén dōu rènshi tā.","vi":"Anh ấy là người nổi tiếng của thành phố mình, rất nhiều người biết anh ấy."}},{"stt":7,"hanzi":"故事","pinyin":"gùshi","hanviet":"Cố sự","pos":"Danh từ","meaning":"câu chuyện","comps":"讲故事 (kể chuyện), 一个故事 (một câu chuyện)","example":{"zh":"小时候，妈妈每天晚上都给我讲故事。","py":"Xiǎoshíhou, māma měi tiān wǎnshang dōu gěi wǒ jiǎng gùshi.","vi":"Hồi nhỏ, tối nào mẹ cũng kể chuyện cho mình nghe."}},{"stt":8,"hanzi":"然后","pinyin":"ránhòu","hanviet":"Nhiên hậu","pos":"Liên từ","meaning":"sau đó, rồi","comps":"先……，然后…… (trước…, sau đó…), 然后呢？ (rồi sao nữa?)","example":{"zh":"我们先去吃饭，然后去看电影。","py":"Wǒmen xiān qù chī fàn, ránhòu qù kàn diànyǐng.","vi":"Chúng mình đi ăn trước, sau đó đi xem phim."}},{"stt":9,"hanzi":"报纸","pinyin":"bàozhǐ","hanviet":"Báo chỉ","pos":"Danh từ","meaning":"báo (giấy)","comps":"看报纸 (đọc báo), 中文报纸 (báo tiếng Trung), 一张报纸 (một tờ báo)","example":{"zh":"爷爷每天早上都喝着茶看报纸。","py":"Yéye měi tiān zǎoshang dōu hēzhe chá kàn bàozhǐ.","vi":"Sáng nào ông cũng vừa uống trà vừa đọc báo."}},{"stt":10,"hanzi":"忘记","pinyin":"wàngjì","hanviet":"Vong ký","pos":"Động từ","meaning":"quên","comps":"忘记带 (quên mang), 别忘记 (đừng quên), 忘记了 (quên mất rồi)","example":{"zh":"我忘记带手机了，只能回家拿。","py":"Wǒ wàngjì dài shǒujī le, zhǐ néng huí jiā ná.","vi":"Mình quên mang điện thoại, đành phải về nhà lấy."}},{"stt":11,"hanzi":"电子书","pinyin":"diànzǐshū","hanviet":"Điện tử thư","pos":"Danh từ","meaning":"sách điện tử","comps":"看电子书 (đọc sách điện tử), 买电子书 (mua sách điện tử)","example":{"zh":"现在很多人喜欢在手机上看电子书。","py":"Xiànzài hěn duō rén xǐhuan zài shǒujī shang kàn diànzǐshū.","vi":"Bây giờ nhiều người thích đọc sách điện tử trên điện thoại."}},{"stt":12,"hanzi":"女生","pinyin":"nǚshēng","hanviet":"Nữ sinh","pos":"Danh từ","meaning":"bạn nữ, nữ sinh","comps":"几个女生 (mấy bạn nữ), 男生和女生 (nam sinh và nữ sinh)","example":{"zh":"我们班有十个男生，十二个女生。","py":"Wǒmen bān yǒu shí ge nánshēng, shí'èr ge nǚshēng.","vi":"Lớp mình có mười bạn nam, mười hai bạn nữ."}},{"stt":13,"hanzi":"表演","pinyin":"biǎoyǎn","hanviet":"Biểu diễn","pos":"Động từ","meaning":"biểu diễn","comps":"表演节目 (biểu diễn tiết mục), 看表演 (xem biểu diễn)","example":{"zh":"孩子们在晚会上表演得非常好。","py":"Háizimen zài wǎnhuì shang biǎoyǎn de fēicháng hǎo.","vi":"Bọn trẻ biểu diễn ở buổi liên hoan rất hay."}},{"stt":14,"hanzi":"节目","pinyin":"jiémù","hanviet":"Tiết mục","pos":"Danh từ","meaning":"tiết mục, chương trình","comps":"电视节目 (chương trình tivi), 表演节目 (biểu diễn tiết mục)","example":{"zh":"这个电视节目很有意思，我每周都看。","py":"Zhège diànshì jiémù hěn yǒu yìsi, wǒ měi zhōu dōu kàn.","vi":"Chương trình tivi này rất thú vị, tuần nào mình cũng xem."}},{"stt":15,"hanzi":"怎么办","pinyin":"zěnme bàn","hanviet":"Chẩm ma biện","pos":"Cụm từ","meaning":"làm thế nào, làm sao bây giờ","comps":"怎么办呢？ (làm sao đây?), 不知道怎么办 (không biết làm thế nào)","example":{"zh":"我的护照不见了，怎么办？","py":"Wǒ de hùzhào bú jiàn le, zěnme bàn?","vi":"Hộ chiếu của mình không thấy đâu, làm sao bây giờ?"}},{"stt":16,"hanzi":"校长","pinyin":"xiàozhǎng","hanviet":"Hiệu trưởng","pos":"Danh từ","meaning":"hiệu trưởng","comps":"王校长 (hiệu trưởng Vương), 我们学校的校长 (hiệu trưởng trường mình)","example":{"zh":"今天校长来我们班听课了。","py":"Jīntiān xiàozhǎng lái wǒmen bān tīngkè le.","vi":"Hôm nay thầy hiệu trưởng đến lớp mình dự giờ."}},{"stt":17,"hanzi":"面前","pinyin":"miànqián","hanviet":"Diện tiền","pos":"Danh từ","meaning":"trước mặt","comps":"在……面前 (trước mặt…), 在大家面前 (trước mặt mọi người)","example":{"zh":"我不习惯在很多人面前说话。","py":"Wǒ bù xíguàn zài hěn duō rén miànqián shuōhuà.","vi":"Mình không quen nói trước mặt nhiều người."}},{"stt":18,"hanzi":"有些","pinyin":"yǒuxiē","hanviet":"Hữu ta","pos":"Phó từ","meaning":"hơi, có phần","comps":"有些紧张 (hơi căng thẳng), 有些累 (hơi mệt)","example":{"zh":"今天天气有些冷，多穿点儿衣服吧。","py":"Jīntiān tiānqì yǒuxiē lěng, duō chuān diǎnr yīfu ba.","vi":"Hôm nay trời hơi lạnh, mặc thêm áo vào nhé."}},{"stt":19,"hanzi":"相信","pinyin":"xiāngxìn","hanviet":"Tương tín","pos":"Động từ","meaning":"tin, tin tưởng","comps":"相信自己 (tin vào bản thân), 我相信你 (mình tin bạn)","example":{"zh":"别紧张，我相信你一定能考好。","py":"Bié jǐnzhāng, wǒ xiāngxìn nǐ yídìng néng kǎohǎo.","vi":"Đừng căng thẳng, mình tin bạn nhất định thi tốt."}},{"stt":20,"hanzi":"新年","pinyin":"xīnnián","hanviet":"Tân niên","pos":"Danh từ","meaning":"năm mới","comps":"新年快乐 (chúc mừng năm mới), 新年晚会 (dạ hội năm mới)","example":{"zh":"新年快乐！祝你身体健康！","py":"Xīnnián kuàilè! Zhù nǐ shēntǐ jiànkāng!","vi":"Chúc mừng năm mới! Chúc bạn mạnh khoẻ!"}},{"stt":21,"hanzi":"班级","pinyin":"bānjí","hanviet":"Ban cấp","pos":"Danh từ","meaning":"lớp (học)","comps":"每个班级 (mỗi lớp), 班级活动 (hoạt động của lớp)","example":{"zh":"我们学校一共有二十个班级。","py":"Wǒmen xuéxiào yígòng yǒu èrshí ge bānjí.","vi":"Trường mình có tổng cộng hai mươi lớp."}},{"stt":22,"hanzi":"跳","pinyin":"tiào","hanviet":"Khiêu","pos":"Động từ","meaning":"nhảy","comps":"跳舞 (nhảy múa), 又唱又跳 (vừa hát vừa nhảy)","example":{"zh":"听到这个好消息，他高兴得跳了起来。","py":"Tīngdào zhège hǎo xiāoxi, tā gāoxìng de tiàole qǐlai.","vi":"Nghe tin vui này, cậu ấy mừng đến mức nhảy cẫng lên."}},{"stt":23,"hanzi":"留学生","pinyin":"liúxuéshēng","hanviet":"Lưu học sinh","pos":"Danh từ","meaning":"du học sinh","comps":"外国留学生 (du học sinh nước ngoài), 中国留学生 (du học sinh Trung Quốc)","example":{"zh":"我们学校有很多外国留学生。","py":"Wǒmen xuéxiào yǒu hěn duō wàiguó liúxuéshēng.","vi":"Trường mình có rất nhiều du học sinh nước ngoài."}},{"stt":24,"hanzi":"最后","pinyin":"zuìhòu","hanviet":"Tối hậu","pos":"Danh từ","meaning":"cuối cùng","comps":"最后一天 (ngày cuối cùng), 最后一个 (người cuối cùng)","example":{"zh":"他每天都是最后一个到教室的。","py":"Tā měi tiān dōu shì zuìhòu yí ge dào jiàoshì de.","vi":"Ngày nào cậu ấy cũng là người cuối cùng đến lớp."}},{"stt":25,"hanzi":"一块儿","pinyin":"yíkuàir","hanviet":"Nhất khối nhi","pos":"Phó từ / Danh từ","meaning":"cùng nhau; cùng chỗ","comps":"一块儿去 (cùng đi), 在一块儿 (ở cùng nhau)","example":{"zh":"周末我们一块儿去爬山吧。","py":"Zhōumò wǒmen yíkuàir qù páshān ba.","vi":"Cuối tuần mình cùng đi leo núi nhé."}},{"stt":26,"hanzi":"网站","pinyin":"wǎngzhàn","hanviet":"Võng trạm","pos":"Danh từ","meaning":"trang web","comps":"学校网站 (trang web của trường), 在网站上 (trên trang web)","example":{"zh":"考试时间可以在学校的网站上找到。","py":"Kǎoshì shíjiān kěyǐ zài xuéxiào de wǎngzhàn shang zhǎodào.","vi":"Lịch thi có thể tìm thấy trên trang web của trường."}},{"stt":27,"hanzi":"视频","pinyin":"shìpín","hanviet":"Thị tần","pos":"Danh từ","meaning":"video","comps":"看视频 (xem video), 拍视频 (quay video)","example":{"zh":"晚上我常常在手机上看视频。","py":"Wǎnshang wǒ chángcháng zài shǒujī shang kàn shìpín.","vi":"Buổi tối mình hay xem video trên điện thoại."}}],"hanzi":[{"char":"词典","pinyin":"cídiǎn","hanviet":"Từ điển","chars":["词","典"],"story":"词 = 讠 (lời nói) + 司 → từ ngữ (生词 = từ mới). 典 = sách quý đặt trên giá → sách chuẩn để tra. 词典 = sách tra từ → từ điển (Hán Việt: Từ điển)."},{"char":"最好","pinyin":"zuìhǎo","hanviet":"Tối hảo","chars":["最","好"],"story":"最 = nhất; 好 = tốt. Trước động từ, 最好 = tốt nhất là…, nên…: 你最好今天还书. Còn 最好的 + danh từ = … tốt nhất: 最好的朋友 (bạn thân nhất)."},{"char":"节","pinyin":"jié","hanviet":"Tiết","chars":["节"],"story":"节 = ⺮ / 艹 (tre) + 卩 → đốt tre, từng đoạn một → từng tiết học: 两节课. Bài 18 sẽ học 节 với nghĩa khác (ngày lễ, tết)."},{"char":"图书馆","pinyin":"túshūguǎn","hanviet":"Đồ thư quán","chars":["图","书","馆"],"story":"图 = tranh, hình; 书 = sách; 馆 = 饣 + 官 → toà nhà lớn (宾馆, 体育馆). 图书馆 = toà nhà chứa tranh và sách → thư viện (Đồ thư quán)."},{"char":"被","pinyin":"bèi","hanviet":"Bị","chars":["被"],"story":"被 = 衤 (áo) + 皮 (da) → tấm chăn phủ lên người (被子). Bị phủ lên → chịu tác động → 被 = bị. Đặt trước người gây ra hành động: 被别人借走了."},{"char":"名人","pinyin":"míngrén","hanviet":"Danh nhân","chars":["名","人"],"story":"名 = 夕 (đêm tối) + 口 → trời tối phải gọi tên để nhận ra nhau → tên, danh tiếng. 名人 = người có tiếng tăm → người nổi tiếng (Danh nhân)."},{"char":"故事","pinyin":"gùshi","hanviet":"Cố sự","chars":["故","事"],"story":"故 = 古 (xưa) + 攵 → chuyện ngày xưa. 事 = sự việc. 故事 = chuyện đã xảy ra → câu chuyện. 事 đọc nhẹ: gùshi. Kể chuyện = 讲故事."},{"char":"然后","pinyin":"ránhòu","hanviet":"Nhiên hậu","chars":["然","后"],"story":"然 = như thế; 后 = sau. 然后 = sau khi như thế → sau đó, rồi. Đứng đầu vế sau, trước chủ ngữ: 我先吃饭，然后我们去看电影."},{"char":"报纸","pinyin":"bàozhǐ","hanviet":"Báo chỉ","chars":["报","纸"],"story":"报 = 扌 (tay) + 艮 → báo tin. 纸 = 纟 (tơ) + 氏 → giấy (bài 3). 报纸 = tờ giấy báo tin → báo giấy. Lượng từ: 一张报纸, 一份报纸."},{"char":"忘记","pinyin":"wàngjì","hanviet":"Vong ký","chars":["忘","记"],"story":"忘 = 亡 (mất) + 心 (lòng) → mất khỏi lòng → quên. 记 = ghi nhớ (bài 2). 忘记 = quên (Vong ký) — khẩu ngữ hay nói 忘了: 我忘了带手机."},{"char":"电子书","pinyin":"diànzǐshū","hanviet":"Điện tử thư","chars":["电","子","书"],"story":"电 = điện; 子 = hậu tố; 电子 = điện tử. 书 = sách. 电子书 = sách điện tử, đọc trên điện thoại / máy tính. Cùng nhóm: 电子邮件 (email)."},{"char":"女生","pinyin":"nǚshēng","hanviet":"Nữ sinh","chars":["女","生"],"story":"女 = hình người phụ nữ ngồi khoanh tay. 生 = học sinh (学生). 女生 = học sinh nữ, bạn nữ. Cặp với 男生 (bài 9)."},{"char":"表演","pinyin":"biǎoyǎn","hanviet":"Biểu diễn","chars":["表","演"],"story":"表 = bày ra bên ngoài (表示). 演 = 氵 + 寅 → diễn, trình diễn (演员). 表演 = bày ra cho người xem → biểu diễn: 表演节目, 表演跳舞."},{"char":"节目","pinyin":"jiémù","hanviet":"Tiết mục","chars":["节","目"],"story":"节 = tiết, từng đoạn (两节课 — buổi trước). 目 = con mắt → mục, khoản. 节目 = từng mục trong chương trình → tiết mục, chương trình (电视节目)."},{"char":"怎么办","pinyin":"zěnme bàn","hanviet":"Chẩm ma biện","chars":["怎","么","办"],"story":"怎么 = thế nào; 办 = làm, giải quyết (办信用卡 — bài 3). 怎么办 = làm thế nào bây giờ? Dùng khi gặp khó: 找不到人，怎么办?"},{"char":"校长","pinyin":"xiàozhǎng","hanviet":"Hiệu trưởng","chars":["校","长"],"story":"校 = 木 + 交 → trường học (学校). 长 đọc zhǎng = người đứng đầu (≠ cháng dài). 校长 = người đứng đầu trường → hiệu trưởng."},{"char":"面前","pinyin":"miànqián","hanviet":"Diện tiền","chars":["面","前"],"story":"面 = khuôn mặt; 前 = phía trước. 面前 = phía trước mặt. Mẫu quen dùng: 在 + người + 面前: 在校长、老师和同学面前."},{"char":"有些","pinyin":"yǒuxiē","hanviet":"Hữu ta","chars":["有","些"],"story":"有些 + tính từ = hơi…, có phần… ≈ 有点儿: 有些紧张. Phân biệt: 有些 + danh từ = có một số…: 有些人, 有些书 (đại từ)."},{"char":"相信","pinyin":"xiāngxìn","hanviet":"Tương tín","chars":["相","信"],"story":"相 = qua lại, lẫn nhau; 信 = 亻 + 言 → lời người nói ra phải giữ → tin. 相信 = tin tưởng: 相信自己 (tin vào chính mình)."},{"char":"新年","pinyin":"xīnnián","hanviet":"Tân niên","chars":["新","年"],"story":"新 = mới; 年 = năm. 新年 = năm mới (Tân niên) — ngày 1/1 dương lịch. Tết âm lịch gọi là 春节 (bài 18). Lời chúc: 新年快乐!"},{"char":"班级","pinyin":"bānjí","hanviet":"Ban cấp","chars":["班","级"],"story":"班 = 王 + 刂 + 王 → chia ngọc thành từng phần → nhóm, lớp. 级 = cấp, khối (年级 — bài 10). 班级 = các lớp học nói chung, trang trọng hơn 班."},{"char":"跳","pinyin":"tiào","hanviet":"Khiêu","chars":["跳"],"story":"跳 = 足 (chân) + 兆 → bật chân lên → nhảy. 跳舞 = nhảy múa; 跳起来 = nhảy cẫng lên. Bài khoá: 又唱又跳 = vừa hát vừa nhảy."},{"char":"留学生","pinyin":"liúxuéshēng","hanviet":"Lưu học sinh","chars":["留","学","生"],"story":"留 = ở lại; 学 = học; 生 = học sinh. 留学生 = người ở lại nước ngoài để học → du học sinh (Lưu học sinh). 留学 = đi du học."},{"char":"最后","pinyin":"zuìhòu","hanviet":"Tối hậu","chars":["最","后"],"story":"最 = nhất; 后 = sau. 最后 = sau cùng, cuối cùng. Phân biệt: 然后 = sau đó (nối việc trước – sau) · 最后 = cuối cùng (việc sau hết)."},{"char":"一块儿","pinyin":"yíkuàir","hanviet":"Nhất khối nhi","chars":["一","块","儿"],"story":"块 = khối, miếng; 一块儿 = cùng một khối → cùng nhau, cùng chỗ ≈ 一起 (khẩu ngữ, có âm 儿): 一块儿跳, 在一块儿. Đọc yíkuàir."},{"char":"网站","pinyin":"wǎngzhàn","hanviet":"Võng trạm","chars":["网","站"],"story":"网 = lưới → mạng (上网). 站 = trạm, đứng (车站, bài 1). 网站 = trạm trên mạng → trang web: 学校的网站."},{"char":"视频","pinyin":"shìpín","hanviet":"Thị tần","chars":["视","频"],"story":"视 = 礻 + 见 (thấy) → nhìn (电视). 频 = tần số. 视频 = tín hiệu hình ảnh → video: 看视频, 拍视频, 晚会的视频."}],"grammar":[{"title":"主语 + 被 +（宾语）+ 动词 + 其他成分","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>Chủ ngữ</b><small>người / vật chịu tác động</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>被</b><small>bị</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>(Tân ngữ)</b><small>người gây ra</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>Động từ</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>Thành phần khác</b><small>了 / bổ ngữ</small></span></div>","summary":"<p class=\"gr-lead\">Bị … (bởi ai đó)</p><ul><li>Nhấn mạnh chủ ngữ <b>chịu tác động</b>, thường là chuyện không vui; người gây ra có thể lược: <span class=\"zh\">我们俩经常被叫错名字</span>.</li><li>Phó từ, động từ năng nguyện đứng <b>trước 被</b>: <span class=\"zh\">水果可能被弟弟吃了</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">被 · bốn dạng câu</span> · Cấu trúc</h4><p>Bị … (bởi ai đó)</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Có người gây ra</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>这本书</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>被</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>别人</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>借</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>走了</b></span></div><div class=\"fx-ex zh\">这本书被别人借走了。</div><div class=\"fx-lbl\">Lược người gây ra</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>我的蛋糕</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>被</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>吃</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b></span></div><div class=\"fx-ex zh\">我的蛋糕被吃了。</div><div class=\"fx-lbl\">Phó từ / NNĐT + 被</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>水果</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>可能被</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>弟弟</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>吃</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b></span></div><div class=\"fx-ex zh\">水果可能被弟弟吃了。</div><div class=\"fx-lbl\">Đối chiếu 把</div><div class=\"fx-row\"><span class=\"fx-p c-b\"><b>弟弟</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>把</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>水果</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>吃</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b></span></div><div class=\"fx-ex zh\">弟弟把水果吃了。</div></div><p class=\"gr-key\"><span class=\"zh\">把</span>: người làm đứng đầu câu　·　<span class=\"zh\">被</span>: người / vật chịu tác động đứng đầu câu</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">这本书被别人借走了。</span> = Cuốn sách này bị người khác mượn mất rồi.</p>","note":"<b>Lưu ý:</b> Sau động từ phải có thành phần khác: ✗ <span class=\"zh\">书被别人借</span> → ✓ <span class=\"zh\">书被别人借走了</span>","examples":[{"zh":"这本书被别人借走了。","py":"Zhè běn shū bèi biérén jièzǒu le.","vi":"Cuốn sách này bị người khác mượn mất rồi."},{"zh":"水果可能被弟弟吃了。","py":"Shuǐguǒ kěnéng bèi dìdi chī le.","vi":"Hoa quả có lẽ bị em trai ăn rồi."},{"zh":"我们俩经常被叫错名字。","py":"Wǒmen liǎ jīngcháng bèi jiàocuò míngzi.","vi":"Hai đứa mình hay bị gọi nhầm tên."}],"exercises":[]},{"title":"（主语）+ 先 + 动词₁，再 / 然后（再）+ 动词₂","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>(Chủ ngữ)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>先</b><small>trước</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>ĐT₁</b><small>việc làm trước</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，再 / 然后</b><small>rồi / sau đó</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>ĐT₂</b><small>việc làm sau</small></span></div>","summary":"<p class=\"gr-lead\">Trước …, rồi / sau đó …</p><ul><li><span class=\"zh\">再</span> là phó từ, đứng <b>sau chủ ngữ</b>, trước động từ; <span class=\"zh\">然后</span> là liên từ, đứng <b>đầu vế sau</b>.</li><li>Có thể nói <span class=\"zh\">然后再</span>: <span class=\"zh\">你们先回房间休息一会儿，然后再出来吃晚饭</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">先……，再/然后……</span> · Ba dạng</h4><p>Trước …, rồi …</p><div class=\"gr-formula\"><div class=\"fx-lbl\">先……，再……</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>先</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>买门票</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，再</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>来找我</b></span></div><div class=\"fx-ex zh\">你先去买门票，再来这里找我。</div><div class=\"fx-lbl\">先……，然后……</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>先</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>借书</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，然后</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>去游泳</b></span></div><div class=\"fx-ex zh\">我先去图书馆借书，然后去游泳。</div><div class=\"fx-lbl\">先……，然后再……</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>先</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>休息</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，然后再</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>吃晚饭</b></span></div><div class=\"fx-ex zh\">先休息一会儿，然后再吃晚饭。</div></div><p class=\"gr-key\">Ở đây <span class=\"zh\">再</span> = rồi (mới), không phải \"lại\"　·　hai chủ ngữ khác nhau → dùng <span class=\"zh\">然后</span>: <span class=\"zh\">我先说，然后你说</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我要先去图书馆借书，然后去游泳。</span> = Mình phải ra thư viện mượn sách trước, sau đó đi bơi.</p>","note":"<b>Lưu ý:</b> 再 không đứng trước chủ ngữ: ✗ <span class=\"zh\">我先吃饭，再我去学校</span> → ✓ <span class=\"zh\">我先吃饭，再去学校</span>","examples":[{"zh":"我要先去图书馆借书，然后去游泳。","py":"Wǒ yào xiān qù túshūguǎn jiè shū, ránhòu qù yóuyǒng.","vi":"Mình phải ra thư viện mượn sách trước, sau đó đi bơi."},{"zh":"你先去买门票，再来这里找我。","py":"Nǐ xiān qù mǎi ménpiào, zài lái zhèlǐ zhǎo wǒ.","vi":"Bạn đi mua vé vào cửa trước, rồi đến đây tìm mình."},{"zh":"你们先回房间休息一会儿，然后再出来吃晚饭。","py":"Nǐmen xiān huí fángjiān xiūxi yíhuìr, ránhòu zài chūlai chī wǎnfàn.","vi":"Các bạn về phòng nghỉ một lát trước, sau đó hẵng ra ăn tối."}],"exercises":[]},{"title":"动词 / 形容词 + 什么（啊）","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>ĐT / TT</b><small>điều đối phương vừa nói</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>什么</b><small>… gì mà</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>(啊)</b><small>giọng nói</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>，lý do / lời khuyên</b><small>vì sao không cần</small></span></div>","summary":"<p class=\"gr-lead\">… gì mà …, … gì chứ</p><ul><li>Lặp lại <b>ĐT / TT</b> đối phương vừa nói + <span class=\"zh\">什么啊</span> → \"có gì mà phải…\": <span class=\"zh\">急什么啊</span>.</li><li>Sau đó thường nói <b>lý do</b> hoặc <b>lời khuyên</b>: <span class=\"zh\">胖什么啊，你看起来不胖也不瘦</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">×什么（啊）</span> · Ba sắc thái</h4><p>Phản bác · an ủi</p><div class=\"gr-formula\"><div class=\"fx-lbl\">TT · phản bác</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>胖</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>什么啊</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>，你不胖</b></span></div><div class=\"fx-ex zh\">胖什么啊，你看起来不胖也不瘦。</div><div class=\"fx-lbl\">ĐT · trấn an</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>急</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>什么啊</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>，马上就到了</b></span></div><div class=\"fx-ex zh\">急什么啊，马上就到了。</div><div class=\"fx-lbl\">ĐT · động viên</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>紧张</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>什么啊</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>，相信自己</b></span></div><div class=\"fx-ex zh\">紧张什么啊，你要相信自己。</div></div><p class=\"gr-key\"><span class=\"zh\">什么</span> đọc nhẹ, nhấn vào ĐT / TT phía trước　·　dùng với bạn bè, người thân — không dùng với người trên</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">紧张什么啊，我们都喜欢听你唱歌。</span> = Căng thẳng gì chứ, bọn mình đều thích nghe bạn hát mà.</p>","note":"<b>Lưu ý:</b> Không phải câu hỏi, không thêm 吗: ✗ <span class=\"zh\">紧张什么吗？</span> → ✓ <span class=\"zh\">紧张什么啊！</span>","examples":[],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这个地方太远了，走过去要很久。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____，走路十几分钟就到了。</span></span></span><span class=\"qz-hint\">Chỗ này xa quá, đi bộ qua mất lâu lắm. — Xa gì mà xa, đi bộ mười mấy phút là tới.</span>","answer":["远什么啊","远什么"],"explain":"远什么啊，走路十几分钟就到了。 (Yuǎn shénme a, zǒulù shí jǐ fēnzhōng jiù dào le.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这家饭馆的菜挺贵的，咱们换一家吧。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____，今天你生日，想吃什么就吃什么。</span></span></span><span class=\"qz-hint\">Món ở quán này khá đắt, mình đổi quán khác đi. — Đắt gì chứ, hôm nay sinh nhật bạn, muốn ăn gì cứ ăn.</span>","answer":["贵什么啊","贵什么"],"explain":"贵什么啊，今天你生日，想吃什么就吃什么。 (Guì shénme a, jīntiān nǐ shēngrì, xiǎng chī shénme jiù chī shénme.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">明天就要考试了，我好紧张。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____，我们都相信你。</span></span></span><span class=\"qz-hint\">Mai thi rồi, mình căng thẳng quá. — Căng thẳng gì chứ, bọn mình đều tin bạn mà.</span>","answer":["紧张什么啊","紧张什么"],"explain":"紧张什么啊，我们都相信你。 (Jǐnzhāng shénme a, wǒmen dōu xiāngxìn nǐ.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在校园餐厅","titleVi":"Căng tin trường — nhờ bạn trả sách giúp","lines":[{"speaker":"文","name":"Lý Văn","zh":"我借的这本词典最好今天还，但是我没时间去。","py":"Wǒ jiè de zhè běn cídiǎn zuìhǎo jīntiān huán, dànshì wǒ méi shíjiān qù.","vi":"Cuốn từ điển mình mượn tốt nhất là trả trong hôm nay, nhưng mình không có thời gian đi."},{"speaker":"月","name":"Gia Nguyệt","zh":"下午我只有两节课，可以帮你去图书馆还书。","py":"Xiàwǔ wǒ zhǐ yǒu liǎng jié kè, kěyǐ bāng nǐ qù túshūguǎn huán shū.","vi":"Chiều mình chỉ có hai tiết, có thể ra thư viện trả sách giúp bạn."},{"speaker":"文","name":"Lý Văn","zh":"那太谢谢了。你能再帮我借本书吗？","py":"Nà tài xièxie le. Nǐ néng zài bāng wǒ jiè běn shū ma?","vi":"Vậy cảm ơn bạn nhiều. Bạn mượn giúp mình thêm một cuốn sách được không?"},{"speaker":"月","name":"Gia Nguyệt","zh":"行，你告诉我书名。","py":"Xíng, nǐ gàosu wǒ shūmíng.","vi":"Được, bạn cho mình biết tên sách."},{"speaker":"文","name":"Lý Văn","zh":"我把名字写在纸上吧。我去了好几次图书馆，这本书都被别人借走了。","py":"Wǒ bǎ míngzi xiě zài zhǐ shang ba. Wǒ qùle hǎo jǐ cì túshūguǎn, zhè běn shū dōu bèi biérén jièzǒu le.","vi":"Để mình viết tên ra giấy. Mình đến thư viện mấy lần rồi, lần nào cuốn này cũng bị người khác mượn mất."},{"speaker":"月","name":"Gia Nguyệt","zh":"《名人的故事》？我有这本书。明天我借给你吧。","py":"《Míngrén de Gùshi》? Wǒ yǒu zhè běn shū. Míngtiān wǒ jiè gěi nǐ ba.","vi":"\"Chuyện người nổi tiếng\"? Mình có cuốn này. Mai mình cho bạn mượn nhé."}]},{"titleZh":"课文二 · 在校园里","titleVi":"Sân trường — thẻ trường không thấy đâu","lines":[{"speaker":"妮","name":"Annie","zh":"今天下课早，你一会儿做什么？","py":"Jīntiān xiàkè zǎo, nǐ yíhuìr zuò shénme?","vi":"Hôm nay tan học sớm, lát nữa cậu làm gì?"},{"speaker":"月","name":"Gia Nguyệt","zh":"我今天忙得很，要先去图书馆借书，然后去游泳。","py":"Wǒ jīntiān máng de hěn, yào xiān qù túshūguǎn jiè shū, ránhòu qù yóuyǒng.","vi":"Hôm nay mình bận lắm, phải ra thư viện mượn sách trước, sau đó đi bơi."},{"speaker":"妮","name":"Annie","zh":"咱们一起走吧，我想去图书馆看看中文报纸。","py":"Zánmen yìqǐ zǒu ba, wǒ xiǎng qù túshūguǎn kànkan Zhōngwén bàozhǐ.","vi":"Mình đi cùng nhau đi, mình muốn ra thư viện đọc báo tiếng Trung."},{"speaker":"月","name":"Gia Nguyệt","zh":"等等，我的校园卡不见了，没有卡进不去图书馆。","py":"Děngdeng, wǒ de xiàoyuánkǎ bú jiàn le, méiyǒu kǎ jìn bu qù túshūguǎn.","vi":"Khoan đã, thẻ trường của mình không thấy đâu, không có thẻ thì không vào thư viện được."},{"speaker":"妮","name":"Annie","zh":"你想想上一次用是什么时候？","py":"Nǐ xiǎngxiang shàng yí cì yòng shì shénme shíhou?","vi":"Cậu nghĩ xem lần trước dùng là lúc nào?"},{"speaker":"月","name":"Gia Nguyệt","zh":"我忘记了，可能被我放在家里了。","py":"Wǒ wàngjì le, kěnéng bèi wǒ fàng zài jiāli le.","vi":"Mình quên mất rồi, có lẽ bị mình để ở nhà rồi."},{"speaker":"妮","name":"Annie","zh":"进不去图书馆也没关系，上网看看有没有电子书。","py":"Jìn bu qù túshūguǎn yě méi guānxi, shàngwǎng kànkan yǒu méiyǒu diànzǐshū.","vi":"Không vào được thư viện cũng không sao, lên mạng xem có sách điện tử không."},{"speaker":"月","name":"Gia Nguyệt","zh":"不行，我必须去，我还得帮李文还书呢。","py":"Bù xíng, wǒ bìxū qù, wǒ hái děi bāng Lǐ Wén huán shū ne.","vi":"Không được, mình phải đi, mình còn phải trả sách giúp Lý Văn nữa."}]},{"titleZh":"课文三 · 在校园餐厅","titleVi":"Căng tin — chuyện dạ hội tuần sau","lines":[{"speaker":"文","name":"Lý Văn","zh":"下周学校有晚会，你知道吗？","py":"Xià zhōu xuéxiào yǒu wǎnhuì, nǐ zhīdào ma?","vi":"Tuần sau trường có dạ hội, bạn biết không?"},{"speaker":"月","name":"Gia Nguyệt","zh":"知道，我和几个女生要表演一个节目。你也参加吗？","py":"Zhīdào, wǒ hé jǐ ge nǚshēng yào biǎoyǎn yí ge jiémù. Nǐ yě cānjiā ma?","vi":"Biết chứ, mình với mấy bạn nữ sẽ biểu diễn một tiết mục. Bạn cũng tham gia à?"},{"speaker":"文","name":"Lý Văn","zh":"我想唱中文歌，但是还没找到人一起表演，不知道怎么办。","py":"Wǒ xiǎng chàng Zhōngwén gē, dànshì hái méi zhǎodào rén yìqǐ biǎoyǎn, bù zhīdào zěnme bàn.","vi":"Mình muốn hát bài tiếng Trung, nhưng chưa tìm được người biểu diễn cùng, không biết làm sao."},{"speaker":"月","name":"Gia Nguyệt","zh":"找不到人，你就一个人唱吧。","py":"Zhǎo bu dào rén, nǐ jiù yí ge rén chàng ba.","vi":"Không tìm được người thì bạn hát một mình đi."},{"speaker":"文","name":"Lý Văn","zh":"一想到要在校长、老师和那么多同学面前表演，我就有些紧张。","py":"Yì xiǎngdào yào zài xiàozhǎng, lǎoshī hé nàme duō tóngxué miànqián biǎoyǎn, wǒ jiù yǒuxiē jǐnzhāng.","vi":"Cứ nghĩ đến việc biểu diễn trước mặt hiệu trưởng, thầy cô và bao nhiêu bạn học là mình lại hơi căng thẳng."},{"speaker":"月","name":"Gia Nguyệt","zh":"紧张什么啊，我们都喜欢听你唱歌，你要相信自己。","py":"Jǐnzhāng shénme a, wǒmen dōu xǐhuan tīng nǐ chàng gē, nǐ yào xiāngxìn zìjǐ.","vi":"Căng thẳng gì chứ, bọn mình đều thích nghe bạn hát mà, bạn phải tin vào bản thân."}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — Gia Nguyệt viết nhật ký","para":true,"speaker":"月","lines":[{"zh":"昨天是我们学校的新年晚会，每个班级的同学都表演节目了。","py":"Zuótiān shì wǒmen xuéxiào de xīnnián wǎnhuì, měi ge bānjí de tóngxué dōu biǎoyǎn jiémù le.","vi":"Hôm qua là dạ hội mừng năm mới của trường, học sinh lớp nào cũng biểu diễn tiết mục."},{"zh":"晚会是八点开始的，差不多十二点才结束。","py":"Wǎnhuì shì bā diǎn kāishǐ de, chàbuduō shí'èr diǎn cái jiéshù.","vi":"Dạ hội bắt đầu lúc tám giờ, gần mười hai giờ mới kết thúc."},{"zh":"我一个晚上跟大家一起又唱又跳，开心极了，也累坏了。","py":"Wǒ yí ge wǎnshang gēn dàjiā yìqǐ yòu chàng yòu tiào, kāixīn jí le, yě lèi huài le.","vi":"Cả buổi tối tôi vừa hát vừa nhảy cùng mọi người, vui cực kỳ, cũng mệt rã rời."},{"zh":"我最喜欢的节目是留学生们跳舞，最后老师和校长也被叫起来一块儿跳，特别有意思。","py":"Wǒ zuì xǐhuan de jiémù shì liúxuéshēngmen tiàowǔ, zuìhòu lǎoshī hé xiàozhǎng yě bèi jiào qǐlai yíkuàir tiào, tèbié yǒu yìsi.","vi":"Tiết mục tôi thích nhất là các du học sinh nhảy múa, cuối cùng thầy cô và hiệu trưởng cũng bị kéo lên nhảy cùng, thú vị vô cùng."},{"zh":"过几天学校的网站上会有晚会的视频，我打算再看一遍。","py":"Guò jǐ tiān xuéxiào de wǎngzhàn shang huì yǒu wǎnhuì de shìpín, wǒ dǎsuàn zài kàn yí biàn.","vi":"Vài hôm nữa trên trang web của trường sẽ có video dạ hội, tôi định xem lại một lượt."}]}]},"extra":[],"activity":{"act":[{"zh":"猜猜发生了什么","py":"cāicai fāshēngle shénme","tag":"Trò chơi câu 被","mean":"Lượt 1 · Đoán chuyện xui xẻo","q":{"zh":"听句子，猜猜什么东西出了问题。","py":"Tīng jùzi, cāicai shénme dōngxi chūle wèntí.","vi":"Nghe câu, đoán xem đồ vật nào gặp chuyện."},"banks":[{"lbl":"Các đáp án","items":[{"zh":"🚲 自行车","py":"zìxíngchē","vi":"xe đạp"},{"zh":"🎂 蛋糕","py":"dàngāo","vi":"bánh ngọt"},{"zh":"📖 词典","py":"cídiǎn","vi":"từ điển"},{"zh":"🪪 校园卡","py":"xiàoyuánkǎ","vi":"thẻ trường"},{"zh":"☂️ 伞","py":"sǎn","vi":"cái ô"},{"zh":"📱 手机","py":"shǒujī","vi":"điện thoại"}]}],"items":[{"zh":"这本书被别人借走了。","py":"Zhè běn shū bèi biérén jièzǒu le.","vi":"Cuốn sách này bị người khác mượn mất rồi."},{"lines":[{"who":"1","zh":"我每天都用它去学校，比走路快多了。","py":"Wǒ měi tiān dōu yòng tā qù xuéxiào, bǐ zǒulù kuài duō le.","vi":"Ngày nào mình cũng dùng nó đến trường, nhanh hơn đi bộ nhiều."},{"who":"2","zh":"昨天晚上我把它放在楼下了。","py":"Zuótiān wǎnshang wǒ bǎ tā fàng zài lóu xià le.","vi":"Tối qua mình để nó dưới lầu."},{"who":"3","zh":"今天早上它不见了，可能被别人骑走了。","py":"Jīntiān zǎoshang tā bú jiàn le, kěnéng bèi biérén qízǒu le.","vi":"Sáng nay nó biến mất, có lẽ bị người khác đạp đi rồi."},{"who":"✓","zh":"自行车","py":"zìxíngchē","vi":"xe đạp"}]},{"lines":[{"who":"1","zh":"这是妈妈给我买的，我想过生日的时候吃。","py":"Zhè shì māma gěi wǒ mǎi de, wǒ xiǎng guò shēngrì de shíhou chī.","vi":"Đây là mẹ mua cho mình, mình định để sinh nhật ăn."},{"who":"2","zh":"我把它放进冰箱里了。","py":"Wǒ bǎ tā fàngjìn bīngxiāng li le.","vi":"Mình cho nó vào tủ lạnh rồi."},{"who":"3","zh":"我回家一看，它已经被弟弟吃完了！","py":"Wǒ huí jiā yí kàn, tā yǐjīng bèi dìdi chīwán le!","vi":"Về nhà nhìn một cái, nó đã bị em trai ăn hết rồi!"},{"who":"✓","zh":"蛋糕","py":"dàngāo","vi":"bánh ngọt"}]},{"lines":[{"who":"1","zh":"我学中文的时候常常用它。","py":"Wǒ xué Zhōngwén de shíhou chángcháng yòng tā.","vi":"Lúc học tiếng Trung mình hay dùng nó."},{"who":"2","zh":"它是我在图书馆借的，最好今天还。","py":"Tā shì wǒ zài túshūguǎn jiè de, zuìhǎo jīntiān huán.","vi":"Nó là mình mượn ở thư viện, tốt nhất hôm nay phải trả."},{"who":"3","zh":"可是它被同学借走了，还没还给我。","py":"Kěshì tā bèi tóngxué jièzǒu le, hái méi huán gěi wǒ.","vi":"Nhưng nó bị bạn học mượn mất, vẫn chưa trả mình."},{"who":"✓","zh":"词典","py":"cídiǎn","vi":"từ điển"}]},{"lines":[{"who":"1","zh":"它很小，我每天都带着它。","py":"Tā hěn xiǎo, wǒ měi tiān dōu dàizhe tā.","vi":"Nó rất nhỏ, ngày nào mình cũng mang theo."},{"who":"2","zh":"没有它，我进不去图书馆。","py":"Méiyǒu tā, wǒ jìn bu qù túshūguǎn.","vi":"Không có nó, mình không vào được thư viện."},{"who":"3","zh":"我找不到它了，可能被我忘在家里了。","py":"Wǒ zhǎo bu dào tā le, kěnéng bèi wǒ wàng zài jiāli le.","vi":"Mình không tìm thấy nó, có lẽ bị mình để quên ở nhà."},{"who":"✓","zh":"校园卡","py":"xiàoyuánkǎ","vi":"thẻ trường"}]},{"lines":[{"who":"1","zh":"下雨的时候，我需要它。","py":"Xià yǔ de shíhou, wǒ xūyào tā.","vi":"Lúc trời mưa mình cần đến nó."},{"who":"2","zh":"今天早上出门的时候，我带着它。","py":"Jīntiān zǎoshang chūmén de shíhou, wǒ dàizhe tā.","vi":"Sáng nay lúc ra khỏi nhà mình có mang theo nó."},{"who":"3","zh":"下课的时候，它被别人拿走了，我只能跑回家。","py":"Xiàkè de shíhou, tā bèi biérén názǒu le, wǒ zhǐ néng pǎo huí jiā.","vi":"Lúc tan học nó bị người khác cầm mất, mình đành chạy về nhà."},{"who":"✓","zh":"伞","py":"sǎn","vi":"cái ô"}]},{"lines":[{"who":"1","zh":"我每天都用它看视频、发邮件。","py":"Wǒ měi tiān dōu yòng tā kàn shìpín, fā yóujiàn.","vi":"Ngày nào mình cũng dùng nó xem video, gửi email."},{"who":"2","zh":"昨天晚上它没电了，我找了很久也没找到。","py":"Zuótiān wǎnshang tā méi diàn le, wǒ zhǎole hěn jiǔ yě méi zhǎodào.","vi":"Tối qua nó hết pin, mình tìm mãi không thấy."},{"who":"3","zh":"最后我发现，它被妈妈放在沙发上了。","py":"Zuìhòu wǒ fāxiàn, tā bèi māma fàng zài shāfā shang le.","vi":"Cuối cùng mình phát hiện nó bị mẹ để trên sofa."},{"who":"✓","zh":"手机","py":"shǒujī","vi":"điện thoại"}]}]},{"zh":"最倒霉的一天","py":"zuì dǎoméi de yì tiān","tag":"Trò chơi câu 被","mean":"Lượt 2 · Thi đua nói câu 被","q":{"zh":"讲述\"最倒霉的一天\"，尽量使用被动句，看看谁说得最多。","py":"Jiǎngshù \"zuì dǎoméi de yì tiān\", jǐnliàng shǐyòng bèidòngjù, kànkan shéi shuō de zuì duō.","vi":"Kể về \"ngày xui xẻo nhất\", dùng câu bị động càng nhiều càng tốt, xem ai nói được nhiều nhất."},"banks":[{"lbl":"Các tình huống","items":[{"zh":"💻 电脑","py":"diànnǎo","vi":"máy tính"},{"zh":"👕 衣服","py":"yīfu","vi":"quần áo"},{"zh":"🍱 午饭","py":"wǔfàn","vi":"bữa trưa"},{"zh":"📷 照相机","py":"zhàoxiàngjī","vi":"máy ảnh"},{"zh":"✈️ 护照","py":"hùzhào","vi":"hộ chiếu"},{"zh":"📝 作业","py":"zuòyè","vi":"bài tập"}]}],"items":[{"zh":"买的水果被我忘在超市了。","py":"Mǎi de shuǐguǒ bèi wǒ wàng zài chāoshì le.","vi":"Hoa quả mua xong bị mình để quên ở siêu thị."},{"zh":"图书馆借的书被我丢了。","py":"Túshūguǎn jiè de shū bèi wǒ diū le.","vi":"Sách mượn ở thư viện bị mình làm mất rồi."},{"lines":[{"who":"💻","zh":"电脑","py":"diànnǎo","vi":"máy tính"},{"who":"•","zh":"我的电脑被弟弟用坏了。","py":"Wǒ de diànnǎo bèi dìdi yònghuài le.","vi":"Máy tính của mình bị em trai dùng hỏng rồi."},{"who":"•","zh":"我想借同学的电脑，可是已经被别人借走了。","py":"Wǒ xiǎng jiè tóngxué de diànnǎo, kěshì yǐjīng bèi biérén jièzǒu le.","vi":"Mình muốn mượn máy của bạn, nhưng đã bị người khác mượn mất."}]},{"lines":[{"who":"👕","zh":"衣服","py":"yīfu","vi":"quần áo"},{"who":"•","zh":"我新买的衣服被妈妈洗坏了。","py":"Wǒ xīn mǎi de yīfu bèi māma xǐhuài le.","vi":"Bộ đồ mới mua của mình bị mẹ giặt hỏng rồi."},{"who":"•","zh":"晚会上，我的大衣被别人拿错了。","py":"Wǎnhuì shang, wǒ de dàyī bèi biérén nácuò le.","vi":"Ở buổi liên hoan, áo khoác của mình bị người khác cầm nhầm."}]},{"lines":[{"who":"🍱","zh":"午饭","py":"wǔfàn","vi":"bữa trưa"},{"who":"•","zh":"我带的午饭被同学吃了。","py":"Wǒ dài de wǔfàn bèi tóngxué chī le.","vi":"Cơm trưa mình mang theo bị bạn học ăn mất."},{"who":"•","zh":"我去饭馆买饭，好吃的菜都被卖完了。","py":"Wǒ qù fànguǎn mǎi fàn, hǎochī de cài dōu bèi màiwán le.","vi":"Mình ra quán mua cơm, món ngon đều bị bán hết rồi."}]},{"lines":[{"who":"📷","zh":"照相机","py":"zhàoxiàngjī","vi":"máy ảnh"},{"who":"•","zh":"我的照相机被朋友借走了，还没还给我。","py":"Wǒ de zhàoxiàngjī bèi péngyou jièzǒu le, hái méi huán gěi wǒ.","vi":"Máy ảnh của mình bị bạn mượn mất, vẫn chưa trả."},{"who":"•","zh":"我拍的照片被弟弟发到网上了。","py":"Wǒ pāi de zhàopiàn bèi dìdi fādào wǎngshang le.","vi":"Ảnh mình chụp bị em trai đăng lên mạng rồi."}]},{"lines":[{"who":"✈️","zh":"护照","py":"hùzhào","vi":"hộ chiếu"},{"who":"•","zh":"到了机场，我才发现护照被我放在家里了。","py":"Dàole jīchǎng, wǒ cái fāxiàn hùzhào bèi wǒ fàng zài jiāli le.","vi":"Đến sân bay mình mới phát hiện hộ chiếu bị mình để ở nhà."},{"who":"•","zh":"下了飞机，我的行李又被别人拿错了。","py":"Xiàle fēijī, wǒ de xíngli yòu bèi biérén nácuò le.","vi":"Xuống máy bay, hành lý của mình lại bị người khác lấy nhầm."}]},{"lines":[{"who":"📝","zh":"作业","py":"zuòyè","vi":"bài tập"},{"who":"•","zh":"我的作业被小狗吃了！","py":"Wǒ de zuòyè bèi xiǎogǒu chī le!","vi":"Bài tập của mình bị chó con ăn mất rồi!"},{"who":"•","zh":"上课的时候，我被老师叫起来回答问题，可是我不会。","py":"Shàngkè de shíhou, wǒ bèi lǎoshī jiào qǐlai huídá wèntí, kěshì wǒ bú huì.","vi":"Trong giờ học, mình bị cô gọi đứng dậy trả lời, mà mình không biết."}]}]}],"speak":[]}},{"id":"k3v3-b15","courseId":"k3v3","order":15,"title":"Tôi là nửa người Nam Kinh","titleZh":"我是半个南京人","titlePy":"wǒ shì bàn ge Nánjīngrén","vocab":[{"stt":1,"hanzi":"蓝","pinyin":"lán","hanviet":"Lam","pos":"Tính từ","meaning":"xanh lam, xanh da trời","comps":"蓝天 (trời xanh), 蓝色 (màu xanh lam), 蓝蓝的 (xanh xanh)","example":{"zh":"今天天气很好，天特别蓝。","py":"Jīntiān tiānqì hěn hǎo, tiān tèbié lán.","vi":"Hôm nay thời tiết đẹp, trời xanh lắm."}},{"stt":2,"hanzi":"段","pinyin":"duàn","hanviet":"Đoạn","pos":"Lượng từ","meaning":"đoạn, quãng, khoảng","comps":"一段时间 (một khoảng thời gian), 一段路 (một quãng đường)","example":{"zh":"我在北京住过一段时间。","py":"Wǒ zài Běijīng zhùguo yí duàn shíjiān.","vi":"Mình từng sống ở Bắc Kinh một thời gian."}},{"stt":3,"hanzi":"附近","pinyin":"fùjìn","hanviet":"Phụ cận","pos":"Danh từ","meaning":"gần đây, lân cận","comps":"学校附近 (gần trường), 附近的超市 (siêu thị gần đây)","example":{"zh":"我家附近有一个很大的超市。","py":"Wǒ jiā fùjìn yǒu yí ge hěn dà de chāoshì.","vi":"Gần nhà mình có một siêu thị rất lớn."}},{"stt":4,"hanzi":"马路","pinyin":"mǎlù","hanviet":"Mã lộ","pos":"Danh từ","meaning":"đường cái, đường phố","comps":"过马路 (sang đường), 马路对面 (bên kia đường)","example":{"zh":"过马路的时候要注意车。","py":"Guò mǎlù de shíhou yào zhùyì chē.","vi":"Lúc sang đường phải chú ý xe cộ."}},{"stt":5,"hanzi":"平时","pinyin":"píngshí","hanviet":"Bình thời","pos":"Danh từ","meaning":"ngày thường, bình thường","comps":"平时很忙 (ngày thường rất bận), 跟平时一样 (như mọi ngày)","example":{"zh":"我平时七点起床，周末九点才起。","py":"Wǒ píngshí qī diǎn qǐchuáng, zhōumò jiǔ diǎn cái qǐ.","vi":"Ngày thường mình dậy lúc 7 giờ, cuối tuần 9 giờ mới dậy."}},{"stt":6,"hanzi":"放学","pinyin":"fàngxué","hanviet":"Phóng học","pos":"Động từ (li hợp)","meaning":"tan học","comps":"放学后 (sau giờ tan học), 放了学 (tan học rồi)","example":{"zh":"孩子们下午四点放学。","py":"Háizimen xiàwǔ sì diǎn fàngxué.","vi":"Bọn trẻ tan học lúc bốn giờ chiều."}},{"stt":7,"hanzi":"游戏","pinyin":"yóuxì","hanviet":"Du hí","pos":"Danh từ","meaning":"trò chơi","comps":"做游戏 (chơi trò chơi), 玩游戏 (chơi game)","example":{"zh":"下课后，孩子们在外面做游戏。","py":"Xiàkè hòu, háizimen zài wàimiàn zuò yóuxì.","vi":"Tan tiết, bọn trẻ chơi trò chơi ở bên ngoài."}},{"stt":8,"hanzi":"老人","pinyin":"lǎorén","hanviet":"Lão nhân","pos":"Danh từ","meaning":"người già, người cao tuổi","comps":"帮助老人 (giúp người già), 老人和孩子 (người già và trẻ em)","example":{"zh":"公园里每天早上都有很多老人锻炼身体。","py":"Gōngyuán li měi tiān zǎoshang dōu yǒu hěn duō lǎorén duànliàn shēntǐ.","vi":"Sáng nào trong công viên cũng có nhiều cụ già tập thể dục."}},{"stt":9,"hanzi":"根据","pinyin":"gēnjù","hanviet":"Căn cứ","pos":"Giới từ / Động từ","meaning":"căn cứ vào, dựa theo","comps":"根据需要 (dựa theo nhu cầu), 根据天气 (tuỳ theo thời tiết)","example":{"zh":"我们根据天气决定明天去不去爬山。","py":"Wǒmen gēnjù tiānqì juédìng míngtiān qù bu qù pá shān.","vi":"Chúng mình dựa vào thời tiết để quyết định mai có đi leo núi không."}},{"stt":10,"hanzi":"了解","pinyin":"liǎojiě","hanviet":"Liễu giải","pos":"Động từ","meaning":"hiểu, tìm hiểu","comps":"了解中国文化 (tìm hiểu văn hoá TQ), 不太了解 (không hiểu lắm)","example":{"zh":"我想多了解一下中国的历史。","py":"Wǒ xiǎng duō liǎojiě yíxià Zhōngguó de lìshǐ.","vi":"Mình muốn tìm hiểu thêm về lịch sử Trung Quốc."}},{"stt":11,"hanzi":"可是","pinyin":"kěshì","hanviet":"Khả thị","pos":"Liên từ","meaning":"nhưng","comps":"虽然……，可是…… (tuy…, nhưng…)","example":{"zh":"这件衣服很漂亮，可是太贵了。","py":"Zhè jiàn yīfu hěn piàoliang, kěshì tài guì le.","vi":"Chiếc áo này đẹp lắm, nhưng đắt quá."}},{"stt":12,"hanzi":"以上","pinyin":"yǐshàng","hanviet":"Dĩ thượng","pos":"Danh từ","meaning":"trở lên, hơn","comps":"两千年以上 (hơn hai nghìn năm), 八十分以上 (80 điểm trở lên)","example":{"zh":"这次考试八十分以上的同学有十个。","py":"Zhè cì kǎoshì bāshí fēn yǐshàng de tóngxué yǒu shí ge.","vi":"Kỳ thi lần này có mười bạn được từ 80 điểm trở lên."}},{"stt":13,"hanzi":"有名","pinyin":"yǒumíng","hanviet":"Hữu danh","pos":"Tính từ","meaning":"nổi tiếng","comps":"很有名 (rất nổi tiếng), 有名的景点 (điểm tham quan nổi tiếng)","example":{"zh":"这家饭馆的北京菜很有名。","py":"Zhè jiā fànguǎn de Běijīng cài hěn yǒumíng.","vi":"Món Bắc Kinh của nhà hàng này rất nổi tiếng."}},{"stt":14,"hanzi":"景点","pinyin":"jǐngdiǎn","hanviet":"Cảnh điểm","pos":"Danh từ","meaning":"điểm tham quan","comps":"旅游景点 (điểm du lịch), 有名的景点 (điểm tham quan nổi tiếng)","example":{"zh":"这个城市有很多有名的景点。","py":"Zhège chéngshì yǒu hěn duō yǒumíng de jǐngdiǎn.","vi":"Thành phố này có nhiều điểm tham quan nổi tiếng."}},{"stt":15,"hanzi":"游客","pinyin":"yóukè","hanviet":"Du khách","pos":"Danh từ","meaning":"du khách, khách du lịch","comps":"外国游客 (du khách nước ngoài), 游客很多 (đông du khách)","example":{"zh":"每年夏天，海边的游客特别多。","py":"Měi nián xiàtiān, hǎibiān de yóukè tèbié duō.","vi":"Mùa hè năm nào bãi biển cũng rất đông du khách."}},{"stt":16,"hanzi":"外地","pinyin":"wàidì","hanviet":"Ngoại địa","pos":"Danh từ","meaning":"nơi khác, tỉnh khác","comps":"外地人 (người nơi khác), 去外地 (đi nơi khác)","example":{"zh":"我是外地人，对这里不太了解。","py":"Wǒ shì wàidìrén, duì zhèli bú tài liǎojiě.","vi":"Mình là người nơi khác, không hiểu lắm về chỗ này."}},{"stt":17,"hanzi":"聊","pinyin":"liáo","hanviet":"Liêu","pos":"Động từ","meaning":"nói chuyện, tán gẫu","comps":"聊天儿 (trò chuyện), 边吃边聊 (vừa ăn vừa nói chuyện)","example":{"zh":"下课以后，我们常常一起喝咖啡聊一聊。","py":"Xiàkè yǐhòu, wǒmen chángcháng yìqǐ hē kāfēi liáo yi liáo.","vi":"Tan học, chúng mình hay cùng uống cà phê tán gẫu."}},{"stt":25,"hanzi":"南京","pinyin":"Nánjīng","hanviet":"Nam Kinh","pos":"Danh từ riêng","meaning":"Nam Kinh (thành phố)","comps":"南京人 (người Nam Kinh), 去南京旅游 (đi du lịch Nam Kinh)","example":{"zh":"南京是一个历史很长的城市。","py":"Nánjīng shì yí ge lìshǐ hěn cháng de chéngshì.","vi":"Nam Kinh là một thành phố có lịch sử rất lâu đời."}},{"stt":18,"hanzi":"河","pinyin":"hé","hanviet":"Hà","pos":"Danh từ","meaning":"sông","comps":"一条河 (một con sông), 河边 (bờ sông), 河水 (nước sông)","example":{"zh":"我家附近有一条小河。","py":"Wǒ jiā fùjìn yǒu yì tiáo xiǎo hé.","vi":"Gần nhà mình có một con sông nhỏ."}},{"stt":19,"hanzi":"关系","pinyin":"guānxi","hanviet":"Quan hệ","pos":"Danh từ","meaning":"quan hệ, liên quan","comps":"跟……有关系 (có liên quan đến…), 关系很好 (quan hệ tốt), 没关系 (không sao)","example":{"zh":"我和同事们的关系都很好。","py":"Wǒ hé tóngshìmen de guānxi dōu hěn hǎo.","vi":"Mình và các đồng nghiệp đều có quan hệ rất tốt."}},{"stt":20,"hanzi":"养","pinyin":"yǎng","hanviet":"Dưỡng","pos":"Động từ","meaning":"nuôi, nuôi dưỡng","comps":"养狗 (nuôi chó), 养花 (trồng hoa), 养孩子 (nuôi con)","example":{"zh":"我家养了一只小猫。","py":"Wǒ jiā yǎngle yì zhī xiǎo māo.","vi":"Nhà mình nuôi một chú mèo con."}},{"stt":21,"hanzi":"西北","pinyin":"xīběi","hanviet":"Tây Bắc","pos":"Danh từ","meaning":"tây bắc","comps":"西北边 (phía tây bắc), 中国西北 (vùng tây bắc TQ)","example":{"zh":"我们学校在城市的西北边。","py":"Wǒmen xuéxiào zài chéngshì de xīběi biān.","vi":"Trường mình ở phía tây bắc thành phố."}},{"stt":22,"hanzi":"经过","pinyin":"jīngguò","hanviet":"Kinh quá","pos":"Động từ / Danh từ","meaning":"đi qua; quá trình","comps":"经过公园 (đi qua công viên), 事情的经过 (diễn biến sự việc)","example":{"zh":"每天上班我都经过这家咖啡店。","py":"Měi tiān shàngbān wǒ dōu jīngguò zhè jiā kāfēidiàn.","vi":"Ngày nào đi làm mình cũng đi qua quán cà phê này."}},{"stt":23,"hanzi":"草地","pinyin":"cǎodì","hanviet":"Thảo địa","pos":"Danh từ","meaning":"bãi cỏ","comps":"在草地上 (trên bãi cỏ), 绿绿的草地 (bãi cỏ xanh mướt)","example":{"zh":"孩子们在草地上做游戏。","py":"Háizimen zài cǎodì shang zuò yóuxì.","vi":"Bọn trẻ chơi trò chơi trên bãi cỏ."}},{"stt":24,"hanzi":"遇见","pinyin":"yùjiàn","hanviet":"Ngộ kiến","pos":"Động từ","meaning":"gặp (tình cờ)","comps":"遇见朋友 (gặp bạn), 在路上遇见 (gặp trên đường)","example":{"zh":"昨天我在超市遇见了我的老师。","py":"Zuótiān wǒ zài chāoshì yùjiànle wǒ de lǎoshī.","vi":"Hôm qua mình tình cờ gặp cô giáo ở siêu thị."}},{"stt":26,"hanzi":"黄河","pinyin":"Huáng Hé","hanviet":"Hoàng Hà","pos":"Danh từ riêng","meaning":"sông Hoàng Hà","comps":"黄河边 (ven sông Hoàng Hà), 黄河水 (nước sông Hoàng Hà)","example":{"zh":"黄河是中国第二长的河。","py":"Huáng Hé shì Zhōngguó dì-èr cháng de hé.","vi":"Hoàng Hà là con sông dài thứ hai Trung Quốc."}}],"hanzi":[{"char":"蓝","pinyin":"lán","hanviet":"Lam","chars":["蓝"],"story":"蓝 = 艹 (cỏ) + 监 → cây chàm, lá dùng nhuộm vải xanh → màu xanh lam. 蓝天 = trời xanh; tên khu nhà 蓝天小区 trong bài khoá = khu Lam Thiên."},{"char":"段","pinyin":"duàn","hanviet":"Đoạn","chars":["段"],"story":"段 = bậc đá + 殳 (tay cầm búa) → đập đá thành từng khúc → đoạn, khúc. Lượng từ cho thời gian, quãng đường: 一段时间, 一段路."},{"char":"附近","pinyin":"fùjìn","hanviet":"Phụ cận","chars":["附","近"],"story":"附 = 阝 (gò đất) + 付 → dựa sát vào. 近 = 辶 + 斤 → gần. 附近 = vùng sát bên → gần đây, lân cận (Phụ cận). Đặt sau nơi chốn: 学校附近."},{"char":"马路","pinyin":"mǎlù","hanviet":"Mã lộ","chars":["马","路"],"story":"马 = con ngựa; 路 = 足 (chân) + 各 → con đường. 马路 = đường cho ngựa xe chạy → đường cái, đường phố. 过马路 = sang đường."},{"char":"平时","pinyin":"píngshí","hanviet":"Bình thời","chars":["平","时"],"story":"平 = bằng phẳng, bình thường; 时 = lúc. 平时 = lúc bình thường → ngày thường. Hay đối lập với 周末, 假期: 平时很忙，周末才休息."},{"char":"放学","pinyin":"fàngxué","hanviet":"Phóng học","chars":["放","学"],"story":"放 = thả ra (放假 = được nghỉ). 学 = học. 放学 = thả học trò về → tan học (hết buổi, về nhà). Khác 下课 = hết một tiết học."},{"char":"游戏","pinyin":"yóuxì","hanviet":"Du hí","chars":["游","戏"],"story":"游 = 氵 + 斿 → bơi, rong chơi (游泳, 旅游). 戏 = 又 + 戈 → đùa nghịch, diễn kịch. 游戏 = trò chơi. 做游戏 = chơi trò chơi tập thể; 玩游戏 = chơi game."},{"char":"老人","pinyin":"lǎorén","hanviet":"Lão nhân","chars":["老","人"],"story":"老 = hình người già tóc dài chống gậy. 人 = người. 老人 = người già (Lão nhân). Nói kính trọng hơn: 老人家."},{"char":"根据","pinyin":"gēnjù","hanviet":"Căn cứ","chars":["根","据"],"story":"根 = 木 + 艮 → rễ cây. 据 = 扌 + 居 → dựa vào. 根据 = dựa vào gốc rễ → căn cứ (Căn cứ). Làm giới từ: 根据他们的需要 = dựa theo nhu cầu của họ."},{"char":"了解","pinyin":"liǎojiě","hanviet":"Liễu giải","chars":["了","解"],"story":"了 ở đây đọc liǎo = hiểu rõ (không phải le). 解 = 角 + 刀 + 牛 → mổ xẻ (解决 bài 11). 了解 = hiểu rõ ngọn ngành → hiểu, tìm hiểu."},{"char":"可是","pinyin":"kěshì","hanviet":"Khả thị","chars":["可","是"],"story":"可 = có thể; 是 = là. 可是 = nhưng — nghĩa như 但是, dùng nhiều trong khẩu ngữ. Hay đi thành cặp: 虽然……，可是……"},{"char":"以上","pinyin":"yǐshàng","hanviet":"Dĩ thượng","chars":["以","上"],"story":"以 = lấy … làm mốc; 上 = trên. 以上 = từ mốc đó trở lên. Đặt sau số lượng: 两千年以上. Ngược lại: 以下 = trở xuống."},{"char":"有名","pinyin":"yǒumíng","hanviet":"Hữu danh","chars":["有","名"],"story":"有 = có; 名 = tên, danh tiếng (名人 bài 14). 有名 = có tiếng tăm → nổi tiếng (Hữu danh): 很有名, 有名的景点."},{"char":"景点","pinyin":"jǐngdiǎn","hanviet":"Cảnh điểm","chars":["景","点"],"story":"景 = 日 (mặt trời) + 京 (kinh thành) → cảnh sắc dưới nắng → phong cảnh. 点 = điểm, chỗ. 景点 = chỗ có cảnh đẹp → điểm tham quan."},{"char":"游客","pinyin":"yóukè","hanviet":"Du khách","chars":["游","客"],"story":"游 = rong chơi (旅游); 客 = khách (客人 bài 13). 游客 = khách đi chơi → du khách (Hán Việt: Du khách)."},{"char":"外地","pinyin":"wàidì","hanviet":"Ngoại địa","chars":["外","地"],"story":"外 = bên ngoài; 地 = vùng đất. 外地 = nơi khác, không phải nơi đang nói tới. 外地人 = người nơi khác đến. Ngược lại: 本地 (bản địa)."},{"char":"聊","pinyin":"liáo","hanviet":"Liêu","chars":["聊"],"story":"聊 = 耳 (tai) + 卯 → ghé tai nhau mà nói → nói chuyện phiếm. 聊天儿 (bài 13) = 聊 + 天. Lặp lại: 聊聊, 聊一聊; 边吃边聊."},{"char":"南京","pinyin":"Nánjīng","hanviet":"Nam Kinh","chars":["南","京"],"story":"南 = phía nam; 京 = kinh đô. 南京 = kinh đô phía nam (đối với 北京 = kinh đô phía bắc). Cố đô của nhiều triều đại, nay là thủ phủ tỉnh Giang Tô."},{"char":"河","pinyin":"hé","hanviet":"Hà","chars":["河"],"story":"河 = 氵 (nước) + 可 (gợi âm kě → hé) → dòng nước chảy → sông. Lượng từ 条: 一条河. 河边 = bờ sông, 河水 = nước sông."},{"char":"关系","pinyin":"guānxi","hanviet":"Quan hệ","chars":["关","系"],"story":"关 = then cài cửa (关门); 系 = sợi dây buộc. 关系 = những mối buộc nối với nhau → quan hệ, liên quan. 跟……有关系 = có liên quan; 没关系 = không sao. 系 đọc nhẹ: guānxi."},{"char":"养","pinyin":"yǎng","hanviet":"Dưỡng","chars":["养"],"story":"养 = 羊 (con dê) ở trên → chăn dê, cho dê ăn → nuôi. 养狗, 养花; nghĩa rộng là nuôi dưỡng: 黄河养了我们几千年."},{"char":"西北","pinyin":"xīběi","hanviet":"Tây Bắc","chars":["西","北"],"story":"西 = tây; 北 = bắc. Tiếng Trung nói tây / đông trước bắc / nam: 西北, 东北, 西南, 东南 — giống tiếng Việt. 北京的西北边 = phía tây bắc Bắc Kinh."},{"char":"经过","pinyin":"jīngguò","hanviet":"Kinh quá","chars":["经","过"],"story":"经 = 纟 (sợi) + 坙 → sợi dọc chạy suốt khung cửi. 过 = qua. 经过 = đi ngang qua (有一条河经过那里) hoặc quá trình, diễn biến (事情的经过)."},{"char":"草地","pinyin":"cǎodì","hanviet":"Thảo địa","chars":["草","地"],"story":"草 = 艹 (cỏ) + 早 → cỏ. 地 = đất. 草地 = đất mọc đầy cỏ → bãi cỏ. 在草地上 = trên bãi cỏ; 绿绿的草地 = bãi cỏ xanh mướt."},{"char":"遇见","pinyin":"yùjiàn","hanviet":"Ngộ kiến","chars":["遇","见"],"story":"遇 = 辶 (đi) + 禺 → gặp nhau trên đường. 见 = thấy. 遇见 = tình cờ gặp người. 遇到 (bài 10) rộng hơn: gặp người hoặc gặp chuyện (遇到问题)."},{"char":"黄河","pinyin":"Huáng Hé","hanviet":"Hoàng Hà","chars":["黄","河"],"story":"黄 = màu vàng; 河 = sông. Nước sông mang nhiều phù sa nên có màu vàng → 黄河 (Hoàng Hà). Sông dài thứ hai TQ, được gọi là \"sông mẹ\" của người Trung Quốc."}],"grammar":[{"title":"根据 + 依据，（主语）+ 动词","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>根据</b><small>dựa theo</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>Căn cứ</b><small>nhu cầu / yêu cầu …</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>，(Chủ ngữ)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>Hành động</b></span></div>","summary":"<p class=\"gr-lead\">Căn cứ vào, dựa theo …</p><ul><li>根据 + <b>danh từ</b> (需要, 要求, 兴趣, 天气…) → hành động <b>dựa vào</b> căn cứ đó.</li><li>Đặt <b>đầu câu</b> (có dấu phẩy) hoặc <b>sau chủ ngữ</b>: <span class=\"zh\">根据要求，我们…… · 老师根据……选择了……</span></li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">根据 · vị trí trong câu</span> · Hai vị trí</h4><p>Dựa theo …</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Đầu câu</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>根据</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>要求</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>，我们</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>必须参加会议</b></span></div><div class=\"fx-ex zh\">根据要求，我们必须参加明天的会议。</div><div class=\"fx-lbl\">Sau chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>老师</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>根据</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>学生的兴趣</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>选择了书</b></span></div><div class=\"fx-ex zh\">老师根据每个学生的兴趣，选择了不一样的书。</div><div class=\"fx-lbl\">Sau chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>小区</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>根据</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>他们的需要</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>有了变化</b></span></div><div class=\"fx-ex zh\">这几年小区根据他们的需要，有了很多变化。</div></div><p class=\"gr-key\">Căn cứ hay gặp: <span class=\"zh\">需要 · 要求 · 兴趣 · 天气 · 时间 · 水平</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">这几年小区根据他们的需要，有了很多变化。</span> = Mấy năm nay khu nhà đã thay đổi nhiều, dựa theo nhu cầu của họ.</p>","note":"<b>Lưu ý:</b> 根据 không đi thẳng với người: ✗ <span class=\"zh\">根据老师，明天考试</span> → ✓ <span class=\"zh\">根据老师的要求，……</span>","examples":[{"zh":"这几年小区根据他们的需要，有了很多变化。","py":"Zhè jǐ nián xiǎoqū gēnjù tāmen de xūyào, yǒule hěn duō biànhuà.","vi":"Mấy năm nay khu nhà có nhiều thay đổi dựa theo nhu cầu của họ."},{"zh":"根据要求，我们必须参加明天的会议。","py":"Gēnjù yāoqiú, wǒmen bìxū cānjiā míngtiān de huìyì.","vi":"Theo yêu cầu, chúng tôi phải dự cuộc họp ngày mai."},{"zh":"老师根据每个学生的兴趣，选择了不一样的书。","py":"Lǎoshī gēnjù měi ge xuésheng de xìngqù, xuǎnzéle bù yíyàng de shū.","vi":"Thầy cô dựa vào sở thích của từng học sinh mà chọn những cuốn sách khác nhau."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">你应该____选择合适的衣服。</span><span class=\"qz-hint\">Bạn nên dựa vào thời tiết để chọn quần áo phù hợp.</span>","answer":["根据天气"],"explain":"你应该根据天气选择合适的衣服。 (Nǐ yīnggāi gēnjù tiānqì xuǎnzé héshì de yīfu.)"},{"type":"fill","q":"<span class=\"zh\">老师会____，给每个学生不同的作业。</span><span class=\"qz-hint\">Thầy cô sẽ dựa vào trình độ từng em để giao bài tập khác nhau.</span>","answer":["根据每个学生的水平","根据学生的水平"],"explain":"老师会根据每个学生的水平，给每个学生不同的作业。 (Lǎoshī huì gēnjù měi ge xuésheng de shuǐpíng, gěi měi ge xuésheng bù tóng de zuòyè.)"}]},{"title":"数词 + 量词 + 数词 + 量词 +（地）+ 动词","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>Số + LT</b><small>一点儿</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>Số + LT</b><small>一点儿</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>(地)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>Động từ</b></span></div>","summary":"<p class=\"gr-lead\">Từng … một</p><ul><li>Cụm số lượng lặp lại làm <b>trạng ngữ</b>, tả <b>cách thức</b>: từng … một, dần dần: <span class=\"zh\">一天一天地提高了</span>.</li><li>Khác 量词重叠 bài 5 (<span class=\"zh\">张张都很漂亮</span> = tấm nào cũng) — cụm này đứng <b>trước động từ</b>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">数量重叠 · ba kiểu hay gặp</span> · Cấu trúc</h4><p>Từng … một</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Từng chút một</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>一点儿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>一点儿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>给您</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>讲</b></span></div><div class=\"fx-ex zh\">我得一点儿一点儿给您讲。</div><div class=\"fx-lbl\">Theo thời gian</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>一天</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>一天</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>地</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>提高了</b></span></div><div class=\"fx-ex zh\">学生们的汉语水平一天一天地提高了。</div><div class=\"fx-lbl\">Theo nhóm</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>两个</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>两个</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>地</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>走进去了</b></span></div><div class=\"fx-ex zh\">他们两个两个地走进去了。</div><div class=\"fx-lbl\">Bài 5 · 量词重叠</div><div class=\"fx-row\"><span class=\"fx-p\"><b>照片</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>张张</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>都很漂亮</b></span></div><div class=\"fx-ex zh\">这些照片张张都很漂亮。</div></div><p class=\"gr-key\"><span class=\"zh\">一本一本 · 一张一张 · 一个一个</span> = từng cuốn · từng tấm · từng cái một</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">那太多了，我得一点儿一点儿给您讲。</span> = Thế thì nhiều lắm, em phải kể dần từng chút một cho chị.</p>","note":"<b>Lưu ý:</b> Đặt trước động từ: ✗ <span class=\"zh\">我讲一点儿一点儿</span> → ✓ <span class=\"zh\">我一点儿一点儿地讲</span>","examples":[{"zh":"我得一点儿一点儿给您讲。","py":"Wǒ děi yìdiǎnr yìdiǎnr gěi nín jiǎng.","vi":"Em phải kể dần từng chút một cho chị."},{"zh":"学生们的汉语水平一天一天地提高了。","py":"Xuéshengmen de Hànyǔ shuǐpíng yì tiān yì tiān de tígāo le.","vi":"Trình độ tiếng Trung của học sinh tiến bộ từng ngày."},{"zh":"他们两个两个地走进去了。","py":"Tāmen liǎng ge liǎng ge de zǒu jìnqu le.","vi":"Họ đi vào từng tốp hai người một."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你女儿喜欢看外语书吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">喜欢，她____，已经看完十多本了。（本）</span></span></span><span class=\"qz-hint\">Con gái chị có thích đọc sách ngoại văn không? — Thích lắm, nó đọc từng cuốn một, đã đọc xong hơn chục cuốn rồi.</span>","answer":["一本一本地看","一本一本看"],"explain":"喜欢，她一本一本地看，已经看完十多本了。（本） (Xǐhuan, tā yì běn yì běn de kàn, yǐjīng kànwán shí duō běn le. (běn))"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你现在能选好用哪张照片吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">别着急，我要____。（张）</span></span></span><span class=\"qz-hint\">Giờ bạn chọn được dùng tấm ảnh nào chưa? — Đừng vội, mình phải xem từng tấm một.</span>","answer":["一张一张地看","一张一张看"],"explain":"别着急，我要一张一张地看。（张） (Bié zháojí, wǒ yào yì zhāng yì zhāng de kàn. (zhāng))"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这么多的练习题，什么时候能做完啊？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____，慢慢就做完了。（个）</span></span></span><span class=\"qz-hint\">Nhiều bài tập thế này, bao giờ mới làm xong đây? — Làm từng bài một, dần dần sẽ xong thôi.</span>","answer":["一个一个地做","一个一个做"],"explain":"一个一个地做，慢慢就做完了。（个） (Yí ge yí ge de zuò, mànmàn jiù zuòwán le. (gè))"}]},{"title":"在 + 人 / 群体 + 看来，……","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>在</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>Người / nhóm</b><small>我 · 同事们 …</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>看来</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>，Quan điểm</b></span></div>","summary":"<p class=\"gr-lead\">Theo … thì, trong mắt …</p><ul><li>Giữa 在 và 看来 là <b>người / nhóm người</b>: <span class=\"zh\">在我看来 · 在同事们看来 · 在我们中国人看来</span>.</li><li>Khác <span class=\"zh\">看来</span> bài 11 = xem ra (đoán từ tình hình): <span class=\"zh\">看来要下雨了</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">在……看来 · 看来</span> · Đối chiếu bài 11</h4><p>Theo … thì</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Bản thân</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>在</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>看来</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>，读书是好习惯</b></span></div><div class=\"fx-ex zh\">在我看来，读书是好习惯。</div><div class=\"fx-lbl\">Người khác</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>在</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>同事们</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>看来</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>，她很认真</b></span></div><div class=\"fx-ex zh\">在同事们看来，她很认真。</div><div class=\"fx-lbl\">Một nhóm người</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>在</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>中国人</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>看来</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>，黄河像妈妈</b></span></div><div class=\"fx-ex zh\">在中国人看来，黄河像妈妈。</div></div><p class=\"gr-key\"><span class=\"zh\">在……看来</span> = <b>ý kiến</b> của ai đó　·　<span class=\"zh\">看来</span> (bài 11) = <b>suy đoán</b>: <span class=\"zh\">看来他正在开会</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">在我看来，每天读书是一种很好的习惯。</span> = Theo tôi, mỗi ngày đọc sách là một thói quen rất tốt.</p>","note":"<b>Lưu ý:</b> Không thêm 我觉得 phía sau: ✗ <span class=\"zh\">在我看来，我觉得他很认真</span> → ✓ <span class=\"zh\">在我看来，他很认真</span>","examples":[{"zh":"在我们中国人看来，黄河像妈妈一样，养了我们几千年。","py":"Zài wǒmen Zhōngguórén kànlái, Huáng Hé xiàng māma yíyàng, yǎngle wǒmen jǐ qiān nián.","vi":"Trong mắt người Trung Quốc, Hoàng Hà như người mẹ, đã nuôi chúng tôi mấy nghìn năm."},{"zh":"在同事们看来，她工作非常认真。","py":"Zài tóngshìmen kànlái, tā gōngzuò fēicháng rènzhēn.","vi":"Theo các đồng nghiệp, cô ấy làm việc rất chăm chỉ."},{"zh":"在我看来，每天读书是一种很好的习惯。","py":"Zài wǒ kànlái, měi tiān dú shū shì yì zhǒng hěn hǎo de xíguàn.","vi":"Theo tôi, mỗi ngày đọc sách là một thói quen rất tốt."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">____，时间比钱更重要。</span><span class=\"qz-hint\">Theo tôi, thời gian quan trọng hơn tiền bạc.</span>","answer":["在我看来"],"explain":"在我看来，时间比钱更重要。 (Zài wǒ kànlái, shíjiān bǐ qián gèng zhòngyào.)"},{"type":"fill","q":"<span class=\"zh\">____，每天运动对身体很好。</span><span class=\"qz-hint\">Theo bác sĩ, vận động mỗi ngày rất tốt cho sức khoẻ.</span>","answer":["在医生看来"],"explain":"在医生看来，每天运动对身体很好。 (Zài yīshēng kànlái, měi tiān yùndòng duì shēntǐ hěn hǎo.)"},{"type":"fill","q":"<span class=\"zh\">____，这个城市的环境非常好。</span><span class=\"qz-hint\">Trong mắt nhiều du khách, môi trường thành phố này rất tốt.</span>","answer":["在很多游客看来","在游客看来","在我看来"],"explain":"在很多游客看来，这个城市的环境非常好。 (Zài hěn duō yóukè kànlái, zhège chéngshì de huánjìng fēicháng hǎo.)"}]},{"title":"不一会儿（，主语）+ 就 + 动词 + 了","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>不一会儿</b><small>chẳng mấy chốc</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>，(Chủ ngữ)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>就</b><small>đã</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>Động từ + 了</b></span></div>","summary":"<p class=\"gr-lead\">Chẳng mấy chốc, một lát sau</p><ul><li>Đứng <b>đầu câu</b> hoặc <b>sau chủ ngữ</b>, hay đi với <span class=\"zh\">就……了</span>: <span class=\"zh\">不一会儿，张校长就来了</span>.</li><li>Kể việc <b>đã xảy ra</b>; còn <span class=\"zh\">一会儿</span> (bài 14) = lát nữa: <span class=\"zh\">你一会儿做什么？</span></li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">不一会儿 · 一会儿</span> · Đối chiếu bài 14</h4><p>Chẳng mấy chốc · lát nữa</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Đầu câu</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>不一会儿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>，张校长</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>来了</b></span></div><div class=\"fx-ex zh\">不一会儿，张校长就来了。</div><div class=\"fx-lbl\">Sau chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>难过的事情</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不一会儿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>忘了</b></span></div><div class=\"fx-ex zh\">难过的事情不一会儿就忘了。</div><div class=\"fx-lbl\">一会儿 · bài 14</div><div class=\"fx-row\"><span class=\"fx-p\"><b>你</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>一会儿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>做什么？</b></span></div><div class=\"fx-ex zh\">今天下课早，你一会儿做什么？</div></div><p class=\"gr-key\"><span class=\"zh\">不一会儿</span> = <b>đã</b> xảy ra rất nhanh (kể lại)　·　<span class=\"zh\">一会儿</span> = <b>sắp</b> làm (lát nữa) / làm trong chốc lát</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">难过的事情不一会儿就忘了。</span> = Chuyện buồn chẳng mấy chốc đã quên.</p>","note":"<b>Lưu ý:</b> Không dùng cho việc sắp làm: ✗ <span class=\"zh\">我不一会儿去找你</span> → ✓ <span class=\"zh\">我一会儿去找你</span>","examples":[{"zh":"难过的事情不一会儿就忘了。","py":"Nánguò de shìqing bù yíhuìr jiù wàng le.","vi":"Chuyện buồn chẳng mấy chốc đã quên."},{"zh":"不一会儿，张校长就来了。","py":"Bù yíhuìr, Zhāng xiàozhǎng jiù lái le.","vi":"Chẳng mấy chốc thầy hiệu trưởng Trương đã đến."},{"zh":"两个小时看起来长，但是不一会儿就过去了。","py":"Liǎng ge xiǎoshí kàn qǐlai cháng, dànshì bù yíhuìr jiù guòqu le.","vi":"Hai tiếng nghe thì dài, nhưng chẳng mấy chốc đã trôi qua."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">我只想看半个小时电视，可是____一个小时就过去了。</span><span class=\"qz-hint\">Mình chỉ định xem TV nửa tiếng, nhưng chẳng mấy chốc đã hết một tiếng.</span>","answer":["不一会儿"],"explain":"我只想看半个小时电视，可是不一会儿一个小时就过去了。 (Wǒ zhǐ xiǎng kàn bàn ge xiǎoshí diànshì, kěshì bù yíhuìr yí ge xiǎoshí jiù guòqu le.)"},{"type":"fill","q":"<span class=\"zh\">他们在门口站着，出租车____。</span><span class=\"qz-hint\">Họ đứng ở cổng, chẳng mấy chốc taxi đã đến.</span>","answer":["不一会儿就来了","不一会儿就到了"],"explain":"他们在门口站着，出租车不一会儿就来了。 (Tāmen zài ménkǒu zhànzhe, chūzūchē bù yíhuìr jiù lái le.)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在办公室里","titleVi":"Văn phòng — chuyện khu nhà Lam Thiên","lines":[{"speaker":"乐","name":"Đồng Lạc","zh":"您搬到蓝天小区一段时间了，觉得怎么样？","py":"Nín bāndào Lántiān Xiǎoqū yí duàn shíjiān le, juéde zěnmeyàng?","vi":"Chị chuyển đến khu Lam Thiên được một thời gian rồi, thấy thế nào ạ?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"小区环境挺好的，附近买东西也很方便，过马路就是超市。","py":"Xiǎoqū huánjìng tǐng hǎo de, fùjìn mǎi dōngxi yě hěn fāngbiàn, guò mǎlù jiù shì chāoshì.","vi":"Môi trường khu khá tốt, gần đó mua sắm cũng tiện, qua đường là siêu thị."},{"speaker":"乐","name":"Đồng Lạc","zh":"平时孩子们在哪儿玩？","py":"Píngshí háizimen zài nǎr wán?","vi":"Ngày thường bọn trẻ chơi ở đâu ạ?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"小区里有很多树，孩子们放学后就在树下做游戏。你想买房子吗？","py":"Xiǎoqū li yǒu hěn duō shù, háizimen fàngxué hòu jiù zài shù xià zuò yóuxì. Nǐ xiǎng mǎi fángzi ma?","vi":"Trong khu có nhiều cây, bọn trẻ tan học là chơi dưới gốc cây. Em muốn mua nhà à?"},{"speaker":"乐","name":"Đồng Lạc","zh":"是。我想买一个大房子，让我爸妈过来跟我一起住。","py":"Shì. Wǒ xiǎng mǎi yí ge dà fángzi, ràng wǒ bà mā guòlai gēn wǒ yìqǐ zhù.","vi":"Vâng. Em muốn mua một căn nhà rộng, để bố mẹ em sang ở cùng."},{"speaker":"雪","name":"Nhất Tuyết","zh":"蓝天小区的老人挺多的，这几年小区根据他们的需要，有了很多变化。","py":"Lántiān Xiǎoqū de lǎorén tǐng duō de, zhè jǐ nián xiǎoqū gēnjù tāmen de xūyào, yǒule hěn duō biànhuà.","vi":"Khu Lam Thiên khá nhiều người già, mấy năm nay khu đã thay đổi nhiều dựa theo nhu cầu của họ."},{"speaker":"乐","name":"Đồng Lạc","zh":"真不错！过几天我去蓝天小区看看。","py":"Zhēn búcuò! Guò jǐ tiān wǒ qù Lántiān Xiǎoqū kànkan.","vi":"Hay thật! Mấy hôm nữa em đến khu Lam Thiên xem thử."}]},{"titleZh":"课文二 · 在办公室里","titleVi":"Văn phòng — hỏi chuyện du lịch Nam Kinh","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"假期我想去南京旅游，但是我不太了解那里。","py":"Jiàqī wǒ xiǎng qù Nánjīng lǚyóu, dànshì wǒ bú tài liǎojiě nàli.","vi":"Kỳ nghỉ chị muốn đi Nam Kinh du lịch, nhưng chị không hiểu lắm về nơi đó."},{"speaker":"乐","name":"Đồng Lạc","zh":"我虽然不是南京人，可是我是在南京上的大学，可以说是半个南京人。","py":"Wǒ suīrán bú shì Nánjīngrén, kěshì wǒ shì zài Nánjīng shàng de dàxué, kěyǐ shuō shì bàn ge Nánjīngrén.","vi":"Em tuy không phải người Nam Kinh, nhưng em học đại học ở đó, có thể nói là nửa người Nam Kinh."},{"speaker":"雪","name":"Nhất Tuyết","zh":"太好了！你快给我介绍一下南京吧。","py":"Tài hǎo le! Nǐ kuài gěi wǒ jièshào yíxià Nánjīng ba.","vi":"Tuyệt quá! Em mau giới thiệu cho chị về Nam Kinh đi."},{"speaker":"乐","name":"Đồng Lạc","zh":"南京有两千年以上的历史，有老城、老街，还有很多有名的景点，每年去旅游的游客特别多。","py":"Nánjīng yǒu liǎngqiān nián yǐshàng de lìshǐ, yǒu lǎochéng, lǎojiē, hái yǒu hěn duō yǒumíng de jǐngdiǎn, měi nián qù lǚyóu de yóukè tèbié duō.","vi":"Nam Kinh có hơn hai nghìn năm lịch sử, có thành cổ, phố cổ, còn nhiều điểm tham quan nổi tiếng, năm nào du khách cũng rất đông."},{"speaker":"雪","name":"Nhất Tuyết","zh":"除了这些以外，你再告诉我一些外地人不知道的地方。","py":"Chúle zhèxiē yǐwài, nǐ zài gàosu wǒ yìxiē wàidìrén bù zhīdào de dìfang.","vi":"Ngoài những chỗ đó ra, em kể thêm cho chị vài nơi người nơi khác không biết nhé."},{"speaker":"乐","name":"Đồng Lạc","zh":"那太多了，我得一点儿一点儿给您讲。","py":"Nà tài duō le, wǒ děi yìdiǎnr yìdiǎnr gěi nín jiǎng.","vi":"Thế thì nhiều lắm, em phải kể dần từng chút cho chị."},{"speaker":"雪","name":"Nhất Tuyết","zh":"行，下班后我请你吃晚饭，咱们边吃边聊。","py":"Xíng, xiàbān hòu wǒ qǐng nǐ chī wǎnfàn, zánmen biān chī biān liáo.","vi":"Được, tan làm chị mời em ăn tối, mình vừa ăn vừa nói chuyện."}]},{"titleZh":"课文三 · 在家里","titleVi":"Ở nhà — hai mẹ con nói về Hoàng Hà","lines":[{"speaker":"雪","name":"Nhất Tuyết","zh":"小明，中国有一条大河，它的名字跟颜色有关系，你知道是什么河吗？","py":"Xiǎomíng, Zhōngguó yǒu yì tiáo dà hé, tā de míngzi gēn yánsè yǒu guānxi, nǐ zhīdào shì shénme hé ma?","vi":"Tiểu Minh, Trung Quốc có một con sông lớn, tên của nó liên quan đến màu sắc, con biết là sông gì không?"},{"speaker":"弟","name":"Tiểu Minh","zh":"我知道，是黄河！","py":"Wǒ zhīdào, shì Huáng Hé!","vi":"Con biết, là sông Hoàng Hà!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"你说对了。我再问问你，你知道它为什么叫黄河吗？","py":"Nǐ shuō duì le. Wǒ zài wènwen nǐ, nǐ zhīdào tā wèi shénme jiào Huáng Hé ma?","vi":"Con nói đúng rồi. Mẹ hỏi thêm nhé, con biết vì sao nó gọi là Hoàng Hà không?"},{"speaker":"弟","name":"Tiểu Minh","zh":"因为河水看起来是黄色的，所以叫这个名字。黄河是中国最长的河吗？","py":"Yīnwèi héshuǐ kàn qǐlai shì huángsè de, suǒyǐ jiào zhège míngzi. Huáng Hé shì Zhōngguó zuì cháng de hé ma?","vi":"Vì nước sông trông có màu vàng nên gọi tên đó. Hoàng Hà là sông dài nhất Trung Quốc ạ?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"不是。黄河虽然不是最长的河，可是在历史上很重要。","py":"Bú shì. Huáng Hé suīrán bú shì zuì cháng de hé, kěshì zài lìshǐ shang hěn zhòngyào.","vi":"Không phải. Hoàng Hà tuy không phải sông dài nhất, nhưng rất quan trọng trong lịch sử."},{"speaker":"弟","name":"Tiểu Minh","zh":"这个我知道。很久以前，很多中国人都住在黄河边上。","py":"Zhège wǒ zhīdào. Hěn jiǔ yǐqián, hěn duō Zhōngguórén dōu zhù zài Huáng Hé biān shang.","vi":"Cái này con biết. Từ rất lâu rồi, nhiều người Trung Quốc đã sống ven sông Hoàng Hà."},{"speaker":"雪","name":"Nhất Tuyết","zh":"对。在我们中国人看来，黄河像妈妈一样，养了我们几千年。","py":"Duì. Zài wǒmen Zhōngguórén kànlái, Huáng Hé xiàng māma yíyàng, yǎngle wǒmen jǐ qiān nián.","vi":"Đúng. Trong mắt người Trung Quốc chúng ta, Hoàng Hà như người mẹ, đã nuôi chúng ta mấy nghìn năm."}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — Nhất Tuyết viết nhật ký","para":true,"speaker":"雪","lines":[{"zh":"我小时候住在北京的西北边，有一条非常有名的河经过那里。","py":"Wǒ xiǎoshíhou zhù zài Běijīng de xīběi biān, yǒu yì tiáo fēicháng yǒumíng de hé jīngguò nàli.","vi":"Hồi nhỏ tôi sống ở phía tây bắc Bắc Kinh, có một con sông rất nổi tiếng chảy qua đó."},{"zh":"我家就住在河边。","py":"Wǒ jiā jiù zhù zài hé biān.","vi":"Nhà tôi ở ngay bên bờ sông."},{"zh":"那里有高高的大树和绿绿的草地。","py":"Nàli yǒu gāogāo de dà shù hé lǜlǜ de cǎodì.","vi":"Ở đó có những cây to cao vút và bãi cỏ xanh mướt."},{"zh":"春天，河边的花都开了，看起来特别漂亮。","py":"Chūntiān, hé biān de huā dōu kāi le, kàn qǐlai tèbié piàoliang.","vi":"Mùa xuân, hoa ven sông nở rộ, trông đẹp vô cùng."},{"zh":"还记得小时候，一到夏天我就去河里游泳。","py":"Hái jìde xiǎoshíhou, yí dào xiàtiān wǒ jiù qù hé li yóuyǒng.","vi":"Tôi vẫn nhớ hồi nhỏ, cứ đến mùa hè là tôi ra sông bơi."},{"zh":"长大以后，遇到什么不开心的事情，我就去河边的树下坐着，听听鸟叫，看看河水，跟遇见的朋友聊聊天儿，难过的事情不一会儿就忘了。","py":"Zhǎngdà yǐhòu, yùdào shénme bù kāixīn de shìqing, wǒ jiù qù hé biān de shù xià zuòzhe, tīngting niǎo jiào, kànkan héshuǐ, gēn yùjiàn de péngyou liáoliao tiānr, nánguò de shìqing bù yíhuìr jiù wàng le.","vi":"Lớn lên, gặp chuyện gì không vui, tôi lại ra ngồi dưới gốc cây bên sông, nghe chim hót, ngắm dòng nước, trò chuyện với bạn bè tình cờ gặp, chẳng mấy chốc chuyện buồn đã quên hết."},{"zh":"那是我最喜欢的地方。","py":"Nà shì wǒ zuì xǐhuan de dìfang.","vi":"Đó là nơi tôi yêu thích nhất."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"北京 · 上海 · 西安 · 南京","q":{"zh":"两人一组，查阅以下城市的资料，说说自己最喜欢哪一个，并说明理由。","py":"Liǎng rén yì zǔ, cháyuè yǐxià chéngshì de zīliào, shuōshuo zìjǐ zuì xǐhuan nǎ yí ge, bìng shuōmíng lǐyóu.","vi":"Theo cặp: tìm hiểu 4 thành phố, nói mình thích nhất thành phố nào và vì sao."},"items":[{"zh":"这个城市有多少年的历史？","py":"Zhège chéngshì yǒu duōshao nián de lìshǐ?","vi":"Thành phố này có bao nhiêu năm lịch sử?"},{"zh":"那里有哪些有名的景点？","py":"Nàli yǒu nǎxiē yǒumíng de jǐngdiǎn?","vi":"Ở đó có những điểm tham quan nổi tiếng nào?"},{"zh":"在你看来，去那里最好做什么？","py":"Zài nǐ kànlái, qù nàli zuìhǎo zuò shénme?","vi":"Theo bạn, đến đó nên làm gì?"},{"zh":"你最喜欢哪个城市？为什么？","py":"Nǐ zuì xǐhuan nǎge chéngshì? Wèi shénme?","vi":"Bạn thích thành phố nào nhất? Vì sao?"}]}],"speak":[]},"review":{"range":"13–15","rows":[{"l":13,"zh":"假设复句 \"……的话，就……\"","vi":"Câu phức giả thiết ……的话，就……","ex":{"zh":"你们有时间的话，就来我家做客。","py":"Nǐmen yǒu shíjiān dehuà, jiù lái wǒ jiā zuòkè.","vi":"Các em có thời gian thì đến nhà chị chơi nhé."}},{"l":13,"zh":"\"把\"字句 (4)","vi":"Câu chữ 把 (4)","ex":{"zh":"你把声音开得太大了。","py":"Nǐ bǎ shēngyīn kāi de tài dà le.","vi":"Anh mở tiếng to quá rồi."}},{"l":13,"zh":"并列复句 \"一边……，一边……\"","vi":"Câu phức đẳng lập 一边……，一边……","ex":{"zh":"咱们一边吃蛋糕，一边聊天儿吧。","py":"Zánmen yìbiān chī dàngāo, yìbiān liáotiānr ba.","vi":"Chúng ta vừa ăn bánh vừa trò chuyện nhé."}},{"l":14,"zh":"被动句 (1)","vi":"Câu bị động (1)","ex":{"zh":"这本书被别人借走了。","py":"Zhè běn shū bèi biérén jièzǒu le.","vi":"Cuốn sách này bị người khác mượn mất rồi."}},{"l":14,"zh":"承接复句 \"先……，再/然后……\"","vi":"Câu phức nối tiếp 先……，再/然后……","ex":{"zh":"我要先去图书馆借书，然后去游泳。","py":"Wǒ yào xiān qù túshūguǎn jiè shū, ránhòu qù yóuyǒng.","vi":"Mình phải ra thư viện mượn sách trước, sau đó đi bơi."}},{"l":14,"zh":"固定格式 \"×什么（啊）\"","vi":"Cấu trúc ×什么（啊）","ex":{"zh":"A：一想到要在校长、老师和那么多同学面前表演，我就有些紧张。B：紧张什么啊，我们都喜欢听你唱歌，你要相信自己。","py":"A: Yì xiǎngdào yào zài xiàozhǎng, lǎoshī hé nàme duō tóngxué miànqián biǎoyǎn, wǒ jiù yǒuxiē jǐnzhāng. B: Jǐnzhāng shénme a, wǒmen dōu xǐhuan tīng nǐ chàng gē, nǐ yào xiāngxìn zìjǐ.","vi":"A: Nghĩ tới phải biểu diễn trước bao người là mình hơi run. B: Run gì chứ, ai cũng thích nghe cậu hát, hãy tin vào bản thân."}},{"l":15,"zh":"介词 \"根据\"","vi":"Giới từ 根据","ex":{"zh":"这几年小区根据他们的需要，有了很多变化。","py":"Zhè jǐ nián xiǎoqū gēnjù tāmen de xūyào, yǒule hěn duō biànhuà.","vi":"Mấy năm nay khu nhà có nhiều thay đổi dựa theo nhu cầu của họ."}},{"l":15,"zh":"数量重叠 \"数词+量词+数词+量词\"","vi":"Lặp cụm số lượng","ex":{"zh":"我得一点儿一点儿给您讲。","py":"Wǒ děi yìdiǎnr yìdiǎnr gěi nín jiǎng.","vi":"Em phải kể dần từng chút cho chị."}},{"l":15,"zh":"固定短语 \"在……看来\"","vi":"Cụm cố định 在……看来","ex":{"zh":"在我们中国人看来，黄河像妈妈一样，养了我们几千年。","py":"Zài wǒmen Zhōngguórén kànlái, Huáng Hé xiàng māma yíyàng, yǎngle wǒmen jǐ qiān nián.","vi":"Trong mắt người Trung Quốc, Hoàng Hà như người mẹ, đã nuôi chúng tôi mấy nghìn năm."}},{"l":15,"zh":"固定短语 \"不一会儿\"","vi":"Cụm cố định 不一会儿","ex":{"zh":"难过的事情不一会儿就忘了。","py":"Nánguò de shìqing bù yíhuìr jiù wàng le.","vi":"Chuyện buồn chẳng mấy chốc đã quên."}}]}},{"id":"k3v3-b16","courseId":"k3v3","order":16,"title":"Nghe nói có những chú gấu trúc đã ra nước ngoài","titleZh":"我听说有的熊猫出国了","titlePy":"wǒ tīngshuō yǒude xióngmāo chūguó le","vocab":[{"stt":1,"hanzi":"脏","pinyin":"zāng","hanviet":"Tảng","pos":"Tính từ","meaning":"bẩn","comps":"很脏 (rất bẩn), 脏衣服 (quần áo bẩn), 又脏又小 (vừa bẩn vừa nhỏ)","example":{"zh":"你的鞋太脏了，快去洗一洗吧。","py":"Nǐ de xié tài zāng le, kuài qù xǐ yi xǐ ba.","vi":"Giày của bạn bẩn quá, mau đi giặt đi."}},{"stt":2,"hanzi":"可爱","pinyin":"kě'ài","hanviet":"Khả ái","pos":"Tính từ","meaning":"đáng yêu, dễ thương","comps":"很可爱 (rất đáng yêu), 可爱的小猫 (chú mèo con đáng yêu)","example":{"zh":"这只小狗特别可爱，大家都喜欢它。","py":"Zhè zhī xiǎo gǒu tèbié kě'ài, dàjiā dōu xǐhuan tā.","vi":"Chú cún này rất đáng yêu, ai cũng thích nó."}},{"stt":3,"hanzi":"一会儿","pinyin":"yíhuìr","hanviet":"Nhất hội nhi","pos":"Phó từ","meaning":"lúc thì … (lúc thì …)","comps":"一会儿……一会儿…… (lúc thì… lúc thì…), 等一会儿 (đợi một lát)","example":{"zh":"他一会儿看书，一会儿看手机。","py":"Tā yíhuìr kàn shū, yíhuìr kàn shǒujī.","vi":"Cậu ấy lúc thì đọc sách, lúc thì xem điện thoại."}},{"stt":4,"hanzi":"脚","pinyin":"jiǎo","hanviet":"Cước","pos":"Danh từ","meaning":"chân, bàn chân","comps":"脚边 (bên chân), 左脚 (chân trái), 大脚 (bàn chân to)","example":{"zh":"我的脚太大了，这双鞋穿不上。","py":"Wǒ de jiǎo tài dà le, zhè shuāng xié chuān bu shàng.","vi":"Chân mình to quá, đôi giày này đi không vừa."}},{"stt":5,"hanzi":"照顾","pinyin":"zhàogù","hanviet":"Chiếu cố","pos":"Động từ","meaning":"chăm sóc, trông nom","comps":"照顾孩子 (chăm con), 照顾好自己 (chăm sóc tốt bản thân)","example":{"zh":"妈妈生病的时候，我在家照顾她。","py":"Māma shēngbìng de shíhou, wǒ zài jiā zhàogù tā.","vi":"Lúc mẹ ốm, mình ở nhà chăm sóc mẹ."}},{"stt":6,"hanzi":"好像","pinyin":"hǎoxiàng","hanviet":"Hảo tượng","pos":"Động từ","meaning":"giống như","comps":"好像……一样 (giống như … vậy), 就好像 (cứ như là)","example":{"zh":"王老师对我们好像妈妈一样。","py":"Wáng lǎoshī duì wǒmen hǎoxiàng māma yíyàng.","vi":"Cô Vương đối với chúng em giống như mẹ vậy."}},{"stt":7,"hanzi":"认得","pinyin":"rènde","hanviet":"Nhận đắc","pos":"Động từ","meaning":"nhận ra, biết (mặt, chữ, đường)","comps":"认得路 (biết đường), 认得这个字 (biết chữ này)","example":{"zh":"十年没见了，我还认得他。","py":"Shí nián méi jiàn le, wǒ hái rènde tā.","vi":"Mười năm không gặp, mình vẫn nhận ra anh ấy."}},{"stt":8,"hanzi":"周末","pinyin":"zhōumò","hanviet":"Chu mạt","pos":"Danh từ","meaning":"cuối tuần","comps":"这个周末 (cuối tuần này), 周末愉快 (cuối tuần vui vẻ)","example":{"zh":"这个周末你打算做什么？","py":"Zhège zhōumò nǐ dǎsuàn zuò shénme?","vi":"Cuối tuần này bạn định làm gì?"}},{"stt":9,"hanzi":"动物园","pinyin":"dòngwùyuán","hanviet":"Động vật viên","pos":"Danh từ","meaning":"vườn bách thú, sở thú","comps":"去动物园 (đi sở thú), 北京动物园 (vườn thú Bắc Kinh)","example":{"zh":"孩子们最喜欢去动物园看动物。","py":"Háizimen zuì xǐhuan qù dòngwùyuán kàn dòngwù.","vi":"Bọn trẻ thích nhất là đi sở thú xem động vật."}},{"stt":10,"hanzi":"动物","pinyin":"dòngwù","hanviet":"Động vật","pos":"Danh từ","meaning":"động vật, con vật","comps":"小动物 (con vật nhỏ), 野生动物 (động vật hoang dã)","example":{"zh":"你最喜欢什么动物？","py":"Nǐ zuì xǐhuan shénme dòngwù?","vi":"Bạn thích con vật nào nhất?"}},{"stt":11,"hanzi":"大熊猫","pinyin":"dàxióngmāo","hanviet":"Đại hùng miêu","pos":"Danh từ","meaning":"gấu trúc lớn","comps":"熊猫 (gấu trúc), 熊猫馆 (khu gấu trúc)","example":{"zh":"大熊猫看起来胖胖的，非常可爱。","py":"Dàxióngmāo kàn qǐlai pàngpàng de, fēicháng kě'ài.","vi":"Gấu trúc trông mũm mĩm, rất đáng yêu."}},{"stt":12,"hanzi":"奇怪","pinyin":"qíguài","hanviet":"Kỳ quái","pos":"Tính từ","meaning":"lạ, kỳ lạ","comps":"很奇怪 (rất lạ), 奇怪的名字 (cái tên lạ)","example":{"zh":"真奇怪，他今天怎么没来上课？","py":"Zhēn qíguài, tā jīntiān zěnme méi lái shàngkè?","vi":"Lạ thật, sao hôm nay cậu ấy không đi học?"}},{"stt":13,"hanzi":"其实","pinyin":"qíshí","hanviet":"Kỳ thực","pos":"Phó từ","meaning":"thực ra","comps":"其实不难 (thực ra không khó), 其实是 (thực ra là)","example":{"zh":"这个问题看起来很难，其实很简单。","py":"Zhège wèntí kàn qǐlai hěn nán, qíshí hěn jiǎndān.","vi":"Câu hỏi này trông thì khó, thực ra rất đơn giản."}},{"stt":14,"hanzi":"竹子","pinyin":"zhúzi","hanviet":"Trúc tử","pos":"Danh từ","meaning":"cây trúc, cây tre","comps":"吃竹子 (ăn trúc), 竹子做的筷子 (đũa làm bằng tre)","example":{"zh":"我家后面有很多竹子。","py":"Wǒ jiā hòumiàn yǒu hěn duō zhúzi.","vi":"Sau nhà mình có rất nhiều tre."}},{"stt":15,"hanzi":"国宝","pinyin":"guóbǎo","hanviet":"Quốc bảo","pos":"Danh từ","meaning":"quốc bảo, báu vật quốc gia","comps":"中国的国宝 (quốc bảo của Trung Quốc)","example":{"zh":"大熊猫是中国的国宝，大家都很喜欢它。","py":"Dàxióngmāo shì Zhōngguó de guóbǎo, dàjiā dōu hěn xǐhuan tā.","vi":"Gấu trúc là quốc bảo của Trung Quốc, ai cũng rất quý nó."}},{"stt":16,"hanzi":"全","pinyin":"quán","hanviet":"Toàn","pos":"Tính từ","meaning":"toàn, cả","comps":"全世界 (toàn thế giới), 全家 (cả nhà), 全班 (cả lớp)","example":{"zh":"周末我们全家一起去爬山了。","py":"Zhōumò wǒmen quán jiā yìqǐ qù pá shān le.","vi":"Cuối tuần cả nhà mình cùng đi leo núi."}},{"stt":17,"hanzi":"野生","pinyin":"yěshēng","hanviet":"Dã sinh","pos":"Tính từ","meaning":"hoang dã","comps":"野生动物 (động vật hoang dã), 野生大熊猫 (gấu trúc hoang dã)","example":{"zh":"野生的大熊猫生活在山里。","py":"Yěshēng de dàxióngmāo shēnghuó zài shān li.","vi":"Gấu trúc hoang dã sống ở trong núi."}},{"stt":18,"hanzi":"关于","pinyin":"guānyú","hanviet":"Quan ư","pos":"Giới từ","meaning":"về, liên quan đến","comps":"关于这个问题 (về vấn đề này), 关于中国的书 (sách về TQ)","example":{"zh":"我想买一本关于中国历史的书。","py":"Wǒ xiǎng mǎi yì běn guānyú Zhōngguó lìshǐ de shū.","vi":"Mình muốn mua một cuốn sách về lịch sử Trung Quốc."}},{"stt":19,"hanzi":"饱","pinyin":"bǎo","hanviet":"Bão","pos":"Tính từ","meaning":"no (ăn no)","comps":"吃饱了 (ăn no rồi), 没吃饱 (chưa no)","example":{"zh":"我已经吃饱了，不能再吃了。","py":"Wǒ yǐjīng chībǎo le, bù néng zài chī le.","vi":"Mình no rồi, không ăn thêm được nữa."}},{"stt":20,"hanzi":"张","pinyin":"zhāng","hanviet":"Trương","pos":"Động từ","meaning":"há, mở (miệng)","comps":"张嘴 (há miệng), 张着嘴 (đang há miệng)","example":{"zh":"请张嘴，让医生看一下。","py":"Qǐng zhāng zuǐ, ràng yīshēng kàn yíxià.","vi":"Há miệng ra để bác sĩ xem một chút nhé."}},{"stt":21,"hanzi":"嘴","pinyin":"zuǐ","hanviet":"Chuỷ","pos":"Danh từ","meaning":"miệng, mồm","comps":"张嘴 (há miệng), 嘴里 (trong miệng), 大嘴 (miệng to)","example":{"zh":"他嘴里吃着东西，不能说话。","py":"Tā zuǐ li chīzhe dōngxi, bù néng shuōhuà.","vi":"Miệng cậu ấy đang nhai đồ ăn, không nói được."}},{"stt":22,"hanzi":"身边","pinyin":"shēnbiān","hanviet":"Thân biên","pos":"Danh từ","meaning":"bên cạnh, bên mình","comps":"在我身边 (ở bên tôi), 身边的人 (người bên cạnh)","example":{"zh":"爸妈不在身边，你要照顾好自己。","py":"Bà mā bú zài shēnbiān, nǐ yào zhàogù hǎo zìjǐ.","vi":"Bố mẹ không ở bên, con phải tự chăm sóc tốt bản thân."}},{"stt":23,"hanzi":"半天","pinyin":"bàntiān","hanviet":"Bán thiên","pos":"Số lượng từ","meaning":"cả buổi, hồi lâu","comps":"等了半天 (đợi mãi), 半天没说话 (hồi lâu không nói)","example":{"zh":"我找了半天，也没找到我的手机。","py":"Wǒ zhǎole bàntiān, yě méi zhǎodào wǒ de shǒujī.","vi":"Mình tìm cả buổi mà vẫn không thấy điện thoại."}},{"stt":24,"hanzi":"脸","pinyin":"liǎn","hanviet":"Kiểm","pos":"Danh từ","meaning":"mặt, khuôn mặt","comps":"洗脸 (rửa mặt), 脸红 (đỏ mặt), 小脸 (khuôn mặt nhỏ)","example":{"zh":"早上起床以后，我先洗脸，再吃早饭。","py":"Zǎoshang qǐchuáng yǐhòu, wǒ xiān xǐ liǎn, zài chī zǎofàn.","vi":"Sáng ngủ dậy, mình rửa mặt trước rồi mới ăn sáng."}},{"stt":25,"hanzi":"大人","pinyin":"dàren","hanviet":"Đại nhân","pos":"Danh từ","meaning":"người lớn","comps":"大人和孩子 (người lớn và trẻ em), 像个大人 (như người lớn)","example":{"zh":"这个电影大人和孩子都喜欢看。","py":"Zhège diànyǐng dàren hé háizi dōu xǐhuan kàn.","vi":"Bộ phim này người lớn và trẻ em đều thích xem."}},{"stt":26,"hanzi":"喜爱","pinyin":"xǐ'ài","hanviet":"Hỉ ái","pos":"Động từ","meaning":"yêu thích","comps":"最喜爱的 (yêu thích nhất), 受到喜爱 (được yêu thích)","example":{"zh":"这本书受到了很多孩子的喜爱。","py":"Zhè běn shū shòudàole hěn duō háizi de xǐ'ài.","vi":"Cuốn sách này được rất nhiều trẻ em yêu thích."}}],"hanzi":[{"char":"脏","pinyin":"zāng","hanviet":"Tảng","chars":["脏"],"story":"脏 = 月 (thịt) + 庄. Chữ giản thể dùng chung cho hai nghĩa: zāng = bẩn (bài này) và zàng = nội tạng (心脏). Trái nghĩa: 干净."},{"char":"可爱","pinyin":"kě'ài","hanviet":"Khả ái","chars":["可","爱"],"story":"可 = đáng, có thể; 爱 = yêu. 可爱 = đáng để yêu → dễ thương (Khả ái). Hay khen trẻ con, con vật: 可爱的孩子, 可爱的小猫."},{"char":"一会儿","pinyin":"yíhuìr","hanviet":"Nhất hội nhi","chars":["一","会","儿"],"story":"会 = khoảnh khắc; 一会儿 = một lát (等一会儿). Lặp hai lần: 一会儿A，一会儿B = lúc thì A, lúc thì B (ngữ pháp 1). Đọc yíhuìr; ôn 不一会儿 bài 15."},{"char":"脚","pinyin":"jiǎo","hanviet":"Cước","chars":["脚"],"story":"脚 = 月 (thịt — bộ phận cơ thể) + 却 → bàn chân. 脚 = bàn chân (chỗ đi giày); 腿 (bài 8) = cẳng chân. 脚边 = bên chân."},{"char":"照顾","pinyin":"zhàogù","hanviet":"Chiếu cố","chars":["照","顾"],"story":"照 = soi sáng (照相, 照片); 顾 = 页 (cái đầu) → ngoái đầu trông. 照顾 = để mắt trông nom → chăm sóc. Khác tiếng Việt \"chiếu cố\" (hạ cố, nể tình)."},{"char":"好像","pinyin":"hǎoxiàng","hanviet":"Hảo tượng","chars":["好","像"],"story":"Bài 1: 好像 là phó từ \"hình như\" (他好像病了). Bài 16: 好像 là động từ \"giống như\", hay đi với 一样: 它就好像我们的孩子 = nó cứ như con của chúng tôi."},{"char":"认得","pinyin":"rènde","hanviet":"Nhận đắc","chars":["认","得"],"story":"认 = 讠 (lời) + 人 → nhận biết (认识, 认真). 得 đọc thanh nhẹ de. 认得 = nhìn là nhận ra (người, chữ, đường) — khẩu ngữ, gần nghĩa 认识."},{"char":"周末","pinyin":"zhōumò","hanviet":"Chu mạt","chars":["周","末"],"story":"周 = tuần (一周); 末 = 木 + nét ngang trên ngọn → ngọn, phần cuối. 周末 = cuối tuần (Chu mạt)."},{"char":"动物园","pinyin":"dòngwùyuán","hanviet":"Động vật viên","chars":["动","物","园"],"story":"园 = 囗 (hàng rào) + 元 → khu vườn có rào (公园, 花园). 动物园 = vườn nuôi động vật → vườn bách thú. 北京动物园 là vườn thú nổi tiếng ở Bắc Kinh."},{"char":"动物","pinyin":"dòngwù","hanviet":"Động vật","chars":["动","物"],"story":"动 = 云 + 力 (sức) → cử động (运动). 物 = 牛 + 勿 → vật, đồ vật (礼物). 动物 = vật biết cử động → động vật."},{"char":"大熊猫","pinyin":"dàxióngmāo","hanviet":"Đại hùng miêu","chars":["大","熊","猫"],"story":"熊 = 能 + 灬 → con gấu; 猫 = 犭 + 苗 → con mèo. Tên đúng ra là 猫熊 = gấu mèo, sau quen gọi 熊猫. 大熊猫 = gấu trúc lớn (Đại hùng miêu)."},{"char":"奇怪","pinyin":"qíguài","hanviet":"Kỳ quái","chars":["奇","怪"],"story":"奇 = 大 + 可 → lạ thường; 怪 = 忄 (lòng) + 圣 → trong lòng thấy lạ. 奇怪 thường chỉ là \"lạ\", nhẹ hơn \"kỳ quái\" tiếng Việt."},{"char":"其实","pinyin":"qíshí","hanviet":"Kỳ thực","chars":["其","实"],"story":"其 = cái đó; 实 = 宀 + 头 → thật, chắc. 其实 = sự thật là → thực ra (Kỳ thực); hay đứng đầu vế sau, nói điều khác với cái mình tưởng."},{"char":"竹子","pinyin":"zhúzi","hanviet":"Trúc tử","chars":["竹","子"],"story":"竹 = hình hai cành trúc rủ lá; bộ ⺮ (trúc) có trong 筷子, 笔, 第. 子 = hậu tố. 竹子 = cây tre, trúc — món ăn chính của gấu trúc."},{"char":"国宝","pinyin":"guóbǎo","hanviet":"Quốc bảo","chars":["国","宝"],"story":"国 = 囗 + 玉 → đất nước; 宝 = 宀 + 玉 → ngọc quý cất trong nhà → báu vật. 国宝 = báu vật quốc gia (Quốc bảo)."},{"char":"全","pinyin":"quán","hanviet":"Toàn","chars":["全"],"story":"全 = 人 + 王 (ngọc) → ngọc nguyên vẹn → toàn, cả. Đứng trước danh từ: 全世界, 全家, 全班. Khác 都 (phó từ, đứng trước động từ)."},{"char":"野生","pinyin":"yěshēng","hanviet":"Dã sinh","chars":["野","生"],"story":"野 = 里 (làng) + 予 → đồng nội ngoài làng, hoang dã; 生 = sinh sống. 野生 = sống ngoài tự nhiên (Dã sinh) — ngược với 养 (nuôi, bài 15)."},{"char":"关于","pinyin":"guānyú","hanviet":"Quan ư","chars":["关","于"],"story":"关 = then cửa → liên quan (关系 bài 15); 于 = ở, về. 关于 = về, liên quan đến (Quan ư) — ngữ pháp 2 hôm nay."},{"char":"饱","pinyin":"bǎo","hanviet":"Bão","chars":["饱"],"story":"饱 = 饣 (ăn) + 包 (cái bọc) → ăn đến bụng căng như cái bọc → no. Trái nghĩa: 饿 (bài 2). 吃饱 = ăn + kết quả no."},{"char":"张","pinyin":"zhāng","hanviet":"Trương","chars":["张"],"story":"张 = 弓 (cây cung) + 长 → giương cung → mở rộng ra. Bài 2: lượng từ (一张照片); bài 16: động từ há, mở (张嘴, 张着嘴). Còn là họ: 张校长."},{"char":"嘴","pinyin":"zuǐ","hanviet":"Chuỷ","chars":["嘴"],"story":"嘴 = 口 (miệng) + 觜 → cái mồm. 嘴 dùng trong khẩu ngữ (张嘴, 嘴里); 口 dùng trong từ ghép (口语, 门口)."},{"char":"身边","pinyin":"shēnbiān","hanviet":"Thân biên","chars":["身","边"],"story":"身 = thân người; 边 = bên (旁边). 身边 = bên cạnh người → bên mình. 在……身边 = ở bên cạnh ai đó."},{"char":"半天","pinyin":"bàntiān","hanviet":"Bán thiên","chars":["半","天"],"story":"半 = nửa; 天 = ngày. Nghĩa đen: nửa ngày; trong khẩu ngữ: cả buổi, hồi lâu (cảm thấy lâu): 半天没动 = nằm im mãi."},{"char":"脸","pinyin":"liǎn","hanviet":"Kiểm","chars":["脸"],"story":"脸 = 月 (thịt — bộ phận cơ thể) + 佥 → khuôn mặt. Cùng bộ 月: 脚, 腿, 胖. 洗脸 = rửa mặt; 脸红 = đỏ mặt."},{"char":"大人","pinyin":"dàren","hanviet":"Đại nhân","chars":["大","人"],"story":"大 + 人 = người lớn; 人 đọc thanh nhẹ: dàren. Khác \"đại nhân\" tiếng Việt (quan lớn). Đối lập: 孩子 (trẻ con)."},{"char":"喜爱","pinyin":"xǐ'ài","hanviet":"Hỉ ái","chars":["喜","爱"],"story":"喜 = vui (喜欢); 爱 = yêu. 喜爱 ≈ 喜欢 nhưng trang trọng hơn, hay dùng trong văn viết: 最喜爱的, 受到……的喜爱."}],"grammar":[{"title":"（主语）+ 一会儿 + A，一会儿 + B","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>一会儿</b><small>lúc thì</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>A</b><small>việc / trạng thái 1</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，一会儿</b><small>lúc thì</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>B</b><small>việc / trạng thái 2</small></span></div>","summary":"<p class=\"gr-lead\">Lúc thì A, lúc thì B</p><ul><li>A, B là <b>hai hành động</b> thay nhau nhanh (<span class=\"zh\">一会儿进来，一会儿出去</span>) hoặc <b>hai trạng thái trái ngược</b> (<span class=\"zh\">一会儿冷，一会儿热</span>).</li><li>Chủ ngữ đứng <b>trước</b> 一会儿 thứ nhất; một mình <span class=\"zh\">一会儿</span> = một lát: <span class=\"zh\">等一会儿</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">一会儿……，一会儿…… · hai kiểu</span> · Cấu trúc</h4><p>Lúc thì …, lúc thì …</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Hai hành động</div><div class=\"fx-row\"><span class=\"fx-p\"><b>他</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>一会儿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>进来</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>一会儿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>出去</b></span></div><div class=\"fx-ex zh\">他一会儿进来，一会儿出去，忙得很。</div><div class=\"fx-lbl\">Trạng thái trái ngược</div><div class=\"fx-row\"><span class=\"fx-p\"><b>天气</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>一会儿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>冷</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>一会儿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>热</b></span></div><div class=\"fx-ex zh\">最近天气变化很快，一会儿冷，一会儿热。</div><div class=\"fx-lbl\">Một mình · một lát</div><div class=\"fx-row\"><span class=\"fx-p\"><b>你</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>等</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>一会儿</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>，我马上来</b></span></div><div class=\"fx-ex zh\">你等一会儿，我马上就来。</div></div><p class=\"gr-key\"><span class=\"zh\">一会儿</span> một mình = một lát　·　<span class=\"zh\">不一会儿</span> (bài 15) = chẳng mấy chốc</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">它一会儿在你脚边睡觉，一会儿在你身上爬。</span> = Nó lúc thì ngủ bên chân em, lúc thì trèo lên người em.</p>","note":"<b>Lưu ý:</b> Phải đủ hai 一会儿: ✗ <span class=\"zh\">他一会儿看书，看手机</span> → ✓ <span class=\"zh\">他一会儿看书，一会儿看手机</span>","examples":[{"zh":"它一会儿在你脚边睡觉，一会儿在你身上爬。","py":"Tā yíhuìr zài nǐ jiǎo biān shuìjiào, yíhuìr zài nǐ shēn shang pá.","vi":"Nó lúc thì ngủ bên chân em, lúc thì trèo lên người em."},{"zh":"他一会儿进来，一会儿出去，忙得很。","py":"Tā yíhuìr jìnlai, yíhuìr chūqu, máng de hěn.","vi":"Anh ấy lúc thì đi vào, lúc thì đi ra, bận lắm."},{"zh":"最近天气变化很快，一会儿冷，一会儿热。","py":"Zuìjìn tiānqì biànhuà hěn kuài, yíhuìr lěng, yíhuìr rè.","vi":"Dạo này thời tiết thay đổi nhanh, lúc thì lạnh, lúc thì nóng."}],"exercises":[]},{"title":"关于 + 名词，…… · 关于 + 名词 + 的 + 名词","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>关于</b><small>về</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>Danh từ</b><small>vấn đề / chuyện …</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>，Chủ ngữ + Vị ngữ</b></span></div>","summary":"<p class=\"gr-lead\">Về …, liên quan đến …</p><ul><li>Đầu câu: <span class=\"zh\">关于 + DT，……</span> — nêu <b>chủ đề</b> trước rồi mới nói: <span class=\"zh\">关于比赛的时间，……</span></li><li>Làm định ngữ: <span class=\"zh\">关于 + DT + 的 + DT</span>: <span class=\"zh\">关于中国历史的书</span> = sách về lịch sử TQ.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">关于 · hai vị trí</span> · Cấu trúc</h4><p>Về …</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Đầu câu</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>关于</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>这个问题</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>，我得慢慢给你讲</b></span></div><div class=\"fx-ex zh\">关于这个问题，我得慢慢给你讲。</div><div class=\"fx-lbl\">Đầu câu</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>关于</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>比赛的时间</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>，我明天告诉大家</b></span></div><div class=\"fx-ex zh\">关于比赛的时间，我明天一定告诉大家。</div><div class=\"fx-lbl\">Định ngữ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>一本</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>关于</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>中国历史</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>的书</b></span></div><div class=\"fx-ex zh\">我想买一本关于中国历史的书。</div></div><p class=\"gr-key\">Hay gặp: <span class=\"zh\">关于这个问题 · 关于他的要求 · 关于……的事情 / 方法 / 书</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">关于这个问题，我得慢慢给你讲。</span> = Về vấn đề này, mẹ phải từ từ kể cho con.</p>","note":"<b>Lưu ý:</b> Đứng trước chủ ngữ: ✗ <span class=\"zh\">我关于这个问题不太了解</span> → ✓ <span class=\"zh\">关于这个问题，我不太了解</span>","examples":[{"zh":"关于这个问题，我得慢慢给你讲。","py":"Guānyú zhège wèntí, wǒ děi mànmàn gěi nǐ jiǎng.","vi":"Về vấn đề này, mẹ phải từ từ kể cho con."},{"zh":"关于他的要求，我们还要开会以后再决定。","py":"Guānyú tā de yāoqiú, wǒmen hái yào kāihuì yǐhòu zài juédìng.","vi":"Về yêu cầu của anh ấy, chúng tôi còn phải họp xong rồi mới quyết định."},{"zh":"关于比赛的时间，我明天一定告诉大家。","py":"Guānyú bǐsài de shíjiān, wǒ míngtiān yídìng gàosu dàjiā.","vi":"Về thời gian thi đấu, ngày mai tôi nhất định sẽ báo mọi người."}],"exercises":[]},{"title":"一般来说，……","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>一般来说</b><small>nói chung</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>，Chủ ngữ</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>Điều thường thấy</b></span></div>","summary":"<p class=\"gr-lead\">Nói chung, thông thường</p><ul><li>Nêu điều <b>đúng trong phần lớn trường hợp</b>; đứng <b>đầu câu</b>, sau có dấu phẩy.</li><li>Gần nghĩa phó từ <span class=\"zh\">一般</span> (bài 10), nhưng <span class=\"zh\">一般</span> đứng sau chủ ngữ: <span class=\"zh\">我一般七点起床</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">一般来说 · 一般</span> · Đối chiếu bài 10</h4><p>Nói chung · thường</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Đầu câu</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>一般来说</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>，熊猫</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>每天要睡很多次觉</b></span></div><div class=\"fx-ex zh\">一般来说，熊猫每天要睡很多次觉。</div><div class=\"fx-lbl\">Đầu câu</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>一般来说</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>，学习外语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>需要多练习</b></span></div><div class=\"fx-ex zh\">一般来说，学习外语需要多练习。</div><div class=\"fx-lbl\">一般 · bài 10</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>一般</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>七点起床</b></span></div><div class=\"fx-ex zh\">我一般早上七点起床。</div></div><p class=\"gr-key\"><span class=\"zh\">一般来说</span> = đầu câu, nói chuyện chung　·　<span class=\"zh\">一般</span> = sau chủ ngữ, thói quen của ai đó</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">一般来说，熊猫每天要睡很多次觉。</span> = Nói chung, gấu trúc mỗi ngày phải ngủ rất nhiều lần.</p>","note":"<b>Lưu ý:</b> Không dùng cho một việc cụ thể: ✗ <span class=\"zh\">一般来说，他昨天来晚了</span> → ✓ <span class=\"zh\">一般来说，他来得很早</span>","examples":[{"zh":"一般来说，熊猫每天要睡很多次觉。","py":"Yìbān lái shuō, xióngmāo měi tiān yào shuì hěn duō cì jiào.","vi":"Nói chung, gấu trúc mỗi ngày phải ngủ rất nhiều lần."},{"zh":"一般来说，这种树每年开一次花。","py":"Yìbān lái shuō, zhè zhǒng shù měi nián kāi yí cì huā.","vi":"Thông thường, loại cây này mỗi năm ra hoa một lần."},{"zh":"一般来说，学习外语需要多练习。","py":"Yìbān lái shuō, xuéxí wàiyǔ xūyào duō liànxí.","vi":"Nói chung, học ngoại ngữ cần luyện tập nhiều."}],"exercises":[]},{"title":"A + 比 + B + 多/少/早/晚 + 动词 + 数量短语","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>A 比 B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>多 / 少 / 早 / 晚</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>Động từ</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>Số lượng</b><small>一个小时 · 三个…</small></span></div>","summary":"<p class=\"gr-lead\">A hơn B … bao nhiêu</p><ul><li><span class=\"zh\">多 / 少 / 早 / 晚</span> đứng <b>trước động từ</b>, cụm số lượng đứng <b>sau động từ</b>: <span class=\"zh\">多吃了三个饺子</span>.</li><li>Tiếng Việt nói \"đến <b>muộn hơn</b> mười phút\" — tiếng Trung đưa <span class=\"zh\">晚</span> lên trước động từ.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">多 / 少 / 早 / 晚 + 动词</span> · Bốn từ</h4><p>Nhiều / ít / sớm / muộn hơn</p><div class=\"gr-formula\"><div class=\"fx-lbl\">多 · nhiều hơn</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>哥哥比弟弟</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>多</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>吃了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>三个饺子</b></span></div><div class=\"fx-ex zh\">哥哥比弟弟多吃了三个饺子。</div><div class=\"fx-lbl\">早 · sớm hơn</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>冬天比夏天</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>早</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>关门</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>一个小时</b></span></div><div class=\"fx-ex zh\">冬天比夏天早关门一个小时。</div><div class=\"fx-lbl\">晚 · muộn hơn</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>我比他</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>晚</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>到了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>十分钟</b></span></div><div class=\"fx-ex zh\">我比他晚到了十分钟。</div></div><p class=\"gr-key\"><span class=\"zh\">少</span> cũng vậy: <span class=\"zh\">这个月比上个月少花了五百块</span>　·　ôn <span class=\"zh\">A比B + 形容词</span>: <span class=\"zh\">他比我高</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">冬天比夏天早关门一个小时。</span> = Mùa đông đóng cửa sớm hơn mùa hè một tiếng.</p>","note":"<b>Lưu ý:</b> ✗ <span class=\"zh\">我比他到晚了十分钟</span> → ✓ <span class=\"zh\">我比他晚到了十分钟</span>","examples":[{"zh":"冬天比夏天早关门一个小时。","py":"Dōngtiān bǐ xiàtiān zǎo guānmén yí ge xiǎoshí.","vi":"Mùa đông đóng cửa sớm hơn mùa hè một tiếng."},{"zh":"哥哥比弟弟多吃了三个饺子。","py":"Gēge bǐ dìdi duō chīle sān ge jiǎozi.","vi":"Anh ăn nhiều hơn em ba cái sủi cảo."},{"zh":"我比他晚到了十分钟。","py":"Wǒ bǐ tā wǎn dàole shí fēnzhōng.","vi":"Tôi đến muộn hơn anh ấy mười phút."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在宠物店","titleVi":"Cửa hàng thú cưng — xem mèo con","lines":[{"speaker":"小","name":"Tiểu Tuyết","zh":"这只小猫你们养了多久了？","py":"Zhè zhī xiǎo māo nǐmen yǎngle duō jiǔ le?","vi":"Chú mèo con này các anh chị nuôi bao lâu rồi ạ?"},{"speaker":"员","name":"Nhân viên","zh":"已经一年多了。第一天看见它的时候，它又脏又小。","py":"Yǐjīng yì nián duō le. Dì-yī tiān kànjiàn tā de shíhou, tā yòu zāng yòu xiǎo.","vi":"Hơn một năm rồi. Hôm đầu tiên thấy nó, nó vừa bẩn vừa bé."},{"speaker":"小","name":"Tiểu Tuyết","zh":"现在它变得又干净又漂亮了。","py":"Xiànzài tā biàn de yòu gānjìng yòu piàoliang le.","vi":"Giờ nó đã trở nên vừa sạch vừa xinh rồi."},{"speaker":"员","name":"Nhân viên","zh":"是啊。它还特别可爱，一会儿在你脚边睡觉，一会儿在你身上爬。","py":"Shì a. Tā hái tèbié kě'ài, yíhuìr zài nǐ jiǎo biān shuìjiào, yíhuìr zài nǐ shēn shang pá.","vi":"Đúng vậy. Nó còn rất đáng yêu, lúc thì ngủ bên chân em, lúc thì trèo lên người em."},{"speaker":"小","name":"Tiểu Tuyết","zh":"你们把它照顾得真好。","py":"Nǐmen bǎ tā zhàogù de zhēn hǎo.","vi":"Các anh chị chăm nó tốt thật."},{"speaker":"员","name":"Nhân viên","zh":"它就好像我们的孩子，我们照顾它，它也认得我们了。","py":"Tā jiù hǎoxiàng wǒmen de háizi, wǒmen zhàogù tā, tā yě rènde wǒmen le.","vi":"Nó cứ như con của chúng tôi, chúng tôi chăm nó, nó cũng nhận ra chúng tôi rồi."},{"speaker":"小","name":"Tiểu Tuyết","zh":"妈妈，我们家也养一只小猫吧。","py":"Māma, wǒmen jiā yě yǎng yì zhī xiǎo māo ba.","vi":"Mẹ ơi, nhà mình cũng nuôi một con mèo con đi."},{"speaker":"雪","name":"Nhất Tuyết","zh":"咱们没时间照顾，还是别养了，我周末带你们去北京动物园看动物吧。","py":"Zánmen méi shíjiān zhàogù, háishi bié yǎng le, wǒ zhōumò dài nǐmen qù Běijīng Dòngwùyuán kàn dòngwù ba.","vi":"Nhà mình không có thời gian chăm, thôi đừng nuôi, cuối tuần mẹ dẫn các con đi vườn thú Bắc Kinh xem động vật nhé."}]},{"titleZh":"课文二 · 在动物园","titleVi":"Vườn thú — vừa đi vừa trò chuyện","lines":[{"speaker":"弟","name":"Tiểu Minh","zh":"妈妈，大熊猫这个名字很奇怪，它们跟猫有什么关系？","py":"Māma, dàxióngmāo zhège míngzi hěn qíguài, tāmen gēn māo yǒu shénme guānxi?","vi":"Mẹ ơi, cái tên \"gấu trúc\" (gấu mèo) lạ quá, chúng có liên quan gì đến mèo ạ?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"这个问题问得好，它们跟猫没什么关系，其实应该叫大猫熊。","py":"Zhège wèntí wèn de hǎo, tāmen gēn māo méi shénme guānxi, qíshí yīnggāi jiào dà māoxióng.","vi":"Con hỏi hay lắm, chúng chẳng liên quan gì đến mèo, thực ra phải gọi là \"mèo gấu\" mới đúng."},{"speaker":"弟","name":"Tiểu Minh","zh":"大熊猫为什么只吃竹子不吃肉？","py":"Dàxióngmāo wèi shénme zhǐ chī zhúzi bù chī ròu?","vi":"Sao gấu trúc chỉ ăn trúc mà không ăn thịt ạ?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"它们跟人一样，也可以吃肉，但是对肉不感兴趣。","py":"Tāmen gēn rén yíyàng, yě kěyǐ chī ròu, dànshì duì ròu bù gǎn xìngqù.","vi":"Chúng cũng như người, ăn thịt được, nhưng không hứng thú với thịt."},{"speaker":"弟","name":"Tiểu Minh","zh":"大熊猫为什么是中国的国宝？","py":"Dàxióngmāo wèi shénme shì Zhōngguó de guóbǎo?","vi":"Vì sao gấu trúc là quốc bảo của Trung Quốc ạ?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"全世界只有中国有野生大熊猫，中国是大熊猫的家。","py":"Quán shìjiè zhǐ yǒu Zhōngguó yǒu yěshēng dàxióngmāo, Zhōngguó shì dàxióngmāo de jiā.","vi":"Cả thế giới chỉ Trung Quốc có gấu trúc hoang dã, Trung Quốc là nhà của gấu trúc."},{"speaker":"弟","name":"Tiểu Minh","zh":"我听说有的熊猫出国了，他们去哪儿了？","py":"Wǒ tīngshuō yǒude xióngmāo chūguó le, tāmen qù nǎr le?","vi":"Con nghe nói có những con gấu trúc ra nước ngoài rồi, chúng đi đâu vậy ạ?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"关于这个问题，我得慢慢给你讲。","py":"Guānyú zhège wèntí, wǒ děi mànmàn gěi nǐ jiǎng.","vi":"Về vấn đề này, mẹ phải từ từ kể cho con."},{"speaker":"小","name":"Tiểu Tuyết","zh":"弟弟，你真是“十万个为什么”。","py":"Dìdi, nǐ zhēn shì “Shí Wàn Ge Wèi Shénme”.","vi":"Em trai, em đúng là \"Mười vạn câu hỏi vì sao\"."}]},{"titleZh":"课文三 · 在熊猫馆","titleVi":"Khu gấu trúc — ngắm gấu trúc ăn ngủ","lines":[{"speaker":"小","name":"Tiểu Tuyết","zh":"这只大熊猫一会儿爬上去，一会儿跳下来，可爱极了！","py":"Zhè zhī dàxióngmāo yíhuìr pá shàngqu, yíhuìr tiào xiàlai, kě'ài jí le!","vi":"Con gấu trúc này lúc thì trèo lên, lúc thì nhảy xuống, đáng yêu quá!"},{"speaker":"雪","name":"Nhất Tuyết","zh":"它好像还没吃饱，站起来张着嘴找吃的呢。","py":"Tā hǎoxiàng hái méi chībǎo, zhàn qǐlai zhāngzhe zuǐ zhǎo chī de ne.","vi":"Hình như nó vẫn chưa no, đang đứng dậy há miệng tìm đồ ăn kìa."},{"speaker":"小","name":"Tiểu Tuyết","zh":"它身边那只熊猫半天没动，是不是在睡觉呢？","py":"Tā shēnbiān nà zhī xióngmāo bàntiān méi dòng, shì bu shì zài shuìjiào ne?","vi":"Con gấu trúc bên cạnh nó nằm im mãi, có phải đang ngủ không mẹ?"},{"speaker":"雪","name":"Nhất Tuyết","zh":"我看不见它的脸，可能是吧。一般来说，熊猫每天要睡很多次觉。","py":"Wǒ kàn bu jiàn tā de liǎn, kěnéng shì ba. Yìbān lái shuō, xióngmāo měi tiān yào shuì hěn duō cì jiào.","vi":"Mẹ không thấy mặt nó, chắc vậy. Nói chung, gấu trúc mỗi ngày phải ngủ rất nhiều lần."},{"speaker":"小","name":"Tiểu Tuyết","zh":"对，除了睡觉以外，很多时间都在吃东西。","py":"Duì, chúle shuìjiào yǐwài, hěn duō shíjiān dōu zài chī dōngxi.","vi":"Vâng, ngoài ngủ ra, phần lớn thời gian chúng đều ăn."},{"speaker":"弟","name":"Tiểu Minh","zh":"大熊猫的生活真舒服啊！","py":"Dàxióngmāo de shēnghuó zhēn shūfu a!","vi":"Cuộc sống của gấu trúc sướng thật đấy!"},{"speaker":"小","name":"Tiểu Tuyết","zh":"妈妈，您帮我和这两只大熊猫照一张照片吧。","py":"Māma, nín bāng wǒ hé zhè liǎng zhī dàxióngmāo zhào yì zhāng zhàopiàn ba.","vi":"Mẹ ơi, mẹ chụp giúp con một tấm với hai con gấu trúc này nhé."}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — Nhất Tuyết viết nhật ký","para":true,"speaker":"雪","lines":[{"zh":"今天我带小雪和小明去动物园玩了。","py":"Jīntiān wǒ dài Xiǎoxuě hé Xiǎomíng qù dòngwùyuán wán le.","vi":"Hôm nay tôi dẫn Tiểu Tuyết và Tiểu Minh đi chơi vườn thú."},{"zh":"北京动物园是中国很有名的动物园，里面有非常多的动物，当然，大人和孩子最喜爱的还是大熊猫。","py":"Běijīng Dòngwùyuán shì Zhōngguó hěn yǒumíng de dòngwùyuán, lǐmian yǒu fēicháng duō de dòngwù, dāngrán, dàren hé háizi zuì xǐ'ài de háishi dàxióngmāo.","vi":"Vườn thú Bắc Kinh là vườn thú rất nổi tiếng của Trung Quốc, bên trong có rất nhiều động vật; tất nhiên, thứ người lớn và trẻ em yêu thích nhất vẫn là gấu trúc."},{"zh":"每天有很多游客去熊猫馆，他们带着相机去给可爱的大熊猫拍照。","py":"Měi tiān yǒu hěn duō yóukè qù xióngmāoguǎn, tāmen dàizhe xiàngjī qù gěi kě'ài de dàxióngmāo pāizhào.","vi":"Ngày nào cũng có rất nhiều du khách đến khu gấu trúc, họ mang theo máy ảnh để chụp những chú gấu trúc đáng yêu."},{"zh":"动物园早上七点半开门，晚上七点关门，冬天比夏天游客少，所以也比平时早关门一个小时。","py":"Dòngwùyuán zǎoshang qī diǎn bàn kāimén, wǎnshang qī diǎn guānmén, dōngtiān bǐ xiàtiān yóukè shǎo, suǒyǐ yě bǐ píngshí zǎo guānmén yí ge xiǎoshí.","vi":"Vườn thú mở cửa lúc bảy giờ rưỡi sáng, đóng cửa lúc bảy giờ tối; mùa đông khách ít hơn mùa hè nên cũng đóng cửa sớm hơn ngày thường một tiếng."},{"zh":"如果第一次来北京旅游，跟家人一起去北京动物园是个不错的选择。","py":"Rúguǒ dì-yī cì lái Běijīng lǚyóu, gēn jiārén yìqǐ qù Běijīng Dòngwùyuán shì ge búcuò de xuǎnzé.","vi":"Nếu lần đầu đến Bắc Kinh du lịch, cùng gia đình đi vườn thú Bắc Kinh là một lựa chọn không tồi."}]}]},"extra":[],"activity":{"act":[{"zh":"多人活动","py":"duōrén huódòng","tag":"Hoạt động nhóm","mean":"Giới thiệu một con vật","q":{"zh":"四人一组，选一个有特色的动物，讨论以后向全班介绍。","py":"Sì rén yì zǔ, xuǎn yí ge yǒu tèsè de dòngwù, tǎolùn yǐhòu xiàng quán bān jièshào.","vi":"Nhóm 4 người chọn một con vật có nét đặc biệt, thảo luận rồi cử đại diện giới thiệu với cả lớp."},"items":[{"zh":"这种动物长什么样？","py":"Zhè zhǒng dòngwù zhǎng shénme yàng?","vi":"Loài vật này trông như thế nào?"},{"zh":"它们一般生活在什么地方？","py":"Tāmen yìbān shēnghuó zài shénme dìfang?","vi":"Chúng thường sống ở đâu?"},{"zh":"它们的生活习惯是什么样的？","py":"Tāmen de shēnghuó xíguàn shì shénme yàng de?","vi":"Thói quen sinh hoạt của chúng thế nào?"},{"zh":"你们为什么喜欢这种动物？","py":"Nǐmen wèi shénme xǐhuan zhè zhǒng dòngwù?","vi":"Vì sao nhóm bạn thích loài vật này?"}]}],"speak":[]}},{"id":"k3v3-b17","courseId":"k3v3","order":17,"title":"Tôi phải học hỏi nhiều hơn ở những người nghiêm túc","titleZh":"我要多向认真的人学习","titlePy":"wǒ yào duō xiàng rènzhēn de rén xuéxí","vocab":[{"stt":1,"hanzi":"向","pinyin":"xiàng","hanviet":"Hướng","pos":"Giới từ","meaning":"về phía; với, ở (ai)","comps":"向前走 (đi về phía trước), 向他学习 (học hỏi anh ấy), 向东 (về phía đông)","example":{"zh":"你向前走两百米就到了。","py":"Nǐ xiàng qián zǒu liǎngbǎi mǐ jiù dào le.","vi":"Bạn đi thẳng về phía trước hai trăm mét là tới."}},{"stt":2,"hanzi":"楼梯","pinyin":"lóutī","hanviet":"Lâu thê","pos":"Danh từ","meaning":"cầu thang","comps":"走楼梯 (đi thang bộ), 上楼梯 (lên cầu thang), 楼梯口 (đầu cầu thang)","example":{"zh":"只有三层，我们走楼梯上去吧。","py":"Zhǐ yǒu sān céng, wǒmen zǒu lóutī shàngqu ba.","vi":"Chỉ có ba tầng, mình đi thang bộ lên đi."}},{"stt":3,"hanzi":"害怕","pinyin":"hàipà","hanviet":"Hại phạ","pos":"Động từ","meaning":"sợ, sợ hãi","comps":"很害怕 (rất sợ), 别害怕 (đừng sợ), 害怕考试 (sợ thi)","example":{"zh":"我妹妹很害怕一个人在家。","py":"Wǒ mèimei hěn hàipà yí ge rén zài jiā.","vi":"Em gái mình rất sợ ở nhà một mình."}},{"stt":4,"hanzi":"生气","pinyin":"shēngqì","hanviet":"Sinh khí","pos":"Động từ (li hợp)","meaning":"tức giận, giận","comps":"别生气 (đừng giận), 很生气 (rất giận), 生他的气 (giận anh ấy)","example":{"zh":"他又来晚了，老师有点儿生气。","py":"Tā yòu lái wǎn le, lǎoshī yǒudiǎnr shēngqì.","vi":"Cậu ấy lại đến muộn, cô giáo hơi giận."}},{"stt":5,"hanzi":"常见","pinyin":"cháng jiàn","hanviet":"Thường kiến","pos":"Cụm từ","meaning":"thường gặp, phổ biến","comps":"很常见 (rất thường gặp), 常见的问题 (vấn đề thường gặp)","example":{"zh":"感冒是冬天很常见的病。","py":"Gǎnmào shì dōngtiān hěn cháng jiàn de bìng.","vi":"Cảm cúm là bệnh rất thường gặp vào mùa đông."}},{"stt":6,"hanzi":"聪明","pinyin":"cōngming","hanviet":"Thông minh","pos":"Tính từ","meaning":"thông minh","comps":"很聪明 (rất thông minh), 聪明的孩子 (đứa trẻ thông minh)","example":{"zh":"这个孩子很聪明，什么都一学就会。","py":"Zhège háizi hěn cōngming, shénme dōu yì xué jiù huì.","vi":"Đứa trẻ này rất thông minh, cái gì cũng học là biết ngay."}},{"stt":7,"hanzi":"错","pinyin":"cuò","hanviet":"Thác","pos":"Danh từ","meaning":"lỗi, cái sai","comps":"出错 (mắc lỗi), 是我的错 (là lỗi của tôi), 没错 (không sai)","example":{"zh":"对不起，这次是我的错。","py":"Duìbuqǐ, zhè cì shì wǒ de cuò.","vi":"Xin lỗi, lần này là lỗi của mình."}},{"stt":8,"hanzi":"认为","pinyin":"rènwéi","hanviet":"Nhận vi","pos":"Động từ","meaning":"cho rằng, cho là","comps":"我认为 (tôi cho rằng), 大家都认为 (mọi người đều cho rằng)","example":{"zh":"我认为这个办法很好，我们试一试吧。","py":"Wǒ rènwéi zhège bànfǎ hěn hǎo, wǒmen shì yi shì ba.","vi":"Mình cho rằng cách này rất hay, chúng ta thử xem."}},{"stt":9,"hanzi":"到处","pinyin":"dàochù","hanviet":"Đáo xứ","pos":"Phó từ","meaning":"khắp nơi, đâu đâu","comps":"到处都是 (đâu đâu cũng là), 到处找 (tìm khắp nơi)","example":{"zh":"春天到了，公园里到处都是花。","py":"Chūntiān dào le, gōngyuán li dàochù dōu shì huā.","vi":"Mùa xuân đến rồi, trong công viên đâu đâu cũng là hoa."}},{"stt":10,"hanzi":"继续","pinyin":"jìxù","hanviet":"Kế tục","pos":"Động từ","meaning":"tiếp tục","comps":"继续学习 (tiếp tục học), 继续工作 (tiếp tục làm việc), 请继续 (mời tiếp tục)","example":{"zh":"休息十分钟，然后我们继续上课。","py":"Xiūxi shí fēnzhōng, ránhòu wǒmen jìxù shàngkè.","vi":"Nghỉ mười phút, sau đó chúng ta học tiếp."}},{"stt":11,"hanzi":"同意","pinyin":"tóngyì","hanviet":"Đồng ý","pos":"Động từ","meaning":"đồng ý","comps":"我同意 (tôi đồng ý), 不同意 (không đồng ý), 同意他去 (đồng ý cho anh ấy đi)","example":{"zh":"妈妈不同意我一个人去旅游。","py":"Māma bù tóngyì wǒ yí ge rén qù lǚyóu.","vi":"Mẹ không đồng ý cho mình đi du lịch một mình."}},{"stt":12,"hanzi":"可","pinyin":"kě","hanviet":"Khả","pos":"Liên từ","meaning":"nhưng (= 可是)","comps":"可是 (nhưng), 可我没时间 (nhưng mình không có thời gian)","example":{"zh":"我很想去，可我今天没有时间。","py":"Wǒ hěn xiǎng qù, kě wǒ jīntiān méiyǒu shíjiān.","vi":"Mình rất muốn đi, nhưng hôm nay mình không có thời gian."}},{"stt":13,"hanzi":"屋子","pinyin":"wūzi","hanviet":"Ốc tử","pos":"Danh từ","meaning":"căn phòng, gian phòng","comps":"屋子里 (trong phòng), 一间屋子 (một gian phòng)","example":{"zh":"这间屋子不大，但是很干净。","py":"Zhè jiān wūzi bú dà, dànshì hěn gānjìng.","vi":"Căn phòng này không to, nhưng rất sạch sẽ."}},{"stt":14,"hanzi":"有关","pinyin":"yǒuguān","hanviet":"Hữu quan","pos":"Động từ / Giới từ","meaning":"có liên quan; về","comps":"跟……有关 (liên quan đến …), 有关的书 (sách liên quan)","example":{"zh":"我想找一些跟历史有关的书。","py":"Wǒ xiǎng zhǎo yìxiē gēn lìshǐ yǒuguān de shū.","vi":"Mình muốn tìm mấy cuốn sách liên quan đến lịch sử."}},{"stt":15,"hanzi":"关机","pinyin":"guānjī","hanviet":"Quan cơ","pos":"Động từ (li hợp)","meaning":"tắt máy (điện thoại)","comps":"手机关机了 (điện thoại tắt máy), 关了机 (tắt máy rồi), 开机 (mở máy)","example":{"zh":"上课的时候请大家把手机关机。","py":"Shàngkè de shíhou qǐng dàjiā bǎ shǒujī guānjī.","vi":"Trong giờ học mời mọi người tắt điện thoại."}},{"stt":16,"hanzi":"前天","pinyin":"qiántiān","hanviet":"Tiền thiên","pos":"Danh từ","meaning":"hôm kia","comps":"前天晚上 (tối hôm kia), 前天、昨天、今天 (hôm kia, hôm qua, hôm nay)","example":{"zh":"前天我在超市看见王老师了。","py":"Qiántiān wǒ zài chāoshì kànjiàn Wáng lǎoshī le.","vi":"Hôm kia mình gặp cô Vương ở siêu thị."}},{"stt":17,"hanzi":"留学","pinyin":"liúxué","hanviet":"Lưu học","pos":"Động từ (li hợp)","meaning":"du học","comps":"出国留学 (ra nước ngoài du học), 去中国留学 (sang TQ du học), 留学生 (du học sinh)","example":{"zh":"他打算明年去中国留学。","py":"Tā dǎsuàn míngnián qù Zhōngguó liúxué.","vi":"Anh ấy định sang năm sang Trung Quốc du học."}},{"stt":18,"hanzi":"国家","pinyin":"guójiā","hanviet":"Quốc gia","pos":"Danh từ","meaning":"đất nước, quốc gia","comps":"哪个国家 (nước nào), 很多国家 (nhiều nước), 我的国家 (đất nước tôi)","example":{"zh":"你去过哪些国家？","py":"Nǐ qùguo nǎxiē guójiā?","vi":"Bạn đã đến những nước nào rồi?"}},{"stt":19,"hanzi":"比如","pinyin":"bǐrú","hanviet":"Tỷ như","pos":"Động từ","meaning":"ví dụ như","comps":"比如说 (ví dụ như là), 比如北京、上海 (ví dụ như Bắc Kinh, Thượng Hải)","example":{"zh":"我喜欢吃水果，比如苹果、香蕉。","py":"Wǒ xǐhuan chī shuǐguǒ, bǐrú píngguǒ, xiāngjiāo.","vi":"Mình thích ăn hoa quả, ví dụ như táo, chuối."}},{"stt":20,"hanzi":"查","pinyin":"chá","hanviet":"Tra","pos":"Động từ","meaning":"tra, tìm (thông tin)","comps":"查词典 (tra từ điển), 上网查 (lên mạng tra), 查一查 (tra thử)","example":{"zh":"这个字我不认识，我查一下词典。","py":"Zhège zì wǒ bú rènshi, wǒ chá yíxià cídiǎn.","vi":"Chữ này mình không biết, để mình tra từ điển chút."}},{"stt":21,"hanzi":"有用","pinyin":"yǒuyòng","hanviet":"Hữu dụng","pos":"Tính từ","meaning":"có ích, hữu ích","comps":"很有用 (rất có ích), 有用的网站 (trang web có ích), 没有用 (vô ích)","example":{"zh":"这本词典对学汉语很有用。","py":"Zhè běn cídiǎn duì xué Hànyǔ hěn yǒuyòng.","vi":"Cuốn từ điển này rất có ích cho việc học tiếng Trung."}},{"stt":22,"hanzi":"容易","pinyin":"róngyì","hanviet":"Dung dị","pos":"Tính từ","meaning":"dễ","comps":"很容易 (rất dễ), 不容易 (không dễ), 容易做 (dễ làm)","example":{"zh":"汉字不太容易写，要多练习。","py":"Hànzì bú tài róngyì xiě, yào duō liànxí.","vi":"Chữ Hán không dễ viết lắm, phải luyện nhiều."}},{"stt":23,"hanzi":"回答","pinyin":"huídá","hanviet":"Hồi đáp","pos":"Động từ","meaning":"trả lời","comps":"回答问题 (trả lời câu hỏi), 回答得很好 (trả lời rất tốt)","example":{"zh":"老师的问题，你回答得很好。","py":"Lǎoshī de wèntí, nǐ huídá de hěn hǎo.","vi":"Câu hỏi của cô, em trả lời rất tốt."}},{"stt":24,"hanzi":"方向","pinyin":"fāngxiàng","hanviet":"Phương hướng","pos":"Danh từ","meaning":"phương hướng, hướng","comps":"走错方向 (đi nhầm hướng), 学习方向 (hướng học), 方向不同 (hướng khác nhau)","example":{"zh":"我们走错方向了，应该向东走。","py":"Wǒmen zǒucuò fāngxiàng le, yīnggāi xiàng dōng zǒu.","vi":"Chúng mình đi nhầm hướng rồi, phải đi về phía đông."}},{"stt":25,"hanzi":"只有","pinyin":"zhǐyǒu","hanviet":"Chỉ hữu","pos":"Liên từ","meaning":"chỉ có (… mới …)","comps":"只有……才…… (chỉ có … mới …)","example":{"zh":"只有你去请他，他才会来。","py":"Zhǐyǒu nǐ qù qǐng tā, tā cái huì lái.","vi":"Chỉ có bạn đi mời, anh ấy mới đến."}},{"stt":26,"hanzi":"真正","pinyin":"zhēnzhèng","hanviet":"Chân chính","pos":"Phó từ","meaning":"thật sự","comps":"真正喜欢 (thật sự thích), 真正了解 (thật sự hiểu), 真正的朋友 (bạn thật sự)","example":{"zh":"到了中国以后，我才真正了解了中国文化。","py":"Dàole Zhōngguó yǐhòu, wǒ cái zhēnzhèng liǎojiěle Zhōngguó wénhuà.","vi":"Đến Trung Quốc rồi, mình mới thật sự hiểu văn hoá TQ."}},{"stt":27,"hanzi":"难题","pinyin":"nántí","hanviet":"Nan đề","pos":"Danh từ","meaning":"câu hỏi khó, vấn đề nan giải","comps":"数学难题 (bài toán khó), 遇到难题 (gặp vấn đề khó)","example":{"zh":"遇到难题的时候，你可以问问老师。","py":"Yùdào nántí de shíhou, nǐ kěyǐ wènwen lǎoshī.","vi":"Khi gặp câu hỏi khó, em có thể hỏi thầy cô."}}],"hanzi":[{"char":"向","pinyin":"xiàng","hanviet":"Hướng","chars":["向"],"story":"向 = 冂 (bức tường) + 口 (ô cửa sổ) → cửa sổ quay về một phía → hướng về. 向 + nơi chốn: 向前走; 向 + người: 向老师学习. Ôn trước 方向 (buổi sau)."},{"char":"楼梯","pinyin":"lóutī","hanviet":"Lâu thê","chars":["楼","梯"],"story":"楼 = 木 + 娄 → nhà tầng (ôn 楼). 梯 = 木 + 弟 (thứ bậc) → thang gỗ từng bậc. 楼梯 = cầu thang bộ; thang máy là 电梯."},{"char":"害怕","pinyin":"hàipà","hanviet":"Hại phạ","chars":["害","怕"],"story":"害 = 宀 + 丰 + 口 → hại; 怕 = 忄 + 白 (ôn bài 11). 害怕 = sợ hãi, nghĩa như 怕 nhưng hay đứng một mình hơn: 我很害怕. 害怕 + việc: 害怕见老师."},{"char":"生气","pinyin":"shēngqì","hanviet":"Sinh khí","chars":["生","气"],"story":"生 = sinh ra; 气 = hơi, khí → cơn giận. 生气 = nổi giận. Là động từ li hợp: 生他的气 = giận anh ấy; không nói ✗ 生气他."},{"char":"常见","pinyin":"cháng jiàn","hanviet":"Thường kiến","chars":["常","见"],"story":"常 = thường (常常 bài 12); 见 = thấy, gặp. 常见 = thường gặp, phổ biến (Thường kiến); trái nghĩa 少见 = hiếm gặp."},{"char":"聪明","pinyin":"cōngming","hanviet":"Thông minh","chars":["聪","明"],"story":"聪 = 耳 (tai) + 总 → tai thính; 明 = 日 + 月 → sáng. Tai thính, mắt sáng → thông minh. 明 đọc thanh nhẹ: cōngming."},{"char":"错","pinyin":"cuò","hanviet":"Thác","chars":["错"],"story":"错 = 钅 (kim loại) + 昔. Đã học 错 là tính từ \"sai\": 不错, 做错. Bài này 错 là danh từ \"lỗi\": 这是我的错; 出错 = mắc lỗi."},{"char":"认为","pinyin":"rènwéi","hanviet":"Nhận vi","chars":["认","为"],"story":"认 = 讠 + 人 → nhận (认识, 认真, 认得); 为 đọc wéi = là. 认为 = cho là — nêu nhận định, ý kiến; trang trọng hơn 觉得."},{"char":"到处","pinyin":"dàochù","hanviet":"Đáo xứ","chars":["到","处"],"story":"到 = đến; 处 = nơi chốn. 到处 = đến chỗ nào cũng … → khắp nơi (Đáo xứ). Hay đi với 都: 到处都是人."},{"char":"继续","pinyin":"jìxù","hanviet":"Kế tục","chars":["继","续"],"story":"继 và 续 đều có bộ 纟 (sợi tơ) → nối sợi tơ cho khỏi đứt → tiếp nối, tiếp tục (Kế tục). 继续 + động từ: 继续学习, 继续留学."},{"char":"同意","pinyin":"tóngyì","hanviet":"Đồng ý","chars":["同","意"],"story":"同 = cùng (同学, 不同); 意 = 音 + 心 → ý trong lòng. 同意 = cùng một ý → đồng ý. 同意 + người + làm gì: 同意我去."},{"char":"可","pinyin":"kě","hanviet":"Khả","chars":["可"],"story":"可 = 口 + 丁. Bài này 可 là liên từ = 可是 / 但是 (khẩu ngữ, đứng đầu vế sau): 可我还没想好. Khác 可以 (có thể), 可爱 (đáng yêu)."},{"char":"屋子","pinyin":"wūzi","hanviet":"Ốc tử","chars":["屋","子"],"story":"屋 = 尸 (mái nhà) + 至 (đến) → chỗ đến ở dưới mái → nhà, phòng. 屋子 = gian phòng, khẩu ngữ phương Bắc, gần nghĩa 房间."},{"char":"有关","pinyin":"yǒuguān","hanviet":"Hữu quan","chars":["有","关"],"story":"有 + 关 (liên quan — ôn 关系, 关于). 跟……有关 = 跟……有关系 (KW2 dùng cả hai cách). Làm định ngữ: 跟电脑有关的书."},{"char":"关机","pinyin":"guānjī","hanviet":"Quan cơ","chars":["关","机"],"story":"关 = đóng (关门); 机 = máy (手机, 飞机). 关机 = tắt máy ↔ 开机 (bài 7). Động từ li hợp: 关了机. Hết pin thì máy tự tắt: 没电了."},{"char":"前天","pinyin":"qiántiān","hanviet":"Tiền thiên","chars":["前","天"],"story":"前天 hôm kia → 昨天 hôm qua → 今天 hôm nay → 明天 ngày mai → 后天 ngày kia (bài 11). Tương tự: 前年 · 去年 · 今年 · 明年 · 后年."},{"char":"留学","pinyin":"liúxué","hanviet":"Lưu học","chars":["留","学"],"story":"留 = ở lại; 学 = học. 留学 = ở lại nơi khác để học → du học (Lưu học). Ôn 留学生 (bài 14). Li hợp: 留过学 = từng du học."},{"char":"国家","pinyin":"guójiā","hanviet":"Quốc gia","chars":["国","家"],"story":"国 = 囗 + 玉 (ôn 国宝); 家 = nhà. 国家 = nước nhà → quốc gia, đất nước. Hỏi quốc tịch: 你是哪个国家的人？"},{"char":"比如","pinyin":"bǐrú","hanviet":"Tỷ như","chars":["比","如"],"story":"比 = so (比较); 如 = 女 + 口 → như. 比如 = so như → ví dụ như; sau nó liệt kê vài ví dụ: 比如北京、上海."},{"char":"查","pinyin":"chá","hanviet":"Tra","chars":["查"],"story":"查 = 木 + 旦 → tra xét. 查 + nguồn: 查词典, 上网查; lặp lại cho nhẹ nhàng: 查一查 / 查查."},{"char":"有用","pinyin":"yǒuyòng","hanviet":"Hữu dụng","chars":["有","用"],"story":"有 + 用 (dùng) → có chỗ dùng → có ích (Hữu dụng). Phủ định: 没(有)用. 对……有用 = có ích cho …: 对学习很有用."},{"char":"容易","pinyin":"róngyì","hanviet":"Dung dị","chars":["容","易"],"story":"容 = 宀 + 谷 → chứa được; 易 = dễ. 容易 = dễ (Dung dị) ↔ 难. 不容易 = không dễ: 这个问题真不容易回答 (KW4)."},{"char":"回答","pinyin":"huídá","hanviet":"Hồi đáp","chars":["回","答"],"story":"回 = trả lại (ôn 回 lượng từ bài 9); 答 = ⺮ + 合 → đáp. 回答 = đáp lại → trả lời. 问问题 (hỏi) ↔ 回答问题 (trả lời)."},{"char":"方向","pinyin":"fāngxiàng","hanviet":"Phương hướng","chars":["方","向"],"story":"方 = phương (东方 bài 13, 地方); 向 = hướng (ngữ pháp buổi trước). 方向 = phương hướng; nghĩa bóng: hướng đi trong đời — 大家选择的方向都不同."},{"char":"只有","pinyin":"zhǐyǒu","hanviet":"Chỉ hữu","chars":["只","有"],"story":"只 = chỉ (bài 2); 有 = có. 只有 là liên từ trong 只有……才…… (ngữ pháp 4). Khác 只有 = chỉ có (động từ): 教室里只有三个人."},{"char":"真正","pinyin":"zhēnzhèng","hanviet":"Chân chính","chars":["真","正"],"story":"真 = thật (真的); 正 = đúng, ngay ngắn. 真正 = thật sự, đích thực (Chân chính). 真正 + động từ: 真正喜欢; 真正的 + danh từ: 真正的朋友."},{"char":"难题","pinyin":"nántí","hanviet":"Nan đề","chars":["难","题"],"story":"难 = khó (bài 10); 题 = 是 + 页 → đề bài, câu hỏi (问题). 难题 = câu hỏi khó, vấn đề nan giải (Nan đề): 数学难题, 生活中的难题."}],"grammar":[{"title":"向 + 方向 / 人 + 动词","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>向</b><small>về phía / với</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>Phương hướng / Người</b><small>前 · 她 · 老师</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>Động từ</b><small>走 · 跑 · 学习</small></span></div>","summary":"<p class=\"gr-lead\">Về phía …; với, ở (ai) …</p><ul><li>Chỉ <b>phương hướng</b>: <span class=\"zh\">向前走 · 向东走 · 向她跑过去</span>.</li><li>Chỉ <b>đối tượng</b> là người: <span class=\"zh\">向老师请假 · 向他学习 · 向大家介绍</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">向 · hai cách dùng</span> · Cấu trúc</h4><p>Về phía … · với (ai) …</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Phương hướng</div><div class=\"fx-row\"><span class=\"fx-p\"><b>别再</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>向</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>前</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>走了</b></span></div><div class=\"fx-ex zh\">别再向前走了。</div><div class=\"fx-lbl\">Phương hướng</div><div class=\"fx-row\"><span class=\"fx-p\"><b>孩子</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>向</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>她</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>跑过去了</b></span></div><div class=\"fx-ex zh\">孩子一看见妈妈，就向她跑过去了。</div><div class=\"fx-lbl\">Đối tượng</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我要多</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>向</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>认真的人</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>学习</b></span></div><div class=\"fx-ex zh\">以后我要多向认真的人学习。</div></div><p class=\"gr-key\">Hay gặp: <span class=\"zh\">向前 / 向东 · 向……学习 · 向……请假 · 向……介绍</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">以后我要多向认真的人学习。</span> = Sau này mình phải học hỏi nhiều hơn ở những người nghiêm túc.</p>","note":"<b>Lưu ý:</b> Cụm 向 đứng trước động từ: ✗ <span class=\"zh\">我要学习向他</span> → ✓ <span class=\"zh\">我要向他学习</span>","examples":[{"zh":"别再向前走了。","py":"Bié zài xiàng qián zǒu le.","vi":"Đừng đi tiếp về phía trước nữa."},{"zh":"以后我要多向认真的人学习。","py":"Yǐhòu wǒ yào duō xiàng rènzhēn de rén xuéxí.","vi":"Sau này mình phải học hỏi nhiều hơn ở những người nghiêm túc."},{"zh":"孩子一看见妈妈，就向她跑过去了。","py":"Háizi yí kànjiàn māma, jiù xiàng tā pǎo guòqu le.","vi":"Đứa bé vừa thấy mẹ là chạy về phía mẹ ngay."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">如果有事不能上课，你就应该____。</span><span class=\"qz-hint\">Nếu có việc không đi học được, bạn nên xin phép thầy cô.</span>","answer":["向老师请假"],"explain":"如果有事不能上课，你就应该向老师请假。 (Rúguǒ yǒu shì bù néng shàngkè, nǐ jiù yīnggāi xiàng lǎoshī qǐngjià.)"},{"type":"fill","q":"<span class=\"zh\">我是新来的，不懂的东西我会多____。</span><span class=\"qz-hint\">Tôi là người mới, chỗ nào chưa hiểu tôi sẽ học hỏi mọi người nhiều.</span>","answer":["向大家学习","向你们学习"],"explain":"我是新来的，不懂的东西我会多向大家学习。 (Wǒ shì xīn lái de, bù dǒng de dōngxi wǒ huì duō xiàng dàjiā xuéxí.)"}]},{"title":"（主语）+ 不是 + …… + 吗？","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>Chủ ngữ</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不是</b><small>chẳng phải</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>Điều đã biết</b><small>喜欢 · 说过 · 下个月</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>吗？</b><small>sao?</small></span></div>","summary":"<p class=\"gr-lead\">Chẳng phải … sao?</p><ul><li>Hình thức <b>phủ định</b>, ý <b>khẳng định</b>: <span class=\"zh\">你不是说今天有事吗？</span> = cậu đã nói hôm nay có việc mà.</li><li>Tỏ ý <b>khó hiểu / không vui</b> (hay kèm <span class=\"zh\">为什么 · 怎么</span>), hoặc để <b>nhắc nhở, xác nhận</b>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">不是……吗？ · ba sắc thái</span> · Cấu trúc</h4><p>Chẳng phải … sao?</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Nhắc nhở · gợi ý</div><div class=\"fx-row\"><span class=\"fx-p\"><b>你</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不是</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>喜欢玩电脑</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>吗？</b></span></div><div class=\"fx-ex zh\">你不是喜欢玩电脑吗？</div><div class=\"fx-lbl\">Khó hiểu</div><div class=\"fx-row\"><span class=\"fx-p\"><b>考试</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不是</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>下个月</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>吗？</b></span></div><div class=\"fx-ex zh\">考试不是下个月吗？</div><div class=\"fx-lbl\">Không vui</div><div class=\"fx-row\"><span class=\"fx-p\"><b>你</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不是</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>说八点到</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>吗？</b></span></div><div class=\"fx-ex zh\">你不是说八点到吗？都九点了！</div></div><p class=\"gr-key\"><span class=\"zh\">不是……吗？</span> = \"đã … mà / chẳng phải … sao\" (phản vấn)　·　<span class=\"zh\">是不是……？</span> = hỏi thật</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">你不是喜欢玩电脑吗？</span> = Chẳng phải cậu thích chơi máy tính sao? (= cậu thích mà)</p>","note":"<b>Lưu ý:</b> Kết thúc bằng 吗, không dùng 呢: ✗ <span class=\"zh\">你不是喜欢玩电脑呢？</span> → ✓ <span class=\"zh\">你不是喜欢玩电脑吗？</span>","examples":[{"zh":"你不是喜欢玩电脑吗？你可以去看看跟电脑有关系的书。","py":"Nǐ bú shì xǐhuan wán diànnǎo ma? Nǐ kěyǐ qù kànkan gēn diànnǎo yǒu guānxi de shū.","vi":"Chẳng phải cậu thích chơi máy tính sao? Cậu có thể xem sách liên quan đến máy tính."},{"zh":"你不是说今天有事吗？为什么来了？","py":"Nǐ bú shì shuō jīntiān yǒu shì ma? Wèi shénme lái le?","vi":"Chẳng phải cậu bảo hôm nay có việc sao? Sao lại đến?"},{"zh":"考试不是下个月吗？你怎么今天就开始复习了？","py":"Kǎoshì bú shì xià ge yuè ma? Nǐ zěnme jīntiān jiù kāishǐ fùxí le?","vi":"Chẳng phải tháng sau mới thi sao? Sao hôm nay cậu đã bắt đầu ôn rồi?"}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">今年放假我还想去南京。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">____？</span></span></span><span class=\"qz-hint\">Kỳ nghỉ năm nay mình vẫn muốn đi Nam Kinh. — Chẳng phải năm ngoái cậu đi Nam Kinh rồi sao?</span>","answer":["你不是去年去过南京吗","你不是去过南京吗"],"explain":"你不是去年去过南京吗？ (Nǐ bú shì qùnián qùguo Nánjīng ma?)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">____？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">对不起，我没带。我把作业放在家里了。</span></span></span><span class=\"qz-hint\">Chẳng phải em bảo hôm nay mang bài tập đến sao? — Xin lỗi, em không mang. Em để bài tập ở nhà rồi.</span>","answer":["你不是说今天把作业带来吗","你不是说今天带作业来吗"],"explain":"你不是说今天把作业带来吗？ (Nǐ bú shì shuō jīntiān bǎ zuòyè dàilai ma?)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我下午上班，这件事明天再说吧。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">今天是星期天，____？</span></span></span><span class=\"qz-hint\">Chiều nay anh đi làm, việc này mai hẵng nói nhé. — Hôm nay là chủ nhật, chẳng phải anh không đi làm sao?</span>","answer":["你不是不上班吗","你不是不用上班吗"],"explain":"今天是星期天，你不是不上班吗？ (Jīntiān shì xīngqītiān, nǐ bú shì bú shàngbān ma?)"}]},{"title":"分句1，（主语）+ 更 + 分句2","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>Vế 1</b><small>mức cơ bản</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，(CN) 更</b><small>càng · hơn nữa</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>Vế 2</b><small>mức sâu hơn</small></span></div>","summary":"<p class=\"gr-lead\">…, càng / hơn nữa …</p><ul><li><span class=\"zh\">更</span> đứng <b>trước động từ / trợ động từ</b> của vế 2: <span class=\"zh\">更没想好 · 更要多说 · 更了解了</span>.</li><li>Vế 2 nói điều <b>quan trọng hơn, sâu hơn</b>; phủ định hay gặp: <span class=\"zh\">还没……，更没……</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">……，更…… · ba dạng</span> · Cấu trúc</h4><p>…, càng …</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Phủ định</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>还没想好学什么</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>更</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>没想好去哪儿</b></span></div><div class=\"fx-ex zh\">我还没想好学什么，更没想好去哪个国家。</div><div class=\"fx-lbl\">Trợ động từ</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>要多听多看</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>更</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>要多说多练</b></span></div><div class=\"fx-ex zh\">想提高中文水平要多听多看，更要多说多练。</div><div class=\"fx-lbl\">Khẳng định</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>学会了中文</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>更</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>了解了中国文化</b></span></div><div class=\"fx-ex zh\">来中国学习，我学会了中文，更了解了中国文化。</div></div><p class=\"gr-key\">Ôn <span class=\"zh\">更</span> so sánh (bài 7): <span class=\"zh\">那条裙子更漂亮</span>　·　bài 17: <span class=\"zh\">更</span> nối hai vế, vế sau sâu hơn</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我还没想好学什么，更没想好去哪个国家。</span> = Mình chưa nghĩ ra học gì, càng chưa nghĩ ra đi nước nào.</p>","note":"<b>Lưu ý:</b> 更 đứng sau chủ ngữ: ✗ <span class=\"zh\">……，更我了解了中国文化</span> → ✓ <span class=\"zh\">……，我更了解了中国文化</span>","examples":[{"zh":"我还没想好学什么，更没想好去哪个国家。","py":"Wǒ hái méi xiǎnghǎo xué shénme, gèng méi xiǎnghǎo qù nǎge guójiā.","vi":"Mình chưa nghĩ ra học gì, càng chưa nghĩ ra đi nước nào."},{"zh":"想提高中文水平要多听多看，更要多说多练。","py":"Xiǎng tígāo Zhōngwén shuǐpíng yào duō tīng duō kàn, gèng yào duō shuō duō liàn.","vi":"Muốn nâng cao trình độ tiếng Trung phải nghe nhiều, đọc nhiều, càng phải nói nhiều, luyện nhiều."},{"zh":"来中国学习，我学会了中文，更了解了中国文化。","py":"Lái Zhōngguó xuéxí, wǒ xuéhuìle Zhōngwén, gèng liǎojiěle Zhōngguó wénhuà.","vi":"Sang Trung Quốc học, mình biết tiếng Trung, lại càng hiểu thêm văn hoá Trung Quốc."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">找工作的时候需要别人的帮助，更需要____。</span><span class=\"qz-hint\">Khi tìm việc cần người khác giúp đỡ, càng cần sự cố gắng của bản thân.</span>","answer":["自己的努力","自己努力"],"explain":"找工作的时候需要别人的帮助，更需要自己的努力。 (Zhǎo gōngzuò de shíhou xūyào biérén de bāngzhù, gèng xūyào zìjǐ de nǔlì.)"}]},{"title":"只有 + 条件，（主语）+ 才 + 结果","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>只有</b><small>chỉ có</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>Điều kiện</b><small>duy nhất</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>，(CN) 才</b><small>mới</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>Kết quả</b><small>能 · 会 …</small></span></div>","summary":"<p class=\"gr-lead\">Chỉ có …, mới …</p><ul><li><span class=\"zh\">才</span> đứng <b>sau chủ ngữ</b> của vế 2, hay đi với <span class=\"zh\">能 / 会</span>: <span class=\"zh\">你的中文水平才能提高</span>.</li><li>Nhấn mạnh <b>điều kiện duy nhất</b>; khác <span class=\"zh\">才</span> bài 3 (= muộn, chậm): <span class=\"zh\">他十点才起床</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">只有……，才…… · vị trí của 才</span> · Cấu trúc</h4><p>Chỉ có …, mới …</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Không chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>只有</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>每天锻炼身体</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>才</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>会越来越健康</b></span></div><div class=\"fx-ex zh\">只有每天锻炼身体，才会越来越健康。</div><div class=\"fx-lbl\">Có chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>只有</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>多听多说</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>你</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>才</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>能说好</b></span></div><div class=\"fx-ex zh\">只有多听多说，你才能说好。</div><div class=\"fx-lbl\">才 · muộn (bài 3)</div><div class=\"fx-row\"><span class=\"fx-p\"><b>他</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>十点</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>才</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>起床</b></span></div><div class=\"fx-ex zh\">他今天十点才起床。</div></div><p class=\"gr-key\"><span class=\"zh\">只有……才……</span>: thiếu điều kiện → không có kết quả　·　<span class=\"zh\">才</span> bài 3 = muộn / chậm hơn dự kiến</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">只有每天锻炼身体，才会越来越健康。</span> = Chỉ có rèn luyện mỗi ngày mới ngày càng khoẻ mạnh.</p>","note":"<b>Lưu ý:</b> 才 không đứng trước chủ ngữ: ✗ <span class=\"zh\">只有多练习，才你能说好</span> → ✓ <span class=\"zh\">只有多练习，你才能说好</span>","examples":[{"zh":"只有想清楚自己真正喜欢什么，才能做出最合适的选择。","py":"Zhǐyǒu xiǎng qīngchu zìjǐ zhēnzhèng xǐhuan shénme, cái néng zuòchū zuì héshì de xuǎnzé.","vi":"Chỉ có nghĩ rõ mình thật sự thích gì mới đưa ra được lựa chọn phù hợp nhất."},{"zh":"只有每天锻炼身体，才会越来越健康。","py":"Zhǐyǒu měi tiān duànliàn shēntǐ, cái huì yuè lái yuè jiànkāng.","vi":"Chỉ có rèn luyện mỗi ngày mới ngày càng khoẻ mạnh."},{"zh":"只有多听、多说、多看，你的中文水平才能提高。","py":"Zhǐyǒu duō tīng, duō shuō, duō kàn, nǐ de Zhōngwén shuǐpíng cái néng tígāo.","vi":"Chỉ có nghe nhiều, nói nhiều, đọc nhiều, trình độ tiếng Trung của bạn mới nâng cao được."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在教学楼里","titleVi":"Toà nhà học — hai bạn vừa đi vừa nói","lines":[{"speaker":"小","name":"Tiểu Tuyết","zh":"别再向前走了，李老师的办公室已经到了。","py":"Bié zài xiàng qián zǒu le, Lǐ lǎoshī de bàngōngshì yǐjīng dào le.","vi":"Đừng đi tiếp về phía trước nữa, đến văn phòng cô Lý rồi."},{"speaker":"同","name":"Bạn học","zh":"你进去吧，我在楼梯那儿等你。我害怕见李老师。","py":"Nǐ jìnqu ba, wǒ zài lóutī nàr děng nǐ. Wǒ hàipà jiàn Lǐ lǎoshī.","vi":"Cậu vào đi, mình đợi cậu ở chỗ cầu thang. Mình sợ gặp cô Lý."},{"speaker":"小","name":"Tiểu Tuyết","zh":"怎么回事？","py":"Zěnme huí shì?","vi":"Sao thế?"},{"speaker":"同","name":"Bạn học","zh":"最近我做错了好几件事，我怕李老师生气。","py":"Zuìjìn wǒ zuòcuòle hǎo jǐ jiàn shì, wǒ pà Lǐ lǎoshī shēngqì.","vi":"Dạo này mình làm sai mấy việc liền, mình sợ cô Lý giận."},{"speaker":"小","name":"Tiểu Tuyết","zh":"你想多了，做错事情是很常见的。","py":"Nǐ xiǎng duō le, zuòcuò shìqing shì hěn cháng jiàn de.","vi":"Cậu nghĩ nhiều rồi, làm sai là chuyện rất thường gặp mà."},{"speaker":"同","name":"Bạn học","zh":"我把简单的事情做错了，李老师一定觉得我不认真。","py":"Wǒ bǎ jiǎndān de shìqing zuòcuò le, Lǐ lǎoshī yídìng juéde wǒ bú rènzhēn.","vi":"Mình làm sai cả những việc đơn giản, cô Lý chắc chắn thấy mình không nghiêm túc."},{"speaker":"小","name":"Tiểu Tuyết","zh":"有的人虽然很聪明，但是会在简单的事情中出错，因为他们认为事情简单，就不会认真去做了。","py":"Yǒude rén suīrán hěn cōngming, dànshì huì zài jiǎndān de shìqing zhōng chūcuò, yīnwèi tāmen rènwéi shìqing jiǎndān, jiù bú huì rènzhēn qù zuò le.","vi":"Có người tuy rất thông minh nhưng lại mắc lỗi ở việc đơn giản, vì cho rằng việc đơn giản nên không làm cẩn thận."},{"speaker":"同","name":"Bạn học","zh":"你说的就是我，以后我要多向认真的人学习。","py":"Nǐ shuō de jiù shì wǒ, yǐhòu wǒ yào duō xiàng rènzhēn de rén xuéxí.","vi":"Cậu nói đúng là mình rồi, sau này mình phải học hỏi nhiều hơn ở những người nghiêm túc."}]},{"titleZh":"课文二 · 在阅览室门口","titleVi":"Cửa phòng đọc — gặp nhau","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"太阳从西边出来了？这几天怎么总是在图书馆看见你？","py":"Tàiyáng cóng xībian chūlai le? Zhè jǐ tiān zěnme zǒngshì zài túshūguǎn kànjiàn nǐ?","vi":"Mặt trời mọc đằng tây à? Sao mấy hôm nay cứ thấy cậu ở thư viện thế?"},{"speaker":"中","name":"Thiên Trung","zh":"这有什么奇怪的？我是来学习的。","py":"Zhè yǒu shénme qíguài de? Wǒ shì lái xuéxí de.","vi":"Có gì lạ đâu? Mình đến để học mà."},{"speaker":"月","name":"Gia Nguyệt","zh":"你怎么还来图书馆学习？同学们都在到处找工作呢。","py":"Nǐ zěnme hái lái túshūguǎn xuéxí? Tóngxuémen dōu zài dàochù zhǎo gōngzuò ne.","vi":"Sao cậu còn đến thư viện học? Các bạn đều đang đi khắp nơi tìm việc kìa."},{"speaker":"中","name":"Thiên Trung","zh":"我不想现在就工作，还想继续学习，我爸妈也同意。可我还没想好学什么，所以来图书馆看看。","py":"Wǒ bù xiǎng xiànzài jiù gōngzuò, hái xiǎng jìxù xuéxí, wǒ bà mā yě tóngyì. Kě wǒ hái méi xiǎnghǎo xué shénme, suǒyǐ lái túshūguǎn kànkan.","vi":"Mình chưa muốn đi làm ngay, còn muốn học tiếp, bố mẹ cũng đồng ý. Nhưng mình chưa nghĩ ra học gì, nên đến thư viện xem thử."},{"speaker":"月","name":"Gia Nguyệt","zh":"你不是喜欢玩电脑吗？你可以去看看跟电脑有关系的书。","py":"Nǐ bú shì xǐhuan wán diànnǎo ma? Nǐ kěyǐ qù kànkan gēn diànnǎo yǒu guānxi de shū.","vi":"Chẳng phải cậu thích chơi máy tính sao? Cậu có thể xem sách liên quan đến máy tính."},{"speaker":"中","name":"Thiên Trung","zh":"你说得对，我记得那个屋子里有些跟电脑有关的书，我去找找。","py":"Nǐ shuō de duì, wǒ jìde nàge wūzi li yǒuxiē gēn diànnǎo yǒuguān de shū, wǒ qù zhǎozhao.","vi":"Cậu nói đúng, mình nhớ trong phòng kia có mấy cuốn sách về máy tính, mình đi tìm xem."}]},{"titleZh":"课文三 · 在校园里","titleVi":"Sân trường — chuyện đi du học","lines":[{"speaker":"文","name":"Lý Văn","zh":"天中，你的手机怎么关机了？","py":"Tiānzhōng, nǐ de shǒujī zěnme guānjī le?","vi":"Thiên Trung, sao điện thoại cậu tắt máy vậy?"},{"speaker":"中","name":"Thiên Trung","zh":"我的手机没电了。你找我有事吗？","py":"Wǒ de shǒujī méi diàn le. Nǐ zhǎo wǒ yǒu shì ma?","vi":"Điện thoại mình hết pin. Cậu tìm mình có việc gì à?"},{"speaker":"文","name":"Lý Văn","zh":"前天我看见家月了，她告诉我你打算继续留学？","py":"Qiántiān wǒ kànjiàn Jiāyuè le, tā gàosu wǒ nǐ dǎsuàn jìxù liúxué?","vi":"Hôm kia mình gặp Gia Nguyệt, cô ấy bảo cậu định tiếp tục du học à?"},{"speaker":"中","name":"Thiên Trung","zh":"是，可是我还没想好学什么，更没想好去哪个国家。","py":"Shì, kěshì wǒ hái méi xiǎnghǎo xué shénme, gèng méi xiǎnghǎo qù nǎge guójiā.","vi":"Ừ, nhưng mình chưa nghĩ ra học gì, càng chưa nghĩ ra đi nước nào."},{"speaker":"文","name":"Lý Văn","zh":"你可以去中国学中文啊。比如可以去北京、上海这样的大城市，那里有很多好大学，也有很多留学生。","py":"Nǐ kěyǐ qù Zhōngguó xué Zhōngwén a. Bǐrú kěyǐ qù Běijīng, Shànghǎi zhèyàng de dà chéngshì, nàli yǒu hěn duō hǎo dàxué, yě yǒu hěn duō liúxuéshēng.","vi":"Cậu có thể sang TQ học tiếng Trung mà. Ví dụ đến thành phố lớn như Bắc Kinh, Thượng Hải, ở đó có nhiều trường tốt, cũng có nhiều du học sinh."},{"speaker":"中","name":"Thiên Trung","zh":"好，那我上网查一查。","py":"Hǎo, nà wǒ shàngwǎng chá yi chá.","vi":"Được, vậy mình lên mạng tra thử."},{"speaker":"文","name":"Lý Văn","zh":"我给你介绍几个有用的网站。","py":"Wǒ gěi nǐ jièshào jǐ ge yǒuyòng de wǎngzhàn.","vi":"Mình giới thiệu cho cậu mấy trang web có ích."}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — Thiên Trung viết nhật ký","para":true,"speaker":"中","lines":[{"zh":"大学生活马上就要结束了，我最近经常被问到一个问题——“你以后想做什么”，这个问题真不容易回答。","py":"Dàxué shēnghuó mǎshàng jiù yào jiéshù le, wǒ zuìjìn jīngcháng bèi wèndào yí ge wèntí — \"nǐ yǐhòu xiǎng zuò shénme\", zhège wèntí zhēn bù róngyì huídá.","vi":"Cuộc sống đại học sắp kết thúc rồi, dạo này tôi thường bị hỏi một câu — \"Sau này cậu muốn làm gì?\", câu hỏi này thật không dễ trả lời."},{"zh":"我也问了几个同学，大家选择的方向都不同。","py":"Wǒ yě wènle jǐ ge tóngxué, dàjiā xuǎnzé de fāngxiàng dōu bù tóng.","vi":"Tôi cũng hỏi mấy bạn học, hướng đi mỗi người chọn đều khác nhau."},{"zh":"有的想继续在学校学习，有的打算出国留学，还有的决定先找工作。","py":"Yǒude xiǎng jìxù zài xuéxiào xuéxí, yǒude dǎsuàn chūguó liúxué, hái yǒude juédìng xiān zhǎo gōngzuò.","vi":"Có người muốn tiếp tục học ở trường, có người định ra nước ngoài du học, còn có người quyết định đi làm trước."},{"zh":"我认为只有想清楚自己真正喜欢什么，才能做出最合适的选择。","py":"Wǒ rènwéi zhǐyǒu xiǎng qīngchu zìjǐ zhēnzhèng xǐhuan shénme, cái néng zuòchū zuì héshì de xuǎnzé.","vi":"Tôi cho rằng chỉ có nghĩ rõ bản thân thật sự thích gì mới có thể đưa ra lựa chọn phù hợp nhất."},{"zh":"对我来说，想清楚“真正喜欢什么”是个难题。","py":"Duì wǒ lái shuō, xiǎng qīngchu \"zhēnzhèng xǐhuan shénme\" shì ge nántí.","vi":"Đối với tôi, nghĩ cho rõ \"thật sự thích gì\" là một bài toán khó."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Kể một trải nghiệm thật","q":{"zh":"选一种情绪，分享一次真实的经历。","py":"Xuǎn yì zhǒng qíngxù, fēnxiǎng yí cì zhēnshí de jīnglì.","vi":"Chọn một cảm xúc, kể cho bạn nghe một trải nghiệm thật (dùng từ, ngữ pháp bài 17)."},"items":[{"zh":"开心 · 难过 · 生气 · 害怕 · 紧张 · 着急 · 奇怪","py":"kāixīn · nánguò · shēngqì · hàipà · jǐnzhāng · zháojí · qíguài","vi":"Gợi ý cảm xúc: vui · buồn · giận · sợ · hồi hộp · sốt ruột · thấy lạ"},{"zh":"你上一次有这样的感受是什么时候？","py":"Nǐ shàng yí cì yǒu zhèyàng de gǎnshòu shì shénme shíhou?","vi":"Lần gần nhất bạn có cảm giác này là khi nào?"},{"zh":"那时候发生了什么事情？","py":"Nà shíhou fāshēngle shénme shìqing?","vi":"Khi đó đã xảy ra chuyện gì?"},{"zh":"最后你是怎么解决的？","py":"Zuìhòu nǐ shì zěnme jiějué de?","vi":"Cuối cùng bạn đã giải quyết thế nào?"}]}],"speak":[]}},{"id":"k3v3-b18","courseId":"k3v3","order":18,"title":"Tôi đã học được cách gói sủi cảo","titleZh":"我学会了包饺子","titlePy":"wǒ xuéhuìle bāo jiǎozi","vocab":[{"stt":1,"hanzi":"怎样","pinyin":"zěnyàng","hanviet":"Chẩm dạng","pos":"Đại từ","meaning":"thế nào, ra sao","comps":"怎样过节 (đón lễ thế nào), 怎样学习 (học thế nào), 怎样去 (đi bằng cách nào)","example":{"zh":"你知道怎样做中国菜吗？","py":"Nǐ zhīdào zěnyàng zuò Zhōngguócài ma?","vi":"Bạn có biết nấu món Trung Quốc thế nào không?"}},{"stt":2,"hanzi":"过节","pinyin":"guòjié","hanviet":"Quá tiết","pos":"Động từ (li hợp)","meaning":"ăn Tết, đón lễ","comps":"回家过节 (về nhà ăn Tết), 过节的时候 (lúc đón lễ), 过了一个节 (đón một dịp lễ)","example":{"zh":"过节的时候，我们全家会一起吃饭。","py":"Guòjié de shíhou, wǒmen quán jiā huì yìqǐ chīfàn.","vi":"Lúc đón lễ, cả nhà mình sẽ cùng ăn cơm."}},{"stt":3,"hanzi":"节","pinyin":"jié","hanviet":"Tiết","pos":"Danh từ","meaning":"ngày lễ, tết","comps":"春节 (Tết Nguyên đán), 过节 (đón lễ), 节日 (ngày lễ)","example":{"zh":"你最喜欢过什么节？","py":"Nǐ zuì xǐhuan guò shénme jié?","vi":"Bạn thích đón dịp lễ nào nhất?"}},{"stt":4,"hanzi":"节日","pinyin":"jiérì","hanviet":"Tiết nhật","pos":"Danh từ","meaning":"ngày lễ","comps":"节日快乐 (chúc ngày lễ vui vẻ), 重要的节日 (ngày lễ quan trọng)","example":{"zh":"祝你节日快乐！","py":"Zhù nǐ jiérì kuàilè!","vi":"Chúc bạn ngày lễ vui vẻ!"}},{"stt":5,"hanzi":"联欢","pinyin":"liánhuān","hanviet":"Liên hoan","pos":"Động từ","meaning":"liên hoan, sum họp vui vẻ","comps":"联欢会 (buổi liên hoan), 春节联欢晚会 (Gala chào Xuân)","example":{"zh":"新年的时候，我们班要开联欢会。","py":"Xīnnián de shíhou, wǒmen bān yào kāi liánhuānhuì.","vi":"Dịp năm mới, lớp mình sẽ tổ chức liên hoan."}},{"stt":6,"hanzi":"大概","pinyin":"dàgài","hanviet":"Đại khái","pos":"Phó từ / Tính từ","meaning":"khoảng, chắc là; đại khái","comps":"大概七八天 (khoảng bảy tám ngày), 大概知道 (biết đại khái), 大概的意思 (ý đại khái)","example":{"zh":"他大概不来了，我们先吃吧。","py":"Tā dàgài bù lái le, wǒmen xiān chī ba.","vi":"Chắc anh ấy không đến nữa, chúng ta ăn trước đi."}},{"stt":7,"hanzi":"阿姨","pinyin":"āyí","hanviet":"A di","pos":"Danh từ","meaning":"cô, dì","comps":"张阿姨 (cô Trương), 阿姨好 (cháu chào cô)","example":{"zh":"阿姨，您做的菜太好吃了！","py":"Āyí, nín zuò de cài tài hǎochī le!","vi":"Cô ơi, món cô nấu ngon quá ạ!"}},{"stt":8,"hanzi":"叔叔","pinyin":"shūshu","hanviet":"Thúc thúc","pos":"Danh từ","meaning":"chú","comps":"李叔叔 (chú Lý), 叔叔好 (cháu chào chú)","example":{"zh":"叔叔，这是我送给您的礼物。","py":"Shūshu, zhè shì wǒ sòng gěi nín de lǐwù.","vi":"Chú ơi, đây là quà cháu tặng chú ạ."}},{"stt":9,"hanzi":"收","pinyin":"shōu","hanviet":"Thu","pos":"Động từ","meaning":"nhận","comps":"收下 (nhận lấy), 收礼物 (nhận quà), 收到 (nhận được)","example":{"zh":"生日的时候，我收了很多礼物。","py":"Shēngrì de shíhou, wǒ shōule hěn duō lǐwù.","vi":"Hôm sinh nhật, mình nhận được rất nhiều quà."}},{"stt":10,"hanzi":"总","pinyin":"zǒng","hanviet":"Tổng","pos":"Phó từ","meaning":"luôn, lúc nào cũng","comps":"总是 (luôn luôn), 总听说 (cứ nghe nói), 总来晚 (lúc nào cũng đến muộn)","example":{"zh":"他总来晚，老师有点儿生气。","py":"Tā zǒng lái wǎn, lǎoshī yǒudiǎnr shēngqì.","vi":"Cậu ấy lúc nào cũng đến muộn, cô giáo hơi giận."}},{"stt":11,"hanzi":"起","pinyin":"qǐ","hanviet":"Khởi","pos":"Động từ (bổ ngữ)","meaning":"(sau ĐT) nhắc đến, nói về","comps":"说起 (nhắc đến), 问起 (hỏi tới), 想起 (nhớ tới)","example":{"zh":"妈妈常常跟我说起她小时候的事。","py":"Māma chángcháng gēn wǒ shuōqǐ tā xiǎoshíhou de shì.","vi":"Mẹ hay kể với mình chuyện hồi mẹ còn nhỏ."}},{"stt":12,"hanzi":"见面","pinyin":"jiànmiàn","hanviet":"Kiến diện","pos":"Động từ (li hợp)","meaning":"gặp mặt","comps":"跟他见面 (gặp anh ấy), 第一次见面 (lần đầu gặp mặt), 见过一次面 (gặp một lần rồi)","example":{"zh":"我们明天下午三点在学校门口见面吧。","py":"Wǒmen míngtiān xiàwǔ sān diǎn zài xuéxiào ménkǒu jiànmiàn ba.","vi":"Chiều mai ba giờ mình gặp nhau ở cổng trường nhé."}},{"stt":13,"hanzi":"矿泉水","pinyin":"kuàngquánshuǐ","hanviet":"Khoáng tuyền thuỷ","pos":"Danh từ","meaning":"nước khoáng","comps":"一瓶矿泉水 (một chai nước khoáng), 买矿泉水 (mua nước khoáng)","example":{"zh":"天太热了，我想买一瓶矿泉水。","py":"Tiān tài rè le, wǒ xiǎng mǎi yì píng kuàngquánshuǐ.","vi":"Trời nóng quá, mình muốn mua một chai nước khoáng."}},{"stt":14,"hanzi":"刚刚","pinyin":"gānggāng","hanviet":"Cương cương","pos":"Phó từ","meaning":"vừa mới","comps":"刚刚到 (vừa mới đến), 刚刚学会 (vừa mới biết), 刚刚开始 (vừa mới bắt đầu)","example":{"zh":"我刚刚下课，现在就去找你。","py":"Wǒ gānggāng xiàkè, xiànzài jiù qù zhǎo nǐ.","vi":"Mình vừa mới tan học, giờ đi tìm cậu ngay."}},{"stt":29,"hanzi":"春节","pinyin":"Chūnjié","hanviet":"Xuân tiết","pos":"Danh từ riêng","meaning":"Tết Nguyên đán","comps":"过春节 (ăn Tết), 春节快乐 (chúc mừng năm mới), 春节联欢晚会 (Gala chào Xuân)","example":{"zh":"春节的时候，很多人都回家过年。","py":"Chūnjié de shíhou, hěn duō rén dōu huí jiā guònián.","vi":"Dịp Tết, rất nhiều người về nhà ăn Tết."}},{"stt":15,"hanzi":"出发","pinyin":"chūfā","hanviet":"Xuất phát","pos":"Động từ","meaning":"xuất phát, khởi hành","comps":"从北京出发 (xuất phát từ Bắc Kinh), 几点出发 (mấy giờ xuất phát), 明天出发 (mai lên đường)","example":{"zh":"我们明天早上七点从学校出发。","py":"Wǒmen míngtiān zǎoshang qī diǎn cóng xuéxiào chūfā.","vi":"Bảy giờ sáng mai chúng ta xuất phát từ trường."}},{"stt":16,"hanzi":"不久","pinyin":"bùjiǔ","hanviet":"Bất cửu","pos":"Tính từ","meaning":"không lâu","comps":"不久前 (cách đây không lâu), 不久以后 (không lâu sau)","example":{"zh":"不久以后，他就要去中国留学了。","py":"Bùjiǔ yǐhòu, tā jiù yào qù Zhōngguó liúxué le.","vi":"Không lâu nữa, anh ấy sẽ sang Trung Quốc du học."}},{"stt":17,"hanzi":"发生","pinyin":"fāshēng","hanviet":"Phát sinh","pos":"Động từ","meaning":"xảy ra","comps":"发生了什么事 (đã xảy ra chuyện gì), 发生变化 (xảy ra thay đổi)","example":{"zh":"昨天这里发生了什么事？","py":"Zuótiān zhèli fāshēngle shénme shì?","vi":"Hôm qua ở đây đã xảy ra chuyện gì vậy?"}},{"stt":18,"hanzi":"刚","pinyin":"gāng","hanviet":"Cương","pos":"Phó từ","meaning":"vừa, mới","comps":"刚来 (vừa đến), 刚离开 (vừa rời đi), 刚……就…… (vừa … đã …)","example":{"zh":"我刚到家，就下起雨来了。","py":"Wǒ gāng dào jiā, jiù xià qǐ yǔ lai le.","vi":"Mình vừa về đến nhà thì trời đổ mưa."}},{"stt":19,"hanzi":"只要","pinyin":"zhǐyào","hanviet":"Chỉ yếu","pos":"Liên từ","meaning":"chỉ cần","comps":"只要……就…… (chỉ cần … là …), 只要你同意 (chỉ cần bạn đồng ý)","example":{"zh":"只要多练习，你就能说得很好。","py":"Zhǐyào duō liànxí, nǐ jiù néng shuō de hěn hǎo.","vi":"Chỉ cần luyện nhiều là bạn có thể nói rất tốt."}},{"stt":20,"hanzi":"学期","pinyin":"xuéqī","hanviet":"Học kỳ","pos":"Danh từ","meaning":"học kỳ","comps":"这个学期 (học kỳ này), 下学期 (học kỳ sau), 最后一个学期 (học kỳ cuối)","example":{"zh":"下个学期我想多参加一些比赛。","py":"Xià ge xuéqī wǒ xiǎng duō cānjiā yìxiē bǐsài.","vi":"Học kỳ sau mình muốn tham gia nhiều cuộc thi hơn."}},{"stt":21,"hanzi":"毕业","pinyin":"bìyè","hanviet":"Tất nghiệp","pos":"Động từ (li hợp)","meaning":"tốt nghiệp","comps":"大学毕业 (tốt nghiệp đại học), 毕业以后 (sau khi tốt nghiệp), 毕了业 (tốt nghiệp rồi)","example":{"zh":"我哥哥去年大学毕业，现在在银行工作。","py":"Wǒ gēge qùnián dàxué bìyè, xiànzài zài yínháng gōngzuò.","vi":"Anh mình năm ngoái tốt nghiệp đại học, giờ làm ở ngân hàng."}},{"stt":22,"hanzi":"出生","pinyin":"chūshēng","hanviet":"Xuất sinh","pos":"Động từ","meaning":"sinh ra, ra đời","comps":"出生在北京 (sinh ra ở Bắc Kinh), 出生时 (lúc mới sinh)","example":{"zh":"我出生在一个小城市。","py":"Wǒ chūshēng zài yí ge xiǎo chéngshì.","vi":"Mình sinh ra ở một thành phố nhỏ."}},{"stt":23,"hanzi":"过去","pinyin":"guòqù","hanviet":"Quá khứ","pos":"Danh từ","meaning":"quá khứ, trước đây","comps":"过去的事 (chuyện đã qua), 过去的故事 (chuyện ngày trước), 跟过去比 (so với trước đây)","example":{"zh":"过去这里没有地铁，现在方便多了。","py":"Guòqù zhèli méiyǒu dìtiě, xiànzài fāngbiàn duō le.","vi":"Trước đây chỗ này không có tàu điện ngầm, giờ tiện hơn nhiều rồi."}},{"stt":24,"hanzi":"懂得","pinyin":"dǒngde","hanviet":"Đổng đắc","pos":"Động từ","meaning":"hiểu được, biết (cách)","comps":"懂得了 (đã hiểu ra), 懂得照顾别人 (biết quan tâm người khác)","example":{"zh":"他虽然很小，但是很懂得照顾别人。","py":"Tā suīrán hěn xiǎo, dànshì hěn dǒngde zhàogù biérén.","vi":"Cậu bé tuy còn nhỏ nhưng rất biết quan tâm người khác."}},{"stt":25,"hanzi":"坚持","pinyin":"jiānchí","hanviet":"Kiên trì","pos":"Động từ","meaning":"kiên trì, bền bỉ","comps":"坚持锻炼 (kiên trì tập luyện), 坚持下去 (kiên trì tiếp), 一直坚持 (luôn kiên trì)","example":{"zh":"他坚持每天跑步，身体越来越好了。","py":"Tā jiānchí měi tiān pǎobù, shēntǐ yuè lái yuè hǎo le.","vi":"Anh ấy kiên trì chạy bộ mỗi ngày, sức khoẻ ngày càng tốt."}},{"stt":26,"hanzi":"完成","pinyin":"wánchéng","hanviet":"Hoàn thành","pos":"Động từ","meaning":"hoàn thành","comps":"完成作业 (làm xong bài tập), 完成工作 (hoàn thành công việc), 完成目标 (đạt mục tiêu)","example":{"zh":"你今天的作业都完成了吗？","py":"Nǐ jīntiān de zuòyè dōu wánchéng le ma?","vi":"Bài tập hôm nay em làm xong hết chưa?"}},{"stt":27,"hanzi":"目标","pinyin":"mùbiāo","hanviet":"Mục tiêu","pos":"Danh từ","meaning":"mục tiêu","comps":"我的目标 (mục tiêu của tôi), 学习目标 (mục tiêu học tập), 完成目标 (hoàn thành mục tiêu)","example":{"zh":"我今年的目标是考上一个好大学。","py":"Wǒ jīnnián de mùbiāo shì kǎoshang yí ge hǎo dàxué.","vi":"Mục tiêu năm nay của mình là đỗ một trường đại học tốt."}},{"stt":28,"hanzi":"发展","pinyin":"fāzhǎn","hanviet":"Phát triển","pos":"Động từ","meaning":"phát triển","comps":"发展得很快 (phát triển rất nhanh), 城市的发展 (sự phát triển của thành phố)","example":{"zh":"这几年，这个城市发展得很快。","py":"Zhè jǐ nián, zhège chéngshì fāzhǎn de hěn kuài.","vi":"Mấy năm nay, thành phố này phát triển rất nhanh."}}],"hanzi":[{"char":"怎样","pinyin":"zěnyàng","hanviet":"Chẩm dạng","chars":["怎","样"],"story":"怎 = 乍 + 心 → hỏi \"thế nào\"; 样 = 木 + 羊 → dáng vẻ (样子, 一样). 怎样 = 怎么样, hơi trang trọng hơn; hay hỏi cách thức: 你们怎样过节？"},{"char":"过节","pinyin":"guòjié","hanviet":"Quá tiết","chars":["过","节"],"story":"过 = trải qua (过生日, 过年); 节 = ngày lễ. 过节 = trải qua ngày lễ → ăn Tết, đón lễ. Là động từ li hợp: 过了一个快乐的节."},{"char":"节","pinyin":"jié","hanviet":"Tiết","chars":["节"],"story":"节 = 艹 (vốn là ⺮ tre) + 卩 → đốt tre. Đốt tre chia cây thành từng đoạn → tiết học (一节课, bài 14) → mốc trong năm → ngày lễ, tết: 春节."},{"char":"节日","pinyin":"jiérì","hanviet":"Tiết nhật","chars":["节","日"],"story":"节 (lễ) + 日 (ngày) = ngày lễ. 节日 là danh từ chung (重要的节日); tên một lễ cụ thể thì dùng 节: 春节."},{"char":"联欢","pinyin":"liánhuān","hanviet":"Liên hoan","chars":["联","欢"],"story":"联 = 耳 + 关 → nối liền (liên); 欢 = 又 + 欠 (người há miệng) → vui (欢迎, 喜欢). 联欢 = cùng nhau vui → liên hoan. 春节联欢晚会 = Gala chào Xuân đêm giao thừa."},{"char":"大概","pinyin":"dàgài","hanviet":"Đại khái","chars":["大","概"],"story":"概 = 木 + 既 → tấm gạt đong cho bằng miệng đấu → ước chừng. 大概 = phó từ \"khoảng, chắc là\" (大概七八天) hoặc tính từ \"đại khái\" (大概的意思)."},{"char":"阿姨","pinyin":"āyí","hanviet":"A di","chars":["阿","姨"],"story":"阿 = tiền tố gọi thân mật; 姨 = 女 + 夷 → dì (chị em gái của mẹ). Người Trung Quốc gọi phụ nữ tầm tuổi mẹ là 阿姨: 张阿姨 = cô Trương."},{"char":"叔叔","pinyin":"shūshu","hanviet":"Thúc thúc","chars":["叔","叔"],"story":"叔 = 尗 (hạt đậu) + 又 (tay) → nhặt đậu, mượn chỉ em trai của bố → chú. Gọi đàn ông tầm tuổi bố là 叔叔: 李叔叔. Chữ sau thanh nhẹ: shūshu."},{"char":"收","pinyin":"shōu","hanviet":"Thu","chars":["收"],"story":"收 = 丩 + 攵 (tay cầm gậy) → gom về → thu, nhận. 收礼物 · 请收下 (下 = kết quả: nhận lấy). Ôn 收到 (bài 5)."},{"char":"总","pinyin":"zǒng","hanviet":"Tổng","chars":["总"],"story":"总 = 丷 + 口 + 心 → gom về một mối → tổng. Phó từ 总 = 总是 \"lúc nào cũng, cứ\": 总听小文说起你 = cứ nghe Tiểu Văn nhắc đến cháu."},{"char":"起","pinyin":"qǐ","hanviet":"Khởi","chars":["起"],"story":"起 = 走 + 己 → đứng dậy đi (起床). Bài này 起 đứng sau động từ nói / nghĩ: 说起 · 问起 · 想起 = nhắc đến, hỏi tới, nhớ tới (ai / việc gì)."},{"char":"见面","pinyin":"jiànmiàn","hanviet":"Kiến diện","chars":["见","面"],"story":"见 = thấy; 面 = mặt. 见面 = thấy mặt → gặp mặt. Là động từ li hợp: ✓ 跟他见面 · ✗ 见面他."},{"char":"矿泉水","pinyin":"kuàngquánshuǐ","hanviet":"Khoáng tuyền thuỷ","chars":["矿","泉","水"],"story":"矿 = 石 + 广 → khoáng chất; 泉 = 白 + 水 → suối nước trong; 水 = nước. 矿泉水 = nước suối khoáng → nước khoáng (Khoáng tuyền thuỷ)."},{"char":"刚刚","pinyin":"gānggāng","hanviet":"Cương cương","chars":["刚","刚"],"story":"刚 = 冈 + 刂 (dao) → cứng (cương), mượn làm phó từ \"vừa\". 刚刚 = vừa mới — phó từ, chỉ đứng sau chủ ngữ, trước động từ; khác 刚才 (danh từ \"vừa nãy\")."},{"char":"春节","pinyin":"Chūnjié","hanviet":"Xuân tiết","chars":["春","节"],"story":"春 = mùa xuân (bài 12); 节 = lễ. 春节 = lễ mùa xuân → Tết Nguyên đán (đầu tháng Giêng âm lịch), ngày lễ quan trọng nhất của người Trung Quốc."},{"char":"出发","pinyin":"chūfā","hanviet":"Xuất phát","chars":["出","发"],"story":"出 = ra; 发 = phát ra, bắt đầu (ôn 发现, 发烧). 出发 = ra đi → xuất phát, lên đường. Hay đi với 从: 从北京出发."},{"char":"不久","pinyin":"bùjiǔ","hanviet":"Bất cửu","chars":["不","久"],"story":"不 + 久 (lâu — bài 4). 不久 = không lâu; hay dùng 不久前 (cách đây không lâu), 不久以后 (ít lâu sau). KW3: 好像是不久前发生的一样."},{"char":"发生","pinyin":"fāshēng","hanviet":"Phát sinh","chars":["发","生"],"story":"发 = phát ra; 生 = sinh ra. 发生 = (sự việc) xảy ra: 发生了什么事？ Chủ ngữ là sự việc, không phải người."},{"char":"刚","pinyin":"gāng","hanviet":"Cương","chars":["刚"],"story":"刚 = 冈 + 刂 (dao). 刚 = 刚刚 \"vừa mới\", ngắn gọn hơn; hay dùng 刚……时 / 刚……就……: 他刚离开家时. Khác 刚才 (danh từ \"vừa nãy\")."},{"char":"只要","pinyin":"zhǐyào","hanviet":"Chỉ yếu","chars":["只","要"],"story":"只 = chỉ; 要 = cần. 只要 = chỉ cần → điều kiện đủ, đi với 就: 只要……就……. Khác 只有……才…… (bài 17) = điều kiện duy nhất."},{"char":"学期","pinyin":"xuéqī","hanviet":"Học kỳ","chars":["学","期"],"story":"期 = 其 + 月 (mặt trăng) → kỳ hạn, một khoảng thời gian (星期). 学期 = kỳ học. 上学期 / 下学期 = học kỳ trước / sau."},{"char":"毕业","pinyin":"bìyè","hanviet":"Tất nghiệp","chars":["毕","业"],"story":"毕 = 比 + 十 → xong hết (tất); 业 = việc học (作业). 毕业 = học xong → tốt nghiệp. Li hợp: 毕了业 · ✗ 毕业大学 → ✓ 大学毕业."},{"char":"出生","pinyin":"chūshēng","hanviet":"Xuất sinh","chars":["出","生"],"story":"出 = ra; 生 = sinh. 出生 = ra đời: 出生在 + nơi chốn (出生在北京); KW4: 李文出生时的照片 = ảnh lúc Lý Văn mới sinh."},{"char":"过去","pinyin":"guòqù","hanviet":"Quá khứ","chars":["过","去"],"story":"Bài này 过去 là danh từ \"quá khứ, trước đây\" (guòqù, 去 thanh 4): 他过去的故事. Khác động từ xu hướng 过去 \"đi qua\" (guòqu, thanh nhẹ): 走过去."},{"char":"懂得","pinyin":"dǒngde","hanviet":"Đổng đắc","chars":["懂","得"],"story":"懂 = 忄 (lòng) + 董 → hiểu trong lòng; 得 = được. 懂得 = hiểu được đạo lý, biết cách làm: 我懂得了…… · 懂得照顾别人. Sâu hơn 懂 (hiểu câu chữ)."},{"char":"坚持","pinyin":"jiānchí","hanviet":"Kiên trì","chars":["坚","持"],"story":"坚 = 又 + 土 → đất nện chặt → vững; 持 = 扌 + 寺 → cầm giữ. 坚持 = giữ vững → kiên trì: 坚持锻炼 · 一直坚持."},{"char":"完成","pinyin":"wánchéng","hanviet":"Hoàn thành","chars":["完","成"],"story":"完 = xong (做完); 成 = thành. 完成 = làm xong trọn vẹn → hoàn thành; đi với 作业 · 工作 · 目标."},{"char":"目标","pinyin":"mùbiāo","hanviet":"Mục tiêu","chars":["目","标"],"story":"目 = con mắt; 标 = 木 + 示 → cọc mốc, dấu hiệu. 目标 = cái mốc mắt nhắm tới → mục tiêu: 完成自己的目标."},{"char":"发展","pinyin":"fāzhǎn","hanviet":"Phát triển","chars":["发","展"],"story":"发 = phát ra; 展 = mở ra, trải rộng. 发展 = phát ra rồi mở rộng → phát triển: 城市发展得很快 · 他以后会发展得更好."}],"grammar":[{"title":"相邻两个数字 + 量词 + 名词","formula":"<div class=\"fx-row\"><span class=\"fx-p c-a\"><b>Số n</b><small>七 · 五 · 三</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>Số n + 1</b><small>八 · 六 · 四</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>Lượng từ</b><small>天 · 个 · 年</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>(Danh từ)</b><small>假 · 学生</small></span></div>","summary":"<p class=\"gr-lead\">Số ước lượng</p><ul><li>Hai số <b>liền nhau</b> đặt cạnh nhau = số không chính xác: <span class=\"zh\">七八天 · 五六个 · 三四年前</span>.</li><li>Hay đi với <span class=\"zh\">大概</span>; số chục: <span class=\"zh\">十一二点</span> (11–12 giờ) · <span class=\"zh\">二三十分钟</span> (20–30 phút).</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">概数 · hai số liền nhau</span> · Cấu trúc</h4><p>Bảy tám ngày</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Ngày</div><div class=\"fx-row\"><span class=\"fx-p\"><b>放</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>七八</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>天</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>假</b></span></div><div class=\"fx-ex zh\">春节大概放七八天假。</div><div class=\"fx-lbl\">Người</div><div class=\"fx-row\"><span class=\"fx-p\"><b>来了</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>五六</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>个</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>学生</b></span></div><div class=\"fx-ex zh\">教室里来了五六个学生。</div><div class=\"fx-lbl\">Năm</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>三四</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>年</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>前</b></span></div><div class=\"fx-ex zh\">这些照片是三四年前照的吧？</div><div class=\"fx-lbl\">Số chục</div><div class=\"fx-row\"><span class=\"fx-p\"><b>锻炼</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>二三十</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>分钟</b></span></div><div class=\"fx-ex zh\">我每天都锻炼二三十分钟。</div></div><p class=\"gr-key\">Hỏi <span class=\"zh\">几天？</span> → đáp <span class=\"zh\">七八天</span>　·　<span class=\"zh\">十一二</span> = 11–12　·　<span class=\"zh\">二三十</span> = 20–30</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">春节大概放七八天假。</span> = Tết được nghỉ khoảng bảy tám ngày.</p>","note":"<b>Lưu ý:</b> Đã ước lượng thì không thêm 多: ✗ <span class=\"zh\">七八多天</span> → ✓ <span class=\"zh\">七八天</span>","examples":[{"zh":"春节大概放七八天假。","py":"Chūnjié dàgài fàng qī bā tiān jià.","vi":"Tết được nghỉ khoảng bảy tám ngày."},{"zh":"教室里来了五六个学生。","py":"Jiàoshì li láile wǔ liù ge xuésheng.","vi":"Trong lớp có năm sáu học sinh đến."},{"zh":"这些照片是三四年前照的吧？","py":"Zhèxiē zhàopiàn shì sān sì nián qián zhào de ba?","vi":"Mấy tấm ảnh này chụp khoảng ba bốn năm trước nhỉ?"}],"exercises":[]},{"title":"刚才 (名词) · 刚刚 (副词)","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>(刚才)</b><small>đầu câu</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>Chủ ngữ</b><small>我 · 他</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>刚才 / 刚刚</b><small>vừa nãy / vừa mới</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>Động từ</b><small>看过 · 来 · 学会</small></span></div>","summary":"<p class=\"gr-lead\">Vừa nãy · vừa mới</p><ul><li><b>刚才</b> = danh từ thời gian \"vừa nãy\" (vài phút trước); đứng <b>đầu câu</b> hoặc sau chủ ngữ, thêm được 的: <span class=\"zh\">刚才的电话</span>.</li><li><b>刚刚</b> = phó từ \"vừa mới\" — vài phút, vài ngày, thậm chí vài tháng; <b>chỉ</b> đứng sau chủ ngữ: <span class=\"zh\">他刚刚来北京两个月</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">刚才 ↔ 刚刚</span> · Đối chiếu</h4><p>Vị trí · thời gian</p><div class=\"gr-formula\"><div class=\"fx-lbl\">刚才 · đầu câu</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>刚才</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>的电话</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>是我妈妈打来的</b></span></div><div class=\"fx-ex zh\">刚才的电话是我妈妈打来的。</div><div class=\"fx-lbl\">刚才 · sau CN</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>刚才</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>看过一遍</b></span></div><div class=\"fx-ex zh\">我刚才看过一遍，不想再看了。</div><div class=\"fx-lbl\">刚刚 · vài phút</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>刚刚</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>学会了包饺子</b></span></div><div class=\"fx-ex zh\">我刚刚看视频学会了包饺子。</div><div class=\"fx-lbl\">刚刚 · vài tháng</div><div class=\"fx-row\"><span class=\"fx-p\"><b>他</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>刚刚</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>来北京</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>两个月</b></span></div><div class=\"fx-ex zh\">他刚刚来北京两个月。</div></div><p class=\"gr-key\"><span class=\"zh\">刚才</span> = vừa nãy (danh từ, thêm được 的)　·　<span class=\"zh\">刚刚 / 刚</span> = vừa mới (phó từ, sau chủ ngữ)</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我刚刚看视频学会了包饺子。</span> = Cháu vừa mới xem video học được cách gói sủi cảo.</p>","note":"<b>Lưu ý:</b> 刚刚 không đứng đầu câu, không thêm 的: ✗ <span class=\"zh\">刚刚的问题</span> → ✓ <span class=\"zh\">刚才的问题</span>","examples":[{"zh":"刚才的电话是我妈妈打来的。","py":"Gāngcái de diànhuà shì wǒ māma dǎlai de.","vi":"Cuộc điện thoại vừa nãy là mẹ mình gọi."},{"zh":"我刚才看过一遍，不想再看了。","py":"Wǒ gāngcái kànguo yí biàn, bù xiǎng zài kàn le.","vi":"Vừa nãy mình xem một lượt rồi, không muốn xem lại nữa."},{"zh":"我刚刚看视频学会了包饺子。","py":"Wǒ gānggāng kàn shìpín xuéhuìle bāo jiǎozi.","vi":"Mình vừa mới xem video học được cách gói sủi cảo."},{"zh":"他刚刚来北京两个月。","py":"Tā gānggāng lái Běijīng liǎng ge yuè.","vi":"Anh ấy mới đến Bắc Kinh được hai tháng."}],"exercises":[{"type":"fill","q":"<span class=\"zh\">请你再说一遍____的问题。</span><span class=\"qz-hint\">Bạn nói lại câu hỏi vừa nãy một lần nữa nhé.</span>","answer":["刚才"],"explain":"请你再说一遍刚才的问题。 (Qǐng nǐ zài shuō yí biàn gāngcái de wèntí.)"},{"type":"fill","q":"<span class=\"zh\">你____来了两三天就要走，为什么？</span><span class=\"qz-hint\">Bạn mới đến có hai ba ngày đã định đi, sao vậy?</span>","answer":["刚刚","刚"],"explain":"你刚刚来了两三天就要走，为什么？ (Nǐ gānggāng láile liǎng sān tiān jiù yào zǒu, wèi shénme?)"},{"type":"fill","q":"<span class=\"zh\">我不是____开始学习中文的，我已经学了一年了。</span><span class=\"qz-hint\">Mình không phải mới bắt đầu học tiếng Trung đâu, mình học được một năm rồi.</span>","answer":["刚刚","刚"],"explain":"我不是刚刚开始学习中文的，我已经学了一年了。 (Wǒ bú shì gānggāng kāishǐ xuéxí Zhōngwén de, wǒ yǐjīng xuéle yì nián le.)"}]},{"title":"只要 + 条件，（主语）+ 就 + 结果","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>(Chủ ngữ)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>只要</b><small>chỉ cần</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>Điều kiện</b><small>你同意 · 坚持</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>(CN 2) + 就</b><small>là</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>Kết quả</b><small>很想他 · 能完成</small></span></div>","summary":"<p class=\"gr-lead\">Chỉ cần … là …</p><ul><li>Sau <span class=\"zh\">只要</span> là <b>điều kiện đủ</b>: có điều kiện này là có kết quả sau <span class=\"zh\">就</span> (\"chỉ cần … là …\").</li><li>Chủ ngữ đứng trước hoặc sau 只要; có <b>hai chủ ngữ</b> thì chủ ngữ 2 đặt <b>trước 就</b>: <span class=\"zh\">只要你同意，我们就……</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">只要……就 · 只有……才</span> · Đối chiếu</h4><p>Đủ · duy nhất</p><div class=\"gr-formula\"><div class=\"fx-lbl\">CN trước 只要</div><div class=\"fx-row\"><span class=\"fx-p\"><b>我</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>只要</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>有时间</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>去看他</b></span></div><div class=\"fx-ex zh\">我只要有时间，就去看他。</div><div class=\"fx-lbl\">Hai chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>只要</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>你同意</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>我们</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>去</b></span></div><div class=\"fx-ex zh\">只要你同意，我们就去。</div><div class=\"fx-lbl\">Đối chiếu B17</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>只有</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>多练习</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>才</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>能说好</b></span></div><div class=\"fx-ex zh\">只有多练习，才能说好。</div></div><p class=\"gr-key\"><span class=\"zh\">只要……就</span> = có điều kiện này là đủ　·　<span class=\"zh\">只有……才</span> = bắt buộc phải có điều kiện này</p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">只要一直坚持，就能完成自己的目标。</span> = Chỉ cần luôn kiên trì là có thể hoàn thành mục tiêu của mình.</p>","note":"<b>Lưu ý:</b> Chủ ngữ không đứng sau 就: ✗ <span class=\"zh\">只要你同意，就我们去</span> → ✓ <span class=\"zh\">只要你同意，我们就去</span>","examples":[{"zh":"我只要几天不跟他视频，就很想他。","py":"Wǒ zhǐyào jǐ tiān bù gēn tā shìpín, jiù hěn xiǎng tā.","vi":"Cô chỉ cần vài hôm không gọi video với nó là đã rất nhớ."},{"zh":"只要你同意，我们就这么决定了。","py":"Zhǐyào nǐ tóngyì, wǒmen jiù zhème juédìng le.","vi":"Chỉ cần bạn đồng ý là chúng ta quyết định vậy nhé."},{"zh":"只要你坚持每天早睡，身体就一定会好起来。","py":"Zhǐyào nǐ jiānchí měi tiān zǎo shuì, shēntǐ jiù yídìng huì hǎo qǐlai.","vi":"Chỉ cần bạn kiên trì ngủ sớm mỗi ngày, sức khoẻ nhất định sẽ tốt lên."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你对大家都这么好啊？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我相信只要我对别人好，____。</span></span></span><span class=\"qz-hint\">Bạn tốt với mọi người thế à? — Mình tin chỉ cần mình tốt với người khác thì người khác sẽ tốt với mình.</span>","answer":["别人就会对我好","别人也会对我好","就会对我好"],"explain":"我相信只要我对别人好，别人就会对我好。 (Wǒ xiāngxìn zhǐyào wǒ duì biérén hǎo, biérén jiù huì duì wǒ hǎo.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">只要你努力学习，____。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">老师，我一定会努力的。</span></span></span><span class=\"qz-hint\">Chỉ cần em chăm chỉ học là nhất định thi tốt. — Thưa cô, em nhất định sẽ cố gắng.</span>","answer":["就一定能考好","就能考好","就一定会考好"],"explain":"只要你努力学习，就一定能考好。 (Zhǐyào nǐ nǔlì xuéxí, jiù yídìng néng kǎohǎo.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">张阿姨，谢谢您做了这么多菜，一定累得很。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">不累，____，我就不觉得累。</span></span></span><span class=\"qz-hint\">Cô Trương ơi, cảm ơn cô nấu nhiều món thế, chắc cô mệt lắm. — Không mệt đâu, chỉ cần các cháu thích ăn là cô không thấy mệt.</span>","answer":["只要你们喜欢吃"],"explain":"不累，只要你们喜欢吃，我就不觉得累。 (Bú lèi, zhǐyào nǐmen xǐhuan chī, wǒ jiù bù juéde lèi.)"}]},{"title":"从 + 时间 / 事情 + 起，……","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>从</b><small>từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>Thời điểm / Sự việc</b><small>那时 · 那天 · 明天</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>起</b><small>trở đi</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>(Chủ ngữ) + Hành động</b><small>就努力学习</small></span></div>","summary":"<p class=\"gr-lead\">Kể từ … (trở đi)</p><ul><li><span class=\"zh\">从……起</span> = <span class=\"zh\">从……开始</span> \"kể từ … (trở đi)\", chủ yếu chỉ <b>thời gian</b>.</li><li>Thường đứng <b>đầu câu</b> làm trạng ngữ; vế sau hay có <span class=\"zh\">就 · 都</span>: <span class=\"zh\">从明天起，我每天都跑步</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">从……起 · ba dạng</span> · Cấu trúc</h4><p>Kể từ … trở đi</p><div class=\"gr-formula\"><div class=\"fx-lbl\">Thời điểm</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>从</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>明天</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>起</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>我每天都去跑步</b></span></div><div class=\"fx-ex zh\">从明天起，我每天早上都去跑步。</div><div class=\"fx-lbl\">Sự việc</div><div class=\"fx-row\"><span class=\"fx-p key\"><b>从</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>上大学</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>起</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>他就一个人住</b></span></div><div class=\"fx-ex zh\">从上大学起，他就一个人住。</div><div class=\"fx-lbl\">Sau chủ ngữ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>他</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>从</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>那时</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>起</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-b\"><b>就努力学习</b></span></div><div class=\"fx-ex zh\">他从那时起就努力学习。</div></div><p class=\"gr-key\"><span class=\"zh\">从……起 = 从……开始</span>　·　vế sau hay có <span class=\"zh\">就 / 都</span></p></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">他从那时起就努力学习。</span> = Từ đó trở đi anh ấy cố gắng học tập.</p>","note":"<b>Lưu ý:</b> Không bỏ 起: ✗ <span class=\"zh\">从那天，我们变成了好朋友</span> → ✓ <span class=\"zh\">从那天起，……</span>","examples":[{"zh":"他从那时起就努力学习。","py":"Tā cóng nà shí qǐ jiù nǔlì xuéxí.","vi":"Từ đó trở đi anh ấy cố gắng học tập."},{"zh":"从那天起，我们就变成了好朋友。","py":"Cóng nà tiān qǐ, wǒmen jiù biànchéngle hǎo péngyou.","vi":"Từ hôm đó, chúng mình trở thành bạn tốt."},{"zh":"从那次旅游起，我对中国文化更有兴趣了。","py":"Cóng nà cì lǚyóu qǐ, wǒ duì Zhōngguó wénhuà gèng yǒu xìngqù le.","vi":"Từ chuyến du lịch đó, mình càng thích văn hoá Trung Quốc hơn."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在飞机上","titleVi":"Trên máy bay — chuyện ăn Tết ở TQ","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"我要在中国过年，真开心。","py":"Wǒ yào zài Zhōngguó guònián, zhēn kāixīn.","vi":"Mình sắp được đón Tết ở Trung Quốc, vui thật đấy."},{"speaker":"文","name":"Lý Văn","zh":"第一次请外国朋友来家里过春节，我也很高兴。","py":"Dì-yī cì qǐng wàiguó péngyou lái jiāli guò Chūnjié, wǒ yě hěn gāoxìng.","vi":"Lần đầu mời bạn nước ngoài về nhà ăn Tết, mình cũng rất vui."},{"speaker":"月","name":"Gia Nguyệt","zh":"你们怎样过节？","py":"Nǐmen zěnyàng guòjié?","vi":"Nhà bạn ăn Tết thế nào?"},{"speaker":"文","name":"Lý Văn","zh":"春节是中国最重要的节日，我们一般会回家，跟家人一起过。","py":"Chūnjié shì Zhōngguó zuì zhòngyào de jiérì, wǒmen yìbān huì huí jiā, gēn jiārén yìqǐ guò.","vi":"Tết là ngày lễ quan trọng nhất của Trung Quốc, bọn mình thường về nhà, đón Tết cùng gia đình."},{"speaker":"月","name":"Gia Nguyệt","zh":"那你跟家人会一起做什么？","py":"Nà nǐ gēn jiārén huì yìqǐ zuò shénme?","vi":"Vậy bạn với gia đình sẽ cùng làm gì?"},{"speaker":"文","name":"Lý Văn","zh":"我们家会一边包饺子，一边看春节联欢晚会，一直到十二点以后才睡觉。","py":"Wǒmen jiā huì yìbiān bāo jiǎozi, yìbiān kàn Chūnjié Liánhuān Wǎnhuì, yìzhí dào shí'èr diǎn yǐhòu cái shuìjiào.","vi":"Nhà mình sẽ vừa gói sủi cảo vừa xem Gala chào Xuân, mãi đến sau mười hai giờ mới đi ngủ."},{"speaker":"月","name":"Gia Nguyệt","zh":"听起来很有意思。春节放几天假？","py":"Tīng qǐlai hěn yǒu yìsi. Chūnjié fàng jǐ tiān jià?","vi":"Nghe thú vị quá. Tết được nghỉ mấy ngày?"},{"speaker":"文","name":"Lý Văn","zh":"大概七八天。","py":"Dàgài qī bā tiān.","vi":"Khoảng bảy tám ngày."}]},{"titleZh":"课文二 · 在李文家","titleVi":"Nhà Lý Văn — chúc Tết bố mẹ Lý Văn","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"张阿姨，李叔叔。过年好！这是我准备的礼物，请收下。","py":"Zhāng āyí, Lǐ shūshu. Guònián hǎo! Zhè shì wǒ zhǔnbèi de lǐwù, qǐng shōuxia.","vi":"Cô Trương, chú Lý. Chúc mừng năm mới! Đây là quà cháu chuẩn bị, cô chú nhận cho cháu ạ."},{"speaker":"叔","name":"Chú Lý","zh":"谢谢家月，你太客气了！","py":"Xièxie Jiāyuè, nǐ tài kèqi le!","vi":"Cảm ơn Gia Nguyệt, cháu khách sáo quá!"},{"speaker":"姨","name":"Cô Trương","zh":"总听小文说起你，今天终于有机会见面了。","py":"Zǒng tīng Xiǎo Wén shuōqǐ nǐ, jīntiān zhōngyú yǒu jīhuì jiànmiàn le.","vi":"Cứ nghe Tiểu Văn nhắc đến cháu suốt, hôm nay cuối cùng cũng có dịp gặp mặt."},{"speaker":"月","name":"Gia Nguyệt","zh":"谢谢您和叔叔请我来家里做客。","py":"Xièxie nín hé shūshu qǐng wǒ lái jiāli zuòkè.","vi":"Cảm ơn cô và chú đã mời cháu đến nhà chơi."},{"speaker":"叔","name":"Chú Lý","zh":"桌子上有饮料，还有矿泉水，你想喝什么就自己拿。","py":"Zhuōzi shang yǒu yǐnliào, hái yǒu kuàngquánshuǐ, nǐ xiǎng hē shénme jiù zìjǐ ná.","vi":"Trên bàn có đồ uống, còn có nước khoáng, cháu muốn uống gì cứ tự lấy nhé."},{"speaker":"姨","name":"Cô Trương","zh":"你先坐着看会儿电视，饺子很快就包好了。","py":"Nǐ xiān zuòzhe kàn huìr diànshì, jiǎozi hěn kuài jiù bāohǎo le.","vi":"Cháu ngồi xem tivi một lát đã, sủi cảo sắp gói xong rồi."},{"speaker":"月","name":"Gia Nguyệt","zh":"我刚刚看视频学会了包饺子，我跟你们一起包吧。","py":"Wǒ gānggāng kàn shìpín xuéhuìle bāo jiǎozi, wǒ gēn nǐmen yìqǐ bāo ba.","vi":"Cháu vừa mới xem video học được cách gói sủi cảo, cháu gói cùng cô chú nhé."}]},{"titleZh":"课文三 · 在李文家","titleVi":"Nhà Lý Văn — cùng xem ảnh cũ","lines":[{"speaker":"月","name":"Gia Nguyệt","zh":"这张照片是李文出国前照的吗？","py":"Zhè zhāng zhàopiàn shì Lǐ Wén chūguó qián zhào de ma?","vi":"Tấm ảnh này chụp trước khi Lý Văn ra nước ngoài ạ?"},{"speaker":"姨","name":"Cô Trương","zh":"对，这是他从北京出发时，我们全家在机场照的。","py":"Duì, zhè shì tā cóng Běijīng chūfā shí, wǒmen quán jiā zài jīchǎng zhào de.","vi":"Đúng rồi, đây là lúc nó xuất phát từ Bắc Kinh, cả nhà cô chụp ở sân bay."},{"speaker":"月","name":"Gia Nguyệt","zh":"那是三四年前吧？","py":"Nà shì sān sì nián qián ba?","vi":"Vậy là khoảng ba bốn năm trước ạ?"},{"speaker":"姨","name":"Cô Trương","zh":"是啊，时间过得真快，好像是不久前发生的一样。","py":"Shì a, shíjiān guò de zhēn kuài, hǎoxiàng shì bùjiǔ qián fāshēng de yíyàng.","vi":"Ừ, thời gian trôi nhanh thật, cứ như mới xảy ra cách đây không lâu."},{"speaker":"月","name":"Gia Nguyệt","zh":"您一定特别想李文吧？","py":"Nín yídìng tèbié xiǎng Lǐ Wén ba?","vi":"Chắc cô nhớ Lý Văn lắm ạ?"},{"speaker":"姨","name":"Cô Trương","zh":"他刚离开家时，我很不习惯，只要几天不跟他视频，就很想他。","py":"Tā gāng líkāi jiā shí, wǒ hěn bù xíguàn, zhǐyào jǐ tiān bù gēn tā shìpín, jiù hěn xiǎng tā.","vi":"Lúc nó mới xa nhà, cô rất không quen, chỉ cần vài hôm không gọi video với nó là cô đã nhớ lắm."},{"speaker":"月","name":"Gia Nguyệt","zh":"还有最后一个学期就要毕业了，他很快就会回来了。","py":"Hái yǒu zuìhòu yí ge xuéqī jiù yào bìyè le, tā hěn kuài jiù huì huílai le.","vi":"Còn học kỳ cuối nữa là tốt nghiệp rồi, anh ấy sẽ sớm về thôi ạ."}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — Gia Nguyệt viết nhật ký","para":true,"speaker":"月","lines":[{"zh":"这次来中国，我最高兴的是认识了李文的父母。","py":"Zhè cì lái Zhōngguó, wǒ zuì gāoxìng de shì rènshile Lǐ Wén de fùmǔ.","vi":"Lần này đến Trung Quốc, điều tôi vui nhất là được quen bố mẹ Lý Văn."},{"zh":"他们给我看了李文出生时的照片，还给我讲了很多他过去的故事。","py":"Tāmen gěi wǒ kànle Lǐ Wén chūshēng shí de zhàopiàn, hái gěi wǒ jiǎngle hěn duō tā guòqù de gùshi.","vi":"Cô chú cho tôi xem ảnh lúc Lý Văn mới sinh, còn kể cho tôi nghe nhiều chuyện ngày trước của anh ấy."},{"zh":"李文高中的时候想学医，从那时起就努力学习。","py":"Lǐ Wén gāozhōng de shíhou xiǎng xué yī, cóng nà shí qǐ jiù nǔlì xuéxí.","vi":"Hồi cấp ba Lý Văn muốn học y, từ đó trở đi anh ấy cố gắng học tập."},{"zh":"高三的时候，因为成绩特别好，他得到了出国留学的机会。","py":"Gāosān de shíhou, yīnwèi chéngjì tèbié hǎo, tā dédàole chūguó liúxué de jīhuì.","vi":"Năm lớp 12, vì thành tích rất tốt, anh ấy đã có được cơ hội du học."},{"zh":"在他身上，我懂得了，只要一直坚持，就能完成自己的目标。","py":"Zài tā shēn shang, wǒ dǒngde le, zhǐyào yìzhí jiānchí, jiù néng wánchéng zìjǐ de mùbiāo.","vi":"Từ anh ấy, tôi hiểu được rằng chỉ cần luôn kiên trì là có thể hoàn thành mục tiêu của mình."},{"zh":"我相信，他以后一定会发展得更好。","py":"Wǒ xiāngxìn, tā yǐhòu yídìng huì fāzhǎn de gèng hǎo.","vi":"Tôi tin sau này anh ấy nhất định sẽ phát triển tốt hơn nữa."}]}]},"extra":[],"activity":{"act":[{"zh":"多人活动","py":"duōrén huódòng","tag":"Hoạt động nhóm","mean":"Ngày lễ truyền thống","q":{"zh":"四人一组，每人介绍自己国家的一个传统节日。","py":"Sì rén yì zǔ, měi rén jièshào zìjǐ guójiā de yí ge chuántǒng jiérì.","vi":"Nhóm 4 người: mỗi người giới thiệu một ngày lễ truyền thống của nước mình (dùng từ, ngữ pháp bài 18)."},"items":[{"zh":"这个节日叫什么？是什么时候？","py":"Zhège jiérì jiào shénme? Shì shénme shíhou?","vi":"Ngày lễ này tên là gì? Vào lúc nào?"},{"zh":"人们怎样过这个节日？大概放几天假？","py":"Rénmen zěnyàng guò zhège jiérì? Dàgài fàng jǐ tiān jià?","vi":"Mọi người đón ngày lễ này thế nào? Nghỉ khoảng mấy ngày?"},{"zh":"过节的时候，大家一般吃什么？","py":"Guòjié de shíhou, dàjiā yìbān chī shénme?","vi":"Khi đón lễ, mọi người thường ăn gì?"},{"zh":"这个节日有什么意义？","py":"Zhège jiérì yǒu shénme yìyì?","vi":"Ngày lễ này có ý nghĩa gì?"}]}],"speak":[{"zh":"口语练习","py":"kǒuyǔ liànxí","tag":"Luyện nói","mean":"Ôn bài 13–18 · Thay đổi","prep":3,"talk":2,"q":{"zh":"请你谈谈这几年你的生活发生了什么变化。","py":"Qǐng nǐ tántan zhè jǐ nián nǐ de shēnghuó fāshēngle shénme biànhuà.","vi":"Hãy kể về những thay đổi trong cuộc sống của bạn mấy năm nay."},"frame":[{"lbl":"开头","zh":"这……年我变化很大，从……起，我就……。","py":"Zhè …… nián wǒ biànhuà hěn dà, cóng …… qǐ, wǒ jiù …….","vi":"Mấy năm nay mình thay đổi nhiều, từ khi … mình …","ex":{"zh":"这三四年我变化很大，从上大学起，我就一个人住了。","py":"Zhè sān sì nián wǒ biànhuà hěn dà, cóng shàng dàxué qǐ, wǒ jiù yí ge rén zhù le.","vi":"Ba bốn năm nay mình thay đổi nhiều, từ khi vào đại học mình sống một mình."}},{"lbl":"中间","zh":"刚……的时候，我一会儿……，一会儿……。","py":"Gāng …… de shíhou, wǒ yíhuìr ……, yíhuìr …….","vi":"Lúc mới …, mình lúc thì …, lúc thì …","ex":{"zh":"刚离开家的时候，我一会儿想家，一会儿担心考试。","py":"Gāng líkāi jiā de shíhou, wǒ yíhuìr xiǎng jiā, yíhuìr dānxīn kǎoshì.","vi":"Lúc mới xa nhà, mình lúc thì nhớ nhà, lúc thì lo thi cử."}},{"lbl":"中间","zh":"后来，我先……，然后一边……，一边……。","py":"Hòulái, wǒ xiān ……, ránhòu yìbiān ……, yìbiān …….","vi":"Sau đó, mình … trước, rồi vừa … vừa …","ex":{"zh":"后来，我先认识了几个朋友，然后一边学习，一边打网球。","py":"Hòulái, wǒ xiān rènshile jǐ ge péngyou, ránhòu yìbiān xuéxí, yìbiān dǎ wǎngqiú.","vi":"Sau đó, mình quen vài người bạn trước, rồi vừa học vừa chơi tennis."}},{"lbl":"中间","zh":"现在，只要……，我就……，每天还比过去早……。","py":"Xiànzài, zhǐyào ……, wǒ jiù ……, měi tiān hái bǐ guòqù zǎo …….","vi":"Bây giờ, chỉ cần … là mình …, mỗi ngày còn … sớm hơn trước …","ex":{"zh":"现在，只要有问题，我就自己解决，每天还比过去早起一个小时。","py":"Xiànzài, zhǐyào yǒu wèntí, wǒ jiù zìjǐ jiějué, měi tiān hái bǐ guòqù zǎo qǐ yí ge xiǎoshí.","vi":"Bây giờ, có chuyện gì là mình tự giải quyết, mỗi ngày còn dậy sớm hơn trước một tiếng."}},{"lbl":"结尾","zh":"在我看来，只有……，才能……，以后我要多向……学习。","py":"Zài wǒ kànlái, zhǐyǒu ……, cái néng ……, yǐhòu wǒ yào duō xiàng …… xuéxí.","vi":"Theo mình, chỉ có … mới …, sau này mình phải học hỏi … nhiều hơn.","ex":{"zh":"在我看来，只有坚持，才能完成目标，以后我要多向他们学习。","py":"Zài wǒ kànlái, zhǐyǒu jiānchí, cái néng wánchéng mùbiāo, yǐhòu wǒ yào duō xiàng tāmen xuéxí.","vi":"Theo mình, chỉ có kiên trì mới đạt mục tiêu, sau này mình phải học hỏi họ nhiều hơn."}}]}]},"review":{"range":"16–18","rows":[{"l":16,"zh":"并列复句 \"一会儿……，一会儿……\"","vi":"Câu phức đẳng lập 一会儿……，一会儿……","ex":{"zh":"它一会儿在你脚边睡觉，一会儿在你身上爬。","py":"Tā yíhuìr zài nǐ jiǎo biān shuìjiào, yíhuìr zài nǐ shēn shang pá.","vi":"Nó lúc thì ngủ bên chân em, lúc thì trèo lên người em."}},{"l":16,"zh":"介词 \"关于\"","vi":"Giới từ 关于","ex":{"zh":"关于这个问题，我得慢慢给你讲。","py":"Guānyú zhège wèntí, wǒ děi mànmàn gěi nǐ jiǎng.","vi":"Về vấn đề này, mẹ phải từ từ kể cho con."}},{"l":16,"zh":"固定短语 \"一般来说\"","vi":"Cụm cố định 一般来说","ex":{"zh":"一般来说，熊猫每天要睡很多次觉。","py":"Yìbān lái shuō, xióngmāo měi tiān yào shuì hěn duō cì jiào.","vi":"Nói chung, gấu trúc mỗi ngày phải ngủ rất nhiều lần."}},{"l":16,"zh":"比较句 (11)","vi":"Câu so sánh (11): A比B + 早 / 晚… + ĐT + số lượng","ex":{"zh":"冬天比夏天早关门一个小时。","py":"Dōngtiān bǐ xiàtiān zǎo guānmén yí ge xiǎoshí.","vi":"Mùa đông đóng cửa sớm hơn mùa hè một tiếng."}},{"l":17,"zh":"介词 \"向\"","vi":"Giới từ 向","ex":{"zh":"别再向前走了。","py":"Bié zài xiàng qián zǒu le.","vi":"Đừng đi tiếp về phía trước nữa."}},{"l":17,"zh":"反问句 \"不是……吗？\"","vi":"Câu phản vấn 不是……吗？","ex":{"zh":"你不是喜欢玩电脑吗？你可以去看看跟电脑有关系的书。","py":"Nǐ bú shì xǐhuan wán diànnǎo ma? Nǐ kěyǐ qù kànkan gēn diànnǎo yǒu guānxi de shū.","vi":"Chẳng phải cậu thích chơi máy tính sao? Cậu có thể xem sách về máy tính."}},{"l":17,"zh":"递进复句 \"……，更……\"","vi":"Câu phức tăng tiến ……，更……","ex":{"zh":"我还没想好学什么，更没想好去哪个国家。","py":"Wǒ hái méi xiǎnghǎo xué shénme, gèng méi xiǎnghǎo qù nǎge guójiā.","vi":"Mình chưa nghĩ ra học gì, càng chưa nghĩ ra đi nước nào."}},{"l":17,"zh":"条件复句 \"只有……，才……\"","vi":"Câu phức điều kiện 只有……，才……","ex":{"zh":"只有想清楚自己真正喜欢什么，才能做出最合适的选择。","py":"Zhǐyǒu xiǎng qīngchu zìjǐ zhēnzhèng xǐhuan shénme, cái néng zuòchū zuì héshì de xuǎnzé.","vi":"Chỉ có nghĩ rõ mình thật sự thích gì mới đưa ra được lựa chọn phù hợp nhất."}},{"l":18,"zh":"概数表达法","vi":"Cách nói số ước lượng","ex":{"zh":"春节大概放七八天假。","py":"Chūnjié dàgài fàng qī bā tiān jià.","vi":"Tết được nghỉ khoảng bảy tám ngày."}},{"l":18,"zh":"\"刚才\"和\"刚刚\"","vi":"Phân biệt 刚才 và 刚刚","ex":{"zh":"刚才的电话是我妈妈打来的。","py":"Gāngcái de diànhuà shì wǒ māma dǎlai de.","vi":"Cuộc điện thoại vừa nãy là mẹ mình gọi."}},{"l":18,"zh":"条件复句 \"只要……，就……\"","vi":"Câu phức điều kiện 只要……，就……","ex":{"zh":"我只要几天不跟他视频，就很想他。","py":"Wǒ zhǐyào jǐ tiān bù gēn tā shìpín, jiù hěn xiǎng tā.","vi":"Cô chỉ cần vài hôm không gọi video với nó là đã rất nhớ."}},{"l":18,"zh":"固定格式 \"从……起\"","vi":"Cấu trúc cố định 从……起","ex":{"zh":"他从那时起就努力学习。","py":"Tā cóng nà shí qǐ jiù nǔlì xuéxí.","vi":"Từ đó trở đi anh ấy cố gắng học tập."}}]}}];
